/**
 * bootstrap/llm.ts 鈥?LLM 閫傞厤鍣ㄥ垵濮嬪寲
 *
 * 浠?main.ts 鎶界鐨?LLM 閰嶇疆涓庝笁璺?Key 寮曞閫昏緫銆俓r
 * 瀵嗛挜鍔犺浇浼樺厛绾э細pm vault > DEEPSEEK_*_API_KEY > DEEPSEEK_API_KEY锛堝厹搴曪級
 *
 * @module bootstrap/llm
 */

import { LlmAdapter } from "@cortex/llm";
import type { PasswordEntry } from "@cortex/pm";
import {
  ENV_DEEPSEEK_BASE_URL,
  ENV_DEEPSEEK_CHAT_MODEL,
  ENV_DEEPSEEK_REASONER_MODEL,
  ENV_DEEPSEEK_REASONING_EFFORT,
  ENV_DEEPSEEK_API_KEY,
  ENV_DEEPSEEK_CYRENE_API_KEY,
  ENV_DEEPSEEK_CHAT_API_KEY,
  ENV_DEEPSEEK_REASONER_API_KEY,
  ENV_PM_MASTER_KEY,
  DEFAULT_LLM_BASE_URL,
  DEFAULT_LLM_CHAT_MODEL,
  DEFAULT_LLM_REASONER_MODEL,
  LLM_KEY_NAMES,
} from "@cortex/config";

/** pm vault 鐨勬渶灏忔帴鍙?*/
interface PmStore {
  getEntry(name: string): PasswordEntry | undefined;
}

/** 鍒濆鍖栫殑 LLM 閫傞厤鍣ㄦ槧灏?*/
export type LlmBootstrapResult = Map<string, LlmAdapter>;

/** 鎸変紭鍏堢骇瑙ｆ瀽 API Key锛歷ault 鈫?涓撶敤鐜鍙橀噺 鈫?DEEPSEEK_API_KEY 鍏滃簳 */
function resolveKey(
  pmStore: PmStore | undefined,
  pmKey: string,
  envVarName: string,
  fallbackKey?: string,
): string | undefined {
  if (pmStore) {
    try {
      const entry = pmStore.getEntry(pmKey);
      if (entry) return entry.password;
    } catch {
      // vault 璇诲彇澶辫触锛岀户缁洖閫€
    }
  }
  return process.env[envVarName] || fallbackKey || undefined;
}

/**
 * 鍒濆鍖?LLM 閫傞厤鍣ㄤ笁璺疄渚嬶紙鏄旀稛 / Chat姹?/ Reasoner锛夈€俓r
 *
 * 鍏变韩 baseUrl / chatModel / reasonerModel / reasoningEffort 閰嶇疆锛孿r
 * 浠?API Key 鎸変笁璺嫭绔嬭В鏋愩€俓r
 */
export async function bootstrapLlm(): Promise<LlmBootstrapResult> {
  const llms = new Map<string, LlmAdapter>();

  // 鍏变韩鐨勬ā鍨?URL 閰嶇疆
  const llmBaseUrl = process.env[ENV_DEEPSEEK_BASE_URL] || DEFAULT_LLM_BASE_URL;
  const llmChatModel = process.env[ENV_DEEPSEEK_CHAT_MODEL] || DEFAULT_LLM_CHAT_MODEL;
  const llmReasonerModel = process.env[ENV_DEEPSEEK_REASONER_MODEL] || DEFAULT_LLM_REASONER_MODEL;
  const llmReasoningEffort = (process.env[ENV_DEEPSEEK_REASONING_EFFORT] as "high" | "max") || undefined;

  const fallbackKey = process.env[ENV_DEEPSEEK_API_KEY];

  // 鑻ヨ缃簡 PM_MASTER_KEY锛屽皾璇曚粠 pm 鍔犲瘑 vault 鍔犺浇瀵嗛挜
  let pmStore: PmStore | undefined;
  if (process.env[ENV_PM_MASTER_KEY]) {
    try {
      pmStore = await import("@cortex/pm");
    } catch {
      // @cortex/pm 涓嶅彲鐢紝闈欓粯鍥為€€鍒扮幆澧冨彉閲廫r
    }
  }

  const adapter = (key: string, label: string) =>
    new LlmAdapter({
      apiKey: key,
      baseUrl: llmBaseUrl,
      chatModel: llmChatModel,
      reasonerModel: llmReasonerModel,
      reasoningEffort: llmReasoningEffort,
      label,
    });

  // 鏄旀稛鐙珛 Key
  const cyreneKey = resolveKey(pmStore, LLM_KEY_NAMES.CYRENE, ENV_DEEPSEEK_CYRENE_API_KEY, fallbackKey);
  if (cyreneKey) llms.set(LLM_KEY_NAMES.CYRENE, adapter(cyreneKey, "cyrene"));

  // Chat 姹?Key
  const chatKey = resolveKey(pmStore, LLM_KEY_NAMES.CHAT, ENV_DEEPSEEK_CHAT_API_KEY, fallbackKey);
  if (chatKey) llms.set(LLM_KEY_NAMES.CHAT, adapter(chatKey, "chat"));

  // Reasoner Key
  const reasonerKey = resolveKey(pmStore, LLM_KEY_NAMES.REASONER, ENV_DEEPSEEK_REASONER_API_KEY, fallbackKey);
  if (reasonerKey) llms.set(LLM_KEY_NAMES.REASONER, adapter(reasonerKey, "reasoner"));

  return llms;
}

/** 妫€鏌ユ槸鍚︽湁浠讳綍 API Key 鍙敤 */
export function hasAnyLlmKey(): boolean {
  return !!(
    process.env[ENV_DEEPSEEK_API_KEY] ||
    process.env[ENV_DEEPSEEK_CYRENE_API_KEY] ||
    process.env[ENV_DEEPSEEK_CHAT_API_KEY] ||
    process.env[ENV_DEEPSEEK_REASONER_API_KEY]
  );
}

/** 鍚敤 API 瀹¤鏃ュ織 */
export function enableLlmAudit(): void {
  if (process.env["CORTEX_API_AUDIT"] !== "0") {
    LlmAdapter.enableAudit();
  }
}

/**
 * bootstrap/mcp.ts 鈥?MCP 鍚庣鍒濆鍖朶r
 *
 * 浠?main.ts 鎶界鐨?MCP Server 鍔犺浇涓庢悳绱㈣仛鍚堝櫒寮曞閫昏緫銆俓r
 * 鍔犺浇浼樺厛绾э細config/data/mcp-servers.json锛堟柊鏍煎紡锛夆啋 cortex-agents.json searchProviders锛堟棫鏍煎紡锛塡r
 *
 * @module bootstrap/mcp
 */

import * as nodeFs from "node:fs";
import * as nodePath from "node:path";
import {
  SearchAggregator,
  McpSearchBackend,
  DdgSearchBackend,
  type McpServerConfig,
  type Toolkit,
} from "@cortex/platform";
import {
  ENV_CORTEX_NO_SEARCH,
  ENV_VITEST,
  FILE_CORTEX_AGENTS_JSON,
  resolveConfigDataDir,
  loadConfigDomain,
  type McpServerEntry,
  type ConfigFileReader,
} from "@cortex/config";

/** MCP 寮曞缁撴灉鈥斺€旀垚鍔熷惎鍔ㄧ殑鍚庣鍒楄〃 */
export interface McpBootstrapResult {
  /** 鎼滅储鑱氬悎鍣紙鍚?MCP + DDG 鍚庣锛?*/
  aggregator: SearchAggregator | null;
  /** 鎴愬姛鍚姩鐨?MCP 鍚庣鏁?*/
  startedCount: number;
}

/**
 * 鍒濆鍖?MCP 鍚庣涓庢悳绱㈣仛鍚堝櫒銆俓r
 *
 * 璁剧疆 CORTEX_NO_SEARCH=1 鍙烦杩囨暣涓垵濮嬪寲娴佺▼銆俓r
 */
export async function bootstrapMcp(
  toolkit: Toolkit,
  configRoot: string,
): Promise<McpBootstrapResult> {
  if (process.env[ENV_CORTEX_NO_SEARCH] === "1") {
    return { aggregator: null, startedCount: 0 };
  }

  let mcpConfigs: McpServerConfig[] = [];

  // 1) 浼樺厛 mcpServers 鍩燂紙config 鍖?data/mcp-servers.json锛塡r
  try {
    const dataDir = resolveConfigDataDir();
    const readFile: ConfigFileReader = (fp) => nodeFs.readFileSync(fp, "utf-8");
    const servers = loadConfigDomain<Record<string, McpServerEntry>>("mcpServers", readFile, dataDir);
    if (servers) {
      mcpConfigs = Object.entries(servers)
        .filter(([key]) => !key.startsWith("_"))
        .map(([id, cfg]) => ({ id, ...cfg } as McpServerConfig))
        .filter((c) => c.enabled !== false);
    }
  } catch {
    // mcp-servers.json 缂哄け鈥斺€斿洖閫€ searchProviders
  }

  // 2) 鍥為€€ searchProviders锛堟棫鏍煎紡锛屼粠 cortex-agents.json 璇诲彇锛塡r
  if (mcpConfigs.length === 0) {
    const configPath = nodePath.join(configRoot, FILE_CORTEX_AGENTS_JSON);
    if (nodeFs.existsSync(configPath)) {
      const raw = JSON.parse(nodeFs.readFileSync(configPath, "utf-8"));
      const searchProviders = raw?.searchProviders;
      if (searchProviders?.backends && Array.isArray(searchProviders.backends)) {
        mcpConfigs = (searchProviders.backends as McpServerConfig[])
          .filter((b) => b.enabled !== false);
      }
    }
  }

  if (mcpConfigs.length === 0) {
    return { aggregator: null, startedCount: 0 };
  }

  const ddgBackend = new DdgSearchBackend();
  const started: McpSearchBackend[] = [];

  for (const cfg of mcpConfigs) {
    const backend = new McpSearchBackend({ ...cfg, env: {} });
    try {
      await backend.start();
      started.push(backend);
      toolkit.registerMcpClient(backend.getMcpClient());
      if (!process.env[ENV_VITEST]) {
        console.log(`[bootstrap] MCP 鍚庣宸茶繛鎺? ${cfg.id} (${backend.serverName ?? cfg.id})`);
      }
    } catch (e) {
      if (!process.env[ENV_VITEST]) {
        console.warn(`[bootstrap] MCP 鍚庣鍚姩澶辫触: ${cfg.id} 鈥?${String(e)}`);
      }
    }
  }

  if (started.length > 0) {
    const aggregator = new SearchAggregator({ backends: [...started, ddgBackend] });
    toolkit.setSearchAggregator(aggregator);
    return { aggregator, startedCount: started.length };
  }

  return { aggregator: null, startedCount: 0 };
}

#!/usr/bin/env node
 

/**
 * cli.ts 鈥?Markdown 鈫?HTML 鍛戒护琛岃浆鎹㈠櫒
 *
 * 鐢ㄦ硶:
 *   npx tsx packages/cli/src/cli.ts <杈撳叆>.md
 *   npx tsx packages/cli/src/cli.ts <杈撳叆>.md -o <杈撳嚭>.html
 *   npx tsx packages/cli/src/cli.ts <杈撳叆>.md --title "鏂囨。鏍囬"
 *
 * 榛樿杈撳嚭: <杈撳叆鏂囦欢鍚?.html
 *
 * 鍘熶綅浜?projects/solo-flight/packages/cli/src/cli.ts
 * 閫傞厤锛氫娇鐢?@cortex/parser 鏇夸唬鐩稿璺緞寮曠敤
 */

import fs from 'node:fs';
import path from 'node:path';
import { convert, convertToDocument } from '@cortex/parser';
import { CLI_EXIT_INTERNAL_ERROR } from '@cortex/config';

function printUsage(): void {
  console.error(`
鐢ㄦ硶: npx tsx packages/cli/src/cli.ts <杈撳叆鏂囦欢> [閫夐」]

鍙傛暟:
  <杈撳叆鏂囦欢>          杈撳叆鐨?Markdown 鏂囦欢璺緞 (.md)

閫夐」:
  -o, --output <鏂囦欢>  鎸囧畾杈撳嚭鐨?HTML 鏂囦欢璺緞
  -t, --title <鏍囬>   鎸囧畾鏂囨。鏍囬锛堥粯璁ゅ彇绗竴涓?# 鏍囬锛塡r
  -d, --document       杈撳嚭瀹屾暣 HTML 鏂囨。锛堝惈 DOCTYPE/head/style锛塡r
  -h, --help           鏄剧ず甯姪淇℃伅
`);
}

interface CliOptions {
  input: string;
  output?: string;
  title?: string;
  document?: boolean;
}

function parseArgs(argv: string[]): CliOptions | null {
  const args = argv.slice(2);
  if (args.length === 0 || args[0] === '--help' || args[0] === '-h') {
    printUsage();
    return null;
  }

  const options: CliOptions = { input: '' };
  let i = 0;

  while (i < args.length) {
    const arg = args[i];

    if (arg === '-o' || arg === '--output') {
      i++;
      if (i >= args.length) {
        console.error('鉁?閿欒: --output 闇€瑕佹寚瀹氭枃浠惰矾寰?);
        return null;
      }
      options.output = args[i];
    } else if (arg === '-t' || arg === '--title') {
      i++;
      if (i >= args.length) {
        console.error('鉁?閿欒: --title 闇€瑕佹寚瀹氭爣棰樻枃鏈?);
        return null;
      }
      options.title = args[i];
    } else if (arg === '-d' || arg === '--document') {
      options.document = true;
    } else if (arg.startsWith('-')) {
      console.error(`鉁?閿欒: 鏈煡閫夐」 "${arg}"`);
      return null;
    } else {
      if (!options.input) {
        options.input = arg;
      } else {
        console.error(`鉁?閿欒: 澶氫綑鍙傛暟 "${arg}"`);
        return null;
      }
    }
    i++;
  }

  if (!options.input) {
    console.error('鉁?閿欒: 鏈寚瀹氳緭鍏ユ枃浠?);
    return null;
  }

  return options;
}

function main(): void {
  const options = parseArgs(process.argv);
  if (!options) {
    process.exit(CLI_EXIT_INTERNAL_ERROR);
  }

  const inputPath = path.resolve(options.input);

  if (!fs.existsSync(inputPath)) {
    console.error(`鉁?閿欒: 鏂囦欢涓嶅瓨鍦?鈥?"${inputPath}"`);
    process.exit(CLI_EXIT_INTERNAL_ERROR);
  }

  const ext = path.extname(inputPath).toLowerCase();
  if (ext !== '.md' && ext !== '.markdown') {
    console.error(`鈿? 璀﹀憡: 杈撳叆鏂囦欢鎵╁睍鍚嶄负 "${ext}"锛岄鏈熶负 .md 鎴?.markdown`);
  }

  let markdown: string;
  try {
    markdown = fs.readFileSync(inputPath, 'utf-8');
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`鉁?閿欒: 璇诲彇鏂囦欢澶辫触 鈥?${msg}`);
    process.exit(CLI_EXIT_INTERNAL_ERROR);
  }

  if (markdown.length === 0) {
    console.error('鉁?閿欒: 杈撳叆鏂囦欢涓虹┖');
    process.exit(CLI_EXIT_INTERNAL_ERROR);
  }

  let outputPath: string;
  if (options.output) {
    outputPath = path.resolve(options.output);
  } else {
    const dir = path.dirname(inputPath);
    const basename = path.basename(inputPath, path.extname(inputPath));
    outputPath = path.join(dir, `${basename}.html`);
  }

  let html: string;
  try {
    if (options.document) {
      html = convertToDocument(markdown, options.title);
    } else {
      html = convert(markdown);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`鉁?閿欒: 杞崲澶辫触 鈥?${msg}`);
    process.exit(CLI_EXIT_INTERNAL_ERROR);
  }

  try {
    fs.writeFileSync(outputPath, html, 'utf-8');
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`鉁?閿欒: 鍐欏叆鏂囦欢澶辫触 鈥?${msg}`);
    process.exit(CLI_EXIT_INTERNAL_ERROR);
  }

  console.log(`鉁?杞崲瀹屾垚: ${path.basename(inputPath)} 鈫?${path.basename(outputPath)}`);
  console.log(`  杈撳嚭璺緞: ${outputPath}`);
  console.log(`  杈撳嚭澶у皬: ${html.length} 瀛楄妭`);
}

main();

