/**
 * commands/agent.ts 鈥?`cortex agent` Agent 绠＄悊鍛戒护
 *
 * 绠＄悊 Agent 绫诲瀷鐨勬敞鍐屻€佸疄渚嬬殑鐢熷懡鍛ㄦ湡銆佹煡鐪嬭繍琛屾椂鐘舵€併€俓r
 * 瀵规帴 AgentPool API锛堥€氳繃寮曟搸妗ユ帴鍣級銆俓r
 *
 * @see CLI 璁捐鏂囨。 搂4.1
 */

import type { CommandHandler, CommandResult, CommandContext } from "../types.js";
import { AGENT_CHINESE_ROLE, AgentStatus, AgentType, CHINESE_NAME_TO_TYPE, getAgentTags, getAgentToolPermissions, type AgentConfig, type ICortexApi } from "@cortex/shared";
import type { IAgentPool, StrategistAgent } from "@cortex/engine";
import * as fs from "node:fs";
import * as path from "node:path";

/** Agent 瀹炰緥鎸佷箙鍖栨枃浠讹紙璺ㄨ繘绋嬪叡浜?spawn/list 鐘舵€侊級 */
const INSTANCES_FILE = path.join(process.cwd(), ".cortex", "agent-instances.json");

interface PersistedInstances {
  [agentType: string]: number;
}

function readPersistedInstances(): PersistedInstances {
  try {
    if (fs.existsSync(INSTANCES_FILE)) {
      return JSON.parse(fs.readFileSync(INSTANCES_FILE, "utf-8"));
    }
  } catch { /* 鏂囦欢鎹熷潖鍒欏拷鐣?*/ }
  return {};
}

function writePersistedInstances(instances: PersistedInstances): void {
  const dir = path.dirname(INSTANCES_FILE);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(INSTANCES_FILE, JSON.stringify(instances, null, 2), "utf-8");
}

/**
 * 瑙ｆ瀽杈撳叆鈥斺€旀敮鎸佽嫳鏂?type 鍚嶅拰涓枃瑙掕壊鍚嶃€俓r
 * 杩斿洖 AgentType 鎴?undefined锛堟棤鏁堣緭鍏ワ級銆俓r
 */
function resolveAgentType(input: string): AgentType | undefined {
  // 1. 鐩存帴鍖归厤鑻辨枃 type 鍚峔r
  const byType = Object.values(AgentType).find((t) => t === input);
  if (byType) return byType;
  // 2. 涓枃鍚?鈫?AgentType
  return CHINESE_NAME_TO_TYPE[input];
}

/** 鑾峰彇涓枃瑙掕壊鍚嶏紙AgentType 鈫?涓枃鍚嶏紝strategist 杩斿洖 "閽熺/闇滃嚌"锛?*/
function getChineseRole(type: AgentType): string {
  return AGENT_CHINESE_ROLE[type] ?? type;
}

export function createAgentHandler(bridge: ICortexApi): CommandHandler {
  return async (args, options, context): Promise<CommandResult> => {
    if (args.length === 0 || args[0] === "--help" || args[0] === "-h") {
      return {
        success: true,
        output: [
          "鐢ㄦ硶: cortex agent <瀛愬懡浠? [閫夐」]",
          "",
          "瀛愬懡浠?",
          "  list                 鍒楀嚭鎵€鏈夊凡娉ㄥ唽 Agent 绫诲瀷",
          "  inspect <type>       鏌ョ湅 Agent 璇︽儏",
          "  spawn <type>         鎵嬪姩鍚姩 Agent 瀹炰緥",
          "  destroy <type>       鍥炴敹 Agent 瀹炰緥",
          "",
          "閫夐」:",
          "  --status <s>         鎸夌姸鎬佽繃婊?(awake/active/draining/destroyed)",
          "  --format <fmt>       杈撳嚭鏍煎紡 (text/json/color)",
          "  --count <n>          鍚姩瀹炰緥鏁帮紙榛樿 1锛塡

鏂瑰悜鐩戠悊\";\r\n const idTags = id =:
鏂瑰悜鐩戠悊";
    tags = id === "zhongli" ? ["strategy", "contract"] : ["strategy", "direction"];
    permissions = getAgentToolPermissions()[AgentType.Strategist] ?? [];
  } else {
    const p = safePool(pool);
    count = p.count(agentType);
    statuses = p.getStatuses(agentType);
    tags = getAgentTags()[agentType as AgentType] ?? [];
    permissions = getAgentToolPermissions()[agentType as AgentType] ?? [];
    role = getChineseRole(agentType);
  }

  return {
    success: true,
    data: {
      type: agentType,
      role,
      instances: count,
      statuses,
      tags,
      permissions,
    },
    output: [
      `Agent: ${agentType}锛?{role}锛塦,
      `瀹炰緥鏁? ${count}`,
      `鐘舵€? ${statuses.join(", ") || "鏈敞鍐孿

, ")}`,
      `宸ュ叿鏉冮檺: ${permissions.join(", ")}`,
    ].join("\n"),
    exitCode: 0,
  };
}

async function handleAgentSpawn(
  pool: IAgentPool,
  typeName: string | undefined,
  options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  if (!typeName) {
    return { success: false, error: "璇锋寚瀹?Agent 绫诲瀷銆傜敤娉? cortex agent spawn <type>", exitCode: 1 };
  }

  const p = safePool(pool);
  const count = parseInt(String(options["count"] ?? "1"), 10);
  const agentType = resolveAgentType(typeName);
  if (!agentType) {
    return { success: false, error: `鏈煡 Agent 绫诲瀷鎴栧悕绉? "${typeName}"`, exitCode: 1 };
  }
  let spawned = 0;

  for (let i = 0; i < count; i++) {
    const instanceId = `${typeName}-${Date.now()}-${i}`;
    const ok = p.spawn(agentType, instanceId);
    if (ok) spawned++;
  }

  // @fix H-03 鈥?妫€鏌?spawn 缁撴灉锛屽叏閮ㄥけ璐ユ椂杩斿洖閿欒
  if (spawned === 0) {
    return {
      success: false,
      error: `鎵€鏈?${count} 涓?spawn 璇锋眰鍧囧け璐ワ細Agent 绫诲瀷鏈敞鍐屾垨宸茶揪瀹炰緥涓婇檺`,
      exitCode: 1,
    };
  }

  // 鎸佷箙鍖栵細鍐欏叆璺ㄨ繘绋嬪叡浜殑瀹炰緥璁℃暟鏂囦欢
  const persisted = readPersistedInstances();
  persisted[agentType] = (persisted[agentType] ?? 0) + spawned;
  writePersistedInstances(persisted);

  return {
    success: true,
    output: `鉁?宸插惎鍔?${spawned}/${count} 涓?${typeName} 瀹炰緥`,
    data: { agentType, requested: count, spawned, failed: count - spawned },
    exitCode: 0,
  };
}

async function handleAgentDestroy(
  pool: IAgentPool,
  typeName: string | undefined,
  options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  if (!typeName) {
    return { success: false, error: "璇锋寚瀹?Agent 绫诲瀷銆傜敤娉? cortex agent destroy <type>", exitCode: 1 };
  }

  const p = safePool(pool);
  const instanceId = options["id"] as string | undefined;
  const agentType = resolveAgentType(typeName);
  if (!agentType) {
    return { success: false, error: `鏈煡 Agent 绫诲瀷鎴栧悕绉? "${typeName}"`, exitCode: 1 };
  }

  if (instanceId) {
    p.destroy(agentType, instanceId);
    // 鎸佷箙鍖栵細閫掑噺璁℃暟
    const persisted = readPersistedInstances();
    if (persisted[agentType] && persisted[agentType] > 0) {
      persisted[agentType]--;
      if (persisted[agentType] === 0) delete persisted[agentType];
      writePersistedInstances(persisted);
    }
    return {
      success: true,
      output: `鉁?宸插洖鏀跺疄渚?${instanceId}`,
      exitCode: 0,
    };
  }

  // @fix H-03 鈥?娌℃湁鎸囧畾瀹炰緥 ID 鏃惰繑鍥為敊璇€岄潪闈欓粯鎴愬姛
  return {
    success: false,
    error: `璇蜂娇鐢?--id <instanceId> 鎸囧畾瑕佸洖鏀剁殑瀹炰緥 ID`,
    exitCode: 1,
  };
}

