/**
 * commands/config.ts 鈥?`cortex config` 閰嶇疆绠＄悊鍛戒护
 *
 * 绠＄悊绯荤粺閰嶇疆鈥斺€旂幆澧冨彉閲忋€侀厤缃枃浠躲€佽繍琛屽弬鏁般€俓n * 鐩存帴瀵规帴 ConfigManager 鏈嶅姟銆俓n *
 * @see CLI 璁捐鏂囨。 搂4.7
 */

import type { CommandHandler, CommandResult, CommandContext } from "../types.js";
import { ConfigManager } from "../services/config-manager.js";
import * as path from "node:path";
import * as os from "node:os";

export function createConfigHandler(configManager: ConfigManager): CommandHandler {
  return async (args, options, context): Promise<CommandResult> => {
    if (args.length === 0 || args[0] === "--help" || args[0] === "-h") {
      return {
        success: true,
        output: [
          "鐢ㄦ硶: cortex config <瀛愬懡浠? [閫夐」]",
          "",
          "瀛愬懡浠?",
          "  list                 鍒楀嚭閰嶇疆椤筡

  --format <fmt>       杈撳嚭鏍煎紡",
          "  --global             鍐欏叆鍏ㄥ眬閰嶇疆",
          "  --local              鍐欏叆鏈湴閰嶇疆",
          "  --force, -f          瑕嗙洊宸叉湁閰嶇疆",
          "  --strict             涓ユ牸妯″紡",
        ].join("\n"),
        exitCode: 0,
      };
    }

    const subcommand = args[0];

    switch (subcommand) {
      case "list":
        return handleConfigList(configManager, options, context);
      case "get":
        return handleConfigGet(configManager, args[1], context);
      case "set":
        return handleConfigSet(configManager, args[1], args.slice(2).join(" "), options, context);
      case "init":
        return handleConfigInit(options, context);
      case "validate":
        return handleConfigValidate(configManager, options, context);
      default:
        return {
          success: false,
          error: `鏈煡瀛愬懡浠? "${subcommand}"銆傚彲鐢ㄥ瓙鍛戒护: list, get, set, init, validate`,
          exitCode: 1,
        };
    }
  };
}

function handleConfigList(
  config: ConfigManager,
  options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  const prefix = options["prefix"] as string | undefined;
  const all = config.getAll();

  // 鎵佸钩鍖栭厤缃甛n  const flatten = (obj: unknown, prefix = ""): Record<string, unknown> => {
    const result: Record<string, unknown> = {};
    if (obj && typeof obj === "object" && !Array.isArray(obj)) {
      for (const [key, value] of Object.entries(obj)) {
        const fullKey = prefix ? `${prefix}.${key}` : key;
        if (value && typeof value === "object" && !Array.isArray(value)) {
          Object.assign(result, flatten(value, fullKey));
        } else {
          result[fullKey] = value;
        }
      }
    }
    return result;
  };

  const flat = flatten(all);
  let entries = Object.entries(flat);

  if (prefix) {
    entries = entries.filter(([k]) => k.startsWith(prefix));
  }

  return {
    success: true,
    data: Object.fromEntries(entries),
    output: entries.map(([k, v]) => `${k} = ${JSON.stringify(v)}`).join("\n"),
    exitCode: 0,
  };
}

function handleConfigGet(
  config: ConfigManager,
  key: string | undefined,
  _context: CommandContext,
): CommandResult {
  if (!key) {
    return { success: false, error: "璇锋寚瀹氶厤缃敭銆傜敤娉? cortex config get <key>", exitCode: 1 };
  }

  const value = config.getNested(key);
  if (value === undefined) {
    return { success: false, error: `閰嶇疆椤逛笉瀛樺湪: ${key}`, exitCode: 1 };
  }

  return {
    success: true,
    data: { [key]: value },
    output: `${key} = ${JSON.stringify(value)}`,
    exitCode: 0,
  };
}

function handleConfigSet(
  config: ConfigManager,
  key: string | undefined,
  value: string | undefined,
  _options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  if (!key || value === undefined) {
    return { success: false, error: "璇锋寚瀹?key 鍜?value銆傜敤娉? cortex config set <key> <val>", exitCode: 1 };
  }

  // 灏濊瘯 JSON 瑙ｆ瀽
  let parsedValue: unknown = value;
  try { parsedValue = JSON.parse(value); } catch { /* 淇濇寔瀛楃涓?*/ }

  config.set(key, parsedValue);

  return {
    success: true,
    output: `鉁?${key} = ${JSON.stringify(parsedValue)}`,
    data: { [key]: parsedValue },
    exitCode: 0,
  };
}

function handleConfigInit(
  options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  const global_ = options["global"] as boolean;
  const force = options["force"] || options["f"];

  const configPath = global_
    ? path.join(os.homedir(), ".cortex", "config")
    : path.join(process.cwd(), ".cortex", "config");

  // 浣跨敤 ConfigManager 鍒濆鍖朶n  const mgr = new ConfigManager();
  const created = mgr.initConfig(configPath, !!force);

  if (created) {
    return { success: true, output: `鉁?閰嶇疆鏂囦欢宸插垱寤? ${configPath}`, exitCode: 0 };
  }
  return {
    success: true,
    output: `鈿狅笍 閰嶇疆鏂囦欢宸插瓨鍦? ${configPath}锛堜娇鐢?--force 瑕嗙洊锛塦,
    exitCode: 0,
  };
}

function handleConfigValidate(
  config: ConfigManager,
  options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  const strict = options["strict"] as boolean;
  const errors = config.validate(strict);

  if (errors.length === 0) {
    return { success: true, output: "鉁?閰嶇疆鏍￠獙閫氳繃", exitCode: 0 };
  }

  return {
    success: false,
    output: `閰嶇疆鏍￠獙澶辫触 (${errors.length} 椤?:\n${errors.map((e) => `  鉁?${e}`).join("\n")}`,
    data: { errors },
    exitCode: 3,
  };
}

/**
 * commands/confirm.ts 鈥?`cortex confirm` 纭闂ㄥ懡浠r
 *
 * 鏌ョ湅鍜屾搷浣滃緟纭鐨?L2/L3 鎿嶄綔銆俓r
 * 瀵规帴 ConfirmGate API銆俓r
 *
 * @see CLI 璁捐鏂囨。 搂4.12
 */

import type { CommandHandler, CommandResult, CommandContext } from "../types.js";
import type { ICortexApi, IConfirmGate } from "@cortex/shared";
import { CLI_EXIT_SUCCESS, CLI_EXIT_CONFIRM_DENIED } from "@cortex/config";

export function createConfirmHandler(bridge: ICortexApi): CommandHandler {
  return async (args, options, context): Promise<CommandResult> => {
    if (args.length === 0 || args[0] === "--help" || args[0] === "-h") {
      return {
        success: true,
        output: [
          "鐢ㄦ硶: cortex confirm <瀛愬懡浠? [閫夐」]",
          "",
          "瀛愬懡浠?",
          "  pending               鍒楀嚭寰呯‘璁ょ殑鎿嶄綔",
          "  approve <id>          鎵瑰噯鎿嶄綔",
          "  reject <id>           鎷掔粷鎿嶄綔",
          "",
          "閫夐」:",
          "  --level <l>           鎸夌瓑绾ц繃婊?(L2/L3)",
          "  --agent <type>        鎸夎姹?Agent 杩囨护",
          "  --format <fmt>        杈撳嚭鏍煎紡",
          "  --reason <text>       鎵瑰噯/鎷掔粷鐞嗙敱",
        ].join("\n"),
        exitCode: 0,
      };
    }

    const subcommand = args[0];

    try {
      const gate = await bridge.getConfirmGate();

      switch (subcommand) {
        case "pending":
          return handleConfirmPending(gate, options, context);
        case "approve":
          return handleConfirmApprove(gate, args[1], options, context);
        case "reject":
          return handleConfirmReject(gate, args[1], options, context);
        default:
          return {
            success: false,
            error: `鏈煡瀛愬懡浠? "${subcommand}"銆傚彲鐢ㄥ瓙鍛戒护: pending, approve, reject`,
            exitCode: 1,
          };
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      return { success: false, error: `纭闂ㄦ搷浣滃け璐? ${msg}`, exitCode: 2 };
    }
  };
}

function handleConfirmPending(
  gate: IConfirmGate,
  _options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  const hasPending = gate.hasPending();

  return {
    success: true,
    data: { hasPending, pendingCount: hasPending ? 1 : 0 },
    output: hasPending
      ? "鏈夊緟澶勭悊鐨勭‘璁よ姹俓

璇锋寚瀹氱‘璁よ姹?ID銆傜敤娉? cortex confirm approve <id>", exitCode: 1 };
  }

  // ConfirmGate.resolve() 鏄鐞嗙敤鎴峰搷搴旂殑鍏ュ彛
  const result = gate.resolve({
    requestId,
    approved: true,
  });

  return {
    success: result,
    output: result ? `鉁?宸叉壒鍑? ${requestId}` : `鎵瑰噯澶辫触: ${requestId}锛堣姹備笉瀛樺湪鎴栧凡澶勭悊锛塦,
    data: { requestId, approved: true },
    exitCode: result ? 0 : 1,
  };
}

function handleConfirmReject(
  gate: IConfirmGate,
  requestId: string | undefined,
  _options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  if (!requestId) {
    return { success: false, error: "璇锋寚瀹氱‘璁よ姹?ID銆傜敤娉? cortex confirm reject <id>", exitCode: 1 };
  }

  const result = gate.resolve({
    requestId,
    approved: false,
  });

  return {
    success: result,
    output: result ? `鉁?宸叉嫆缁? ${requestId}` : `鎷掔粷澶辫触: ${requestId}锛堣姹備笉瀛樺湪鎴栧凡澶勭悊锛塦,
    data: { requestId, approved: false },
    exitCode: result ? CLI_EXIT_SUCCESS : CLI_EXIT_CONFIRM_DENIED,
  };
}

