/**
 * commands/doc.ts 鈥?`cortex doc` 鏂囨。宸ュ叿鍛戒护
 *
 * 缁ф壙鐜版湁 packages/cli/ 鐨?Markdown鈫扝TML 杞崲鍔熻兘锛孿r
 * 骞舵墿灞曟枃妗ｅ悎瑙勬鏌ャ€俓r
 *
 * @see CLI 璁捐鏂囨。 搂4.8
 */

import type { CommandHandler, CommandResult, CommandContext } from "../types.js";
import { convert, convertToDocument } from "@cortex/parser";
import * as fs from "node:fs";
import * as path from "node:path";
import { createServer } from "node:http";

export function createDocHandler(): CommandHandler {
  return async (args, options, context): Promise<CommandResult> => {
    if (args.length === 0 || args[0] === "--help" || args[0] === "-h") {
      return {
        success: true,
        output: [
          "鐢ㄦ硶: cortex doc <瀛愬懡浠? [閫夐」]",
          "",
          "瀛愬懡浠?",
          "  convert <file>       杞崲 Markdown鈫扝TML",
          "  serve <dir>          鍚姩鏂囨。鏈嶅姟鍣╘

\n"),
        exitCode: 0,
      };
    }

    const subcommand = args[0];

    switch (subcommand) {
      case "convert":
        return handleDocConvert(args[1], options, context);
      case "serve":
        return handleDocServe(args[1], options, context);
      case "check":
        return handleDocCheck(args[1], options, context);
      default:
        return {
          success: false,
          error: `鏈煡瀛愬懡浠? "${subcommand}"銆傚彲鐢ㄥ瓙鍛戒护: convert, serve, check`,
          exitCode: 1,
        };
    }
  };
}

function handleDocConvert(
  filePath: string | undefined,
  options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  if (!filePath) {
    return { success: false, error: "璇锋寚瀹氳緭鍏ユ枃浠躲€傜敤娉? cortex doc convert <file>", exitCode: 1 };
  }

  const resolvedPath = path.resolve(filePath);
  if (!fs.existsSync(resolvedPath)) {
    return { success: false, error: `鏂囦欢涓嶅瓨鍦? ${resolvedPath}`, exitCode: 1 };
  }

  const ext = path.extname(filePath).toLowerCase();
  if (ext !== ".md" && ext !== ".markdown") {
    return { success: false, error: `涓嶆敮鎸佺殑鏂囦欢鏍煎紡: ${ext}锛堜粎鏀寔 .md锛塦, exitCode: 1 };
  }

  try {
    const markdown = fs.readFileSync(resolvedPath, "utf-8");
    const title = options["title"] as string | undefined;
    const documentMode = options["document"] as boolean;
    const outputPath = (options["output"] ?? options["o"]) as string | undefined;

    let html: string;
    if (documentMode) {
      html = convertToDocument(markdown, title);
    } else {
      html = convert(markdown);
    }

    if (outputPath) {
      const resolvedOutput = path.resolve(outputPath);
      fs.writeFileSync(resolvedOutput, html, "utf-8");
      return {
        success: true,
        output: `鉁?杞崲瀹屾垚: ${path.basename(filePath)} 鈫?${path.basename(outputPath)}`,
        data: { input: filePath, output: outputPath, size: html.length },
        exitCode: 0,
      };
    }

    return {
      success: true,
      output: html,
      data: { html, size: html.length },
      exitCode: 0,
    };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return { success: false, error: `杞崲澶辫触: ${msg}`, exitCode: 2 };
  }
}

function handleDocServe(
  dirPath: string | undefined,
  options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  const rootDir = dirPath ? path.resolve(dirPath) : process.cwd();
  const port = parseInt(String(options["port"] ?? "8080"), 10);

  if (!fs.existsSync(rootDir)) {
    return { success: false, error: `鐩綍涓嶅瓨鍦? ${rootDir}`, exitCode: 1 };
  }

  const server = createServer((req, res) => {
    const url = new URL(req.url ?? "/", `http://localhost:${port}`);
    // @fix B1 (code-review) 鈥?璺緞绌胯秺淇濇姢
    const normalizedRoot = path.resolve(rootDir);
    let filePath = path.resolve(normalizedRoot, "." + url.pathname);
    if (!filePath.startsWith(normalizedRoot + path.sep) && filePath !== normalizedRoot) {
      res.writeHead(403);
      res.end("403 Forbidden");
      return;
    }

    if (!fs.existsSync(filePath)) {
      res.writeHead(404, { "Content-Type": "text/plain" });
      res.end("404 Not Found");
      return;
    }

    const stat = fs.statSync(filePath);
    if (stat.isDirectory()) {
      filePath = path.join(filePath, "index.html");
      if (!fs.existsSync(filePath)) {
        res.writeHead(404);
        res.end("404 Not Found");
        return;
      }
    }

    const content = fs.readFileSync(filePath, "utf-8");
    const ext = path.extname(filePath);
    const mime: Record<string, string> = {
      ".html": "text/html",
      ".css": "text/css",
      ".js": "application/javascript",
      ".json": "application/json",
    };

    res.writeHead(200, { "Content-Type": mime[ext] ?? "text/plain" });
    res.end(content);
  });

  server.listen(port, () => {
    console.log(`馃摉 鏂囨。鏈嶅姟鍣ㄥ惎鍔? http://localhost:${port}`);
    console.log(`   鏍圭洰褰? ${rootDir}`);
  });

  // @fix P1-4 (code-review) 鈥?娉ㄥ唽 SIGINT/SIGTERM 娓呯悊璺緞锛孿r
  // 閬垮厤 `cortex doc serve` 閫€鍑哄悗绔彛浠嶈鍗犵敤銆俓r
  // @fix S2 鈥?process.once + _cleanedUp 骞傜瓑闃叉姢锛岄槻姝㈤噸澶嶆墽琛屻€俓r
  let _cleanedUp = false;
  const cleanup = () => {
    if (_cleanedUp) return;
    _cleanedUp = true;
    server.close(() => {
      console.log("\n馃摉 鏂囨。鏈嶅姟鍣ㄥ凡鍏抽棴");
      process.exit(0);
    });
  };
  process.once("SIGINT", cleanup);
  process.once("SIGTERM", cleanup);

  // 鍦ㄥ師鍨嬮樁娈碉紝serve 鍛戒护淇濇寔杩涚▼杩愯
  return {
    success: true,
    output: `鏂囨。鏈嶅姟鍣ㄨ繍琛屼簬 http://localhost:${port}`,
    exitCode: 0,
  };
}

function handleDocCheck(
  filePath: string | undefined,
  options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  if (!filePath) {
    return { success: false, error: "璇锋寚瀹氭枃浠躲€傜敤娉? cortex doc check <file>", exitCode: 1 };
  }

  const resolvedPath = path.resolve(filePath);
  if (!fs.existsSync(resolvedPath)) {
    return { success: false, error: `鏂囦欢涓嶅瓨鍦? ${resolvedPath}`, exitCode: 1 };
  }

  try {
    const content = fs.readFileSync(resolvedPath, "utf-8");
    const rules = ((options["rules"] as string) ?? "links,headings").split(",");

    const issues: string[] = [];

    // 鍩烘湰鍚堣妫€鏌r
    if (rules.includes("headings")) {
      const lines = content.split("\n");
      let prevLevel = 0;
      for (let i = 0; i < lines.length; i++) {
        const match = lines[i].match(/^(#{1,6})\s/);
        if (match) {
          const level = match[1].length;
          if (prevLevel > 0 && level > prevLevel + 1) {
            issues.push(`绗?${i + 1} 琛? 鏍囬绾у埆璺宠穬 (h${prevLevel} 鈫?h${level})`);
          }
          prevLevel = level;
        }
      }
    }

    if (rules.includes("links")) {
      const linkMatches = content.matchAll(/\[([^\]]+)\]\(([^)]+)\)/g);
      for (const match of linkMatches) {
        const url = match[2];
        if (url.startsWith("http") && !url.startsWith("http://localhost")) {
          // 澶栭儴閾炬帴鈥斺€斾粎璁板綍
          issues.push(`澶栭儴閾炬帴: ${match[1]} 鈫?${url}`);
        }
      }
    }

    return {
      success: issues.length === 0,
      output: issues.length === 0
        ? "鉁?鏂囨。鍚堣妫€鏌ラ€氳繃"
        : `鏂囨。鍚堣妫€鏌? ${issues.length} 椤筡
${issues.map((i) => `  ${i}`).join("\n")}`,
      data: { file: filePath, issues, passed: issues.length === 0 },
      exitCode: issues.length === 0 ? 0 : 2,
    };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return { success: false, error: `妫€鏌ュけ璐? ${msg}`, exitCode: 2 };
  }
}

