/**
 * commands/doctor.ts 鈥?`cortex doctor` Monorepo 鍋ュ悍璇婃柇鍛戒护
 *
 * 闆嗘垚 @cortex/doctor 鐨勫仴搴锋鏌ョ绾匡紝鎻愪緵椤圭洰鍋ュ悍鐘舵€佽瘖鏂€俓r
 * 鏀寔鏂囨湰/JSON 杈撳嚭銆佹鏌ュ櫒绛涢€夈€佸仴搴峰垎闃堝€奸樆鏂€俓r
 *
 * @see CLI 璁捐鏂囨。 搂4.16
 */

import type { CommandHandler, CommandResult } from "../types.js";
import { HealthChecker, type DoctorOptions, type HealthReport } from "@cortex/doctor";
import * as fs from "node:fs";
import * as path from "node:path";

export function createDoctorHandler(): CommandHandler {
