/**
 * commands/help.ts 鈥?`cortex help` 甯姪淇℃伅鍛戒护
 *
 * 鏄剧ず鍛戒护鎬昏鎴栫壒瀹氬懡浠ょ殑璇︾粏甯姪銆俓r
 *
 * @see CLI 璁捐鏂囨。 搂4.16
 */

import type { CommandHandler, CommandResult } from "../types.js";
import type { CommandRegistry } from "./index.js";

export function createHelpHandler(registry: CommandRegistry): CommandHandler {
  return async (args, _options, _context): Promise<CommandResult> => {
    // 濡傛灉鎸囧畾浜嗗懡浠ゅ悕锛屾樉绀鸿鍛戒护鐨勫府鍔‐r
    const cmdName = args[0];
    if (cmdName) {
      const cmd = registry.find(cmdName);
      if (cmd) {
        // 浠庡懡浠ゅ厓鏁版嵁鏋勯€犲府鍔╂枃鏈琝r
        const lines: string[] = [];
        lines.push("");
        lines.push(`鍛戒护: cortex ${cmd.name}`);
        if (cmd.alias) lines.push(`鍒悕: ${cmd.alias}`);
        lines.push(`鎻忚堪: ${cmd.description}`);

        if (cmd.subcommands && Object.keys(cmd.subcommands).length > 0) {
          lines.push("");
          lines.push("瀛愬懡浠?");
          for (const [subName, sub] of Object.entries(cmd.subcommands)) {
            lines.push(`  ${subName.padEnd(12)} ${sub.description}`);
            if (sub.usage) lines.push(`    鐢ㄦ硶: ${sub.usage}`);
          }
        }

        return {
          success: true,
          output: lines.join("\n"),
          exitCode: 0,
        };
      }
      return {
        success: false,
        error: `娌℃湁 "${cmdName}" 鐨勫府鍔╀俊鎭€傝緭鍏?'cortex help' 鏌ョ湅鍏ㄩ儴鍛戒护銆俙,
        exitCode: 1,
      };
    }

    // 鎬昏
    const commands = registry.getCommandNames().sort();
    const aliases = registry.getAliases();

    const cmdList = commands.map((name) => {
      const alias = [...aliases.entries()].find(([, v]) => v === name)?.[0];
      const aliasStr = alias ? ` (鍒悕: ${alias})` : "";
      return `  ${name.padEnd(14)}${aliasStr}`;
    });

    return {
      success: true,
      output: [
        "Cortex CLI 鈥?缁熶竴鍛戒护琛屽墠绔痋

/**
 * commands/index.ts 鈥?鍛戒护娉ㄥ唽琛ㄤ笌璺敱
 *
 * 缁存姢鎵€鏈夐《绾у懡浠ゅ強鍏跺瓙鍛戒护鐨勬敞鍐屾槧灏勩€俓n * 鏀寔鐭埆鍚嶈В鏋愬拰妯＄硦鍖归厤銆俓n *
 * @see CLI 璁捐鏂囨。 搂3锛堝懡浠や綋绯绘€昏锛塡n */

import type { CommandDefinition, CommandContext, CommandResult } from "../types.js";

export class CommandRegistry {
  private commands = new Map<string, CommandDefinition>();
  private aliases = new Map<string, string>();

  /** 娉ㄥ唽涓€涓《绾у懡浠?*/
  register(cmd: CommandDefinition): void {
    this.commands.set(cmd.name, cmd);
    if (cmd.alias) {
      this.aliases.set(cmd.alias, cmd.name);
    }
  }

  /** 鎵归噺娉ㄥ唽鍛戒护 */
  registerAll(cmds: CommandDefinition[]): void {
    for (const cmd of cmds) {
      this.register(cmd);
    }
  }

  /** 鏍规嵁鍛戒护鍚嶆煡鎵惧畾涔夛紙鏀寔鍒悕瑙ｆ瀽锛?*/
  find(name: string): CommandDefinition | undefined {
    const resolvedName = this.aliases.get(name) ?? name;
    return this.commands.get(resolvedName);
  }

  /** 鑾峰彇鎵€鏈夋敞鍐岀殑鍛戒护鍚?*/
  getCommandNames(): string[] {
    return Array.from(this.commands.keys());
  }

  /** 鑾峰彇鎵€鏈夊埆鍚嶆槧灏?*/
  getAliases(): Map<string, string> {
    return new Map(this.aliases);
  }

  /**
   * 瑙ｆ瀽骞舵墽琛屽懡浠ゃ€俓n   * 杈撳叆鏍煎紡锛歔"agent", "list", "--status", "awake"]
   * 杩斿洖鎵ц缁撴灉銆俓n   */
  async dispatch(
    args: string[],
    context: CommandContext,
  ): Promise<CommandResult> {
    if (args.length === 0) {
      return {
        success: false,
        error: "鏈寚瀹氬懡浠ゃ€傝緭鍏?'cortex help' 鏌ョ湅鍙敤鍛戒护銆俓

${cmdName}"銆傝緭鍏?'cortex help' 鏌ョ湅鍙敤鍛戒护銆俙,
        exitCode: 1,
      };
    }

    // 瑙ｆ瀽瀛愬懡浠n    const subArgs = args.slice(1);
    if (cmd.subcommands && subArgs.length > 0) {
      const subName = subArgs[0];
      const sub = cmd.subcommands[subName];
      if (sub) {
        // 瑙ｆ瀽鍓╀綑鍙傛暟鍜岄€夐」
        const { options, remaining } = this._parseOptions(subArgs.slice(1));
        return await sub.handler(remaining, options, context);
      }
    }

    // 瑙ｆ瀽閫夐」骞惰皟鐢ㄩ《绾у鐞嗗櫒
    const { options: _parsedOptions, remaining: _parsedRemaining } = this._parseOptions(subArgs);
    return await cmd.handler(_parsedRemaining, _parsedOptions, context);
  }

  /** 绠€鍗曢€夐」瑙ｆ瀽鍣?*/
  private _parseOptions(args: string[]): { options: Record<string, unknown>; remaining: string[] } {
    const options: Record<string, unknown> = {};
    const remaining: string[] = [];

    for (let i = 0; i < args.length; i++) {
      const arg = args[i];

      if (arg.startsWith("--")) {
        const eqIdx = arg.indexOf("=");
        if (eqIdx !== -1) {
          // --key=value
          options[arg.slice(2, eqIdx)] = arg.slice(eqIdx + 1);
        } else {
          const key = arg.slice(2);
          if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
            options[key] = args[++i];
          } else {
            options[key] = true;
          }
        }
      } else if (arg.startsWith("-") && arg.length === 2) {
        // 鐭€夐」 -k
        const key = arg.slice(1);
        if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
          options[key] = args[++i];
        } else {
          options[key] = true;
        }
      } else {
        remaining.push(arg);
      }
    }

    return { options, remaining };
  }
}

