/**
 * commands/inspect.ts 鈥?`cortex inspect` 椤圭洰渚﹀療鍛戒护
 *
 * 瀹夋煆锛圛nspectorAgent锛夌殑鏍稿績鑳藉姏鈥斺€斾睛瀵熺洰褰曠粨鏋勩€佷緷璧栨嫇鎵戙€侀厤缃紓绉汇€俓n *
 * @see CLI 璁捐鏂囨。 搂4.9
 */

import type { CommandHandler, CommandResult, CommandContext } from "../types.js";
import { buildEdges, collectDependencies, collectDeps, collectPackages, detectCycles, detectDrift, findProjectRoot, generateDot } from "@cortex/tools";
import * as fs from "node:fs";
import * as path from "node:path";

export function createInspectHandler(): CommandHandler {
  return async (args, options, context): Promise<CommandResult> => {
    if (args.length === 0 || args[0] === "--help" || args[0] === "-h") {
      return {
        success: true,
        output: [
          "鐢ㄦ硶: cortex inspect <瀛愬懡浠? [閫夐」]",
          "",
          "瀛愬懡浠?",
          "  dir <path>            渚﹀療鐩綍缁撴瀯",
          "  deps                  渚﹀療渚濊禆鎷撴墤",
          "  drift                 渚﹀療閰嶇疆婕傜Щ",
          "  report                鐢熸垚瀹屾暣渚﹀療鎶ュ憡",
          "",
          "閫夐」:",
          "  --depth <n>           閫掑綊娣卞害锛堥粯璁?3锛塡

\n"),
        exitCode: 0,
      };
    }

    const subcommand = args[0];

    switch (subcommand) {
      case "dir":
        return handleInspectDir(args[1], options, context);
      case "deps":
        return handleInspectDeps(options, context);
      case "drift":
        return handleInspectDrift(options, context);
      case "report":
        return handleInspectReport(options, context);
      default:
        return {
          success: false,
          error: `鏈煡瀛愬懡浠? "${subcommand}"銆傚彲鐢ㄥ瓙鍛戒护: dir, deps, drift, report`,
          exitCode: 1,
        };
    }
  };
}

function handleInspectDir(
  dirPath: string | undefined,
  options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  const target = dirPath ? path.resolve(dirPath) : process.cwd();
  const depth = parseInt(String(options["depth"] ?? "3"), 10);

  if (!fs.existsSync(target)) {
    return { success: false, error: `鐩綍涓嶅瓨鍦? ${target}`, exitCode: 1 };
  }

  interface DirEntry {
    name: string;
    type: "directory" | "file";
    children?: DirEntry[];
  }

  function scanDir(dir: string, currentDepth: number): DirEntry[] {
    if (currentDepth > depth) return [];
    const entries: DirEntry[] = [];
    try {
      const items = fs.readdirSync(dir, { withFileTypes: true });
      for (const item of items) {
        if (item.name.startsWith(".") || item.name === "node_modules") continue;
        entries.push({
          name: item.name,
          type: item.isDirectory() ? "directory" : "file",
          ...(item.isDirectory() ? { children: scanDir(path.join(dir, item.name), currentDepth + 1) } : {}),
        });
      }
    } catch { /* 鏉冮檺閿欒蹇界暐 */ }
    return entries;
  }

  const tree = scanDir(target, 0);

  return {
    success: true,
    data: { root: target, depth, entries: tree },
    output: `鐩綍缁撴瀯: ${target} (娣卞害 ${depth})`,
    exitCode: 0,
  };
}

function handleInspectDeps(
  options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  const graphFormat = options["graph"] as boolean;
  const detectCyclesOpt = options["cycles"] as boolean;

  const root = findProjectRoot(process.cwd());
  const packages = collectPackages(root);
  const allDeps = collectDeps(root, packages);
  const edges = buildEdges(packages, allDeps, false);

  // 鏋勫缓鍖呭悕鈫抴orkspace渚濊禆鏄犲皠
  const deps: Record<string, string[]> = {};
  for (const pkg of packages) {
    if (pkg.isRoot) continue;
    const pkgEdges = edges.filter((e) => e.from === pkg.id);
    deps[pkg.name] = pkgEdges.map((e) => e.to);
  }

  if (graphFormat) {
    const cycles = detectCyclesOpt ? detectCycles(edges) : [];
    const dot = generateDot(packages, edges, cycles);
    return {
      success: true,
      output: dot,
      data: { dot, deps, edges },
      exitCode: 0,
    };
  }

  let output = Object.entries(deps)
    .map(([pkg, targets]) => `  ${pkg} 鈫?${targets.join(", ") || "(鏃?workspace 渚濊禆)"}`)
    .join("\n");

  if (detectCyclesOpt) {
    const cycles = detectCycles(edges);
    if (cycles.length > 0) {
      output += "\n\n鈿狅笍 寰幆渚濊禆:";
      for (const cycle of cycles) {
        output += `\n  ${cycle.path.join(" 鈫?")}`;
      }
    } else {
      output += "\n\n鉁?鏈彂鐜板惊鐜緷璧朶

鉁?鏈彂鐜扮増鏈紓绉伙紙鎵€鏈夊悓鍚嶄緷璧栫増鏈竴鑷达級",
      exitCode: 0,
    };
  }

  const lines = [`鉂?鍙戠幇 ${drifts.length} 澶勭増鏈紓绉?\n`];
  for (const drift of drifts) {
    lines.push(`  ${drift.depName}:`);
    for (const entry of drift.entries) {
      lines.push(`    ${entry.pkg}: ${entry.version}`);
    }
    lines.push("");
  }

  return {
    success: true,
    data: { drifts },
    output: lines.join("\n"),
    exitCode: 0,
  };
}

function handleInspectReport(
  options: Record<string, unknown>,
  _context: CommandContext,
): CommandResult {
  const outputPath = (options["output"] ?? options["o"]) as string | undefined;

  const report = {
    timestamp: new Date().toISOString(),
    dependencies: {},
    structure: {},
  };

  if (outputPath) {
    fs.writeFileSync(path.resolve(outputPath), JSON.stringify(report, null, 2), "utf-8");
    return {
      success: true,
      output: `鉁?渚﹀療鎶ュ憡宸茬敓鎴? ${outputPath}`,
      data: report,
      exitCode: 0,
    };
  }

  return {
    success: true,
    data: report,
    output: "渚﹀療鎶ュ憡宸茬敓鎴愶紙浣跨敤 --output 淇濆瓨鍒版枃浠讹級",
    exitCode: 0,
  };
}

