        topic ? `   璁: ${topic}` : "   璁: 浣跨敤妯℃澘榛樿",
        outputPath ? `   杈撳嚭: ${outputPath}` : "   杈撳嚭: stdout",
      ].join("\n"),
      exitCode: 0,
    };
  }

  // 鈹€鈹€ 鐪熸鐨勫渾妗岃京璁猴細澶?Agent 閫氳繃 LLM 鍋氬杞璇?鈹€鈹€
  const topicText = topic ?? template.description;
  const rounds = template.rounds;
  const agentNames = template.agents;

  console.log(`馃 鍦嗘浼氳鍚姩: ${template.name}`);
