  const systemPrompt = buildRoundtableSystemPrompt(template, topicText);
  const messages: LlmMessage[] = [
    { role: "system", content: systemPrompt },
    { role: "user", content: `璇峰紑濮嬬 1 杞渾妗岃京璁恒€傝棰? ${topicText}` },
  ];

  let consensusContent = "";
  try {
    // 澶氳疆杈╄锛氭瘡杞拷鍔犲墠涓€杞緭鍑轰綔涓轰笂涓嬫枃
    for (let r = 1; r <= rounds; r++) {
      console.log(`  鈴?绗?${r}/${rounds} 杞京璁轰腑...`);
      const response = await bridge.directChat(systemPrompt, messages);
      if (response) {
        messages.push({ role: "assistant", content: response });
        messages.push({
          role: "user",
          content: r < rounds
            ? `绗?${r + 1} 杞細璇峰湪鍓嶄竴杞熀纭€涓婃繁鍏ヨ京璁猴紝鏀舵潫鍒嗘锛屼骇鍑哄叿浣撶粨璁恒€俙
            : "杈╄缁撴潫銆傝浜у嚭鏈€缁堝叡璇嗘竻鍗曗€斺€旀寜 P0/P1/P2/寤鸿 鍒嗙被锛屾瘡鏉￠檮涓€鍙ヨ瘽鐞嗙敱銆俓

",
    `- 妯℃澘: ${template.description}`,
    `- 杞: ${template.rounds}`,
    `- 鍙備笌: ${template.agents.join(", ")}`,
    `- 璁: ${topicText}`,
    "",
    "## 鍏辫瘑浜у嚭",
    "",
    consensusContent,
  ].join("\n");

  // 閫氳繃 DocRegistry 娉ㄥ唽褰掓。
  const docType = template.name === "attribution" ? "attribution" as const : "consensus" as const;
  const committeeType = template.name === "attribution" || template.name === "review" ? "standing" as const : "ad-hoc" as const;

  let registryInfo: string;
  try {
    const entry = await docRegistry.register({
      type: docType,
      title: `鍦嗘-${template.name}${topic ? `: ${topicText.slice(0, 40)}` : ""}`,
      content: output,
      authors: template.agents,
