      `馃 鍦嗘浼氳瀹屾垚: ${template.name}`,
      `   杞: ${template.rounds}  |  鍙備笌: ${template.agents.join(", ")}`,
      topicText ? `   璁: ${topicText.slice(0, 60)}${topicText.length > 60 ? "..." : ""}` : "",
      "",
      consensusContent.slice(0, 500) + (consensusContent.length > 500 ? "\n...(鎴柇)" : ""),
      "",
