      registryInfo,
    ].filter(Boolean).join("\n"),
    exitCode: 0,
  };
}

/** 鏋勫缓鍦嗘杈╄ system prompt鈥斺€旇 LLM 鎵紨澶氫綅 Agent 杩涜澶氳疆瀵硅瘽 */
