- 浜嬮」2: 鐞嗙敱",
  ].join("\n");
}

async function handleRoundtableList(
  options: Record<string, unknown>,
  context: CommandContext,
  bridge: EngineBridge,
): Promise<CommandResult> {
  const detail = options["detail"] || options["d"];

  const ctx = await bridge.ensureBootstrappedContext();
