        } else {
          html = convert(content);
        }

        if (outputPath) {
          fs.writeFileSync(path.resolve(outputPath), html, "utf-8");
          return {
            success: true,
            output: `鉁?杞崲瀹屾垚: ${path.basename(outputPath)}`,
            data: { outputPath, size: html.length },
            exitCode: 0,
          };
        }

        return {
          success: true,
          output: html,
          data: { html, size: html.length },
          exitCode: 0,
        };
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        return { success: false, error: `杞崲澶辫触: ${msg}`, exitCode: 2 };
      }
    }

    // 鈹€鈹€ Engine 璋冨害璺緞 鈹€鈹€
    try {
      if (bridge.isBootstrapConfigured) {
        await bridge.ensureBootstrapped();
      } else {
        await bridge.ensureInitialized();
      }
      const board = await bridge.getTaskBoard();
      const scheduler = await bridge.getScheduler();

      const taskNode: TaskNode = {
        id: `cli-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: agentType ?? "analysis",
        tags: (agentType ? [agentType] : ["analysis"]) as Tag[],
        needsMultiPerspective: false,
        status: "pending",
        claimedBy: [],
        payload: content,
        results: [],
        createdAt: Date.now(),
      };

      board.addNode(taskNode);
      const report = await scheduler.executeAll();

      if (report.completed > 0) {
        const result = report.results[0];
        return {
          success: true,
          output: result.output ?? "鉁?鎵ц瀹屾垚",
          data: {
            totalNodes: report.totalNodes,
            completed: report.completed,
            failed: report.failed,
            durationMs: report.durationMs,
            result,
          },
          exitCode: 0,
        };
      }

      const errorDetails = report.results
        .filter((r: { success: boolean }) => !r.success)
        .map((r: { nodeId: string; error?: string }) => `  [${r.nodeId}] ${r.error ?? "鏈煡閿欒"}`)
        .join("\n");
      return {
        success: false,
        error: `鎵ц澶辫触: ${report.failed}/${report.totalNodes} 鑺傜偣澶辫触\n${errorDetails}`,
        data: report,
        exitCode: 2,
      };
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      return { success: false, error: `璋冨害鎵ц澶辫触: ${msg}`, exitCode: 2 };
    }
  };
}

