  _context: CommandContext,
): Promise<CommandResult> {
  if (!filePath) {
    return { success: false, error: "璇锋寚瀹氫换鍔℃弿杩版枃浠躲€傜敤娉? cortex schedule plan <file>", exitCode: 1 };
  }

