    exitCode: 0,
  };
}

async function handleScheduleRun(
  bridge: ICortexApi,
  planPath: string | undefined,
  _options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  if (!planPath) {
    return { success: false, error: "璇锋寚瀹氳鍒掓枃浠躲€傜敤娉? cortex schedule run <plan>", exitCode: 1 };
  }

  const board = await bridge.getTaskBoard() as ITaskBoard;
  const scheduler = await bridge.getScheduler() as IScheduler;

  try {
    const content = fs.readFileSync(path.resolve(planPath), "utf-8");
    const plan = JSON.parse(content);

    if (plan.tasks) {
      for (let i = 0; i < plan.tasks.length; i++) {
        const t = plan.tasks[i];
        board.addNode({
          id: t.id ?? `sched-${Date.now()}-${i}`,
          type: t.type ?? "analysis",
          tags: (t.tags ?? ["analysis"]) as Tag[],
          needsMultiPerspective: false,
          status: "pending",
          claimedBy: [],
          payload: t.payload ?? "",
          results: [],
          createdAt: Date.now(),
        });
      }
    }

    const report = await scheduler.executeAll();
    return {
      success: report.completed > 0,
      output: `璋冨害鎵ц瀹屾垚: ${report.completed}/${report.totalNodes} 鎴愬姛`,
      data: report,
      exitCode: report.completed > 0 ? 0 : 2,
    };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
