  }
}

async function handleScheduleStatus(
  bridge: ICortexApi,
  _options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  const board = await bridge.getTaskBoard() as ITaskBoard;

  const allNodes = board.getAllNodes();
  const pendingNodes = board.getPendingNodes();

  const status = {
    taskBoard: {
      total: allNodes.length,
      pending: pendingNodes.length,
      active: allNodes.filter((n: TaskNode) => n.status === "claimed" || n.status === "running").length,
      done: allNodes.filter((n: TaskNode) => n.status === "done").length,
      failed: allNodes.filter((n: TaskNode) => n.status === "failed").length,
    },
  };

  if (pendingNodes.length === 0) {
    return {
      success: true,
      data: status,
      output: "璋冨害绯荤粺: 绌洪棽锛堟棤寰呭鐞嗕换鍔★級",
      exitCode: 0,
    };
  }

  return {
    success: true,
    data: status,
    output: [
      `璋冨害绯荤粺鐘舵€?`,
      `  浠诲姟鏉? ${status.taskBoard.total} 鎬讳换鍔,
      `    ${status.taskBoard.pending} 寰呭鐞哷,
      `    ${status.taskBoard.active} 鎵ц涓璥,
      `    ${status.taskBoard.done} 宸插畬鎴恅,
      `    ${status.taskBoard.failed} 澶辫触`,
    ].join("\n"),
    exitCode: 0,
  };
}

