/**
 * commands/skill.ts 鈥?`cortex skill` 鎶€鑳芥敞鍐岃〃鍛戒护
 *
 * 绠＄悊鎶€鑳斤紙缁撴瀯鍖栬鐭ワ級鐨勭敓鍛藉懆鏈燂細鏌ヨ銆佹敞鍐屻€佹敞閿€銆佺粺璁°€俓r
 * 鍩轰簬 @cortex/engine 鐨?SkillRegistry锛屾妧鑳藉嵆璁板繂锛岄潪鍙墽琛屽嚱鏁般€俓r
 *
 * @since v2.6 鈥?閫傞厤鎶€鑳界郴缁熼噸鏋勶細浠庡彲鎵ц鍑芥暟鍒扮粨鏋勫寲璁板繂
 * @moved-from projects/solo-flight/src/cli/
 */

import type { CommandHandler, CommandResult, CommandContext } from "../types.js";
import { SkillRegistry } from "@cortex/engine";
import type { SkillTemplate } from "@cortex/shared";

// 鈹€鈹€鈹€ 鎳掑姞杞藉崟渚?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

let _registryCache: SkillRegistry | null = null;

function getRegistry(): SkillRegistry {
  if (_registryCache) return _registryCache;
  const registry = new SkillRegistry();
  _registryCache = registry;
  return registry;
}

// 鈹€鈹€鈹€ 鍛戒护鍏ュ彛 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export function createSkillHandler(): CommandHandler {
  return async (args, options, context): Promise<CommandResult> => {
    if (args.length === 0 || args[0] === "--help" || args[0] === "-h") {
      return { success: true, output: HELP_TEXT, exitCode: 0 };
    }

    const subcommand = args[0];
    const subArgs = args.slice(1);

    try {
      const registry = await getRegistry();

      switch (subcommand) {
        case "list":
          return await handleList(registry, options, context);
        case "search":
          return await handleSearch(registry, subArgs, options, context);
        case "info":
          return await handleInfo(registry, subArgs, context);
        case "register":
          return await handleRegister(registry, subArgs, options, context);
        case "unregister":
          return await handleUnregister(registry, subArgs, options, context);
        case "stats":
          return await handleStats(registry, options, context);
        default:
          return {
            success: false,
            error: `鏈煡瀛愬懡浠? "${subcommand}"銆傚彲鐢? list, search, info, register, unregister, stats`,
            exitCode: 1,
          };
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      return { success: false, error: `鎶€鑳芥搷浣滃け璐? ${msg}`, exitCode: 2 };
    }
  };
}

const HELP_TEXT = [
  "鐢ㄦ硶: cortex skill <瀛愬懡浠? [閫夐」]",
  "",
  "瀛愬懡浠?",
  "  list                  鍒楀嚭鎵€鏈夊凡娉ㄥ唽鎶€鑳絓

\\n\");\r\n\r\n// 鈹€鈹€鈹€ list 鈹€鈹€鈹€鈹€鈹€:
"}`);
  }
  return { success: true, output: lines.join("\n"), exitCode: 0 };
}

// 鈹€鈹€鈹€ info 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

async function handleInfo(
  registry: SkillRegistry,
  args: string[],
  _context: CommandContext,
): Promise<CommandResult> {
  const skillId = args[0];
  if (!skillId) {
    return { success: false, error: "璇锋寚瀹氭妧鑳?ID銆傜敤娉? cortex skill info <id>", exitCode: 1 };
  }

  const tmpl = registry.get(skillId);
  if (!tmpl) {
    return { success: false, error: `鎶€鑳姐€?{skillId}銆嶆湭鍦ㄦ敞鍐岃〃涓壘鍒癭, exitCode: 1 };
  }

  const status = tmpl.status ?? "trial";
  const lines = [
    `鎶€鑳借鎯? ${tmpl.id}`,
    `  鍚嶇О:     ${tmpl.name}`,
    `  绉嶇被:     ${tmpl.kind}`,
    `  瑙﹀彂:     ${tmpl.trigger}`,
    `  鏍囩:     [${tmpl.triggerTags.join(", ")}]`,
    `  鏉冮噸:     ${tmpl.weight}`,
    `  鐘舵€?     ${status}`,
    `  浜у嚭鑰?   ${tmpl.discoveredBy}`,
    `  姝ラ鏁?   ${tmpl.steps.length}`,
    `  璇勪环鏁?   ${tmpl.feedbackHistory.length}`,
    `  鍒涘缓浜?   ${new Date(tmpl.createdAt).toISOString()}`,
  ];
  if (tmpl.expectedOutput) lines.push(`  棰勬湡浜у嚭: ${tmpl.expectedOutput}`);
  if (tmpl.outputFile) lines.push(`  杈撳嚭鏂囦欢: ${tmpl.outputFile}`);

  return { success: true, output: lines.join("\n"), exitCode: 0 };
}

// 鈹€鈹€鈹€ register 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

async function handleRegister(
  registry: SkillRegistry,
  _args: string[],
  options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  const id = options["id"] as string;
  const name = options["name"] as string;
  const trigger = options["trigger"] as string;
  const kind = (options["kind"] as string) ?? "action";
  const tagsStr = (options["tags"] as string) ?? "";

  if (!id || !name || !trigger) {
    return {
      success: false,
      error: "缂哄皯蹇呰鍙傛暟銆傜敤娉? cortex skill register --id <id> --name <name> --trigger <瑙﹀彂鏉′欢> [--kind action|thought|workflow] [--tags t1,t2]",
      exitCode: 1,
    };
  }

  // 绠€鍗?ID 鏍￠獙
  if (!/^[a-z][a-z0-9_-]{1,63}$/.test(id)) {
    return { success: false, error: `鏃犳晥鎶€鑳?ID銆?{id}銆嶃€傞渶灏忓啓瀛楁瘝寮€澶达紝2-64 瀛楃锛屽瓧姣?鏁板瓧/杩炲瓧绗?涓嬪垝绾縛, exitCode: 1 };
  }

  if (!["action", "thought", "workflow"].includes(kind)) {
    return { success: false, error: `鏃犳晥鎶€鑳界绫汇€?{kind}銆嶃€傚彲鐢? action, thought, workflow`, exitCode: 1 };
  }

  const tags = tagsStr ? tagsStr.split(",").map((t) => t.trim()).filter(Boolean) : [];

  const overwrite = !!options["overwrite"];
  if (!overwrite && registry.get(id)) {
    return { success: false, error: `鎶€鑳姐€?{id}銆嶅凡瀛樺湪銆備娇鐢?--overwrite 瑕嗙洊`, exitCode: 1 };
  }

  const template: SkillTemplate = {
    id,
    kind: kind as SkillTemplate["kind"],
    name,
    triggerTags: tags as SkillTemplate["triggerTags"],
    trigger,
    steps: (options["steps"] as string[] | undefined) ?? [],
    expectedOutput: (options["expected-output"] as string) ?? "",
    status: "trial",
    weight: 0,
    feedbackHistory: [],
    discoveredBy: (options["author"] as string) ?? "cli",
    createdAt: Date.now(),
  };

  registry.register(template);
  return { success: true, output: `鉁?鎶€鑳姐€?{id}銆嶆敞鍐屾垚鍔焋, exitCode: 0 };
}

// 鈹€鈹€鈹€ unregister 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

async function handleUnregister(
  registry: SkillRegistry,
  args: string[],
  options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  const skillId = args[0];
  if (!skillId) {
    return { success: false, error: "璇锋寚瀹氭妧鑳?ID銆傜敤娉? cortex skill unregister <id>", exitCode: 1 };
  }

  const force = !!options["force"];
  const exists = registry.get(skillId);
  if (!exists) {
    return { success: false, error: `鎶€鑳姐€?{skillId}銆嶆湭鍦ㄦ敞鍐岃〃涓壘鍒癭, exitCode: 1 };
  }

  if (!force) {
    // 妫€鏌ユ槸鍚︽湁鍏朵粬鎶€鑳戒緷璧栨鎶€鑳斤紙閫氳繃 trigger 鏂囨湰寮曠敤锛塡r
    const allSkills = registry.getAll();
    const dependents = allSkills.filter((s) => s.trigger.includes(skillId));
    if (dependents.length > 0) {
      return {
        success: false,
        error: `鎶€鑳姐€?{skillId}銆嶅彲鑳借寮曠敤: ${dependents.map((d) => d.id).join(", ")}銆備娇鐢?--force 寮哄埗娉ㄩ攢`,
        exitCode: 1,
      };
    }
  }

  const ok = registry.unregister(skillId);
  if (ok) {
    return { success: true, output: `鉁?鎶€鑳姐€?{skillId}銆嶅凡娉ㄩ攢`, exitCode: 0 };
  }
  return { success: false, error: `娉ㄩ攢澶辫触: 鎶€鑳姐€?{skillId}銆嶄笉瀛樺湪`, exitCode: 1 };
}

// 鈹€鈹€鈹€ execute 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
// 娉細v2.6 閲嶆瀯鍚庯紝鎶€鑳戒笉鍐嶆槸鍙墽琛屽嚱鏁帮紝鑰屾槸缁撴瀯鍖栬鐭ワ紙琚弬鐓ц€岄潪琚墽琛岋級銆俓r
// execute 瀛愬懡浠ゅ凡绉婚櫎銆傚闇€鎵ц Agent锛岃浣跨敤 cortex run銆俓r

// 鈹€鈹€鈹€ stats 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

async function handleStats(
  registry: SkillRegistry,
  options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  const allSkills = registry.getAll();
  const byKind: Record<string, number> = {};
  const byTag: Record<string, number> = {};
  const byStatus: Record<string, number> = {};

  for (const s of allSkills) {
    byKind[s.kind] = (byKind[s.kind] ?? 0) + 1;
    byStatus[s.status] = (byStatus[s.status] ?? 0) + 1;
    for (const t of s.triggerTags) {
      byTag[t] = (byTag[t] ?? 0) + 1;
    }
  }

  const format = (options["format"] as string) ?? "text";
  if (format === "json") {
    return {
      success: true,
      data: { total: allSkills.length, byKind, byStatus, byTag },
      output: JSON.stringify({ total: allSkills.length, byKind, byStatus, byTag }, null, 2),
      exitCode: 0,
    };
  }

  const lines = [
    `鎶€鑳芥敞鍐岃〃缁熻:`,
    `  鎬绘暟: ${allSkills.length}`,
    `  娲昏穬: ${byStatus["active"] ?? 0}`,
    `  璇曠敤: ${byStatus["trial"] ?? 0}`,
    `  寮冪敤: ${byStatus["deprecated"] ?? 0}`,
    ``,
    `  鎸夌绫?`,
  ];
  for (const [kind, count] of Object.entries(byKind)) {
    lines.push(`    ${kind.padEnd(14)} ${count}`);
  }
  lines.push(``, `  鐑棬鏍囩:`);
  const topTags = Object.entries(byTag).sort((a, b) => b[1] - a[1]).slice(0, 10);
  for (const [tag, count] of topTags) {
    lines.push(`    ${tag.padEnd(14)} ${count}`);
  }

  return { success: true, output: lines.join("\n"), exitCode: 0 };
}

