import type { CommandHandler, CommandResult, CommandContext } from "../types.js";
import { DEFAULT_TASK_TIMEOUT_SEC } from "@cortex/config";
import { type ICortexApi, type TaskNode, type Tag } from "@cortex/shared";
import type { ITaskBoard, IScheduler } from "@cortex/engine";
import * as fs from "node:fs";
import * as path from "node:path";

export function createTaskHandler(bridge: ICortexApi): CommandHandler {
  return async (args, options, context): Promise<CommandResult> => {
    if (args.length === 0 || args[0] === "--help" || args[0] === "-h") {
      return {
        success: true,
        output: [
          "鐢ㄦ硶: cortex task <瀛愬懡浠? [閫夐」]",
          "",
          "瀛愬懡浠?",
          "  submit <file>        鎻愪氦浠诲姟鏂囦欢",
          "  list                 鍒楀嚭浠诲姟闃熷垪",
          "  status <id>          鏌ヨ浠诲姟鐘舵€乗

  --force, -f          寮哄埗鍙栨秷",
          "  --strategy <s>       閲嶈瘯绛栫暐",
        ].join("\n"),
        exitCode: 0,
      };
    }

    const subcommand = args[0];

    try {
      const board = await bridge.getTaskBoard() as ITaskBoard;
      const scheduler = await bridge.getScheduler() as IScheduler;

      switch (subcommand) {
        case "submit":
          return await handleTaskSubmit(board, scheduler, args[1], options, context);
        case "list":
          return await handleTaskList(board, options, context);
        case "status":
          return await handleTaskStatus(board, args[1], options, context);
        case "cancel":
          return await handleTaskCancel(board, args[1], options, context);
        case "redo":
          return await handleTaskRedo(board, scheduler, args[1], options, context);
        default:
          return {
            success: false,
            error: `鏈煡瀛愬懡浠? "${subcommand}"銆傚彲鐢ㄥ瓙鍛戒护: submit, list, status, cancel, redo`,
            exitCode: 1,
          };
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      return { success: false, error: `浠诲姟鎿嶄綔澶辫触: ${msg}`, exitCode: 2 };
    }
  };
}

async function handleTaskSubmit(
  board: ITaskBoard,
  scheduler: IScheduler,
  filePath: string | undefined,
  options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  if (!filePath) {
    return { success: false, error: "璇锋寚瀹氫换鍔℃枃浠躲€傜敤娉? cortex task submit <file>", exitCode: 1 };
  }

  let content: string;
  try {
    content = fs.readFileSync(path.resolve(filePath), "utf-8");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return { success: false, error: `璇诲彇鏂囦欢澶辫触: ${msg}`, exitCode: 1 };
  }

  const agentType = (options["agent"] ?? options["a"]) as string | undefined;
  const priority = (options["priority"] ?? "P2") as string;
  const label = options["label"] as string | undefined;
  const wait = options["wait"] || options["w"];
  const _timeout = parseInt(String(options["timeout"] ?? String(DEFAULT_TASK_TIMEOUT_SEC)), 10);

  const taskNode: TaskNode = {
    id: `task-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    type: agentType ?? "analysis",
    tags: (label ? [label] : agentType ? [agentType] : ["analysis"]) as Tag[],
    needsMultiPerspective: false,
    status: "pending",
    claimedBy: [],
    payload: content,
    results: [],
    createdAt: Date.now(),
  };

  board.addNode(taskNode);

  if (wait) {
    const report = await scheduler.executeAll();
    const taskResult = report.results.find((r: { nodeId: string }) => r.nodeId === taskNode.id);
    return {
      success: report.completed > 0,
      output: taskResult?.output ?? `瀹屾垚: ${report.completed}/${report.totalNodes}`,
      data: { taskId: taskNode.id, report },
      exitCode: report.completed > 0 ? 0 : 2,
    };
  }

  return {
    success: true,
    output: `鉁?浠诲姟宸叉彁浜? ${taskNode.id}`,
    data: { taskId: taskNode.id, priority, agentType },
    exitCode: 0,
  };
}

async function handleTaskList(
  board: ITaskBoard,
  options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  const statusFilter = options["status"] as string | undefined;
  const limit = parseInt(String(options["limit"] ?? "20"), 10);

  const allNodes = board.getAllNodes();
  let nodes = allNodes;

  if (statusFilter) {
    nodes = nodes.filter((n: TaskNode) => n.status === statusFilter);
  }

  nodes = nodes.slice(0, limit);

  const summaries = nodes.map((n: TaskNode) => ({
    id: n.id,
    type: n.type,
    status: n.status,
    createdAt: new Date(n.createdAt).toISOString(),
    results: n.results.length,
  }));

  return {
    success: true,
    data: { total: allNodes.length, filtered: nodes.length, tasks: summaries },
    output: `浠诲姟鍒楄〃: ${nodes.length}/${allNodes.length} 涓换鍔,
    exitCode: 0,
  };
}

async function handleTaskStatus(
  board: ITaskBoard,
  taskId: string | undefined,
  options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  if (!taskId) {
    return { success: false, error: "璇锋寚瀹氫换鍔?ID銆傜敤娉? cortex task status <id>", exitCode: 1 };
  }

  const node = board.getNode(taskId);
  if (!node) {
    return { success: false, error: `浠诲姟涓嶅瓨鍦? ${taskId}`, exitCode: 1 };
  }

  const verbose = options["verbose"] || options["v"];

  return {
    success: true,
    data: {
      id: node.id,
      type: node.type,
      status: node.status,
      tags: node.tags,
      claimedBy: node.claimedBy,
      results: node.results,
      createdAt: new Date(node.createdAt).toISOString(),
    },
    output: [
      `浠诲姟 ID:    ${node.id}`,
      `鐘舵€?       ${node.status}`,
      `绫诲瀷:       ${node.type}`,
      `鏍囩:       ${node.tags.join(", ")}`,
      `璁ら鑰?     ${node.claimedBy.join(", ") || "(鏃?"}`,
      `鍒涘缓鏃堕棿:   ${new Date(node.createdAt).toISOString()}`,
      ...(verbose ? [`缁撴灉鏁?     ${node.results.length}`] : []),
    ].join("\n"),
    exitCode: 0,
  };
}

async function handleTaskCancel(
  board: ITaskBoard,
  taskId: string | undefined,
  _options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  if (!taskId) {
    return { success: false, error: "璇锋寚瀹氫换鍔?ID銆傜敤娉? cortex task cancel <id>", exitCode: 1 };
  }

  const ok = board.failNode(taskId);
  if (!ok) {
    return { success: false, error: `鍙栨秷澶辫触: 浠诲姟 ${taskId} 涓嶅瓨鍦ㄦ垨宸茬粓鎬乣, exitCode: 1 };
  }

  return {
    success: true,
    output: `鉁?浠诲姟宸插彇娑? ${taskId}`,
    data: { taskId },
    exitCode: 0,
  };
}

async function handleTaskRedo(
  board: ITaskBoard,
  scheduler: IScheduler,
  taskId: string | undefined,
  _options: Record<string, unknown>,
  _context: CommandContext,
): Promise<CommandResult> {
  if (!taskId) {
    return { success: false, error: "璇锋寚瀹氫换鍔?ID銆傜敤娉? cortex task redo <id>", exitCode: 1 };
  }

  const node = board.getNode(taskId);
  if (!node) {
    return { success: false, error: `浠诲姟涓嶅瓨鍦? ${taskId}`, exitCode: 1 };
  }

  // 閲婃斁璁ら锛屼娇鑺傜偣鍥炲埌 pending 鐘舵€乗n  if (node.claimedBy.length > 0) {
    for (const agentType of node.claimedBy) {
      board.release(taskId, agentType);
    }
  }

  // 閲嶆柊璋冨害
  const report = await scheduler.executeAll();
  const redoResult = report.results.find((r: { nodeId: string }) => r.nodeId === taskId);

  return {
    success: report.completed > 0,
    output: redoResult?.output ?? `閲嶈窇瀹屾垚: ${report.completed}/${report.totalNodes}`,
    data: { taskId, report },
    exitCode: report.completed > 0 ? 0 : 2,
  };
}

/**
 * commands/version.ts 鈥?`cortex version` 鐗堟湰淇℃伅鍛戒护
 *
