/**
 * EngineBridge 鈥?寮曟搸缁勪欢鐢熷懡鍛ㄦ湡绠＄悊鍣ㄣ€俓r
 *
 * 鏀寔涓ょ鍒濆鍖栨ā寮忥細
 * 1. 杞婚噺妯″紡锛坋nsureInitialized锛夆€斺€?浣跨敤 MiniAgentPool锛屾棤 Agent 娉ㄥ唽
 * 2. 閰嶇疆椹卞姩妯″紡锛坋nsureBootstrapped锛夆€斺€?浣跨敤 bootstrapEngine锛孿r
 *    浠?cortex-agents.json 鍔犺浇鎵€鏈?Agent 瀹氫箟骞舵敞鍐孿r
 */
export class EngineBridge implements ICortexApi {
  private ctx: BridgeContext = { initialized: false };
  private _pool: MiniAgentPool = new MiniAgentPool();
  private config: ConfigManager;
  private dbPath?: string;
  private engineConfig?: EngineConfig;
  private _bootstrapConfig?: BootstrapConfig;

  constructor(config: ConfigManager, dbPath?: string, engineConfig?: EngineConfig) {
    this.config = config;
    this.dbPath = dbPath;
    this.engineConfig = engineConfig;
  }

  /**
   * 璁剧疆 Bootstrap 閰嶇疆鈥斺€斿惎鐢ㄩ厤缃┍鍔ㄦā寮忋€俓r
   * 蹇呴』鍦?ensureBootstrapped() 涔嬪墠璋冪敤銆俓r
   */
  setBootstrapConfig(bootstrapConfig: BootstrapConfig): void {
    this._bootstrapConfig = bootstrapConfig;
  }

  /**
   * 閰嶇疆椹卞姩鍒濆鍖栤€斺€斾娇鐢?bootstrapEngine 鍔犺浇 cortex-agents.json
   * 绛夐厤缃枃浠讹紝鍒涘缓鎵€鏈?Agent 骞舵敞鍐屽埌 Scheduler銆俓r
   *
   * 姝ゆ柟娉曞畬鍏ㄦ浛浠ｇ‖缂栫爜 Agent 鍒涘缓娴佺▼銆俓r
   * 蹇呴』鍏堣皟鐢?setBootstrapConfig() 璁剧疆 LlmAdapter 绛夊弬鏁般€俓r
   */
  async ensureBootstrapped(): Promise<void> {
    await this._ensureBootstrapped();
  }

  /**
   * 浠ユ柊鐨勫伐浣滃尯鏍硅矾寰勯噸鏂板紩瀵煎紩鎿庛€俓r
   * 鐢ㄤ簬鐢ㄦ埛鍦?intent 涓寚瀹氫簡涓嶅悓鐨勫伐浣滃尯璺緞锛堝 "灏嗚繖涓矾寰勪綔涓哄伐浣滃尯 D:\\Projects\\xxx"锛夈€俓r
   * 鍙湁 workspaceRoot 涓庡綋鍓嶄笉鍚屾椂鎵嶈Е鍙戝疄闄呴噸寮曞銆俓r
   */
  async rebootstrapIfNeeded(workspaceRoot: string): Promise<void> {
    if (!this._bootstrapConfig) {
      throw new Error("[EngineBridge] rebootstrap() 闇€瑕佸厛璋冪敤 setBootstrapConfig()");
    }
    const current = path.resolve(this._bootstrapConfig.workspaceRoot ?? this._bootstrapConfig.projectRoot);
    const target = path.resolve(workspaceRoot);
    if (current === target) return;
    this.ctx.bootstrapped = false;
    this._bootstrapConfig.workspaceRoot = target;
    await this._ensureBootstrapped();
  }

  /** 鍏煎鏃ц皟鐢ㄦ柟鈥斺€旇繑鍥?BridgeContext 鐨勫叿浣撳疄鐜?*/
  private async _ensureBootstrapped(): Promise<BridgeContext> {
    if (this.ctx.bootstrapped) return this.ctx;

    if (!this._bootstrapConfig) {
      throw new Error(
        "[EngineBridge] ensureBootstrapped() 闇€瑕佸厛璋冪敤 setBootstrapConfig() 璁剧疆 LlmAdapter/Toolkit",
      );
    }

    const { llms, toolkit, projectRoot, dbPath, engineConfig, workspaceRoot } =
      this._bootstrapConfig;

    const result = await bootstrapEngine(projectRoot, {
      llms,
      toolkit,
      dbPath: dbPath ?? this.dbPath,
      engineConfig: engineConfig ?? this.engineConfig,
      workspaceRoot: workspaceRoot ?? projectRoot,
    });

    this.ctx = {
      scheduler: result.scheduler,
      memoryStore: result.memory,
      taskBoard: result.board,
      pipelineObserver: result.observer,
      confirmGate: result.gate,
      cliAdapter: result.cliAdapter,
      initialized: true,
      bootstrapped: true,
      bootstrapResult: result,
    };

    return this.ctx;
  }

  /**
   * 鑾峰彇 Bootstrap 涓婁笅鏂囷紙EngineBridge 涓撴湁锛屼笉鍦?ICortexApi 濂戠害涓級銆俓r
   * 渚?roundtable / agent / task 绛夊懡浠ゅ伐鍘傚湪闇€瑕佽闂?bootstrapResult 鏃朵娇鐢ㄣ€俓r
   */
  async ensureBootstrappedContext(): Promise<BridgeContext> {
    return await this._ensureBootstrapped();
  }

  /** 鍒濆鍖栧叏閮ㄥ紩鎿庣粍浠讹紙杞婚噺妯″紡锛屾儼鎬э紝浠呴娆¤皟鐢ㄦ椂鍒涘缓锛?*/
  async ensureInitialized(): Promise<BridgeContext> {
    if (this.ctx.initialized) return this.ctx;

    // 1. PipelineObserver
    const observer = new PipelineObserver();

    // 2. CLIAdapter
    const cliAdapter = new CLIAdapter();

    // 3. ConfirmGate锛堣交閲忔ā寮忥細涓嶈繛鎺ヤ氦浜掓ˉ锛屾棤 bridge 鏃惰嚜鍔ㄦ斁琛?L2/L3 纭锛塡r
    const gate = new ConfirmGate();
    // gate.setBridge(cliAdapter); 鈥?杞婚噺妯″紡涓嶈繛鎺?CLIAdapter锛孿r
    // 閬垮厤鍦ㄩ潪 TTY/鑷姩鍖栧満鏅笅闃诲 stdin銆備氦浜掔‘璁や粎鍦?bootstrap 妯″紡鏈夋晥銆俓r

    // 4. TaskBoard
    const board = new TaskBoard();
    board.setObserver(observer);

    // 5. MemoryStore
    const memory = new MemoryStore(undefined, observer);
    if (this.dbPath) {
      await memory.init(this.dbPath);
    }

    // 6. Scheduler锛堜娇鐢?MiniAgentPool锛塡r
    // 娉ㄦ剰锛歋cheduler 鏋勯€犻渶瑕?AgentPool 瀹炰緥銆傚湪鍘熷瀷闃舵锛孿r
    // MiniAgentPool 婊¤冻鎺ュ彛瑕佹眰銆俓r
    // 閰嶇疆椹卞姩妯″紡璇蜂娇鐢?ensureBootstrapped()锛屽畠浼氱敤鐪熷疄 AgentPool
    // 骞朵粠 cortex-agents.json 鍔犺浇鎵€鏈?Agent銆俓r
    const scheduler = new Scheduler(board, this._pool, observer, undefined, this.engineConfig);

    this.ctx = {
      scheduler,
      memoryStore: memory,
      taskBoard: board,
      pipelineObserver: observer,
      confirmGate: gate,
      cliAdapter,
      initialized: true,
    };

    return this.ctx;
  }

  /** 鏄惁宸插垵濮嬪寲锛圛CortexApi.ready锛?*/
  get ready(): boolean {
    return this.ctx.initialized;
  }

  /** 鏄惁宸?Bootstrap锛圛CortexApi.bootstrapped锛?*/
  get bootstrapped(): boolean {
    return this.ctx.bootstrapped ?? false;
  }

  /** 纭繚寮曟搸灏辩华锛堣交閲忔ā寮忥紝ICortexApi锛?*/
  async ensureReady(): Promise<void> {
    await this.ensureInitialized();
  }

  /**
   * 缁熶竴瀵硅瘽鎺ュ彛锛圛CortexApi.chat锛夈€俓r
   * 绛変环浜?directChat鈥斺€斾笉缁忚皟搴﹀櫒锛岀洿杩?LLM銆俓r
   */
  async chat(systemPrompt: string, messages: LlmMessage[], opts?: ChatOptions): Promise<string> {
    return await this.directChat(systemPrompt, messages, opts);
  }

  /** 鑾峰彇闂茶亰妯″瀷鍚嶏紙ICortexApi锛?*/
  getChatModelName(): string {
    return this.llm?.chatModel ?? "";
  }

  /** 鑾峰彇鎺ㄧ悊妯″瀷鍚嶏紙ICortexApi锛?*/
  getReasonerModelName(): string {
    return this.llm?.reasonerModel ?? "";
  }

  /**
   * 鎵ц宸ュ叿璋冪敤鈥斺€擳UI 灞傞€氳繃姝ゆ柟娉曞皢 LLM 浜у嚭鐨?tool_call 杞彂鍒板紩鎿?Toolkit銆俓r
   *
   * 榛樿浠?"code" Agent 韬唤璋冪敤锛圱UI chat 妯″紡鐨勫伐鍏疯皟鐢ㄦ潈闄愪笌 CodeAgent 涓€鑷达級銆俓r
   */
  async executeToolCall(name: string, args: Record<string, unknown>): Promise<{ success: boolean; output: string }> {
    const toolkit = this._bootstrapConfig?.toolkit;
    if (!toolkit) {
      return { success: false, output: "Toolkit 鏈垵濮嬪寲鈥斺€旇閫氳繃 setBootstrapConfig() 娉ㄥ叆 Toolkit" };
