    return { success: result.success, output: result.success ? (result.output ?? "") : (result.error ?? "鏈煡閿欒") };
  }

  /**
   * 娴佸紡 LLM 瀵硅瘽鈥斺€斾緵 TUI queryLoop 浣跨敤銆俓r
   *
   * 閫氳繃 LlmAdapter.chatStream() 瀹炵幇鐪熸鐨?SSE 娴佸紡鍥炶皟锛孿r
   * 姣忎釜 token chunk 鍗虫椂鎺ㄩ€佺粰 TUI 娓叉煋灞傘€俓r
   *
   * @param model 妯″瀷鍚峔r
   * @param messages 瀹屾暣娑堟伅鍒楄〃锛堝惈 system锛塡r
   * @param tools 宸ュ叿瀹氫箟锛堝彲閫夛紝鐢ㄤ簬 function calling锛塡r
   * @param onChunk 姣忔鏀跺埌鏂囨湰 chunk 鏃跺洖璋僜r
   * @param opts 鎺ㄧ悊閫夐」
   * @returns LLM 瀹屾暣鍝嶅簲
   */
  async streamChat(
    model: string,
    messages: LlmMessage[],
    tools: { name: string; description: string; parameters?: Record<string, unknown> }[] | undefined,
    onChunk: (content: string, reasoning?: string) => void,
