   * 鍙戝皠 node_complete/node_failed 浜嬩欢銆俓r
   *
   * @param nodes 瑕佹墽琛岀殑浠诲姟鑺傜偣鍒楄〃
   * @param onEvent 浜嬩欢鍥炶皟鈥斺€斿紩鎿庢瘡瀹屾垚涓€涓妭鐐瑰氨璋冪敤涓€娆r
   * @returns 瀹屾暣鎵ц鎶ュ憡
   */
  async executeWithStream(
    nodes: TaskNode[],
    onEvent: (event: TuiEvent) => void,
  ): Promise<ExecutionReport> {
    const ctx = await (this.ctx.bootstrapped ? this._ensureBootstrapped() : this.ensureInitialized());
    const board = ctx.taskBoard;
    const scheduler = ctx.scheduler;

    if (!board || !scheduler) {
      throw new Error("[EngineBridge] executeWithStream 闇€瑕佸垵濮嬪寲鐨?taskBoard 鍜?scheduler");
    }

    // 1. 鍙戝皠浠诲姟鏍戞洿鏂颁簨浠禱r
    onEvent({ type: "task_tree_update", nodes });

    // 2. 鎻愪氦鎵€鏈夎妭鐐筡r
    for (const node of nodes) {
      board.addNode(node as unknown as TaskNode);
      onEvent({
        type: "node_start",
        nodeId: node.id,
        nodeType: node.type,
        agent: (node.claimedBy?.[0] ?? "code") as AgentType,
        description: node.payload,
        parentId: node.parentId,
      });
    }

    // 3. 鎵ц鍏ㄩ儴
    const _startMs = Date.now();
    const report = await scheduler.executeAll();

    // 4. 鍙戝皠鍚勮妭鐐瑰畬鎴?澶辫触浜嬩欢
    for (const result of report.results) {
      const durationMs = report.durationMs;
      if (result.success) {
        onEvent({
          type: "node_complete",
          nodeId: result.nodeId,
          agent: result.agentType ?? ("code" as AgentType),
          output: result.output ?? "",
          durationMs,
        });
      } else {
        onEvent({
          type: "node_failed",
          nodeId: result.nodeId,
          agent: result.agentType ?? ("code" as AgentType),
          error: result.error ?? "鏈煡閿欒",
          durationMs,
        });
      }
    }

    return report;
  }

