  private get llm(): LlmAdapter | undefined {
    const map = this._bootstrapConfig?.llms;
    if (!map || map.size === 0) return undefined;
    // 浼樺厛鍙栨様娑熼€傞厤鍣紙talk 妯″紡涓昏浣跨敤鑰咃級
