      // Plan 妯″紡锛氱敓鎴愯鍒掕妭鐐瑰悗鍙戝皠 task_tree_update
      return "allow";
    },
    onNodeComplete: (_event) => {
      // 鑺傜偣瀹屾垚鍚庢洿鏂拌鍒掔姸鎬乗r
    },
    onNodeFailed: (_event) => {
      // 鑺傜偣澶辫触璁板綍
    },
  };

  // 濡傛灉宸叉湁鎵瑰噯鐨勮鍒掞紝鎵ц
  if (planState.approved && planState.nodes.length > 0) {
    // 鏀堕泦鎵ц浜嬩欢鈥斺€攅xecuteWithStream 閫氳繃鍥炶皟鎺ㄩ€侊紝planMode 鏄?async generator
    // 闇€妗ユ帴锛氬厛鏀堕泦鍏ㄩ儴浜嬩欢锛屽啀閫愭潯 yield
    const collectedEvents: TuiEvent[] = [];
    const report = await bridge.executeWithStream(planState.nodes, (event) => {
      collectedEvents.push(event);
    });

    // 閫愭潯鍙戝皠鏀堕泦鐨勪簨浠禱r
    for (const event of collectedEvents) {
      yield event;
    }

    if (report.failed > 0) {
      return `璁″垝鎵ц瀹屾垚锛?{report.completed}/${report.totalNodes} 鎴愬姛锛?{report.failed} 澶辫触`;
    }
    return "璁″垝鎵ц瀹屾垚";
  }

  // 鍚﹀垯锛氱敓鎴愯鍒抃r
  return yield* queryLoop(input, bridge, "plan", agent, hooks, history);
}

