export function formatPlanTree(nodes: TaskNode[]): string {
  const childrenMap = new Map<string, TaskNode[]>();
  const roots: TaskNode[] = [];

  for (const node of nodes) {
    if (!node.parentId) {
      roots.push(node);
    } else {
      const list = childrenMap.get(node.parentId) ?? [];
      list.push(node);
      childrenMap.set(node.parentId, list);
    }
  }

  const lines: string[] = [];
  const icon = (node: TaskNode): string => {
    if (node.needsMultiPerspective) return "馃攢";
    const t = node.type.toLowerCase();
    if (t === "code" || t === "implementation") return "馃敤";
    if (t === "review") return "馃攳";
    if (t === "analysis" || t === "research") return "馃";
    if (t === "fix" || t === "bugfix") return "馃拪";
    if (t === "inspect" || t === "inspector") return "馃敪";
    if (t === "ops" || t === "deploy") return "鈿揬

doc-govern" || t === "audit") return "馃摐";
    if (t === "browser") return "馃巻";
    if (t === "loop" || t === "pattern_scan") return "馃敭";
    return "馃搶";
  };

  const render = (node: TaskNode, depth: number, isLast: boolean, prefix: string) => {
    const connector = depth === 0 ? "" : isLast ? "  鈹斺攢 " : "  鈹溾攢 ";
    const typeLabel = node.type ? `[${node.type}]` : "";
    const tagStr = node.tags?.length ? ` {${node.tags.join(", ")}}` : "";
    const multiStr = node.needsMultiPerspective ? " [澶氳瑙抅" : "";
    lines.push(`${prefix}${connector}${icon(node)} ${typeLabel} ${node.payload}${tagStr}${multiStr}`);

    const children = childrenMap.get(node.id);
    if (children && children.length > 0) {
      for (let i = 0; i < children.length; i++) {
        const childPrefix = depth === 0 ? "" : isLast ? "    " : "  鈹?";
        render(children[i], depth + 1, i === children.length - 1, prefix + childPrefix);
      }
    }
  };

  lines.push("鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺怽

");
  }

  return lines.join("\n");
}

