 *
 * @param input 鐢ㄦ埛杈撳叆
 * @param bridge 寮曟搸妗ユ帴锛圠lmStreamBridge + ICortexApi锛塡r
 * @param mode 褰撳墠妯″紡
 * @param agent 褰撳墠 Agent
 * @param hooks 鐢熷懡鍛ㄦ湡閽╁瓙
 * @param history 瀵硅瘽鍘嗗彶锛堝杞級
 * @yields TuiEvent 鎵ц浜嬩欢
 * @returns 鏈€缁堣緭鍑烘枃鏈琝r
 */
export async function* queryLoop(
  input: string,
  bridge: LlmStreamBridge & Pick<ICortexApi, "chat" | "submitTask" | "executeAll">,
  mode: ReplMode,
  agent: AgentType,
  hooks: TuiHooks,
  history?: LlmMessage[],
): AsyncGenerator<TuiEvent, string, void> {
  const systemPrompt = assembleSystemPrompt(mode, agent);
  const messages: LlmMessage[] = [];

  // 娉ㄥ叆 system prompt
