  while (toolRound < MAX_TOOL_ROUNDS) {
    // 璋冪敤 LLM锛堟祦寮忥級鈥斺€旀敹闆?chunk 鍚庣粺涓€ yield
    const chunks: { content: string; reasoning?: string }[] = [];
    const resp = await bridge.streamChat(
      chatModel,
      messages,
      undefined, // tools 鈥?鍚庣画鍙敞鍏?Toolkit 鐨勫伐鍏峰畾涔塡r
      (content, reasoning) => {
        chunks.push({ content, reasoning });
      },
    );

    // 鍙戝皠鏀堕泦鐨?LLM chunk 浜嬩欢
    for (const chunk of chunks) {
      const chunkEvent: TuiEvent = {
        type: "llm_chunk",
        agent,
        content: chunk.content,
        reasoning: chunk.reasoning,
      };
      yield chunkEvent;

      // hook: onChunk
      hooks.onChunk?.(chunkEvent as TuiEvent & { type: "llm_chunk" });
    }

    // Token 鐢ㄩ噺
    if (resp.usage) {
      yield {
        type: "token_usage",
        promptTokens: resp.usage.prompt_tokens,
        completionTokens: resp.usage.completion_tokens,
        sessionTotalTokens: resp.usage.prompt_tokens + resp.usage.completion_tokens,
        contextWindowSize: 128000,
      };
    }

    // 妫€鏌?tool_calls
    if (resp.tool_calls && resp.tool_calls.length > 0) {
      toolRound++;

      for (const tc of resp.tool_calls) {
        // hook: onPreToolUse
        let permission: "allow" | "deny" | "skip" = "allow";
        if (hooks.onPreToolUse) {
          permission = await hooks.onPreToolUse({
            type: "tool_start",
            agent,
            tool: tc.name,
            input: JSON.stringify(tc.arguments),
          });
        }

        if (permission === "deny") continue;
        if (permission === "skip") {
          messages.push({
            role: "assistant",
            content: "",
            tool_calls: [tc],
          });
          messages.push({
            role: "tool",
            content: "[skipped by user]",
            tool_call_id: tc.id,
          });
          continue;
        }

        // 鍙戝皠 tool_start 浜嬩欢
        yield {
          type: "tool_start",
          agent,
          tool: tc.name,
          input: JSON.stringify(tc.arguments),
        };

        // 瀹為檯鎵ц宸ュ叿鈥斺€旈€氳繃 bridge.executeToolCall 杞彂鍒板紩鎿?Toolkit
        const startMs = Date.now();
        let toolResult: string;
        let toolSuccess: boolean;
        try {
          const execResult = await bridge.executeToolCall(tc.name, tc.arguments);
          toolResult = execResult.output;
          toolSuccess = execResult.success;
        } catch (e) {
          toolResult = `宸ュ叿鎵ц寮傚父: ${e instanceof Error ? e.message : String(e)}`;
          toolSuccess = false;
        }
        const durationMs = Date.now() - startMs;

        // 鍙戝皠 tool_result 浜嬩欢
        yield {
          type: "tool_result",
          agent,
          tool: tc.name,
          success: toolSuccess,
          output: toolResult,
          durationMs,
        };

        // 灏嗗伐鍏疯皟鐢ㄥ拰缁撴灉鍔犲叆娑堟伅鍘嗗彶
        messages.push({
          role: "assistant",
          content: "",
          tool_calls: [tc],
        });
        messages.push({
          role: "tool",
          content: toolResult,
          tool_call_id: tc.id,
        });

        // hook: onPostToolUse
        await hooks.onPostToolUse?.({
          type: "tool_result",
          agent,
          tool: tc.name,
          success: toolSuccess,
          output: toolResult,
          durationMs,
        });
      }

      // 缁х画寰幆鈥斺€擫LM 澶勭悊宸ュ叿缁撴灉
      continue;
    }

    // 鏃?tool_calls 鈫?鏈€缁堣緭鍑篭r
    finalOutput = resp.content ?? "";
    break;
  }

  if (toolRound >= MAX_TOOL_ROUNDS) {
    finalOutput = "[宸茶揪鍒版渶澶у伐鍏疯皟鐢ㄨ疆娆★紝鍋滄]";
  }

  // 灏嗗姪鎵嬪洖澶嶅姞鍏ュ巻鍙瞈r
  if (finalOutput) {
    messages.push({ role: "assistant", content: finalOutput });
  }

  return finalOutput;
}

// 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺怽r
// 搂3 杈呭姪鍑芥暟
// 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺怽r

/**
 * 浠?queryLoop 鐨?messages 涓彁鍙栧璇濆巻鍙诧紙涓嶅惈 system prompt锛夈€俓r
 * 鐢ㄤ簬澶氳疆瀵硅瘽涓婁笅鏂囩殑淇濈暀銆俓r
 */
export function extractHistory(messages: LlmMessage[]): LlmMessage[] {
  return messages.filter((m) => m.role !== "system");
}

