}

export class ToolLogRenderer {
  private pending: Map<string, PendingCall> = new Map();
  private callSeq: number = 0;

  /** 澶勭悊浜嬩欢 */
  handleEvent(event: TuiEvent): void {
    switch (event.type) {
      case "tool_start":
        this.onToolStart(event.tool, event.input, event.nodeId);
        break;
      case "tool_result":
