    const timeStr = duration !== undefined ? `(${duration}ms)` : "";
    const statusIcon = success
      ? style("鉁揬

"), StyleCode.dim)
      : style(truncate(error ?? "鏈煡閿欒"), ColorCode.red);

    writeln(
      `  ${statusIcon} ${style(timeStr, StyleCode.dim)} ${detail}`,
    );
