 *
 * 褰撳墠闃舵閫氳繃 `cortex --tui` 鍚敤銆俓r
 */
export async function tuiReplHandler(
  registry: CommandRegistry,
  bridge: EngineBridge,
  context: CommandContext,
): Promise<number> {
  // 鈹€鈹€ 娓叉煋鍣ㄥ垵濮嬪寲 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  const taskTree = new TaskTreeRenderer();
  const toolLog = new ToolLogRenderer();
  const tokenMonitor = new TokenMonitor();
  const _confirmGate = new ConfirmGateState();

  // 鈹€鈹€ 鐘舵€?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
