  const history: LlmMessage[] = [];

  // 鈹€鈹€ 鎭㈠鎸佷箙鍖栫殑 Plan 鐘舵€?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
