  };

  // 鈹€鈹€ 璁㈤槄浜嬩欢鎬荤嚎 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  tuiEventBus.on("task_tree_update", (e) => taskTree.handleEvent(e));
  tuiEventBus.on("node_start", (e) => taskTree.handleEvent(e));
  tuiEventBus.on("node_complete", (e) => taskTree.handleEvent(e));
  tuiEventBus.on("node_failed", (e) => taskTree.handleEvent(e));
  tuiEventBus.on("tool_start", (e) => toolLog.handleEvent(e));
  tuiEventBus.on("tool_result", (e) => toolLog.handleEvent(e));
  tuiEventBus.on("token_usage", (e) => tokenMonitor.handleEvent(e));

  // 鈹€鈹€ 娓叉煋鍒濆澶?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  renderPersonaHeader(agent, mode);

  // 鈹€鈹€ 娆㈣繋淇℃伅 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  writeln(`  ${bold("Cortex TUI v3")} 鈥?${dim("鏂版灦鏋勯瑙圽

");

  // 鈹€鈹€ 涓诲惊鐜?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  let running = true;

  // 浣跨敤 readline 鍏煎寮傛
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    prompt: buildPrompt(mode, agent),
  });

  rl.prompt();

  rl.on("line", async (line: string) => {
    const input = line.trim();
    if (!input) {
      rl.prompt();
      return;
    }

    // 鍐呴儴鍛戒护澶勭悊
    if (input.startsWith(".")) {
      running = await handleInternalCommand(input, rl, (m) => { mode = m; }, (a) => { agent = a; }, () => {}, context.projectRoot ?? process.cwd());
      if (!running) return;
      rl.prompt();
      return;
    }

    // 妯″紡鍒嗗彂
    try {
      switch (mode) {
        case "command": {
          const result = await commandMode(
            (args) => registry.dispatch(args, context),
            input.split(/\s+/),
          );
          writeln(result);
          break;
        }
        case "chat": {
          const gen = chatMode(input, bridge, agent, history);
          const result = await consumeGenerator(gen, tuiEventBus);
          if (result) {
            history.push({ role: "user", content: input });
            history.push({ role: "assistant", content: result });
            writeln(result);
          }
          break;
        }
        case "talk": {
          const gen = talkMode(input, bridge, history);
          const result = await consumeGenerator(gen, tuiEventBus);
          if (result) {
            history.push({ role: "user", content: input });
            history.push({ role: "assistant", content: result });
            writeln(result);
          }
          break;
        }
        case "plan": {
          planState = {
            nodes: [],
            intent: input,
            approved: false,
            reviewStatus: "pending",
          };
          const gen = planMode(input, bridge, agent, planState, history);
          const result = await consumeGenerator(gen, tuiEventBus);
          if (result) {
            // 淇濆瓨璁″垝鐘舵€佸埌纾佺洏锛屼笅娆″惎鍔ㄦ仮澶峔r
            savePlanState(context.projectRoot ?? process.cwd(), planState);
            writeln(result);
          }
          break;
        }
        case "party": {
          const gen = partyMode(input, bridge, [agent], history);
          const result = await consumeGenerator(gen, tuiEventBus);
          if (result) writeln(result);
          break;
        }
      }
    } catch (err) {
      writeln(`鉁?閿欒: ${err instanceof Error ? err.message : String(err)}`);
    }

    rl.prompt();
  });

  rl.on("close", () => {
    tokenMonitor.dispose();
  });

  // 绛夊緟 readline 鍏抽棴
  await new Promise<void>((resolve) => rl.on("close", resolve));

  return 0;
}

// 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺怽r
// 杈呭姪鍑芥暟
// 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺怽r

function buildPrompt(mode: ReplMode, agent: AgentType): string {
  const modeIcons: Record<ReplMode, string> = {
    command: "鈱╘

馃挰",
    talk: "馃棧",
    plan: "馃搵",
    party: "馃懃",
  };
  return `${modeIcons[mode]} ${agent} > `;
}

async function handleInternalCommand(
  input: string,
  rl: readline.Interface,
  setMode: (m: ReplMode) => void,
  setAgent: (a: AgentType) => void,
  _onStop: () => void,
  projectRoot: string,
): Promise<boolean> {
  const args = input.slice(1).split(/\s+/);
  const cmd = args[0];

  switch (cmd) {
    case "exit":
    case "quit":
      writeln("馃憢 鍐嶈锛乗

help":
      writeln("");
      writeln(`  ${bold("Cortex TUI 鍐呴儴鍛戒护")}`);
      writeln(`  ${dim("鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€")}`);
      writeln(`  .mode chat|talk|plan|party|command   鍒囨崲妯″紡`);
      writeln(`  .agent code|review|analysis|...      鍒囨崲瑙掕壊`);
      writeln(`  .help                                鏄剧ず甯姪`);
      writeln(`  .exit                                閫€鍑篳);
      writeln("");
      return true;

    case "mode":
      if (args[1]) {
        const newMode = args[1] as ReplMode;
        if (["chat", "talk", "plan", "party", "command"].includes(newMode)) {
          setMode(newMode);
          writeln(`鉁?宸插垏鎹㈠埌 ${newMode} 妯″紡`);
          rl.setPrompt(buildPrompt(newMode, "code" as AgentType));
        } else {
          writeln(`鉁?鏈煡妯″紡: ${args[1]}`);
        }
      }
      return true;

    case "agent":
      if (args[1]) {
        const newAgent = args[1] as AgentType;
        setAgent(newAgent);
        rl.setPrompt(buildPrompt("chat" as ReplMode, newAgent));
        writeln(`鉁?宸插垏鎹㈠埌 ${newAgent}`);
        renderAgentTransition("code" as AgentType, newAgent);
      }
      return true;

    default:
      writeln(`鉁?鏈煡鍛戒护: .${cmd}锛?help 鏌ョ湅甯姪锛塦);
      return true;
  }
}

/** 娑堣垂 async generator锛屽皢鎵€鏈変簨浠惰浆鍙戝埌浜嬩欢鎬荤嚎 */
async function consumeGenerator<T>(
  gen: AsyncGenerator<TuiEvent, T, void>,
  bus: typeof tuiEventBus,
): Promise<T> {
  let result: IteratorResult<TuiEvent, T>;
  while (!(result = await gen.next()).done) {
    bus.emit(result.value);
  }
  return result.value;
}

