/**
 * @cortex/config 鈥?鍙彃鎷旈厤缃姞杞藉櫒
 *
 * 鏍稿績璁捐鐞嗗康锛歕r
 *   1. 鍩熸敞鍐岋紙Domain Registry锛夆€斺€?姣忎釜閰嶇疆鍩熺嫭绔嬪０鏄庢枃浠跺悕銆佹槸鍚﹀繀闇€銆佹暟鎹敭鍚峔r
 *   2. 鎳掑姞杞斤紙Lazy Load锛夆€斺€?鎸夐渶鍔犺浇鍗曚釜鍩燂紝涓嶅繀涓€娆℃€у叏閲廫r
 *   3. 鍙彃鎷旓紙Pluggable锛夆€斺€?鏂板閰嶇疆鍩熷彧闇€娣诲姞涓€涓?ConfigDomain 鏉＄洰
 *   4. 鏂囦欢绯荤粺鏃犲叧锛團S-Agnostic锛夆€斺€?璋冪敤鏂规彁渚?readFile 瀹炵幇锛岃В鑰?Node/Browser
 *
 * 浣跨敤绀轰緥锛歕r
 * ```typescript
 * import { loadConfigDomain, loadAllConfig, getConfigDataPath } from "@cortex/config";
 *
 * // 鍔犺浇鍏ㄩ儴閰嶇疆
 * const config = loadAllConfig(readFileSync, getConfigDataPath());
 *
 * // 鎸夐渶鍔犺浇鍗曚釜鍩焅r
 * const agents = loadConfigDomain("agents", readFileSync, getConfigDataPath());
 * ```
 *
 * @module loader
 * @layer root 鈥?闆惰繍琛屾椂渚濊禆锛堜粎 fs 绫诲瀷锛塡r
 */

import * as path from "node:path";
import { fileURLToPath } from "node:url";

import type { AgentsConfig } from "./interfaces/agent.js";
import type { EngineConfig } from "./interfaces/engine.js";
import type { EventRoutingConfig } from "./interfaces/event-routing.js";
import type { RoundtableTemplate } from "./interfaces/roundtable.js";
import type { SearchProviderConfig, SearchAggregationConfig, McpServerEntry } from "./interfaces/search.js";
import type { SelfExaminationConfig } from "./interfaces/self-examination.js";
import type { CrossVerificationConfig } from "./interfaces/cross-verification.js";
import type { SeedMemoriesConfig } from "./interfaces/seed-memory.js";
import type { GovernancePipelineConfig } from "./interfaces/governance.js";
import type { CognitionConfig } from "./interfaces/cognition.js";
import type { DocsConfig } from "./interfaces/docs.js";
import type { ToolRegistry } from "./interfaces/tool.js";

// 鈹€鈹€鈹€ 鍩熸敞鍐?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 閰嶇疆鍩熸弿杩扮鈥斺€旀敞鍐屼竴涓厤缃煙鎵€闇€鐨勫厓淇℃伅銆俓r
 * 鏂板閰嶇疆鍩熷彧闇€鍦?CONFIG_DOMAINS 鏁扮粍娣诲姞涓€椤瑰嵆鍙€俓r
 */
export interface ConfigDomain {
  /** 鍩熸爣璇嗭紙濡?"agents", "engine"锛?*/
  name: string;
  /** JSON 鏂囦欢鍚嶏紙濡?"agents.json"锛?*/
  fileName: string;
  /** 鏄惁蹇呴渶鈥斺€旇嫢涓?true锛屾枃浠剁己澶辨椂鎶ラ敊 */
  required: boolean;
  /** JSON 涓壙杞芥暟鎹殑椤跺眰 key锛堝 "agents"锛夛紝undefined 琛ㄧず鏁翠釜 JSON 鍗充负鏁版嵁 */
  dataKey?: string;
  /** 鍩熸弿杩帮紙浜虹被鍙锛?*/
  description: string;
}

/**
 * 鎵€鏈夐厤缃煙鐨勬敞鍐岃〃鈥斺€斿彲鎻掓嫈銆俓r
 * 鏂板鍩熸椂鍙渶娣诲姞涓€椤癸紝鏃犻渶淇敼浠讳綍鍏朵粬浠ｇ爜銆俓r
 */
export const CONFIG_DOMAINS: ConfigDomain[] = [
  {
    name: "agents",
    fileName: "agents.json",
    required: true,
    dataKey: "agents",
    description: "Agent 瀹氫箟闆嗗悎鈥斺€旀瘡涓?Agent 鐨勫畬鏁村０鏄嶾

ConfigLoadError";
  }
}

/** 閰嶇疆鏍￠獙閿欒 */
export class ConfigValidationError extends Error {
  constructor(
    message: string,
    public readonly domainName: string,
  ) {
    super(`[config/${domainName}] ${message}`);
    this.name = "ConfigValidationError";
  }
}

// 鈹€鈹€鈹€ 璺緞宸ュ叿 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 瑙ｆ瀽 config 鍖呯殑 data 鐩綍缁濆璺緞銆俓r
 *
 * 鍦?monorepo 鐜涓紝閫氳繃 import.meta.url 鎺ㄥ dist/data/ 璺緞銆俓r
 * 缁撴灉浼氳缂撳瓨锛屽悗缁皟鐢ㄧ洿鎺ヨ繑鍥炪€俓r
 *
 * @returns data 鐩綍鐨勭粷瀵硅矾寰刓r
 * @throws ConfigLoadError 鑻ユ棤娉曡В鏋愶紙闈?Node.js ESM 鐜锛塡r
 */
export function resolveConfigDataDir(): string {
  if (_cachedDataDir) return _cachedDataDir;

  try {
    // 浠?dist/loader.js 鎺ㄥ锛歞ist/loader.js 鈫?dist/ 鈫?dist/data/
    const distDir = path.dirname(fileURLToPath(import.meta.url));
    const resolved = path.join(distDir, "data");
    _cachedDataDir = resolved;
    return resolved;
  } catch {
    throw new ConfigLoadError(
      "鏃犳硶瑙ｆ瀽 config data 鐩綍銆傝纭繚鍦?Node.js ESM 鐜涓繍琛岋紝鎴栨樉寮忎紶鍏?dataDir 鍙傛暟銆俓

loader",
    );
  }
}

/** 缂撳瓨宸茶В鏋愮殑 data 鐩綍璺緞 */
let _cachedDataDir: string | null = null;



// 鈹€鈹€鈹€ 鍔犺浇鍣ㄦ牳蹇?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 鍔犺浇鍗曚釜閰嶇疆鍩熴€俓r
 *
 * @param domainName 鍩熸爣璇嗭紙濡?"agents"锛塡r
 * @param readFile 鏂囦欢璇诲彇鍑芥暟
 * @param dataDir data 鐩綍鐨勭粷瀵硅矾寰刓r
 * @returns 瑙ｆ瀽鍚庣殑閰嶇疆鏁版嵁
 * @throws ConfigLoadError 鑻ユ枃浠剁己澶憋紙蹇呴渶鍩燂級鎴?JSON 瑙ｆ瀽澶辫触
 * @throws ConfigValidationError 鑻ユ暟鎹粨鏋勬牎楠屽け璐r
 */
export function loadConfigDomain<T = unknown>(
  domainName: string,
  readFile: ConfigFileReader,
  dataDir: string,
): T {
  const domain = CONFIG_DOMAINS.find((d) => d.name === domainName);
  if (!domain) {
    throw new ConfigLoadError(
      `鏈煡鐨勯厤缃煙 "${domainName}"銆傛湁鏁堝煙: ${CONFIG_DOMAINS.map((d) => d.name).join(", ")}`,
      domainName,
    );
  }

  const filePath = `${dataDir}/${domain.fileName}`;

  let raw: string;
  try {
    raw = readFile(filePath);
  } catch (e) {
    if (domain.required) {
      throw new ConfigLoadError(
        `蹇呴渶閰嶇疆鏂囦欢涓嶅瓨鍦? ${filePath}`,
        domainName,
        e,
      );
    }
    // 鍙€夊煙鏂囦欢缂哄け杩斿洖 undefined锛岃璋冪敤鏂硅嚜琛屽鐞嗛粯璁ゅ€糪r
    return undefined as T;
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new ConfigLoadError(
      `JSON 瑙ｆ瀽澶辫触: ${filePath}: ${String(e)}`,
      domainName,
      e,
    );
  }

  if (!parsed || typeof parsed !== "object") {
    throw new ConfigValidationError(
      `閰嶇疆鏂囦欢 ${filePath} 椤跺眰蹇呴』涓哄璞,
      domainName,
    );
  }

  const data = parsed as Record<string, unknown>;

  // 濡傛灉鏈?dataKey锛屾彁鍙栭敭鍊硷紱鍚﹀垯杩斿洖鏁翠釜瀵硅薄
  if (domain.dataKey) {
    if (!(domain.dataKey in data)) {
      throw new ConfigValidationError(
        `閰嶇疆鏂囦欢 ${filePath} 缂哄皯 "${domain.dataKey}" 瀛楁`,
        domainName,
      );
    }
    return data[domain.dataKey] as T;
  }

  return data as T;
}

/**
 * 鍔犺浇鎵€鏈夊凡娉ㄥ唽鐨勯厤缃煙銆俓r
 * 蹇呴渶鍩熺己澶变細鎶涘嚭閿欒锛屽彲閫夊煙缂哄け闈欓粯璺宠繃銆俓r
 *
 * @param readFile 鏂囦欢璇诲彇鍑芥暟
 * @param dataDir data 鐩綍鐨勭粷瀵硅矾寰刓r
 * @returns 鍏ㄩ噺閰嶇疆瀵硅薄
 */
export function loadAllConfig(
  readFile: ConfigFileReader,
  dataDir: string,
): CortexConfig {
  const config: CortexConfig = {};

  for (const domain of CONFIG_DOMAINS) {
    try {
      config[domain.name] = loadConfigDomain(domain.name, readFile, dataDir);
    } catch (e) {
      if (domain.required) {
        throw e;
      }
      // 鍙€夊煙缂哄け鈥斺€旈潤榛樿烦杩嘰r
    }
  }

  return config;
}

// 鈹€鈹€鈹€ 鍏ㄩ噺閰嶇疆绫诲瀷 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 鍏ㄩ噺 Cortex 閰嶇疆鈥斺€旀寜鍩熺储寮?*/
export interface CortexConfig {
  agents?: AgentsConfig;
  engine?: EngineConfig;
  tools?: ToolRegistry;
  eventRouting?: EventRoutingConfig;
  roundtable?: RoundtableTemplate[];
  searchProviders?: {
    backends: SearchProviderConfig[];
    aggregation: SearchAggregationConfig;
  };
  mcpServers?: Record<string, McpServerEntry>;
  selfExamination?: SelfExaminationConfig;
  crossVerification?: CrossVerificationConfig;
  seedMemories?: SeedMemoriesConfig;
  governancePipeline?: GovernancePipelineConfig;
  cognition?: CognitionConfig;
  docs?: DocsConfig;
  [key: string]: unknown;
}

