import * as path from "node:path";
import { type IFileSystemAdapter, type MemoryEntry, type MemoryWriteInput, type ReadMode } from "@cortex/shared";
import type { MemoryStore } from "@cortex/memory-store";
import { InitVerifier, type ConsistencyReport } from "./init-verifier.js";
import { SchemaEnforcer, type ValidationResult } from "./schema-enforcer.js";
import { IntentFactWall } from "./intent-fact-wall.js";

/**
 * ConsistencyLayer 鈥斺€?璁板繂-鐜板疄涓€鑷存€ф牎楠屽眰 Facade锛圥1-鍏眰闃插尽锛夈€俓n *
 * 浣滀负 MemoryStore 鐨勫閮ㄤ腑闂翠欢锛岀粍鍚?InitVerifier + SchemaEnforcer + IntentFactWall锛孿n * 鍦ㄥ叧閿叆鍙ｇ偣锛堝惎鍔ㄦ牎楠屻€佸啓鍏ュ墠鏍￠獙銆佽璺緞杩囨护锛夋彃鍏ヤ竴鑷存€ф鏌ャ€俓n *
 * 鏍稿績鍘熷垯锛氫笉淇敼 MemoryStore 鍐呴儴瀹炵幇銆俓n *
 * @since P1-鍏眰闃插尽
 * @since P0 鈥?IntentFactWall 闆嗘垚锛圕SA 璇昏矾寰?Intent 杩囨护锛塡n *
 * @fix D8 鈥?褰?enableInitVerifier: true 浣嗘湭鎻愪緵 fs 鏃讹紝閫氳繃 console.warn 鏄惧紡鍛婄煡鐢ㄦ埛
 *   InitVerifier 琚潤榛樼鐢紝閬垮厤鐢ㄦ埛璇互涓虹涓€閬撻槻绾垮凡灏辩华銆俓n */

// 鈹€鈹€鈹€ 閰嶇疆 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export interface ConsistencyLayerConfig {
  /** 椤圭洰鏍圭洰褰曪紙鐢ㄤ簬鏂囦欢璺緞瑙ｆ瀽锛?*/
  projectRoot: string;
  /** 鍚姩鏍￠獙闃堝€硷細缂哄け姣斾緥瓒呰繃姝ゅ€兼爣璁?fatal锛堥粯璁?0.3锛?*/
  failThreshold?: number;
  /** 鏄惁鍚敤鍚姩鏍￠獙 */
  enableInitVerifier?: boolean;
  /** 鏄惁鍚敤缁撴瀯鏍￠獙 */
  enableSchemaEnforcer?: boolean;
  /** FileSystemAdapter锛堟敞鍏ヤ互瀹炵幇鍙祴璇曟€э級 */
  fs?: IFileSystemAdapter;
  /** 杈呭姪鎼滅储璺緞锛氱煭鏂囦欢鍚嶆壘涓嶅埌鏃讹紝鍦ㄨ繖浜涘瓙鐩綍涓€掑綊鏌ユ壘 */
  searchPaths?: string[];
}

// 鈹€鈹€鈹€ Facade 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class ConsistencyLayer {
  private readonly _memory: MemoryStore;
  private readonly _config: Omit<Required<ConsistencyLayerConfig>, 'fs'> & { fs: IFileSystemAdapter | undefined };
  private readonly _initVerifier: InitVerifier | null;
  private readonly _schemaEnforcer: SchemaEnforcer | null;
  private readonly _intentFactWall: IntentFactWall;

  constructor(
    memory: MemoryStore,
    config: ConsistencyLayerConfig,
  ) {
    this._memory = memory;
    this._config = {
      projectRoot: path.resolve(config.projectRoot),
      failThreshold: config.failThreshold ?? 0.3,
      enableInitVerifier: config.enableInitVerifier ?? true,
      enableSchemaEnforcer: config.enableSchemaEnforcer ?? true,
      searchPaths: config.searchPaths ?? [],
      fs: config.fs,
    };

    if (this._config.enableInitVerifier && !this._config.fs) {
      console.warn(
        "[ConsistencyLayer] enableInitVerifier=true 浣嗘湭鎻愪緵 fs (IFileSystemAdapter)锛孿

; ")}`,
        );
      }
      input = this._schemaEnforcer.annotate(input);
    }
    input = this._intentFactWall.ensureSubType(input);
    return input;
  }

  /**
   * 鏍￠獙鍐欏叆杈撳叆鐨勭粨鏋勫畬鏁存€с€俓n   */
  validateInput(input: MemoryWriteInput): ValidationResult {
    if (!this._schemaEnforcer) {
      return { valid: true, errors: [] };
    }
    return this._schemaEnforcer.validate(input);
  }

  /**
   * 鑷姩娉ㄥ叆榛樿瀛楁銆俓n   */
  annotateInput(input: MemoryWriteInput): MemoryWriteInput {
    if (!this._schemaEnforcer) return input;
    return this._schemaEnforcer.annotate(input);
  }

  /**
   * 璇昏矾寰?Intent 杩囨护锛圥0-鍏眰闃插尽锛夈€俓n   *
   * CSA 妯″紡涓嬫帓闄?subType === Intent 鐨勮蹇嗭紝闃瞈

姹℃煋 Agent 鍐崇瓥銆俓n   * HCA 妯″紡涓嬩笉杩囨护鈥斺€擬etaAgent 闇€瑕佸叏灞€瑙嗗浘锛堝惈鍗婃垚鍝佹剰鍥撅級銆俓n   *
   * @param entries 璁板繂鍒楄〃
   * @param queryMode 娉ㄦ剰鍔涙ā寮忥紙hca/csa锛塡n   * @returns 杩囨护鍚庣殑璁板繂鍒楄〃
   */
  filterRead(entries: MemoryEntry[], mode: ReadMode = "CSA"): MemoryEntry[] {
    return this._intentFactWall.filterRead(entries, mode);
  }

  /**
   * 鍐欏墠 subType 榛樿鍊兼敞鍏ワ紙P0-鍏眰闃插尽锛夈€俓n   *
   * 鑻ユ湭鏄惧紡鎸囧畾 subType锛岄粯璁ゆ爣璁颁负 Fact銆俓n   * "璇翠笉娓呮槸鎰忓浘杩樻槸浜嬪疄鐨勶紝鎸変簨瀹炲鐞哱

@cortex/shared";
import type { MemoryStore } from "@cortex/memory-store";
import * as path from "node:path";
import * as crypto from "node:crypto";
import * as fs from "node:fs";
import { DEFAULT_ENGINE_CONFIG, DIR_CORTEX } from "@cortex/config";

/**
 * InitVerifier 鈥斺€?鍚姩鏃舵枃浠朵竴鑷存€ф牎楠岋紙P1-鍏眰闃插尽锛夈€俓r
 *
 * 鍦?MemoryStore.init() 涔嬪悗璋冪敤锛岄亶鍘嗘墍鏈?Active 璁板繂锛孿r
 * 鎻愬彇鍏朵腑寮曠敤鐨勬枃浠惰矾寰勶紝鏍￠獙鏂囦欢鏄惁渚濈劧瀛樺湪銆俓r
 *
 * Core-1 瀹炵幇锛氭枃浠跺瓨鍦ㄦ€ф鏌?+ SHA256 鍝堝笇鏍￠獙銆俓r
 * 鍝堝笇缂撳瓨鎸佷箙鍖栬嚦 .cortex/file-hashes.json锛岃法浼氳瘽姣斿銆俓r
 *
 * @since P1-鍏眰闃插尽
 */

// 鈹€鈹€鈹€ 鍝堝笇缂撳瓨璺緞 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

const HASH_CACHE_FILENAME = DEFAULT_ENGINE_CONFIG.filePaths.hashCache ?? ".cache/hash-cache.json";

// 鈹€鈹€鈹€ 绫诲瀷 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export interface VerificationEntry {
  memoryId: string;
  filePath: string;
  checkType: "exists" | "hash";
  status: "ok" | "missing" | "unchecked" | "changed";
  /** SHA256 hash锛堜粎 checkType=hash 涓?status=ok/changed 鏃舵湁鍊硷級 */
  hash?: string;
  /** 涓婃璁板綍鐨勫搱甯屽€硷紙浠?status=changed 鏃舵湁鍊硷級 */
  previousHash?: string;
}

export interface ConsistencyReport {
  timestamp: number;
  totalMemories: number;
  checkedMemories: number;
  fileChecks: VerificationEntry[];
  summary: {
    ok: number;
    missing: number;
    unchecked: number;
    changed: number;
  };
  /** 缂哄け姣斾緥瓒呰繃 failThreshold 鏃朵负 true */
  fatal: boolean;
}

// 鈹€鈹€鈹€ 鏂囦欢璺緞鎻愬彇 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 浠庤蹇嗘潯鐩腑鎻愬彇寮曠敤鐨勬枃浠惰矾寰勫垪琛ㄣ€俓r
 *
 * 浠呬娇鐢ㄦ樉寮忓０鏄庣殑璺緞鏉ユ簮锛歮etadata.files, content_blob.filePath, content_blob.path銆俓r
 *
 * 涓嶅啀浠?summary 鏂囨湰涓€氳繃姝ｅ垯鎻愬彇鏂囦欢鍚嶁€斺€旇鏉ユ簮瀛樺湪璺緞姝т箟涓旈殢 Agent
 * 鍛藉悕椋庢牸婕傜Щ鎸佺画浜х敓鍋囬槼鎬э紙涓嶅悓杩愯涓悓涓€璇箟鐨勬枃浠惰鍛藉悕涓轰笉鍚屽悕绉帮級銆俓r
 */
export function extractFileReferences(entry: MemoryEntry): string[] {
  const paths = new Set<string>();

  // 1. metadata.files: string[]
  const metaFiles = entry.content_blob?.["files"];
  if (Array.isArray(metaFiles)) {
    for (const f of metaFiles) {
      if (typeof f === "string" && f.length > 0) paths.add(f);
    }
  }

  // 2. content_blob.filePath / content_blob.path
  const content = entry.content_blob;
  if (content && typeof content === "object") {
    const fp = (content as Record<string, unknown>)["filePath"];
    const p = (content as Record<string, unknown>)["path"];
    if (typeof fp === "string" && fp.length > 0) paths.add(fp);
    if (typeof p === "string" && p.length > 0) paths.add(p);
  }

  return Array.from(paths);
}

// 鈹€鈹€鈹€ 鏍￠獙鍣?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class InitVerifier {
  private readonly _memory: MemoryStore;
  private readonly _fs: IFileSystemAdapter;
  private readonly _projectRoot: string;
  private readonly _failThreshold: number;
  /** 褰撶煭鏂囦欢鍚嶅湪 projectRoot 涓嬫壘涓嶅埌鏃讹紝灏濊瘯鍦ㄨ繖浜涘瓙鐩綍涓煡鎵?*/
  private readonly _searchPaths: string[];

  constructor(
    memory: MemoryStore,
    fs: IFileSystemAdapter,
    projectRoot: string,
    failThreshold: number = 0.3,
    searchPaths?: string[],
  ) {
    this._memory = memory;
    this._fs = fs;
    this._projectRoot = projectRoot;
    this._failThreshold = failThreshold;
    this._searchPaths = searchPaths ?? [];
  }

  /**
   * 杩愯鍚姩鏍￠獙銆俓r
   *
   * 娴佺▼锛歕r
   * 1. 璇诲彇鍏ㄩ儴 Active 璁板繂
   * 2. 閫愭潯鎻愬彇鏂囦欢寮曠敤
   * 3. 瀵规瘡涓枃浠惰矾寰勬鏌ュ瓨鍦ㄦ€?+ SHA256 鍝堝笇姣斿
   * 4. 鎸佷箙鍖栧綋鍓嶅搱甯岀紦瀛榎r
   * 5. 姹囨€荤敓鎴?ConsistencyReport
   */
  async run(): Promise<ConsistencyReport> {
    const timestamp = Date.now();

    // 鍔犺浇涓婃鍝堝笇缂撳瓨
    const prevHashes = this._loadHashCache();
    const currHashes = new Map<string, string>();

    // 鑾峰彇鍏ㄩ儴 Active 璁板繂锛坙imit=0 涓嶉檺閲忥紝trackAccess=false 閬垮厤鏍￠獙鎵弿姹℃煋璁块棶缁熻锛塡r
    const activeMemories = await this._memory.read({
      limit: 0,
    } as unknown as MemoryQuery);

    const totalMemories = activeMemories.length;
    const fileChecks: VerificationEntry[] = [];
    let okCount = 0;
    let missingCount = 0;
    let uncheckedCount = 0;
    let changedCount = 0;
    const checkedMemoryIds = new Set<string>();

    for (const entry of activeMemories) {
      const refs = extractFileReferences(entry);

      if (refs.length === 0) {
        // 鏃犳枃浠跺紩鐢ㄢ€斺€旇烦杩囷紙涓嶇畻 checked锛塡r
        continue;
      }

      checkedMemoryIds.add(entry.id);

      for (const filePath of refs) {
        let absPath = path.isAbsolute(filePath)
          ? filePath
          : path.resolve(this._projectRoot, filePath);

        try {
          let fileExists = await this._fs.exists(absPath);

          // 鐩存帴璺緞涓嶅瓨鍦ㄦ椂锛屽皾璇曞湪 searchPaths 涓€掑綊鏌ユ壘
          if (!fileExists && this._searchPaths.length > 0) {
            const fileName = path.basename(filePath);
            for (const searchDir of this._searchPaths) {
              const found = await this._findFile(fileName, searchDir);
              if (found) {
                absPath = found;
                fileExists = true;
                break;
              }
            }
          }

          if (!fileExists) {
            fileChecks.push({
              memoryId: entry.id,
              filePath,
              checkType: "exists",
              status: "missing",
            });
            missingCount++;
            continue;
          }

          // 鏂囦欢瀛樺湪鈥斺€旇绠?SHA256 鍝堝笇
          try {
            const hash = await this._computeHash(absPath);
            currHashes.set(filePath, hash);

            const prevHash = prevHashes.get(filePath);
            if (prevHash && prevHash !== hash) {
              // 鍝堝笇鍙樻洿锛氭枃浠跺唴瀹瑰凡淇敼
              fileChecks.push({
                memoryId: entry.id,
                filePath,
                checkType: "hash",
                status: "changed",
                hash,
                previousHash: prevHash,
              });
              changedCount++;
            } else {
              fileChecks.push({
                memoryId: entry.id,
                filePath,
                checkType: "hash",
                status: "ok",
                hash,
              });
              okCount++;
            }
          } catch {
            // 鍝堝笇璁＄畻澶辫触锛堝鏉冮檺涓嶈冻锛夆€斺€旈檷绾т负瀛樺湪鎬ф鏌r
            fileChecks.push({
              memoryId: entry.id,
              filePath,
              checkType: "exists",
              status: "ok",
            });
            okCount++;
          }
        } catch {
          fileChecks.push({
            memoryId: entry.id,
            filePath,
            checkType: "exists",
            status: "unchecked",
          });
          uncheckedCount++;
        }
      }
    }

    // 鎸佷箙鍖栧綋鍓嶅搱甯岀紦瀛榎r
    this._saveHashCache(currHashes);

    const totalChecked = okCount + missingCount + uncheckedCount + changedCount;
    const fatal = totalChecked > 0
      ? missingCount / totalChecked > this._failThreshold
      : false;

    return {
      timestamp,
      totalMemories,
      checkedMemories: checkedMemoryIds.size,
      fileChecks,
      summary: {
        ok: okCount,
        missing: missingCount,
        unchecked: uncheckedCount,
        changed: changedCount,
      },
      fatal,
    };
  }

  // 鈹€鈹€ 鍝堝笇缂撳瓨鎸佷箙鍖?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /** 鍝堝笇缂撳瓨鏂囦欢璺緞 */
  private get _hashCachePath(): string {
    return path.join(this._projectRoot, DIR_CORTEX, HASH_CACHE_FILENAME);
  }

  private _loadHashCache(): Map<string, string> {
    try {
      const cachePath = this._hashCachePath;
      if (fs.existsSync(cachePath)) {
        const raw = fs.readFileSync(cachePath, "utf-8");
        const data = JSON.parse(raw) as Record<string, string>;
        return new Map(Object.entries(data));
      }
    } catch { /* 缂撳瓨鎹熷潖鎴栭娆¤繍琛屸€斺€旇繑鍥炵┖鏄犲皠 */ }
    return new Map();
  }

  private _saveHashCache(hashes: Map<string, string>): void {
    try {
      const cachePath = this._hashCachePath;
      const dir = path.dirname(cachePath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      const data: Record<string, string> = {};
      for (const [k, v] of hashes) {
        data[k] = v;
      }
      fs.writeFileSync(cachePath, JSON.stringify(data, null, 2), "utf-8");
    } catch { /* 缂撳瓨鍐欏叆澶辫触鈥斺€旈潪鑷村懡 */ }
  }

  /**
   * 鍦ㄧ粰瀹氬瓙鐩綍涓€掑綊鏌ユ壘鎸囧畾鏂囦欢鍚嶇殑鏂囦欢銆俓r
   * 鏈€澶ф繁搴?3 灞傦紝閬垮厤鍦?node_modules 绛夊法鍨嬬洰褰曚腑娴垂鎬ц兘銆俓r
   * @returns 鎵惧埌鐨勭粷瀵硅矾寰勶紝鏈壘鍒拌繑鍥?null
   */
  private async _findFile(fileName: string, searchDir: string): Promise<string | null> {
    const baseDir = path.resolve(this._projectRoot, searchDir);
    return await this._searchFile(fileName, baseDir, 3);
  }

  private async _searchFile(
    fileName: string,
    dir: string,
    maxDepth: number,
  ): Promise<string | null> {
    if (maxDepth <= 0) return null;
    try {
      const exists = await this._fs.exists(dir);
      if (!exists) return null;
      const entries = await this._fs.listDirectory(dir);
      for (const entry of entries) {
        const entryPath = path.join(dir, entry.name);
        if (entry.isDirectory) {
          // 璺宠繃闅愯棌鐩綍鍜?node_modules
          if (entry.name.startsWith(".") || entry.name === "node_modules") continue;
          const found = await this._searchFile(fileName, entryPath, maxDepth - 1);
          if (found) return found;
        } else if (entry.name === fileName) {
          return entryPath;
        }
      }
    } catch {
      // 鐩綍涓嶅瓨鍦ㄦ垨鏃犳潈闄怽r
    }
    return null;
  }

  /**
   * 璁＄畻鏂囦欢 SHA256 鍝堝笇銆俓r
   * 瀵瑰ぇ鏂囦欢浣跨敤娴佸紡璇诲彇锛岄伩鍏?OOM銆俓r
   */
  private async _computeHash(absPath: string): Promise<string> {
    return await new Promise((resolve, reject) => {
      const hash = crypto.createHash("sha256");
      const stream = fs.createReadStream(absPath, { highWaterMark: 64 * 1024 });
      stream.on("data", (chunk) => hash.update(chunk));
      stream.on("end", () => resolve(hash.digest("hex")));
      stream.on("error", reject);
    });
  }
}

