 * 灏嗕换鍔℃暟鎹瓨鍌ㄤ负 JSON 鏂囦欢銆俓n * 鍐欐搷浣滀娇鐢ㄥ師瀛愬啓鍏ワ紙鍐欎复鏃舵枃浠?-> rename锛夈€俓n *
 * 鍘熶綅浜?.cortex/archive/.../solo-flight/src/storage/adapters/json-file.adapter.ts
 *
 * @fix P2-9 -- 鍚屾 I/O 缃崲涓哄紓姝?fs.promises锛岄伩鍏嶉樆濉炰簨浠跺惊鐜痋n * @fix M-02 -- ensureDir 鏀逛负寮傛锛屾秷闄?async 鏂规硶鍐呭悓姝?I/O 闃诲浜嬩欢寰幆
 */

import { mkdir, readFile, writeFile, rename, unlink } from 'node:fs/promises';
import * as path from 'node:path';
import { Task, type TaskJSON } from '../../core/models/task.js';
import type { TaskRepository, TaskFilter } from '../interfaces/task.repository.js';
import { TaskNotFoundError, StorageIOError } from '../errors.js';

export class JsonFileAdapter implements TaskRepository {
  private tasks: Map<string, Task> = new Map();
  private readonly filePath: string;
  private loaded: boolean = false;
  private _loadPromise: Promise<void> | null = null;

  constructor(filePath: string) {
    this.filePath = path.resolve(filePath);
  }

  /**
   * @fix P1-7 鈥?浠呭悶娌?EEXIST 閿欒锛堢洰褰曞凡瀛樺湪锛夛紝
   *   鍏朵粬閿欒锛堟潈闄愪笉瓒炽€佺鐩樻弧銆佽矾寰勯潪娉曪級鍚戜笂浼犳挱锛孿n   *   閬垮厤涓㈠け鏍瑰洜璇婃柇淇℃伅銆俓n   */
  private async ensureDir(): Promise<void> {
    const dir = path.dirname(this.filePath);
    try {
      await mkdir(dir, { recursive: true });
    } catch (err: unknown) {
      // EEXIST: 鐩綍宸插瓨鍦紝瀹夊叏蹇界暐锛坮ecursive:true 鏈簲澶勭悊锛屼絾鏌愪簺骞冲彴/FS 浠嶅彲鑳芥姏 EEXIST锛塡n      if ((err as NodeJS.ErrnoException)?.code === 'EEXIST') return;
      // 闈?EEXIST 閿欒鈥斺€旀潈闄愪笉瓒炽€佺鐩樻弧绛夆€斺€斿悜涓婁紶鎾璡n      throw err;
    }
  }

  private async load(): Promise<void> {
    if (this.loaded) return;
    // 闃插苟鍙戯細澶氫釜璇锋眰鍚屾椂瑙﹀彂 load 鏃讹紝棣栦釜璇锋眰璐熻矗鍔犺浇锛屽悗缁姹傜瓑寰匼n    if (this._loadPromise) {
      await this._loadPromise;
      return;
    }

    this._loadPromise = this._doLoad();
    try {
      await this._loadPromise;
    } finally {
      this._loadPromise = null;
    }
  }

  private async _doLoad(): Promise<void> {
    await this.ensureDir();

    let fileExists: boolean;
    try {
      await readFile(this.filePath, 'utf-8');
      fileExists = true;
    } catch {
      fileExists = false;
    }

    if (!fileExists) {
      this.tasks = new Map();
      this.loaded = true;
      // 鍒涘缓绌烘枃浠讹紝纭繚鍚庣画 reopen 鍙甯稿姞杞絓n      await this.persist();
      return;
    }

    try {
      const raw = await readFile(this.filePath, 'utf-8');

      if (!raw || raw.trim().length === 0) {
        this.tasks = new Map();
        this.loaded = true;
        return;
      }

      const data: { version: number; tasks: Record<string, TaskJSON> } = JSON.parse(raw);

      this.tasks = new Map();
      if (data && data.tasks) {
        for (const [id, taskData] of Object.entries(data.tasks)) {
          this.tasks.set(id, Task.fromJSON(taskData));
        }
      }
      this.loaded = true;
    } catch (err) {
      throw new StorageIOError(
        `鏃犳硶璇诲彇浠诲姟鏁版嵁鏂囦欢: ${this.filePath}`,
        err instanceof Error ? err : undefined,
      );
    }
  }

  private async persist(): Promise<void> {
    await this.ensureDir();

    const data: { version: number; tasks: Record<string, TaskJSON> } = {
      version: 1,
      tasks: {},
    };

    for (const [id, task] of this.tasks) {
      data.tasks[id] = task.toJSON();
    }

    const content = JSON.stringify(data, null, 2);
    const tmpPath = this.filePath + '.tmp';

    try {
      await writeFile(tmpPath, content, 'utf-8');
      await rename(tmpPath, this.filePath);
    } catch (err) {
      try { await unlink(tmpPath); } catch { /* ignore */ }
      throw new StorageIOError(
        `鏃犳硶鍐欏叆浠诲姟鏁版嵁鏂囦欢: ${this.filePath}`,
        err instanceof Error ? err : undefined,
      );
    }
  }

  async findAll(filter?: TaskFilter): Promise<Task[]> {
    await this.load();

    let result = Array.from(this.tasks.values());

    if (!filter?.includeDeleted) {
      result = result.filter(t => !t.isDeleted);
    }

    if (filter) {
      if (filter.status !== undefined) {
        result = result.filter(t => t.status === filter.status);
      }
      if (filter.priority !== undefined) {
        result = result.filter(t => t.priority === filter.priority);
      }
      if (filter.tags && filter.tags.length > 0) {
        const tags = filter.tags;
        result = result.filter(t =>
          tags.some(tag => t.tags.includes(tag)),
        );
      }
      if (filter.search?.trim()) {
        const keyword = filter.search.toLowerCase();
        result = result.filter(t =>
          t.title.toLowerCase().includes(keyword)
          || t.description.toLowerCase().includes(keyword)
          || t.tags.some(tag => tag.toLowerCase().includes(keyword))
        );
      }
    }

    result.sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());

    return result;
  }

  async findById(id: string): Promise<Task | null> {
    await this.load();
    return this.tasks.get(id) || null;
  }

  async save(task: Task): Promise<void> {
    await this.load();
    this.tasks.set(task.id, task);
    await this.persist();
  }

  async delete(id: string): Promise<void> {
    await this.load();
    if (!this.tasks.has(id)) {
      throw new TaskNotFoundError(id);
    }
    this.tasks.delete(id);
    await this.persist();
  }

  async count(filter?: TaskFilter): Promise<number> {
    const tasks = await this.findAll(filter);
    return tasks.length;
  }
}

