/** 娴嬭瘯鏂囦欢棣栬鏍囨敞鐨勬鍒?*/
const CI_TAG_REGEX = /^\/\/\s*@ci:\s*(unit|llm|integration|e2e|manual)/;

/** 璇勫垎鎵ｅ垎甯搁噺 */
const ERROR_PENALTY_POINTS = 15;
const WARNING_PENALTY_POINTS = 10;

/** runId 鐢熸垚鍙傛暟 */
const RUN_ID_RADIX = 36;

