/**
 * 浠庨」鐩牴鐩綍鎵弿鎵€鏈夊瓙鍖呫€俓n * 鏌ユ壘 packages/ 鐩綍涓嬫墍鏈夊惈 package.json 鐨勭洰褰曘€俓n */
function scanPackages(projectRoot: string): PackageMeta[] {
  const packagesDir = path.join(projectRoot, "packages");
  const results: PackageMeta[] = [];

  let entryNames: string[];
  try {
    entryNames = fs.readdirSync(packagesDir);
  } catch (err: unknown) {
    // packages 鐩綍涓嶅瓨鍦ㄦ垨涓嶅彲璇伙紝杩斿洖绌虹粨鏋淺n    const errMsg = err instanceof Error ? err.message : String(err);
    console.error(`scanPackages: 璇诲彇 ${packagesDir} 澶辫触: ${errMsg}`);
    return results;
  }

  for (const name of entryNames) {
    const pkgPath = path.join(packagesDir, name);
    let stat: fs.Stats;

    try {
      stat = fs.statSync(pkgPath);
    } catch (err: unknown) {
      const errMsg = err instanceof Error ? err.message : String(err);
      console.error(`scanPackages: 鑾峰彇 ${pkgPath} 鐘舵€佸け璐? ${errMsg}`);
      continue;
    }

    if (!stat.isDirectory()) {
      continue;
    }

    const pkgJsonPath = path.join(pkgPath, "package.json");
    if (!fs.existsSync(pkgJsonPath)) {
      continue;
    }

    let pkgName = name;
    const pkgJsonIssues: string[] = [];

    try {
      const raw = fs.readFileSync(pkgJsonPath, "utf-8");
      const parsed = JSON.parse(raw) as Record<string, unknown>;
      if (typeof parsed.name === "string") {
        pkgName = parsed.name;
      }
      pkgJsonIssues.push(...checkPackageJsonFields(parsed));
    } catch (err: unknown) {
      const errMsg = err instanceof Error ? err.message : String(err);
      pkgJsonIssues.push(`鏃犳硶瑙ｆ瀽 package.json: ${errMsg}`);
    }

    const hasPositioningDoc = fs.existsSync(
      path.join(pkgPath, "PACKAGE_POSITIONING.md"),
    );

    const testHeaderIssues = checkTestHeaders(pkgPath);

    results.push({
      name: pkgName,
      path: `packages/${name}`,
      absolutePath: pkgPath,
      hasPositioningDoc,
      pkgJsonIssues,
      testHeaderIssues,
    });
  }

  return results;
}

/**
 * 妫€鏌?package.json 鐨勫繀妫€瀛楁銆俓n * 鏀寔鐐瑰彿璺緞宓屽锛堝 "scripts.build" 琛ㄧず scripts 瀵硅薄涓嬬殑 build 瀛楁锛夈€俓n */
function checkPackageJsonFields(pkgJson: Record<string, unknown>): string[] {
  const issues: string[] = [];

  for (const field of REQUIRED_PKG_FIELDS) {
    const parts = field.split(".");
    let current: unknown = pkgJson;

    let missing = false;
    for (const part of parts) {
      if (current === null || current === undefined || typeof current !== "object") {
        issues.push(`缂哄皯瀛楁: ${field}`);
        missing = true;
        break;
      }
      const obj = current as Record<string, unknown>;
      if (!(part in obj)) {
        issues.push(`缂哄皯瀛楁: ${field}`);
        missing = true;
        break;
      }
      current = obj[part];
    }

    if (missing) {
      continue;
    }

    // 鏍瑰瓧娈靛€兼鏌n    if (parts.length === 1 && current !== undefined) {
      if (field === "name" && typeof current !== "string") {
        issues.push(`${field} 搴斾负 string锛屽疄闄呬负 ${typeof current}`);
      } else if (field === "version" && typeof current !== "string") {
        issues.push(`${field} 搴斾负 string锛屽疄闄呬负 ${typeof current}`);
      } else if (field === "private" && typeof current !== "boolean") {
        issues.push(`${field} 搴斾负 boolean锛屽疄闄呬负 ${typeof current}`);
      } else if (field === "type" && current !== "module") {
        issues.push(`${field} 搴斾负 "module"锛屽疄闄呬负 ${JSON.stringify(current)}`);
      } else if (field === "scripts" && typeof current !== "object") {
        issues.push(`${field} 搴斾负 object锛屽疄闄呬负 ${typeof current}`);
      }
    }
  }

  // 妫€鏌?scripts 涓悇瀛楁鐨勫€肩被鍨媆n  const scripts = pkgJson.scripts;
  if (scripts && typeof scripts === "object") {
    const scriptObj = scripts as Record<string, unknown>;
    for (const key of ["build", "typecheck", "test"]) {
      if (key in scriptObj && typeof scriptObj[key] !== "string") {
        issues.push(`scripts.${key} 搴斾负 string`);
      }
    }
  }

  return issues;
}

/**
 * 妫€鏌ュ寘鐩綍涓嬬殑娴嬭瘯鏂囦欢棣栬鏄惁鍖呭惈鍚堟硶鐨?`// @ci:` 鏍囨敞銆俓n * 鎵弿 tests/ 鐩綍涓嬫墍鏈?*.test.ts 鏂囦欢銆俓n */
function checkTestHeaders(pkgPath: string): string[] {
  const issues: string[] = [];
  const testsDir = path.join(pkgPath, "tests");

  if (!fs.existsSync(testsDir)) {
    return []; // 鏃?tests 鐩綍涓嶆姤閿欙紙鏈変簺鍖呭彲鑳借繕娌℃湁娴嬭瘯锛塡n  }

  let testFileNames: string[];
  try {
    testFileNames = fs.readdirSync(testsDir).filter((f) => f.endsWith(".test.ts"));
  } catch (err: unknown) {
    const errMsg = err instanceof Error ? err.message : String(err);
    console.error(`checkTestHeaders: 璇诲彇 ${testsDir} 澶辫触: ${errMsg}`);
    return issues;
  }

  for (const file of testFileNames) {
    const filePath = path.join(testsDir, file);
    try {
      const content = fs.readFileSync(filePath, "utf-8");
      const firstLine = content.split("\n")[0].trim();

      if (!CI_TAG_REGEX.test(firstLine)) {
        issues.push(
          `${file}: 棣栬缂哄皯鍚堟硶鐨?@ci 鏍囨敞锛堝簲涓?// @ci: unit | llm | integration | e2e | manual锛夛紝瀹為檯棣栬: "${firstLine}"`,
        );
      }
    } catch {
      issues.push(`${file}: 鏃犳硶璇诲彇`);
    }
  }

  return issues;
}

