// 妫€鏌ュ櫒锛歅ACKAGE_POSITIONING.md 瀛樺湪鎬ф鏌n// ============================================================

class PositioningDocChecker implements IChecker {
  readonly name = "positioning-doc";
  readonly description = "妫€鏌ュ悇鍖呮槸鍚﹀瓨鍦?PACKAGE_POSITIONING.md 瀹氫綅鏂囨。";

  async check(projectRoot: string, _options?: CheckerOptions): Promise<CheckResult> {
    const startTime = Date.now();
    const packages = scanPackages(projectRoot);
    const findings: Finding[] = [];

    for (const pkg of packages) {
      if (!pkg.hasPositioningDoc) {
        findings.push({
          id: `POS-DOC-${findings.length + 1}`,
          severity: "warning",
          checker: this.name,
          title: `${pkg.name}: 缂哄皯 PACKAGE_POSITIONING.md`,
          message: `鍖?${pkg.name}锛?{pkg.path}锛夋湭鎻愪緵 PACKAGE_POSITIONING.md锛屾棤娉曠‘璁ゅ叾瀹氫綅鍜岃ˉ瓒冲０鏄巂,
          files: [pkg.absolutePath],
          suggestion: `鍦?${pkg.path}/ 涓嬪垱寤?PACKAGE_POSITIONING.md锛岃鏄庤鍖呰ˉ瓒充簡浠€涔堛€佸畾浣嶆槸浠€涔堛€佸€煎緱鍚堝叆鐨勫師鍥燻,
          reference: "瀹硶 搂浜?琛ヨ冻澹版槑鏈哄埗",
        });
      }
    }

    const summary = computeSummary(findings);
    const passed = summary.error === 0 && summary.fatal === 0;

    return {
      checker: this.name,
      passed,
      findings,
      summary,
      score: passed
        ? 100
        : Math.max(0, 100 - findings.length * WARNING_PENALTY_POINTS),
      durationMs: Date.now() - startTime,
    };
  }
}

