class TestHeaderChecker implements IChecker {
  readonly name = "test-header";
  readonly description = "妫€鏌ュ悇鍖呮祴璇曟枃浠堕琛屾槸鍚﹀寘鍚悎娉曠殑 // @ci: 鏍囨敞";

  async check(projectRoot: string, _options?: CheckerOptions): Promise<CheckResult> {
    const startTime = Date.now();
    const packages = scanPackages(projectRoot);
    const findings: Finding[] = [];

    for (const pkg of packages) {
      for (const issue of pkg.testHeaderIssues) {
        findings.push({
          id: `TEST-HDR-${findings.length + 1}`,
          severity: "error",
          checker: this.name,
          title: `${pkg.name}: 娴嬭瘯鏂囦欢棣栬鏍囨敞涓嶅悎瑙刞,
          message: `鍖?${pkg.name}锛?{pkg.path}锛夌殑娴嬭瘯鏂囦欢闂锛?{issue}`,
          files: [path.join(pkg.absolutePath, "tests")],
          suggestion: `鍦ㄦ祴璇曟枃浠堕琛屾坊鍔?// @ci: unit | llm | integration | e2e | manual 鏍囨敞`,
          reference: "瀹硶 搂鍗佸洓路涓€ 娴嬭瘯闂ㄧ鑷０鏄庢満鍒禱

summary"] {
  let fatal = 0;
  let error = 0;
  let warning = 0;
  let info = 0;

  for (const f of findings) {
    switch (f.severity) {
      case "fatal": {
        fatal++;
        break;
      }
      case "error": {
        error++;
        break;
      }
      case "warning": {
        warning++;
        break;
      }
      case "info": {
        info++;
        break;
      }
    }
  }

  return { fatal, error, warning, info, total: findings.length };
}

