// HealthChecker 鈥斺€?缁熶竴鍋ュ悍妫€鏌ュ叆鍙n// ============================================================

/**
 * HealthChecker 鏄?@cortex/doctor 鐨勬牳蹇冨叆鍙ｃ€俓n * 瀹冩敞鍐屽唴缃鏌ュ櫒锛坧ackageJson銆乸ositioningDoc銆乼estHeader锛夛紝
 * 骞舵彁渚?diagnose() 鏂规硶鎵ц瀹屾暣妫€鏌ョ绾裤€俓n *
 * 鐢ㄦ硶锛歕n * ```typescript
 * const checker = new HealthChecker();
 * const report = await checker.diagnose("/path/to/monorepo");
 * console.log(report.status); // "healthy" | "warning" | "unhealthy" | "error"
 * ```
 */
export class HealthChecker {
  private checkers: IChecker[];

  constructor() {
    this.checkers = [
      new PackageJsonChecker(),
      new PositioningDocChecker(),
      new TestHeaderChecker(),
    ];
  }

  /**
   * 娉ㄥ唽鑷畾涔夋鏌ュ櫒銆俓n   * 鍚屽悕妫€鏌ュ櫒锛坣ame 鐩稿悓锛変細瑕嗙洊宸叉敞鍐岀殑妫€鏌ュ櫒銆俓n   */
  registerChecker(checker: IChecker): void {
    const existing = this.checkers.findIndex((c) => c.name === checker.name);
    if (existing >= 0) {
      this.checkers[existing] = checker;
    } else {
      this.checkers.push(checker);
    }
  }

  /** 鑾峰彇宸叉敞鍐岀殑鎵€鏈夋鏌ュ櫒 */
  getCheckers(): IChecker[] {
    return [...this.checkers];
  }

  /**
   * 鎵ц瀹屾暣鍋ュ悍妫€鏌ャ€俓n   *
   * @param projectRoot - 椤圭洰鏍圭洰褰曪紙榛樿 process.cwd()锛塡n   * @param options - 璇婃柇閫夐」
   * @returns HealthReport 鍋ュ悍鎶ュ憡
   */
  async diagnose(
    projectRoot?: string,
    options?: Partial<DoctorOptions>,
  ): Promise<HealthReport> {
    const root = projectRoot ?? process.cwd();
    const verbose = options?.verbose ?? false;
    const only = options?.only;
    const skip = options?.skip;

    // 瑙ｆ瀽 only/skip 杩囨护鍣╘n    // 娉ㄦ剰锛氶渶鍖哄垎 "鏈彁渚涘弬鏁癨

" 鈫?[]锛岃繃婊ゅ嚭绌洪泦锛塡n    const onlyNames = only !== undefined
      ? only.split(",").map((s) => s.trim()).filter(Boolean)
      : null;
    const skipNames = skip !== undefined
      ? skip.split(",").map((s) => s.trim()).filter(Boolean)
      : null;

    // 杩囨护妫€鏌ュ櫒
    let activeCheckers = this.checkers;
    if (onlyNames) {
      const o = onlyNames;
      activeCheckers = activeCheckers.filter((c) => o.includes(c.name));
    }
    if (skipNames) {
      const s = skipNames;
      activeCheckers = activeCheckers.filter((c) => !s.includes(c.name));
    }

    if (activeCheckers.length === 0) {
      return {
        meta: {
          scannedAt: new Date().toISOString(),
          projectRoot: root,
          runId: generateRunId(),
          durationMs: 0,
          packageCount: 0,
        },
        checks: [],
        status: "healthy",
      };
    }

    // 鎵弿鍖咃紙渚涘厓淇℃伅浣跨敤锛屽悇妫€鏌ュ櫒鍐呴儴涔熶細鎵弿锛塡n    const packages = scanPackages(root);

    // 骞惰鎵ц鎵€鏈夋鏌ュ櫒
    const startTime = Date.now();
    const results = await Promise.all(
      activeCheckers.map((checker) =>
        checker.check(root, { verbose, projectRoot: root }).catch((err: unknown) => {
          const errMsg = err instanceof Error ? err.message : String(err);
          const failedResult: CheckResult = {
            checker: checker.name,
            passed: false,
            findings: [
              {
                id: `CHECKER-ERR-${checker.name}`,
                severity: "fatal",
                checker: checker.name,
                title: `${checker.name} 妫€鏌ュ櫒鎵ц寮傚父`,
                message: `妫€鏌ュ櫒 ${checker.name} 鎵ц鏃跺彂鐢熸湭棰勬湡閿欒: ${errMsg}`,
                files: [],
                suggestion: `璇锋鏌ラ」鐩粨鏋勬槸鍚︽纭紝鎴栨煡鐪嬪畬鏁撮敊璇棩蹇梎,
              },
            ],
            summary: { fatal: 1, error: 0, warning: 0, info: 0, total: 1 },
            score: 0,
            durationMs: 0,
          };
          return failedResult;
        }),
      ),
    );
    const totalDuration = Date.now() - startTime;

    // 璁＄畻鎬讳綋鐘舵€乗n    const allFindings = results.flatMap((r) => r.findings);
    const hasFatal = allFindings.some((f) => f.severity === "fatal");
    const hasError = allFindings.some((f) => f.severity === "error");
    const hasWarning = allFindings.some((f) => f.severity === "warning");

    // 鍖哄垎"妫€鏌ュ櫒鑷韩寮傚父"涓嶾

    const hasCheckerCrash = allFindings.some(
      (f) => f.severity === "fatal" && f.id.startsWith("CHECKER-ERR-"),
    );

    let status: HealthReport["status"];
    if (hasCheckerCrash) {
      status = "error";  // 妫€鏌ュ櫒鎵ц寮傚父锛堜笌鍋ュ悍闂鍖哄垎锛塡n    } else if (hasFatal || hasError) {
      status = "unhealthy";
    } else if (hasWarning) {
      status = "warning";
    } else {
      status = "healthy";
    }

    return {
      meta: {
        scannedAt: new Date().toISOString(),
        projectRoot: root,
        runId: generateRunId(),
        durationMs: totalDuration,
        packageCount: packages.length,
      },
      checks: results,
      status,
    };
  }

  /**
   * 杩愯鎸囧畾鍚嶇О鐨勬鏌ュ櫒锛岃烦杩囧叾浠栨鏌ュ櫒銆俓n   * 绛変环浜?diagnose 璁剧疆 only 鍙傛暟銆俓n   */
  async runOnly(checkerNames: string[], projectRoot?: string): Promise<HealthReport> {
    return await this.diagnose(projectRoot, { only: checkerNames.join(",") });
  }
}

// ============================================================
// 渚挎嵎宸ュ巶鍑芥暟
// ============================================================

/**
 * 鍒涘缓榛樿 HealthChecker 瀹炰緥骞舵墽琛岃瘖鏂€俓n * 閫傚悎 CLI 鎴?CI 鑴氭湰鐩存帴璋冪敤銆俓n *
 * @example
 * ```typescript
 * import { doctor } from '@cortex/doctor';
 * const report = await doctor();
 * console.log(report.status);
 * ```
 */
export async function doctor(projectRoot?: string): Promise<HealthReport> {
  const checker = new HealthChecker();
  return await checker.diagnose(projectRoot);
}

