import { AgentType as AT, LinkType, type MemoryQuery, type AgentType, type TaskNode } from "@cortex/shared";
import type { LlmAdapter } from "@cortex/llm";
import type { Toolkit } from "@cortex/platform";
import type { MemoryStore } from "@cortex/memory-store";
import { BaseAgent } from "../base-agent.js";
import { createMemoryQuery } from "./registry.js";

const apiMemoryQuery = createMemoryQuery({
  kind: "TaskLog",
  linkTypes: [LinkType.DerivedFrom, LinkType.ProducedBy],
  bfsDepth: 2,
  limit: 5,
});

export class ApiAgent extends BaseAgent {
  readonly type: AgentType = AT.Api;
  readonly systemPrompt: string;

  constructor(llm: LlmAdapter, toolkit: Toolkit, systemPrompt: string, memory?: MemoryStore) {
    super(llm, toolkit, memory);
    this.systemPrompt = systemPrompt;
  }

  getMemoryQuery(node: TaskNode): MemoryQuery {
    return apiMemoryQuery(node);
  }
}

import { AgentType as AT, AgentStatus as AS, type TaskNode, type Agent, type SafeErrorReporter, type MemoryEntry, type ReadMode } from "@cortex/shared";
import type { LlmAdapter } from "@cortex/llm";
import type { Toolkit } from "@cortex/platform";
import type { MemoryStore } from "@cortex/memory-store";
import type { AgentPool } from "@cortex/scheduler";
import { createAgent, type AgentFactoryConfig } from "../components/agent-factory.js";
import { BROWSER_DEFAULT_VIEWPORT } from "@cortex/config";
import { chromium, type Browser, type Page } from "playwright";

/**
 * 鍒涘缓 BrowserAgent鈥斺€擯laywright UI 楠岃瘉涓撳銆俓r
 * 杩斿洖绗﹀悎 Agent 鎺ュ彛鐨勫璞★紝闄勫姞 setWorkspaceRoot + browser_do 鏀寔銆俓r
 */
export function createBrowserAgent(
  llm: LlmAdapter,
  toolkit: Toolkit,
  memory?: MemoryStore,
  systemPrompt?: string,
  filterRead?: (entries: MemoryEntry[], mode: ReadMode) => MemoryEntry[],
): Agent & {
  setPool(pool: AgentPool, instanceId: string): void;
  setSafeReporter(reporter: SafeErrorReporter): void;
  setWorkspaceRoot(root: string): void;
  wakeup(): Promise<void>;
  shutdown(): Promise<void>;
} {
  let browser: Browser | null = null;
  let page: Page | null = null;
  let workspaceRoot: string | null = null;
  let safeReporterRef: SafeErrorReporter | null = null;

  // 娉ㄥ唽 browser_do 宸ュ叿
  toolkit.register("browser_do", async (params) => {
    const action = params.action as string;
    const timeout = (params.timeout as number) ?? 10_000;

    if (!page) {
      return { success: false, error: "娴忚鍣ㄦ湭鍒濆鍖朶

navigate": {
          const url = params.url as string;
          if (!url) return { success: false, error: "navigate 缂哄皯 url 鍙傛暟" };
          await page.goto(url, { timeout, waitUntil: "domcontentloaded" });
          const title = await page.title();
          return { success: true, output: `宸叉墦寮€椤甸潰: ${title} (${url})` };
        }
        case "type": {
          const selector = params.selector as string;
          const text = params.text as string;
          if (!selector) return { success: false, error: "type 缂哄皯 selector 鍙傛暟" };
          if (text === undefined) return { success: false, error: "type 缂哄皯 text 鍙傛暟" };
          await page.waitForSelector(selector, { timeout });
          await page.fill(selector, text);
          return { success: true, output: `宸插湪 "${selector}" 涓緭鍏? "${text}"` };
        }
        case "click": {
          const selector = params.selector as string;
          if (!selector) return { success: false, error: "click 缂哄皯 selector 鍙傛暟" };
          await page.waitForSelector(selector, { timeout });
          await page.click(selector);
          return { success: true, output: `宸茬偣鍑?"${selector}"` };
        }
        case "read": {
          const selector = params.selector as string;
          if (!selector) return { success: false, error: "read 缂哄皯 selector 鍙傛暟" };
          await page.waitForSelector(selector, { timeout, state: "visible" });
          const text = await page.textContent(selector);
          return { success: true, output: text ?? "(鍏冪礌瀛樺湪浣嗘棤鏂囨湰鍐呭)" };
        }
        case "screenshot": {
          const buf = await page.screenshot({ type: "png", fullPage: false });
          const b64 = buf.toString("base64");
          return { success: true, output: `[鎴浘宸茬敓鎴愶紝${buf.length} bytes锛宐ase64 鍓?200 瀛楃] ${b64.slice(0, 200)}...` };
        }
        default:
          return { success: false, error: `鏈煡 browser_do 鎿嶄綔: "${action}"` };
      }
    } catch (e) {
      return { success: false, error: `browser_do.${action} 澶辫触: ${e instanceof Error ? e.message.slice(0, 300) : String(e).slice(0, 300)}` };
    }
  });

  const config: AgentFactoryConfig = {
    type: AT.Browser,
    systemPrompt: systemPrompt ?? '',
    memoryEnabled: true,
    filterRead,
    preExecuteHook: (node: TaskNode): TaskNode => {
      if (!workspaceRoot) return node;
      return {
        ...node,
        payload: `${node.payload}\n\n[宸ヤ綔鍖鸿矾寰刔 ${workspaceRoot}\n锛堟湰鍦?HTML 鏂囦欢鍙娇鐢?file:/// 鍗忚鎵撳紑锛屼緥濡?file:///${workspaceRoot.replace(/\\/g, "/")}/index.html锛塦,
      };
    },
  };

  const agent = createAgent(config, llm, toolkit, memory);

  async function initBrowser(): Promise<void> {
    if (browser?.isConnected()) return;
    browser = await chromium.launch({ headless: true });
    page = await browser.newPage();
    await page.setViewportSize(BROWSER_DEFAULT_VIEWPORT);
  }

  const origWakeup = agent.wakeup;
  const origExecute = agent.execute;
  const origShutdown = agent.shutdown;

  return {
    ...agent,

    setWorkspaceRoot(root: string) {
      workspaceRoot = root;
    },

    setSafeReporter(reporter: SafeErrorReporter) {
      safeReporterRef = reporter;
      agent.setSafeReporter(reporter);
    },

    async wakeup(): Promise<void> {
      if (agent.status !== AS.Created) return;
      await initBrowser();
      await origWakeup();
    },

    async execute(node: TaskNode, model: string) {
      if (!page) await initBrowser();
      return await origExecute(node, model);
    },

    async shutdown(): Promise<void> {
      await origShutdown();
      if (browser) {
        try { await browser.close(); } catch (e) {
          if (safeReporterRef) {
            safeReporterRef({ source: "BrowserAgent.shutdown", error: e, severity: "degraded", hint: "browser.close() failed" });
          } else {
            console.warn(`[BrowserAgent] browser.close() 澶辫触: ${String(e)}`);
          }
        }
      }
      browser = null;
      page = null;
    },
  };
}

