import { AgentStatus as AS, type TaskNode, type NodeResult, type AgentType, type MemoryQuery, type SafeErrorReporter, type MemoryEntry, type ReadMode, type Agent } from "@cortex/shared";
import type { LlmAdapter } from "@cortex/llm";
import type { Toolkit } from "@cortex/platform";
import type { MemoryStore } from "@cortex/memory-store";
import type { AgentPool, IStep } from "@cortex/scheduler";
import { executeWithMemoryPipeline, resolvePipeline } from "./memory/pipeline.js";
import { PoolAwareState } from "./components/pool-aware.js";
import { DEFAULT_ENGINE_CONFIG } from "@cortex/config";

/**
 * BaseAgent 鈥斺€?鎵€鏈?Agent 鐨勬娊璞″熀绫汇€俓r
 * 灏佽鐢熷懡鍛ㄦ湡銆佽蹇嗘绱笌鍐欏叆銆丷eAct 璋冨害銆俓r
 * 瀛愮被鍙渶瀹氫箟 type 鍜?systemPrompt銆俓r
 */
export abstract class BaseAgent implements Agent {
  abstract readonly type: AgentType;
  abstract readonly systemPrompt: string;

  // 鏂规B锛氱姸鎬佹墍鏈夋潈褰掍竴锛屽鎵樼粰 PoolAwareState 鍏变韩缁勪欢锛堟秷闄ゅ鍒剁矘璐达級
  // 浣跨敤 `() => this.type` 寤惰繜姹傚€硷紝閬垮厤 abstract property 鍒濆鍖栭『搴忛棶棰榎r
  protected readonly _state = new PoolAwareState(() => this.type);

  /** 鏂规B锛欰gent.status 鍙 getter 鈥斺€?濮旀墭鍒?PoolAwareState */
  get status(): AS {
    return this._state.status;
  }

  /** ReAct 寰幆涓婇檺銆傚瓙绫诲彲瑕嗗啓锛堝 InspectorAgent 鐢?24 浠ラ檷浣庡够瑙夐闄╋級銆?*/
  protected maxLoops = DEFAULT_ENGINE_CONFIG.defaultMaxLoops;

  /** SafeErrorReporter 鈥斺€?缁熶竴閿欒涓婃姤锛屾潨缁濋潤榛樺悶閿橽r
   *  娉ㄦ剰锛氫粎鐢ㄤ簬 executeWithMemoryPipeline 绛夐潪鐘舵€佹満鐨勫唴閮ㄩ敊璇笂鎶ャ€俓r
   *  鐘舵€佹満鐩稿叧閿欒鐢?PoolAwareState 鑷涓婃姤銆?*/
  protected _safeReporter: SafeErrorReporter | null = null;

  /** P0-鍏眰闃插尽锛氳璺緞 Intent 杩囨护鍥炶皟锛堢敱 bootstrap 灞傛敞鍏?ConsistencyLayer.filterRead锛?*/
  protected _filterRead?: (entries: MemoryEntry[], mode: ReadMode) => MemoryEntry[];

  constructor(
    protected readonly llm: LlmAdapter,
    protected readonly toolkit: Toolkit,
    protected readonly memory?: MemoryStore,
  ) {}

  /** 娉ㄥ叆 SafeErrorReporter锛堢敱 bootstrap 鍦ㄤ笂灞傜粺涓€娉ㄥ叆锛夈€傚弻璺緞锛氳嚜韬?+ PoolAwareState */
  setSafeReporter(reporter: SafeErrorReporter): void {
    this._safeReporter = reporter;
    this._state.setSafeReporter(reporter);
  }

  /** 娉ㄥ叆璇昏矾寰?Intent 杩囨护鍥炶皟锛圥0-鍏眰闃插尽锛?*/
  setFilterRead(fn: (entries: MemoryEntry[], mode: ReadMode) => MemoryEntry[]): void {
    this._filterRead = fn;
  }

  /** 娉ㄥ叆 AgentPool 寮曠敤锛堟柟妗圔锛氱姸鎬佹墍鏈夋潈褰掍竴锛?*/
  setPool(pool: AgentPool, instanceId: string): void {
    this._state.setPool(pool, instanceId);
  }

  /** 鏂规B锛氬唴閮ㄧ姸鎬佸彉鏇粹€斺€斿鎵樺埌 PoolAwareState.transition()
   *
   * 娌荤悊鍒や緥 NG-2026-0511-LocalStatus-Bypass锛歕r
   * 鏃?Pool 鐨勯檷绾ц矾寰勪粎鍏佽娴嬭瘯/璇婃柇鐜浣跨敤锛屼粛椤绘牎楠屾祦杞悎娉曟€с€俓r
   * 绂佹鐩存帴鍐欏叆 _localStatus 缁曡繃鐘舵€佹満銆?*/
  private _setStatus(status: AS): void {
    this._state.transition(status);
  }

  async wakeup(): Promise<void> {
    this._setStatus(AS.Awake);
  }

  /**
   * 鎵ц鍓嶉挬瀛愨€斺€斿瓙绫诲彲瑕嗗啓姝ゆ柟娉曟敞鍏ュ墠缃簨瀹為噰闆嗭紙濡?tsc 缂栬瘧缁撴灉銆亀orkspaceRoot 璺緞锛夈€俓r
   * 榛樿鍘熸牱杩斿洖 node銆俓r
   */
  protected preExecuteHook(node: TaskNode): TaskNode | Promise<TaskNode> {
    return node;
  }

  async execute(node: TaskNode, model: string): Promise<NodeResult> {
    this._setStatus(AS.Active);
    try {
      const enrichedNode = await this.preExecuteHook(node);
      const steps = this._selectPipeline(enrichedNode);
      const result = await executeWithMemoryPipeline(
        {
          agentType: this.type,
          llm: this.llm,
          toolkit: this.toolkit,
          systemPrompt: this.systemPrompt,
          maxLoops: this.maxLoops,
          reactLoopTimeoutMs: DEFAULT_ENGINE_CONFIG.reactLoopTimeoutMs,
          memory: this.memory,
        },
        enrichedNode,
        model,
        this.memory ? (n) => this.getMemoryQuery(n) : undefined,
        this._safeReporter ?? undefined,
        this._filterRead,
        steps,
      );
      return result;
    } finally {
      if (this.status === AS.Active) this._setStatus(AS.Awake);
    }
  }

  async shutdown(): Promise<void> {
    this._setStatus(AS.Draining);
    this._setStatus(AS.Destroyed);
  }

  // 鈹€鈹€ 绠￠亾绛栫暐閫夋嫨 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 鏍规嵁 TaskNode.preferredStrategy 瑙ｆ瀽瀵瑰簲鐨?Step 绠￠亾銆俓r
   * 瀛愮被鍙鍐欐鏂规硶瀹氬埗绛栫暐閫夋嫨閫昏緫銆俓r
   *
   * - "react"   鈫?榛樿 [MemoryRetrieval, ReActLoop, MemoryWrite]
   * - "direct"  鈫?[DirectStep, MemoryWrite]  璺宠繃璁板繂妫€绱㈠拰 ReAct
   * - undefined  鈫?鍥為€€榛樿
   * - "decompose" / "jury" 鈫?鏈潵鎵╁睍
   */
  protected _selectPipeline(node: TaskNode): IStep[] | undefined {
    return resolvePipeline(node.preferredStrategy);
  }

  /**
   * 璁板繂妫€绱㈢瓥鐣ユā鏉挎柟娉曘€俓r
   * 瀛愮被瑕嗙洊姝ゆ柟娉曞畾涔夊悇鑷殑"鍥炲璺緞"锛歕r
   * - CodeAgent: 浼樺厛 PRODUCED_BY + REFACTORED_FROM锛堝伐鍦版棩璁帮級
   * - ReviewAgent: 浼樺厛 CITED_IN_COMMITTEE + REFACTORED_FROM锛堝鏌ユ。妗堬級
   * - DocGovernAgent: 浼樺厛 DEPENDS_ON + 鍚?Archived 鎬侊紙瀹¤杩芥函锛塡r
   * - AnalysisAgent: 浼樺厛 DERIVED_FROM锛堢煡璇嗚氨绯伙級
   */
  // 鏀逛负 public 浠ユ弧瓒?Agent 鎺ュ彛濂戠害锛圡emoryAware.getMemoryQuery 涓?public锛塡r
  getMemoryQuery(node: TaskNode): MemoryQuery {
    const payload = node.payload;
    const keywords: string[] = [];

    // 1. 涓枃鍏抽敭璇嶏細鎻愬彇 CJK 瀛楃搴忓垪锛岀敤 2-gram 婊戝姩绐楀彛鍒嗚瘝
    const cjkChars = payload.replace(/[^涓€-榭裤悁-涠縘/g, "");
    for (let i = 0; i <= cjkChars.length - 2; i++) {
      keywords.push(cjkChars.slice(i, i + 2));
    }

    // 2. 鎷変竵/鑻辨枃鍏抽敭璇嶏細鐜版湁 split(\s+) 閫昏緫锛屼繚鐣欏悜鍚庡吋瀹筡r
    const latinWords = payload.split(/\s+/).filter((w) => w.length > 3);
    keywords.push(...latinWords);

    return {
      keywords,
      kind: "TaskLog" as const,
      limit: 5,
    };
  }

}

// ============================================================
// @cortex/engine 鈥?bootstrapEngine() 闆嗘垚鍏ュ彛锛坴3.0 鎻掍欢鍖栵級
//
// 鍘?v2.x 鐨勭‖缂栫爜瑁呴厤娴佹按绾匡紙createEngineCore / createSpecialAgents /
// createScheduler / initMemoryStore / initConsistencyLayer /
// registerAgents / initSkillSystem锛夊凡閫€鍖栦负 PluginLoader.load()銆俓r
//
// 娴佹按绾匡紙绠€鍖栵級锛歕r
//   loadConfig 鈫?configAndInject 鈫?PluginLoader.load(plugins) 鈫?assemble
//
// @refactor v3.0 鈥?寮曟搸鎻掍欢鍖栬В鑰r
// ============================================================

import type { AgentDefinition } from "@cortex/factory";
import { loadConfig, resolveCodingStandards, resolveLlm, injectRegistryFromConfig } from "./load-config.js";
import { StrategistAgent } from "../agents/strategist-agent.js";
import { ButlerAgent } from "../agents/butler-agent.js";
// 鍓綔鐢ㄥ鍏ワ細瑙﹀彂鍏ㄩ儴鎻掍欢鑷敞鍐岃嚦 PluginLoader锛堟棤闇€璋冪敤浠讳綍鍑芥暟锛塡r
import "../plugin/register-all.js";
import { PluginLoader, type EnginePluginLoadConfig } from "../plugin/plugin-loader.js";
import type { Toolkit } from "@cortex/platform";
import { preloadModel } from "@cortex/memory-store";
import type { LlmAdapter } from "@cortex/llm";
import { PipelineEventType, PipelinePriority, type IFileSystemAdapter, type IMemoryStore, type MemoryEntry, type ReadMode } from "@cortex/shared";
import { resolveConfigDataDir, type EngineConfig } from "@cortex/config";
import { readFileSync } from "node:fs";
import { initSkillSystem } from "./init-skills.js";
import { LifecycleManager } from "../lifecycle/lifecycle-manager.js";
import { installConsoleBridge, uninstallConsoleBridge } from "../observer/console-bridge.js";

// 鎻掍欢绫诲瀷寮曠敤
import type { PipelineObserverPlugin } from "../plugin/pipeline-observer.plugin.js";
import type { TaskBoardPlugin } from "../plugin/task-board.plugin.js";
import type { AgentPoolPlugin } from "../plugin/agent-pool.plugin.js";
import type { ConfirmGatePlugin } from "../plugin/confirm-gate.plugin.js";
import type { TrustModelPlugin } from "../plugin/trust-model.plugin.js";
import type { MemoryStorePlugin } from "../plugin/memory-store.plugin.js";
import type { ConsistencyLayerPlugin } from "../plugin/consistency-layer.plugin.js";
import type { MetaAgentPlugin } from "../plugin/meta-agent.plugin.js";
import type { SchedulerPlugin } from "../plugin/scheduler.plugin.js";

// 閲嶅鍑哄閮ㄤ緷璧栫殑绫诲瀷
import type { BootstrapEngineResult } from "./assemble.js";

export type { BootstrapEngineResult };

export interface BootstrapEngineOptions {
  llms: Map<string, LlmAdapter>;
  toolkit: Toolkit;
  memory?: IMemoryStore;
  dbPath?: string;
  engineConfig?: EngineConfig;
  workspaceRoot?: string;
  filterRead?: (entries: MemoryEntry[], mode: ReadMode) => MemoryEntry[];
  fs?: IFileSystemAdapter;
}

export { resolveLlm };

/**
 * bootstrapEngine 鈥斺€?浠庨厤缃枃浠跺埌杩愯鏃跺紩鎿庣殑瀹屾暣鍚姩娴佹按绾匡紙v3.0 鎻掍欢鍖栵級銆俓r
 *
 * 涓嶅啀纭紪鐮佽閰嶉『搴忥紝鑰屾槸锛歕r
 *   1. 鍔犺浇宸ュ巶閰嶇疆锛圓gent 瀹氫箟绛夛級
 *   2. 娉ㄥ唽鍏ㄩ儴鎻掍欢鍒?PluginLoader
 *   3. PluginLoader.load() 鎸夋嫇鎵戞帓搴忓姞杞?鈫?init 鈫?postInit 鈫?start
 *   4. 鍙栧嚭鍚勬彃浠跺疄渚嬬粍瑁?BootstrapEngineResult
 */
export async function bootstrapEngine(
  projectRoot: string,
  options: BootstrapEngineOptions,
): Promise<BootstrapEngineResult> {
  // 搂1 鍔犺浇閰嶇疆
  const config = loadConfig(projectRoot);

  // 搂1.5 璁剧疆 Toolkit 鐨?workspaceRoot锛堣矾寰勬矙绠憋級
  const wsRoot = options.workspaceRoot ?? projectRoot;
  options.toolkit.setWorkspaceRoot(wsRoot);

  // 搂2 娉ㄥ叆杩愯鏃舵敞鍐岃〃 + 宸ュ叿鍏冩暟鎹甛r
  injectRegistryFromConfig(config.agentDefinitions);
  const codingStandards = resolveCodingStandards(projectRoot);

  // 搂3 宸茬敱 plugin/register-all.js 鍓綔鐢ㄥ鍏ュ畬鎴愬叏閮ㄦ彃浠舵敞鍐孿r

  // 搂4 浠?engine-plugins.json 璇诲彇鎻掍欢娓呭崟锛堥厤缃┍鍔紝涓嶅啀纭紪鐮侊級
  const pluginsDataDir = resolveConfigDataDir();
  let pluginsJson: { plugins: string[] };
  try {
    pluginsJson = JSON.parse(readFileSync(`${pluginsDataDir}/engine-plugins.json`, "utf-8")) as { plugins: string[] };
  } catch (e) {
    throw new Error(
      `[bootstrapEngine] 鏃犳硶鍔犺浇寮曟搸鎻掍欢娓呭崟 ${pluginsDataDir}/engine-plugins.json: ` +
      (e instanceof Error ? e.message : String(e)),
      { cause: e },
    );
  }
  const pluginConfig: EnginePluginLoadConfig = {
    plugins: pluginsJson.plugins,
    engineConfig: options.engineConfig,
    workspaceRoot: wsRoot,
    externals: {
      llms: options.llms,
      toolkit: options.toolkit,
      codingStandards,
      factoryConfig: config,
      dbPath: options.dbPath,
      fs: options.fs,
      memory: options.memory,
    },
  };

  // 搂5 鍔犺浇骞跺惎鍔ㄥ叏閮ㄦ彃浠禱r
  const loader = new PluginLoader();
  const container = await loader.load(pluginConfig);

  // 搂6 浠庢彃浠跺鍣ㄤ腑鍙栧嚭缁勪欢
  const observer = container.get<PipelineObserverPlugin>("pipelineObserver").getInstance();
  const board = container.get<TaskBoardPlugin>("taskBoard").getInstance();
  const pool = container.get<AgentPoolPlugin>("agentPool").getInstance();
  const gate = container.get<ConfirmGatePlugin>("confirmGate").getInstance();
  const cliAdapter = container.get<ConfirmGatePlugin>("confirmGate").getCliAdapter();
  // 淇′换妯″瀷鍙€夋敞鍏モ€斺€斾笉鍦ㄦ彃浠舵竻鍗曚腑鏃堕潤榛樿烦杩嘰r
  if (container.has("trustModel")) {
    const trustModel = container.get<TrustModelPlugin>("trustModel").getInstance();
    gate.setTrustModel(trustModel);
  }
  const memory = container.get<MemoryStorePlugin>("memoryStore").getInstance();
  const consistencyLayer = container.get<ConsistencyLayerPlugin>("consistencyLayer").getInstance();
  const metaAgent = container.get<MetaAgentPlugin>("metaAgent").getInstance();
  const scheduler = container.get<SchedulerPlugin>("scheduler").getInstance();
  const agents = container.get<SchedulerPlugin>("scheduler").getAgents();
  const butler = container.get<SchedulerPlugin>("scheduler").getButler();

  // 搂6.0 ConsoleBridge 鈥斺€?PipelineObserver 灏辩华鍚庡畨瑁咃紝鎷︽埅瑁?console
  installConsoleBridge(observer);

  // 搂6.0.1 LifecycleManager 鈥斺€?绠＄悊闈炴彃浠?ILifecycle 缁勪欢鐨勭敓鍛藉懆鏈焅r
  const lifecycleManager = new LifecycleManager();
  // 鐩戝惉鐢熷懡鍛ㄦ湡浜嬩欢 鈫?PipelineObserver
  lifecycleManager.on((event, detail) => {
    if (event === "component_error") {
      observer.emit({
        type: PipelineEventType.InfraComponentDegraded,
        priority: PipelinePriority.HIGH,
        payload: {
          component: detail.component ?? "unknown",
          operation: "lifecycle",
          detail: detail.error ?? "鏈煡閿欒",
        },
        timestamp: Date.now(),
        notificationType: "WARNING",
      });
    }
  });

  // 搂6.1 鎶€鑳界郴缁熷垵濮嬪寲鈥斺€斾笉鍐嶉€氳繃鎻掍欢锛岀洿鎺ュ湪 bootstrap 涓閰峔r
  const skillRegistry = await initSkillSystem(
    observer,
    memory,
    metaAgent,
    projectRoot,
  );

  // 搂7 鍒涘缓 StrategistAgent锛堥挓绂?+ 闇滃嚌鈥斺€擟ore-2 棰勭暀锛塡r
  const strategistDefs = config.agentDefinitions.filter((d: AgentDefinition) => d.type === "strategist");
  const strategists = new Map<string, StrategistAgent>();
  for (const def of strategistDefs) {
    const agent = new StrategistAgent(
      resolveLlm(options.llms, def.key),
      codingStandards ? def.systemPrompt?.replace(/%%CODING_STANDARDS%%/g, codingStandards) ?? "" : def.systemPrompt ?? "",
    );
    await agent.wakeup();
    strategists.set(def.id, agent);
  }

  // 搂8 纭闂ㄦ帴绾库€斺€擳oolkit 闇€瑕?ConfirmGate
  options.toolkit.setGate(gate);

  // 搂9 ONNX 妯″瀷棰勭儹锛坒ire-and-forget锛塡r
  preloadModel().catch((err) => {
    observer.emit({
      type: PipelineEventType.MemoryEmbeddingWarmupFailed,
      priority: PipelinePriority.HIGH,
      payload: { error: String(err instanceof Error ? err.message : err) },
      timestamp: Date.now(),
      notificationType: "WARNING",
    });
  });

  // 搂10 缁勮杩斿洖
  return {
    scheduler,
    pool,
    observer,
    board,
    gate,
    cliAdapter,
    memory,
    metaAgent,
    butler: butler ?? new ButlerAgent(observer),
    strategists,
    skillRegistry,
    config,
    agents,
    consistencyLayer,
    lifecycleManager,
    shutdown: async () => {
      // 鍏堜紭闆呭叧闂?ILifecycle 缁勪欢
      await lifecycleManager.shutdown();
      // 鍐嶅叧闂彃浠跺鍣紙鍙嶅悜椤哄簭 stop 鍚勬彃浠讹級
      await container.shutdown();
      // 鏈€鍚庡嵏杞?ConsoleBridge锛屾仮澶嶅師濮?console
      uninstallConsoleBridge();
    },
  };
}

