// ============================================================
// @cortex/engine/bootstrap/init-skills 鈥斺€?鎶€鑳界郴缁熷垵濮嬪寲
//
// @since v2.6 鈥?閲嶆瀯锛氭妧鑳藉嵆璁板繂锛孲killExecutor 宸茬Щ闄ゃ€俓r
//   Agent 鑷富鎷夊彇鎶€鑳藉弬鐓э紝涓嶉€氳繃寮哄埗娉ㄥ叆銆俓r
// ============================================================
/* eslint-disable no-console */

import { SkillRegistry, deriveStatus } from "../registry/skill-registry.js";
import { registerSkillPipeline } from "../memory/skill-pipeline.js";
import { crystallizeSkillToKnowledge, loadSkillsFromMemory, persistSkillsToMemory, verifySkillKnowledge, type ExternalSearcher } from "../components/skill-persister.js";
import type { MemoryStore } from "@cortex/memory-store";
import { type IMemoryStore, type IPipelineObserver, type SkillTemplate } from "@cortex/shared";
import type { MetaAgent } from "../core/meta-agent.js";

export async function initSkillSystem(
  observer: IPipelineObserver,
  memory: IMemoryStore | undefined,
  metaAgent: MetaAgent,
  projectRoot: string,
  externalSearch?: ExternalSearcher,
): Promise<SkillRegistry> {
  const skillRegistry = new SkillRegistry();
  const onSkillStatusChange = async (skill: SkillTemplate, oldStatus: string) => {
    if (memory) {
      try {
        persistSkillsToMemory([skill], memory as MemoryStore);
      } catch (e) {
        console.warn(
          `[bootstrapEngine] 鎶€鑳界姸鎬佸彉鏇存寔涔呭寲澶辫触 (MemoryStore): ${skill.id}`,
          e instanceof Error ? e.message : String(e),
        );
      }

      // 缁撴櫠涓虹煡璇嗭細trial 鈫?active 鏃讹紝鍏堜簨瀹炶璇佸啀鍐欏叆 MemoryKind.Knowledge锛堝箓绛夋洿鏂帮級
      const currentStatus = deriveStatus(skill.weight, skill.feedbackHistory);
      if (currentStatus === "active" && oldStatus !== "active") {
        try {
          const vr = externalSearch
            ? await verifySkillKnowledge(skill, memory as MemoryStore, "analysis-agent", { externalSearch })
            : await verifySkillKnowledge(skill, memory as MemoryStore, "analysis-agent");
          console.log(`[bootstrapEngine] 鐭ヨ瘑楠岃瘉: ${skill.name} verified=${vr.verified}`);
          if (vr.externalResults && vr.externalResults.length > 0) {
            console.log(`[bootstrapEngine] 澶栭儴浣愯瘉: ${vr.externalResults.length} 鏉?web_search 缁撴灉`);
          }

          const result = await crystallizeSkillToKnowledge(skill, memory as MemoryStore, {
            verifiedBy: vr.verified ? "analysis-agent" : undefined,
            evidenceIds: vr.evidenceIds,
          });
          if (result) {
            const tag = result.isUpdate ? "鏇存柊(v" + result.version + ")" : "鏂板缓";
            console.log(`[bootstrapEngine] 鎶€鑳界粨鏅朵负鐭ヨ瘑: ${skill.name} ${tag} verified=${result.verified}`);
          }
        } catch (e) {
          console.warn(
            `[bootstrapEngine] 鎶€鑳界粨鏅朵负鐭ヨ瘑澶辫触: ${skill.id}`,
            e instanceof Error ? e.message : String(e),
          );
        }
      }
    }
    console.log(`[bootstrapEngine] 鎶€鑳界姸鎬佸彉鏇? ${skill.name}(${skill.id}) ${oldStatus} 鈫?${deriveStatus(skill.weight, skill.feedbackHistory)}`);
  };

  // 灏?onSkillStatusChange 鎸傚埌 registry 涓婏紙渚?recordFeedback 绛夎皟鐢級
  (skillRegistry as unknown as { _onStatusChange: typeof onSkillStatusChange })._onStatusChange = onSkillStatusChange;

  metaAgent.setSkillRegistry(skillRegistry);
  registerSkillPipeline(observer, skillRegistry, memory);

  // 浠?MemoryStore 鎭㈠宸叉寔涔呭寲鐨勬妧鑳芥ā鏉縗r
  if (memory) {
    try {
      const loadedSkills = await loadSkillsFromMemory(memory as MemoryStore);
      if (loadedSkills.length > 0) {
        skillRegistry.registerAll(loadedSkills);
        console.log(
          `[bootstrapEngine] 浠庤蹇嗗簱鎭㈠ ${loadedSkills.length} 涓妧鑳芥ā鏉? ` +
          loadedSkills.map((s) => `${s.name}(${s.id})`).join(", "),
        );
      }
    } catch (e) {
      console.warn("[bootstrapEngine] 浠庤蹇嗗簱鍔犺浇鎶€鑳藉け璐ワ紙闈炶嚧鍛斤級:", e);
    }
  }

  return skillRegistry;
}

// ============================================================
// @cortex/engine/bootstrap/register-agents 鈥斺€?Agent 娉ㄥ唽
// ============================================================

import { type Agent, type AgentConfig, type AgentType, type IFileSystemAdapter, type IMemoryStore, type IPipelineObserver, type MemoryEntry, type ReadMode } from "@cortex/shared";
import type { Scheduler } from "../core/scheduler.js";
import type { AgentPool } from "@cortex/scheduler";
import type { MemoryStore } from "@cortex/memory-store";
import type { Toolkit } from "@cortex/platform";
import type { BootstrapResult } from "@cortex/factory";
import type { LlmAdapter } from "@cortex/llm";
import type { EngineConfig } from "@cortex/config";
import { createAgent, type AgentFactoryConfig } from "../components/agent-factory.js";
import { createInspectorAgent } from "../agents/inspector-agent.js";
import { createBrowserAgent } from "../agents/browser-agent.js";
import { ButlerAgent } from "../agents/butler-agent.js";
import { resolveLlm, injectStandards, MEMORY_QUERY_REGISTRY } from "./load-config.js";

export async function registerAgents(
  config: BootstrapResult,
  options: {
    llms: Map<string, LlmAdapter>;
    toolkit: Toolkit;
    scheduler: Scheduler;
    pool: AgentPool;
    memory: IMemoryStore | undefined;
    codingStandards: string;
    workspaceRoot?: string;
    filterRead?: (entries: MemoryEntry[], mode: ReadMode) => MemoryEntry[];
    engineConfig?: EngineConfig;
    fs?: IFileSystemAdapter;
    observer?: IPipelineObserver;
  },
): Promise<Map<string, Agent>> {
  const agents = new Map<string, Agent>();

  for (const def of config.agentDefinitions) {
    const agentType = def.type;

    // 璺宠繃涓嶅弬涓庤皟搴︾殑鐗规畩 Agent
    if (agentType === "meta") {
      continue;
    }

    let agent: Agent | undefined;

    switch (agentType) {
      case "inspector": {
        const inspAgent = createInspectorAgent(
          resolveLlm(options.llms, def.key),
          options.toolkit,
          options.memory as MemoryStore,
          options.engineConfig,
          injectStandards(def.systemPrompt, options.codingStandards),
          options.filterRead,
        );
        if (options.workspaceRoot) inspAgent.setWorkspaceRoot(options.workspaceRoot);
        agent = inspAgent;
        break;
      }

      case "browser": {
        const brwAgent = createBrowserAgent(
          resolveLlm(options.llms, def.key),
          options.toolkit,
          options.memory as MemoryStore,
          injectStandards(def.systemPrompt, options.codingStandards),
          options.filterRead,
        );
        if (options.workspaceRoot) brwAgent.setWorkspaceRoot(options.workspaceRoot);
        agent = brwAgent;
        break;
      }

      case "butler": {
        if (!options.observer) break;
        const butler = new ButlerAgent(options.observer);
        // Butler 涓嶈皟鐢?LLM銆佷笉浣跨敤 toolkit锛屼粎鏃佸惉绠＄嚎浜嬩欢
        await butler.wakeup();
        agent = butler as unknown as Agent;
        break;
      }

      default: {
        const strategy = def.memoryQueryStrategy ?? agentType;
        const memoryQuery = MEMORY_QUERY_REGISTRY.get(strategy);
        const factoryConfig: AgentFactoryConfig = {
          type: agentType as AgentType,
          systemPrompt: injectStandards(def.systemPrompt, options.codingStandards),
          memoryEnabled: options.memory != null,
          getMemoryQuery: memoryQuery,
          filterRead: options.filterRead,
        };
        agent = createAgent(factoryConfig, resolveLlm(options.llms, def.key), options.toolkit, options.memory as MemoryStore);
      }
    }

    if (agent) {
      options.scheduler.register(agentType, agent, def.model);
      options.pool.register({
        type: agentType as AgentType,
        maxInstances: def.maxInstances ?? 1,
      } as AgentConfig);
      agents.set(agentType, agent);
    }
  }

  return agents;
}

import {
  AgentStatus as AS,
  type Agent,
  type TaskNode,
  type NodeResult,
  type AgentType,
  type MemoryQuery,
  type SafeErrorReporter,
  type AgentStatus,
  type MemoryEntry,
  type ReadMode,
} from "@cortex/shared";
import type { LlmAdapter } from "@cortex/llm";
import type { Toolkit } from "@cortex/platform";
import type { MemoryStore } from "@cortex/memory-store";
import type { AgentPool } from "@cortex/scheduler";
import { PoolAwareState } from "./pool-aware.js";
import { type ReActContext } from "./react-loop.js";
import { executeWithMemoryPipeline, resolvePipeline } from "../memory/pipeline.js";
import { DEFAULT_ENGINE_CONFIG } from "@cortex/config";

/**
 * Agent 宸ュ巶閰嶇疆鈥斺€旂粍鍚堝紡鏇夸唬 BaseAgent 缁ф壙銆俓r
 *
 * 涓?abstract class 涓嶅悓锛屾閰嶇疆鏄函鏁版嵁锛歕r
 *   - 涓嶈姹傚瓙绫昏鍐欐柟娉昞r
 *   - 涓嶄緷璧?this 闅愬紡鑰﹀悎
 *   - 姣忎釜瀛楁閮芥槸鏄惧紡澹版槑
 */
export interface AgentFactoryConfig {
  /** Agent 绫诲瀷 */
  type: AgentType;
  /** 绯荤粺鎻愮ず璇?*/
  systemPrompt: string;
  /** ReAct 寰幆涓婇檺銆傞粯璁?64 */
  maxLoops?: number;
  /** 鏄惁闇€瑕佽蹇嗘敮鎸?*/
  memoryEnabled?: boolean;
  /** 鑷畾涔夎蹇嗘绱㈢瓥鐣ャ€備笉鎻愪緵鍒欑敤 CJK bigram 榛樿绛栫暐 */
  getMemoryQuery?: (node: TaskNode) => MemoryQuery;
  /** 鎵ц鍓嶉挬瀛愨€斺€斿 InspectorAgent 鐨?tsc 缂栬瘧浜嬪疄閲囬泦 */
  preExecuteHook?: (node: TaskNode) => TaskNode | Promise<TaskNode>;
  /** 璁板繂 BFS 娣卞害瑕嗗啓鈥斺€斾笉鎻愪緵鍒欑敱 getMemoryQuery 鍐冲畾 */
  memoryBfsDepth?: number;
  /** 璁板繂妫€绱㈡潯鏁拌鍐欌€斺€斾笉鎻愪緵鍒欑敱 getMemoryQuery 鍐冲畾 */
  memoryLimit?: number;
  /** P0-鍏眰闃插尽锛氳璺緞 Intent 杩囨护鍥炶皟 */
  filterRead?: (entries: MemoryEntry[], mode: ReadMode) => MemoryEntry[];
}

/**
 * 鍒涘缓 Agent 瀹炰緥鈥斺€旂粍鍚堝伐鍘傘€俓r
 *
 * 鏇夸唬 `abstract class BaseAgent` 鐨勭户鎵挎ā寮忋€俓r
 * 姣忎釜 Agent 绫诲瀷璋冪敤姝ゅ伐鍘傦紝浼犲叆閰嶇疆鍗冲彲浜у嚭绗﹀悎 Agent 鎺ュ彛鐨勫璞°€俓r
 *
 * 鍐呴儴缁勪欢锛歕r
 *   - PoolAwareState锛堢姸鎬佺鐞嗭紝鏂规B 褰掍竴锛塡r
 *   - ReActContext锛圠LM + Toolkit + MemoryStore 渚濊禆娉ㄥ叆锛塡r
 *   - executeWithMemoryPipeline锛堣蹇嗘绱?鈫?鎵ц 鈫?璁板繂鍐欏叆锛塡r
 *
 * @param config Agent 宸ュ巶閰嶇疆
 * @param llm LLM 閫傞厤鍣╘r
 * @param toolkit 宸ュ叿绠盶r
 * @param memory 璁板繂瀛樺偍锛堝彲閫夛紝memoryEnabled 涓?true 鏃跺繀闇€锛塡r
 */
export function createAgent(
  config: AgentFactoryConfig,
  llm: LlmAdapter,
  toolkit: Toolkit,
  memory?: MemoryStore,
): Agent & {
  setPool(pool: AgentPool, instanceId: string): void;
  setSafeReporter(reporter: SafeErrorReporter): void;
} {
  const maxLoops = config.maxLoops ?? DEFAULT_ENGINE_CONFIG.defaultMaxLoops;
  const state = new PoolAwareState(config.type);
  let safeReporter: SafeErrorReporter | null = null;

  // 鈹€鈹€ ReAct 涓婁笅鏂囷紙execution 鏃舵瀯寤哄畬鏁?ctx锛?鈹€鈹€
  const buildCtx = (): ReActContext => ({
    agentType: config.type,
    llm,
    toolkit,
    systemPrompt: config.systemPrompt,
    maxLoops,
    reactLoopTimeoutMs: DEFAULT_ENGINE_CONFIG.reactLoopTimeoutMs,
    memory,
    safeReporter: safeReporter ?? undefined,
  });

  const agent = {
    type: config.type,

    get status(): AgentStatus {
      return state.status;
    },

    async wakeup(): Promise<void> {
      state.transition(AS.Awake);
    },

    async execute(node: TaskNode, model: string): Promise<NodeResult> {
      // @fix N3 (enhancement-review) 鈥?transition(Active) 澶辫触鏃舵嫆缁濇墽琛岋紝
      // 闃叉姹犻厤棰濊€楀敖鍚?Agent 浠嶇粫杩囬檺鍒舵墽琛屼换鍔°€俓r
      if (!state.transition(AS.Active)) {
        return {
          nodeId: node.id,
          success: false,
          output: `[${config.type}] 鐘舵€佽浆鎹㈡嫆缁? 鏃犳硶杩涘叆 Active锛堟睜閰嶉鑰楀敖鎴栭潪娉曠姸鎬侊級`,
          error: "AGENT_TRANSITION_DENIED",
        };
      }
      try {
        const enrichedNode = config.preExecuteHook
          ? await config.preExecuteHook(node)
          : node;

        const ctx = buildCtx();
        const steps = resolvePipeline(enrichedNode.preferredStrategy);
        const result = config.memoryEnabled && memory
          ? await executeWithMemoryPipeline(
              ctx, enrichedNode, model,
              config.getMemoryQuery,
              safeReporter ?? undefined,
              config.filterRead,
              steps,
            )
          : await executeWithMemoryPipeline(
              ctx, enrichedNode, model,
              undefined,
              safeReporter ?? undefined,
              config.filterRead,
              steps,
            );
        return result;
      } finally {
        if (state.status === AS.Active) {
          state.transition(AS.Awake);
        }
      }
    },

    async shutdown(): Promise<void> {
      state.transition(AS.Draining);
      state.transition(AS.Destroyed);
    },

    setPool(pool: AgentPool, instanceId: string): void {
      state.setPool(pool, instanceId);
    },

    setSafeReporter(reporter: SafeErrorReporter): void {
      safeReporter = reporter;
      state.setSafeReporter(reporter);
    },
  };

  return agent;
}

