  }

  /** @fix M7 鈥?tagProvider 鎶涘紓甯告椂閫氳繃 safeReporter 涓婃姤锛屼笉鍐嶅悶娌′负 "Agent"銆俓r
   * @fix FG-6 鈥?澧炲姞 try/catch fallback锛氬紓甯告椂 fallback 鍒?"Agent" 骞堕€氳繃 _safeReporter 涓婃姤锛孿r
   *   閬垮厤寮傚父鐩存帴浼犳挱鍒?transition() 鐨勬秷鎭瀯閫犲眰瀵艰嚧涓婃姤鏈韩涔熷け璐ャ€?*/
  private get _tag(): string {
    try {
      return this._tagProvider();
    } catch (e) {
      if (this._safeReporter) {
        this._safeReporter({
          source: "PoolAwareState._tag",
          error: new Error(`tagProvider 鎶涘紓甯? ${String(e).slice(0, 200)}`),
          severity: "degraded",
          hint: "fallback 鍒?'Agent'",
        });
      } else {
        console.warn(`[PoolAwareState._tag] tagProvider 鎶涘紓甯? ${String(e).slice(0, 200)}`);
      }
      return "Agent";
    }
  }

  /** 鏂规B锛歴tatus 鍙 getter 鈥斺€?Pool 鏈夊垯濮旀墭锛屽惁鍒欓檷绾у埌 _localStatus */
  get status(): AgentStatus {
