        const current = this._pool.getStatus(this._instanceId);
        if (current === undefined || current === AS.Destroyed) {
          // 瀹炰緥宸茬粓缁撯€斺€旇В闄?Pool 缁戝畾锛岄檷绾у埌鏈湴鐘舵€佹満缁х画鎵ц
          this._pool = null;
          this._instanceId = null;
