            this._safeReporter({
              source: `${this._tag}.PoolAwareState.transition`,
              error: new Error(`Pool 鎷掔粷娴佽浆 ${current} 鈫?${status}`),
              severity: "fatal",
              hint: `instanceId=${this._instanceId}`,
            });
