import type { LlmAdapter } from "@cortex/llm";
import type { Toolkit } from "@cortex/platform";
import type { MemoryStore } from "@cortex/memory-store";

/**
 * ReAct 寰幆涓婁笅鏂団€斺€旇В鑰?BaseAgent 缁ф壙閾俱€俓r
 * 鎵€鏈夋墽琛屽瀷 Agent 閫氳繃姝や笂涓嬫枃娉ㄥ叆渚濊禆锛屼笉鍐嶄緷璧?this.llm / this.toolkit 绛夐殣寮忚€﹀悎銆俓r
 */
export interface ReActContext {
  agentType: AgentType;
  llm: LlmAdapter;
  toolkit: Toolkit;
  systemPrompt: string;
  maxLoops: number;
  /** 鍗?Agent ReAct 寰幆澧欓挓瓒呮椂 (ms)銆傝秴鏃跺悗杩斿洖 partial output + error 淇℃伅锛屼笉浼氳璋冨害鍣ㄨ涓哄紓甯稿穿婧冦€?*/
  reactLoopTimeoutMs: number;
  memory?: MemoryStore;
  safeReporter?: SafeErrorReporter;
}

/**
 * 鍏变韩 ReAct 寰幆鈥斺€旀墍鏈?Agent 鍏辩敤銆俓r
 * 浠?react-helper.ts 鎻愬彇锛屽鍔?ReActContext 灏佽銆俓r
 *
 * @param ctx ReAct 涓婁笅鏂団€斺€擜gent 绫诲瀷 + 娉ㄥ叆渚濊禆
 * @param node 浠诲姟鑺傜偣
 * @param model LLM 妯″瀷鍚峔r
 */
export async function runReActLoop(
  ctx: ReActContext,
  node: TaskNode,
  model: string,
): Promise<NodeResult> {
  const { agentType, llm, toolkit, systemPrompt, maxLoops } = ctx;

  const toolDefs: ToolDef[] = toolkit.listDefinitions(agentType).map((d) => ({
    name: d.name,
    description: d.description,
    parameters: d.parameters ?? {
      type: "object",
      properties: {},
      required: [],
    },
  }));

  const TOOL_DISCIPLINE = [
    "鈹€鈹€鈹€鈹€ 鈿狅笍 宸ュ叿浣跨敤纭害鏉燂紙杩濆弽灏嗗鑷翠换鍔″け璐ワ級鈹€鈹€鈹€鈹€",
    "",
    "路 鏂囦欢鎼滅储 鈫?浼樺厛鐢?search_code銆傝嫢 search_code 杩斿洖閿欒锛岀珛鍗虫敼鐢?list_files + read_file銆傜姝㈢敤 run_shell 鎵ц grep/findstr/rg/dir",
    "路 鐩綍娴忚 鈫?蹇呴』鐢?list_files锛岀姝㈢敤 run_shell 鎵ц ls/dir/Get-ChildItem",
    "路 鏂囦欢璇诲彇 鈫?蹇呴』鐢?read_file锛岀姝㈢敤 run_shell 鎵ц cat/type/Get-Content",
    "路 鏂囦欢鍐欏叆 鈫?蹇呴』鐢?write_file锛岀姝㈢敤 run_shell 鎵ц echo/copy/Out-File",
    "路 run_shell 浠呯敤浜庢瀯寤?娴嬭瘯/鍖呯鐞嗗懡浠わ紙濡?pnpm build, npx vitest, npm install锛夛紝",
    "  缁濅笉鐢ㄤ簬鏂囦欢鎼滅储銆佺洰褰曟祻瑙堛€佹枃浠惰鍐欑瓑宸叉湁涓撶敤宸ュ叿鐨勬搷浣溿€俓

\n");

  const messages: LlmMessage[] = [
    { role: "system", content: systemPrompt },
    { role: "system", content: TOOL_DISCIPLINE },
    { role: "user", content: `Task: ${node.payload}` },
  ];

  let loops = 0;
  let finalOutput: string | undefined;
  const startTime = Date.now();
  const deadline = startTime + ctx.reactLoopTimeoutMs;

  const diagnostic = (msg: string): void => {
    console.log(`  馃攣 [ReAct-${agentType}#${loops}] ${msg}`);
  };

  diagnostic(`鍚姩鈥斺€攎axLoops=${maxLoops}, timeout=${ctx.reactLoopTimeoutMs}ms, tools=${toolDefs.length}涓猔);

  while (loops < maxLoops) {
    // 鈹€鈹€ 澧欓挓瓒呮椂妫€鏌?鈹€鈹€
    if (Date.now() >= deadline) {
      return {
        nodeId: node.id,
        agentType: agentType,
        success: false,
        output: finalOutput ?? `[partial output 鈥?wall-clock timeout at ${Date.now() - startTime}ms]`,
        error: `ReAct loop wall-clock timeout after ${ctx.reactLoopTimeoutMs}ms (iteration ${loops}/${maxLoops})`,
      };
    }

    loops++;

    try {
      if (loops === maxLoops - 4) {
        diagnostic("鎺ヨ繎寰幆涓婇檺锛屾敞鍏ユ埅姝㈡彁绀篭

user",
          content: "鈿狅笍 You have only 4 tool-call turns left. Start wrapping up and produce a final answer summarising what you have found or done so far. It's OK if the work is incomplete.",
        });
      }

      const msgCount = messages.length;
      diagnostic(`馃洶锔? 璋冪敤 LLM (${model})鈥斺€斾笂涓嬫枃 ${msgCount} 鏉℃秷鎭紝宸ュ叿 ${toolDefs.length} 涓?..`);
      const callStart = Date.now();
      const res = await llm.chat(model, messages, toolDefs, node.reasoningEffort);
      const callElapsed = Date.now() - callStart;

      // 鈹€鈹€ 鎬濈淮閾捐瘖鏂細鎵撳嵃鎺ㄧ悊鍐呭 鈹€鈹€
      if (res.reasoning_content) {
        const preview = res.reasoning_content.slice(0, 300);
        console.log(`  馃挱 [ReAct-${agentType}#${loops}] 鎬濈淮閾鹃瑙? ${preview}${res.reasoning_content.length > 300 ? "...(鎴柇)" : ""}`);
      }
      if (res.content) {
        const preview = res.content.slice(0, 200);
        console.log(`  馃摑 [ReAct-${agentType}#${loops}] 鏂囨湰鍝嶅簲: ${preview}${res.content.length > 200 ? "...(鎴柇)" : ""}`);
      }

      const toolCallCount = (res.tool_calls ?? []).length;
      diagnostic(`鉁?LLM 鍝嶅簲鑰楁椂 ${callElapsed}ms鈥斺€斿伐鍏疯皟鐢?${toolCallCount} 涓猔);

      if (toolCallCount === 0) {
        finalOutput = res.content ?? undefined;
        diagnostic(`馃洃 鏃犲伐鍏疯皟鐢紝鏈疆缁撴潫鈥斺€攐utput=${(finalOutput ?? "(绌?").slice(0, 100)}`);
        break;
      }

      messages.push({
        role: "assistant",
        content: res.content ?? "",
        tool_calls: res.tool_calls,
        reasoning_content: res.reasoning_content,
      });

      for (const tc of (res.tool_calls ?? [])) {
        diagnostic(`馃敡 鎵ц宸ュ叿 ${tc.name}`);
        const toolStart = Date.now();
        const result = await toolkit.execute(
          { toolName: tc.name, params: tc.arguments },
          agentType,
        );
        const toolElapsed = Date.now() - toolStart;
        const outcome = result.success ? `鉁?鎴愬姛 (${toolElapsed}ms)` : `鉂?澶辫触: ${(result.error ?? "鏈煡").slice(0, 100)}`;
        diagnostic(`馃敡 ${tc.name} 鈫?${outcome}`);

        messages.push({
          role: "tool",
          content: result.success
            ? (result.output ?? "success")
            : `ERROR: ${result.error}`,
          tool_call_id: tc.id,
        });
      }
    } catch (e) {
      diagnostic(`馃挜 宕╂簝: ${String(e).slice(0, 200)}`);
      return {
        nodeId: node.id,
        agentType: agentType,
        success: false,
        output: `[partial output before crash at iteration ${loops}/${maxLoops}]`,
        error: `[ReAct loop crashed at iteration ${loops}/${maxLoops}: ${String(e)}]`,
      };
    }
  }

  const totalElapsed = Date.now() - startTime;
  diagnostic(`馃弫 寰幆缁撴潫鈥斺€旇€楁椂 ${totalElapsed}ms, loops=${loops}/${maxLoops}, success=${finalOutput !== undefined}`);

  return {
    nodeId: node.id,
    agentType: agentType,
    success: finalOutput !== undefined,
    output: finalOutput,
    error: finalOutput === undefined ? "Exceeded max loops without final answer" : undefined,
  };
}

