/**
 * 浠?LoopAgent 鐨?LLM 杈撳嚭涓彁鍙?SkillTemplate JSON銆俓r
 *
 * 鏀寔涓ょ杈撳嚭鏍煎紡锛歕r
 *   1. 鍗曚釜 SkillTemplate JSON 瀵硅薄
 *   2. SkillTemplate JSON 鏁扮粍
 *
 * 鎻愬彇绛栫暐锛歕r
 *   1. 浼樺厛鍖归厤 ```json ... ``` 鍥存爮
 *   2. 鍥為€€鍒版渶澶栧眰骞宠　 { } 鎴?[ ] 缁撴瀯
 *   3. 楠岃瘉蹇呴渶瀛楁瀹屾暣鎬r
 *   4. 涓虹己澶卞瓧娈靛～鍏呭畨鍏ㄩ粯璁ゅ€糪r
 */
export function extractSkillsFromOutput(raw: string): SkillExtractResult {
  const diagnostics: string[] = [];
  const skills: SkillTemplate[] = [];

  if (!raw || raw.trim().length === 0) {
    diagnostics.push("绌鸿緭鍑猴紝鏃犳妧鑳藉彲鎻愬彇");
    return { skills, diagnostics };
  }

  // 姝ラ1锛氭彁鍙?JSON 鏂囨湰
  const jsonStr = extractJson(raw);
  if (!jsonStr) {
    diagnostics.push(`鏃犳硶浠?${raw.length} 瀛楃鐨勮緭鍑轰腑鎻愬彇 JSON`);
    return { skills, diagnostics };
  }

  // 姝ラ2锛氳В鏋?JSON
  let parsed: unknown;
  try {
    parsed = JSON.parse(jsonStr);
  } catch (e) {
    diagnostics.push(`JSON 瑙ｆ瀽澶辫触: ${String(e).slice(0, 200)}`);
    return { skills, diagnostics };
  }

  // 姝ラ3锛氳鑼冨寲鏁扮粍
  const items = Array.isArray(parsed) ? parsed : [parsed];

  // 姝ラ4锛氶獙璇?+ 濉厖
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (typeof item !== "object" || item === null) {
      diagnostics.push(`鏉＄洰[${i}]涓嶆槸瀵硅薄锛岃烦杩嘸);
      continue;
    }

    const result = normalizeSkillTemplate(item as Record<string, unknown>, diagnostics);
    if (result) {
      skills.push(result);
    } else {
      diagnostics.push(`鏉＄洰[${i}]楠岃瘉澶辫触锛岃烦杩嘸);
    }
  }

  return { skills, diagnostics };
}

/**
 * 瑙勮寖鍖栵細楠岃瘉瀛楁瀹屾暣鎬?+ 濉厖瀹夊叏榛樿鍊笺€俓r
 * 杩斿洖 null 琛ㄧず瀹屽叏鏃犳晥锛堣繛鏍稿績瀛楁閮芥病鏈夛級銆俓r
 */
function normalizeSkillTemplate(
  raw: Record<string, unknown>,
  diagnostics: string[],
): SkillTemplate | null {
  // 蹇呴渶锛歩d
  let id = typeof raw.id === "string" ? raw.id : "";
  if (!id) {
    // 鏃?id 鑷姩鐢熸垚
    id = `skill-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    diagnostics.push(`缂哄皯 id锛岃嚜鍔ㄧ敓鎴? ${id}`);
  }

  // 蹇呴渶锛歯ame锛堣嚦灏戣鏈夋弿杩版€ф爣棰橈級
  const name = typeof raw.name === "string" ? raw.name : "";
  if (!name) {
    diagnostics.push(`鎶€鑳?${id} 缂哄皯 name锛岃烦杩嘸);
    return null;
  }

  // 蹇呴渶锛歬ind
  const kind = normalizeSkillKind(raw.kind ?? raw.agentType, diagnostics, id);

  // 蹇呴渶锛歵riggerTags
  const triggerTags = normalizeTriggerTags(raw.triggerTags ?? raw.trigger_tags, diagnostics, id);

  // 蹇呴渶锛歵rigger
  const trigger = typeof raw.trigger === "string" ? raw.trigger : "";

  // 蹇呴渶锛歴teps
  const steps = normalizeSteps(raw.steps ?? raw.steps_json, id);
  if (steps.length === 0) {
    diagnostics.push(`鎶€鑳?${id} 缂哄皯 steps锛岃烦杩嘸);
    return null;
  }

  // 鍙€夛細expectedOutput
  const expectedOutput = typeof raw.expectedOutput === "string" || typeof raw.expected_output === "string"
    ? (raw.expectedOutput ?? raw.expected_output) as string
    : "";

  // 鍙€夛細outputFile锛堣В鏋愭ā鏉垮彉閲?{date}/{time}锛塡r
  const rawOutputFile = typeof raw.outputFile === "string" || typeof raw.output_file === "string"
    ? (raw.outputFile ?? raw.output_file) as string
    : undefined;
  const outputFile = rawOutputFile ? resolveOutputFile(rawOutputFile) : undefined;

  // 鐘舵€侊細榛樿涓?trial锛堥渶楠岃瘉鍚庡崌绾т负 active锛塡r
  const status = normalizeStatus(raw.status, diagnostics, id);

  return {
    id,
    kind,
    name,
    triggerTags,
    trigger,
    steps,
    expectedOutput,
    outputFile,
    status,
    weight: typeof raw.weight === "number" ? raw.weight : (typeof raw.adoptionCount === "number" ? raw.adoptionCount : 0),
    feedbackHistory: Array.isArray(raw.feedbackHistory) ? raw.feedbackHistory as FeedbackEntry[] : [],
    discoveredBy: typeof raw.discoveredBy === "string" ? raw.discoveredBy : "LoopAgent",
    createdAt: typeof raw.createdAt === "number" ? raw.createdAt : Date.now(),
  };
}

/** 浠?LLM 鍘熷杈撳嚭鎻愬彇 JSON 瀛愪覆 */
function extractJson(raw: string): string | null {
  // 浼樺厛 ```json ... ``` 鍥存爮
  const fenceMatch = raw.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
  if (fenceMatch) return fenceMatch[1].trim();

  // 鍥為€€锛氭渶澶栧眰 { } 鎴?[ ]
  const trimmed = raw.trim();
  const startChar = trimmed[0];
  const endChar = startChar === "{" ? "}" : startChar === "[" ? "]" : null;
  if (!endChar) {
    // 灏濊瘯鎵惧埌绗竴涓?{ 鎴?[
    const objStart = trimmed.indexOf("{");
    const arrStart = trimmed.indexOf("[");
    if (objStart === -1 && arrStart === -1) return null;
    const start = objStart === -1 ? arrStart :
      arrStart === -1 ? objStart :
      Math.min(objStart, arrStart);
    return extractBalanced(trimmed, start);
  }

  return extractBalanced(trimmed, 0);
}

/** 鎻愬彇浠?startIdx 寮€濮嬬殑骞宠　鎷彿鍐呭 */
function extractBalanced(text: string, startIdx: number): string | null {
  const stack: string[] = [];
  for (let i = startIdx; i < text.length; i++) {
    const ch = text[i];
    if (ch === "{" || ch === "[") {
      stack.push(ch === "{" ? "}" : "]");
    } else if (ch === "}" || ch === "]") {
      if (stack.length === 0) return null; // 涓嶅钩琛r
      const expected = stack.pop();
      if (expected === undefined) return null; // 涓嶅钩琛r
      if (stack.length === 0) {
        return text.slice(startIdx, i + 1);
      }
    }
  }
  return null; // 鏈棴鍚圽r
}

/** 瑙勮寖鍖?skillKind */
function normalizeSkillKind(
  raw: unknown,
  diagnostics: string[],
  skillId: string,
): SkillKind {
  if (typeof raw === "string") {
    const known: SkillKind[] = ["action", "thought", "workflow"];
    if (known.includes(raw as SkillKind)) return raw as SkillKind;

    // 瀹归敊锛氭棫鐗?agentType 鈫?kind 鏄犲皠
    const agentTypeAliasMap: Record<string, SkillKind> = {
      "cod": "action", "rev": "action",
      "analy": "thought", "op": "action",
      "loop": "workflow", "doc": "thought",
      "fix": "action", "ins": "action",
      "brow": "action", "api": "action",
      "data": "thought", "strat": "thought",
    };
    if (agentTypeAliasMap[raw]) return agentTypeAliasMap[raw];
  }
  diagnostics.push(`鎶€鑳?${skillId} kind 鏃犳晥锛岄粯璁?action`);
  return "action";
}

/** 瑙勮寖鍖?triggerTags */
function normalizeTriggerTags(
  raw: unknown,
  diagnostics: string[],
  skillId: string,
): Tag[] {
  if (!Array.isArray(raw)) {
    diagnostics.push(`鎶€鑳?${skillId} triggerTags 涓嶆槸鏁扮粍锛岃涓虹┖`);
    return [];
  }
  const vocabSet = new Set<string>(getTagVocabulary());
  const tags = raw
    .filter((t): t is string => typeof t === "string")
    .map((t) => {
      if (!vocabSet.has(t)) {
        diagnostics.push(`鎶€鑳?${skillId} 鐨勬爣绛?"${t}" 涓嶅湪棰勫畾涔夎瘝姹囪〃涓€斺€斾繚鐣欎负鑷畾涔夋爣绛撅紝璇风‘璁?MetaAgent 鑺傜偣鏍囩涓庝箣鍖归厤`);
      }
      return t;
    });
  if (tags.length === 0) {
    diagnostics.push(`鎶€鑳?${skillId} triggerTags 涓虹┖锛堟墍鏈夋爣绛捐杩囨护锛塦);
  }
  return tags as Tag[];
}

/** 瑙勮寖鍖?steps */
function normalizeSteps(raw: unknown, _skillId: string): string[] {
  if (!Array.isArray(raw)) {
    if (typeof raw === "string") {
      // 瀹归敊锛歀LM 鍙兘杈撳嚭閫楀彿鍒嗛殧鐨勫瓧绗︿覆
      return raw.split(/[,锛宂/).map((s) => s.trim()).filter(Boolean);
    }
    return [];
  }
  return raw.filter((s): s is string => typeof s === "string" && s.trim().length > 0);
}

/** 瑙勮寖鍖?status */
function normalizeStatus(
  raw: unknown,
  diagnostics: string[],
  skillId: string,
): SkillTemplate["status"] {
  const valid = ["trial", "active", "deprecated"];
  if (typeof raw === "string" && valid.includes(raw)) {
    // 瀹夊叏绾︽潫锛歀LM 杈撳嚭涓嶈兘鐩存帴澹版槑涓?active
    if (raw === "active") {
