/**
 * 鏍￠獙澶栨簮鎶€鑳?JSON 瀵硅薄鐨勭粨鏋勫拰瀛楁鍚堟硶鎬с€俓r
 *
 * 鍐呴儴閫氳繃 VALIDATOR_REGISTRY 閫愮粍浠舵墽琛屾牎楠屻€俓r
 * 鍗充娇鏃╂湡缁勪欢浜х敓 error锛屽悗缁粍浠朵粛浼氱户缁墽琛屼互鏀堕泦瀹屾暣鐨勮瘖鏂俊鎭€俓r
 *
 * @param json - 浠?JSON 瑙ｆ瀽寰楀埌鐨勪换鎰忓€糪r
 * @returns 鏍￠獙缁撴灉
 */
export function validateExternalSkillJson(json: unknown): SkillJsonValidationResult {
  const errors: SkillJsonValidationError[] = [];
  const warnings: SkillJsonValidationWarning[] = [];
  const infos: SkillJsonValidationInfo[] = [];

  // 椤跺眰绫诲瀷鏍￠獙
  if (typeof json !== "object" || json === null || Array.isArray(json)) {
    errors.push({
      field: "(root)",
      message: "杈撳叆蹇呴』鏄?JSON 瀵硅薄锛堥潪鏁扮粍銆侀潪 null锛塡

INVALID_ROOT_TYPE",
    });
    return { valid: false, errors, warnings, infos };
  }

  const data = json as Record<string, unknown>;

  // 閫愮粍浠舵墽琛屾牎楠屸€斺€旀墍鏈夌粍浠堕兘浼氭墽琛岋紝涓嶅洜鍗曚釜缁勪欢澶辫触鑰岀煭璺痋r
  for (const validator of VALIDATOR_REGISTRY) {
    const result = validator.validate(data);
    errors.push(...result.errors);
    warnings.push(...result.warnings);
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings,
    infos,
  };
}

// 鈹€鈹€鈹€ 杞寲妗ワ細澶栨簮 JSON 鈫?SkillTemplate 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** agentType 鈫?SkillKind 鏄犲皠琛?*/
const AGENT_TYPE_TO_KIND: Record<string, SkillKind> = {
  cod: "action",
  rev: "action",
  analy: "thought",
  op: "action",
  loop: "workflow",
  doc: "thought",
  fix: "action",
  ins: "action",
  brow: "action",
  data: "thought",
  strat: "thought",
};

/** 瑙勮寖鍖?kind锛氫紭鍏堜娇鐢?kind 瀛楁锛屽洖閫€鍒?agentType 鏄犲皠 */
function resolveKind(data: Record<string, unknown>): SkillKind {
  if (typeof data.kind === "string") {
    const known: SkillKind[] = ["action", "thought", "workflow"];
    if (known.includes(data.kind as SkillKind)) return data.kind as SkillKind;
  }
  if (typeof data.agentType === "string") {
    const mapped = AGENT_TYPE_TO_KIND[data.agentType];
    if (mapped) return mapped;
  }
  return "action";
}

/** 瀹夊叏绾︽潫锛歴tatus="active" 澶栭儴杈撳叆闇€闄嶇骇涓?trial */
function resolveStatus(raw: string | undefined): SkillTemplate["status"] {
  if (raw === "active") return "trial"; // 澶栭儴澹版槑 active 涓嶅彲淇r
  if (raw === "deprecated") return "deprecated";
  if (raw === "draft") return "trial";
  return "trial";
}

/**
 * 灏嗗凡閫氳繃 validateExternalSkillJson 鏍￠獙鐨勫婧?JSON 杞寲涓?SkillTemplate銆俓r
 *
 * 姝ゅ嚱鏁板亣璁炬暟鎹凡閫氳繃鏍￠獙鈥斺€斾笉浼氬洜瀛楁缂哄け鑰屽穿婧冿紝
 * 浣嗕粛浼氫负杈圭晫鎯呭喌鎻愪緵瀹夊叏鐨勯粯璁ゅ€笺€俓r
 *
 * @param data - 宸叉牎楠岀殑澶栨簮鎶€鑳?JSON 瀵硅薄
 * @returns SkillTemplate鈥斺€斿彲鐩存帴娉ㄥ唽鍒?SkillRegistry
 */
export function externalJsonToSkillTemplate(
  data: Record<string, unknown>,
): SkillTemplate {
  const now = Date.now();

  // triggerTags锛氳繃婊ょ函瀛楃涓叉爣绛綷r
  const triggerTags: Tag[] = Array.isArray(data.triggerTags)
    ? (data.triggerTags.filter((t): t is string => typeof t === "string" && t.trim().length > 0) as Tag[])
    : [];

  // steps锛氳繃婊ょ函瀛楃涓叉楠r
  const steps: string[] = Array.isArray(data.steps)
    ? data.steps.filter((s): s is string => typeof s === "string" && s.trim().length > 0)
    : [];

  // weight锛氫紭鍏?weight锛屽洖閫€鍒?adoptionCount - rejectionCount
  let weight = 0;
  if (typeof data.weight === "number" && Number.isFinite(data.weight)) {
    weight = Math.max(0, Math.round(data.weight));
  } else if (typeof data.adoptionCount === "number" || typeof data.rejectionCount === "number") {
    const adoption = typeof data.adoptionCount === "number" ? Math.max(0, Math.round(data.adoptionCount)) : 0;
    const rejection = typeof data.rejectionCount === "number" ? Math.max(0, Math.round(data.rejectionCount)) : 0;
    weight = Math.max(0, adoption - rejection);
  }

  return {
    id: String(data.id ?? `ext-${now}-${Math.random().toString(36).slice(2, 8)}`),
    kind: resolveKind(data),
    name: String(data.name ?? "鏈懡鍚嶆妧鑳絓

"),
    steps,
    expectedOutput: String(data.expectedOutput ?? ""),
    outputFile: typeof data.outputFile === "string" ? data.outputFile : undefined,
    status: resolveStatus(typeof data.status === "string" ? data.status : undefined),
    weight,
    feedbackHistory: Array.isArray(data.feedbackHistory)
      ? (data.feedbackHistory as FeedbackEntry[])
      : [],
    discoveredBy: String(data.discoveredBy ?? "external-import"),
    createdAt: typeof data.createdAt === "number" ? data.createdAt : now,
    tagHits: undefined,
  };
}

/**
 * 澶栨簮鎶€鑳藉鍏ヤ竴绔欏紡绠＄嚎锛氭牎楠?鈫?杞寲 鈫?杩斿洖 SkillTemplate銆俓r
 *
 * 鏍￠獙涓嶉€氳繃鏃惰繑鍥?null锛堝閮ㄨ皟鐢ㄦ柟搴斿厛妫€鏌?validationResult锛夈€俓r
 *
 * @param json - 浠庡婧?JSON 鏂囦欢瑙ｆ瀽鐨勫師濮嬫暟鎹甛r
