/**
 * 灏嗗凡楠岃瘉鎶€鑳界粨鏅朵负 kind="Knowledge" 璁板繂銆傛敮鎸佸箓绛夋洿鏂颁笌鐗堟湰杩借釜銆俓r
 *
 * 琛屼负锛歕r
 *   - 棣栨缁撴櫠锛堟棤鍚屽悕 Knowledge锛夆啋 鏂板缓锛寁ersion=1
 *   - 閲嶅缁撴櫠锛堝凡鏈夊悓鍚?Knowledge锛夆啋 褰掓。鏃х増锛寁ersion 閫掑锛屽悎骞惰瘉鎹摼
 *   - 浼犲叆 verifiedBy 鍗宠涓哄凡璁よ瘉锛坵eight=5锛夛紝鍚﹀垯涓烘湭璁よ瘉锛坵eight=3锛塡r
 *
 * @param skill  鎶€鑳芥ā鏉縗r
 * @param memory MemoryStore 瀹炰緥
 * @param opts   鍙€夛細璁よ瘉淇℃伅 + 璇佹嵁閾綷r
 * @returns 缁撴櫠缁撴灉锛屽け璐ヨ繑鍥?null
 */
export async function crystallizeSkillToKnowledge(
  skill: SkillTemplate,
  memory: MemoryStore,
  opts?: CrystallizeOptions,
): Promise<CrystallizeResult | null> {
  try {
    // 1. 鏌ラ噸锛氭槸鍚﹀凡鏈夊悓鍚?Active Knowledge
    const existing = await memory.read({
      kind: "Insight",
      metadataFilter: { skillId: skill.id },
      limit: 1,
    }, "CSA");

    let version = 1;
    let existingEvidenceIds: string[] = [];

    if (existing.length > 0) {
      // 2. 宸叉湁璁板綍 鈫?褰掓。鏃х増鏈?鈫?缁ф壙鐗堟湰鍙?+ 璇佹嵁閾綷r
      const oldEntry = existing[0];
      version = ((oldEntry.content_blob?.version as number) ?? 1) + 1;
      existingEvidenceIds = (oldEntry.content_blob?.evidenceIds as string[]) ?? [];
      memory.cas(oldEntry.id, "Active", "Archived");
    }

    // 3. 鍚堝苟璇佹嵁閾撅紙鍘婚噸锛塡r
    const evidenceIds = [...existingEvidenceIds];
    if (opts?.evidenceIds) {
      for (const eid of opts.evidenceIds) {
        if (!evidenceIds.includes(eid)) evidenceIds.push(eid);
      }
    }

    // 4. 璁よ瘉鐘舵€乗r
    const verified = opts?.verifiedBy != null;

    // 5. 鍐欏叆鏂?Knowledge
    const summaryPrefix = verified ? "[宸查獙璇佹妧鑳界煡璇哴" : "[鏈獙璇佹妧鑳界煡璇哴";
    const memId = memory.writePending({
      source: { agentType: AgentType.Loop, taskId: "" },
      kind: "Insight",
      content_blob: {
        skillId: skill.id,
        name: skill.name,
        trigger: skill.trigger,
        steps: skill.steps,
        expectedOutput: skill.expectedOutput,
        triggerTags: skill.triggerTags,
        kind: skill.kind,
        version,
        verified,
        verifiedBy: opts?.verifiedBy,
        verifiedAt: opts?.verifiedBy ? Date.now() : undefined,
        evidenceIds,
        weight: skill.weight,
      },
      summary: `${summaryPrefix} [${skill.kind}] ${skill.name} 鈥?${skill.trigger}`,
      semantic_gist: `[${skill.kind}] ${skill.name} 鈥?${skill.trigger}`.slice(0, 200),
      weight: verified ? 5 : 3,
      content_hash: "",
    });
    memory.commitMemory(memId);

    // 6. 閾炬帴璇佹嵁閾撅紙DerivedFrom锛塡r
    if (opts?.evidenceIds) {
      for (const eid of opts.evidenceIds) {
        try { memory.link(memId, eid, LinkType.DerivedFrom); } catch { /* link best-effort */ }
      }
    }

    return { memId, isUpdate: existing.length > 0, version, verified };
  } catch (e) {
    console.error(
      `[skill-persister] 鎶€鑳界粨鏅朵负鐭ヨ瘑澶辫触: [${skill.kind}] ${skill.name}`,
      e instanceof Error ? e.message : String(e),
    );
    return null;
  }
}

