 *   2. 澶栭儴璇佹嵁鈥斺€旈€氳繃 externalSearch 鍥炶皟鑱旂綉鎼滅储锛堝彲閫夛級
 *
 * 楠岃瘉閫氳繃鏉′欢锛氬唴閮ㄨ瘉鎹?鈮?1 鏉★紙澶栭儴璇佹嵁杈呭姪浣嗕笉鏀瑰彉 verdict锛夈€俓r
 * AnalysisAgent锛堢撼瑗垮Σ锛夊彲浼犲叆 externalSearch 鍋氭繁搴﹂獙璇併€俓r
 *
 * @param skill    寰呴獙璇佺殑鎶€鑳芥ā鏉縗r
 * @param memory   MemoryStore 瀹炰緥
 * @param verifier 璁よ瘉鑰呮爣璇嗭紙濡?"analysis-agent"锛塡r
 * @param opts     鍙€夛細澶栭儴鎼滅储鍥炶皟
 * @returns 楠岃瘉缁撴灉
 */
export async function verifySkillKnowledge(
  skill: SkillTemplate,
  memory: MemoryStore,
  verifier: string,
  opts?: VerifyOptions,
): Promise<VerifyResult> {
  // 妫€绱笌璇ユ妧鑳藉叧鑱旂殑鎯呮櫙璁板繂
  const episodes = await memory.read({
    kind: "TaskLog",
    metadataFilter: { skillId: skill.id },
    limit: 10,
  }, "CSA");

  const evidenceIds = episodes.map((e) => e.id);

  // 鈹€鈹€ 澶栭儴璇佹嵁鎼滅储锛堝苟琛岋紝澶辫触涓嶉樆濉烇級 鈹€鈹€
  let externalResults: SearchResult[] | undefined;
  if (opts?.externalSearch) {
    try {
      externalResults = await searchExternalEvidence(skill, opts.externalSearch);
    } catch {
      // 澶栭儴鎼滅储澶辫触涓嶅奖鍝嶅唴閮ㄩ獙璇乗r
    }
  }

  // 楠岃瘉鏍囧噯锛氬唴閮ㄨ瘉鎹?鈮?1 鏉★紙澶栭儴璇佹嵁杈呭姪锛屼笉鏀瑰彉 verdict锛塡r
  const verified = episodes.length >= 1;

  let report: string;
  if (verified) {
    report = `鐭ヨ瘑閫氳繃浜嬪疄璁よ瘉 (${verifier}): ${episodes.length} 鏉℃儏鏅蹇嗕綈璇併€俙 +
      episodes.map((e) => `\n  - ${e.summary.slice(0, 120)}`).join("");
    if (externalResults && externalResults.length > 0) {
      report += `\n澶栭儴浣愯瘉 (web_search): ${externalResults.length} 鏉°€俙 +
        externalResults.slice(0, 3).map((r) => `\n  - [${r.title}](${r.url})`).join("");
    }
  } else {
    report = `鐭ヨ瘑鏈€氳繃浜嬪疄璁よ瘉 (${verifier}): 缂哄皯鎯呮櫙璁板繂浣愯瘉銆俙 +
      `鎶€鑳?${skill.name} 铏芥潈閲?${skill.weight}锛屼絾鏃犳儏鏅蹇嗗彲杩芥函銆俙;
    if (externalResults && externalResults.length > 0) {
      report += `\n鎻愮ず: web_search 鎵惧埌 ${externalResults.length} 鏉″閮ㄧ粨鏋滐紝鍙緟鍔╀汉宸ュ鏍搞€俙 +
        externalResults.slice(0, 3).map((r) => `\n  - [${r.title}](${r.url})`).join("");
    }
  }

  return { verified, evidenceIds, externalResults, report };
}

