export function persistSkillsToMemory(
  skills: SkillTemplate[],
  memory: MemoryStore,
): number {
  let count = 0;

  for (const skill of skills) {
    try {
      const memId = memory.writePending({
        source: { agentType: AgentType.Loop, taskId: "" },
        kind: "Skill",
        content_blob: skill as unknown as Record<string, unknown>,
        summary: `[鎶€鑳芥矇娣€] [${skill.kind}] ${skill.name} 鈥?${skill.trigger}`,
        semantic_gist: `[${skill.kind}] ${skill.name} 鈥?${skill.trigger}`.slice(0, 200),
        weight: 5,
        content_hash: "",
      });
      memory.commitMemory(memId);
      count++;
    } catch (e) {
      console.error(
        `[skill-persister] 鍐欏叆鎶€鑳藉け璐? [${skill.kind}] ${skill.name}`,
        e instanceof Error ? e.message : String(e),
      );
    }
  }

  return count;
}

