/**
 * 浠?Markdown 鍐呭涓彁鍙?P0-P9 鏍煎紡鐨勬钀斤紝杞崲涓?SkillTemplate銆俓r
 * 鍖归厤 "## P0 鈥?鍚嶇О (English Name)" 鎴?"## P9 鈥?鍚嶇О" 鏍煎紡銆俓r
 */
function extractPNSections(content: string, kind: SkillKind): SkillTemplate[] {
  const patterns: SkillTemplate[] = [];
  const timestamp = Date.now();

  const sectionRegex = /(?:^|\n)#{2}\s*P(\d+)\s*[鈥擻\-鈥揮\s*(.+?)(?:\n|$)/g;
  let match: RegExpExecArray | null;

  while ((match = sectionRegex.exec(content)) !== null) {
    const pNumber = match[1];
    const fullName = match[2].trim();
    const name = fullName.replace(/\(.*?\)/g, "").trim();

    const sectionStart = match.index + match[0].length;

    // 鏌ユ壘涓嬩竴涓?section 鐨勪綅缃甛r
    const nextSection = content.slice(sectionStart).search(/(?:^|\n)#{2}\s*P\d+\s*[鈥擻\-鈥揮/);
    const sectionContent = nextSection === -1
      ? content.slice(sectionStart)
      : content.slice(sectionStart, sectionStart + nextSection);

    // 鎻愬彇 tags锛堝湪 section 鍐呭涓煡鎵?"Tags:" 琛岋級
    const tagsMatch = sectionContent.match(/Tags?[锛?]\s*(.+)/);
    const triggerTags: Tag[] = tagsMatch
      ? (tagsMatch[1].split(/[,锛屻€乚/).map((t: string) => t.trim()).filter(Boolean) as Tag[])
      : ([] as unknown as Tag[]);

    // 鎻愬彇 trigger
    const triggerMatch = sectionContent.match(/Trigger[锛?]\s*(.+)/);
    const trigger = triggerMatch
      ? triggerMatch[1].trim()
      : `P${pNumber}:${kind}`;

    // 鎻愬彇 steps锛堟煡鎵?"Steps:" 鎴?"Recipe:" 鍚庣殑琛岋級
    const recipeMatch = sectionContent.match(/Recipe[锛?]\s*([\s\S]*?)(?:\n(?:#{1,3}|\n)|$)/);
    let steps: string[] = [];
    if (recipeMatch) {
      const recipeContent = recipeMatch[0];
      const stepLines = recipeContent.match(/[-*]\s*(.+)/g);
      if (stepLines) {
        const stepParts = stepLines.map((s: string) => s.replace(/^[-*]\s*/, "").trim());
        steps = stepParts.filter(Boolean);
      }
    }

    if (steps.length === 0) {
      steps = ["鍒嗘瀽鐩稿叧浠ｇ爜妯″紡", "閬靛惊宸插缓绔嬬殑鏋舵瀯绾﹀畾"];
    }

    // 鎻愬彇 conditions 鈫?expectedOutput
    const conditionMatch = sectionContent.match(/Condition[锛?]\s*([\s\S]*?)(?:\n(?:#{1,3}|\n)|$)/);
    const conditions = conditionMatch
      ? conditionMatch[1].split("\n").map((c: string) => c.trim()).filter(Boolean).join("; ")
      : "";
    const expectedOutput = conditions || `P${pNumber}:${name}`;

    // 鏋勯€?skillName锛堢敤浜?id锛塡r
    const skillName = name.replace(/\s+/g, "-").toLowerCase();
    const id = `p${pNumber}-${skillName}-${timestamp}`;

    patterns.push({
      id,
      kind,
      name: `P${pNumber}:${name}`,
      triggerTags,
      trigger,
      steps,
      expectedOutput,
      status: "trial" as const,
      weight: 0,
      feedbackHistory: [],
      discoveredBy: "file-scanner-pattern",
      createdAt: timestamp,
    });
  }

  return patterns;
}

/**
 * 浠?Markdown 鍐呭涓彁鍙朶

## 妯″紡 N: 鍚嶇О" 鏍煎紡銆俓r
 */
function extractPatternSections(content: string, kind: SkillKind): SkillTemplate[] {
  const patterns: SkillTemplate[] = [];
  const timestamp = Date.now();

  const sectionRegex = /(?:^|\n)#{2}\s*妯″紡\s*(\d+)\s*[锛?]\s*(.+?)(?:\n|$)/g;
  let match: RegExpExecArray | null;

  while ((match = sectionRegex.exec(content)) !== null) {
    const patternNumber = match[1];
    const name = match[2].trim();

    const sectionStart = match.index + match[0].length;

    // 鏌ユ壘涓嬩竴涓?section 鐨勪綅缃甛r
    const nextSection = content.slice(sectionStart).search(/(?:^|\n)#{2}\s*妯″紡\s*\d+\s*[锛?]/);
    const sectionContent = nextSection === -1
      ? content.slice(sectionStart)
      : content.slice(sectionStart, sectionStart + nextSection);

    // 鎻愬彇 tags
    const tagsMatch = sectionContent.match(/Tags?[锛?]\s*(.+)/);
    const triggerTags2: Tag[] = tagsMatch
      ? (tagsMatch[1].split(/[,锛屻€乚/).map((t: string) => t.trim()).filter(Boolean) as Tag[])
      : ([] as unknown as Tag[]);
    
    // 鎻愬彇 trigger
    const triggerMatch2 = sectionContent.match(/Trigger[锛?]s*(.+)/);
    const trigger2 = triggerMatch2
      ? triggerMatch2[1].trim()
      : `妯″紡${patternNumber}:${kind}`;
    
    // 鎻愬彇 steps锛堝涓彲鑳界殑妯″紡锛塡r
    const stepLines2 =
      sectionContent.match(/姝ラ[锛?]s*([\s\S]*?)(?:\n(?:#{1,3}|\n)|$)/)?.[1]
      ?.split("\n").map((s: string) => s.replace(/^\d+[.銆乚\s*/, "").trim())
      .filter(Boolean)
      ??
      sectionContent.match(/娴佺▼[锛?]s*([\s\S]*?)(?:\n(?:#{1,3}|\n)|$)/)?.[1]
      ?.split("\n").map((s: string) => s.replace(/^[-*]\s*/, "").trim())
      .filter(Boolean)
      ??
      sectionContent.match(/[-*]\s*(.+)/g)
      ?.map((s: string) => s.replace(/^[-*]\s*/, "").trim())
      .filter(Boolean);
    
    const steps2: string[] = stepLines2
      ? stepLines2.map((s: string) => s.replace(/^-\s*/, "").trim()).filter(Boolean)
      : ["鍙傝€冩枃妗ｄ腑鐨勬ā寮忔弿杩癨

-").toLowerCase();
    const id = `pattern-${patternNumber}-${skillName}-${timestamp}`;

    patterns.push({
      id,
      kind,
      name: `妯″紡${patternNumber}:${name}`,
      triggerTags: triggerTags2,
      trigger: trigger2,
      steps: steps2,
      expectedOutput,
      status: "trial" as const,
      weight: 0,
