// ============================================================
// skill-template-engine.ts 鈥斺€?鎶€鑳芥楠ゆā鏉挎覆鏌撳紩鎿嶾r
//
// 浠?@cortex/skill-kit 杩佺Щ鑰屾潵锛岀撼鍏?engine 缁勪欢绠＄嚎銆俓r
// 鎻愪緵杞婚噺绾фā鏉挎覆鏌撹兘鍔涳紝鐢ㄤ簬鎶€鑳芥楠ょ殑 prompt 妯℃澘娓叉煋銆俓r
//
// 鏀寔鐨勮娉曪細
// - {{ variable }} 鈥?鍙橀噺鎻掑€糪r
// - {{ user.name }} 鈥?宓屽灞炴€ц闂紙鐐瑰彿璺緞锛塡r
// - {{ variable || fallback }} 鈥?榛樿鍊糪r
// - {{#if condition}}...{{/if}} 鈥?鏉′欢娓叉煋锛堟敮鎸?{{else}} 鍒嗘敮锛塡r
// - {{#each list}}...{{/each}} 鈥?寰幆娓叉煋
//
// 涓嶄緷璧栦换浣曞閮ㄦā鏉垮紩鎿庡簱銆俓r
//
// @merged-from @cortex/skill-kit/src/template-engine.ts
// ============================================================

/** 妯℃澘寮曟搸閰嶇疆閫夐」 */
export interface TemplateEngineOptions {
  /** 鍙橀噺鎻掑€煎垎闅旂锛岄粯璁?["{{", "}}"] */
  delimiters?: [string, string];
  /** 鏈畾涔夊彉閲忔椂鐨勯粯璁ゅ€硷紝榛樿 "" */
  undefinedPlaceholder?: string;
  /** 鏄惁鍚敤 HTML 杞箟锛岄粯璁?false */
  escapeHtml?: boolean;
}

/** 妯℃澘涓婁笅鏂団€斺€斾紶閫掔粰妯℃澘寮曟搸鐨勫彉閲忓拰杈呭姪鍑芥暟 */
export interface TemplateContext {
  [key: string]: unknown;
}

const DEFAULT_OPTIONS: Required<TemplateEngineOptions> = {
  delimiters: ["{{", "}}"],
  undefinedPlaceholder: "",
  escapeHtml: false,
};

/**
 * SkillTemplateEngine 鈥斺€?杞婚噺绾фā鏉挎覆鏌撳紩鎿庛€俓r
 *
 * @example
 * ```typescript
 * const engine = new SkillTemplateEngine();
 * const result = engine.render("Hello, {{ name }}!", { name: "World" });
 * // => "Hello, World!"
 * ```
 */
export class SkillTemplateEngine {
  private options: Required<TemplateEngineOptions>;
  private openTag: string;
  private closeTag: string;

  constructor(options: TemplateEngineOptions = {}) {
    this.options = { ...DEFAULT_OPTIONS, ...options };
    [this.openTag, this.closeTag] = this.options.delimiters;
  }

  /**
   * 娓叉煋妯℃澘瀛楃涓层€俓r
   *
   * @param template 妯℃澘瀛楃涓瞈r
   * @param context  鍙橀噺涓婁笅鏂嘰r
   * @returns 娓叉煋鍚庣殑瀛楃涓瞈r
   */
  render(template: string, context: TemplateContext): string {
    if (!template) return "";

    let result = template;

    // 1. 澶勭悊鏉′欢鍧?{{#if condition}}...{{/if}}
    result = this.renderConditionals(result, context);

    // 2. 澶勭悊寰幆鍧?{{#each list}}...{{/each}}
    result = this.renderEach(result, context);

    // 3. 澶勭悊鍙橀噺鎻掑€?{{ variable }} 鍜?{{ variable || fallback }}
    result = this.renderVariables(result, context);

    return result;
  }

  /**
   * 娓叉煋瀛楃涓叉暟缁勬ā鏉匡紙姣忔潯渚濇娓叉煋锛屾嫾鎺ユ崲琛岋級銆俓r
   */
  renderEachLine(
    templates: string[],
    context: TemplateContext,
  ): string[] {
    return templates.map((t) => this.render(t, context));
  }

  // 鈹€鈹€ 绉佹湁鏂规硶 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private safeRender(value: unknown): string {
    const str = value === null || value === undefined
      ? this.options.undefinedPlaceholder
      : String(value);

    if (this.options.escapeHtml) {
      return this.escapeHtml(str);
    }
    return str;
  }

  private escapeHtml(str: string): string {
    return str
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  // 鈹€鈹€ 鍙橀噺鎻掑€?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private renderVariables(template: string, context: TemplateContext): string {
    const variableRegex = new RegExp(
      `${this.escapeRegex(this.openTag)}\\s*(?!#|/)([\\s\\S]+?)\\s*${this.escapeRegex(this.closeTag)}`,
      "g",
    );

    return template.replace(variableRegex, (_match, expression: string) => {
      const trimmed = expression.trim();

      // 澶勭悊榛樿鍊艰娉曪細variable || fallback
      const pipeIndex = trimmed.indexOf("||");
      let path: string;
      let fallback: string | undefined;

      if (pipeIndex !== -1) {
        path = trimmed.substring(0, pipeIndex).trim();
        fallback = trimmed.substring(pipeIndex + 2).trim();
      } else {
        path = trimmed;
      }

      const value = this.resolvePath(context, path);

      if (value === undefined || value === null) {
        if (fallback !== undefined) {
          const fallbackValue = this.resolvePath(context, fallback);
          return this.safeRender(fallbackValue ?? fallback);
        }
        return this.safeRender(this.options.undefinedPlaceholder);
      }

      if (typeof value === "function") {
        return this.safeRender(value.call(context));
      }

      return this.safeRender(value);
    });
  }

  // 鈹€鈹€ 鏉′欢娓叉煋 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private renderConditionals(template: string, context: TemplateContext): string {
    const ifRegex = new RegExp(
      `${this.escapeRegex(this.openTag)}\\s*#if\\s+(.+?)\\s*${this.escapeRegex(this.closeTag)}([\\s\\S]*?)${this.escapeRegex(this.openTag)}\\s*/if\\s*${this.escapeRegex(this.closeTag)}`,
      "g",
    );

    return template.replace(ifRegex, (_match, condition: string, body: string) => {
      const conditionValue = this.evaluateCondition(condition.trim(), context);

      // 澶勭悊 {{else}} 鍒嗘敮
      const elseMatch = body.match(
        new RegExp(
          `${this.escapeRegex(this.openTag)}\\s*else\\s*${this.escapeRegex(this.closeTag)}([\\s\\S]*)`,
        ),
      );

      let trueBody: string;
      let falseBody: string;

      if (elseMatch) {
        trueBody = body.substring(0, body.indexOf(this.openTag + "else" + this.closeTag));
        falseBody = elseMatch[1];
      } else {
        trueBody = body;
        falseBody = "";
      }

      const selectedBody = conditionValue ? trueBody : falseBody;
      return this.render(selectedBody, context);
    });
  }

  private evaluateCondition(condition: string, context: TemplateContext): boolean {
    let expr = condition.trim();

    const isNegated = expr.startsWith("!");
    if (isNegated) {
      expr = expr.substring(1).trim();
    }

    if (expr === "true") return !isNegated;
    if (expr === "false") return isNegated;

    const value = this.resolvePath(context, expr);
    const isTruthy = value !== undefined && value !== null && value !== false && value !== 0 && value !== "";

    return isNegated ? !isTruthy : isTruthy;
  }

  // 鈹€鈹€ 寰幆娓叉煋 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private renderEach(template: string, context: TemplateContext): string {
    const eachRegex = new RegExp(
      `${this.escapeRegex(this.openTag)}\\s*#each\\s+(.+?)\\s*${this.escapeRegex(this.closeTag)}([\\s\\S]*?)${this.escapeRegex(this.openTag)}\\s*/each\\s*${this.escapeRegex(this.closeTag)}`,
      "g",
    );

    return template.replace(eachRegex, (_match, listExpr: string, body: string) => {
      const list = this.resolvePath(context, listExpr.trim());

      if (!Array.isArray(list) && (typeof list !== "object" || list === null)) {
        return "";
      }

      const parts: string[] = [];

      if (Array.isArray(list)) {
        for (let i = 0; i < list.length; i++) {
          const item = list[i];
          const itemContext: TemplateContext = {
            ...context,
            this: item,
            index: i,
            key: String(i),
          };
          parts.push(this.render(body, itemContext));
        }
      } else {
        const keys = Object.keys(list as Record<string, unknown>);
        for (const key of keys) {
          const item = (list as Record<string, unknown>)[key];
          const itemContext: TemplateContext = {
            ...context,
            this: item,
            key,
            index: keys.indexOf(key),
          };
          parts.push(this.render(body, itemContext));
        }
      }

      return parts.join("");
    });
  }

  // 鈹€鈹€ 璺緞瑙ｆ瀽 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private resolvePath(context: TemplateContext, pathStr: string): unknown {
    const parts = pathStr.split(".");
    let current: unknown = context;

    for (const part of parts) {
      if (current === null || current === undefined) {
        return undefined;
      }

      if (typeof current === "object" && part in (current as Record<string, unknown>)) {
        current = (current as Record<string, unknown>)[part];
      } else {
        return undefined;
      }
    }

    return current;
  }

  // 鈹€鈹€ 宸ュ叿鏂规硶 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private escapeRegex(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
}

/**
 * MetaAgentReplanAdapter 鈥斺€?灏?MetaAgent 閫傞厤涓?IReplanProvider 鎺ュ彛銆俓r
 *
 * 寮曟搸鐨?MetaAgent 鎷ユ湁鍏蜂綋鐨?requestReplan / requestBoundaryReplan 鏂规硶锛孿r
 * scheduler 鐨?ReplanManager 鍒欎緷璧栨娊璞＄殑 IReplanProvider 鎺ュ彛銆俓r
 * 姝ら€傞厤鍣ㄥ畬鎴愪粠鍏蜂綋绫诲埌鎺ュ彛鐨勬ˉ鎺ワ紝浣垮紩鎿庡彲浠ユ棤缂濅娇鐢?scheduler 鐨?ReplanManager銆俓r
 *
 * @since v3.x 鈥?engine 鍓湰鍘嬫墎锛氬垹闄ゆ湰鍦?ReplanManager锛岀粺涓€鐢?@cortex/scheduler
 */

import type { IReplanProvider } from "@cortex/scheduler";
import type { MetaAgent } from "./meta-agent.js";

export class MetaAgentReplanAdapter implements IReplanProvider {
  constructor(private readonly metaAgent: MetaAgent) {}

  async requestReplan(
    node: Parameters<IReplanProvider["requestReplan"]>[0],
    reason: string,
    count: number,
    _currentDepth?: number,
    maxReplanPerNode?: number,
  ): ReturnType<IReplanProvider["requestReplan"]> {
    return await this.metaAgent.requestReplan(node, reason, count, undefined, maxReplanPerNode);
  }

  async requestBoundaryReplan(
    node: Parameters<IReplanProvider["requestBoundaryReplan"]>[0],
    reason: string,
    count: number,
    _currentDepth?: number,
    maxReplanPerNode?: number,
  ): ReturnType<IReplanProvider["requestBoundaryReplan"]> {
    return await this.metaAgent.requestBoundaryReplan(node, reason, count, undefined, maxReplanPerNode);
  }
}

import { PRESET_CONTEXT_POLICIES, PipelinePriority, type IPipelineObserver, type ImpactScope, type ObservableEvent, type PipelineEventType, type ReplanResult, type SafeErrorReporter, type Tag, type TaskNode } from "@cortex/shared";
import type { LlmAdapter } from "@cortex/llm";
import {
  buildPlanningSystem,
  buildPlanningSystemBlank,
  REPLAN_SYSTEM,
  PIPELINE_CTX_MAX_OUTPUT_LEN,
  PIPELINE_CTX_MAX_ERROR_LEN,
  PIPELINE_CTX_RECENT_LIMIT,
  PIPELINE_CTX_HARD_CAP,
} from "@cortex/config";
import type { SkillRegistry } from "../registry/skill-registry.js";

/**
 * MetaAgent 鈥斺€?鎴樻湳寮曟搸銆俓r
 * 鎺ユ敹鐢ㄦ埛鎰忓浘锛屾媶瑙ｄ负 TaskNode 鏍戯紝鍐欏叆 TaskBoard銆俓r
 * 鐙韩 DeepSeek V4 Flash 鎬濊€冩ā寮忥紙reasoner 妯″瀷锛屼粎鐢橀洦/閽熺/闇滃嚌鍗囨牸涓?V4 Pro锛夈€俓r
 *
 * @contract 妯″潡杈圭晫濂戠害锛堜箙宀愬繊 P1-5锛氭ā鍧楄竟鐣岀己灏戞樉寮忓绾﹀寲瀹氫箟 鈫?宸查棴鍚堬級
 *
 *   plan(intent) 鈫?TaskNode[]锛氱函鍑芥暟寮忚鍒掞紝涓嶅啓鏉縗r
 *   requestReplan(failedNode, reason, count) 鈫?ReplanResult锛氬熀浜庡け璐ヨ瘖鏂敓鎴愭浛浠ｆ柟妗圽r
 *
 *   璋冪敤鏂癸紙Scheduler锛夌殑璐ｄ换锛歕r
 *   - plan() 杩斿洖鐨?TaskNode[] 鐢辫皟鐢ㄦ柟 add 鍒?TaskBoard
 *   - requestReplan() 杩斿洖鐨?nodes 鐢?Scheduler._drainReplanQueue add 鍒?TaskBoard锛堥鑰屼笉鎵э級
 *   - 璋冪敤鏂硅礋璐ｈ妭鐐瑰湪 TaskBoard 涓殑鐢熷懡鍛ㄦ湡绠＄悊
 *
 *   寮傚父璇箟锛歕r
 *   - JSON 瑙ｆ瀽澶辫触涓嶆姏寮傚父鈥斺€斿洖閫€涓哄崟涓?generic fallbackNode
 *   - LLM 璋冪敤澶辫触鐢?LlmAdapter 鎶涘嚭锛岃皟鐢ㄦ柟 catch
 *   - skillRegistry 缂哄け涓嶉樆濉炶鍒掆€斺€旇烦杩囨妧鑳藉寮篭r
 *
 * 鍙€夐泦鎴?SkillRegistry锛氳鍒掓椂鏌ヨ宸叉矇娣€鐨勬妧鑳芥ā鏉匡紝
 * 娉ㄥ叆 prompt 涓婁笅鏂囷紝鎻愬崌浠诲姟鎷嗚В绮惧噯搴︺€俓r
 *
 * @fix 涔呭矏蹇?P1-3锛歋killRegistry 瀹炵幇绫讳粠 @cortex/shared 绉诲叆鏈寘銆俓r
 *   shared 浠呬繚鐣?SerializedSkillRegistry 绫诲瀷銆俓r
 * @fix D5 鈥?_parseReplanResult 鏀寔绠€娲佹暟缁勬牸寮忎腑鐨?impactScope 瀛楁锛孿r
 *   闃叉 LLM 杈撳嚭鏁扮粍鏍煎紡鏃?impactScope 琚潤榛樿涓?"local"銆俓r
 */

export class MetaAgent {
  private _nodeCounter = 0; // 闃?Date.now() 楂橀纰版挒
  private _safeReporter?: SafeErrorReporter;
  private _skillRegistry?: SkillRegistry;
  private _observer?: IPipelineObserver;
  /** 澶勭悊鍑芥暟寮曠敤鈥斺€旂敤浜?shutdown 鏃剁簿纭€€璁?*/
  private _onNodeComplete?: (event: ObservableEvent) => void;
  private _onNodeFailed?: (event: ObservableEvent) => void;
  /** 绠＄嚎浜嬩欢绉疮鈥斺€攑lan() 璋冪敤鏃舵敞鍏?prompt 涓婁笅鏂?*/
  private _pipelineContext: string[] = [];
  private readonly _planningSystem: string;
  private readonly _replanSystem: string;
  private _workspaceRoot?: string;

  constructor(
    private readonly llm: LlmAdapter,
    skillRegistry?: SkillRegistry,
    planningSystemPrompt?: string,
    replanSystemPrompt?: string,
    observer?: IPipelineObserver,
    workspaceRoot?: string,
  ) {
    this._skillRegistry = skillRegistry;
    this._planningSystem = planningSystemPrompt ?? buildPlanningSystemBlank();
    this._replanSystem = replanSystemPrompt ?? REPLAN_SYSTEM;
    this._workspaceRoot = workspaceRoot;
    if (observer) this.setObserver(observer);
  }

  /** RLM 鎷嗚В鐢ㄧ殑 LLM 閫傞厤鍣紙鍙锛夈€係cheduler 閫氳繃姝ゅ叆鍙ｆ敞鍏?decompose() 鐨?LLM 璋冪敤鑳藉姏銆?*/
  get llmAdapter(): LlmAdapter {
    return this.llm;
  }

  /** 娉ㄥ叆/鏇存柊宸ヤ綔鍖烘牴璺緞 */
  setWorkspaceRoot(root: string): void {
    this._workspaceRoot = root;
  }

  /** 娉ㄥ叆鎶€鑳芥敞鍐岃〃锛堝彲鍚庣疆缁戝畾锛?*/
  setSkillRegistry(registry: SkillRegistry): void {
    this._skillRegistry = registry;
  }

  /** 娉ㄥ叆绠＄嚎鈥斺€擬etaAgent 璁㈤槄鑺傜偣浜嬩欢浠ヨ幏鍙栨墽琛屽眰淇℃伅 */
  setObserver(observer: IPipelineObserver): void {
    if (this._observer) this._unsubscribe();
    this._observer = observer;
    // 璁㈤槄 NodeComplete锛堝彧鎺モ€斺€旇幏鍙?Agent 鎵ц浜у嚭锛塡r
    // NodeComplete 浠?HIGH 浼樺厛绾у彂灏勶紙cleanup-step.ts + scheduler._dispatchMulti锛塡r
    this._onNodeComplete = (event: ObservableEvent) => {
      if (event.type === "node.complete" as PipelineEventType.NodeComplete) {
        const { nodeId, agentType, output } = event.payload as { nodeId: string; agentType: string; success: true; output?: string };
        if (output) {
          this._enqueuePipelineCtx(`[${agentType}] ${nodeId}: ${output.slice(0, PIPELINE_CTX_MAX_OUTPUT_LEN)}`);
        }
      }
    };
    observer.on(PipelinePriority.HIGH, this._onNodeComplete);
    // 璁㈤槄 NodeFailed锛堝彧鏀垛€斺€旀劅鐭ユ墽琛屽け璐ワ級
    // NodeFailed 浠?CRITICAL 浼樺厛绾у彂灏勶紙scheduler._dispatchNode锛塡r
    this._onNodeFailed = (event: ObservableEvent) => {
      if (event.type === "node.failed" as PipelineEventType.NodeFailed) {
        const { nodeId, error } = event.payload as { nodeId: string; error: string };
        this._enqueuePipelineCtx(`[FAILED] ${nodeId}: ${error.slice(0, PIPELINE_CTX_MAX_ERROR_LEN)}`);
      }
    };
    observer.on(PipelinePriority.CRITICAL, this._onNodeFailed);
  }

  /** 娉ㄥ叆閿欒涓婃姤閫氶亾锛坥bserver 鍙岄€氶亾妯″紡锛?*/
  setSafeReporter(reporter: SafeErrorReporter): void {
    this._safeReporter = reporter;
  }

  /** 璁㈤槄缁堟鈥斺€旂簿纭€€璁㈠凡娉ㄥ唽鐨?handler锛岄槻姝㈣鍒犲叾浠栫粍浠?*/
  private _unsubscribe(): void {
    if (!this._observer) return;
    if (this._onNodeComplete) this._observer.off(PipelinePriority.HIGH, this._onNodeComplete);
    if (this._onNodeFailed) this._observer.off(PipelinePriority.CRITICAL, this._onNodeFailed);
    this._onNodeComplete = undefined;
    this._onNodeFailed = undefined;
  }

  /** 灏嗕簨浠跺叆闃熷埌绠＄嚎涓婁笅鏂囷紙甯︾‖涓婇檺闃插唴瀛樻硠婕忥級 */
  private _enqueuePipelineCtx(entry: string): void {
    if (this._pipelineContext.length >= PIPELINE_CTX_HARD_CAP) {
      // 鎴崐淇濈暀鏈€杩戜簨浠禱r
      this._pipelineContext = this._pipelineContext.slice(-Math.floor(PIPELINE_CTX_HARD_CAP / 2));
    }
    this._pipelineContext.push(entry);
  }

  /** 娓呯┖绠＄嚎涓婁笅鏂囩Н绱紙姣忔 plan() 璋冪敤鍚庨噸缃級 */
  private _clearPipelineContext(): void {
    this._pipelineContext = [];
  }

  /** 鑾峰彇褰撳墠绉疮鐨勭绾夸笂涓嬫枃 */
  private _getPipelineContext(): string {
    if (this._pipelineContext.length === 0) return "";
    const recent = this._pipelineContext.slice(-PIPELINE_CTX_RECENT_LIMIT);
    return `\nRecent execution context (from pipeline):\n${recent.map((c) => `  ${c}`).join("\n")}\n`;
  }

  /**
   * 閲嶈鍒掞細褰撹妭鐐规墽琛屽け璐ユ椂锛屽熀浜嶾

string" ? parsed.unclear : undefined,
        originalIntent,
      };
    } catch {
      return {
        goal: originalIntent.slice(0, 80),
        actionType: "inquiry",
        scope: "鏈寚瀹歕

analysis", "modification", "audit", "refactor", "generation", "inquiry"]);

  private _normalizeActionType(raw: unknown): IntentClarification["actionType"] {
    if (typeof raw === "string" && this._validActionTypes.has(raw)) {
      return raw as IntentClarification["actionType"];
    }
    return "inquiry";
  }

  /**
   * 瑙勫垝锛氬皢鐢ㄦ埛鎰忓浘鎷嗚В涓?TaskNode 鍒楄〃銆俓r
   * 杩斿洖鐨勮妭鐐?`parentId` 鍏崇郴宸插缓绔嬶紝鍙洿鎺?add 鍒?TaskBoard銆俓r
   */
  async plan(
    intent: string,
    context?: PlanContext,
  ): Promise<TaskNode[]> {
    const prompt = this._planningPrompt(intent, context);
    // 鏈夊伐浣滃尯鏃舵敞鍏ュ埌绯荤粺鎻愮ず璇嶏紝纭繚杈圭晫鏍￠獙瑙勫垯鐢熸晥
    const systemPrompt = this._workspaceRoot
      ? buildPlanningSystem(this._workspaceRoot)
      : this._planningSystem;
    try {
      const res = await this.llm.chat(this.llm.reasonerModel, [
        { role: "system", content: systemPrompt },
        { role: "user", content: prompt },
      ]);
      return this._parsePlan(res.content ?? "", context?.parentId);
    } finally {
      // 鏃犺 LLM 璋冪敤鎴愬姛鎴栧紓甯革紝閮藉繀椤绘竻鐞嗭紝闃叉涓嬩竴娆?plan() 娉ㄥ叆杩囨湡涓婁笅鏂嘰r
      this._clearPipelineContext();
    }
  }

  /** 鐢熸垚瑙勫垝 prompt */
  private _planningPrompt(intent: string, context?: PlanContext): string {
    const parts: string[] = [];

    if (context?.parentId) {
      parts.push(`Parent node: ${context.parentId}`);
    }
    if (context?.existingTags && context.existingTags.length > 0) {
      parts.push(`Existing context tags: ${context.existingTags.join(", ")}`);
    }

    // 鈹€鈹€ 绠＄嚎涓婁笅鏂囷紙v2.5.41 鏂板鈥斺€斿師鍒欎簩鍙屽悜涓嬫斁鍚庡湪 MetaAgent 渚х殑钀界偣锛夆攢鈹€
    const pipeCtx = this._getPipelineContext();
    if (pipeCtx) {
      parts.push(pipeCtx);
    }

    // 鈹€鈹€ 鎶€鑳藉寮猴細鏌ヨ SkillRegistry 鍖归厤鐨勬妧鑳芥ā鏉?鈹€鈹€
    if (this._skillRegistry && context?.existingTags) {
      const matched = this._skillRegistry.queryByTags(context.existingTags as Tag[]);
      if (matched.length > 0) {
        const skillLines = matched.map((s) =>
          `  路 ${s.name} (id:${s.id}) [${s.kind}] tags:[${s.triggerTags.join(",")}] 鈥?${s.trigger}`,
        );
        parts.push(
          `Available skill templates (pre-existing patterns):\n${skillLines.join("\n")}\n\n` +
          "You MAY reference these skills in your plan by mentioning their id in the payload. " +
          "These are vetted, repeatable workflows 鈥?prefer them over inventing new task sequences.",
        );
      }
    }

    parts.push(`User intent: ${intent}`);

    return parts.join("\n");
  }

  /** 浠?LLM 杈撳嚭鎻愬彇 JSON锛坄``json ... ``` 鎴栫函瀛楃涓诧級銆俓r
   * 鍏堝皾璇曟爣璁板洿鏍忥紝鍐嶅皾璇曟彁鍙栨渶澶栧眰骞宠　鏁扮粍銆俓r
   * 鎷彿鍖归厤鏃惰瘑鍒?JSON 瀛楃涓茶竟鐣岋紝閬垮厤 payload 鍐呯殑 [ ] 瀛楃璇璁℃暟鍣ㄣ€?*/
  private _extractJson(raw: string): string {
    // 浼樺厛鍖归厤 ```json ... ``` 鏍囪鍥存爮锛堥潪璐┆锛屽尮閰嶆渶杩戠殑闂悎锛塡r
    const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (fenceMatch) return fenceMatch[1];

    // 鍥為€€锛氭彁鍙栨渶澶栧眰骞宠　 [ ... ] 鏁扮粍
    const startIdx = raw.indexOf("[");
    if (startIdx === -1) return raw;

    let depth = 0;
    let inString = false;
    let stringChar = ""; // 褰撳墠瀛楃涓茬殑寮曞彿瀛楃锛圽

\\") {
          escaped = true;
          continue;
        }
        if (ch === stringChar) {
          inString = false;
          stringChar = "";
        }
        continue;
      }

      if (ch === "\"" || ch === "'") {
        inString = true;
        stringChar = ch;
        continue;
      }

      if (ch === "[") depth++;
      else if (ch === "]") {
        depth--;
        if (depth === 0) return raw.slice(startIdx, i + 1);
      }
    }
    return raw;
  }

  /** 鏋勯€犲厹搴?TaskNode锛圝SON 瑙ｆ瀽澶辫触鏃讹級 */
  private _fallbackNode(raw: string, parentId?: string): TaskNode {
    return {
      id: `task-${Date.now()}-0`,
      parentId,
      type: "analysis",
      tags: ["analysis"] as Tag[],
      needsMultiPerspective: false,
      status: "pending",
      claimedBy: [],
      payload: raw,
      results: [],
      createdAt: Date.now(),
      contextPolicyId: "diagnose",
    };
  }

  /** 浠?LLM 杈撳嚭瑙ｆ瀽 JSON 浠诲姟鏍?*/
  private _parsePlan(raw: string, parentId?: string): TaskNode[] {
    // 澶氱骇瀹归敊绛栫暐锛歟xtractJson 鈫?raw鐩存帴 鈫?淇甯歌JSON闂
    const candidates = [
      this._extractJson(raw),
      raw, // LLM 鍙兘鐩存帴杈撳嚭骞插噣 JSON
    ];

    for (const candidate of candidates) {
      const items = this._tryParseItems(candidate);
      if (items !== null) {
        // 绌烘暟缁勬槸鍚堟硶缁撴灉锛氬伐浣滃尯杈圭晫鎷掔粷 / 鏃犳搷浣滃繀瑕乗r
        // 鐩存帴杩斿洖 [] 璁╄皟鐢ㄦ柟澶勭悊锛屼笉鐢熸垚鍨冨溇鍏滃簳鑺傜偣
        if (items.length === 0) return [];
        return items.flatMap((item, i) => this._toTaskNode(item, parentId, i));
      }
    }

    const msg = `JSON 瑙ｆ瀽澶辫触 (${raw.length} chars)锛屽洖閫€涓哄崟 generic 鑺傜偣銆傚師濮嬭緭鍑哄墠200瀛? ${raw.slice(0, 200)}`;
    if (this._safeReporter) {
      this._safeReporter({ source: "MetaAgent._parsePlan", error: msg, severity: "degraded" });
    } else if (this._observer) {
      this._observer.emit({
        type: "infra.component_degraded" as PipelineEventType,
        priority: PipelinePriority.NORMAL,
        payload: { component: "MetaAgent", operation: "_parsePlan", detail: msg },
        timestamp: Date.now(),
        notificationType: "FYI",
      });
    }
    return [this._fallbackNode(raw, parentId)];
  }

  /** 灏濊瘯瑙ｆ瀽 JSON 涓?PlanItem[]锛岃嚜鍔ㄤ慨澶嶅父瑙?LLM 鏍煎紡闂 */
  private _tryParseItems(jsonStr: string): PlanItem[] | null {
    if (!jsonStr || jsonStr.length < 2) return null;

    // 绛栫暐 1: 鐩存帴瑙ｆ瀽
    try { return JSON.parse(jsonStr); } catch { /* continue */ }

    // 绛栫暐 2: 鍘婚櫎灏鹃儴澶氫綑閫楀彿锛圠LM 缁忓吀閿欒锛塡r
    try { return JSON.parse(jsonStr.replace(/,\s*([}\]])/g, "$1")); } catch { /* continue */ }

    // 绛栫暐 3: 鎴彇棣?[ 鍒版湯 ]锛屽啀鍋氫竴娆″瓧绗︿覆鎰熺煡鎻愬彇锛堝弻淇濋櫓锛塡r
    const firstBracket = jsonStr.indexOf("[");
    const lastBracket = jsonStr.lastIndexOf("]");
    if (firstBracket !== -1 && lastBracket > firstBracket) {
      const trimmed = jsonStr.slice(firstBracket, lastBracket + 1);
      try { return JSON.parse(trimmed); } catch { /* continue */ }
      try { return JSON.parse(trimmed.replace(/,\s*([}\]])/g, "$1")); } catch { /* continue */ }
    }

    return null;
  }

  /** 灏?PlanItem 杞负 TaskNode[]锛堣嚜韬?+ 鎵€鏈夊瓙瀛欙級 */
  private _toTaskNode(item: PlanItem, parentId: string | undefined, index: number): TaskNode[] {
    const now = Date.now();
    const nodeId = `task-${now}-${this._nodeCounter++}-${index}`;

    // 瀛愪换鍔￠€掑綊鈥斺€旀嬁鍒扮殑鏄墎骞虫暟缁勶紝姣忎釜瀛愯妭鐐圭殑 parentId 宸叉寚鍥炲綋鍓嶈妭鐐筡r
    const children: TaskNode[] = (item.children ?? []).flatMap((child, ci) =>
      this._toTaskNode(child, nodeId, ci),
    );

    // 鎺ㄧ悊娣卞害锛歀LM 鍙樉寮忔寚瀹氾紝鍚﹀垯鎸夋爣绛炬櫤鑳介粯璁r
    const reasoningEffort: "high" | "max" =
      item.reasoningEffort ??
      (item.tags?.some((t) => t === "audit" || t === "constitution_check") ? "max" : "high");

    const self: TaskNode = {
      id: nodeId,
      parentId,
      type: item.type ?? "analysis",
      tags: (item.tags ?? ["code"]) as Tag[],
      needsMultiPerspective: item.needsMultiPerspective ?? false,
      status: "pending",
      claimedBy: [],
      payload: item.task,
      results: [],
      createdAt: now,
      reasoningEffort,
      recommendedTier: _validTier(item.recommendedTier),
      contextPolicyId: _resolveContextPolicy(item.type, item.tags),
    };

    return [self, ...children];
  }

  /** 瑙ｆ瀽 ReplanResult锛氫粠 LLM 杈撳嚭鎻愬彇 tasks + impactScope */
  private _parseReplanResult(raw: string, parentId?: string): ReplanResult {
    const jsonStr = this._extractJson(raw);

    try {
      const parsed = JSON.parse(jsonStr);
      // 鍏煎涓ょ鏍煎紡锛歀LM 瑙勮寖杈撳嚭 {"tasks":[...], "impactScope":"..."}
      // 浠ュ強绠€娲佹暟缁勬牸寮?[{task, type, tags, ...}]
      const items: PlanItem[] = Array.isArray(parsed) ? parsed : (parsed.tasks ?? []);
      // impactScope: 鏀寔瀵硅薄鏍煎紡涓庣畝娲佹暟缁勬牸寮廫r
      // 鏁扮粍鏍煎紡鏃?impactScope 瀛楁锛屼粎瀵硅薄鏍煎紡鏀寔
      const impactScope: ImpactScope =
        (!Array.isArray(parsed) && parsed.impactScope === "subtree") ? "subtree" : "local";
      const nodes = items.flatMap((item, i) => this._toTaskNode(item, parentId, i));
      return { nodes, impactScope };
    } catch {
      return { nodes: [this._fallbackNode(raw, parentId)], impactScope: "local" };
    }
  }
}

// 鈹€鈹€鈹€ 绫诲瀷 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

interface PlanItem {
  task: string;
  type?: string;
  tags?: string[];
  needsMultiPerspective?: boolean;
  reasoningEffort?: "high" | "max";
  recommendedTier?: "fast" | "standard" | "thinking";
  children?: PlanItem[];
}

interface PlanContext {
  parentId?: string;
  existingTags?: string[];
}

/** 鎰忓浘纭缁撴灉鈥斺€攃larifyIntent() 杩斿洖 */
export interface IntentClarification {
  goal: string;
  actionType: "analysis" | "modification" | "audit" | "refactor" | "generation" | "inquiry";
  scope: string;
  constraints: string;
  unclear?: string;
  originalIntent: string;
}

// 绯荤粺鎻愮ず宸茶縼绉昏嚦 @cortex/config/constants/meta-agent.ts
// 閫氳繃 buildPlanningSystem(workspaceRoot) / REPLAN_SYSTEM 瀵煎叆浣跨敤

// 鈹€鈹€鈹€ ContextPolicy 鑷姩鍖归厤 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 鏍规嵁浠诲姟绫诲瀷鍜屾爣绛捐嚜鍔ㄩ€夋嫨 ContextPolicy銆俓r
 *
 * 鍖归厤瑙勫垯锛歕r
 *   1. type 绮剧‘鍛戒腑棰勮 ID 鈫?鐩存帴杩斿洖
 *   2. tags 鍖呭惈鐗瑰緛鏍囩 鈫?鍖归厤瀵瑰簲棰勮
 *   3. 鍥為€€ 鈫?"single-step"
 */
function _resolveContextPolicy(type?: string, tags?: string[]): string {
  // 瑙勫垯 1: type 绮剧‘鍛戒腑
  if (type && PRESET_CONTEXT_POLICIES[type]) return type;

  // 瑙勫垯 2: tags 鍖归厤
  if (tags) {
    const tagSet = new Set(tags.map((t) => t.toLowerCase()));
    if (tagSet.has("audit") || tagSet.has("architecture") || tagSet.has("constitution_check")) {
      return "architecture-review";
    }
    if (tagSet.has("debug") || tagSet.has("diagnose") || tagSet.has("bugfix")) {
      return "diagnose";
    }
    if (tagSet.has("code") || tagSet.has("refactor")) {
      return "code-refactor";
    }
  }

  // 瑙勫垯 3: 鍥為€€
  return "single-step";
}

/** 鏍￠獙骞跺綊涓€鍖?recommendedTier锛氶潪娉曞€?鈫?undefined锛岄槻姝㈢敇闆?prompt 婕傜Щ娉ㄥ叆鑴忔暟鎹?*/
const _VALID_TIERS = new Set(["fast", "standard", "thinking"]);
function _validTier(t?: string): "fast" | "standard" | "thinking" | undefined {
  return t && _VALID_TIERS.has(t) ? t as "fast" | "standard" | "thinking" : undefined;
}

