import { type EngineConfig, resolveConfig } from "@cortex/config";

/**
 * Scheduler 鈥斺€?璋冨害寮曟搸銆俓n *
 * 鑱岃矗锛歕n * 1. 鎷撴墤鎺掑簭浠诲姟鏍慭n * 2. 閫愬眰骞惰鍒嗗彂鑺傜偣缁欏尮閰嶇殑 AgentRunner
 * 3. 閫氳繃 PipelineObserver 鍙戝竷鑺傜偣鐢熷懡鍛ㄦ湡浜嬩欢
 * 4. 浜у嚭 ExecutionReport
 *
 * @contract 妯″潡杈圭晫濂戠害锛堜箙宀愬繊 P1-5锛氭ā鍧楄竟鐣岀己灏戞樉寮忓绾﹀寲瀹氫箟 鈫?宸查棴鍚堬級
 *
 * @merge-complete Core-1 璋冨害鍣ㄥ弻瀹炵幇鍚堝苟锛坴2.6.6鈫抳2.6.7锛夛細
 *   CompositeScheduler 鐨勪笁鎶借薄锛圛ScheduleStrategy/ILoopDriver/IExecutionModel/IModelRouter锛塡n *   宸插叏閮ㄥ惛鏀惰繘 Scheduler銆侰ompositeScheduler 绫诲凡浠?@cortex/scheduler 绉婚櫎銆俓n *   schedulerConfig?: CompositeSchedulerConfig 鍙€夊弬鏁颁繚鐣欎笁鎶借薄鍙浛鎹㈡€с€俓n *
 * @depends  task-board.ts锛坈laim/release/complete/failNode/getPendingNodes锛塡n * @depends  agent-pool.ts锛坰pawn/destroy锛屽疄渚嬬敓鍛藉懆鏈燂級
 * @depends  pipeline-observer.ts锛堜簨浠跺彂灏勶紝鍙岄€氶亾 reporter锛塡n * @depends  meta-agent.ts锛堥噸瑙勫垝閫昏緫锛屽彲閫夆€斺€旂己鍒?replanQueue 闈欓粯鎺掔┖锛塡n * @depends  @cortex/shared锛圓gentType, AGENT_TAGS, TaskNode, PipelineEventType 绛夌被鍨嬶級
 * @dataflow Scheduler 鏄皟搴︿腑鏋細TaskBoard(杈撳叆) 鈫?鎷撴墤鎺掑簭 鈫?dispatch 鈫?AgentPool(鎵ц)
 *           鈫?TaskBoard.complete(钀界洏) 鈫?observer.emit(浜嬩欢) 鈫?ExecutionReport(杈撳嚭)
 *           MetaAgent 閫氳繃 replanQueue 鏃佽矾娉ㄥ叆鏂拌妭鐐癸紙棰嗚€屼笉鎵э級锛屼笉鍙備笌涓绘墽琛岃矾寰刓n *
 *   鈹屸攢 Scheduler 鈹€鈹怽n *   鈹? register()  鈹傗梽鈹€鈹€ Agent + Model锛堟瀯閫犳椂娉ㄥ叆锛塡n *   鈹? executeAll()鈹傗攢鈹€鈻?TaskBoard.claim() 鈫?release() 鈫?complete() / failNode()
 *   鈹?             鈹傗攢鈹€鈻?AgentPool.spawn() 鈫?destroy()
 *   鈹?             鈹傗攢鈹€鈻?MetaAgent.requestReplan() 鈫?鏂拌妭鐐瑰叆鏉匡紙棰嗚€屼笉鎵э級
 *   鈹?             鈹傗攢鈹€鈻?PipelineObserver.emit()锛堝弻閫氶亾锛歰bserver + console锛塡n *   鈹斺攢鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹榎n *
 *   鍓嶇疆鏉′欢锛歕n *   - TaskBoard 宸插～鍏呰妭鐐癸紙鑷冲皯涓€涓?pending锛塡n *   - AgentPool 宸叉敞鍐?Runner锛坮egister() 鎴栫洿鎺ユ敞鍏?agents Map锛塡n *   - PipelineObserver 宸叉瀯寤猴紙constructor 娉ㄥ叆锛岄潪 null锛塡n *   - MetaAgent 鍙€夛紙缂哄垯閲嶈鍒掗槦鍒楅潤榛樻帓绌猴級
 *
 *   鍚庣疆鏉′欢锛歕n *   - ExecutionReport 瀹屾暣锛坱otalNodes/completed/failed/results/durationMs锛塡n *   - 鎵€鏈夎妭鐐圭粓鎬佷负 done 鎴?failed锛堟棤 pending/claimed 娈嬬暀锛塡n *   - Pool 瀹炰緥宸插叏閮?destroy锛坰pawn 瀵圭瓑閲婃斁锛塡n *
 *   寮傚父璇箟锛歕n *   - executeAll() 鍗曡疆寮傚父涓嶅穿婧冿細鏍囪褰撳墠 pending 涓?failed锛屼笂鎶?SchedulerLoopCrashed锛宐reak 杩斿洖宸叉湁缁撴灉
 *   - execute() 鎶涘紓甯革細涓嶉樆鏂?complete 钀界洏
 *   - destroy() 鎶涘紓甯革細涓婃姤 PoolDestroyFailed锛屼笉闃绘柇
 *
 * **璁㈤槄鑰呮敞鍐?*锛歅ipelineObserver 鐨勮闃呰€咃紙Sentinel/MemoryStore/绠″锛塡n * 鐢?bootstrap 鍏ュ彛鐐瑰湪 Scheduler 鏋勯€犲墠娉ㄥ唽锛屼笉鍦?Scheduler 鍐呴儴闅愬紡娉ㄥ唽銆俓n * 璁㈤槄绾﹀畾瑙?PipelineObserver.emit() 娉ㄩ噴銆俓n */
export class Scheduler implements IScheduler {
  private agents = new Map<string, Agent>();
  private models = new Map<string, string>();
  private readonly replanManager: ReplanManager;
  private readonly config: Required<EngineConfig>;
  // 鍥涙娊璞＄粍浠讹紙榛樿琛屼负涓庡師 Scheduler 瀹屽叏涓€鑷达級
  readonly strategy: IScheduleStrategy;
  readonly loopDriver: ILoopDriver;
  readonly executionModel: IExecutionModel;
  readonly modelRouter: IModelRouter;
  /** 褰撳墠杩愯浼氳瘽鏍囪瘑鈥斺€攅xecuteAll() 鍚姩鏃剁敓鎴?*/
  private _sessionId?: string;
  /** MemoryStore 寮曠敤鈥斺€旂敤浜?beginSession/endSession 鐢熷懡鍛ㄦ湡绠＄悊 */
  private _memoryStore?: IMemoryStore;

  constructor(
    private readonly board: ITaskBoard,
    private readonly pool: ISchedulerAgentPool,
    private readonly observer: IPipelineObserver,
    private readonly metaAgent?: MetaAgent,
    engineConfig?: EngineConfig,
    schedulerConfig?: CompositeSchedulerConfig,
  ) {
    this.config = resolveConfig(engineConfig);
    this.replanManager = new ReplanManager(board, observer, metaAgent ? new MetaAgentReplanAdapter(metaAgent) : undefined, this.config);
    this.strategy = schedulerConfig?.strategy ?? new TagMatchingStrategy();
    this.loopDriver = schedulerConfig?.loopDriver ?? new TopologicalLayeredDriver();
    this.executionModel = schedulerConfig?.executionModel ?? new PipelineModel();
    this.modelRouter = schedulerConfig?.modelRouter ?? new FixedModelRouter();
  }

  /** 娉ㄥ唽涓€涓?AgentRunner 鍙婂叾鎵€鐢ㄦā鍨?*/
  register(agentType: string, agent: Agent, model: string): void {
    this.agents.set(agentType, agent);
    this.models.set(agentType, model);
  }

  /** 娉ㄥ叆 MemoryStore鈥斺€旂敤浜?executeAll() 鐨?sessionId 鐢熷懡鍛ㄦ湡绠＄悊 */
  setMemoryStore(memory: IMemoryStore): void {
    this._memoryStore = memory;
  }

  /** 鏋勫缓 RLM 鎷嗚В鐢ㄧ殑 LLM 璋冪敤鍏ュ彛銆備粠 MetaAgent 鐨?LlmAdapter 妗ユ帴銆?*/
  private _buildLlmChat(): LlmCallable | undefined {
    const adapter = this.metaAgent?.llmAdapter;
    if (!adapter) return undefined;
    return async (model: string, messages: Array<{ role: string; content: string }>) => {
      const res = await adapter.chat(model, messages as Parameters<typeof adapter.chat>[1]);
      return res.content ?? "";
    };
  }

  /**
   * 鎵ц TaskBoard 涓婂叏閮ㄨ妭鐐广€俓n   * 鍔ㄦ€佹秷璐规ā寮忥細鍙鏈?pending/claimed 鑺傜偣灏辩户缁嫇鎵戞帓搴?+ 閫愬眰骞惰鎵ц銆俓n   * 姣忚疆鎵ц鍚庡鐞?replanQueue锛孧etaAgent 浜у嚭鏂拌妭鐐逛粎鍏ユ澘涓嶆墽琛屸€斺€擻n   * 鐢变笅涓€杞惊鐜粺涓€璋冨害锛圽

锛夈€俓n   */
  async executeAll(): Promise<ExecutionReport> {
    const startTime = Date.now();
    // v2.5.41: 鐢熸垚 sessionId鈥斺€旀瘡娆?executeAll() 鍞竴鏍囪瘑锛屾敞鍏?MetaAgent 绠＄嚎涓婁笅鏂嘰n    this._sessionId = `run-${startTime}-${Math.random().toString(36).slice(2, 8)}`;
    // 婵€娲?MemoryStore 浼氳瘽鈥斺€斿悗缁?write/writePending 鑷姩娉ㄥ叆姝?sessionId
    this._memoryStore?.beginSession(this._sessionId);

    // 鏋勫缓 LoopContext锛屾敞鍏?dispatchNode 淇濈暀瀹屾暣 RLM 鎷嗚В绠＄嚎
    const loopCtx: LoopContext = {
      board: this.board,
      pool: this.pool,
      observer: this.observer,
      agents: this.agents,
      models: this.models,
      replanProvider: this.metaAgent ? new MetaAgentReplanAdapter(this.metaAgent) : undefined,
      replanManager: this.replanManager,
      config: this.config,
      strategy: this.strategy,
      executionModel: this.executionModel,
      modelRouter: this.modelRouter,
      dispatchNode: (node) => this._dispatchNode(node.id),
    };

    const loopResult = await this.loopDriver.run(loopCtx);

    // MemoryStore endSession 宸茶縼绉昏嚦 ShutdownWarden锛堢粺涓€绠＄悊 shutdown 鐢熷懡鍛ㄦ湡锛塡n
    const durationMs = Date.now() - startTime;
    const allNodes = this.board.getAllNodes();

    return {
      totalNodes: allNodes.length,
      completed: loopResult.completed,
      failed: loopResult.failed,
      results: loopResult.results,
      durationMs,
      sessionId: this._sessionId,
    };
  }

  private async _dispatchNode(nodeId: string): Promise<NodeResult> {
    const node = this.board.getNode(nodeId);
    if (!node) {
      return { nodeId, success: false, error: "Node not found" };
    }

    this.observer.emit({
      type: PipelineEventType.NodeStart,
      priority: PipelinePriority.HIGH,
      payload: { nodeId, type: node.type },
      timestamp: Date.now(),
      notificationType: "FYI",
    });

    let result: NodeResult;
    try {
      if (node.needsMultiPerspective) {
        result = await this._dispatchMulti(node);
      } else {
        result = await this._dispatchSingle(node);
      }
    } catch (e) {
      result = {
        nodeId,
        success: false,
        error: String(e),
      };
    }

    if (!result.success) {
      const reason = result.output ?? result.error ?? "unknown";
      this.replanManager.enqueue(node, reason);
    }

    if (!result.success) {
      this.observer.emit({
        type: PipelineEventType.NodeFailed,
        priority: PipelinePriority.CRITICAL,
        payload: { nodeId, error: result.error ?? "unknown" },
        timestamp: Date.now(),
        notificationType: "WARNING",
      });
    }

    return result;
  }

  /**
   * 鎸夐『搴忔墽琛?IDispatchStep 鏁扮粍銆俓n   * - 闈?Cleanup 姝ラ杩斿洖澶辫触缁撴灉鏃剁珛鍗崇粓姝紝浣嗕粛杩愯 CleanupStep
   *   纭繚 board.complete() 钀界洏 + pool.destroy() 閲婃斁锛岄槻姝㈣妭鐐瑰崱 claimed 鐘舵€併€俓n   * - CleanupStep 濮嬬粓杩愯锛堜繚璇佹睜閿€姣?+ 钀界洏锛塡n   * @fix P0-1: 闈?Cleanup 姝ラ澶辫触鍚庝粛鎵ц CleanupStep锛屾秷闄?double-counted 涓?NodeFailed 閲嶅鍙戝皠
   */
  private async _runDispatchPipeline(ctx: DispatchCtx, steps: IDispatchStep[]): Promise<NodeResult> {
    for (const step of steps) {
      ctx = await step.run(ctx);
      if (ctx.result && !ctx.result.success && step.name !== "Cleanup") {
        // 澶辫触鏃朵粛杩愯 CleanupStep锛堟渶鍚庝竴姝ワ級浠ョ‘淇濊惤鐩橀噴鏀綷n        // 鍏跺唴閮?guard (!agentType || !instanceId || !result) 淇濊瘉鍓嶇疆鏉′欢涓嶆弧瓒虫椂瀹夊叏 no-op
        const result = ctx.result;
        const lastStep = steps[steps.length - 1];
        if (lastStep.name === "Cleanup") {
          await lastStep.run(ctx);
        }
        return result;
      }
    }
    return ctx.result ?? { nodeId: ctx.node.id, success: false, error: "Dispatch completed without result" };
  }

  /** 鍗曡瑙掕妭鐐癸細Claim 鈫?Spawn 鈫?[SkillInjection] 鈫?Execute 鈫?Cleanup */
  private async _dispatchSingle(node: TaskNode): Promise<NodeResult> {
    const ctx: DispatchCtx = {
      agents: this.agents,
      models: this.models,
      board: this.board,
      pool: this.pool,
      observer: this.observer,
      isTestEnv: isTestEnv(),
      node,
      llmChat: this._buildLlmChat(),
      modelRouter: this.modelRouter,
    };

    const steps: IDispatchStep[] = [
      new ClaimStep(),
      new SpawnStep(this.config.manifoldGateAcquireTimeoutMs),
      new RlmExecuteStep(),
      new BoundaryGuardStep(),
      new CleanupStep(),
    ];

    return await this._runDispatchPipeline(ctx, steps);
  }

  /** 澶氳瑙掕妭鐐癸細鎵€鏈夊尮閰?Agent 骞惰鎵ц Claim 鈫?Spawn 鈫?Execute 鈫?Cleanup */
  private async _dispatchMulti(node: TaskNode): Promise<NodeResult> {
    const agentTypes = findAllMatchingAgents(this.agents, node);

    if (agentTypes.length === 0) {
      this.board.failNode(node.id);
      return {
        nodeId: node.id,
        success: false,
        error: `No agents match multi-perspective node ${node.id}`,
      };
    }

    const promises = agentTypes.map(async (at) => {
      const agent = this.agents.get(at);
      if (!agent) return null;

      if (agent.status !== AgentStatus.Awake && agent.status !== AgentStatus.Active) return null;

      const innerCtx: DispatchCtx = {
        agents: this.agents,
        models: this.models,
        board: this.board,
        pool: this.pool,
        observer: this.observer,
        isTestEnv: isTestEnv(),
        node,
        agentType: at,
        agent,
        llmChat: this._buildLlmChat(),
        modelRouter: this.modelRouter,
      };

      const claimed = this.board.claim(node.id, at as AgentType);
      if (!claimed) return null;

      innerCtx.model = this.models.get(at) ?? "mock";

      const steps: IDispatchStep[] = [
        new SpawnStep(this.config.manifoldGateAcquireTimeoutMs),
        new RlmExecuteStep(),
        new BoundaryGuardStep(),
        new CleanupStep(),
      ];

      return await this._runDispatchPipeline(innerCtx, steps);
    });

    const results = (await Promise.all(promises)).filter((r): r is NonNullable<typeof r> => r !== null);

    if (results.length > 0) {
      const currentNode = this.board.getNode(node.id);
      if (currentNode && currentNode.status !== "failed") {
        const resultTypes = new Set(results.map((r) => r.agentType).filter((t): t is AgentType => t != null));
        for (const at of currentNode.claimedBy) {
          if (!resultTypes.has(at)) {
            this.observer.emit({
              type: PipelineEventType.SchedulerInvariantViolation,
              priority: PipelinePriority.CRITICAL,
              payload: {
                nodeId: node.id,
                message: `claimedBy 涓?${at} 鏃犲搴?result 鈥?claimedBy=[${currentNode.claimedBy}], results=[${[...resultTypes]}]`,
              },
              timestamp: Date.now(),
            });
          }
        }
      }
    }

    if (results.length === 0) {
      this.board.failNode(node.id);
      return {
        nodeId: node.id,
        success: false,
        error: "All agents failed to claim multi-perspective node",
      };
    }

    const combined = results.map((r) => `[${r.agentType}] ${r.output ?? r.error}`).join("\n");
    const allSuccess = results.every((r) => r.success);

    // @fix P0-3: 閮ㄥ垎瑙嗚 spawn 澶辫触鏃讹紙濡?pool 鑰楀敖 鈫?release锛夛紝鍏朵綑瑙嗚鎴愬姛鍚嶾n    //   board.complete() 宸插皢鑺傜偣缃负 done銆備互 board 缁堟€佷负鍑嗭紝鑰岄潪鏈烘鑱氬悎 allSuccess銆俓n    const finalNode = this.board.getNode(node.id);
    const isDone = finalNode?.status === "done";

    if (isDone) {
      this.observer.emit({
        type: PipelineEventType.NodeComplete,
        priority: PipelinePriority.HIGH,
        payload: {
          nodeId: node.id,
          agentType: agentTypes[0] as AgentType,
          success: true as const,
          output: combined,
          perspectives: results.map((r) => r.agentType),
          allSuccess: true,
        },
        timestamp: Date.now(),
      });
    }

    return {
      nodeId: node.id,
      agentType: agentTypes[0] as AgentType,
      success: isDone || allSuccess,
      output: combined,
    };
  }
}

// ============================================================
// @cortex/engine/core/shutdown-warden 鈥斺€?浼橀泤鍏抽棴鐩戞姢
//
// @since v3.1.0
// @layer 寮曟搸灞?鈥?缂栨帓 shutdown 椤哄簭锛岀鐞嗚祫婧愭硠婕忔姤鍛奬r
//
// 鑱岃矗锛歕r
//   1. 绠＄悊寮曟搸缁勪欢锛團ileLockManager / Scheduler / MemoryStore锛夌殑 shutdown 椤哄簭
//   2. 瓒呮椂寮哄埗缁堟 + 璧勬簮娉勬紡鎶ュ憡
//   3. 纭繚 MemoryStore.endSession() 鍦?Scheduler 閫€鍑哄悗璋冪敤
//
// 浠?scheduler.ts 鎷嗗垎 endSession() 璋冪敤閫昏緫銆俓r
// ============================================================

import type { IMemoryStore, IPipelineObserver } from "@cortex/shared";
import type { LifecycleManager } from "../lifecycle/lifecycle-manager.js";
import {
  SHUTDOWN_TIMEOUT_MS,
  SHUTDOWN_FORCE_EXIT_DELAY_MS,
} from "../config/engine-defaults.js";

/** Shutdown 闃舵鎶ュ憡 */
export interface ShutdownReport {
  /** stop 闃舵鑰楁椂 (ms) */
  stopDurationMs: number;
  /** 鏈甯稿叧闂殑缁勪欢 */
  failedComponents: string[];
  /** endSession 鏄惁鎴愬姛 */
  endSessionDone: boolean;
  /** 寮哄埗閫€鍑哄欢杩?(ms) */
  forceExitDelayMs: number;
}

/**
 * ShutdownWarden 鈥斺€?寮曟搸浼橀泤鍏抽棴鐩戞姢銆俓r
 *
 * 缂栨帓 shutdown 椤哄簭锛歕r
 *   1. Scheduler 瀹屾垚杩涜涓殑浠诲姟
 *   2. LifecycleManager.shutdown() 鈥?鍙嶅悜 stop + dispose 鎵€鏈?ILifecycle 缁勪欢
 *   3. MemoryStore.endSession() 鈥?褰掓。 Active 璁板繂锛屾巩鐏?Pending 璁板繂
 *   4. MemoryStore.close() 鈥?閲婃斁瀛樺偍杩炴帴
 *   5. 璧勬簮娉勬紡鎶ュ憡
 *
 * @example
 * ```typescript
 * const warden = new ShutdownWarden(lifecycleManager, memory, observer);
 * const report = await warden.shutdown();
 * ```
 */
export class ShutdownWarden {
  private readonly lifecycleManager: LifecycleManager;
  private readonly memory?: IMemoryStore;
  private readonly observer?: IPipelineObserver;
  private readonly timeoutMs: number;
  private readonly forceExitDelayMs: number;

  constructor(
    lifecycleManager: LifecycleManager,
    memory?: IMemoryStore,
    observer?: IPipelineObserver,
    timeoutMs: number = SHUTDOWN_TIMEOUT_MS,
    forceExitDelayMs: number = SHUTDOWN_FORCE_EXIT_DELAY_MS,
  ) {
    this.lifecycleManager = lifecycleManager;
    this.memory = memory;
    this.observer = observer;
    this.timeoutMs = timeoutMs;
    this.forceExitDelayMs = forceExitDelayMs;
  }

  /**
   * 鎵ц瀹屾暣 shutdown 搴忓垪銆俓r
   *
   * @returns ShutdownReport 鍖呭惈鍚勯樁娈佃€楁椂鍜屽け璐ヤ俊鎭痋r
   */
  async shutdown(): Promise<ShutdownReport> {
    const stopStart = Date.now();
    const failedComponents: string[] = [];
    let endSessionDone = false;

    // Phase 1: LifecycleManager 鍙嶅悜鍏抽棴鎵€鏈?ILifecycle 缁勪欢
    try {
      await this.lifecycleManager.shutdown();
    } catch (e) {
      failedComponents.push(`lifecycleManager: ${String(e)}`);
    }

    // Phase 2: MemoryStore endSession锛堝綊妗?+ 婀伃锛塡r
    if (this.memory) {
      try {
        await this.memory.endSession();
        endSessionDone = true;
      } catch {
        failedComponents.push("memoryStore.endSession");
      }

      // Phase 3: MemoryStore close
      try {
        await this.memory.close();
      } catch {
        failedComponents.push("memoryStore.close");
      }
    }

    const stopDurationMs = Date.now() - stopStart;

    // Phase 4: 璧勬簮娉勬紡鎶ュ憡
    if (failedComponents.length > 0 && this.observer) {
      // observer emit would go here if needed
    }

    // 缁欏紓姝ユ棩蹇?IO 涓€浜涙椂闂碶r
    if (failedComponents.length > 0 && this.forceExitDelayMs > 0) {
      await delay(this.forceExitDelayMs);
    }

    return {
      stopDurationMs,
      failedComponents,
      endSessionDone,
      forceExitDelayMs: failedComponents.length > 0 ? this.forceExitDelayMs : 0,
    };
  }
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// ============================================================
// @cortex/engine/lifecycle/lifecycle-manager 鈥斺€?鐢熷懡鍛ㄦ湡缂栨帓鍣╘r
//
// @since v3.1.0
// @constitutional 搂9.1 鈥?鏍囧噯缁勪欢鐢熷懡鍛ㄦ湡
//
// 鑱岃矗锛歕r
//   1. 娉ㄥ唽鎵€鏈?ILifecycle 缁勪欢鍙婃嫇鎵戜緷璧朶r
//   2. bootstrap() 鈫?鎸変緷璧栭『搴?init + start
//   3. shutdown() 鈫?鍙嶅悜椤哄簭 stop + dispose锛岃秴鏃跺己鍒剁粓姝r
// ============================================================

import {
  type ILifecycle,
} from "@cortex/shared";
import {
  SHUTDOWN_TIMEOUT_MS,
  SHUTDOWN_FORCE_EXIT_DELAY_MS,
} from "../config/engine-defaults.js";

/** 缁勪欢娉ㄥ唽椤?*/
interface Registration {
  component: ILifecycle;
  name: string;
  deps: string[];
}

/** 鐢熷懡鍛ㄦ湡浜嬩欢鐩戝惉鍣?*/
export type LifecycleListener = (
  event: "bootstrap_done" | "shutdown_start" | "shutdown_done" | "shutdown_timeout" | "component_error",
  detail: { component?: string; error?: string },
) => void;

/**
 * LifecycleManager 鈥斺€?鏍囧噯鍖栫敓鍛藉懆鏈熺紪鎺掋€俓r
 *
 * 浣跨敤绀轰緥锛歕r
 * ```typescript
 * const lm = new LifecycleManager();
 * lm.register(fileLockManager, "fileLock");
 * lm.register(memoryStore, "memoryStore", ["fileLock"]);
 * lm.register(scheduler, "scheduler", ["memoryStore"]);
 * await lm.bootstrap();
 * // ... 搴旂敤杩愯 ...
 * await lm.shutdown();
 * ```
 */
export class LifecycleManager {
  private _registrations = new Map<string, Registration>();
  private _listeners: LifecycleListener[] = [];
  private _bootstrapped = false;
  private _shuttingDown = false;

  /**
   * 娉ㄥ唽缁勪欢銆俓r
   * @param component ILifecycle 缁勪欢
   * @param name 鍞竴鍚嶇О
   * @param deps 渚濊禆鐨勭粍浠跺悕绉板垪琛紙杩欎簺缁勪欢蹇呴』鍏堝惎鍔級
   */
  register(component: ILifecycle, name: string, deps: string[] = []): void {
    if (this._registrations.has(name)) {
      throw new Error(`[LifecycleManager] 閲嶅娉ㄥ唽: ${name}`);
    }
    for (const dep of deps) {
      if (!this._registrations.has(dep)) {
        throw new Error(
          `[LifecycleManager] 渚濊禆鏈敞鍐? ${name} 鈫?${dep}`,
        );
      }
    }
    this._registrations.set(name, { component, name, deps });
  }

  /** 娣诲姞鐢熷懡鍛ㄦ湡浜嬩欢鐩戝惉鍣?*/
  on(listener: LifecycleListener): void {
    this._listeners.push(listener);
  }

  /** 鎸夋嫇鎵戦『搴?bootstrap锛坕nit 鈫?start锛?*/
  async bootstrap(): Promise<void> {
    if (this._bootstrapped) return;
    const order = this._topologicalSort();

    for (const reg of order) {
      try {
        await reg.component.init();
      } catch (e) {
        this._emit("component_error", {
          component: reg.name,
          error: `init 澶辫触: ${String(e)}`,
        });
        throw e;
      }
    }

    for (const reg of order) {
      try {
        await reg.component.start();
      } catch (e) {
        this._emit("component_error", {
          component: reg.name,
          error: `start 澶辫触: ${String(e)}`,
        });
        throw e;
      }
    }

    this._bootstrapped = true;
    this._emit("bootstrap_done", {});
  }

  /** 鍙嶅悜鎷撴墤椤哄簭 shutdown锛坰top 鈫?dispose锛夛紝瓒呮椂寮哄埗缁堟 */
  async shutdown(): Promise<void> {
    if (!this._bootstrapped || this._shuttingDown) return;
    this._shuttingDown = true;
    this._emit("shutdown_start", {});

    const order = this._topologicalSort().reverse();
    const results: { name: string; success: boolean; error?: string }[] = [];

    // 浼橀泤鍋滄锛堝甫瓒呮椂锛塡r
    const stopStart = Date.now();
    for (const reg of order) {
      try {
        await withTimeout(
          reg.component.stop(),
          SHUTDOWN_TIMEOUT_MS,
          `[LifecycleManager] stop 瓒呮椂: ${reg.name}`,
        );
        results.push({ name: reg.name, success: true });
      } catch (e) {
        results.push({
          name: reg.name,
          success: false,
          error: String(e),
        });
        this._emit("component_error", {
          component: reg.name,
          error: `stop 澶辫触: ${String(e)}`,
        });
      }
    }
    const stopDuration = Date.now() - stopStart;

    // 绔嬪嵆閲婃斁锛堜笉璁捐秴鏃讹紝dispose 涓嶆姏閿欙級
    for (const reg of order) {
      try {
        reg.component.dispose();
      } catch {
        // dispose 涓嶆姏閿橽r
      }
    }

    // 鎶ュ憡鏈垚鍔熷叧闂殑缁勪欢
    const failed = results.filter((r) => !r.success);
    if (failed.length > 0) {
      this._emit("shutdown_timeout", {
        error: `${failed.length} 涓粍浠舵湭姝ｅ父鍏抽棴: ${failed.map((f) => f.name).join(", ")}`,
      });
      // 缁欏紓姝ユ棩蹇?IO 涓€鐐规椂闂碶r
      await delay(SHUTDOWN_FORCE_EXIT_DELAY_MS);
    }

    this._emit("shutdown_done", {
      error: `stop 鑰楁椂 ${stopDuration}ms, ${failed.length} 鏈甯稿叧闂璥,
    });
  }

  /** 鎷撴墤鎺掑簭锛歞eps 鍑虹幇鍦ㄦ敞鍐岄」涔嬪墠 */
  private _topologicalSort(): Registration[] {
    const visited = new Set<string>();
    const result: Registration[] = [];
    const recStack = new Set<string>();

    const visit = (name: string): void => {
      if (visited.has(name)) return;
      if (recStack.has(name)) {
        throw new Error(`[LifecycleManager] 寰幆渚濊禆: ${name}`);
      }
      recStack.add(name);
      const reg = this._registrations.get(name);
      if (!reg) throw new Error(`[LifecycleManager] 鏈敞鍐? ${name}`);
      for (const dep of reg.deps) {
        visit(dep);
      }
      recStack.delete(name);
      visited.add(name);
      result.push(reg);
    };

    for (const name of this._registrations.keys()) {
      visit(name);
    }

    return result;
  }

  private _emit(
    event: "bootstrap_done" | "shutdown_start" | "shutdown_done" | "shutdown_timeout" | "component_error",
    detail: { component?: string; error?: string },
  ): void {
    for (const l of this._listeners) {
      try { l(event, detail); } catch { /* 鐩戝惉鍣ㄥ紓甯镐笉褰卞搷涓绘祦绋?*/ }
    }
  }
}

/** 甯﹁秴鏃剁殑 Promise */
function withTimeout<T>(
  promise: Promise<T>,
  ms: number,
  timeoutMsg: string,
): Promise<T> {
  if (ms <= 0) return promise;
  return Promise.race([
    promise,
    new Promise<T>((_, reject) =>
      setTimeout(() => reject(new Error(timeoutMsg)), ms),
    ),
  ]);
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

