/**
 * 璁板繂妫€绱㈡煡璇㈠伐鍘傚嚱鏁扳€斺€旂粺涓€鍏ュ彛銆俓r
 *
 * 11 涓?Agent 鐨勫叧閿瘝鎻愬彇鍏ㄩ儴鏀舵暃鑷虫澶勶紝鍚?Agent 浠呴渶鎸囧畾宸紓鍖栧弬鏁癨r
 * 锛坘ind / linkTypes / bfsDepth / limit锛夈€俓r
 */
export function makeMemoryQuery(
  node: TaskNode,
  opts: {
    kind?: MemoryKind;
    linkTypes?: LinkType[];
    bfsDepth?: number;
    bfsMaxNodes?: number;
    limit?: number;
    bfsDirection?: 'both' | 'outbound';
  },
): MemoryQuery {
  const payload = node.payload;
  const keywords: string[] = [];

  // 1. CJK 2-gram锛堜腑鏃ラ煩缁熶竴姹夊瓧鍖猴級
  const cjkChars = payload.replace(/[^涓€-榭裤悁-涠縘/g, "");
  for (let i = 0; i <= cjkChars.length - 2; i++) {
    keywords.push(cjkChars.slice(i, i + 2));
  }

  // 2. 鎷変竵璇嶏紙鑻辨枃/鏁板瓧/涓嬪垝绾跨瓑锛岄暱搴?> 3 鎵嶄繚鐣欙級
  const latinWords = payload.split(/\s+/).filter((w) => w.length > 3);
  keywords.push(...latinWords);

  return {
    keywords,
    kind: opts.kind,
    linkTypes: opts.linkTypes,
    bfsDepth: opts.bfsDepth ?? 2,
    bfsMaxNodes: opts.bfsMaxNodes ?? 20,
    limit: opts.limit ?? 3,
    bfsDirection: opts.bfsDirection ?? 'outbound',
  };
}

