    systemPrompt: ctx.systemPrompt,
    maxLoops: ctx.maxLoops,
    reactLoopTimeoutMs: ctx.reactLoopTimeoutMs ?? 300_000,
    model,
    memory: ctx.memory,
    safeReporter: safeReporter ?? ctx.safeReporter,
    filterRead,
    memoryQuery,
    node,
  };

  const steps = customSteps ?? DEFAULT_PIPELINE;
