bugfix" || node.type === "refactor";

  const content: Record<string, unknown> = {
    taskType: node.type,
    entities: node.tags,
    decision: result.output ?? (result.error ?? ""),
    outcome: isSuccess ? "success" : "failure",
  };
  if (isFix) {
    content.pitfall = node.payload.slice(0, 300);
  }
  if (!isSuccess) {
    content.lesson = `${agentType} 鎵ц ${node.type} 澶辫触銆傞敊璇? ${(result.error ?? "unknown").slice(0, 300)}`;
  } else if (isFix) {
    content.lesson = `${agentType} successfully fixed a ${node.type}. The original error context is preserved above.`;
  }

  // v3: semantic_gist = summary锛堟殏浠?summary 澶嶅埢锛屽悗缁敱 LLM 钀冨彇澧炲己锛塡r
  const mainSummary = isSuccess
    ? `[${isFix ? "淇璁板綍" : "瀹屾垚"}] ${agentType} 脳 ${node.type}: ${node.payload.slice(0, 120)}`
    : `[澶辫触鏁欒] ${agentType} 脳 ${node.type}: ${(result.error ?? "unknown").slice(0, 120)}`;

  const source = { agentType, taskId: node.id };

