    }
  } catch (memErr) {
    try { if (memId !== undefined) memory.cas(memId, "Active", "Archived"); } catch { /* 闈欓粯 */ }
    try { if (ctxMemId !== undefined) memory.cas(ctxMemId, "Active", "Archived"); } catch { /* 闈欓粯 */ }

    const hint = `浠诲姟 ${node.id} 宸?{isSuccess ? "鎴愬姛" : "澶辫触"}瀹屾垚锛屼絾璁板繂鍐欏叆澶辫触锛屽崐鎴愬搧 Pending 鏉＄洰宸叉竻鐞哷;
    if (safeReporter) {
      safeReporter({
        source: `${agentType}.executeWithMemoryPipeline._rememberResult`,
        error: memErr,
        severity: "degraded",
        hint,
      });
    }
  }
}

