/**
 * SkillPipeline 鈥斺€?鎶€鑳芥彁鍙栦笌鎸佷箙鍖栫閬擄紙Core-1 鎶€鑳介棴鐜級銆俓n *
 * 浠?Agent 鑺傜偣杈撳嚭涓彁鍙栨妧鑳芥ā鏉匡紝娉ㄥ唽鍒?SkillRegistry锛堝唴瀛橈級锛孿n * 骞舵寔涔呭寲鍒?MemoryStore锛圫QLite锛夛紝瀹炵幇璺ㄨ疆娆¤鐭ュ鐢ㄣ€俓n *
 * 鎻愬彇澶辫触涓嶉樆濉炶皟搴︹€斺€旈€氳繃 PipelineObserver 涓婃姤璇婃柇淇℃伅銆俓n *
 * @since 鎶€鑳芥矇娣€鏈哄埗 Core-1
 *
 * @fix D2 鈥?SkillRegistry 绫诲瀷浠?@cortex/shared 鏀逛负浠庢湰鍦?../skill-registry.js 瀵煎叆銆俓n *   SkillRegistry 绫荤殑瀹炵幇宸蹭粠 shared 绉诲叆 engine锛宻hared 浠呬繚鐣?SerializedSkillRegistry 绫诲瀷銆俓n */
import { PipelineEventType, PipelinePriority, type AgentType, type IMemoryStore, type IPipelineObserver, type PipelineHandler, type SkillTemplate } from "@cortex/shared";
import type { SkillRegistry } from "../registry/skill-registry.js";
import type { MemoryStore } from "@cortex/memory-store"; // for cast only
import { extractSkillsFromOutput, persistSkillsToMemory } from "../components/index.js";

// 鈹€鈹€鈹€ 鎶€鑳藉弬鐓т簨浠跺彂灏?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 褰撴妧鑳借鏌ヨ/鍖归厤鍒版煇涓妭鐐规椂锛屽悜绠＄嚎鍙戝皠 SkillReferenced 浜嬩欢銆俓n *
 * 杩欐槸鎶€鑳藉彲瑙傛祴鎬х殑鏍稿績锛氳褰昞

鈥斺€擻n * 鐙珛浜?Agent 鏄惁瀹為檯閲囦俊銆備簨鍚庣粨鍚?NodeComplete 缁撴灉鍗冲彲鍥炴帹鏁堢敤銆俓n *
 * @param observer     鍙娴嬬閬揬n * @param matchedSkills 閫氳繃 queryByTags 鍖归厤鍒扮殑鎶€鑳藉垪琛╘n * @param nodeId       浠诲姟鑺傜偣 ID
 * @param agentType    鎵ц Agent 绫诲瀷
 */
export function emitSkillReferenced(
  observer: IPipelineObserver,
  matchedSkills: SkillTemplate[],
  nodeId: string,
  agentType: AgentType,
): void {
  for (const skill of matchedSkills) {
    observer.emit({
      type: PipelineEventType.SkillReferenced,
      priority: PipelinePriority.NORMAL,
      payload: {
        nodeId,
        agentType,
        skillId: skill.id,
        skillName: skill.name,
      },
      timestamp: Date.now(),
    });
  }
}

/**
 * 浠?Agent 杈撳嚭涓皾璇曟彁鍙栨妧鑳戒娇鐢ㄥ０鏄庛€俓n *
 * Agent 鍙互鍦ㄨ緭鍑轰腑澹版槑浣跨敤浜嗗摢浜涙妧鑳芥楠わ紝鏍煎紡锛歕n *   [鎶€鑳藉弬鐓? skillName] used=[0,1,2] skipped=[3] adaptation="..."
 *
 * @returns 鎻愬彇鍒扮殑浣跨敤淇℃伅锛屽け璐ヨ繑鍥?null
 */
export function extractSkillUsageFromOutput(output: string): Array<{
  skillName: string;
  stepsUsed?: number[];
  stepsSkipped?: number[];
  adaptation?: string;
}> | null {
  const pattern = /\[鎶€鑳藉弬鐓?\s*([^\]]+)\]\s*used=\[([^\]]*)\]\s*skipped=\[([^\]]*)\]\s*adaptation="([^"]*)"/g;
  const results: Array<{ skillName: string; stepsUsed?: number[]; stepsSkipped?: number[]; adaptation?: string }> = [];
  let match: RegExpExecArray | null;
  while ((match = pattern.exec(output)) !== null) {
    const used = match[2] ? match[2].split(",").map(Number).filter((n) => !isNaN(n)) : undefined;
    const skipped = match[3] ? match[3].split(",").map(Number).filter((n) => !isNaN(n)) : undefined;
    results.push({
      skillName: match[1].trim(),
      stepsUsed: used && used.length > 0 ? used : undefined,
      stepsSkipped: skipped && skipped.length > 0 ? skipped : undefined,
      adaptation: match[4] || undefined,
    });
  }
  return results.length > 0 ? results : null;
}

/**
 * 浠庤妭鐐硅緭鍑轰腑鎻愬彇鎶€鑳藉苟娉ㄥ唽+鎸佷箙鍖栥€俓n *
 * @returns 鎴愬姛娉ㄥ唽鐨勬妧鑳芥ā鏉挎暟缁勩€俓n */
export function extractAndPersistSkills(
  skillRegistry: SkillRegistry,
  memoryStore: IMemoryStore | undefined,
  observer: IPipelineObserver,
  nodeId: string,
  agentType: AgentType,
  output: string,
): SkillTemplate[] {
  const { skills, diagnostics } = extractSkillsFromOutput(output);

  for (const diag of diagnostics) {
    observer.emit({
      type: PipelineEventType.NodeComplete,
      priority: PipelinePriority.NORMAL,
      payload: {
        nodeId,
        agentType: agentType as string,
        success: true,
        output: `[skill-extractor] ${diag}`,
      },
      timestamp: Date.now(),
    });
  }

  if (skills.length === 0) return [];

  const registered: SkillTemplate[] = [];
  for (const skill of skills) {
    try {
      skillRegistry.register(skill);
      registered.push(skill);
    } catch (e) {
      observer.emit({
        type: PipelineEventType.ErrorReported,
        priority: PipelinePriority.HIGH,
        payload: {
          source: `skill-pipeline.extractAndPersistSkills.${nodeId}`,
          severity: "degraded",
          error: `娉ㄥ唽鎶€鑳?${skill.id} 澶辫触: ${String(e).slice(0, 200)}`,
        },
        timestamp: Date.now(),
        notificationType: "WARNING",
      });
    }
  }

  if (registered.length > 0) {
    observer.emit({
      type: PipelineEventType.NodeComplete,
      priority: PipelinePriority.NORMAL,
      payload: {
        nodeId,
        agentType: agentType as string,
        success: true,
        output: `[skill-extractor] 鎴愬姛娉ㄥ唽 ${registered.length}/${skills.length} 涓妧鑳芥ā鏉? ${registered.map((s) => `${s.name}(${s.id})`).join(", ")}`,
      },
      timestamp: Date.now(),
    });

    // 鎸佷箙鍖栧埌 MemoryStore
    if (memoryStore) {
      persistSkillsToMemory(registered, memoryStore as MemoryStore);
    }
  }

  return registered;
}

/**
 * 娉ㄥ唽鎶€鑳界閬撹闃呰€呪€斺€旈€氳繃 PipelineObserver 璁㈤槄 NodeComplete 浜嬩欢锛孿n * 鍦ㄦ瘡涓妭鐐规垚鍔熷悗鎻愬彇鎶€鑳芥ā鏉垮苟鎸佷箙鍖栥€俓n *
 * 璁㈤槄鑰呮ā寮忥細Scheduler 涓嶅啀鎸佹湁 SkillRegistry/MemoryStore 寮曠敤锛孿n * 鎶€鑳介棴鐜綔涓虹嫭绔嬭闃呰€呮寕杞藉埌鍙娴嬬閬撲笂锛屼笌璋冨害鏍稿績瑙ｈ€︺€俓n *
 * @param observer      鍙娴嬬閬揬n * @param skillRegistry 鎶€鑳芥敞鍐岃〃
 * @param memoryStore   鍙€夆€斺€旇蹇嗕腑鏋紙鐢ㄤ簬鎸佷箙鍖栨妧鑳藉埌 SQLite锛塡n * @returns             鍙栨秷璁㈤槄鍑芥暟锛堣皟鐢ㄥ嵆绉婚櫎 handler锛塡n */
export function registerSkillPipeline(
  observer: IPipelineObserver,
  skillRegistry: SkillRegistry,
  memoryStore?: IMemoryStore,
): () => void {
  const handler: PipelineHandler = (event) => {
    if (event.type !== PipelineEventType.NodeComplete) return;
    const payload = event.payload as { nodeId: string; agentType: string; success: boolean; output?: string };
    if (!payload.success || !payload.output) return;

    extractAndPersistSkills(
      skillRegistry,
      memoryStore,
      observer,
      payload.nodeId,
      payload.agentType as AgentType,
      payload.output,
    );
  };

  observer.on(PipelinePriority.HIGH, handler);

  // 杩斿洖鍙栨秷璁㈤槄鍑芥暟
  return () => observer.off(PipelinePriority.HIGH, handler);
}

// ============================================================
// @cortex/engine/observer/console-bridge 鈥斺€?Console 鈫?PipelineObserver 妗ユ帴
//
// @since v3.1.0
// @constitutional 搂浜?鈥?鐢熶骇浠ｇ爜璧?PipelineObserver 绠￠亾锛岀姝㈣８ console
//
// 鑱岃矗锛歕r
//   1. install() 鎷︽埅 console.warn/error/log锛岃浆涓?PipelineObserver.emit()
//   2. uninstall() 鎭㈠鍘熷 console 鏂规硶
//   3. 鐧藉悕鍗曡眮鍏嶇壒瀹氳皟鐢ㄦ簮锛圡emoryStoreMonitor銆乪mbedding 棰勭儹绛夛級
//
// 娉細console.error 鈫?ErrorReported 浜嬩欢锛沜onsole.warn/log 鈫?浠呴潤榛樹笉 emit
// 锛圥ipelineEventType 鏃犻€氱敤 console 浜嬩欢锛岄伩鍏嶆薄鏌撲簨浠跺懡鍚嶇┖闂达級
// ============================================================
/* eslint-disable no-console */

import {
  PipelineEventType,
  PipelinePriority,
  type IPipelineObserver,
} from "@cortex/shared";
import { CONSOLE_BRIDGE_WHITELIST } from "../config/engine-defaults.js";

/** 妗ユ帴鐘舵€?*/
interface BridgeState {
  installed: boolean;
  originalWarn: typeof console.warn;
  originalError: typeof console.error;
  originalLog: typeof console.log;
}

const _state: BridgeState = {
  installed: false,
  originalWarn: console.warn.bind(console),
  originalError: console.error.bind(console),
  originalLog: console.log.bind(console),
};

/**
 * 瀹夎 ConsoleBridge 鈥斺€?鎷︽埅瑁?console 璋冪敤锛岃浆涓?PipelineObserver 浜嬩欢銆俓r
 *
 * 鐧藉悕鍗曡眮鍏嶏細
 *   - MemoryStoreMonitor 鈥?PipelineObserver 鍚堟硶娑堣垂鑰匼r
 *   - embedding 棰勭儹闃舵 鈥?observer 灏氭湭灏辩华
 *   - ConsoleBridge 鑷韩
 *
 * @param observer PipelineObserver 瀹炰緥
 */
export function installConsoleBridge(observer: IPipelineObserver): void {
  if (_state.installed) return;

  _state.originalWarn = console.warn.bind(console);
  _state.originalError = console.error.bind(console);
  _state.originalLog = console.log.bind(console);

  console.warn = (...args: unknown[]) => {
    const msg = formatArgs(args);
    if (isWhitelisted(msg)) {
      _state.originalWarn(...args);
      return;
    }
    // warn 鈫?浠呴潤榛橈紝涓?emit锛堥伩鍏嶅櫔澹版椽娉涳級
  };

  console.error = (...args: unknown[]) => {
    const msg = formatArgs(args);
    if (isWhitelisted(msg)) {
      _state.originalError(...args);
      return;
    }
    // error 鈫?ErrorReported 浜嬩欢
    observer.emit({
      type: PipelineEventType.ErrorReported,
      priority: PipelinePriority.HIGH,
      payload: {
        source: "console_bridge",
        message: msg.slice(0, 500),
      },
      timestamp: Date.now(),
      notificationType: "WARNING",
    });
  };

  console.log = (...args: unknown[]) => {
    const msg = formatArgs(args);
    if (isWhitelisted(msg)) {
      _state.originalLog(...args);
      return;
    }
    // log 鈫?浠呴潤榛榎r
  };

  _state.installed = true;
}

/**
 * 鍗歌浇 ConsoleBridge 鈥斺€?鎭㈠鍘熷 console 鏂规硶銆俓r
 */
export function uninstallConsoleBridge(): void {
  if (!_state.installed) return;
  console.warn = _state.originalWarn;
  console.error = _state.originalError;
  console.log = _state.originalLog;
  _state.installed = false;
}

/** 妫€鏌ヨ皟鐢ㄦ簮鏄惁鍦ㄧ櫧鍚嶅崟涓?*/
function isWhitelisted(msg: string): boolean {
  for (const suffix of CONSOLE_BRIDGE_WHITELIST) {
    if (msg.includes(suffix)) return true;
  }
  return false;
}

/** 鏍煎紡鍖?console 鍙傛暟涓哄瓧绗︿覆 */
function formatArgs(args: unknown[]): string {
  return args
    .map((a) => {
      if (typeof a === "string") return a;
      if (a instanceof Error) return a.message;
      try { return JSON.stringify(a).slice(0, 500); } catch { return String(a); }
    })
    .join(" ");
}

// ============================================================
// @cortex/engine/plugin/agent-pool.plugin
//
// AgentPool 鎻掍欢鈥斺€斾緷璧?PipelineObserver銆俓r
// 绠＄悊 Agent 瀹炰緥鐢熷懡鍛ㄦ湡銆佺姸鎬佹満杞崲銆乻pawn/destroy銆俓r
//
// @since v3.0 鈥?寮曟搸鎻掍欢鍖栬В鑰r
// ============================================================

import type { EnginePlugin, PluginContext, PluginHealth } from "./types.js";
import type { Disposable } from "@cortex/shared";
import { AgentPool } from "@cortex/scheduler";

export class AgentPoolPlugin implements EnginePlugin {
  readonly name = "agentPool";
  readonly dependencies = ["pipelineObserver"];

  private instance!: AgentPool;

  async init(ctx: PluginContext): Promise<void> {
    const observer = ctx.get<PipelineObserverPlugin>("pipelineObserver").getInstance();
    this.instance = new AgentPool();
    this.instance.setObserver(observer);
  }

  async start(): Promise<void> {}

  async stop(): Promise<void> {
    (this.instance as unknown as Disposable).destroyAll?.();
  }

  health(): PluginHealth {
    return this.instance ? "healthy" : "dead";
  }

  getInstance(): AgentPool {
    return this.instance;
  }
}

import type { PipelineObserverPlugin } from "./pipeline-observer.plugin.js";

// 鑷敞鍐孿r
import { PluginLoader } from "./plugin-loader.js";
PluginLoader.register("agentPool", AgentPoolPlugin);
PluginLoader.register("agentPool", AgentPoolPlugin);

// ============================================================
// @cortex/engine/plugin/confirm-gate.plugin
//
// ConfirmGate 鎻掍欢鈥斺€斾緷璧?PipelineObserver銆俓r
// 鍩轰簬鍙€嗘€х瓑绾ф嫤鎴伐鍏疯皟鐢紝L2/L3 姘歌繙纭銆俓r
//
// @since v3.0 鈥?寮曟搸鎻掍欢鍖栬В鑰r
// ============================================================

import type { EnginePlugin, PluginContext, PluginHealth } from "./types.js";
import { ConfirmGate } from "@cortex/scheduler";
import { CLIAdapter } from "@cortex/platform";

export class ConfirmGatePlugin implements EnginePlugin {
  readonly name = "confirmGate";
  readonly dependencies = ["pipelineObserver"];

  private instance!: ConfirmGate;
  private cliAdapter!: CLIAdapter;

  async init(ctx: PluginContext): Promise<void> {
    this.instance = new ConfirmGate(ctx.config.toolTimeouts.confirmWait);
    this.cliAdapter = new CLIAdapter();
    this.instance.setBridge(this.cliAdapter);
  }

  async start(): Promise<void> {}

  async stop(): Promise<void> {
    this.instance.dispose();
    this.cliAdapter.close?.();
  }

  health(): PluginHealth {
    return this.instance ? "healthy" : "dead";
  }

  getInstance(): ConfirmGate {
    return this.instance;
  }

  getCliAdapter(): CLIAdapter {
    return this.cliAdapter;
  }
}

// 鑷敞鍐孿r
