// ============================================================
// @cortex/engine/plugin/pipeline-observer.plugin
//
// PipelineObserver 鎻掍欢鈥斺€旈浂渚濊禆锛屼簨浠舵€荤嚎鏍瑰熀銆俓r
// 鎵€鏈夋彃浠?init() 鍓嶅繀椤诲厛鍔犺浇姝ゆ彃浠讹紝observer 閫氳繃 PluginContext 浼犻€掔粰涓嬫父銆俓r
//
// @since v3.0 鈥?寮曟搸鎻掍欢鍖栬В鑰r
// ============================================================

import type { EnginePlugin, PluginContext, PluginHealth } from "./types.js";
import type { Disposable } from "@cortex/shared";
import { PipelineObserver } from "@cortex/scheduler";

export class PipelineObserverPlugin implements EnginePlugin {
  readonly name = "pipelineObserver";
  readonly dependencies: string[] = [];

  private instance!: PipelineObserver;

  async init(_ctx: PluginContext): Promise<void> {
    this.instance = new PipelineObserver();
  }

  async start(): Promise<void> {}

  async stop(): Promise<void> {
    (this.instance as unknown as Disposable).clear?.();
  }

  health(): PluginHealth {
    return this.instance ? "healthy" : "dead";
  }

  /** 鑾峰彇 PipelineObserver 瀹炰緥锛堜緵鍏朵粬鎻掍欢閫氳繃 ctx.get() 浣跨敤锛?*/
  getInstance(): PipelineObserver {
    return this.instance;
  }
}

// 鑷敞鍐岋紙鍓綔鐢ㄥ鍏モ€斺€攊mport 鍗虫敞鍐岋紝鏃犻渶鎵嬪姩璋冪敤 register锛塡r
import { PluginLoader } from "./plugin-loader.js";
PluginLoader.register("pipelineObserver", PipelineObserverPlugin);
PluginLoader.register("pipelineObserver", PipelineObserverPlugin);

// ============================================================
// @cortex/engine/plugin/plugin-loader 鈥斺€?鎻掍欢鍔犺浇瀹瑰櫒
//
// PluginLoader 鑱岃矗锛歕r
//   1. 鎸?engine-plugins.json 澹版槑鍔犺浇鎻掍欢
//   2. 鎷撴墤鎺掑簭锛堜緷璧栧叧绯伙級
//   3. 渚濇 init() 鈫?postInit() 鈫?start()
//   4. 杩斿洖 PluginContainer 灏佽 shutdown()
//
// @since v3.0 鈥?寮曟搸鎻掍欢鍖栬В鑰r
// ============================================================

import type { EnginePlugin, PluginContext, PluginContainer, PluginExternals } from "./types.js";
import type { IPipelineObserver } from "@cortex/shared";
import { resolveConfig, type EngineConfig } from "@cortex/config";

// 鈹€鈹€鈹€ 閰嶇疆 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 鎻掍欢鍔犺浇閰嶇疆 */
export interface EnginePluginLoadConfig {
  /** 瑕佸姞杞界殑鎻掍欢鍚嶅垪琛紙鎸?engine-plugins.json 澹版槑锛?*/
  plugins: string[];
  /** 寮曟搸閰嶇疆锛堝彲閮ㄥ垎瑕嗙洊榛樿鍊硷級 */
  engineConfig?: EngineConfig;
  /** 宸ヤ綔鍖烘牴鐩綍 */
  workspaceRoot: string;
  /** 澶栭儴渚濊禆 */
  externals: PluginExternals;
}

// 鈹€鈹€鈹€ 鎻掍欢娉ㄥ唽琛?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

type PluginConstructor = new () => EnginePlugin;

// 鈹€鈹€鈹€ PluginLoader 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class PluginLoader {
  /** 鎻掍欢鏋勯€犲櫒娉ㄥ唽琛細name 鈫?constructor */
  private static _registry = new Map<string, PluginConstructor>();

  /** 娉ㄥ唽鎻掍欢鏋勯€犲櫒 */
  static register(name: string, ctor: PluginConstructor): void {
    PluginLoader._registry.set(name, ctor);
  }

  /** 鑾峰彇宸叉敞鍐岀殑鎻掍欢鍚嶅垪琛?*/
  static getRegisteredNames(): string[] {
    return [...PluginLoader._registry.keys()];
  }

  // 鈹€鈹€ 瀹炰緥 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private _plugins = new Map<string, EnginePlugin>();
  private _inited = false;
  private _started = false;
  private _ctx!: PluginContext;
  private _config!: EnginePluginLoadConfig;

  /**
   * 鍔犺浇骞跺惎鍔ㄥ叏閮ㄦ彃浠躲€俓r
   * 杩斿洖 PluginContainer鈥斺€旇皟鐢ㄦ柟閫氳繃 container.get() 鍙?Scheduler/MemoryStore 绛夈€俓r
   */
  async load(config: EnginePluginLoadConfig): Promise<PluginContainer> {
    this._config = config;
    const mergedConfig = resolveConfig(config.engineConfig);

    // 搂1 瀹炰緥鍖栬姹傜殑鎻掍欢
    const instances = this._instantiate(config.plugins);

    // 搂2 鎷撴墤鎺掑簭
    const sorted = this._topologicalSort(instances);

    // 搂3 鍒涘缓 PluginContext锛堟爤鍒嗛厤鈥斺€旈棴鍖呮崟鑾?instances 寮曠敤锛塡r
    const ctx = this._createContext(sorted, mergedConfig, config.externals, config.workspaceRoot);
    this._ctx = ctx;

    // 搂4 渚濇 init()
    for (const plugin of sorted) {
      await plugin.init(ctx);
    }
    this._inited = true;

    // 搂5 postInit 璺ㄦ彃浠剁粐鍏ワ紙Scheduler 娉ㄥ唽 Agent / SkillSystem 鎭㈠鎶€鑳斤級
    await this._postInit(ctx, sorted);

    // 搂6 渚濇 start()
    for (const plugin of sorted) {
      await plugin.start();
    }
    this._started = true;

    return {
      get: <T>(name: string): T => {
        const plugin = this._plugins.get(name);
        if (!plugin) throw new Error(`[PluginLoader] 鎻掍欢 "${name}" 鏈姞杞絗);
        return plugin as unknown as T;
      },
      has: (name: string): boolean => this._plugins.has(name),
      shutdown: async () => {
        // 閫嗗簭鍋滄
        for (let i = sorted.length - 1; i >= 0; i--) {
          try {
            await sorted[i].stop();
          } catch (e) {
            console.warn(`[PluginLoader] 鍋滄鎻掍欢 "${sorted[i].name}" 鏃跺嚭閿?`, e);
          }
        }
        this._started = false;
        this._inited = false;
      },
    };
  }

  // 鈹€鈹€ 绉佹湁鏂规硶 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /** 浠庢瀯閫犲櫒娉ㄥ唽琛ㄥ疄渚嬪寲璇锋眰鐨勬彃浠?*/
  private _instantiate(names: string[]): EnginePlugin[] {
    const instances: EnginePlugin[] = [];
    const seen = new Set<string>();

    for (const name of names) {
      if (seen.has(name)) {
        throw new Error(`[PluginLoader] 閲嶅澹版槑鎻掍欢: "${name}"`);
      }
      const ctor = PluginLoader._registry.get(name);
      if (!ctor) {
        throw new Error(`[PluginLoader] 鏈敞鍐岀殑鎻掍欢: "${name}"銆傚彲鐢? [${[...PluginLoader._registry.keys()].join(", ")}]`);
      }
      const instance = new ctor();
      instances.push(instance);
      this._plugins.set(name, instance);
      seen.add(name);
    }

    return instances;
  }

  /** 鎷撴墤鎺掑簭鈥斺€擪ahn 绠楁硶锛屾寜 dependencies 澹版槑璁＄畻鍔犺浇椤哄簭 */
  private _topologicalSort(instances: EnginePlugin[]): EnginePlugin[] {
    const nameToPlugin = new Map<string, EnginePlugin>();
    const inDegree = new Map<string, number>();
    const adjacency = new Map<string, string[]>();

    for (const p of instances) {
      nameToPlugin.set(p.name, p);
      inDegree.set(p.name, 0);
      adjacency.set(p.name, []);
    }

    // 鏋勫缓閭绘帴琛ㄥ拰鍏ュ害
    for (const p of instances) {
      for (const dep of p.dependencies) {
        if (!nameToPlugin.has(dep)) {
          throw new Error(
            `[PluginLoader] 鎻掍欢 "${p.name}" 渚濊禆 "${dep}"锛屼絾 "${dep}" 鏈湪鍔犺浇娓呭崟涓€俙 +
            `璇风‘淇?engine-plugins.json 涓?"${dep}" 鎺掑湪 "${p.name}" 涔嬪墠銆俙,
          );
        }
        const adjList = adjacency.get(dep);
        if (adjList) adjList.push(p.name);
        inDegree.set(p.name, (inDegree.get(p.name) ?? 0) + 1);
      }
    }

    // Kahn 绠楁硶
    const queue: string[] = [];
    for (const [name, degree] of inDegree) {
      if (degree === 0) queue.push(name);
    }

    const sorted: EnginePlugin[] = [];
    while (queue.length > 0) {
      const name = queue.shift();
      if (!name) continue;
      const plugin = nameToPlugin.get(name);
      if (!plugin) continue;
      sorted.push(plugin);

      const neighbors = adjacency.get(name);
      if (!neighbors) continue;
      for (const neighbor of neighbors) {
        const newDegree = (inDegree.get(neighbor) ?? 1) - 1;
        inDegree.set(neighbor, newDegree);
        if (newDegree === 0) queue.push(neighbor);
      }
    }

    if (sorted.length !== instances.length) {
      const remaining = instances.filter((p) => !sorted.includes(p)).map((p) => p.name);
      throw new Error(`[PluginLoader] 妫€娴嬪埌寰幆渚濊禆锛屾棤娉曟帓搴忋€傚墿浣欐湭鍔犺浇: [${remaining.join(", ")}]`);
    }

    return sorted;
  }

  /** 鍒涘缓 PluginContext */
  private _createContext(
    _sorted: EnginePlugin[],
    config: Required<EngineConfig>,
    externals: PluginExternals,
    workspaceRoot: string,
  ): PluginContext {
    return {
      observer: this._ctx?.observer ?? ({} as IPipelineObserver), // 灏嗗湪 init 闃舵鐢?pipelineObserver 鎻掍欢瑕嗙洊
      config,
      workspaceRoot,
      externals,
      get: <T>(name: string): T => {
        const plugin = this._plugins.get(name);
        if (!plugin) throw new Error(`[PluginLoader] 鎻掍欢 "${name}" 灏氭湭鍒濆鍖朻);
        return plugin as unknown as T;
      },
    };
  }

  /**
   * postInit: 鍏ㄩ儴鎻掍欢 init 瀹屾垚鍚庯紝鎵ц璺ㄦ彃浠剁粐鍏ャ€俓r
   * - Scheduler.registerAllAgents() 鍐呴儴瀹屾垚 Agent 娉ㄥ唽 + SkillSystem finalize
   */
  private async _postInit(ctx: PluginContext, _sorted: EnginePlugin[]): Promise<void> {
    const schedulerPlugin = this._plugins.get("scheduler") as SchedulerPlugin;

    if (schedulerPlugin) {
      await schedulerPlugin.registerAllAgents(ctx);
    }
  }
}

// 鍓嶅悜澹版槑鎻掍欢绫诲瀷
import type { SchedulerPlugin } from "./scheduler.plugin.js";

// ============================================================
// @cortex/engine/plugin/scheduler.plugin
//
// Scheduler 鎻掍欢鈥斺€斾緷璧栧叏閮ㄦ牳蹇冩彃浠躲€俓r
// 鎷撴墤鎺掑簭浠诲姟鏍?鈫?閫愬眰骞惰鍒嗗彂缁?Agent 鈫?浜у嚭 ExecutionReport銆俓r
// Agent 娉ㄥ唽锛坮egisterAgents锛夐€昏緫鍐呭缓涓?start() 鐨勪竴閮ㄥ垎銆俓r
//
// @since v3.0 鈥?寮曟搸鎻掍欢鍖栬В鑰r
// ============================================================

import type { EnginePlugin, PluginContext, PluginHealth } from "./types.js";
import type { Agent, AgentType, Disposable, MemoryEntry, ReadMode } from "@cortex/shared";
import { Scheduler } from "../core/scheduler.js";
import { createAgent, type AgentFactoryConfig } from "../components/agent-factory.js";
import { createInspectorAgent } from "../agents/inspector-agent.js";
import { createBrowserAgent } from "../agents/browser-agent.js";
import { ButlerAgent } from "../agents/butler-agent.js";
import type { MemoryStore } from "@cortex/memory-store";
import type { Toolkit } from "@cortex/platform";
import type { PipelineObserver } from "@cortex/scheduler";
import type { LlmAdapter } from "@cortex/llm";
import { resolveLlm, injectStandards, MEMORY_QUERY_REGISTRY } from "../bootstrap/load-config.js";
import {
  registerAgentFactory,
  getAgentFactory,
} from "./agent-factory-registry.js";

export class SchedulerPlugin implements EnginePlugin {
  readonly name = "scheduler";
  readonly dependencies = [
    "taskBoard",
    "agentPool",
    "pipelineObserver",
    "metaAgent",
    "memoryStore",
  ];

  private instance!: Scheduler;
  private _agents = new Map<string, Agent>();
  private _butler?: ButlerAgent;

  async init(ctx: PluginContext): Promise<void> {
    const board = ctx.get<TaskBoardPlugin>("taskBoard").getInstance();
    const pool = ctx.get<AgentPoolPlugin>("agentPool").getInstance();
    const observer = ctx.get<PipelineObserverPlugin>("pipelineObserver").getInstance();
    const metaAgent = ctx.get<MetaAgentPlugin>("metaAgent").getInstance();
    const memoryPlugin = ctx.get<MemoryStorePlugin>("memoryStore");

    this.instance = new Scheduler(
      board,
      pool,
      observer,
      metaAgent,
      ctx.config,
    );

    // 鎺ョ嚎 MemoryStore 鈫?Scheduler
    if (memoryPlugin) {
      this.instance.setMemoryStore(memoryPlugin.getInstance());
    }
  }

  async start(): Promise<void> {
    // Agent 娉ㄥ唽鍦?PluginLoader postInit 闃舵鎵ц锛堥渶瑕?Toolkit + 鍏ㄩ儴渚濊禆灏辩华锛塡r
  }

  async stop(): Promise<void> {
    (this.instance as unknown as Disposable).stop?.();
  }

  health(): PluginHealth {
    return this.instance ? "healthy" : "dead";
  }

  getInstance(): Scheduler {
    return this.instance;
  }

  getAgents(): Map<string, Agent> {
    return this._agents;
  }

  getButler(): ButlerAgent | undefined {
    return this._butler;
  }

  /**
   * 娉ㄥ唽鍏ㄩ儴 Agent鈥斺€旂敱 PluginLoader 鍦ㄥ叏閮ㄦ彃浠?init 鍚庤皟鐢ㄣ€俓r
   * 绛夊悓浜庡師 bootstrap 涓殑 registerAgents() 閫昏緫銆俓r
   */
  async registerAllAgents(ctx: PluginContext): Promise<Map<string, Agent>> {
    const { llms, toolkit, codingStandards, factoryConfig } = ctx.externals;
    const observer = ctx.get<PipelineObserverPlugin>("pipelineObserver").getInstance();
    const memory = ctx.get<MemoryStorePlugin>("memoryStore").getInstance();
    const filterRead = ctx.get<ConsistencyLayerPlugin>("consistencyLayer").getFilterRead();
    const pool = ctx.get<AgentPoolPlugin>("agentPool").getInstance();

    // 娉ㄥ唽琛ㄦ敞鍏ュ凡鍦?bootstrap 闃舵瀹屾垚锛坆ootstrap-engine.ts 搂2锛夛紝姝ゅ涓嶅啀閲嶅璋冪敤

    // 鈹€鈹€ 娉ㄥ唽鐗规畩 Agent 宸ュ巶锛堥厤缃┍鍔細鏂板 Agent 绫诲瀷鍦ㄥ埆澶?registerAgentFactory 鍗冲彲锛夆攢鈹€
    _registerBuiltinAgentFactories(ctx, observer, toolkit, memory as MemoryStore, codingStandards, filterRead, llms);

    for (const def of factoryConfig.agentDefinitions) {
      const agentType = def.type;

      // 璺宠繃涓嶅弬涓庤皟搴︾殑鐗规畩 Agent
      if (agentType === "meta" || agentType === "strategist") {
        continue;
      }

      let agent: Agent | undefined;

      // 閰嶇疆椹卞姩锛氫粠宸ュ巶娉ㄥ唽琛ㄨ幏鍙栧伐鍘傦紙鐗规畩 Agent 宸茶嚜娉ㄥ唽锛夛紝fallback 鍒伴粯璁ゅ伐鍘俓r
      const factory = getAgentFactory(agentType);
      if (factory) {
        agent = await factory(def, ctx);
        // butler锛氬瓨鍌ㄥ紩鐢ㄤ絾涓嶆敞鍐屼负鍙皟搴?Agent
        if (agentType === "butler" && agent) {
          this._butler = agent as unknown as ButlerAgent;
          continue;
        }
      } else {
        // 榛樿宸ュ巶锛氶€氱敤 createAgent 閫昏緫
        const llmAdapter = resolveLlm(llms, def.key);
        const memoryQuery = MEMORY_QUERY_REGISTRY.get(agentType);
        const factoryConf: AgentFactoryConfig = {
          type: agentType as AgentType,
          systemPrompt: injectStandards(def.systemPrompt, codingStandards),
          filterRead,
          memoryEnabled: true,
          getMemoryQuery: memoryQuery ?? undefined,
        };
        agent = createAgent(factoryConf, llmAdapter as LlmAdapter, toolkit, memory as MemoryStore);
      }

      if (agent) {
        try {
          await agent.wakeup();
           
        } catch (e) {
          console.warn(
            `[Scheduler] ${agentType} Agent wakeup 澶辫触锛堝皢璺宠繃娉ㄥ唽锛?`,
            e instanceof Error ? e.message : String(e),
          );
          continue;
        }
        this.instance.register(agentType, agent, def.model);
        pool.register({
          type: agentType as AgentType,
          maxInstances: def.maxInstances ?? 1,
        });
        this._agents.set(agentType, agent);
      }
    }

    return this._agents;
  }
}

// 鈹€鈹€ 鍐呯疆 Agent 宸ュ巶娉ㄥ唽 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 娉ㄥ唽鍐呯疆鐗规畩 Agent 宸ュ巶銆俓r
 * 姣忎釜宸ュ巶闂寘鎹曡幏鎵€闇€鐨勪緷璧栵紙observer/toolkit/memory 绛夛級锛孿r
 * 杩愯鏃舵寜 agentType 鏌ユ壘鎵ц銆俓r
 *
 * 鏂板 Agent 绫诲瀷锛氬湪鍏朵粬妯″潡璋冪敤 registerAgentFactory(type, factory) 鍗冲彲锛孿r
 * 鏃犻渶淇敼鏈枃浠躲€俓r
 */
function _registerBuiltinAgentFactories(
  ctx: PluginContext,
  observer: PipelineObserver,
  toolkit: Toolkit,
  memory: MemoryStore,
  codingStandards: string,
  filterRead: (entries: MemoryEntry[], mode: ReadMode) => MemoryEntry[],
  llms: Map<string, LlmAdapter>,
): void {
  registerAgentFactory("inspector", async (def, c) => {
    const inspAgent = createInspectorAgent(
      resolveLlm(llms, def.key),
      toolkit,
      memory,
      c.config,
      injectStandards(def.systemPrompt, codingStandards),
      filterRead,
    );
    if (c.workspaceRoot) inspAgent.setWorkspaceRoot(c.workspaceRoot);
    return inspAgent;
  });

  registerAgentFactory("browser", async (def, c) => {
    const brwAgent = createBrowserAgent(
      resolveLlm(llms, def.key),
      toolkit,
      memory,
      injectStandards(def.systemPrompt, codingStandards),
      filterRead,
    );
    if (c.workspaceRoot) brwAgent.setWorkspaceRoot(c.workspaceRoot);
    return brwAgent;
  });

  registerAgentFactory("butler", async (_def, _c) => {
    // butler 鐩存帴鍒涘缓鈥斺€斾笉閫氳繃 createAgent锛屾棤闇€宸ュ巶鍙傛暟
    // 浣跨敤闂寘鎹曡幏鐨?observer锛堣€岄潪 c.observer锛屽悗鑰呬负绌哄瓨鏍癸級
    return new ButlerAgent(observer) as unknown as Agent;
  });
}

