// 鈹€鈹€鈹€ 绾嚱鏁帮細鐘舵€佹帹瀵?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 浠?weight 鍜岃瘎浠锋鏁版帹瀵肩姸鎬佹爣绛俱€俓r
 * 杩欎笉鏄姸鎬佹満鈥斺€旀槸绾嚱鏁扮殑鏍囩鍖栨樉绀恒€俓r
 *
 *   - trial:   weight <= 0 鎴栧皻鏃犳鍚戣瘎浠穃r
 *   - active:  weight >= 1 涓旀湁鑷冲皯涓€娆℃鍚戣瘎浠穃r
 *   - deprecated: 杩炵画 3+ 鏉?rating=-1
 */
export function deriveStatus(
  weight: number,
  feedbackHistory: FeedbackEntry[],
): "trial" | "active" | "deprecated" {
  // 鉀戯笍 鍏煎鏃ф暟鎹細feedbackHistory 鍙兘涓?undefined锛坴2.5 閬楃暀鎴栨棫 toJSON 鍙嶅簭鍒楀寲锛塡r
  const history = feedbackHistory ?? [];
  // 杩炵画鏈夊鍒ゅ畾
  let consecutiveNegative = 0;
  for (let i = history.length - 1; i >= 0; i--) {
    if (history[i].rating === -1) {
      consecutiveNegative++;
    } else {
      break;
    }
  }
  if (consecutiveNegative >= 3) return "deprecated";

  if (weight >= 1 && history.some((f) => f.rating === 1)) {
    return "active";
  }

  return "trial";
}

// 鈹€鈹€鈹€ 娉ㄥ唽琛ㄥ疄鐜?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class SkillRegistry {
  /** 鎸夋爣绛剧储寮?*/
  private _byTag: Map<string, SkillTemplate[]> = new Map();
  /** 鎸?id 绱㈠紩 */
  private _byId: Map<string, SkillTemplate> = new Map();

  // 鈹€鈹€ 娉ㄥ唽 / 娉ㄩ攢 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /** 娉ㄥ唽涓€涓妧鑳芥ā鏉匡紙鏈夊垯瑕嗙洊锛?*/
  register(template: SkillTemplate): void {
    // id 鍘婚噸鈥斺€旀柊妯℃澘瑕嗙洊鏃фā鏉縗r
    if (this._byId.has(template.id)) {
      this.unregister(template.id);
    }

    this._byId.set(template.id, template);

    // 鎸夋爣绛剧储寮昞r
    for (const tag of template.triggerTags) {
      const existing = this._byTag.get(tag) ?? [];
      existing.push(template);
      this._byTag.set(tag, existing);
    }
  }

  /**
   * 娉ㄩ攢鎶€鑳芥ā鏉裤€俓r
   * 鏀堕泦寰呭垹闄?key 鍒版暟缁勫悗鍐嶇粺涓€鍒犻櫎锛屼笉鍦?for-of 涓慨鏀?Map銆俓r
   */
  unregister(id: string): boolean {
    const tmpl = this._byId.get(id);
    if (!tmpl) return false;

    this._byId.delete(id);

    // 浠庢爣绛剧储寮曚腑绉婚櫎
    const tagsToDelete: string[] = [];
    for (const [tag, templates] of this._byTag) {
      const filtered = templates.filter((t) => t.id !== id);
      if (filtered.length === 0) {
        tagsToDelete.push(tag);
      } else {
        this._byTag.set(tag, filtered);
      }
    }
    for (const tag of tagsToDelete) {
      this._byTag.delete(tag);
    }

    return true;
  }

  // 鈹€鈹€ 鏌ヨ 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 鎸夋爣绛炬煡璇㈠尮閰嶇殑鎶€鑳芥ā鏉裤€俓r
   * 鍖归厤瑙勫垯锛歵emplate.triggerTags 鈭?queryTags 鈮?鈭匼r
   * 浠呰繑鍥?trial 鎴?active 鐘舵€佺殑妯℃澘銆俓r
   */
  queryByTags(queryTags: Tag[]): SkillTemplate[] {
    const matched = new Map<string, SkillTemplate>();
    for (const tag of queryTags) {
      const templates = this._byTag.get(tag);
      if (templates) {
        for (const t of templates) {
          const status = deriveStatus(t.weight, t.feedbackHistory);
          if (status === "active" || status === "trial") {
            matched.set(t.id, t);
          }
        }
      }
    }
    // 鎸?weight 闄嶅簭鎺掑垪鈥斺€旀潈閲嶉珮鐨勬洿鍙俊锛屾帓鍦ㄥ墠闈r
    return [...matched.values()].sort((a, b) => b.weight - a.weight);
  }

  /** 鎸?id 鑾峰彇 */
  get(id: string): SkillTemplate | undefined {
    return this._byId.get(id);
  }

  /** 鑾峰彇鎵€鏈夊凡娉ㄥ唽鎶€鑳?*/
  getAll(): SkillTemplate[] {
    return [...this._byId.values()];
  }

  /** 鑾峰彇娲昏穬鎶€鑳芥暟 */
  get activeCount(): number {
    return this.getAll().filter((t) => {
      const s = deriveStatus(t.weight, t.feedbackHistory);
      return s === "active" || s === "trial";
    }).length;
  }

  /** 鑾峰彇鎬绘暟 */
  get totalCount(): number {
    return this._byId.size;
  }

  // 鈹€鈹€ 璇勪环鍥炴祦 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * Agent 浣跨敤鎶€鑳藉悗锛屽甫鍥炶瘎浠枫€俓r
   * weight 绱姞锛宖eedbackHistory 杩藉姞銆俓r
   * 杩欐槸鎶€鑳介棴鐜殑鏍稿績鈥斺€旇瘎浠烽┍鍔ㄨ繘鍖栥€俓r
   */
  recordFeedback(
    id: string,
    agentId: string,
    rating: number,
    suggestion?: string,
  ): boolean {
    const tmpl = this._byId.get(id);
    if (!tmpl) return false;

    tmpl.weight += rating; // rating: 1=鏈夋晥, 0=鏃犳劅, -1=鏈夊
    tmpl.feedbackHistory.push({
      agentId,
      rating,
      suggestion,
      timestamp: Date.now(),
    });

    // 璇勪环鍚庨噸鏂拌绠楃姸鎬乗r
    tmpl.status = deriveStatus(tmpl.weight, tmpl.feedbackHistory);

    return true;
  }

  // 鈹€鈹€ 瀛ゆ妧鑳芥竻鐞?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 娓呯悊瀛ゆ妧鑳解€斺€攚eight=0 涓斿垱寤鸿秴杩?maxAgeMs 姣鏈棰嗗彇鐨勬妧鑳姐€俓r
   * 杩斿洖琚竻鐞嗙殑鎶€鑳?id 鍒楄〃銆俓r
   */
  cleanupOrphans(maxAgeMs: number = 7 * 24 * 60 * 60 * 1000): string[] {
    const now = Date.now();
    const removed: string[] = [];
    for (const [id, tmpl] of this._byId) {
      if (tmpl.weight === 0 && tmpl.feedbackHistory.length === 0) {
        if (now - tmpl.createdAt > maxAgeMs) {
          this.unregister(id);
          removed.push(id);
        }
      }
    }
    return removed;
  }

  // 鈹€鈹€ 鎵归噺鎿嶄綔 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /** 鎵归噺娉ㄥ唽 */
  registerAll(templates: SkillTemplate[]): void {
    for (const tmpl of templates) {
      this.register(tmpl);
    }
  }

  /** 娓呯┖娉ㄥ唽琛?*/
  clear(): void {
    this._byId.clear();
    this._byTag.clear();
  }

  // 鈹€鈹€ 鎸佷箙鍖?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  toJSON(): SerializedSkillRegistry {
    const templates = [...this._byId.values()];
    return { version: 2, templates };
  }

  static fromJSON(data: SerializedSkillRegistry): SkillRegistry {
    const registry = new SkillRegistry();
    for (const tmpl of data.templates) {
      registry.register(tmpl);
    }
    return registry;
  }

  /**
   * 搴忓垪鍖栦负 JSON 瀛楃涓层€俓r
   */
  toJSONString(): string {
    return JSON.stringify(this.toJSON(), null, 2);
  }
}

