import { ConsoleCollector, type ITelemetryCollector, type TelemetryData } from "@cortex/telemetry";

let _collector: ITelemetryCollector | null = null;

/** 鑾峰彇鎴栧垱寤洪粯璁ら仴娴嬮噰闆嗗櫒 */
export function getTelemetry(): ITelemetryCollector {
  if (!_collector) {
    _collector = new ConsoleCollector();
  }
  return _collector;
}

/** 鏇挎崲閬ユ祴閲囬泦鍣紙娴嬭瘯/鐢熶骇鐜娉ㄥ叆 FileCollector 绛夛級 */
export function setTelemetry(collector: ITelemetryCollector): void {
  void _collector?.shutdown();
  _collector = collector;
}

/** 璁板綍寮曟搸閬ユ祴浜嬩欢 */
export async function recordTelemetry(
  name: string,
  value: number,
  tags?: { key: string; value: string }[],
  metadata?: Record<string, unknown>,
): Promise<void> {
  const data: TelemetryData = {
    id: `${name}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    name,
    value,
    tags: tags ?? [],
    timestamp: Date.now(),
    metadata,
  };
  await getTelemetry().collect(data);
}

/** 鍏抽棴閬ユ祴锛堝埛鏂扮紦鍐插尯 + 閲婃斁璧勬簮锛?*/
export function shutdownTelemetry(): void {
  void _collector?.shutdown();
  _collector = null;
}

