// @cortex/factory 鈥?Bootstrap 涓绘祦绋媆r
//
// 鍞竴瀵瑰鍏ュ彛锛歜ootstrap(projectRoot)
//
// 娴佹按绾匡細
//   loadAll() 鈫?validateAll() 鈫?assembleAll() 鈫?start()
//
// 鍚姩澶辫触鍗虫姤閿欓€€鍑猴紝涓嶇暀鍗婂惎鍔ㄧ姸鎬併€俓r
// ============================================================

import { loadAgentsConfig } from "./loaders/agents.loader.js";
import { loadCognitionConfig } from "./loaders/cognition.loader.js";
import { loadDocsConfig } from "./loaders/docs.loader.js";
import { validateCrossField } from "./schemas/cross-field.validator.js";
import {
  assembleAgents,
  assembleEventRouter,
  assembleCommittee,
  assembleTelescope,
} from "./assemblers/index.js";
import type { BootstrapResult, AgentDefinition } from "./types.js";

/**
 * Bootstrap 鈥斺€?浠庨厤缃枃浠跺埌杩愯鏃跺璞＄殑瀹屾暣娴佹按绾裤€俓r
 *
 * @param projectRoot 椤圭洰鏍圭洰褰曪紙鍖呭惈 cortex-agents.json 绛夐厤缃枃浠讹級
 * @returns BootstrapResult 鈥斺€?鎵€鏈夌粍瑁呭ソ鐨勯厤缃璞r
 * @throws 鑻ユ牎楠屽け璐ワ紙缂栬瘧鏈熸姤閿欙紝鎷掔粷鍚姩锛塡r
 *
 * @example
 * ```typescript
 * import { bootstrap } from "@cortex/factory";
 * const result = bootstrap("/path/to/project");
 * // result.agentDefinitions 鈫?渚?Scheduler 娉ㄥ唽
 * // result.eventRouting 鈫?渚?NotificationPipe 鍔犺浇
 * ```
 */
export function bootstrap(projectRoot: string, dataDirOverride?: string): BootstrapResult {
  const warnings: string[] = [];

  // 鈹€鈹€ 绗竴闃舵锛歭oadAll 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  let agentsConfig;
  let cognitionConfig;
  let docsConfig;

  try {
    agentsConfig = loadAgentsConfig(projectRoot, dataDirOverride);
  } catch (e) {
    throw new Error(`[factory bootstrap] 鍔犺浇 cortex-agents.json 澶辫触: ${String(e)}`, { cause: e });
  }

  try {
    cognitionConfig = loadCognitionConfig(projectRoot, dataDirOverride);
  } catch (e) {
    throw new Error(`[factory bootstrap] 鍔犺浇 cortex-cognition.json 澶辫触: ${String(e)}`, { cause: e });
  }

  try {
    docsConfig = loadDocsConfig(projectRoot, dataDirOverride);
  } catch (e) {
    throw new Error(`[factory bootstrap] 鍔犺浇 cortex-docs.json 澶辫触: ${String(e)}`, { cause: e });
  }

  // 鈹€鈹€ 绗簩闃舵锛歷alidateAll 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  // 璺ㄥ瓧娈典笁鍚堜竴鏍￠獙
  const crossFieldResult = validateCrossField(agentsConfig);
  if (!crossFieldResult.valid) {
    const errorMsg = crossFieldResult.errors.join("\n  ");
    throw new Error(
      `[factory bootstrap] 璺ㄥ瓧娈垫牎楠屽け璐モ€斺€旀嫆缁濆惎鍔?\n  ${errorMsg}`,
    );
  }
  warnings.push(...crossFieldResult.warnings);

  // 鈹€鈹€ 绗笁闃舵锛歛ssembleAll 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  // @fix N-06 鈥?assemble 杩斿洖鍊煎綋鍓嶆湭琚?BootstrapResult 鐩存帴浣跨敤锛孿r
  // 鍘熷洜锛歛ssemble 杈撳嚭绫诲瀷锛圓gentConfig[] / AssembledEventRouter / etc.锛変笌
  // BootstrapResult 瀛楁绫诲瀷锛圓gentDefinition[] / EventRoutingConfig / etc.锛変笉鍖归厤銆俓r
  // 璋冪敤淇濈暀浣滀负鎵╁睍棰勭暀鈥斺€旀湭鏉ヨ嫢 BootstrapResult 寮曞叆鏂板瓧娈靛彲鎺ュ叆銆俓r
  const agentDefs: AgentDefinition[] = Object.values(agentsConfig.agents);
  void assembleAgents(agentDefs);
  void assembleEventRouter(agentsConfig);
  void assembleCommittee(agentsConfig.eventRouting.committeeRules ?? []);
  void assembleTelescope();

  // 鈹€鈹€ 绗洓闃舵锛氳繑鍥炵粨鏋滐紙start 鐢辫皟鐢ㄦ柟鎵ц锛?鈹€鈹€

  const result: BootstrapResult = {
    agentDefinitions: agentDefs,
    eventRouting: agentsConfig.eventRouting,
    cognition: cognitionConfig,
    docs: docsConfig,
    roundtableTemplates: agentsConfig.roundtableTemplates ?? [],
    tools: agentsConfig.tools,
    warnings,
  };

  return result;
}

