import * as fs from "node:fs";
import * as path from "node:path";
import { resolveConfigDataDir, loadConfigDomain, type ConfigFileReader } from "@cortex/config";
import type { CortexAgentsConfig, AgentDefinition } from "../types.js";

/** 鍩轰簬 Node fs 鐨勬枃浠惰鍙栧櫒 */
const readFileNode: ConfigFileReader = (fp: string) => fs.readFileSync(fp, "utf-8");

/**
 * 鍔犺浇鎵€鏈夐厤缃煙锛坅gents + eventRouting + roundtable + ...锛夈€俓r
 * @param projectRoot 椤圭洰鏍圭洰褰曪紙鐢ㄤ簬瑙ｆ瀽 prompt 鏂囦欢璺緞锛塡r
 * @param dataDirOverride 鍙€夆€斺€旇鐩?config data 鐩綍璺緞锛堟祴璇曠敤锛塡r
 * @returns 瑙ｆ瀽鍚庣殑閰嶇疆
 * @throws 鑻ュ繀闇€鏂囦欢缂哄け銆丣SON 瑙ｆ瀽澶辫触銆佹垨蹇呭～瀛楁缂哄け
 */
export function loadAgentsConfig(projectRoot: string, dataDirOverride?: string): CortexAgentsConfig {
  const dataDir = dataDirOverride ?? resolveConfigDataDir();

  // 鈹€鈹€ 鍔犺浇鍚勯厤缃煙 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  // 1. Agent 瀹氫箟锛堝繀闇€锛塡r
  let agentsRaw: Record<string, AgentDefinition>;
  try {
    agentsRaw = loadConfigDomain<Record<string, AgentDefinition>>(
      "agents",
      readFileNode,
      dataDir,
    );
  } catch (e) {
    throw new Error(`鍔犺浇 agents.json 澶辫触: ${String(e)}`, { cause: e });
  }

  // 2. 浜嬩欢璺敱锛堝繀闇€锛塡r
  let eventRouting: CortexAgentsConfig["eventRouting"];
  try {
    const raw = loadConfigDomain<CortexAgentsConfig["eventRouting"]>(
      "eventRouting",
      readFileNode,
      dataDir,
    );
    eventRouting = raw;
  } catch (e) {
    throw new Error(`鍔犺浇 event-routing.json 澶辫触: ${String(e)}`, { cause: e });
  }

  // 3. 鍦嗘妯℃澘锛堝彲閫夛級
  let roundtableTemplates: CortexAgentsConfig["roundtableTemplates"];
  try {
    const raw = loadConfigDomain<CortexAgentsConfig["roundtableTemplates"]>(
      "roundtable",
      readFileNode,
      dataDir,
    );
    roundtableTemplates = raw ?? [];
  } catch {
    roundtableTemplates = [];
  }

  // 4. 鎼滅储鎻愪緵鍟嗭紙鍙€夛級
  let searchProviders: CortexAgentsConfig["searchProviders"];
  try {
    searchProviders = loadConfigDomain<CortexAgentsConfig["searchProviders"]>(
      "searchProviders",
      readFileNode,
      dataDir,
    );
  } catch {
    searchProviders = undefined;
  }

  // 5. 鑷瑙嗭紙鍙€夛級
  let selfExamination: CortexAgentsConfig["selfExamination"];
  try {
    selfExamination = loadConfigDomain<CortexAgentsConfig["selfExamination"]>(
      "selfExamination",
      readFileNode,
      dataDir,
    );
  } catch {
    selfExamination = undefined;
  }

  // 6. 浜ゅ弶楠岃瘉锛堝彲閫夛級
  let crossVerification: CortexAgentsConfig["crossVerification"];
  try {
    crossVerification = loadConfigDomain<CortexAgentsConfig["crossVerification"]>(
      "crossVerification",
      readFileNode,
      dataDir,
    );
  } catch {
    crossVerification = undefined;
  }

  // 7. 绉嶅瓙璁板繂锛堝彲閫夛級
  let seedMemories: CortexAgentsConfig["seedMemories"];
  try {
    seedMemories = loadConfigDomain<CortexAgentsConfig["seedMemories"]>(
      "seedMemories",
      readFileNode,
      dataDir,
    );
  } catch {
    seedMemories = undefined;
  }

  // 8. 娌荤悊绠＄嚎锛堝彲閫夛級
  let governancePipeline: CortexAgentsConfig["governancePipeline"];
  try {
    governancePipeline = loadConfigDomain<CortexAgentsConfig["governancePipeline"]>(
      "governancePipeline",
      readFileNode,
      dataDir,
    );
  } catch {
    governancePipeline = undefined;
  }

  // 9. 宸ュ叿鍏冩暟鎹紙鍙€夛級
  let tools: CortexAgentsConfig["tools"];
  try {
    const raw = loadConfigDomain<Record<string, unknown>>(
      "tools",
      readFileNode,
      dataDir,
    );
    // tools.json 鐨?dataKey 鏄?"tools"锛屼絾椤跺眰灏变竴涓?key
    // loadConfigDomain 鎻愬彇鍑?dataKey 鍚庤繑鍥炵殑鏄伐鍏峰璞℃湰韬玕r
    if (raw && typeof raw === "object") {
      tools = raw as Record<string, unknown>;
    }
  } catch {
    tools = undefined;
  }

  // 鈹€鈹€ 缁勮 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  const config: CortexAgentsConfig = {
    agents: agentsRaw,
    eventRouting,
    roundtableTemplates,
    searchProviders,
    selfExamination,
    crossVerification,
    seedMemories,
    governancePipeline,
    tools,
  };

  // 鈹€鈹€ 鏍￠獙 + 瑙ｆ瀽 prompt 鏂囦欢 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  _validateStructure(config);
  _resolvePromptFiles(config, projectRoot);

  return config;
}

/** 鏍￠獙鍩烘湰缁撴瀯 */
function _validateStructure(config: CortexAgentsConfig): CortexAgentsConfig {
  if (!config || typeof config !== "object") {
    throw new Error("cortex-agents.json: 椤跺眰蹇呴』涓哄璞

source:
object") {
    throw new Error("agents.json: 缂哄皯 agents 瀛楁");
  }

  if (!config.eventRouting || typeof config.eventRouting !== "object") {
    throw new Error("event-routing.json: 缂哄皯 eventRouting 瀛楁");
  }

  // 鏍￠獙姣忎釜 Agent 瀹氫箟
  for (const [id, agent] of Object.entries(config.agents)) {
    _validateAgent(id, agent as AgentDefinition);
  }

  // 鏍￠獙 eventRouting
  if (!config.eventRouting.routeTable || typeof config.eventRouting.routeTable !== "object") {
    throw new Error("event-routing.json: eventRouting 缂哄皯 routeTable");
  }

  return config;
}

/** 鏍￠獙鍗曚釜 Agent 瀹氫箟 */
function _validateAgent(id: string, agent: AgentDefinition): void {
  const prefix = `agents.json 鈫?agents.${id}`;

  if (!agent.type) {
    throw new Error(`${prefix}: 缂哄皯 type`);
  }
  if (!agent.role) {
    throw new Error(`${prefix}: 缂哄皯 role`);
  }
  if (!agent.systemPrompt && !agent.systemPromptFile) {
    throw new Error(`${prefix}: 缂哄皯 systemPrompt 鎴?systemPromptFile`);
  }
  if (!Array.isArray(agent.produces)) {
    throw new Error(`${prefix}: produces 蹇呴』涓烘暟缁刞);
  }
  if (!agent.model) {
    throw new Error(`${prefix}: 缂哄皯 model`);
  }
  if (!agent.key) {
    throw new Error(`${prefix}: 缂哄皯 key`);
  }

  // 鏍￠獙鍙€夋暟缁勫瓧娈礬r
  if (agent.tags !== undefined && !Array.isArray(agent.tags)) {
    throw new Error(`${prefix}: tags 蹇呴』涓烘暟缁刞);
  }
  if (agent.toolPermissions !== undefined && !Array.isArray(agent.toolPermissions)) {
    throw new Error(`${prefix}: toolPermissions 蹇呴』涓烘暟缁刞);
  }

  // 琛ュ叏 id
  agent.id = id;
}

/** 瑙ｆ瀽 prompt 鏂囦欢寮曠敤锛屽皢鏂囦欢鍐呭娉ㄥ叆鍒板唴鑱斿瓧娈?*/
function _resolvePromptFiles(config: CortexAgentsConfig, projectRoot: string): void {
  for (const [_id, agent] of Object.entries(config.agents)) {
    const a = agent as AgentDefinition;

    // systemPrompt
    if (a.systemPromptFile) {
      a.systemPrompt = _readPromptFile(projectRoot, a.systemPromptFile);
    }

    // roundtable personaPrompt
    if (a.roundtable?.personaPromptFile) {
      a.roundtable.personaPrompt = _readPromptFile(projectRoot, a.roundtable.personaPromptFile);
    }

    // planningPrompt
    if (a.planningPromptFile) {
      a.planningPrompt = _readPromptFile(projectRoot, a.planningPromptFile);
    }

    // replanPrompt
    if (a.replanPromptFile) {
      a.replanPrompt = _readPromptFile(projectRoot, a.replanPromptFile);
    }
  }
}

/** 璇诲彇 prompt 鏂囦欢鍐呭 */
function _readPromptFile(projectRoot: string, filePath: string): string {
  const fullPath = path.join(projectRoot, filePath);
  if (!fs.existsSync(fullPath)) {
    throw new Error(`Prompt 鏂囦欢涓嶅瓨鍦? ${fullPath}`);
  }
  try {
    return fs.readFileSync(fullPath, "utf-8").trim();
  } catch (e) {
    throw new Error(`璇诲彇 Prompt 鏂囦欢澶辫触: ${fullPath}: ${String(e)}`, { cause: e });
  }
}

// ============================================================
// @cortex/factory 鈥?璺ㄥ瓧娈垫牎楠屽櫒
//
// 涓夊悎涓€鑱旈獙锛歱roduces 鈫?routeTable 鈫?channels
// 鍦?validateAll() 闃舵鎵ц锛岀紪璇戞湡鍫垫閰嶇疆婕傜Щ銆俓r
//
// 鏍￠獙缁村害锛歕r
//   1. 鐢熶骇绔細Agent.produces 澹版槑浜嗕絾 routeTable 鏃犲搴旇矾鐢?鈫?鎶ラ敊
//   2. 娑堣垂绔細routeTable 鎸囦簡浣?channels 鏃犲搴旈€氶亾瀹氫箟 鈫?鎶ラ敊
//   3. 鍐茬獊妫€娴嬶細鍚屼竴浜嬩欢琚涓?Agent 澹版槑 produces 浣嗘棤 mergeRule 鈫?璀﹀憡
// ============================================================

import { NotificationChannel } from "@cortex/notification";
import type { CortexAgentsConfig } from "../types.js";

/** 璺ㄥ瓧娈垫牎楠岀粨鏋?*/
export interface CrossFieldValidationResult {
  /** 鏄惁閫氳繃 */
  valid: boolean;
  /** 閿欒鍒楄〃 */
  errors: string[];
  /** 璀﹀憡鍒楄〃 */
  warnings: string[];
}

/**
 * 鎵ц璺ㄥ瓧娈垫牎楠屻€俓r
 * @param config 宸插姞杞界殑 cortex-agents.json 閰嶇疆
 */
export function validateCrossField(config: CortexAgentsConfig): CrossFieldValidationResult {
  const result: CrossFieldValidationResult = {
    valid: true,
    errors: [],
    warnings: [],
  };

  // 鏀堕泦鎵€鏈?produces 澹版槑
  const allProduces = new Map<string, string[]>(); // eventType 鈫?agentIds[]
  for (const [agentId, agent] of Object.entries(config.agents)) {
    if (!Array.isArray(agent.produces)) continue;
    for (const eventType of agent.produces) {
      if (!allProduces.has(eventType)) {
        allProduces.set(eventType, []);
      }
      const producers = allProduces.get(eventType);
      if (producers) producers.push(agentId);
    }
  }

  const routeTable = config.eventRouting.routeTable;
  const mergeRules = config.eventRouting.mergeRules ?? [];

  // 鈹€鈹€ 缁村害涓€锛氱敓浜х鏍￠獙 鈹€鈹€
  for (const [eventType, agentIds] of allProduces) {
    if (!routeTable[eventType]) {
      result.valid = false;
      result.errors.push(
        `璺ㄥ瓧娈垫牎楠屽け璐? 浜嬩欢 "${eventType}" 琚?${agentIds.join(", ")} 澹版槑涓?produces锛屼絾 routeTable 涓棤瀵瑰簲璺敱`,
      );
    }
  }

  // 鈹€鈹€ 缁村害浜岋細娑堣垂绔牎楠?鈹€鈹€
  for (const [eventType, entry] of Object.entries(routeTable)) {
    // 鏍￠獙 channel 鍊兼槸鍚﹀悎娉昞r
    const validChannels = Object.values(NotificationChannel) as string[];
    if (!validChannels.includes(entry.channel)) {
      result.valid = false;
      result.errors.push(
        `璺ㄥ瓧娈垫牎楠屽け璐? routeTable["${eventType}"].channel = "${entry.channel}" 涓嶆槸鍚堟硶鐨勯€氶亾鍊笺€傛湁鏁堝€? ${validChannels.join(", ")}`,
      );
    }

    // 妫€鏌ユ槸鍚︽湁 Agent 澹版槑浜?produces 浣嗚矾鐢辨寚鍚戜笉瀛樺湪鐨勯€氶亾
    if (!allProduces.has(eventType) && eventType !== "MERGED:") {
      // 璺敱琛ㄤ腑瀹氫箟浜嗕絾鏃?Agent 鐢熶骇鈥斺€斿彲鑳芥槸閰嶇疆娈嬬暀
      result.warnings.push(
        `璺ㄥ瓧娈垫牎楠岃鍛? routeTable 涓畾涔変簡 "${eventType}" 鐨勮矾鐢憋紝浣嗘病鏈?Agent 澹版槑 produces 璇ヤ簨浠禶,
      );
    }
  }

  // 鈹€鈹€ 缁村害涓夛細鍐茬獊妫€娴?鈹€鈹€
  for (const [eventType, agentIds] of allProduces) {
    if (agentIds.length > 1) {
      const hasMergeRule = mergeRules.some((r) => r.groupBy === "mergeKey");
      if (!hasMergeRule) {
        result.warnings.push(
          `璺ㄥ瓧娈垫牎楠岃鍛? 浜嬩欢 "${eventType}" 琚?${agentIds.length} 涓?Agent (${agentIds.join(", ")}) 澹版槑 produces锛屼絾鏈厤缃?mergeRule銆傚缓璁坊鍔犲綊骞惰鍒檂,
        );
      }
    }
  }

  // 鈹€鈹€ 缁村害鍥涳細tag / toolPermissions 浜ゅ弶鏍￠獙 鈹€鈹€
  for (const [agentId, agent] of Object.entries(config.agents)) {
    // tags 鍐呯殑鍊煎繀椤诲瓨鍦╘r
    if (agent.tags) {
      for (const tag of agent.tags) {
        if (typeof tag !== "string" || !tag.trim()) {
          result.valid = false;
          result.errors.push(
            `璺ㄥ瓧娈垫牎楠屽け璐? agents.${agentId}.tags 鍖呭惈鏃犳晥鏍囩: "${tag}"`,
          );
        }
      }
    }
    // toolPermissions 鍐呯殑鍊煎繀椤绘湁鏁圽r
    if (agent.toolPermissions) {
      const validTools = ["read_file", "write_file", "search_code", "web_search", "run_shell", "list_files", "delete_file", "parse_ast", "browser_do"];
      for (const tool of agent.toolPermissions) {
        if (!validTools.includes(tool)) {
          result.warnings.push(
            `璺ㄥ瓧娈垫牎楠岃鍛? agents.${agentId}.toolPermissions 鍖呭惈鏈煡宸ュ叿: "${tool}"銆傛湁鏁堝伐鍏? ${validTools.join(", ")}`,
          );
        }
      }
    }
  }

  // 鈹€鈹€ 缁村害浜旓細roundtableTemplates 浜ゅ弶鏍￠獙 鈹€鈹€
  if (config.roundtableTemplates) {
    for (const tmpl of config.roundtableTemplates) {
      if (!tmpl.name || typeof tmpl.name !== "string") {
        result.valid = false;
        result.errors.push("璺ㄥ瓧娈垫牎楠屽け璐? roundtableTemplates 涓瓨鍦ㄧ己灏?name 鐨勬ā鏉縗

${tmpl.name}"].agents 蹇呴』涓烘暟缁刞);
      }
    }
  }

  return result;
}

