/**
 * @cortex/fsm-compiler 鈥?Diagram Generator
 *
 * Generates Mermaid state diagram and Graphviz DOT format from FSM AST.
 */

import type { FsmAst } from "../parser.js";

// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
// Diagram Generator
// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class DiagramGenerator {
  /**
   * Generate Mermaid state diagram.
   *
   * @example Output:
   *   stateDiagram-v2
   *     [*] --> created
   *     created --> awake : wakeup
   *     created --> destroyed : destroy
   */
  toMermaid(ast: FsmAst, _highlight?: string): string {
    const lines: string[] = [];
    lines.push("stateDiagram-v2");
    lines.push("");

    // Initial state pointer
    lines.push(`    [*] --> ${ast.machine.initialState}`);

    // Transitions
    for (const transition of ast.transitionMap.values()) {
      const label = transition.guard
        ? `${transition.event} [${transition.guard}]`
        : transition.event;

      if (transition.from === transition.to) {
        // Self-loop
        lines.push(`    ${transition.from} --> ${transition.to} : ${label}`);
      } else {
        lines.push(`    ${transition.from} --> ${transition.to} : ${label}`);
      }
    }

    // Final states
    for (const finalId of ast.machine.finalStates) {
      lines.push(`    ${finalId} --> [*]`);
    }

    return lines.join("\n") + "\n";
  }

  /**
   * Generate Graphviz DOT format.
   */
  toDot(ast: FsmAst): string {
    const lines: string[] = [];
    lines.push("digraph FSM {");
    lines.push("    rankdir=LR;");
    lines.push("    node [shape=circle];");
    lines.push("");

    // Initial state
    lines.push(`    __start__ [label="" shape=point];`);
    lines.push(`    __start__ -> ${ast.machine.initialState};`);

    // States
    for (const state of ast.stateMap.values()) {
      const isFinal = ast.machine.finalStates.includes(state.id);
      const isInitial = state.id === ast.machine.initialState;
      if (isFinal) {
        lines.push(`    ${state.id} [label="${state.displayName ?? state.id}" shape=doublecircle];`);
      } else if (isInitial) {
        lines.push(`    ${state.id} [label="${state.displayName ?? state.id}" shape=circle style=bold];`);
      } else {
        lines.push(`    ${state.id} [label="${state.displayName ?? state.id}"];`);
      }
    }

    lines.push("");

    // Transitions
    for (const transition of ast.transitionMap.values()) {
      let label = transition.event;
      if (transition.guard) {
        label += ` [${transition.guard}]`;
      }
      if (transition.action) {
        label += ` / ${transition.action}`;
      }
      const style = transition.type === "internal" ? " [style=dashed]" : "";
      lines.push(`    ${transition.from} -> ${transition.to} [label="${label}"${style}];`);
    }

    lines.push("}");
    return lines.join("\n") + "\n";
  }
}

/**
 * @cortex/fsm-compiler 鈥?TypeScript Code Generator
 *
 * Generates TypeScript code from FSM AST.
 *
 * Output includes:
 * 1. Enum of states (string)
 * 2. Enum of events (string)
 * 3. Type-safe transition table (2D matrix: State 脳 Event 鈫?State)
 * 4. Guard function stubs (with JSDoc from DSL)
 * 5. Action function stubs
 * 6. Transition validation function (isValidTransition)
 * 7. State machine class skeleton
 */

import type { FsmAst } from "../parser.js";

// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
// Generator Types
// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export interface GeneratedOutput {
  /** Generated .ts file content */
  types: string;
  /** Generated class with dispatch logic */
  runtime: string;
  /** Guard function stubs */
  guards: string;
  /** Action function stubs */
  actions: string;
  /** Import map 鈥?which imports are needed */
  imports: string[];
}

export interface GenOptions {
  /** Optional namespace prefix for generated enums */
  namespace?: string;
  /** Whether to generate immutable types (readonly) */
  readonly?: boolean;
}

// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
// TypeScript Generator
// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class TypeScriptGenerator {
  generate(ast: FsmAst, options: GenOptions = {}): GeneratedOutput {
    const machineId = ast.machine.id;
    const pascalMachine = this._toPascalCase(machineId);
    const stateEnumName = `${pascalMachine}State`;
    const eventEnumName = `${pascalMachine}Event`;

    const types = this._generateTypes(ast, stateEnumName, eventEnumName, options);
    const runtime = this._generateRuntime(ast, stateEnumName, eventEnumName);
    const guards = this._generateGuards(ast);
    const actions = this._generateActions(ast);

    const imports: string[] = [];
    if (guards.length > 0 || actions.length > 0) {
      imports.push('import type { GuardFn, ActionFn } from "@cortex/fsm-compiler/runtime";');
    }

    return { types, runtime, guards, actions, imports };
  }

  private _generateTypes(
    ast: FsmAst,
    stateEnumName: string,
    eventEnumName: string,
    options: GenOptions,
  ): string {
    const lines: string[] = [];
    const readonly = options.readonly ? "readonly " : "";

    // State enum
    lines.push(`// 鈹€鈹€ State Enum 鈹€鈹€`);
    lines.push(`export enum ${stateEnumName} {`);
    for (const state of ast.machine.states) {
      lines.push(`  ${this._toEnumKey(state.id)} = "${state.id}",`);
    }
    lines.push(`}`);
    lines.push("");

    // Event enum
    lines.push(`// 鈹€鈹€ Event Enum 鈹€鈹€`);
    const events = this._collectEvents(ast);
    lines.push(`export enum ${eventEnumName} {`);
    for (const event of events) {
      lines.push(`  ${this._toEnumKey(event)} = "${event}",`);
    }
    lines.push(`}`);
    lines.push("");

    // Transition table type
    lines.push(`// 鈹€鈹€ Transition Table 鈹€鈹€`);
    lines.push(`export type ${stateEnumName}TransitionTable = {`);
    lines.push(`  ${readonly}[state in ${stateEnumName}]?: {`);
    lines.push(`    ${readonly}[event in ${eventEnumName}]?: ${stateEnumName};`);
    lines.push(`  };`);
    lines.push(`};`);
    lines.push("");

    // Transition table constant
    lines.push(`export const TRANSITION_TABLE: ${stateEnumName}TransitionTable = {`);
    for (const [stateId, transitions] of ast.adjacencyList) {
      const stateKey = this._toEnumKey(stateId);
      lines.push(`  [${stateEnumName}.${stateKey}]: {`);
      for (const t of transitions) {
        const eventKey = this._toEnumKey(t.event);
        const toKey = this._toEnumKey(t.to);
        lines.push(`    [${eventEnumName}.${eventKey}]: ${stateEnumName}.${toKey},`);
      }
      lines.push(`  },`);
    }
    lines.push(`};`);

    return lines.join("\n");
  }

  private _generateRuntime(
    ast: FsmAst,
    stateEnumName: string,
    eventEnumName: string,
  ): string {
    const lines: string[] = [];

    lines.push(`// 鈹€鈹€ State Machine Runtime 鈹€鈹€`);
    lines.push(`import { ${stateEnumName}, ${eventEnumName} } from "./types";`);
    lines.push("");

    lines.push(`export class ${stateEnumName}Machine {`);
    lines.push(`  private _current: ${stateEnumName};`);
    lines.push(`  private _history: Array<{ from: ${stateEnumName}; to: ${stateEnumName}; event: ${eventEnumName}; timestamp: number }> = [];`);
    lines.push("");
    lines.push(`  constructor(initialState: ${stateEnumName} = ${stateEnumName}.${this._toEnumKey(ast.machine.initialState)}) {`);
    lines.push(`    this._current = initialState;`);
    lines.push(`  }`);
    lines.push("");
    lines.push(`  get current(): ${stateEnumName} {`);
    lines.push(`    return this._current;`);
    lines.push(`  }`);
    lines.push("");
    lines.push(`  get history() {`);
    lines.push(`    return this._history as readonly typeof this._history;`);
    lines.push(`  }`);
    lines.push("");
    lines.push(`  can(event: ${eventEnumName}): boolean {`);
    lines.push(`    const table = TRANSITION_TABLE[this._current];`);
    lines.push(`    return table != null && event in table;`);
    lines.push(`  }`);
    lines.push("");
    lines.push(`  dispatch(event: ${eventEnumName}): ${stateEnumName} {`);
    lines.push(`    const table = TRANSITION_TABLE[this._current];`);
    lines.push(`    if (!table || !(event in table)) {`);
    lines.push(`      throw new Error(\`Invalid transition: \${this._current} -> \${event}\`);`);
    lines.push(`    }`);
    lines.push(`    const next = table[event]!;`);
    lines.push(`    this._history.push({ from: this._current, to: next, event, timestamp: Date.now() });`);
    lines.push(`    this._current = next;`);
    lines.push(`    return next;`);
    lines.push(`  }`);
    lines.push("");
    lines.push(`  reset(): void {`);
    lines.push(`    this._current = ${stateEnumName}.${this._toEnumKey(ast.machine.initialState)};`);
    lines.push(`    this._history = [];`);
    lines.push(`  }`);
    lines.push("");
    lines.push(`  get isFinal(): boolean {`);
    lines.push(`    const finals: ${stateEnumName}[] = [${ast.machine.finalStates.map((s) => `${stateEnumName}.${this._toEnumKey(s)}`).join(", ")}];`);
    lines.push(`    return finals.includes(this._current);`);
    lines.push(`  }`);
    lines.push(`}`);
    lines.push("");

    return lines.join("\n");
  }

  private _generateGuards(ast: FsmAst): string {
    const guardNames = new Set<string>();
    for (const t of ast.transitionMap.values()) {
      if (t.guard) {
        guardNames.add(t.guard);
      }
    }

    if (guardNames.size === 0) {
      return "// No guards defined\n";
    }

    const lines: string[] = [];
    lines.push(`// 鈹€鈹€ Guard Function Stubs 鈹€鈹€`);
    for (const name of guardNames) {
      lines.push(`export function ${name}(context: unknown): boolean {`);
      lines.push(`  // TODO: implement guard logic`);
      lines.push(`  return true;`);
      lines.push(`}`);
      lines.push("");
    }
    return lines.join("\n");
  }

  private _generateActions(ast: FsmAst): string {
    const actionNames = new Set<string>();
    for (const t of ast.transitionMap.values()) {
      if (t.action) {
        actionNames.add(t.action);
      }
    }

    if (actionNames.size === 0) {
      return "// No actions defined\n";
    }

    const lines: string[] = [];
    lines.push(`// 鈹€鈹€ Action Function Stubs 鈹€鈹€`);
    for (const name of actionNames) {
      lines.push(`export function ${name}(context: unknown): void {`);
      lines.push(`  // TODO: implement action logic`);
      lines.push(`}`);
      lines.push("");
    }
    return lines.join("\n");
  }

  // 鈹€鈹€ Helpers 鈹€鈹€

  private _collectEvents(ast: FsmAst): string[] {
    const eventSet = new Set<string>();
    for (const t of ast.transitionMap.values()) {
      eventSet.add(t.event);
    }
    return Array.from(eventSet).sort();
  }

  private _toPascalCase(str: string): string {
    return str
      .split(/[_-]/)
      .map((s) => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase())
      .join("");
  }

  private _toEnumKey(str: string): string {
    // Convert snake_case or kebab-case to PascalCase for enum keys
    return str
      .split(/[_-]/)
      .map((s, i) => (i === 0 ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : s.charAt(0).toUpperCase() + s.slice(1).toLowerCase()))
      .join("");
  }
}

/**
 * @cortex/fsm-compiler 鈥?FSM Parser
 *
 * Parses FSM DSL definitions (JSON) into an AST representation
 * with map-based lookups for efficient validation and code generation.
 */

import type { FsmDefinition, FsmStateDefinition, FsmTransitionDefinition } from "../dsl/schema.js";

// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
// AST Types
// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export interface FsmAst {
  machine: FsmDefinition;
  stateMap: Map<string, FsmStateDefinition>;
  transitionMap: Map<string, FsmTransitionDefinition>;
  adjacencyList: Map<string, FsmTransitionDefinition[]>;
  /** Reverse adjacency for reachability analysis */
  reverseAdjacency: Map<string, FsmTransitionDefinition[]>;
}

// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
// Parse Error
// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class FsmParseError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly nodeId?: string,
  ) {
    super(message);
    this.name = "FsmParseError";
  }
}

// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
// Parser
// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class FsmParser {
  /**
   * Parse a JSON FSM definition string into an AST.
   *
   * Validation performed:
   *   - Required fields present
   *   - State IDs referenced in transitions exist in states array
   *   - No duplicate state/transition IDs
   *   - Initial state is a valid state ID
   *   - Final states are all valid state IDs
   */
  parse(json: string): FsmAst {
    const raw = JSON.parse(json) as FsmDefinition;
    return this.parseObject(raw);
  }

  /**
   * Parse a pre-parsed FsmDefinition object into an AST.
   */
  parseObject(definition: FsmDefinition): FsmAst {
    // --- Validate required fields ---
    if (!definition.id) {
      throw new FsmParseError("Machine id is required", "MISSING_FIELD", "id");
    }
    if (!definition.initialState) {
      throw new FsmParseError("initialState is required", "MISSING_FIELD", "initialState");
    }
    if (!definition.states || definition.states.length === 0) {
      throw new FsmParseError("At least one state is required", "MISSING_STATES");
    }
    if (!definition.transitions) {
      throw new FsmParseError("transitions field is required", "MISSING_FIELD", "transitions");
    }

    // --- Build state map & check duplicates ---
    const stateMap = new Map<string, FsmStateDefinition>();
    for (const state of definition.states) {
      if (stateMap.has(state.id)) {
        throw new FsmParseError(`Duplicate state id: "${state.id}"`, "DUPLICATE_STATE", state.id);
      }
      stateMap.set(state.id, state);
    }

    // --- Validate initial state ---
    if (!stateMap.has(definition.initialState)) {
      throw new FsmParseError(
        `Initial state "${definition.initialState}" not found in states`,
        "INVALID_INITIAL",
        definition.initialState,
      );
    }

    // --- Validate final states ---
    for (const finalId of definition.finalStates) {
      if (!stateMap.has(finalId)) {
        throw new FsmParseError(
          `Final state "${finalId}" not found in states`,
          "INVALID_FINAL",
          finalId,
        );
      }
    }

    // --- Build transition map & adjacency lists ---
    const transitionMap = new Map<string, FsmTransitionDefinition>();
    const adjacencyList = new Map<string, FsmTransitionDefinition[]>();
    const reverseAdjacency = new Map<string, FsmTransitionDefinition[]>();

    for (const transition of definition.transitions) {
      // Check duplicate transition IDs
      if (transitionMap.has(transition.id)) {
        throw new FsmParseError(
          `Duplicate transition id: "${transition.id}"`,
          "DUPLICATE_TRANSITION",
          transition.id,
        );
      }

      // Validate from/to states exist
      if (!stateMap.has(transition.from)) {
        throw new FsmParseError(
          `Transition "${transition.id}" references unknown state "${transition.from}" as source`,
          "MISSING_STATE",
          transition.id,
        );
      }
      if (!stateMap.has(transition.to)) {
        throw new FsmParseError(
          `Transition "${transition.id}" references unknown state "${transition.to}" as target`,
          "MISSING_STATE",
          transition.id,
        );
      }

      transitionMap.set(transition.id, transition);

      // Forward adjacency
      if (!adjacencyList.has(transition.from)) {
        adjacencyList.set(transition.from, []);
      }
      const fromList = adjacencyList.get(transition.from);
      if (fromList) {
        fromList.push(transition);
      }

      // Reverse adjacency
      if (!reverseAdjacency.has(transition.to)) {
        reverseAdjacency.set(transition.to, []);
      }
      const toList = reverseAdjacency.get(transition.to);
      if (toList) {
        toList.push(transition);
      }
    }

    return {
      machine: definition,
      stateMap,
      transitionMap,
      adjacencyList,
      reverseAdjacency,
    };
  }
}

/**
 * @cortex/fsm-compiler 鈥?FSM Validator
 *
 * Performs semantic analysis on a parsed FSM AST:
 * 1. Reachability 鈥?every state reachable from initial state?
 * 2. Completeness 鈥?every state has defined transitions for all possible events?
 * 3. Determinism 鈥?no ambiguous transitions (same state + same event 鈫?different targets)
 * 4. Deadlock 鈥?no non-final state without outgoing transitions
 * 5. Event Consistency 鈥?events used in transitions are defined
 * 6. Self-loop Consistency 鈥?self-transitions have type:"self" or type:"internal"
 */

import type { FsmAst } from "./parser.js";

// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
// Validation Types
// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export type ValidationErrorCode =
  | "UNREACHABLE_STATE"
  | "DEADLOCK"
  | "NON_DETERMINISTIC"
  | "INVALID_REFERENCE"
  | "MISSING_STATE"
  | "DUPLICATE_ID"
  | "INVALID_INITIAL"
  | "INVALID_FINAL"
  | "SELF_LOOP_INCONSISTENT";

export interface ValidationError {
  code: ValidationErrorCode;
  nodeId: string;
  message: string;
}

export interface ValidationWarning {
  code: string;
  nodeId: string;
  message: string;
}

export interface ValidationMetrics {
  stateCount: number;
  transitionCount: number;
  reachableStates: number;
  unreachableStates: string[];
  hasDeadlock: boolean;
  deterministic: boolean;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  warnings: ValidationWarning[];
  metrics: ValidationMetrics;
}

// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
// Validator
// 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class FsmValidator {
  /**
   * Validate a parsed FSM AST.
   */
  validate(ast: FsmAst): ValidationResult {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    // 1. Reachability 鈥?BFS from initial state
    const reachable = this._computeReachable(ast);
    const unreachableStates: string[] = [];
    for (const stateId of ast.stateMap.keys()) {
      if (!reachable.has(stateId)) {
        unreachableStates.push(stateId);
        errors.push({
          code: "UNREACHABLE_STATE",
          nodeId: stateId,
          message: `State "${stateId}" is unreachable from initial state "${ast.machine.initialState}"`,
        });
      }
    }

    // 2. Deadlock 鈥?non-final states with no outgoing transitions
    const finalSet = new Set(ast.machine.finalStates);
    for (const stateId of ast.stateMap.keys()) {
      if (finalSet.has(stateId)) continue; // final states are allowed to have no outgoing
      const transitions = ast.adjacencyList.get(stateId);
      if (!transitions || transitions.length === 0) {
        errors.push({
          code: "DEADLOCK",
          nodeId: stateId,
          message: `Non-final state "${stateId}" has no outgoing transitions (deadlock)`,
        });
      }
    }

    // 3. Determinism 鈥?check for ambiguous transitions
    const eventMap = new Map<string, Map<string, string>>(); // state 鈫?(event 鈫?transitionId)
    let deterministic = true;
    for (const [stateId, transitions] of ast.adjacencyList) {
      const eventToTransition = new Map<string, string>();
      for (const t of transitions) {
        if (eventToTransition.has(t.event)) {
          deterministic = false;
          errors.push({
            code: "NON_DETERMINISTIC",
            nodeId: t.id,
            message: `State "${stateId}" has ambiguous transitions for event "${t.event}": "${eventToTransition.get(t.event)}" and "${t.id}"`,
          });
        }
        eventToTransition.set(t.event, t.id);
      }
      eventMap.set(stateId, eventToTransition);
    }

    // 4. Self-loop consistency
    for (const transition of ast.transitionMap.values()) {
      if (transition.from === transition.to) {
        if (transition.type !== "self" && transition.type !== "internal") {
          warnings.push({
            code: "SELF_LOOP_INCONSISTENT",
            nodeId: transition.id,
            message: `Self-loop transition "${transition.id}" should have type:"self" or type:"internal" (currently: "${transition.type ?? "external"}")`,
          });
        }
      }
    }

    const hasDeadlock = errors.some((e) => e.code === "DEADLOCK");

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      metrics: {
        stateCount: ast.stateMap.size,
        transitionCount: ast.transitionMap.size,
        reachableStates: reachable.size,
        unreachableStates,
        hasDeadlock,
        deterministic,
      },
    };
  }

  /**
   * BFS from initial state to compute reachable states.
   */
  private _computeReachable(ast: FsmAst): Set<string> {
    const visited = new Set<string>();
    const queue = [ast.machine.initialState];
    visited.add(ast.machine.initialState);

    while (queue.length > 0) {
      const current = queue.shift();
      if (!current) continue;
      const transitions = ast.adjacencyList.get(current);
      if (!transitions) continue;

      for (const t of transitions) {
        if (!visited.has(t.to)) {
          visited.add(t.to);
          queue.push(t.to);
        }
      }
    }

    return visited;
  }
}

