/**
 * 淇鎵ц鍣ㄣ€俓r
 *
 * 瑁佸喅鏉冧簩鍒嗏€斺€斾粎寮€鎷撹€呰鍐抽€氳繃鍚庤皟鐢ㄣ€俓r
 * 璇诲彇瀹硶鍏ㄦ枃 鈫?澶囦唤 鈫?鎵ц before鈫抋fter 鏇挎崲 鈫?鏇存柊鐗堟湰鍙穃r
 * 鈫?杩藉姞鍙樻洿鍘嗗彶 鈫?鍐欏叆鏂囦欢 鈫?鍚屾鏂囦欢鍚嶇増鏈彿銆俓r
 *
 * @module amendment-applier
 */

import * as fs from "node:fs";
import * as path from "node:path";
import type { AmendmentProposal, AmendmentApplyResult } from "@cortex/shared";

/** 瀹硶鏂囦欢鍚嶆ā寮忊€斺€斿尮閰嶆墍鏈?Cortex 姒傚康椤跺眰璁捐 md 鏂囦欢 */
const CONSTITUTION_PATTERN = /^Cortex 姒傚康椤跺眰璁捐 v[\d.]+.md$/;

/** 瀹硶鏂囦欢鎵€鍦ㄧ洰褰曪紙鐩稿浜庨」鐩牴锛?*/
const CONSTITUTION_DIR = "docs/constitution";

// 鈹€鈹€鈹€ 瀹硶鏂囦欢瀹氫綅 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 鍦ㄩ」鐩牴鐩綍涓嬫壂鎻忓娉曟枃浠躲€俓r
 * 鎸夌増鏈彿闄嶅簭鎺掑垪锛屽彇鏈€鏂拌€呫€俓r
 *
 * @param rootDir 椤圭洰鏍圭洰褰昞r
 * @returns 瀹硶鏂囦欢鐨勫畬鏁磋矾寰刓r
 * @throws 鎵句笉鍒板娉曟枃浠舵椂鎶涘嚭
 */
export function findConstitutionPath(rootDir: string): string {
  const dir = path.resolve(rootDir, CONSTITUTION_DIR);
  if (!fs.existsSync(dir)) {
    throw new Error(`瀹硶鐩綍涓嶅瓨鍦細${dir}`);
  }

  const files = fs.readdirSync(dir).filter((f) => CONSTITUTION_PATTERN.test(f));
  if (files.length === 0) {
    throw new Error(`鍦?${dir} 涓壘涓嶅埌鍖归厤 "Cortex 姒傚康椤跺眰璁捐 v*.md" 鐨勫娉曟枃浠禶);
  }

  // 鎸夌増鏈彿闄嶅簭鈥斺€斿彇鏈€鏂扮殑
  files.sort((a, b) => {
    const va = (a.match(/v([\d.]+)/)?.[1] ?? "0").split(".").map(Number);
    const vb = (b.match(/v([\d.]+)/)?.[1] ?? "0").split(".").map(Number);
    for (let i = 0; i < Math.max(va.length, vb.length); i++) {
      if ((vb[i] ?? 0) !== (va[i] ?? 0)) return (vb[i] ?? 0) - (va[i] ?? 0);
    }
    return 0;
  });

  return path.join(dir, files[0]);
}

/**
 * 鍦ㄥ娉曠増鏈彿琛屼笅鏂硅拷鍔犳湰娆″彉鏇寸殑鍘嗗彶鏉＄洰銆俓r
 * 鐗堟湰鍙疯鏍煎紡锛歚**鐗堟湰**锛歷X.Y.Z`
 */
function appendChangelogEntry(content: string, proposal: AmendmentProposal): string {
  const versionLineRe = /^(\*\*鐗堟湰\*\*[锛?]\s*v[\d.]+.*)$/m;
  const match = content.match(versionLineRe);
  if (!match) return content;

  const fullLine = match[0];
  const idx = match.index;
  if (idx === undefined) return content;
  const insertionIndex = idx + fullLine.length;
  const before = content.slice(0, insertionIndex);
  const after = content.slice(insertionIndex);

  const date = new Date().toISOString().slice(0, 10);
  const entry = ` 鈫?${proposal.version}锛?{proposal.id}锛?{proposal.summary}锛?{date}锛涙潵婧愶細${proposal.source.agent}鈥斺€?{proposal.source.trace}锛塦;

  return before + entry + after;
}

/**
 * 鎵ц淇鎻愭鐨勬枃鏈浛鎹€俓r
 *
 * - modify/remove: 鐢?after 鏇挎崲 before
 * - add: before 涓虹┖鏃朵笉鍋氭浛鎹紙浠呮洿鏂扮増鏈彿 + 杩藉姞鍙樻洿鍘嗗彶锛塡r
 * - restructure: 鍚?modify
 *
 * 瀹夊叏绾︽潫锛氫粎鍦ㄦ彁妗堢姸鎬佷负 "approved" 涓斿紑鎷撹€呮槑纭‘璁ゅ悗璋冪敤銆俓r
 */
function applyTextChanges(content: string, proposal: AmendmentProposal): string {
  if (proposal.category === "add" && !proposal.before.trim()) {
    // 绾柊澧炩€斺€斿皢 after 鏂囨湰鎻掑叆瀹硶浣撴湯灏撅紙鏂囨。鐘舵€佽涔嬪墠锛塡r
    const docStatusRe = /^\*\*鏂囨。鐘舵€乗\*\*[锛?]/m;
    const match = content.match(docStatusRe);
    if (match?.index !== undefined) {
      // 鍦ㄦ枃妗ｇ姸鎬佽涔嬪墠鎻掑叆锛屽墠鍚庡悇鍔犵┖琛屼繚鎸佹牸寮廫r
      const before = content.slice(0, match.index);
      const after = content.slice(match.index);
      return before.trimEnd() + "\n\n" + proposal.after.trim() + "\n\n" + after;
    }
    // 娌℃湁鎵惧埌鏂囨。鐘舵€佽锛岃拷鍔犲埌鏈熬
    return content.trimEnd() + "\n\n" + proposal.after.trim() + "\n";
  }

  // modify / remove / restructure锛氭墽琛屾枃鏈浛鎹r
  // 閫愪釜鏇挎崲鎵€鏈夊嚭鐜帮紙閫氬父鍙湁涓€澶勶紝浣嗕繚瀹堝鐞嗭級
  const result = content;
  let replaced = false;

  // 鏍囧噯鍖栫┖鐧藉瓧绗﹀悗鍋氱簿纭尮閰嶏紝鐒跺悗鍋氬師濮嬫浛鎹r
  const normalize = (s: string) => s.replace(/\s+/g, " ").trim();

  const lines = result.split("\n");
  const searchNormalized = normalize(proposal.before);

  // 婊戝姩绐楀彛鍖归厤
  const beforeLines = proposal.before.split("\n");
  const windowSize = beforeLines.length;

  for (let i = 0; i <= lines.length - windowSize; i++) {
    const windowText = lines.slice(i, i + windowSize).join("\n");
    if (normalize(windowText) === searchNormalized) {
      const afterLines = proposal.after.split("\n");
      lines.splice(i, windowSize, ...afterLines);
      replaced = true;
      break; // 浠呮浛鎹㈢涓€澶勫尮閰峔r
    }
  }

  if (!replaced) {
    throw new Error(
      `鏃犳硶鍦ㄥ娉曚腑鎵惧埌 before 娈佃惤銆傛彁妗?ID: ${proposal.id}锛宻ection: ${proposal.section}`,
    );
  }

  return lines.join("\n");
}

// 鈹€鈹€鈹€ 澶囦唤 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 鍦ㄥ啓鍏ュ墠灏嗗綋鍓嶅娉曞唴瀹瑰浠藉埌 archive 鐩綍銆俓r
 * 鏂囦欢鍚嶆牸寮忥細Cortex 姒傚康椤跺眰璁捐 v2.5.10-backup-2026-05-19T23-50-00.md
 */
function backupConstitution(filePath: string): string | null {
  try {
    if (!fs.existsSync(filePath)) return null;
    const dir = path.dirname(filePath);
    const baseName = path.basename(filePath, ".md");
    const ts = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
    const archiveDir = path.resolve(dir, "archive");
    fs.mkdirSync(archiveDir, { recursive: true });
    const backupName = path.join(archiveDir, `${baseName}-backup-${ts}.md`);
    fs.copyFileSync(filePath, backupName);
    return backupName;
  } catch {
    return null; // 澶囦唤澶辫触涓嶉樆濉炰慨瀹猏r
  }
}

/**
 * 灏嗗娉曟枃浠堕噸鍛藉悕涓哄寘鍚柊鐗堟湰鍙风殑鏂囦欢鍚嶃€俓r
 * 渚嬪锛欳ortex 姒傚康椤跺眰璁捐 v2.5.md 鈫?Cortex 姒傚康椤跺眰璁捐 v2.5.11.md
 */
function renameToVersion(filePath: string, newVersion: string): string {
  const dir = path.dirname(filePath);
  const oldBase = path.basename(filePath);
  const newName = oldBase.replace(/v\d+(?:\.\d+)*(?=\.md$)/, newVersion);
  if (newName === oldBase) return filePath; // 娌″彉

  const newPath = path.join(dir, newName);
  try {
    fs.renameSync(filePath, newPath);
    return newPath;
  } catch {
    return filePath; // 閲嶅懡鍚嶅け璐ヤ笉闃诲锛屼繚鐣欐棫鏂囦欢鍚峔r
  }
}

// 鈹€鈹€鈹€ 淇鍐欏叆 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 淇鍐欏叆銆俓r
 *
 * @param proposal 宸茶鍐抽€氳繃鐨勪慨瀹彁妗圽r
 * @param constitutionPath 瀹硶鏂囦欢鐨勫畬鏁磋矾寰勶紙鍚枃浠跺悕锛夈€傚涓嶆彁渚涘垯鑷姩鎵弿銆俓r
 * @returns 鍐欏叆缁撴灉
 */
export function applyAmendment(
  proposal: AmendmentProposal,
  constitutionPath?: string,
): AmendmentApplyResult {
  const filePath = constitutionPath
    ? path.resolve(constitutionPath)
    : findConstitutionPath(process.cwd());

  try {
    if (!fs.existsSync(filePath)) {
      return {
        success: false,
        appliedVersion: proposal.version,
        error: `瀹硶鏂囦欢涓嶅瓨鍦細${filePath}`,
        filePath,
      };
    }

    // 0. 澶囦唤褰撳墠瀹硶
    backupConstitution(filePath);

    let content = fs.readFileSync(filePath, "utf-8");

    // 1. 鎵ц鏂囨湰鏇挎崲
    content = applyTextChanges(content, proposal);

    // 2. 鏇存柊鐗堟湰鍙疯
    const versionLineRe = /^(\*\*鐗堟湰\*\*[锛?]\s*)v[\d.]+(.*)$/m;
    if (versionLineRe.test(content)) {
      content = content.replace(versionLineRe, `$1${proposal.version}$2`);
    }

    // 3. 杩藉姞鍙樻洿鍘嗗彶鏉＄洰
    content = appendChangelogEntry(content, proposal);

    // 4. 鍐欏叆鏂囦欢
    fs.writeFileSync(filePath, content, "utf-8");

    // 5. 鏂囦欢鍚嶅悓姝ョ増鏈彿
    const finalPath = renameToVersion(filePath, proposal.version);

    return {
      success: true,
      appliedVersion: proposal.version,
      filePath: finalPath,
    };
  } catch (e) {
    return {
      success: false,
      appliedVersion: proposal.version,
      error: String(e),
      filePath,
    };
  }
}

/**
 * 淇鎻愭璇勫垽寮曟搸銆俓r
 *
 * 瑁佸喅鏉冧簩鍒嗭細
 *   - 寮€鎷撹€咃細鏈€缁堝喅瀹氭潈锛屼慨鏀瑰娉曟枃鏈琝r
 *   - 鏄旀稛锛氳鍙栨彁妗堛€佽緭鍑鸿瘎鍒わ紝涓嶆搮鑷惤绗擻r
 *
 * evaluateAmendment() 瀵圭収瀹硶鍏ㄦ枃閫愰」妫€鏌ユ彁妗堢殑鍚堣鎬с€佷竴鑷存€у拰椋庨櫓銆俓r
 *
