// ============================================================
// @cortex/engine/governance/amendment-timeout 鈥斺€?鎻愭瓒呮椂澶勭疆
//
// 瓒呮椂鑷姩澶勭疆锛歕r
//   1. pending_judgment 瓒呰繃 TTL 鈫?鑷姩鏍囪涓?needs_attention
//   2. draft 瓒呰繃 TTL 鈫?鎻愮ず娓呯悊鎴栨帹杩沑r
//   3. 澶氭瓒呮椂 鈫?鍗囩骇涓?rejected锛堝兊灏告彁妗堟竻鐞嗭級
//
// @since Core-2
// ============================================================

import type { AmendmentProposal } from "@cortex/shared";
import * as fs from "node:fs";
import * as path from "node:path";

// 鈹€鈹€鈹€ 绫诲瀷 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 瓒呮椂澶勭疆鍔ㄤ綔 */
export interface TimeoutAction {
  /** 鎻愭 ID */
  proposalId: string;
  /** 褰撳墠鐘舵€?*/
  currentStatus: string;
  /** 寤鸿鍔ㄤ綔 */
  action: "needs_attention" | "warn_stale" | "auto_reject" | "auto_close";
  /** 瓒呮椂澶╂暟 */
  daysPending: number;
  /** 浜虹被鍙鐨勫師鍥?*/
  reason: string;
}

/** 瓒呮椂閰嶇疆 */
export interface TimeoutConfig {
  /** pending_judgment 瓒呮椂澶╂暟锛堥粯璁?7 澶╋級 */
  judgmentTTLDays: number;
  /** draft 瓒呮椂澶╂暟锛堥粯璁?14 澶╋級 */
  draftTTLDays: number;
  /** 杩炵画瓒呮椂鑷姩鎷掔粷鐨勯槇鍊硷紙榛樿 3 娆★級 */
  maxStaleCount: number;
}

const DEFAULT_TIMEOUT_CONFIG: TimeoutConfig = {
  judgmentTTLDays: 7,
  draftTTLDays: 14,
  maxStaleCount: 3,
};

// 鈹€鈹€鈹€ 鏍稿績閫昏緫 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 妫€鏌ユ彁妗堣秴鏃讹紝杩斿洖澶勭疆鍔ㄤ綔鍒楄〃銆俓r
 *
 * @param proposals 寰呮鏌ョ殑鎻愭鍒楄〃
 * @param amendmentsDir 淇鎻愭鐩綍锛堢敤浜庤鍙栨枃浠朵慨鏀规椂闂达級
 * @param config 瓒呮椂閰嶇疆锛堝彲閫夛級
 * @returns 瓒呮椂澶勭疆鍔ㄤ綔锛堢┖鏁扮粍琛ㄧず鏃犻渶澶勭疆锛塡r
 */
export function checkTimeout(
  proposals: AmendmentProposal[],
  amendmentsDir: string,
  config: Partial<TimeoutConfig> = {},
): TimeoutAction[] {
  const cfg = { ...DEFAULT_TIMEOUT_CONFIG, ...config };
  const now = Date.now();
  const actions: TimeoutAction[] = [];

  for (const proposal of proposals) {
    // 鍙鏌ヨ崏绋垮拰寰呭喅鎻愭
    if (proposal.status !== "draft" && proposal.status !== "pending_judgment") {
      continue;
    }

    // 璇诲彇鏂囦欢鏈€鍚庝慨鏀规椂闂翠綔涓轰唬鐞哱r
    const filePath = path.join(amendmentsDir, `${proposal.id}.json`);
    const daysPending = getDaysSinceModified(filePath, now);

    if (proposal.status === "pending_judgment") {
      if (daysPending > cfg.judgmentTTLDays) {
        const staleCount = getStaleCount(proposal.id, amendmentsDir);
        if (staleCount >= cfg.maxStaleCount) {
          actions.push({
            proposalId: proposal.id,
            currentStatus: proposal.status,
            action: "auto_reject",
            daysPending,
            reason: `鎻愭 ${proposal.id} 绛夊緟璇勫垽瓒呰繃 ${daysPending} 澶╋紙TTL: ${cfg.judgmentTTLDays} 澶╋級锛宍 +
              `宸茶繛缁?${staleCount} 娆¤秴鏃讹紝寤鸿鑷姩鎷掔粷骞跺綊妗ｃ€俙,
          });
        } else {
          actions.push({
            proposalId: proposal.id,
            currentStatus: proposal.status,
            action: "needs_attention",
            daysPending,
            reason: `鎻愭 ${proposal.id} 绛夊緟璇勫垽瓒呰繃 ${daysPending} 澶╋紙TTL: ${cfg.judgmentTTLDays} 澶╋級锛宍 +
              `璇峰紑鎷撹€呭敖蹇鍐筹紙绗?${staleCount} 娆℃彁閱掞級銆俙,
          });
        }
      }
    } else if (proposal.status === "draft") {
      if (daysPending > cfg.draftTTLDays) {
        actions.push({
          proposalId: proposal.id,
          currentStatus: proposal.status,
          action: "warn_stale",
          daysPending,
          reason: `鑽夋 ${proposal.id} 宸插仠婊?${daysPending} 澶╋紙TTL: ${cfg.draftTTLDays} 澶╋級锛宍 +
            `寤鸿鎺ㄨ繘涓?pending_judgment 鎴栧叧闂€俙,
        });
      }
    }
  }

  return actions;
}

// 鈹€鈹€鈹€ 宸ュ叿鍑芥暟 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 鑾峰彇鏂囦欢鐨勬渶鍚庝慨鏀规椂闂磋嚦浠婄殑澶╂暟銆俓r
 * 鏂囦欢涓嶅瓨鍦ㄦ椂杩斿洖 0锛堟柊鎻愭锛屽皻鏈啓鍏ユ枃浠讹級銆俓r
 */
function getDaysSinceModified(filePath: string, now: number): number {
  try {
    const stat = fs.statSync(filePath);
    return Math.floor((now - stat.mtimeMs) / (1000 * 60 * 60 * 24));
  } catch {
    return 0;
  }
}

/**
 * 璇诲彇瓒呮椂璁℃暟鏂囦欢锛堢畝鍗曡拷锟斤拷锛夈€俓r
 * 瀛樺偍鏍煎紡锛氭瘡琛?"proposalId:count"
 */
function getStaleCount(proposalId: string, amendmentsDir: string): number {
  const counterPath = path.join(amendmentsDir, ".timeout-counters.json");
  try {
    const raw = fs.readFileSync(counterPath, "utf-8");
    const counters = JSON.parse(raw) as Record<string, number>;
    return counters[proposalId] ?? 1;
  } catch {
    return 1;
  }
}

/**
 * 鏇存柊瓒呮椂璁℃暟锛堟瘡娆¤秴鏃舵鏌ュ悗璋冪敤锛夈€?*/
export function updateStaleCount(
  proposalId: string,
  amendmentsDir: string,
): void {
  const counterPath = path.join(amendmentsDir, ".timeout-counters.json");
  let counters: Record<string, number> = {};
  try {
    const raw = fs.readFileSync(counterPath, "utf-8");
    counters = JSON.parse(raw) as Record<string, number>;
  } catch {
    // 鏂囦欢涓嶅瓨鍦紝浠庡ご寮€濮媆r
  }
  counters[proposalId] = (counters[proposalId] ?? 0) + 1;
  fs.writeFileSync(counterPath, JSON.stringify(counters, null, 2), "utf-8");
}

