/**
 * GovernancePipeline 鈥斺€?娌荤悊绠＄嚎缂栨帓鍣ㄣ€俓r
 *
 * 灏嗗垎鏁ｇ殑鍒跺害鐜妭涓茶仈涓轰竴鏉＄鍒扮闂幆锛歕r
 *   鑷瑙?鈫?鍦嗘鍏辫瘑 鈫?淇鎻愭 鈫?鏄旀稛璇勫垽 鈫?寮€鎷撹€呰鍐?鈫?瀹硶鍐欏叆 鈫?CI 楠岃瘉
 *
 * 璁捐鍘熷垯锛歕r
 *   - 闃舵鍙彃鎷旓細姣忛樁娈垫槸鐙珛鐨?Stage 鍑芥暟锛屾柊澧為樁娈靛彧闇€ register
 *   - 瑁佸喅鏉冧簩鍒嗭細寮€鎷撹€呮渶缁堝喅瀹氾紝鏄旀稛鍙瘎鍒や笉钀界瑪
 *   - 澶辫触涓嶆墿鏁ｏ細浠讳竴闃舵澶辫触闃绘柇涓嬫父锛屼絾涓嶅洖婊氬凡瀹屾垚闃舵
 *   - 鎷撳睍绌洪棿锛氶€氳繃 stageRegistry 鍙敞鍐岃嚜瀹氫箟闃舵
 *
 * @module governance-pipeline
 */

import * as fs from "node:fs";
import * as path from "node:path";
import {
  saveProposal,
  judgeProposals,
  applyApproved,
  summarizeGovernance,
  type BatchJudgment,
  type GovernanceSummary,
} from "./governance-loop.js";

// 鈹€鈹€鈹€ 绫诲瀷 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 绠＄嚎闃舵鏍囪瘑 */
export type PipelineStageId =
  | "examination"       // 鑷瑙哱r
  | "roundtable"        // 鍦嗘鍏辫瘑
  | "amendment_draft"   // 淇鎻愭璧疯崏
  | "judgment"          // 鏄旀稛璇勫垽
  | "ruler_decision"    // 寮€鎷撹€呰鍐砛r
  | "apply"             // 瀹硶鍐欏叆
  | "ci_verify"         // CI 闂ㄧ楠岃瘉
  | "archive";          // 褰掓。

/** 闃舵鎵ц缁撴灉 */
export interface StageResult {
  stage: PipelineStageId;
  success: boolean;
  message: string;
  /** 闃舵浜у嚭鐨勬暟鎹紙渚涗笅娓搁樁娈垫秷璐癸級 */
  data?: unknown;
  /** 澶辫触鏃堕樆鏂笅娓?*/
  blocking: boolean;
}

/** 闃舵鎵ц鍑芥暟 */
export type StageFn = (ctx: PipelineContext) => Promise<StageResult>;

/** 绠＄嚎涓婁笅鏂団€斺€斿湪闃舵闂翠紶閫掑叡浜姸鎬?*/
export interface PipelineContext {
  /** 椤圭洰鏍圭洰褰?*/
  rootDir: string;
  /** 鍚勯樁娈典骇鐗╁叡浜瓨鍌?*/
  artifacts: Map<PipelineStageId, unknown>;
  /** 宸叉墽琛岄樁娈电殑缁撴灉 */
  stageResults: StageResult[];
  /** 鐢ㄦ埛鍥炶皟锛氳姹傚紑鎷撹€呰鍐?*/
  onRulerDecision?: (proposals: BatchJudgment[]) => Promise<BatchJudgment[]>;
}

/** 绠＄嚎閰嶇疆 */
export interface PipelineConfig {
  /** 椤圭洰鏍圭洰褰?*/
  rootDir: string;
  /** 鍚敤鐨勯樁娈靛垪琛紙鎸夊簭鎵ц锛?*/
  stages?: PipelineStageId[];
  /** 鐢ㄦ埛鍥炶皟 */
  onRulerDecision?: (proposals: BatchJudgment[]) => Promise<BatchJudgment[]>;
  /** 闃舵娉ㄥ唽瑕嗙洊 */
  stageOverrides?: Partial<Record<PipelineStageId, StageFn>>;
}

/** 绠＄嚎杩愯缁撴灉 */
export interface PipelineResult {
  success: boolean;
  /** 闃绘柇闃舵 ID锛堟垚鍔熸椂涓?null锛?*/
  blockedAt: PipelineStageId | null;
