/** 娉ㄥ唽/瑕嗗啓涓€涓绾块樁娈?*/
export function registerStage(id: PipelineStageId, fn: StageFn): void {
  stageRegistry.set(id, fn);
}

/** 娉ㄩ攢涓€涓绾块樁娈?*/
export function unregisterStage(id: PipelineStageId): void {
  stageRegistry.delete(id);
}

/** 鑾峰彇宸叉敞鍐岀殑闃舵鍒楄〃 */
export function getRegisteredStages(): PipelineStageId[] {
  return Array.from(stageRegistry.keys());
}

// 鈹€鈹€鈹€ 缂虹渷闃舵瀹炵幇 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 闃舵锛氫慨瀹瘎鍒も€斺€旀様娑熻鍙栨彁妗堝苟杈撳嚭璇勫垽 */
async function stageJudgment(ctx: PipelineContext): Promise<StageResult> {
  try {
    const judgments = judgeProposals(ctx.rootDir);

    if (judgments.length === 0) {
      return {
        stage: "judgment",
        success: true,
        message: "鏃犲緟璇勫垽鐨勪慨瀹彁妗堬紝璺宠繃璇勫垽闃舵",
        blocking: false,
      };
    }

    const blocked = judgments.filter((j) => j.judgment.verdict === "BLOCKED").length;
    const approved = judgments.filter((j) => j.judgment.verdict === "APPROVED" || j.judgment.verdict === "APPROVED_WITH_CAVEATS").length;
    const needsClarification = judgments.filter((j) => j.judgment.verdict === "NEEDS_CLARIFICATION").length;

    ctx.artifacts.set("judgment", judgments);

    const parts: string[] = [`${judgments.length} 鏉℃彁妗堣瘎鍒ゅ畬鎴恅];
    if (approved > 0) parts.push(`${approved} 鏉￠€氳繃`);
    if (blocked > 0) parts.push(`${blocked} 鏉¤闃诲`);
    if (needsClarification > 0) parts.push(`${needsClarification} 鏉￠渶婢勬竻`);

    return {
      stage: "judgment",
      success: true,
      message: parts.join("锛孿

judgment",
      success: false,
      message: `璇勫垽闃舵澶辫触: ${String(e).slice(0, 200)}`,
      blocking: true,
    };
  }
}

/** 闃舵锛氬紑鎷撹€呰鍐斥€斺€斿湪宸茶瘎鍒ょ殑鎻愭涓婄敱寮€鎷撹€呭仛鏈€缁堝喅瀹?*/
async function stageRulerDecision(ctx: PipelineContext): Promise<StageResult> {
  const judgments = ctx.artifacts.get("judgment") as BatchJudgment[] | undefined;

  if (!judgments || judgments.length === 0) {
    return {
      stage: "ruler_decision",
      success: true,
      message: "鏃犲緟瑁佸喅鎻愭",
      blocking: false,
    };
  }

  try {
    let decisions: BatchJudgment[];

    if (ctx.onRulerDecision) {
      // 鐢ㄦ埛鎻愪緵瑁佸喅鍥炶皟
      decisions = await ctx.onRulerDecision(judgments);
    } else {
      // 榛樿锛氬叏閮?APPROVED/APPROVED_WITH_CAVEATS 閫氳繃锛屽叾浣欐爣璁?rejected
      decisions = judgments.map((j) => {
        const verdict = j.judgment.verdict;
        if (verdict === "APPROVED" || verdict === "APPROVED_WITH_CAVEATS") {
          // 鏇存柊鎻愭鐘舵€佷负 approved
          const p = { ...j.proposal, status: "approved" as const };
          saveProposal(p, ctx.rootDir);
          return { ...j, proposal: p };
        }
        // 闃诲鎴栭渶婢勬竻鐨勬爣璁颁负 rejected
        const p = { ...j.proposal, status: "rejected" as const };
        saveProposal(p, ctx.rootDir);
        return { ...j, proposal: p };
      });
    }

    ctx.artifacts.set("ruler_decision", decisions);

    const approved = decisions.filter((d) => d.proposal.status === "approved").length;
    const rejected = decisions.filter((d) => d.proposal.status === "rejected").length;

    return {
      stage: "ruler_decision",
      success: true,
      message: `瑁佸喅瀹屾垚: ${approved} 鏉￠€氳繃, ${rejected} 鏉￠┏鍥瀈,
      data: decisions,
      blocking: false,
    };
  } catch (e) {
    return {
      stage: "ruler_decision",
      success: false,
      message: `瑁佸喅闃舵澶辫触: ${String(e).slice(0, 200)}`,
      blocking: true,
    };
  }
}

/** 闃舵锛氬娉曞啓鍏モ€斺€斿皢宸茶鍐抽€氳繃鐨勬彁妗堝啓鍏ュ娉?*/
async function stageApply(ctx: PipelineContext): Promise<StageResult> {
  const decisions = ctx.artifacts.get("ruler_decision") as BatchJudgment[] | undefined;

  if (!decisions || decisions.length === 0) {
    return {
      stage: "apply",
      success: true,
      message: "鏃犲緟鎵ц鐨勬彁妗圽

approved");
  if (approved.length === 0) {
    return {
      stage: "apply",
      success: true,
      message: "鏃犲凡閫氳繃鐨勬彁妗堥渶瑕佸啓鍏ュ娉昞

apply",
    success: allSuccess,
    message: results.join("\n"),
    data: results,
    blocking: !allSuccess,
  };
}

/** 闃舵锛欳I 闂ㄧ楠岃瘉鈥斺€斾慨瀹啓鍏ュ悗瑙﹀彂 build + typecheck + test + lint锛岀粨鏋滃洖鍐?artifacts */
async function stageCiVerify(ctx: PipelineContext): Promise<StageResult> {
  const _applyResult = ctx.stageResults.find((r) => r.stage === "apply");

  // 浠呭綋瀹硶琚疄闄呬慨鏀规椂鎵嶈Е鍙?CI
  const decisions = ctx.artifacts.get("ruler_decision") as BatchJudgment[] | undefined;
  const hasApplied = decisions?.some((d) => d.proposal.status === "approved") ?? false;

  if (!hasApplied) {
    return {
      stage: "ci_verify",
      success: true,
      message: "鏃犱慨瀹啓鍏ワ紝璺宠繃 CI 楠岃瘉",
      blocking: false,
    };
  }

  try {
    // 璋冪敤 CI 闂ㄧ鑴氭湰锛坣px tsx scripts/ci-gate.ts锛塡r
    const { execSync } = await import("node:child_process");
    const ciScript = path.resolve(ctx.rootDir, "scripts", "ci-gate.ts");

    if (!fs.existsSync(ciScript)) {
      return {
        stage: "ci_verify",
        success: false,
        message: `CI 闂ㄧ鑴氭湰涓嶅瓨鍦? ${ciScript}`,
        blocking: false, // CI 澶辫触涓嶉樆濉炰慨瀹紝浣嗛渶鍛婅
      };
    }

    // --json 妯″紡杈撳嚭缁撴瀯鍖栫粨鏋滐紝浠庢贩鍚堣緭鍑轰腑鎻愬彇 JSON
    const output = execSync(`npx tsx "${ciScript}" --json`, {
      cwd: ctx.rootDir,
      encoding: "utf-8",
      timeout: 600_000, // 10 鍒嗛挓瓒呮椂锛堝寘鍚瀯寤?娴嬭瘯锛塡r
      stdio: ["ignore", "pipe", "pipe"],
    });

    // 浠庢贩鍚堣緭鍑轰腑鎻愬彇 JSON 琛岋紙ci-gate --json 鏈€鍚庝竴琛岄潪绌鸿緭鍑轰负 JSON锛塡r
    const lines = output.trim().split("\n");
    let jsonLine: string | undefined;
    for (let i = lines.length - 1; i >= 0; i--) {
      if (lines[i].startsWith("{")) { jsonLine = lines[i]; break; }
    }

    if (!jsonLine) {
      ctx.artifacts.set("ci_verify", output.slice(-2000));
      return {
        stage: "ci_verify",
        success: false,
        message: "CI 闂ㄧ杈撳嚭瑙ｆ瀽澶辫触锛氭湭鎵惧埌 JSON 缁撴灉",
        blocking: false,
      };
    }

    const ciResult = JSON.parse(jsonLine) as {
      configValid: boolean; build: boolean; typecheck: boolean; lint: boolean; test: boolean;
      testDetails: { total: number; passed: number; skipped: number }; allPassed: boolean;
    };

    // 鍥炲啓 CI 缁撴灉鍒?artifacts锛屼緵涓嬫父闃舵锛堣鐭ラ棴鐜€佹憳瑕佺敓鎴愶級娑堣垂
    ctx.artifacts.set("ci_verify", { structured: ciResult, raw: output.slice(-2000) });

    const passed = ciResult.allPassed;

    if (!passed) {
      const failures: string[] = [];
      if (!ciResult.configValid) failures.push("閰嶇疆鏍￠獙");
      if (!ciResult.build) failures.push("鏋勫缓");
      if (!ciResult.typecheck) failures.push("绫诲瀷妫€鏌

Lint");
      if (!ciResult.test) failures.push(`娴嬭瘯(${ciResult.testDetails.passed}/${ciResult.testDetails.total})`);
      return {
        stage: "ci_verify",
        success: false,
        message: `CI 闂ㄧ澶辫触: ${failures.join("銆乗

ci_verify",
      success: true,
      message: `CI 闂ㄧ閫氳繃 鉁?(build 鉁?typecheck 鉁?test ${ciResult.testDetails.passed}/${ciResult.testDetails.total} 鉁?lint 鉁?`,
      data: ciResult,
      blocking: false,
    };
  } catch (e: unknown) {
    const execErr = e as { stderr?: string; stdout?: string; message?: string };
    const stderr = execErr.stderr ?? "";
    const stdout = execErr.stdout ?? "";
    ctx.artifacts.set("ci_verify", (stdout + "\n" + stderr).slice(-2000));

    return {
      stage: "ci_verify",
      success: false,
      message: `CI 闂ㄧ鎵ц寮傚父: ${stderr.slice(-300) || String(e).slice(0, 300)}`,
      blocking: false,
    };
  }
}

/** 闃舵锛氬綊妗ｂ€斺€旂敓鎴愭不鐞嗘憳瑕?*/
async function stageArchive(ctx: PipelineContext): Promise<StageResult> {
  try {
    const summary = summarizeGovernance(ctx.rootDir);
    ctx.artifacts.set("archive", summary);

    return {
      stage: "archive",
      success: true,
      message: `娌荤悊褰掓。瀹屾垚: ${summary.applied} 鏉″凡搴旂敤, ${summary.approved} 鏉″凡閫氳繃寰呮墽琛? ${summary.blocked} 鏉¤闃诲`,
      data: summary,
      blocking: false,
    };
  } catch (e) {
    return {
      stage: "archive",
      success: false,
      message: `褰掓。澶辫触: ${String(e).slice(0, 200)}`,
      blocking: false, // 褰掓。澶辫触涓嶉樆濉瀄r
    };
  }
}

// 鈹€鈹€鈹€ 榛樿闃舵椤哄簭 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

const DEFAULT_STAGES: PipelineStageId[] = [
  "judgment",       // 鏄旀稛璇勫垽鎵€鏈夊緟鍐虫彁妗圽r
  "ruler_decision", // 寮€鎷撹€呰鍐砛r
  "apply",          // 鍐欏叆瀹硶
  "ci_verify",      // CI 闂ㄧ楠岃瘉
  "archive",        // 鐢熸垚鎽樿
];

// 鈹€鈹€鈹€ 娉ㄥ唽缂虹渷闃舵 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

registerStage("judgment", stageJudgment);
registerStage("ruler_decision", stageRulerDecision);
registerStage("apply", stageApply);
registerStage("ci_verify", stageCiVerify);
registerStage("archive", stageArchive);

// 鈹€鈹€鈹€ 绠＄嚎缂栨帓 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 鎸夊簭鎵ц绠＄嚎鍚勯樁娈点€俓r
 *
 * - 闃舵鎵ц椤哄簭鐢?config.stages 鎴?DEFAULT_STAGES 瀹氫箟
 * - config.stageOverrides 鍙鍐欎换闃舵瀹炵幇
 * - 浠讳竴闃舵杩斿洖 blocking=true 鍒欓樆鏂笅娓竆r
 *
 * @param config 绠＄嚎閰嶇疆
 * @returns 绠＄嚎瀹屾暣杩愯缁撴灉
 */
export async function runPipeline(config: PipelineConfig): Promise<PipelineResult> {
  const { rootDir, stages = DEFAULT_STAGES, onRulerDecision } = config;

  const ctx: PipelineContext = {
    rootDir: path.resolve(rootDir),
    artifacts: new Map(),
    stageResults: [],
    onRulerDecision,
  };

  let blockedAt: PipelineStageId | null = null;

  for (const stageId of stages) {
    const stageFn = config.stageOverrides?.[stageId] ?? stageRegistry.get(stageId);

    if (!stageFn) {
      ctx.stageResults.push({
        stage: stageId,
        success: false,
        message: `闃舵 "${stageId}" 鏈敞鍐岋紝璺宠繃`,
        blocking: false,
      });
      continue;
    }

    const result = await stageFn(ctx);
    ctx.stageResults.push(result);

    if (!result.success && result.blocking) {
      blockedAt = stageId;
      break;
    }
  }

  // 鏈熬鐢熸垚娌荤悊鎽樿
  const governance = summarizeGovernance(rootDir);

  return {
    success: blockedAt === null,
    blockedAt,
    stageResults: ctx.stageResults,
    governance,
  };
}

/**
 * 蹇嵎鐗堟湰锛氫粎璇勫垽锛堜笉鍚啓鍏ワ級锛岀敤浜庨瑙堜慨瀹奖鍝嶃€俓r
 */
export async function previewPipeline(rootDir: string): Promise<{
  judgments: BatchJudgment[];
  summary: GovernanceSummary;
}> {
  const judgments = judgeProposals(rootDir);
  const summary = summarizeGovernance(rootDir);
  return { judgments, summary };
}

