/**
 * rate-limiter.ts 鈥?API Key 鍑嗗叆鎺у埗灞俓r
 *
 * 鍙屽眰闄愭祦锛歕r
 *   1. 婊戝姩绐楀彛 鈥?姣忓垎閽熸渶澶ц姹傛暟锛堜护鐗屾《鍙樹綋锛屾嫆缁濆嵆鎶涢敊锛塡r
 *   2. 姣忔棩閰嶉 鈥?姣忔棩鏈€澶?token 娑堣€楋紙鎸佷箙鍖栧埌 .cortex/logs/quotas.json锛塡r
 *
 * 閰嶇疆锛堢幆澧冨彉閲忥紝鍙€夛紝涓嶈鍒欎笉闄愶級锛歕r
 *   CORTEX_LIMIT_CYRENE_RPM=30       鏄旀稛姣忓垎閽熶笂闄怽r
 *   CORTEX_LIMIT_CHAT_RPM=60          Chat姹犳瘡鍒嗛挓涓婇檺
 *   CORTEX_LIMIT_REASONER_RPM=10      Reasoner姣忓垎閽熶笂闄怽r
 *   CORTEX_QUOTA_CYRENE_DAY_TOKENS=1000000   鏄旀稛鏃ラ厤棰?1M)
 *   CORTEX_QUOTA_CHAT_DAY_TOKENS=5000000      Chat姹犳棩閰嶉(5M)
 *   CORTEX_QUOTA_REASONER_DAY_TOKENS=500000   Reasoner鏃ラ厤棰?500K)
 */

import * as fs from "node:fs";
import * as path from "node:path";

// 鈹€鈹€ 绫诲瀷 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

interface DailyQuota {
  date: string;
  tokens: number;
}

interface QuotaStore {
  [keyFingerprint: string]: DailyQuota;
}

export interface RateLimitResult {
  allowed: boolean;
  reason?: string;
}

// 鈹€鈹€ 閰嶇疆 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** key 鏍囪瘑 鈫?姣忓垎閽熻姹備笂闄?*/
function loadRpmLimit(keyLabel: string): number | undefined {
  const map: Record<string, string> = {
    cyrene: "CORTEX_LIMIT_CYRENE_RPM",
    chat: "CORTEX_LIMIT_CHAT_RPM",
    reasoner: "CORTEX_LIMIT_REASONER_RPM",
  };
  const k = keyLabel.toLowerCase();
  const env = map[k];
  if (!env) return undefined;
  const v = process.env[env];
  return v ? parseInt(v) : undefined;
}

/** key 鏍囪瘑 鈫?姣忔棩 token 閰嶉 */
function loadDayQuota(keyLabel: string): number | undefined {
  const map: Record<string, string> = {
    cyrene: "CORTEX_QUOTA_CYRENE_DAY_TOKENS",
    chat: "CORTEX_QUOTA_CHAT_DAY_TOKENS",
    reasoner: "CORTEX_QUOTA_REASONER_DAY_TOKENS",
  };
  const k = keyLabel.toLowerCase();
  const env = map[k];
  if (!env) return undefined;
  const v = process.env[env];
  return v ? parseInt(v) : undefined;
}

// 鈹€鈹€ RateLimiter 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class RateLimiter {
  // 婊戝姩绐楀彛锛氬瓨鍌ㄦ瘡娆¤姹傜殑鏃堕棿鎴砛r
  private _windows = new Map<string, number[]>();
  // 姣忎釜 key 鐨勫噯鍏ラ攣涓茶鍖栵紝闃叉骞跺彂缁曡繃 RPM 闄愬埗
  private _locks = new Map<string, Promise<void>>();
  // 姣忔棩閰嶉缂撳瓨
  private _dayQuotas = new Map<string, DailyQuota>();
  private _quotaPath: string;

  constructor() {
    const logDir = path.resolve(process.cwd(), ".cortex", "logs");
    if (!fs.existsSync(logDir)) fs.mkdirSync(logDir, { recursive: true });
    this._quotaPath = path.join(logDir, "quotas.json");
    this._loadQuotas();
  }

  /** 鍑嗗叆妫€鏌ャ€傝繑鍥?{ allowed, reason }锛堝悓涓€ key 涓茶鍖栭槻绔炴€侊級*/
  async check(keyLabel: string, keyFingerprint: string, estimatedTokens: number = 0): Promise<RateLimitResult> {
    // 涓茶鍖栧悓涓€ key 鐨勫噯鍏ユ鏌ワ紝闃叉骞跺彂缁曡繃 RPM
    const prev = this._locks.get(keyFingerprint) ?? Promise.resolve();
    let resolve!: () => void;
    const next = new Promise<void>((r) => { resolve = r; });
    this._locks.set(keyFingerprint, next);
    try {
      await prev;
      return this._checkInner(keyLabel, keyFingerprint, estimatedTokens);
    } finally {
      resolve();
      if (this._locks.get(keyFingerprint) === next) {
        this._locks.delete(keyFingerprint);
      }
    }
  }

  /** 鍐呴儴鍑嗗叆閫昏緫锛堟棤閿侊級 */
  private _checkInner(keyLabel: string, keyFingerprint: string, estimatedTokens: number): RateLimitResult {
    // 1. 姣忓垎閽熼檺娴乗r
    const rpmLimit = loadRpmLimit(keyLabel);
    if (rpmLimit) {
      const now = Date.now();
      const window = this._windows.get(keyFingerprint) ?? [];
      // 娓呯悊 60 绉掑鐨勮褰昞r
      const cutoff = now - 60_000;
      const active = window.filter((t) => t > cutoff);
      if (active.length >= rpmLimit) {
        return {
          allowed: false,
          reason: `${keyLabel} 瓒呰繃姣忓垎閽?${rpmLimit} 娆￠檺鍒讹紙褰撳墠绐楀彛 ${active.length} 娆★級`,
        };
      }
      active.push(now);
      this._windows.set(keyFingerprint, active);
    }

    // 2. 姣忔棩 token 閰嶉
    const dayQuota = loadDayQuota(keyLabel);
    if (dayQuota) {
      const today = new Date().toISOString().slice(0, 10);
      let quota = this._dayQuotas.get(keyFingerprint);
      if (quota?.date !== today) {
        quota = { date: today, tokens: 0 };
        this._dayQuotas.set(keyFingerprint, quota);
      }
      if (quota.tokens + estimatedTokens > dayQuota) {
        return {
          allowed: false,
          reason: `${keyLabel} 瓒呰繃姣忔棩 ${(dayQuota / 1_000_000).toFixed(1)}M token 閰嶉锛堝凡鐢?${(quota.tokens / 1_000_000).toFixed(2)}M锛塦,
        };
      }
    }

    return { allowed: true };
  }

  /** 璁板綍瀹為檯娑堣€楃殑 token */
  recordTokens(keyFingerprint: string, tokens: number): void {
    if (tokens <= 0) return;
    const today = new Date().toISOString().slice(0, 10);
    let quota = this._dayQuotas.get(keyFingerprint);
    if (!quota || quota.date !== today) {
      quota = { date: today, tokens: 0 };
    }
    quota.tokens += tokens;
    this._dayQuotas.set(keyFingerprint, quota);
    this._saveQuotas();
  }

  /** 鑾峰彇浠婃棩鐢ㄩ噺 */
  getTodayUsage(keyFingerprint: string): number {
    const quota = this._dayQuotas.get(keyFingerprint);
    const today = new Date().toISOString().slice(0, 10);
    if (quota?.date === today) return quota.tokens;
    return 0;
  }

  private _loadQuotas(): void {
    try {
      if (fs.existsSync(this._quotaPath)) {
        const raw = JSON.parse(fs.readFileSync(this._quotaPath, "utf-8")) as QuotaStore;
        for (const [k, v] of Object.entries(raw)) {
          this._dayQuotas.set(k, v);
        }
      }
    } catch {
      // 鏂囦欢鎹熷潖锛屽拷鐣r
    }
  }

  private _saveQuotas(): void {
    try {
      const obj: QuotaStore = {};
      for (const [k, v] of this._dayQuotas) {
        obj[k] = v;
      }
      fs.writeFileSync(this._quotaPath, JSON.stringify(obj, null, 2), "utf-8");
    } catch {
      // 鍐欏叆澶辫触涓嶉樆濉炰富娴佺▼
    }
  }
}

