// 鈹€鈹€ 绫诲瀷 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** BM25 绱㈠紩缁熻蹇収 */
export interface BM25Stats {
  docCount: number;
  avgDocLength: number;
  totalTerms: number;
}

/** 鍗曞瓧娈?BM25 鎼滅储缁撴灉 */
export interface BM25Result {
