  const node = activatedNodes.find((n) => n.entry.id === entryId);
  return node ? node.activation : 0;
}

// 鈹€鈹€ 鎯呯华鍔犳潈 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 鎯呯华鍞よ捣濂栧姳銆俓r
 *
 * emotionalSalience 鈭?[-1, 1]:
 *   -1 = 寮虹儓璐熼潰 (楂樺敜璧?
 *    0 = 涓€r
 *   +1 = 寮虹儓姝ｉ潰 (楂樺敜璧?
 *
 * 楂樺敜璧疯蹇嗭紙姝ｉ潰鎴栬礋闈級鍦ㄨ瘎鍒嗘椂鑾峰緱杞诲井鍔犲垎銆俓r
