// ============================================================
// context-builder.ts 鈥斺€?涓婁笅鏂囨瀯寤哄櫒
//
// ContextBuilder 鎸?ContextPolicy 椹卞姩妫€绱⑩啋鎺掑簭鈫掑幓閲嶁啋鍒嗗眰缁勮鈫抰oken 閫傞厤
// 灏?MemoryStore 鐨勫婧愭绱㈢粨鏋滆浆鍖栦负绮剧畝涓婁笅鏂囨敞鍏?Agent銆俓r
//
// 鍏眰绠＄嚎锛歕r
//   鈶?浜嬪疄妫€绱?鈥?鎸?RetrievalPolicy (HCA/CSA + BFS + 鍏冩暟鎹繃婊?
//   鈶?璇勫垎鎺掑簭 鈥?鎸?SortPolicy (confidence/recency/relevance/weighted)
//   鈶?鍣０杩囨护 鈥?浣庝簬闃堝€肩殑鍒囨帀
//   鈶?鍘婚噸鍚堝苟 鈥?澶氭簮鍚屼竴浜嬪疄鍚堜负涓€鏉r
//   鈶?鍒嗗眰缁勮 鈥?critical 鈫?support 鈫?reference 涓夊眰
//   鈶?token 閫傞厤 鈥?棰勭畻鍐呮櫤鑳芥埅鏂璡r
//
// @since Cortex Core-2 鈥?涓婁笅鏂囩敓鍛藉懆鏈熺鐞嗗崗璁甛r
// ============================================================

import type { ContextPolicy, MemoryEntry, MemoryLink, MemoryQuery, ReadMode, TaskNode } from "@cortex/shared";
import type { MemoryStore } from "./memory-store.js";
import { CognitiveEngine, type CognitiveConfig } from "./cognitive-engine.js";

// 鈹€鈹€鈹€ 涓婁笅鏂囨瀯寤虹粨鏋?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export interface ContextBuildResult {
  /** 缁勮鍚庣殑涓婁笅鏂囨枃鏈?*/
  readonly context: string;
  /** 鎬诲叡妫€绱㈠埌鐨勮蹇嗘潯鏁?*/
  readonly totalRetrieved: number;
  /** 鍘婚噸鍚庝繚鐣欐潯鏁?*/
  readonly afterDedup: number;
  /** 鏈€缁堟敞鍏ヤ笂涓嬫枃鐨勬潯鏁?*/
  readonly injected: number;
  /** 涓婁笅鏂囧瓧绗︿覆闀垮害 */
  readonly charCount: number;
  /** 涓夊眰鍚勮嚜鐨勬潯鏁?*/
  readonly tierCounts: Record<string, number>;
}

// 鈹€鈹€鈹€ 鍔犳潈鎺掑簭琛板噺 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

function recencyDecay(lastAccessedAt: number, now: number, halfLifeMs: number): number {
  if (halfLifeMs <= 0) return 1;
  const age = now - lastAccessedAt;
  return Math.pow(2, -age / halfLifeMs);
}

// 鈹€鈹€鈹€ 鍘婚噸鍚堝苟锛堟憳瑕佹枃鏈幓閲嶏級 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

function deduplicateEntries(entries: MemoryEntry[]): MemoryEntry[] {
  const seen = new Set<string>();
  const result: MemoryEntry[] = [];
  // 鎸?weight 闄嶅簭鈥斺€斿厛澶勭悊楂樺垎鏉＄洰锛屽悓鎽樿鐨勪綆鍒嗚鍘婚噸
  const sorted = [...entries].sort((a, b) => b.weight - a.weight);
  for (const entry of sorted) {
    const key = entry.summary.slice(0, 100); // 鍓?100 瀛楃鍋氬幓閲?key
    if (!seen.has(key)) {
      seen.add(key);
      result.push(entry);
    }
  }
  return result;
}

// 鈹€鈹€鈹€ ContextBuilder 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class ContextBuilder {
  private readonly _cognitiveEngine: CognitiveEngine;

  constructor(
    private readonly memory: MemoryStore,
    cognitiveConfig?: Partial<CognitiveConfig>,
  ) {
    this._cognitiveEngine = new CognitiveEngine(cognitiveConfig);
  }

  /**
   * 鎸?ContextPolicy 鏋勫缓涓婁笅鏂囥€俓r
   *
   * @param policy  涓婁笅鏂囩鐞嗙瓥鐣ワ紙浠?PRESET_CONTEXT_POLICIES 鎴栬嚜瀹氫箟锛塡r
   * @param node    褰撳墠浠诲姟鑺傜偣鈥斺€攑ayload 鐢ㄤ簬鍏抽敭璇嶆彁鍙朶r
   * @returns       缁勮鍚庣殑涓婁笅鏂囨枃鏈?+ 鏋勫缓缁熻
   */
  async build(policy: ContextPolicy, node: TaskNode): Promise<ContextBuildResult> {
    const now = Date.now();
    const { retrieval, pipeline } = policy;

    // 鈹€鈹€ 鈶?浜嬪疄妫€绱?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
    const rawEntries = await this._retrieve(retrieval, node);

    // 鈹€鈹€ 鈶?璇勫垎鎺掑簭 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
    let sorted: MemoryEntry[];
    if (pipeline.sort.mode === "cognitive") {
      sorted = await this._cognitiveSort(rawEntries, pipeline, node, now);
    } else {
      sorted = this._sort(rawEntries, pipeline.sort, now);
    }

    // 鈹€鈹€ 鈶?鍘婚噸鍚堝苟 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
    const deduped = pipeline.deduplicate ? deduplicateEntries(sorted) : sorted;

    // 鈹€鈹€ 鈶?鍒嗗眰缁勮 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
    const { assembled, tierCounts } = this._assemble(deduped, pipeline.assemble, pipeline.tokenBudget.total);

    return {
      context: assembled,
      totalRetrieved: rawEntries.length,
      afterDedup: deduped.length,
      injected: Object.values(tierCounts).reduce((a, b) => a + b, 0),
      charCount: assembled.length,
      tierCounts,
    };
  }

  // 鈹€鈹€ 鍐呴儴锛氭绱?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private async _retrieve(retrieval: ContextPolicy["retrieval"], node: TaskNode): Promise<MemoryEntry[]> {
    const keywords = this._extractKeywords(node.payload);

    const query: MemoryQuery = {
      keywords,
      bfsDepth: retrieval.bfsDepth ?? 2,
      bfsMaxNodes: retrieval.bfsMaxNodes ?? 50,
      linkTypes: retrieval.linkTypes,
      metadataFilter: retrieval.metadataFilter,
      limit: 30,
    };

    const readMode: ReadMode = retrieval.readMode;
    return await this.memory.read(query, readMode);
  }

  // 鈹€鈹€ 鍐呴儴锛氭帓搴?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private _sort(
    entries: MemoryEntry[],
    sort: ContextPolicy["pipeline"]["sort"],
    now: number,
  ): MemoryEntry[] {
    const { mode, confidenceWeight = 0.5, halfLifeMs = 3_600_000 } = sort;
    const sorted = [...entries];

    switch (mode) {
      case "confidence":
        sorted.sort((a, b) => b.weight - a.weight);
        break;

      case "recency":
        sorted.sort((a, b) => b.lastAccessedAt - a.lastAccessedAt);
        break;

      case "relevance":
      case "cognitive":
        // cognitive 璧扮嫭绔嬭矾寰勶紝姝ゅ fallthrough 鎸?weight
        sorted.sort((a, b) => b.weight - a.weight);
        break;

      case "weighted": {
        const cw = confidenceWeight;
        const rw = 1 - cw;
        sorted.sort((a, b) => {
          const scoreA = cw * (a.weight / 10) + rw * recencyDecay(a.lastAccessedAt, now, halfLifeMs);
          const scoreB = cw * (b.weight / 10) + rw * recencyDecay(b.lastAccessedAt, now, halfLifeMs);
          return scoreB - scoreA;
        });
        break;
      }
    }

    return sorted;
  }

  // 鈹€鈹€ 璁ょ煡鎺掑簭 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 浣跨敤 CognitiveEngine 瀵规绱㈢粨鏋滆繘琛屽叏缁村害璁ょ煡璇勫垎銆俓r
   *
   * 浠?memory-store 鐨?weight 瀛楁鎭㈠ hybridScore (weight / 10)锛孿r
   * 鐒跺悗璋冪敤 CognitiveEngine.scoreAndRank 鎵ц璐濆彾鏂?鍌呴噷鍙?鑱旀兂婵€娲昏瘎鍒嗐€俓r
   */
  private async _cognitiveSort(
    entries: MemoryEntry[],
    pipeline: ContextPolicy["pipeline"],
    node: TaskNode,
    now: number,
  ): Promise<MemoryEntry[]> {
    const keywords = this._extractKeywords(node.payload);
    const queryText = keywords.join(" ");

    // 浠?weight 鎭㈠ hybridScore (memory-store 璁句负 hybridScore * 10)
    const hybridScores = new Map<string, number>();
    for (const e of entries) {
      hybridScores.set(e.id, e.weight / 10);
    }

    // 鏇存柊璁ょ煡閰嶇疆锛堜粠 policy 璇诲彇瑕嗙洊鍊硷級
    if (pipeline.bayesianPrior !== undefined || pipeline.linkActivationDepth !== undefined) {
      if (pipeline.bayesianPrior !== undefined) {
        this._cognitiveEngine.config.bayesianPriorStrength = pipeline.bayesianPrior;
      }
      if (pipeline.linkActivationDepth !== undefined) {
        this._cognitiveEngine.config.spreadingDepth = pipeline.linkActivationDepth;
      }
    }

    // 鑱旀兂婵€娲婚渶瑕佺殑杈呭姪鍑芥暟
    const getLinks = (id: string): MemoryLink[] => this.memory.getLinks(id);
    const getEntry = (id: string): MemoryEntry | undefined => this.memory.peek(id) as MemoryEntry | undefined;

    const scored = this._cognitiveEngine.scoreAndRank(
      entries,
      hybridScores,
      queryText,
      now,
      getLinks,
      getEntry,
    );

    // 杈圭晫鍥炲綊杩囨护
    const filtered = this._cognitiveEngine.boundaryFilter(scored);

    // 灏?finalScore 鍐欏叆 weight锛堝悗缁?_assemble 鎸?weight 鍒嗗眰锛塡r
    return filtered.map((s) => ({ ...s.entry, weight: s.finalScore * 10 }));
  }

  // 鈹€鈹€ 鍐呴儴锛氬垎灞傜粍瑁?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 涓夊眰缁勮锛歕r
   *   critical  鈥?鍓?N 鏉￠珮浼樺厛绾э紝涓嶅弬涓庢埅鏂璡r
   *   support   鈥?涓锛宼oken 涓嶈冻鏃舵寜鏉冮噸鎴柇
   *   reference 鈥?鏈锛宼oken 涓嶈冻鏃堕鍏堣瑁乗r
   */
  private _assemble(
    entries: MemoryEntry[],
    assemble: ContextPolicy["pipeline"]["assemble"],
    totalBudget: number,
  ): { assembled: string; tierCounts: Record<string, number> } {
    const { tierBudget, maxTokensPerEntry = 300 } = assemble;
    const charBudget = totalBudget; // 鐢ㄥ瓧绗︿及绠?token锛堚増1 token 鈮?4 chars锛屼繚瀹堝彇 1:1 閬垮厤瓒呴檺锛塡r

    const criticalCap = Math.floor(charBudget * tierBudget.critical);
    const supportCap = Math.floor(charBudget * tierBudget.support);
    const referenceCap = Math.floor(charBudget * tierBudget.reference);

    // critical: 鍓?N 鏉★紙weight 鏈€楂樼殑锛塡r
    const criticalSlice: MemoryEntry[] = [];
    let criticalChars = 0;
    for (const e of entries) {
      const snippet = this._formatEntry(e, maxTokensPerEntry);
      if (criticalChars + snippet.length > criticalCap) break;
      criticalSlice.push(e);
      criticalChars += snippet.length;
    }

    // support: 浣欎笅鏉＄洰锛堢敤 Set 鏇夸唬 O(n虏) Array.includes锛塡r
    const criticalSet = new Set(criticalSlice);
    const remaining = entries.filter((e) => !criticalSet.has(e));
    const supportSlice: MemoryEntry[] = [];
    let supportChars = 0;
    for (const e of remaining) {
      const snippet = this._formatEntry(e, maxTokensPerEntry);
      if (supportChars + snippet.length > supportCap) break;
      supportSlice.push(e);
      supportChars += snippet.length;
    }

    // reference: 鍐嶄綑涓嬬殑锛堢敤 Set 鏇夸唬 O(n虏) Array.includes锛塡r
    const supportSet = new Set(supportSlice);
    const afterSupport = remaining.filter((e) => !supportSet.has(e));
    const referenceSlice: MemoryEntry[] = [];
    let referenceChars = 0;
    for (const e of afterSupport) {
      const snippet = this._formatEntry(e, maxTokensPerEntry);
      if (referenceChars + snippet.length > referenceCap) break;
      referenceSlice.push(e);
      referenceChars += snippet.length;
    }

    // 缁勮
    const parts: string[] = [];
    if (criticalSlice.length > 0) {
      parts.push("## 鍏抽敭涓婁笅鏂嘰
" + criticalSlice.map((e) => this._formatEntry(e, maxTokensPerEntry)).join("\n"));
    }
    if (supportSlice.length > 0) {
      parts.push("## 鏀拺鏉愭枡\n" + supportSlice.map((e) => this._formatEntry(e, maxTokensPerEntry)).join("\n"));
    }
    if (referenceSlice.length > 0) {
      parts.push("## 鍙傝€冮檮褰昞
" + referenceSlice.map((e) => this._formatEntry(e, maxTokensPerEntry)).join("\n"));
    }

    return {
      assembled: parts.join("\n\n"),
      tierCounts: {
        critical: criticalSlice.length,
        support: supportSlice.length,
        reference: referenceSlice.length,
      },
    };
  }

  // 鈹€鈹€ 鍐呴儴锛氭牸寮忓寲鍗曟潯璁板繂 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private _formatEntry(entry: MemoryEntry, maxChars: number): string {
    const summary = entry.summary.length > maxChars
      ? entry.summary.slice(0, maxChars) + "鈥

usedDeprecatedRules:
");
    for (let i = 0; i <= cjkChars.length - 2; i++) {
      keywords.push(cjkChars.slice(i, i + 2));
    }

    // 鎷変竵璇峔r
    const latinWords = payload.split(/\s+/).filter((w) => w.length > 3);
    keywords.push(...latinWords);

    return keywords;
  }
}

