// ============================================================
// @cortex/engine/memory/dedup-service 鈥斺€?鍐呭鍘婚噸鏈嶅姟
//
// @since v3.1.0
// @layer 寮曟搸灞?鈥?绾绠?+ observer emit锛屼笉鎿嶄綔瀛樺偍
//
// 鑱岃矗锛歕r
//   1. contentHash()   鈥?SHA256 鍐呭鍝堝笇
//   2. vectorDedup()   鈥?鍚戦噺浣欏鸡鐩镐技搴﹀幓閲峔r
//   3. exactMatch()    鈥?content_hash 绮剧‘鍖归厤鍘婚噸
//
// 浠?memory-store.ts 鎷嗗垎锛岄伒寰崟涓€鑱岃矗鍘熷垯銆俓r
//
// @fix FIND-030 鈥?contentHash 缁撴灉鍦?write() 涓€氳繃 content_hash 瀛楁鎸佷箙鍖朶r
// @fix FIND-029 鈥?embedding 缁熶竴瀛樺偍涓?number[]锛堜笌 _parseEmbeddingBlob 瀵归綈锛塡r
// ============================================================

import * as crypto from "node:crypto";
import type { MemoryEntry } from "@cortex/shared";
import {
  CONTENT_HASH_ALGO,
  VECTOR_DEDUP_THRESHOLD,
} from "./schema.js";

/** 鍚戦噺鍘婚噸鍖归厤缁撴灉 */
export interface VectorDedupMatch {
  /** 鍖归厤鍒扮殑宸叉湁鏉＄洰 ID */
  existingId: string;
  /** 浣欏鸡鐩镐技搴?*/
  similarity: number;
}

/**
 * DedupService 鈥斺€?鍐呭鍘婚噸绾绠楁湇鍔°€俓r
 *
 * 涓嶆寔鏈夌姸鎬侊紝涓嶆搷浣滃瓨鍌ㄥ眰锛屼粎瀵逛紶鍏ョ殑鏉＄洰鎵ц鍘婚噸璁＄畻銆俓r
 */
export class DedupService {
  private readonly hashAlgo: string;
  private readonly vectorThreshold: number;

  constructor(
    hashAlgo: string = CONTENT_HASH_ALGO,
    vectorThreshold: number = VECTOR_DEDUP_THRESHOLD,
  ) {
    this.hashAlgo = hashAlgo;
    this.vectorThreshold = vectorThreshold;
  }

  /**
   * 璁＄畻鍐呭 SHA256 鍝堝笇銆俓r
   * 鍝堝笇杈撳叆 = summary + JSON(content_blob)锛岀‘淇濆唴瀹瑰敮涓€鎬с€俓r
   *
   * @param summary 璁板繂鎽樿
   * @param contentBlob 鍐呭浣揬r
   * @returns 鍗佸叚杩涘埗鍝堝笇瀛楃涓瞈r
   */
  contentHash(summary: string, contentBlob: unknown): string {
    return crypto
      .createHash(this.hashAlgo)
      .update(summary + JSON.stringify(contentBlob))
      .digest("hex");
  }

  /**
   * 鍦ㄥ凡鏈夋潯鐩腑鎸?contentHash 绮剧‘鍖归厤鍘婚噸銆俓r
   *
   * @param contentHash 寰呮煡鎵剧殑鍐呭鍝堝笇
   * @param entries 宸叉湁鏉＄洰姹燶r
   * @returns 鍖归厤鍒扮殑鏉＄洰 ID锛宯ull 琛ㄧず鏃犻噸澶峔r
   */
  exactMatch(contentHash: string, entries: MemoryEntry[]): string | null {
    const dup = entries.find((e) => e.content_hash === contentHash);
    return dup?.id ?? null;
  }

  /**
   * 鍚戦噺浣欏鸡鐩镐技搴﹀幓閲嶃€俓r
   * 璁＄畻鏂板悜閲忎笌鎵€鏈夊凡鏈夊悜閲忕殑浣欏鸡鐩镐技搴︼紝>= threshold 瑙嗕负閲嶅銆俓r
   *
   * @param newEmbedding 鏂版潯鐩殑 embedding 鍚戦噺
   * @param entries 宸叉湁鏉＄洰姹燶r
   * @returns 瓒呰繃闃堝€肩殑鍖归厤鍒楄〃锛堟寜鐩镐技搴﹂檷搴忥級
   */
  vectorDedup(
    newEmbedding: number[],
    entries: MemoryEntry[],
  ): VectorDedupMatch[] {
    const matches: VectorDedupMatch[] = [];
    const magA = Math.sqrt(newEmbedding.reduce((s, v) => s + v * v, 0));
    if (magA === 0) return matches;

    for (const e of entries) {
      if (!e.embedding || e.embedding.length !== newEmbedding.length) continue;
      const emb = e.embedding;
      const dot = newEmbedding.reduce(
        (sum, v, i) => sum + v * (emb[i] ?? 0),
        0,
      );
      const magB = Math.sqrt(
        e.embedding.reduce((s, v) => s + v * v, 0),
      );
      if (magB === 0) continue;
      const cos = dot / (magA * magB);
      if (cos >= this.vectorThreshold) {
        matches.push({ existingId: e.id, similarity: cos });
      }
    }

    // 鎸夌浉浼煎害闄嶅簭鎺掑垪
    matches.sort((a, b) => b.similarity - a.similarity);
    return matches;
  }
}

