import type { IEmbeddingService } from "./embedding.js";
import type { MemoryEntry } from "@cortex/shared";

// 鈹€鈹€ 绫诲瀷 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 娣峰悎妫€绱㈣瘎鍒嗙粨鏋?*/
export interface HybridScoreResult {
  entry: MemoryEntry;
  bm25Score: number;
  vectorScore: number;
  hybridScore: number;
}

/** 娣峰悎妫€绱㈠紩鎿庨厤缃?*/
export interface HybridRetrievalConfig {
  /** BM25 鏉冮噸 (0..1) */
  alpha: number;
  /** 鍚戦噺鐩镐技搴︽潈閲?(0..1) */
  beta: number;
  /** 绮楁帓姹犲ぇ灏忓€嶆暟 (2M = 2 脳 topN) */
  coarseMultiplier: number;
  /** 璐績绮炬帓鐩爣鏁?*/
  fineTopN: number;
  /** 杈圭晫鍥炲綊: 鍚敤鑷€傚簲闃堝€?*/
  enableBoundaryRegression: boolean;
  /** 杈圭晫鍥炲綊: 鍒濆闃堝€?(0..1) */
  initialThreshold: number;
  /** 杈圭晫鍥炲綊: EMA 骞虫粦鍥犲瓙 */
  boundaryEma: number;
}

/** 榛樿閰嶇疆 */
export const DEFAULT_HYBRID_CONFIG: HybridRetrievalConfig = {
  alpha: 0.45,
  beta: 0.55,
  coarseMultiplier: 2,
  fineTopN: 15,
  enableBoundaryRegression: true,
  initialThreshold: 0.15,
  boundaryEma: 0.1,
};

// 鈹€鈹€ 浣欏鸡鐩镐技搴?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 璁＄畻涓や釜褰掍竴鍖栧悜閲忕殑浣欏鸡鐩镐技搴?*/
export function cosineSimilarity(a: number[], b: number[]): number {
  let dot = 0;
  const len = Math.min(a.length, b.length);
  for (let i = 0; i < len; i++) {
    dot += a[i] * b[i];
  }
  return dot; // 鍋囪宸插綊涓€鍖栵紝dot 鈭?[-1, 1]
}

/** 鎵归噺璁＄畻浣欏鸡鐩镐技搴?*/
export function batchCosineSimilarity(queryVec: number[], vectors: number[][]): number[] {
  return vectors.map((v) => cosineSimilarity(queryVec, v));
}

// 鈹€鈹€ 璇勫垎褰掍竴鍖?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** Min-max 褰掍竴鍖栧埌 [0, 1] */
function minMaxNormalize(scores: number[]): number[] {
  if (scores.length === 0) return [];
  const min = Math.min(...scores);
  const max = Math.max(...scores);
  const range = max - min;
  if (range === 0) return scores.map(() => 0.5);
  return scores.map((s) => (s - min) / range);
}

// 鈹€鈹€ 瀹炵幇 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class HybridRetriever {
  readonly config: HybridRetrievalConfig;

  // 鈹€鈹€ 杈圭晫鍥炲綊鐘舵€?鈹€鈹€
  private _adaptiveThreshold: number;
  private _thresholdHistory: number[] = []; // 鏈€杩?N 娆′娇鐢ㄧ殑闃堝€糪r

  constructor(config: Partial<HybridRetrievalConfig> = {}) {
    this.config = { ...DEFAULT_HYBRID_CONFIG, ...config };
    this._adaptiveThreshold = this.config.initialThreshold;
  }

  // 鈹€鈹€ 鍏紑 API 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 娣峰悎璇勫垎鈥斺€斿涓€鎵瑰€欓€夎蹇嗚繘琛?BM25 + 鍚戦噺鍙岄噸璇勫垎銆俓r
   *
   * @param candidates 鍊欓€夎蹇嗗垪琛╘r
   * @param bm25Scores  BM25 绱㈠紩杩斿洖鐨勮瘎鍒嗙粨鏋?{ id, score }
   * @param queryEmbedding 鏌ヨ鏂囨湰鐨勫悜閲忓祵鍏ワ紙鐢ㄤ簬浣欏鸡鐩镐技搴︼級
   * @param embedder 宓屽叆鏈嶅姟锛堢敤浜庤绠楀€欓€夎蹇嗗悜閲忥級
   * @returns 娣峰悎璇勫垎鍚庣殑璁板繂鍒楄〃锛屾寜 hybridScore 闄嶅簭
   */
  async score(
    candidates: MemoryEntry[],
    bm25Scores: Map<string, number>,
    queryEmbedding: number[],
    embedder: IEmbeddingService,
  ): Promise<HybridScoreResult[]> {
    if (candidates.length === 0) return [];

    // 鈹€鈹€ 鎻愬彇鍊欓€夎蹇嗙殑 semantic_gist 鎴?summary 鐢ㄤ簬鍚戦噺姣旇緝 鈹€鈹€
    const texts = candidates.map((m) => m.semantic_gist || m.summary || "");
    const candidateVectors = await embedder.embedBatch(texts);

    // 鈹€鈹€ 璁＄畻浣欏鸡鐩镐技搴?鈹€鈹€
    const cosScores = batchCosineSimilarity(queryEmbedding, candidateVectors);

    // 鈹€鈹€ 褰掍竴鍖?鈹€鈹€
    const rawBm25: number[] = candidates.map((m) => bm25Scores.get(m.id) ?? 0);
    const bm25Norm = minMaxNormalize(rawBm25);
    const cosNorm = minMaxNormalize(cosScores);

    // 鈹€鈹€ 鍔犳潈铻嶅悎 鈹€鈹€
    const { alpha, beta } = this.config;
    const results: HybridScoreResult[] = [];
    for (let i = 0; i < candidates.length; i++) {
      const hybrid = alpha * bm25Norm[i] + beta * cosNorm[i];
      results.push({
        entry: candidates[i],
        bm25Score: rawBm25[i],
        vectorScore: cosScores[i],
        hybridScore: hybrid,
      });
    }

    // 鎸夋贩鍚堝垎闄嶅簭
    results.sort((a, b) => b.hybridScore - a.hybridScore);
    return results;
  }

  /**
   * 璐績绮炬帓: 浠庡凡璇勫垎鐨勫€欓€夋睜涓€夊彇 Top-M锛岀劧鍚庢寜杈圭晫鍥炲綊瑁佸垏銆俓r
   *
   * 绠楁硶:
   *   coarse 姹?= 鍏ㄩ儴鍊欓€?(size N)
   *   閫夊彇 hybridScore 鏈€楂樼殑 fineTopN 鏉r
   *   杈圭晫鍥炲綊瑁佸垏: 鍘绘帀浣庝簬 adaptiveThreshold 鐨刓r
   *
   * @param scored 宸茶瘎鍒嗙殑鍊欓€塡r
   * @returns 绮炬帓鍚庣殑缁撴灉锛屼笉瓒呰繃 fineTopN
   */
  greedyFineRank(scored: HybridScoreResult[]): HybridScoreResult[] {
    if (scored.length === 0) return [];

    // 绮楁帓姹?鈫?鍙?Top-M
    const fine = scored.slice(0, Math.min(this.config.fineTopN, scored.length));

    // 杈圭晫鍥炲綊瑁佸垏
    if (this.config.enableBoundaryRegression) {
      const cutoff = this._adaptiveThreshold;
      const filtered = fine.filter((r) => r.hybridScore >= cutoff);

      // 濡傛灉瑁佸垏鍚庝负绌猴紝鑷冲皯淇濈暀 top-1锛堥伩鍏嶇┖缁撴灉锛塡r
      if (filtered.length === 0 && fine.length > 0) {
        return [fine[0]];
      }

      // 鏇存柊鑷€傚簲闃堝€糪r
      this._updateThreshold(filtered);
      return filtered;
    }

    return fine;
  }

  /**
   * 鑾峰彇褰撳墠鑷€傚簲闃堝€笺€俓r
   */
  get adaptiveThreshold(): number {
    return this._adaptiveThreshold;
  }

  /**
   * 閲嶇疆杈圭晫鍥炲綊鐘舵€併€俓r
   */
  resetBoundary(): void {
    this._adaptiveThreshold = this.config.initialThreshold;
    this._thresholdHistory = [];
  }

  // 鈹€鈹€ 鍐呴儴 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 鍦ㄧ嚎杈圭晫鍥炲綊鈥斺€旀寚鏁扮Щ鍔ㄥ钩鍧囨洿鏂拌嚜閫傚簲闃堝€笺€俓r
   *
   * 绛栫暐:
   *   - 璁板綍鏈€杩戠簿鎺掍腑淇濈暀鏉＄洰鐨勬渶浣庡垎
   *   - EMA 鏇存柊: newThreshold = oldThreshold + ema * (observedMin - oldThreshold)
   *   - 濡傛灉绮炬帓缁撴灉寰堝皯锛? 3 鏉★級锛岃交寰檷浣庨槇鍊间互鎵╁ぇ鍙洖
   */
  private _updateThreshold(results: HybridScoreResult[]): void {
    if (results.length === 0) return;

    // 鍙栬淇濈暀鏉＄洰涓殑鏈€浣庡垎浣滀负瑙傚療鍊糪r
    const observedMin = results[results.length - 1].hybridScore;

    // 绮炬帓缁撴灉灏戜簬 3 鏉℃椂锛屽悜鏇村鏉炬柟鍚戣皟鏁碶r
    const adjustedObserved = results.length < 3
      ? Math.max(0, observedMin * 0.7)
      : observedMin;

    // EMA 鏇存柊
    this._adaptiveThreshold =
      this._adaptiveThreshold + this.config.boundaryEma * (adjustedObserved - this._adaptiveThreshold);

    // 闄愬埗鍦ㄥ悎鐞嗚寖鍥碶r
    this._adaptiveThreshold = Math.max(0.01, Math.min(0.95, this._adaptiveThreshold));

    // 璁板綍鍘嗗彶
    this._thresholdHistory.push(this._adaptiveThreshold);
    if (this._thresholdHistory.length > 50) {
      this._thresholdHistory.shift();
    }
  }
}

