// ============================================================
// @cortex/memory 鈥?InMemoryMemoryStore 绾唴瀛樺疄鐜癨n//
// 鍩轰簬 Map<string, MemoryEntry> 鐨勭函鍐呭瓨 MemoryStore 瀹炵幇銆俓n// 閫傜敤浜庢祴璇曘€佷复鏃朵細璇濆拰鏃犻渶鎸佷箙鍖栫殑鍦烘櫙銆俓n//
// @design 鐗规€n//   - 鎵€鏈夋暟鎹瓨鍌ㄥ湪 Map 涓紝鏃犲閮ㄤ緷璧朶n//   - 鏀寔浜嬪姟锛堝熀浜庢搷浣滄棩蹇楃殑蹇収鏈哄埗锛塡n//   - 鏀寔涓ら樁娈垫彁浜わ紙Pending 鈫?Active / Obliterated锛塡n//   - 鏀寔鍏宠仈閾捐矾绠＄悊
//   - 绾跨▼瀹夊叏璇存槑锛歂ode.js 鍗曠嚎绋嬫ā鍨嬩笅 Map 鎿嶄綔鏄畨鍏ㄧ殑
//
// @extends TransactionalMemoryStore 鍚屾椂瀹炵幇 IMemoryStore 鍜屼簨鍔℃帴鍙n// ============================================================

import type {
  MemoryEntry,
  MemoryWriteInput,
  MemoryQuery,
  MemoryLink,
  SemanticState,
  LinkType,
  ReadMode,
} from "@cortex/shared";
import type { IMemoryStore } from "../interfaces/MemoryStore.js";
import type {
  TransactionalMemoryStore,
  TransactionContext,
  TransactionIsolation,
  TransactionResult,
  TransactionLinkOp,
} from "../interfaces/TransactionalMemoryStore.js";
import {
  MemoryStoreError,
  MemoryStoreErrorCode,
  MemoryValidationError,
  TransactionError,
} from "../errors/MemoryStoreError.js";
import { generateId, shortId } from "../_utils.js";

// 鈹€鈹€ 宸ュ叿鍑芥暟 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 閫掑綊鍐荤粨瀵硅薄鍙婂叾鎵€鏈夊祵濂楀睘鎬?*/
function deepFreeze<T>(obj: T): T {
  if (obj && typeof obj === "object" && !Object.isFrozen(obj)) {
    Object.freeze(obj);
    for (const key of Object.keys(obj as Record<string, unknown>)) {
      deepFreeze((obj as Record<string, unknown>)[key]);
    }
  }
  return obj;
}

// 鈹€鈹€ 鍐呴儴绫诲瀷 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 鍐呴儴 Pending 鏉＄洰璁板綍銆俓n */
interface PendingEntry {
  input: MemoryWriteInput;
  createdAt: number;
}

/**
 * 鍐呴儴浜嬪姟璁板綍銆俓n */
interface InternalTransaction {
  id: string;
  isolation: TransactionIsolation;
  status: "active" | "committed" | "rolledback" | "error";
  startedAt: number;
  timeoutAt: number;
  pendingWrites: MemoryWriteInput[];
  pendingLinks: TransactionLinkOp[];
  metadata?: Record<string, unknown>;
}

// 鈹€鈹€ 榛樿鍊煎父閲?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

const DEFAULT_TRANSACTION_TIMEOUT_MS = 30_000; // 30 绉抃nconst DEFAULT_PENDING_ID_PREFIX = "pending_";

/**
 * InMemoryMemoryStore 鈥斺€?鍩轰簬 Map 鐨勭函鍐呭瓨 MemoryStore 瀹炵幇銆俓n *
 * 鍚屾椂瀹炵幇 IMemoryStore锛堝彧璇伙級鍜?TransactionalMemoryStore锛堣鍐?浜嬪姟锛夈€俓n *
 * @example
 * ```typescript
 * const store = new InMemoryMemoryStore();
 * await store.init(":memory:");
 *
 * // 鍐欏叆
 * const id = await store.write({
 *   kind: "Insight",
 *   summary: "绀轰緥",
 *   semantic_gist: "绀轰緥璇箟绮惧崕",
 *   source: { agentType: "Alhaitham", taskId: "task-001" },
 *   content_blob: { key: "value" },
 * });
 *
 * // 璇诲彇
 * const entry = await store.get(id);
 * ```
 */
export class InMemoryMemoryStore implements IMemoryStore, TransactionalMemoryStore {
  // 鈹€鈹€ 瀛樺偍鍚庣 鈹€鈹€
  /** 涓诲瓨鍌細ID 鈫?MemoryEntry */
  private readonly _entries: Map<string, MemoryEntry> = new Map();

  /** 鍏宠仈閾捐矾锛歴ourceId 鈫?MemoryLink[] */
  private readonly _links: Map<string, MemoryLink[]> = new Map();

  /** Pending 鏉＄洰锛欼D 鈫?PendingEntry */
  private readonly _pendingEntries: Map<string, PendingEntry> = new Map();

  // 鈹€鈹€ 浜嬪姟 鈹€鈹€
  /** 娲诲姩浜嬪姟锛歵ransactionId 鈫?InternalTransaction */
  private readonly _transactions: Map<string, InternalTransaction> = new Map();

  /** 浜嬪姟瓒呮椂姣鏁?*/
  private _transactionTimeoutMs: number = DEFAULT_TRANSACTION_TIMEOUT_MS;

  // 鈹€鈹€ 浼氳瘽 鈹€鈹€
  /** 褰撳墠浼氳瘽 ID */
  private _sessionId: string | undefined;

  /** 鍓嶇疆鍐欏叆閽╁瓙 */
  private _preWriteHook: ((input: MemoryWriteInput) => MemoryWriteInput) | undefined;

  // 鈹€鈹€ 鐘舵€?鈹€鈹€
  private _isInitialized = false;

  // 鈹€鈹€ IMemoryStore 瀹炵幇 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  get isReady(): boolean {
    return this._isInitialized;
  }

  get size(): number {
    return this._entries.size;
  }

  get isPersisted(): boolean {
    return false;
  }

  get sessionId(): string | undefined {
    return this._sessionId;
  }

  async get(id: string): Promise<MemoryEntry | undefined> {
    this._ensureInitialized();
    const entry = this._entries.get(id);
    if (!entry) return undefined;

    // 杩斿洖涓嶅彲鍙樺揩鐓n    return structuredClone(entry) as MemoryEntry;
  }

  peek(id: string): Readonly<MemoryEntry> | undefined {
    this._ensureInitialized();
    const entry = this._entries.get(id);
    if (!entry) return undefined;
    // 杩斿洖娣卞喕缁撳揩鐓р€斺€旈槻姝㈠閮ㄦ剰澶栦慨鏀瑰鑷?CAS 绔炴€乗n    return deepFreeze(structuredClone(entry)) as Readonly<MemoryEntry>;
  }

  has(id: string): boolean {
    this._ensureInitialized();
    return this._entries.has(id);
  }

  getAllEntries(): MemoryEntry[] {
    this._ensureInitialized();
    return Array.from(this._entries.values());
  }

  async read(query: MemoryQuery, mode?: ReadMode): Promise<MemoryEntry[]> {
    this._ensureInitialized();

    let results = Array.from(this._entries.values());

    // 鎸夌被鍒繃婊n    if (query.kind) {
      results = results.filter(e => e.kind === query.kind);
    }

    // 鎸夊叧閿瘝杩囨护
    if (query.keywords && query.keywords.length > 0) {
      const lowerKeywords = query.keywords.map(k => k.toLowerCase());
      results = results.filter(entry => {
        const summary = entry.summary.toLowerCase();
        const gist = entry.semantic_gist.toLowerCase();
        return lowerKeywords.some(kw => summary.includes(kw) || gist.includes(kw));
      });
    }

    // 鎸夋椂闂磋寖鍥磋繃婊n    if (query.timeRange) {
      const timeRange = query.timeRange;
      results = results.filter(entry => {
        return entry.createdAt >= timeRange.start
          && entry.createdAt <= timeRange.end;
      });
    }

    // 鎸?agentTypes 杩囨护
    if (query.agentTypes && query.agentTypes.length > 0) {
      const agentTypes = query.agentTypes;
      results = results.filter(entry =>
        agentTypes.includes(entry.source.agentType),
      );
    }

    // 鎸?metadata 杩囨护
    if (query.metadataFilter) {
      const metadataFilter = query.metadataFilter;
      results = results.filter(entry => {
        return Object.entries(metadataFilter).every(([key, value]) => {
          return (entry.content_blob as Record<string, unknown>)[key] === value;
        });
      });
    }

    // BFS 鍥惧睍寮€
    if (query.bfsDepth && query.bfsDepth > 0) {
      results = this._bfsExpand(results, query.bfsDepth, query.bfsMaxNodes);
    }

    // 鎺掑簭锛氭寜鏉冮噸闄嶅簭锛屾潈閲嶇浉鍚屾椂鎸夊垱寤烘椂闂撮檷搴廫n    results.sort((a, b) => {
      if (b.weight !== a.weight) return b.weight - a.weight;
      return b.createdAt - a.createdAt;
    });

    // 闄愬埗鏁伴噺
    if (query.limit && query.limit > 0) {
      results = results.slice(0, query.limit);
    }

    // CSA 妯″紡杩借釜璁块棶鐑害
    if (mode === "CSA") {
      const now = Date.now();
      for (const entry of results) {
        const stored = this._entries.get(entry.id);
        if (stored) {
          stored.accessCount = (stored.accessCount ?? 0) + 1;
          stored.lastAccessedAt = now;
        }
      }
    }

    return results.map(e => structuredClone(e) as MemoryEntry);
  }

  getLinks(sourceId: string): MemoryLink[] {
    this._ensureInitialized();
    return structuredClone(this._links.get(sourceId) ?? []) as MemoryLink[];
  }

  getBySession(sessionId: string): MemoryEntry[] {
    this._ensureInitialized();
    const results: MemoryEntry[] = [];
    for (const entry of this._entries.values()) {
      if (entry.sessionId === sessionId) {
        results.push(structuredClone(entry) as MemoryEntry);
      }
    }
    return results;
  }

  getPending(): MemoryEntry[] {
    this._ensureInitialized();
    const results: MemoryEntry[] = [];
    for (const [id, pending] of this._pendingEntries) {
      const entry = this._buildPendingEntry(id, pending);
      results.push(entry);
    }
    return results;
  }

  hasPending(): boolean {
    this._ensureInitialized();
    return this._pendingEntries.size > 0;
  }

  async init(_dbPath: string): Promise<void> {
    if (this._isInitialized) {
      return;
    }
    // 绾唴瀛樺疄鐜板拷鐣?dbPath
    this._isInitialized = true;
  }

  beginSession(externalId?: string): string {
    this._ensureInitialized();
    this._sessionId = externalId ?? shortId();
    return this._sessionId;
  }

  async endSession(): Promise<number> {
    this._ensureInitialized();
    let affectedCount = 0;

    // 褰掓。褰撳墠浼氳瘽鐨?Active 璁板繂
    for (const entry of this._entries.values()) {
      if (entry.sessionId === this._sessionId && entry.semantic_state === "Active") {
        entry.semantic_state = "Archived";
        affectedCount++;
      }
    }

    // 婀伃褰撳墠浼氳瘽鐨?Pending 璁板繂
    for (const [id, pending] of this._pendingEntries) {
      if (pending.input.sessionId === this._sessionId) {
        this._pendingEntries.delete(id);
        affectedCount++;
      }
    }

    this._sessionId = undefined;
    return affectedCount;
  }

  async flush(): Promise<void> {
    // 绾唴瀛樺疄鐜版棤闇€鍒峰啓
    this._ensureInitialized();
  }

  async close(): Promise<void> {
    this._entries.clear();
    this._links.clear();
    this._pendingEntries.clear();
    this._transactions.clear();
    this._isInitialized = false;
    this._sessionId = undefined;
  }

  // 鈹€鈹€ TransactionalMemoryStore 瀹炵幇 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  async write(input: MemoryWriteInput): Promise<string> {
    this._ensureInitialized();
    this._validateWriteInput(input);

    const finalInput = this._applyPreWriteHook(input);

    const id = generateId();
    const now = Date.now();

    const entry: MemoryEntry = {
      id,
      source: finalInput.source,
      sessionId: finalInput.sessionId ?? this._sessionId,
      kind: finalInput.kind,
      summary: finalInput.summary,
      semantic_gist: finalInput.semantic_gist,
      content_blob: finalInput.content_blob as Record<string, unknown>,
      semantic_state: "Active",
      weight: finalInput.weight ?? 1.0,
      accessCount: 0,
      lastAccessedAt: now,
      createdAt: finalInput.createdAt ?? now,
      content_hash: finalInput.content_hash ?? "",
      embedding: finalInput.embedding,
      expires_at: finalInput.expires_at,
    };

    this._entries.set(id, entry);
    return id;
  }

  async set(id: string, entry: MemoryEntry): Promise<void> {
    this._ensureInitialized();
    this._entries.set(id, { ...entry });
  }

  async delete(id: string): Promise<boolean> {
    this._ensureInitialized();
    if (!this._entries.has(id)) {
      return false;
    }
    this._entries.delete(id);

    // 鍚屾椂娓呯悊鐩稿叧閾捐矾
    this._links.delete(id);
    for (const [, links] of this._links) {
      const filtered = links.filter(l => l.targetId !== id && l.sourceId !== id);
      if (filtered.length !== links.length) {
        // 鐢变簬鏄紩鐢ㄧ被鍨嬶紝鐩存帴淇敼鏁扮粍
        links.length = 0;
        links.push(...filtered);
      }
    }

    return true;
  }

  async writeMany(inputs: MemoryWriteInput[]): Promise<string[]> {
    this._ensureInitialized();
    const ids: string[] = [];
    for (const input of inputs) {
      const id = await this.write(input);
      ids.push(id);
    }
    return ids;
  }

  linkMany(links: Array<{
    sourceId: string;
    targetId: string;
    linkType: LinkType;
    weight?: number;
  }>): (MemoryLink | null)[] {
    this._ensureInitialized();
    return links.map(l => this.link(l.sourceId, l.targetId, l.linkType, l.weight));
  }

  cas(id: string, expected: SemanticState, newState: SemanticState): boolean {
    this._ensureInitialized();
    const entry = this._entries.get(id);
    if (!entry) return false;
    // Obliterated 鏄粓鎬佲€斺€斾笉鍏佽 CAS 杞Щ鍑烘鐘舵€乗n    if (entry.semantic_state === "Obliterated") return false;
    if (entry.semantic_state !== expected) return false;
    entry.semantic_state = newState;
    return true;
  }

  archive(id: string): boolean {
    this._ensureInitialized();
    const entry = this._entries.get(id);
    if (!entry) return false;
    if (entry.semantic_state !== "Active") return false;
    entry.semantic_state = "Archived";
    return true;
  }

  obliterate(id: string): boolean {
    this._ensureInitialized();
    const entry = this._entries.get(id);
    if (!entry) return false;
    entry.semantic_state = "Obliterated";
    return true;
  }

  writePending(input: MemoryWriteInput): string {
    this._ensureInitialized();
    this._validateWriteInput(input);

    const id = `${DEFAULT_PENDING_ID_PREFIX}${generateId()}`;
    const now = Date.now();

    this._pendingEntries.set(id, {
      input: { ...input },
      createdAt: now,
    });

    return id;
  }

  commitMemory(memoryId: string): boolean {
    this._ensureInitialized();
    const pending = this._pendingEntries.get(memoryId);
    if (!pending) return false;

    const now = Date.now();
    const entry: MemoryEntry = {
      id: memoryId,
      source: pending.input.source,
      sessionId: pending.input.sessionId ?? this._sessionId,
      kind: pending.input.kind,
      summary: pending.input.summary,
      semantic_gist: pending.input.semantic_gist,
      content_blob: pending.input.content_blob as Record<string, unknown>,
      semantic_state: "Active",
      weight: pending.input.weight ?? 1.0,
      accessCount: 0,
      lastAccessedAt: now,
      createdAt: pending.input.createdAt ?? now,
      content_hash: pending.input.content_hash ?? "",
      embedding: pending.input.embedding,
      expires_at: pending.input.expires_at,
    };

    this._entries.set(memoryId, entry);
    this._pendingEntries.delete(memoryId);
    return true;
  }

  /**
   * rollback 鈥斺€?閲嶈浇鏂规硶锛屾敮鎸?2PC 鍜屼簨鍔′袱绉嶈皟鐢ㄧ鍚嶃€俓n   *
   * 鐢变簬 TypeScript 涓嶆敮鎸佷袱涓悓鍚嶄笉鍚屽弬鏁扮殑鏂规硶鍏卞瓨浜庤繍琛屾椂锛孿n   * 鍥犳鍦ㄨ繍琛屾椂鏍规嵁鍙傛暟绫诲瀷鍒嗗彂鍒板唴閮ㄥ疄鐜般€俓n   * 缁熶竴杩斿洖 Promise 浠ラ伩鍏?esbuild 杞崲鏃剁殑鏂规硶閲嶈浇鍐茬獊銆俓n   */
  // 鈹€鈹€ 閲嶈浇绛惧悕 鈹€鈹€
  rollback(memoryId: string): Promise<boolean>;
  rollback(txn: TransactionContext): Promise<TransactionResult<void>>;
  // 鈹€鈹€ 瀹炵幇 鈹€鈹€
  async rollback(memoryIdOrTxn: string | TransactionContext): Promise<boolean | TransactionResult<void>> {
    if (typeof memoryIdOrTxn === "string") {
      return this._rollbackPendingEntry(memoryIdOrTxn);
    }
    return await this._rollbackTransaction(memoryIdOrTxn);
  }

  private _rollbackPendingEntry(memoryId: string): boolean {
    this._ensureInitialized();
    if (!this._pendingEntries.has(memoryId)) return false;
    this._pendingEntries.delete(memoryId);
    return true;
  }

  link(sourceId: string, targetId: string, linkType: LinkType, weight?: number): MemoryLink | null {
    this._ensureInitialized();

    // 妫€鏌ユ簮鍜岀洰鏍囨槸鍚﹀瓨鍦╘n    if (!this._entries.has(sourceId) || !this._entries.has(targetId)) {
      return null;
    }

    const targetEntry = this._entries.get(targetId);
    if (!targetEntry) return null;

    const link: MemoryLink = {
      id: generateId(),
      sourceId,
      targetId,
      linkType,
      weight: weight ?? 1.0,
      targetState: targetEntry.semantic_state,
      lastAccessedAt: Date.now(),
    };

    const existing = this._links.get(sourceId) ?? [];
    existing.push(link);
    this._links.set(sourceId, existing);

    return structuredClone(link) as MemoryLink;
  }

  // 鈹€鈹€ 浜嬪姟鎿嶄綔 鈹€鈹€

  async beginTransaction(isolation: TransactionIsolation = "ReadCommitted", metadata?: Record<string, unknown>): Promise<TransactionContext> {
    this._ensureInitialized();

    const id = `txn_${shortId()}`;
    const now = Date.now();

    const txn: InternalTransaction = {
      id,
      isolation,
      status: "active",
      startedAt: now,
      timeoutAt: now + this._transactionTimeoutMs,
      pendingWrites: [],
      pendingLinks: [],
      metadata,
    };

    this._transactions.set(id, txn);

    return this._buildTransactionContext(txn);
  }

  async writeWithin(txn: TransactionContext, input: MemoryWriteInput): Promise<string> {
    this._ensureInitialized();
    this._validateTransactionActive(txn);
    this._validateWriteInput(input);

    const internal = this._transactions.get(txn.id);
    if (!internal) {
      throw new TransactionError("Transaction not found", txn.id);
    }

    internal.pendingWrites.push({ ...input });

    // 杩斿洖鍗犱綅 ID锛坈ommit 鏃剁敓鎴愮湡瀹?ID锛塡n    return `pending_${internal.pendingWrites.length - 1}_${shortId()}`;
  }

  async writeManyWithin(txn: TransactionContext, inputs: MemoryWriteInput[]): Promise<string[]> {
    this._ensureInitialized();
    this._validateTransactionActive(txn);

    const ids: string[] = [];
    for (const input of inputs) {
      const id = await this.writeWithin(txn, input);
      ids.push(id);
    }
    return ids;
  }

  async linkWithin(txn: TransactionContext, sourceId: string, targetId: string, linkType: LinkType, weight?: number): Promise<MemoryLink | null> {
    this._ensureInitialized();
    this._validateTransactionActive(txn);

    const internal = this._transactions.get(txn.id);
    if (!internal) {
      throw new TransactionError("Transaction not found", txn.id);
    }

    internal.pendingLinks.push({
      action: "link",
      sourceId,
      targetId,
      linkType,
      weight,
    });

    // 浜嬪姟鍐呰繑鍥炲崰浣峔n    return {
      id: `pending_link_${internal.pendingLinks.length - 1}`,
      sourceId,
      targetId,
      linkType,
      weight: weight ?? 1.0,
      targetState: "Active",
      lastAccessedAt: Date.now(),
    };
  }

  async linkManyWithin(txn: TransactionContext, links: Array<{
    sourceId: string;
    targetId: string;
    linkType: LinkType;
    weight?: number;
  }>): Promise<(MemoryLink | null)[]> {
    this._ensureInitialized();
    this._validateTransactionActive(txn);

    const results: (MemoryLink | null)[] = [];
    for (const link of links) {
      const result = await this.linkWithin(txn, link.sourceId, link.targetId, link.linkType, link.weight);
      results.push(result);
    }
    return results;
  }

  async readWithin(txn: TransactionContext, query: MemoryQuery, mode?: ReadMode): Promise<MemoryEntry[]> {
    this._ensureInitialized();
    this._validateTransactionActive(txn);

    // 浜嬪姟鍐呰鍙栦笌鏅€氳鍙栫浉鍚岋紙ReadCommitted 绾у埆锛塡n    return await this.read(query, mode);
  }

  async commit(txn: TransactionContext): Promise<TransactionResult<string[]>> {
    this._ensureInitialized();

    const internal = this._transactions.get(txn.id);
    if (!internal) {
      throw new TransactionError("Transaction not found", txn.id);
    }

    if (internal.status !== "active") {
      throw new TransactionError(
        `Transaction is already ${internal.status}, cannot commit`,
        txn.id,
      );
    }

    try {
      // 鎵归噺鍐欏叆鎵€鏈夋寕璧风殑璁板繂
      const committedIds: string[] = [];
      for (const writeInput of internal.pendingWrites) {
        const id = await this.write(writeInput);
        committedIds.push(id);
      }

      // 鎵归噺鍐欏叆鎵€鏈夋寕璧风殑鍏宠仈
      for (const linkOp of internal.pendingLinks) {
        if (linkOp.action === "link") {
          this.link(linkOp.sourceId, linkOp.targetId, linkOp.linkType, linkOp.weight);
        }
        // unlink 鎿嶄綔鍦ㄥ唴瀛樻ā鍨嬩腑鏆備负 noop
      }

      internal.status = "committed";
      this._transactions.delete(internal.id);

      return {
        success: true,
        data: committedIds,
        affectedCount: committedIds.length + internal.pendingLinks.length,
      };
    } catch (error) {
      internal.status = "error";
      return {
        success: false,
        error: error instanceof Error ? error : new Error(String(error)),
        affectedCount: 0,
      };
    }
  }

  private async _rollbackTransaction(txn: TransactionContext): Promise<TransactionResult<void>> {
    this._ensureInitialized();

    const internal = this._transactions.get(txn.id);
    if (!internal) {
      throw new TransactionError("Transaction not found", txn.id);
    }

    if (internal.status !== "active" && internal.status !== "error") {
      throw new TransactionError(
        `Transaction is already ${internal.status}, cannot rollback`,
        txn.id,
      );
    }

    // 娓呯悊鎸傝捣鏁版嵁
    internal.pendingWrites.length = 0;
    internal.pendingLinks.length = 0;
    internal.status = "rolledback";
    this._transactions.delete(internal.id);

    return {
      success: true,
      affectedCount: 0,
    };
  }

  getActiveTransactions(): TransactionContext[] {
    this._ensureInitialized();

    // 娓呯悊瓒呮椂浜嬪姟
    this._purgeExpiredTransactions();

    return Array.from(this._transactions.values())
      .filter(t => t.status === "active")
      .map(t => this._buildTransactionContext(t));
  }

  setTransactionTimeout(ms: number): void {
    this._transactionTimeoutMs = ms;
  }

  setPreWriteHook(hook: (input: MemoryWriteInput) => MemoryWriteInput): void {
    this._preWriteHook = hook;
  }

  // 鈹€鈹€ 鍐呴儴鏂规硶 鈹€鈹€

  /**
   * 鏍￠獙瀛樺偍鏄惁宸插垵濮嬪寲銆俓n   */
  private _ensureInitialized(): void {
    if (!this._isInitialized) {
      throw new MemoryStoreError(
        MemoryStoreErrorCode.StoreNotInitialized,
        "Memory store is not initialized. Call init() first.",
      );
    }
  }

  /**
   * 鏍￠獙鍐欏叆杈撳叆鐨勬湁鏁堟€с€俓n   */
  private _validateWriteInput(input: MemoryWriteInput): void {
    const invalidFields: string[] = [];

    if (!input.source) {
      invalidFields.push("source");
    }
    if (!input.kind) {
      invalidFields.push("kind");
    }
    if (!input.summary || input.summary.trim().length === 0) {
      invalidFields.push("summary");
    }
    if (!input.semantic_gist || input.semantic_gist.trim().length === 0) {
      invalidFields.push("semantic_gist");
    }
    if (!input.content_blob || typeof input.content_blob !== "object") {
      invalidFields.push("content_blob");
    }

    if (invalidFields.length > 0) {
      throw new MemoryValidationError(invalidFields);
    }
  }

  /**
   * 鏍￠獙浜嬪姟澶勪簬娲昏穬鐘舵€併€俓n   */
  private _validateTransactionActive(txn: TransactionContext): void {
    const internal = this._transactions.get(txn.id);
    if (!internal) {
      throw new TransactionError("Transaction not found or already completed", txn.id);
    }

    if (internal.status !== "active") {
      throw new TransactionError(
        `Transaction is ${internal.status}, expected active`,
        txn.id,
      );
    }

    // 妫€鏌ヨ秴鏃禱n    if (Date.now() > internal.timeoutAt) {
      internal.status = "error";
      this._transactions.delete(internal.id);
      throw new TransactionError("Transaction timed out", txn.id);
    }
  }

  /**
   * 娓呯悊宸茶繃鏈熺殑浜嬪姟銆俓n   */
  private _purgeExpiredTransactions(): void {
    const now = Date.now();
    for (const [id, txn] of this._transactions) {
      if (now > txn.timeoutAt && txn.status === "active") {
        txn.status = "rolledback";
        this._transactions.delete(id);
      }
    }
  }

  /**
   * 浠?PendingEntry 鏋勫缓 MemoryEntry锛堢敤浜?getPending锛夈€俓n   */
  private _buildPendingEntry(id: string, pending: PendingEntry): MemoryEntry {
    return {
      id,
      source: pending.input.source,
      sessionId: pending.input.sessionId,
      kind: pending.input.kind,
      summary: pending.input.summary,
      semantic_gist: pending.input.semantic_gist,
      content_blob: pending.input.content_blob as Record<string, unknown>,
      semantic_state: "Active",
      weight: pending.input.weight ?? 1.0,
      accessCount: 0,
      lastAccessedAt: pending.createdAt,
      createdAt: pending.input.createdAt ?? pending.createdAt,
      content_hash: pending.input.content_hash ?? "",
      embedding: pending.input.embedding,
      expires_at: pending.input.expires_at,
      _pending: true,
    };
  }

  /**
   * 搴旂敤鍓嶇疆鍐欏叆閽╁瓙銆俓n   */
  private _applyPreWriteHook(input: MemoryWriteInput): MemoryWriteInput {
    if (this._preWriteHook) {
      return this._preWriteHook(input);
    }
    return input;
  }

  /**
   * 浠庡唴閮ㄤ簨鍔¤褰曟瀯寤哄叕寮€鐨?TransactionContext銆俓n   */
  private _buildTransactionContext(internal: InternalTransaction): TransactionContext {
    return {
      id: internal.id,
      status: internal.status === "error" ? "rolledback" : internal.status,
      startedAt: internal.startedAt,
      isolation: internal.isolation,
      timeoutAt: internal.timeoutAt,
      pendingWrites: [...internal.pendingWrites],
      pendingLinks: [...internal.pendingLinks],
      metadata: internal.metadata ? { ...internal.metadata } : undefined,
    };
  }

  /**
   * BFS 鍥惧睍寮€銆俓n   */
  private _bfsExpand(entries: MemoryEntry[], depth: number, maxNodes?: number): MemoryEntry[] {
    const visited = new Set<string>(entries.map(e => e.id));
    const result = [...entries];
    let queue = entries.map(e => e.id);

    for (let d = 0; d < depth && queue.length > 0; d++) {
      const nextQueue: string[] = [];

      for (const sourceId of queue) {
        const links = this._links.get(sourceId) ?? [];
        for (const link of links) {
          if (!visited.has(link.targetId)) {
            visited.add(link.targetId);
            const target = this._entries.get(link.targetId);
            if (target) {
              result.push(target);
              nextQueue.push(link.targetId);
            }
          }
        }

        if (maxNodes && result.length >= maxNodes) {
          return result.slice(0, maxNodes);
        }
      }

      queue = nextQueue;
    }

    return result;
  }
}

/**
 * parser.ts 鈥?Markdown 鈫?HTML 杞崲瑙ｆ瀽鍣╘n *
 * 鏀寔鐨?Markdown 璇硶锛歕n *   - 鏍囬: # ~ ######
 *   - 娈佃惤: 杩炵画鏂囨湰鍧梊n *   - 寮鸿皟: **鍔犵矖**, *鏂滀綋*
 *   - 琛屽唴浠ｇ爜: `code`
 *   - 浠ｇ爜鍧? ```language ... ```
 *   - 鏃犲簭鍒楄〃: -, *
 *   - 鏈夊簭鍒楄〃: 1. 2. 3.
 *   - 寮曠敤鍧? >
 *   - 鍒嗗壊绾? ---, ***, ___
 *   - 閾炬帴: [text](url)
 *   - 鍥剧墖: ![alt](url)
 *   - 杞箟: \<char> 淇濈暀瀛楅潰瀛楃
 *
 * 鍘熶綅浜?projects/solo-flight/packages/parser/src/parser.ts
 */

// 鈹€鈹€鈹€ 琛屽唴瑙ｆ瀽 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 杞箟瀛楃鏄犲皠 */
const ESCAPE_MAP: Record<string, string> = {
  '\\`': '`',
  '\\*': '*',
  '\\_': '_',
  '\\[': '[',
  '\\]': ']',
  '\\(': '(',
  '\\)': ')',
  '\\!': '!',
  '\\#': '#',
  '\\\\': '\\',
};

/**
 * 瑙ｆ瀽琛屽唴鍏冪礌锛堝己璋冦€佷唬鐮併€侀摼鎺ャ€佸浘鐗囥€佽浆涔夛級銆俓n * 浣跨敤鍗曟鎵弿 + 姝ｅ垯鍖归厤锛屾寜浼樺厛绾т緷娆″鐞嗐€俓n *
 * @fix N-08 鈥?鍦ㄥ姞绮楁鏌ュ墠鎻掑叆涓夌骇宓屽 `***text***` 妫€娴嬶紝
 *       闃叉鍔犵矖鍖归厤璇皢 `***` 缁撳熬鐨勫墠涓や釜 `*` 褰撲綔缁撴潫鏍囪銆俓n */
function parseInline(text: string): string {
  let result = '';
  let i = 0;

  while (i < text.length) {
    // 杞箟瀛楃
    if (text[i] === '\\' && i + 1 < text.length) {
      const seq = text.slice(i, i + 2);
      if (ESCAPE_MAP[seq] !== undefined) {
        result += ESCAPE_MAP[seq];
        i += 2;
        continue;
      }
    }

    // 琛屽唴浠ｇ爜 `鈥
    if (text[i] === '`') {
      const end = text.indexOf('`', i + 1);
      if (end !== -1) {
        result += `<code>${escapeHtml(text.slice(i + 1, end))}</code>`;
        i = end + 1;
        continue;
      }
    }

    // 鍥剧墖 ![alt](url)
    if (text[i] === '!' && i + 1 < text.length && text[i + 1] === '[') {
      const closeBracket = text.indexOf(']', i + 2);
      if (closeBracket !== -1 && text[closeBracket + 1] === '(') {
        const closeParen = text.indexOf(')', closeBracket + 2);
        if (closeParen !== -1) {
          const alt = text.slice(i + 2, closeBracket);
          const url = text.slice(closeBracket + 2, closeParen);
          result += `<img src="${escapeAttr(url)}" alt="${escapeAttr(alt)}">`;
          i = closeParen + 1;
          continue;
        }
      }
    }

    // 閾炬帴 [text](url)
    if (text[i] === '[') {
      const closeBracket = text.indexOf(']', i + 1);
      if (closeBracket !== -1 && text[closeBracket + 1] === '(') {
        const closeParen = text.indexOf(')', closeBracket + 2);
        if (closeParen !== -1) {
          const linkText = text.slice(i + 1, closeBracket);
          const url = text.slice(closeBracket + 2, closeParen);
          result += `<a href="${escapeAttr(url)}">${parseInline(linkText)}</a>`;
          i = closeParen + 1;
          continue;
        }
      }
    }

    // @fix N-08 鈥?涓夌骇宓屽 ***text*** 鈫?<strong><em>text</em></strong>
    if ((text[i] === '*' && text[i + 1] === '*' && text[i + 2] === '*') ||
        (text[i] === '_' && text[i + 1] === '_' && text[i + 2] === '_')) {
      const marker = text.slice(i, i + 3);
      const end = text.indexOf(marker, i + 3);
      if (end !== -1) {
        result += `<strong><em>${parseInline(text.slice(i + 3, end))}</em></strong>`;
        i = end + 3;
        continue;
      }
    }

    // 鍔犵矖 **text** 鎴?__text__
    if ((text[i] === '*' && text[i + 1] === '*') ||
        (text[i] === '_' && text[i + 1] === '_')) {
      const marker = text.slice(i, i + 2);
      const end = text.indexOf(marker, i + 2);
      if (end !== -1) {
        result += `<strong>${parseInline(text.slice(i + 2, end))}</strong>`;
        i = end + 2;
        continue;
      }
    }

    // 鏂滀綋 *text* 鎴?_text_
    if (text[i] === '*' || text[i] === '_') {
      const marker = text[i];
      const end = text.indexOf(marker, i + 1);
      if (end !== -1) {
        // 閬垮厤璇尮閰嶅姞绮楁爣璁癨n        if (end + 1 < text.length && text[end + 1] === marker) {
          // 杩欐槸鍔犵矖鐨勮捣濮嬶紝涓嶆槸鏂滀綋鐨勭粨鏉焅n          result += text[i];
          i++;
          continue;
        }
        result += `<em>${parseInline(text.slice(i + 1, end))}</em>`;
        i = end + 1;
        continue;
      }
    }

    // 鏅€氬瓧绗n    result += text[i];
    i++;
  }

  return result;
}

/** HTML 瀹炰綋杞箟 */
function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/** HTML 灞炴€у€艰浆涔?*/
function escapeAttr(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// 鈹€鈹€鈹€ 鍧楃骇瑙ｆ瀽 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/** 鍒ゆ柇鏄惁涓哄垎鍓茬嚎 */
function isThematicBreak(line: string): boolean {
  const trimmed = line.trim();
  if (trimmed.length < 3) return false;
  if (/^---+\s*$/.test(trimmed)) return true;
  if (/^\*{3,}\s*$/.test(trimmed)) return true;
  if (/^_{3,}\s*$/.test(trimmed)) return true;
  return false;
}

/** 鍒ゆ柇鏄惁涓烘爣棰樿 */
function isHeading(line: string): { level: number; content: string } | null {
  const match = line.match(/^(#{1,6})\s+(.+)$/);
  if (match) {
    return { level: match[1].length, content: match[2].trim() };
  }
  return null;
}

/** 鍒ゆ柇鏄惁涓哄紩鐢ㄨ */
function isBlockquote(line: string): string | null {
  const match = line.match(/^>\s?(.*)$/);
  return match ? match[1] : null;
}

/** 鍒ゆ柇鏄惁涓烘棤搴忓垪琛ㄩ」 */
function isUnorderedListItem(line: string): string | null {
  const match = line.match(/^[-*+]\s+(.+)$/);
  return match ? match[1] : null;
}

/** 鍒ゆ柇鏄惁涓烘湁搴忓垪琛ㄩ」 */
function isOrderedListItem(line: string): { content: string; start: number } | null {
  const match = line.match(/^(\d+)\.\s+(.+)$/);
  if (match) {
    return { content: match[2], start: parseInt(match[1], 10) };
  }
  return null;
}

/** 鍒ゆ柇鏄惁涓轰唬鐮佸洿鏍忓紑濮?*/
function isFenceStart(line: string): string | null {
  const match = line.match(/^```(\w*)$/);
  return match ? match[1] || null : null;
}

/** 瑙ｆ瀽浠ｇ爜鍧楀唴瀹?*/
function parseCodeBlock(lines: string[], startIdx: number): { html: string; endIdx: number } {
  const fenceLang = isFenceStart(lines[startIdx]);
  const langClass = fenceLang ? ` class="language-${escapeAttr(fenceLang)}"` : '';
  const codeLines: string[] = [];
  let i = startIdx + 1;

  while (i < lines.length) {
    if (lines[i].trim() === '```') {
      i++; // 璺宠繃缁撴潫鍥存爮
      break;
    }
    codeLines.push(lines[i]);
    i++;
  }

  const code = codeLines.join('\n');
  const html = `<pre><code${langClass}>${escapeHtml(code)}</code></pre>\n`;
  return { html, endIdx: i };
}

// 鈹€鈹€鈹€ 鍏紑 API 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 灏?Markdown 鏂囨湰杞崲涓?HTML 瀛楃涓层€俓n *
 * @param markdown - 鍘熷 Markdown 鏂囨湰
 * @returns 杞崲鍚庣殑 HTML 瀛楃涓瞈n */
export function convert(markdown: string): string {
  const lines = markdown.split('\n');
  const htmlParts: string[] = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // 绌鸿 鈥?璺宠繃
    if (line.trim() === '') {
      i++;
      continue;
    }

    // 浠ｇ爜鍧梊n    if (line.trimStart().startsWith('```')) {
      const { html, endIdx } = parseCodeBlock(lines, i);
      htmlParts.push(html);
      i = endIdx;
      continue;
    }

    // 鍒嗗壊绾縗n    if (isThematicBreak(line)) {
      htmlParts.push('<hr>\n');
      i++;
      continue;
    }

    // 鏍囬
    const heading = isHeading(line);
    if (heading) {
      htmlParts.push(
        `<h${heading.level}>${parseInline(heading.content)}</h${heading.level}>\n`
      );
      i++;
      continue;
    }

    // 寮曠敤鍧楋紙鏀寔澶氳锛塡n    if (isBlockquote(line) !== null) {
      const quoteLines: string[] = [];
      while (i < lines.length) {
        const q = isBlockquote(lines[i]);
        if (q === null) break;
        quoteLines.push(q);
        i++;
      }
      const content = quoteLines
        .map((q) => parseInline(q))
        .join('<br>\n');
      htmlParts.push(`<blockquote>\n<p>${content}</p>\n</blockquote>\n`);
      continue;
    }

    // 鏃犲簭鍒楄〃
    const ulItem = isUnorderedListItem(line);
    if (ulItem !== null) {
      const items: string[] = [];
      while (i < lines.length) {
        const item = isUnorderedListItem(lines[i]);
        if (item === null) break;
        items.push(parseInline(item));
        i++;
      }
      htmlParts.push(
        '<ul>\n' + items.map((item) => `  <li>${item}</li>`).join('\n') + '\n</ul>\n'
      );
      continue;
    }

    // 鏈夊簭鍒楄〃
    const olItem = isOrderedListItem(line);
    if (olItem !== null) {
      const items: string[] = [];
      const startNum = olItem.start;
      while (i < lines.length) {
        const item = isOrderedListItem(lines[i]);
        if (item === null) break;
        items.push(parseInline(item.content));
        i++;
      }
      const startAttr = startNum !== 1 ? ` start="${startNum}"` : '';
      htmlParts.push(
        `<ol${startAttr}>\n` + items.map((item) => `  <li>${item}</li>`).join('\n') + '\n</ol>\n'
      );
      continue;
    }

    // 娈佃惤
    const paragraphLines: string[] = [];
    while (i < lines.length) {
      const l = lines[i];
      if (l.trim() === '') break;
      if (isHeading(l)) break;
      if (isThematicBreak(l)) break;
      if (l.trimStart().startsWith('```')) break;
      if (isBlockquote(l) !== null) break;
      if (isUnorderedListItem(l) !== null) break;
      if (isOrderedListItem(l) !== null) break;
      paragraphLines.push(l);
      i++;
    }

    if (paragraphLines.length > 0) {
      const paragraph = paragraphLines
        .map((l) => parseInline(l))
        .join('\n');
      htmlParts.push(`<p>${paragraph}</p>\n`);
    }
  }

  return htmlParts.join('');
}

/**
 * 灏?Markdown 鏂囨湰杞崲涓哄畬鏁寸殑 HTML 鏂囨。銆俓n * 鍖呰 convert() 鐨勮緭鍑猴紝娣诲姞 DOCTYPE銆乭ead銆乼itle銆佸熀纭€鏍峰紡鍜?body銆俓n *
 * @param markdown - 鍘熷 Markdown 鏂囨湰
 * @param title - 鍙€夋枃妗ｆ爣棰橈紝榛樿 "Document"
 * @returns 瀹屾暣鐨?HTML 鏂囨。瀛楃涓瞈n */
export function convertToDocument(markdown: string, title?: string): string {
  const docTitle = title || 'Document';
  const body = convert(markdown);
  return [
    '<!DOCTYPE html>',
    '<html lang="zh-CN">',
    '<head>',
    '<meta charset="UTF-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1.0">',
    `<title>${docTitle}</title>`,
    '<style>',
    'body { font-family: system-ui, sans-serif; max-width: 800px; margin: 0 auto; padding: 2rem; line-height: 1.6; color: #333; }',
    'pre { background: #f4f4f4; padding: 1rem; border-radius: 4px; overflow-x: auto; }',
    'code { background: #f4f4f4; padding: 0.2em 0.4em; border-radius: 3px; font-size: 0.9em; }',
    'pre code { background: none; padding: 0; }',
    'blockquote { border-left: 3px solid #ccc; margin: 0; padding: 0.5em 1em; color: #666; }',
    '</style>',
    '</head>',
    '<body>',
    body,
    '</body>',
    '</html>',
  ].join('\n');
}

// ============================================================
// @cortex/pattern-extractor 鈥?JsonPatternExtractor 瀹炵幇
// ============================================================
//
// @file-overview
// JsonPatternExtractor 鏄?PatternExtractor 鎺ュ彛鐨勪竴涓叿浣撳疄鐜帮紝
// 涓撻棬鐢ㄤ簬浠?JSON 鍐呭涓彁鍙栫粨鏋勬ā寮忓拰鍛藉悕绾﹀畾妯″紡銆俓n//
// 閫傜敤鍦烘櫙锛歕n// - 鍒嗘瀽 API 鍝嶅簲鐨?JSON Schema 缁撴瀯妯″紡
