/**
 * 妫€娴嬮敭鍚嶇殑鍛藉悕椋庢牸銆俓n *
 * 鍖归厤瑙勫垯锛堟寜浼樺厛绾э級锛歕n * 1. 鍏ㄥ皬鍐?+ 杩炲瓧绗﹀垎闅?鈫?kebab-case锛堝 "user-name"锛塡n * 2. 鍏ㄥ皬鍐?+ 涓嬪垝绾垮垎闅?鈫?snake_case锛堝 "user_name"锛塡n * 3. 棣栧瓧姣嶅ぇ鍐?+ 鏃犲垎闅旂 鈫?PascalCase锛堝 "UserName"锛塡n * 4. 棣栧瓧姣嶅皬鍐?+ 鏃犲垎闅旂 鈫?camelCase锛堝 "userName"锛塡n * 5. 浠ヤ笂鍧囦笉鍖归厤 鈫?other
 *
 * @param key - JSON 瀵硅薄閿悕
 * @returns 妫€娴嬪埌鐨勫懡鍚嶉鏍糪n *
 * @example
 * ```typescript
 * detectNamingStyle("userName");   // 鈫?"camelCase"
 * detectNamingStyle("user_name");  // 鈫?"snake_case"
 * detectNamingStyle("UserName");   // 鈫?"PascalCase"
 * detectNamingStyle("user-name");  // 鈫?"kebab-case"
 * detectNamingStyle("123key");     // 鈫?"other"
 * ```
 */
function detectNamingStyle(key: string): NamingStyle {
  // 绌洪敭鎴栭潪瀛楁瘝寮€澶碶n  if (key.length === 0) {
    return "other";
  }

  // kebab-case: 浠呭惈灏忓啓瀛楁瘝銆佹暟瀛楀拰杩炲瓧绗︼紝涓斿惈杩炲瓧绗n  if (/^[a-z][a-z0-9]*(-[a-z][a-z0-9]*)*$/.test(key)) {
    return "kebab-case";
  }

  // snake_case: 浠呭惈灏忓啓瀛楁瘝銆佹暟瀛楀拰涓嬪垝绾匡紝涓斿惈涓嬪垝绾縗n  if (/^[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*$/.test(key)) {
    return "snake_case";
  }

  // PascalCase: 棣栧瓧姣嶅ぇ鍐欙紝鏃犲垎闅旂
  if (/^[A-Z][a-zA-Z0-9]*$/.test(key)) {
    return "PascalCase";
  }

  // camelCase: 棣栧瓧姣嶅皬鍐欙紝鏃犲垎闅旂
  if (/^[a-z][a-zA-Z0-9]*$/.test(key)) {
    return "camelCase";
  }

  return "other";
}

/**
 * 妫€娴?JSON 鍊肩殑绫诲瀷銆俓n *
 * 浣跨敤 Object.prototype.toString 杩涜绫诲瀷妫€娴嬶紝
 * 鍖哄垎 object锛堟櫘閫氬璞★級鍜?array锛堟暟缁勶級銆俓n *
 * @param value - JSON 鍊糪n * @returns 灞炴€х被鍨嬫灇涓惧€糪n */
function detectPropertyType(value: JsonValue): PropertyType {
  if (value === null) {
    return "null";
  }

  if (Array.isArray(value)) {
    return "array";
  }

  if (typeof value === "object") {
    return "object";
  }

  // typeof 杩斿洖 "string" | "number" | "boolean"
  // 浣?TypeScript 鏀剁獎鍚?value 涓?string | number | boolean
  if (typeof value === "string") {
    return "string";
  }

  if (typeof value === "number") {
    return "number";
  }

  // boolean
  return "boolean";
}

