/**
 * 閫掑綊鍒嗘瀽 JSON 鍊硷紝濉厖缁熻淇℃伅銆俓n *
 * 閬嶅巻绛栫暐锛歕n * - 瀵硅薄锛氶亶鍘嗘墍鏈夐敭锛岀疮璁″懡鍚嶉鏍艰鏁板拰绫诲瀷璁℃暟
 * - 鏁扮粍锛氭鏌ュ厓绱犵被鍨嬪悓璐ㄦ€э紝閫掑綊鍒嗘瀽瀵硅薄/鏁扮粍鎴愬憳
 * - 鍩烘湰绫诲瀷锛氫粎绱绫诲瀷璁℃暟
 *
 * 娣卞害璺熻釜锛氭瘡杩涘叆涓€灞傚祵濂?depth + 1锛屽綋鍓嶈妭鐐圭殑 depth
 * 涓鸿繘鍏ユ椂鐨勬繁搴﹀€笺€俓n *
 * @param value  - 褰撳墠閬嶅巻鐨?JSON 鍊糪n * @param stats  - 缁熻绱Н鍣紙灏卞湴淇敼锛塡n * @param depth  - 褰撳墠宓屽娣卞害锛堟牴鑺傜偣涓?0锛塡n * @param seen   - 瀵硅薄寮曠敤 Set锛岀敤浜庢娴嬪惊鐜紩鐢╘n * @returns void锛坰tats 灏卞湴淇敼锛塡n */
function analyzeJsonValue(
  value: JsonValue,
  stats: JsonAnalysisStats,
  depth: number,
  seen: Set<object>,
): void {
  stats.visitedNodes++;
  stats.totalDepthSum += depth;

  if (depth > stats.maxDepth) {
    stats.maxDepth = depth;
  }

  if (value === null) {
    stats.typeCounts.null++;
    return;
  }

  if (typeof value === "string") {
    stats.typeCounts.string++;
    stats.totalStringLength += value.length;
    stats.stringValueCount++;
    return;
  }

  if (typeof value === "number") {
    stats.typeCounts.number++;
    return;
  }

  if (typeof value === "boolean") {
    stats.typeCounts.boolean++;
    return;
  }

  if (Array.isArray(value)) {
    stats.typeCounts.array++;
    stats.arraysAnalyzed++;

    // 妫€鏌ユ暟缁勫厓绱犵被鍨嬪悓璐ㄦ€n    if (value.length > 0) {
      const firstType = value.length > 0 ? detectPropertyType(value[0]) : null;
      let isHomogeneous = true;

      if (firstType !== null) {
        for (let i = 1; i < value.length; i++) {
          const elementType = detectPropertyType(value[i]);
          if (elementType !== firstType) {
            isHomogeneous = false;
            break;
          }
        }
      }

      if (isHomogeneous) {
        stats.homogeneousArrays++;
      }
    }

    // 閫掑綊鍒嗘瀽鏁扮粍鍏冪礌
    for (const element of value) {
      analyzeJsonValue(element, stats, depth + 1, seen);
    }
    return;
  }

  // 鏅€氬璞n  if (typeof value === "object" && value !== null) {
    stats.typeCounts.object++;

    // 寰幆寮曠敤妫€娴媆n    if (seen.has(value)) {
      return;
    }
    seen.add(value);

    const keys = Object.keys(value);
    stats.propertyCountsPerObject.push(keys.length);

    for (const key of keys) {
      stats.allKeys.push(key);

      // 缁熻鍛藉悕椋庢牸
      const style = detectNamingStyle(key);
      stats.namingCounts[style]++;

      // 閫掑綊鍒嗘瀽灞炴€у€糪n      const propValue = value[key];
      analyzeJsonValue(propValue, stats, depth + 1, seen);
    }

    seen.delete(value);
  }
}

