  // ============================================================
  // 绛栫暐 1锛欽SON 鍧楁彁鍙朶r
  // ============================================================

  /**
   * 绛栫暐 1 鈥斺€?浠?Markdown 涓彁鍙?```json 浠ｇ爜鍧楀苟瑙ｆ瀽涓?SkillTemplate銆俓r
   *
   * 杩欐槸鏈€楂樼疆淇″害鐨勭瓥鐣モ€斺€擲killTemplate 鏈韩灏辨槸 JSON 鏍煎紡锛孿r
   * 鑾鍜屼竴浜?Agent 鐩存帴杈撳嚭 ```json ... ``` 浠ｇ爜鍧椼€俓r
   *
   * 瀹炵幇璺嚎锛歕r
   * 1. 鐢?JSON_BLOCK_RE 鏌ユ壘鎵€鏈?```json 鍧梊r
   * 2. 瀵规瘡涓潡灏濊瘯 JSON.parse
   * 3. 鏍￠獙鏄惁鍖呭惈 SkillTemplate 鍏抽敭瀛楁锛坕d/name/triggerTags/steps锛塡r
   * 4. 鎴愬姛瑙ｆ瀽 鈫?confidence = 0.9鈥?.0锛堝瓧娈靛畬鏁存€ц秺楂樿秺鎺ヨ繎 1.0锛塡r
   * 5. 瑙ｆ瀽澶辫触 鈫?璁板綍 diagnostic锛屼笉浜у嚭鍊欓€塡r
   *
   * @param input       - Markdown 鏂囨湰
   * @param diagnostics - 璇婃柇淇℃伅绱姞鍣╘r
   * @param opts        - 瀹屾暣閫夐」
   * @returns 鍊欓€夊垪琛╘r
   */
  private _extractJsonBlocks(
    input: string,
    diagnostics: string[],
    _opts: Required<MarkdownExtractorOptions>,
  ): SkillTemplateCandidate[] {
    const candidates: SkillTemplateCandidate[] = [];

    // 閲嶇疆 lastIndex
    MarkdownPatternExtractor.JSON_BLOCK_RE.lastIndex = 0;

    let match: RegExpExecArray | null;
    while ((match = MarkdownPatternExtractor.JSON_BLOCK_RE.exec(input)) !== null) {
      const jsonText = match[1];

      // 鈹€鈹€ JSON 瑙ｆ瀽 鈹€鈹€
      let parsed: unknown;
      try {
        parsed = JSON.parse(jsonText);
      } catch (e) {
        diagnostics.push(
          `[${this.name}] JSON 鍧楄В鏋愬け璐?(offset ${match.index}): ` +
            `${String(e).slice(0, 100)}`,
        );
        continue;
      }

      // 鈹€鈹€ 璁＄畻琛屽彿鑼冨洿 鈹€鈹€
      const beforeMatch = input.slice(0, match.index);
      const startLine = (beforeMatch.match(/\n/g)?.length ?? 0) + 1;
      const endLine =
        startLine + (jsonText.match(/\n/g)?.length ?? 0);

      // 鈹€鈹€ 瑙勮寖鍖栨暟缁?鈹€鈹€
      const items: unknown[] = Array.isArray(parsed) ? parsed : [parsed];

      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (typeof item !== "object" || item === null) {
          diagnostics.push(
            `[${this.name}] JSON 鍧楁潯鐩甗${i}]涓嶆槸瀵硅薄锛岃烦杩嘸,
          );
          continue;
        }

        const obj = item as Record<string, unknown>;

        // 鈹€鈹€ 鎻愬彇鏍稿績瀛楁 鈹€鈹€
        const rawName = typeof obj.name === "string" ? obj.name : "";
        if (!rawName) {
          diagnostics.push(
            `[${this.name}] JSON 鍧楁潯鐩甗${i}]缂哄皯 name 瀛楁锛岃烦杩嘸,
          );
          continue;
        }

        const rawId = typeof obj.id === "string" ? obj.id : "";

        const tags = this._extractTagsFromJson(obj);

        const triggerText =
          typeof obj.trigger === "string" ? obj.trigger : "";

        const steps = this._extractStepsFromJson(obj);

        const expectedOutput =
          typeof obj.expectedOutput === "string"
            ? obj.expectedOutput
            : typeof obj.expected_output === "string"
              ? obj.expected_output
              : undefined;

        // 鈹€鈹€ 缃俊搴﹁绠楋紙瀛楁瀹屾暣鎬ц秺楂樿秺鎺ヨ繎 1.0锛夆攢鈹€
        let baseConfidence = 0.6; // 鍩虹锛欽SON 瑙ｆ瀽鎴愬姛
        if (rawId) baseConfidence += 0.1;
        if (triggerText) baseConfidence += 0.1;
        if (tags.length > 0) baseConfidence += 0.1;
        if (steps.length > 0) baseConfidence += 0.1;
        if (expectedOutput) baseConfidence += 0.05;
        baseConfidence = Math.min(baseConfidence, 1.0);

        candidates.push({
          name: rawId ? `${rawId}: ${rawName}` : rawName,
          tags,
          triggerText,
          steps,
          expectedOutput,
          rawText: jsonText.slice(0, 500),
          strategy: "json-block",
          baseConfidence,
          lineRange: [startLine, endLine],
        });
      }

      diagnostics.push(
        `[${this.name}] JSON block extracted ${items.length} candidates ` +
          `(L${startLine}-L${endLine})`,
      );
    }

    return candidates;
  }

  /**
