   */
  private _extractTagsFromJson(obj: Record<string, unknown>): string[] {
    const raw =
      Array.isArray(obj.triggerTags)
        ? obj.triggerTags
        : Array.isArray(obj.trigger_tags)
          ? obj.trigger_tags
          : Array.isArray(obj.tags)
            ? obj.tags
            : undefined;

    if (!raw) return [];
    return raw.filter((t): t is string => typeof t === "string");
  }

  /**
   * 浠?JSON 瀵硅薄涓彁鍙?steps 瀛楁锛堝閿欓€楀彿鍒嗛殧瀛楃涓诧級銆俓r
