  private _extractStepsFromJson(obj: Record<string, unknown>): string[] {
    const raw =
      Array.isArray(obj.steps)
        ? obj.steps
        : Array.isArray(obj.steps_json)
          ? obj.steps_json
          : obj.steps;

    if (Array.isArray(raw)) {
      return raw.filter((s): s is string => typeof s === "string" && s.trim().length > 0);
    }

    if (typeof raw === "string") {
      // 瀹归敊锛歀LM 鍙兘杈撳嚭閫楀彿鍒嗛殧鐨勫瓧绗︿覆
      return raw
        .split(/[,锛宂/)
        .map((s: string) => s.trim())
        .filter(Boolean);
    }

    return [];
  }

  // ============================================================
  // 绛栫暐 2锛歅0-P9 鏍煎紡鎻愬彇
