   * - steps:
   *   1. 浣跨敤 scanOutputFilesForSkills 鎵弿 ...
   *   2. 璋冪敤 extractSkillsFromMarkdown ...
   * ```
   *
   * 瀹炵幇璺嚎锛歕r
   * 1. 鎸?heading锛?# / ###锛夊皢鏂囨。鎷嗗垎涓烘钀絓r
   * 2. 杩囨护鍑烘爣棰樺尮閰?P_NUMBER_RE 鐨勬钀絓r
   * 3. 鍦ㄦ钀戒綋涓彁鍙?triggerTags锛堟暟缁勶級銆乼rigger 鏂囨湰銆乻teps锛堝垪琛ㄩ」锛塡r
   * 4. 鏍￠獙 steps.length >= minStepsForP0P9
   * 5. confidence = 0.6鈥?.85锛堝瓧娈靛畬鏁存€х嚎鎬ф彃鍊硷級
   *    - 鏈?id/name/tags/steps 鈫?0.85
   *    - 鏈?name/tags/steps 鈫?0.6
   *    - 缂?tags 鈫?0.4
   *
   * @param input       - Markdown 鏂囨湰
   * @param diagnostics - 璇婃柇淇℃伅绱姞鍣╘r
   * @param opts        - 瀹屾暣閫夐」
   * @returns 鍊欓€夊垪琛╘r
   */
  private _extractP0P9Format(
    input: string,
    diagnostics: string[],
    opts: Required<MarkdownExtractorOptions>,
  ): SkillTemplateCandidate[] {
    const candidates: SkillTemplateCandidate[] = [];

    // 鈹€鈹€ 鎸?heading 鎷嗘锛堜粎闄?opts.headingLevels 鎸囧畾鐨勫眰绾э級鈹€鈹€
    const sections = this._splitByHeadings(input, opts.headingLevels);

    for (const section of sections) {
      // 妫€鏌?heading 鏄惁鍖归厤 P 缂栧彿
      const pMatch = MarkdownPatternExtractor.P_NUMBER_RE.exec(
        section.heading,
      );
      if (!pMatch) continue;

      const body = section.body;

      // 鈹€鈹€ 鎻愬彇 triggerTags 鈹€鈹€
      const tags = this._extractTagsFromPNSection(body);

      // 鈹€鈹€ 鎻愬彇 trigger 鈹€鈹€
      const triggerText = this._extractTriggerFromPNSection(body);

      // 鈹€鈹€ 鎻愬彇 steps 鈹€鈹€
      const steps = this._extractStepsFromPNSection(body);

      // 鈹€鈹€ 鎻愬彇 expectedOutput 鈹€鈹€
      const expectedOutput = this._extractExpectedOutputFromPNSection(body);

      // 鈹€鈹€ 鏍￠獙姝ラ鏁?鈹€鈹€
      if (steps.length < opts.minStepsForP0P9) {
        diagnostics.push(
          `[${this.name}] P-number section "${section.heading}" ` +
            `steps (${steps.length}) < min ${opts.minStepsForP0P9}锛岃烦杩?` +
            `(L${section.startLine}-L${section.endLine})`,
        );
        continue;
      }

      // 鈹€鈹€ 缃俊搴﹁绠楋紙瀛楁瀹屾暣鎬х嚎鎬ф彃鍊硷級鈹€鈹€
      let baseConfidence = 0.4; // 鍩虹锛歅 缂栧彿鍛戒腑
      if (triggerText) baseConfidence += 0.15;
      if (tags.length > 0) baseConfidence += 0.15;
      if (steps.length >= 3) baseConfidence += 0.15;
      if (expectedOutput) baseConfidence += 0.1;
      baseConfidence = Math.min(baseConfidence, 0.85);

      const displayName = `P${pMatch[1]}:${section.heading.replace(/^P\d+[\s:锛氣€擻\-鈥揮*/, "")}`;

      candidates.push({
        name: displayName.slice(0, 120),
        tags,
        triggerText,
        steps,
        expectedOutput,
        rawText: body.slice(0, 500),
        strategy: "p0-p9",
        baseConfidence,
        lineRange: [section.startLine, section.endLine],
      });

      diagnostics.push(
        `[${this.name}] P-number section "${section.heading}" ` +
          `鈫?candidate "${displayName.slice(0, 40)}" ` +
          `(conf=${baseConfidence.toFixed(2)}, L${section.startLine}-L${section.endLine})`,
      );
    }

    return candidates;
  }

  /**
   * 浠?P 缂栧彿娈佃惤鐨?body 涓彁鍙?triggerTags銆俓r
   * 鍖归厤 "Tags:" / "triggerTags:" / "- triggerTags: [...]" 绛夋牸寮忋€俓r
   */
  private _extractTagsFromPNSection(body: string): string[] {
    // 鏍煎紡 1: "Tags: tag1, tag2, tag3"
    const lineMatch = body.match(
      /(?:triggerTags|trigger_tags|tags?)[\s:锛歖+(.+)/i,
    );
    if (lineMatch) {
      const raw = lineMatch[1].trim();
      // 鍘绘帀鏂规嫭鍙穃r
      const cleaned = raw.replace(/^\[|\]$/g, "");
      return cleaned
        .split(/[,锛屻€乗\s]+/)
        .map((t) => t.trim())
        .filter(Boolean);
    }

    // 鏍煎紡 2: "- triggerTags: [...]" 鍒楄〃椤筡r
    const listMatch = body.match(
      /^[\t ]*[-*+]\s*(?:triggerTags|trigger_tags|tags?)[\s:锛歖+(.+)/im,
    );
    if (listMatch) {
      const raw = listMatch[1].trim();
      const cleaned = raw.replace(/^\[|\]$/g, "");
      return cleaned
        .split(/[,锛屻€乗\s]+/)
        .map((t) => t.trim())
        .filter(Boolean);
    }

    return [];
  }

  /**
   * 浠?P 缂栧彿娈佃惤鐨?body 涓彁鍙?trigger 鏂囨湰銆俓r
   */
  private _extractTriggerFromPNSection(body: string): string {
    // 鏍煎紡 1: "Trigger: xxx"
    const lineMatch = body.match(/Trigger[\s:锛歖+(.+)/im);
    if (lineMatch) return lineMatch[1].trim();

    // 鏍煎紡 2: "- trigger: xxx" 鍒楄〃椤筡r
    const listMatch = body.match(
      /^[\t ]*[-*+]\s*trigger[\s:锛歖+(.+)/im,
    );
    if (listMatch) return listMatch[1].trim();

    return "";
  }

  /**
   * 浠?P 缂栧彿娈佃惤鐨?body 涓彁鍙?steps 鍒楄〃銆俓r
   * 鏀寔澶氱鏍煎紡锛氱紪鍙峰垪琛ㄣ€丷ecipe/Steps 鑺傘€乥ullet 鍒楄〃銆俓r
   */
  private _extractStepsFromPNSection(body: string): string[] {
    // 鏍煎紡 1: "Recipe:" / "Steps:" 鑺傚悗鐨?bullet 鍒楄〃
    const recipeMatch = body.match(
      /(?:Recipe|Steps?|\u6b65\u9aa4|\u6d41\u7a0b)[\s:\u3000-\u303f\uff00-\uffef]+(?:\r?\n)?([\s\S]*?)(?:\r?\n(?:#{1,3}\s|\r?\n)|$)/i,
    );
    if (recipeMatch) {
      const recipeContent = recipeMatch[1];
      // 鎻愬彇缂栧彿鍒楄〃椤筡r
      const numberedItems = recipeContent.match(
        /^[\t ]*(?:\d+[.銆?\]]\s*)(.+)/gm,
      );
      if (numberedItems && numberedItems.length > 0) {
        return numberedItems
          .map((s) => s.replace(/^[\t ]*\d+[.銆?\]]\s*/, "").trim())
          .filter(Boolean);
      }
      // 鎻愬彇 bullet 鍒楄〃椤筡r
      const bulletItems = recipeContent.match(/^[\t ]*[-*+]\s*(.+)/gm);
      if (bulletItems && bulletItems.length > 0) {
        return bulletItems
          .map((s) => s.replace(/^[\t ]*[-*+]\s*/, "").trim())
          .filter(Boolean);
      }
    }

    // 鏍煎紡 2: 鐩存帴鍦ㄦ钀戒腑鐨勭紪鍙峰垪琛紙濡?"1. xxx\n2. yyy"锛塡r
    const numberedGlobal = body.match(
      /^[\t ]*(?:\d+[.銆?\]]\s*)(.+)/gm,
    );
    if (numberedGlobal && numberedGlobal.length >= 2) {
      return numberedGlobal
        .map((s) => s.replace(/^[\t ]*\d+[.銆?\]]\s*/, "").trim())
        .filter(Boolean);
    }

    // 鏍煎紡 3: bullet 鍒楄〃
    const bulletGlobal = body.match(/^[\t ]*[-*+]\s*(.+)/gm);
    if (bulletGlobal && bulletGlobal.length >= 2) {
      return bulletGlobal
        .map((s) => s.replace(/^[\t ]*[-*+]\s*/, "").trim())
        .filter(Boolean);
    }

    return [];
  }

  /**
   * 浠?P 缂栧彿娈佃惤鐨?body 涓彁鍙?expectedOutput銆俓r
   */
  private _extractExpectedOutputFromPNSection(
    body: string,
  ): string | undefined {
    // 鏍煎紡 1: "expectedOutput: xxx"
    const lineMatch = body.match(
      /(?:expectedOutput|expected_output|Expected[\s]*Output)[\s:锛歖+(.+)/i,
    );
    if (lineMatch) return lineMatch[1].trim();

    // 鏍煎紡 2: "- expectedOutput: xxx" 鍒楄〃椤筡r
    const listMatch = body.match(
      /^[\t ]*[-*+]\s*(?:expectedOutput|expected_output)[\s:锛歖+(.+)/im,
    );
    if (listMatch) return listMatch[1].trim();

    // 鏍煎紡 3: "Condition:" 鑺傦紙鏃х増绾﹀畾锛塡r
    const conditionMatch = body.match(
      /Condition[\s:\u3000-\u303f\uff00-\uffef]+(?:\r?\n)?([\s\S]*?)(?:\r?\n(?:#{1,3}\s|\r?\n)|$)/i,
    );
    if (conditionMatch) {
      const conditions = conditionMatch[1]
        .split("\n")
        .map((c) => c.trim())
        .filter(Boolean)
        .join("; ");
      if (conditions) return conditions;
    }

    return undefined;
  }

  // ============================================================
  // 绛栫暐 3锛氭ā寮忔钀芥彁鍙栵紙鍚彂寮忥級
  // ============================================================

  /**
   * 绛栫暐 3 鈥斺€?瀵硅嚜鐢辨牸寮忕殑 Markdown 娈佃惤杩涜鍚彂寮忔ā寮忔彁鍙栥€俓r
   *
   * 褰撴钀戒笉绗﹀悎 JSON 鎴?P0-P9 鏍煎紡鏃讹紝閲囩敤鍚彂寮忚鍒欏垽鏂璡r
   * 鍏舵槸鍚﹀寘鍚妧鑳芥ā鏉跨殑鍏抽敭淇″彿锛歕r
   *
   * 鍚彂寮忚鍒欙紙HeuristicRule 椋庢牸锛屽弬瑙?pattern.ts 搂9锛夛細
   * - 瑙勫垯 A銆孴RIGGER 淇″彿銆嶏細娈佃惤鍖呭惈 trigger* 瀛楁澹版槑 鈫?confidence +0.2
   * - 瑙勫垯 B銆孲TEPS 淇″彿銆嶏細娈佃惤鍖呭惈 2+ 姝ラ鎻忚堪锛圠IST_ITEM_RE + 琛屼负鍔ㄨ瘝锛夆啋 confidence +0.3
   * - 瑙勫垯 C銆孴AGS 淇″彿銆嶏細娈佃惤鍖呭惈 tag 鍒楄〃锛堥€楀彿鍒嗛殧鎴栨暟缁勬牸寮忥級鈫?confidence +0.15
   * - 瑙勫垯 D銆孫UTPUT 淇″彿銆嶏細娈佃惤鍖呭惈 expectedOutput / outputFile 鈫?confidence +0.1
   * - 瑙勫垯 E銆孖D 淇″彿銆嶏細娈佃惤鍖呭惈 "id:" 鎴?"skill-p" 妯″紡 鈫?confidence +0.1
   *
   * 鍩虹 confidence = 0.1锛岀疮璁″悗 cap 鍦?0.5銆俓r
   *
   * @param input       - Markdown 鏂囨湰
   * @param diagnostics - 璇婃柇淇℃伅绱姞鍣╘r
   * @param opts        - 瀹屾暣閫夐」
   * @returns 鍊欓€夊垪琛╘r
   */
  private _extractPatternParagraphs(
    input: string,
    diagnostics: string[],
    opts: Required<MarkdownExtractorOptions>,
  ): SkillTemplateCandidate[] {
    const candidates: SkillTemplateCandidate[] = [];

    const sections = this._splitByHeadings(input, opts.headingLevels);

    for (const section of sections) {
      // 璺宠繃宸茶绛栫暐 1/2 澶勭悊鐨勬钀斤紙P 缂栧彿鍖归厤鐨勶級
      if (MarkdownPatternExtractor.P_NUMBER_RE.test(section.heading)) continue;

      const body = section.body;
      if (body.length < 30) continue; // 澶煭鐨勬钀借烦杩嘰r

      // 鈹€鈹€ 搴旂敤 5 鏉″惎鍙戝紡瑙勫垯绱Н confidence 鈹€鈹€
      let confidence = 0.1; // 鍩虹

      // 瑙勫垯 A銆孴RIGGER 淇″彿銆? 娈佃惤鍖呭惈 trigger* 瀛楁澹版槑
      if (MarkdownPatternExtractor.TRIGGER_FIELD_RE.test(body)) {
        confidence += 0.2;
      }

      // 瑙勫垯 B銆孲TEPS 淇″彿銆? 娈佃惤鍖呭惈 2+ 姝ラ鎻忚堪
      const stepCount = this._countStepSignals(body);
      if (stepCount >= 2) {
        confidence += 0.3;
      }

      // 瑙勫垯 C銆孴AGS 淇″彿銆? 娈佃惤鍖呭惈 tag 鍒楄〃
      const hasTags = this._hasTagListSignal(body);
      if (hasTags) {
        confidence += 0.15;
      }

      // 瑙勫垯 D銆孫UTPUT 淇″彿銆? 娈佃惤鍖呭惈 expectedOutput / outputFile
      if (/expectedOutput|expected_output|outputFile|output_file/i.test(body)) {
        confidence += 0.1;
      }

      // 瑙勫垯 E銆孖D 淇″彿銆? 娈佃惤鍖呭惈 "id:" 鎴?"skill-p" 妯″紡
      if (/(?:^|[\s(])id[\s]*[锛?]|skill-p\d+/i.test(body)) {
        confidence += 0.1;
      }

      // Cap at 0.5
      confidence = Math.min(confidence, 0.5);

      // 鈹€鈹€ 缃俊搴﹁繃婊?鈹€鈹€
      if (confidence < opts.minConfidence) continue;

      // 鈹€鈹€ 灏濊瘯浠?body 鎻愬彇鍩烘湰瀛楁 鈹€鈹€
      const tags = this._extractTagsFromPatternParagraph(body);
      const triggerText = this._extractTriggerFromPatternParagraph(body);
      const steps = this._extractStepsFromPatternParagraph(body);

      const displayName =
        section.heading ||
        body.split("\n")[0]?.replace(/^#+\s*/, "").slice(0, 60) ||
        "Unnamed pattern";

      candidates.push({
        name: displayName.slice(0, 120),
        tags,
        triggerText,
        steps,
        rawText: body.slice(0, 500),
        strategy: "pattern-paragraph",
        baseConfidence: confidence,
        lineRange: [section.startLine, section.endLine],
      });

      diagnostics.push(
        `[${this.name}] pattern-paragraph heuristic: ` +
          `"${displayName.slice(0, 40)}" (conf=${confidence.toFixed(2)}, ` +
          `L${section.startLine}-L${section.endLine})`,
      );
    }

    return candidates;
  }

  /**
   * 缁熻娈佃惤涓殑姝ラ淇″彿鏁伴噺銆俓r
   * 鍖归厤锛氬垪琛ㄩ」 + 琛屼负鍔ㄨ瘝锛圫TEP_ACTION_RE锛夈€俓r
   */
  private _countStepSignals(body: string): number {
    const lines = body.split("\n");
    let count = 0;
    for (const line of lines) {
      if (
        MarkdownPatternExtractor.LIST_ITEM_RE.test(line) &&
        MarkdownPatternExtractor.STEP_ACTION_RE.test(line)
      ) {
        count++;
      }
    }
    return count;
  }

  /**
   * 妫€娴嬫钀戒腑鏄惁瀛樺湪鏍囩鍒楄〃淇″彿銆俓r
   * 鍖归厤锛氶€楀彿鍒嗛殧鐨勬爣绛惧垪琛ㄣ€佹柟鎷彿鏁扮粍銆乗

 琛屻€俓r
   */
  private _hasTagListSignal(body: string): boolean {
    // "Tags: xxx" 鎴?"- triggerTags: [...]"
    if (/(?:tags?|triggerTags|trigger_tags)[\s:锛歖+/i.test(body)) {
      return true;
    }
    // 鏂规嫭鍙锋暟缁勬牸寮?["tag1", "tag2"]
    if (/\[["'].+["']\]/.test(body)) {
      return true;
    }
    return false;
  }

  /**
   * 浠庤嚜鐢辨牸寮忔钀戒腑鎻愬彇鏍囩銆俓r
   */
  private _extractTagsFromPatternParagraph(body: string): string[] {
    const match = body.match(
      /(?:tags?|triggerTags|trigger_tags)[\s:锛歖+(.+)/i,
    );
    if (!match) return [];
    const raw = match[1].trim().replace(/^\[|\]$/g, "");
    return raw
      .split(/[,锛屻€乗\s]+/)
      .map((t) => t.trim())
      .filter((t) => t.length > 0);
  }

  /**
   * 浠庤嚜鐢辨牸寮忔钀戒腑鎻愬彇 trigger 鏂囨湰銆俓r
   */
  private _extractTriggerFromPatternParagraph(body: string): string {
    const match = body.match(/trigger[\s:锛歖+(.+)/im);
    return match ? match[1].trim() : "";
  }

  /**
   * 浠庤嚜鐢辨牸寮忔钀戒腑鎻愬彇姝ラ鍒楄〃銆俓r
   */
  private _extractStepsFromPatternParagraph(body: string): string[] {
    const lines = body.split("\n");
    return lines
      .filter(
        (line) =>
          MarkdownPatternExtractor.LIST_ITEM_RE.test(line) &&
          MarkdownPatternExtractor.STEP_ACTION_RE.test(line),
      )
      .map((line) => line.replace(MarkdownPatternExtractor.LIST_ITEM_RE, "").trim())
      .filter(Boolean);
  }

