  /**
   * 绛栫暐 4 鈥斺€?灏嗘暣绡囨枃妗ｄ綔涓轰竴涓ā寮忓€欓€夈€俓r
   *
   * 褰撴棩蹇楁枃浠舵湁瀹炶川鎬у唴瀹逛絾涓嶇鍚堜换浣曠粨鏋勫寲鏍煎紡鏃跺惎鐢ㄣ€俓r
   * confidence 鍥哄畾涓?0.2鈥斺€旇繖鏄渶浣庤川閲忕殑鍊欓€夛紝
   * 浣嗘瘮瀹屽叏涓㈠純瑕佸ソ鈥斺€旇帿濞滃彲浠ュ湪绗?2 灞傝涔夎鍐充腑灏嗗叾杩囨护銆俓r
   *
   * @param input       - Markdown 鏂囨湰
   * @param diagnostics - 璇婃柇淇℃伅绱姞鍣╘r
   * @returns 鍊欓€夛紙鎴?null鈥斺€旇嫢鏂囦欢杩囩煭锛塡r
   */
  private _extractFullFileFallback(
    input: string,
    diagnostics: string[],
  ): SkillTemplateCandidate | null {
    const lines = input.split("\n");
    // 灏戜簬 5 琛岀殑鏂囦欢鏀惧純
    if (lines.length < 5) return null;

    const firstLine = lines[0].replace(/^#+\s*/, "").slice(0, 120);

    return {
      name: firstLine || "Untitled pattern",
      tags: [],
      triggerText: "",
      steps: [],
      rawText: input,
      strategy: "full-file",
