  /**
   * 鎸夋寚瀹氬眰绾х殑 Markdown 鏍囬灏嗘枃鏈媶鍒嗕负娈佃惤銆俓r
   *
   * @param input  - Markdown 鏂囨湰
   * @param levels - 鏍囬灞傜骇鍒楄〃锛堝 [2, 3]锛塡r
   * @returns 娈佃惤鏁扮粍锛屾瘡涓钀藉惈 heading銆乥ody銆佽鑼冨洿
   */
  private _splitByHeadings(
    input: string,
    levels: number[],
  ): { heading: string; body: string; startLine: number; endLine: number }[] {
    const sections: {
      heading: string;
      body: string;
      startLine: number;
      endLine: number;
    }[] = [];

    const lines = input.split("\n");
    const headingRe = new RegExp(
      `^(${levels.map((l) => `#{${l}}`).join("|")})\\s+(.+)$`,
    );

    let currentHeading = "";
    let currentBody = "";
    let currentStartLine = 1;

    for (let i = 0; i < lines.length; i++) {
      const m = headingRe.exec(lines[i]);
      if (m) {
        // 閬囧埌鏂版爣棰?鈫?淇濆瓨鍓嶄竴娈礬r
        if (currentHeading) {
          sections.push({
            heading: currentHeading,
            body: currentBody.trim(),
            startLine: currentStartLine,
            endLine: i,
          });
        }
        currentHeading = m[2]; // 鏍囬鏂囨湰锛堜笉鍚?# 鍓嶇紑锛塡r
        currentBody = "";
        currentStartLine = i + 1;
      } else if (currentHeading) {
        currentBody += lines[i] + "\n";
      }
    }

    // 淇濆瓨鏈€鍚庝竴娈礬r
    if (currentHeading) {
      sections.push({
        heading: currentHeading,
        body: currentBody.trim(),
        startLine: currentStartLine,
        endLine: lines.length,
      });
    }

    return sections;
  }

