//   - AgentFactoryRegistry 鈫?Agent 宸ュ巶娉ㄥ唽涓庡彂鐜癨n//   - SkillRegistry 鈫?鎶€鑳芥ā鏉挎敞鍐屼笌鏌ヨ
//   - PatternExtractorRegistry 鈫?鎻愬彇鍣ㄥ疄渚嬫敞鍐屼笌妫€绱n//
// @layer 缂栨帓灞傦紙Orchestration Layer锛塡n// @dependency extractor.ts锛圥atternExtractor 鎺ュ彛 + PatternKind 鏋氫妇锛塡n// ============================================================

import type { PatternExtractor } from "./extractor.js";
import { PatternKind } from "./extractor.js";

// ============================================================
// 搂1 娉ㄥ唽琛ㄧ被
// ============================================================

/**
 * PatternExtractorRegistry 鈥斺€?妯″紡鎻愬彇鍣ㄦ敞鍐屼腑蹇冦€俓n *
 * 绠＄悊鎵€鏈?PatternExtractor 瀹炰緥鐨勬敞鍐屻€佹敞閿€鍜屾煡璇€俓n * 缁存姢涓夊眰绱㈠紩缁撴瀯锛屾敮鎸?O(1) 鍚嶇О鏌ユ壘鍜岄珮鏁堜氦闆嗘煡璇細
 *
 * ```
 * 绱㈠紩缁撴瀯锛歕n *   _byName:      Map<name, PatternExtractor>         鈥斺€?鍚嶇О 鈫?瀹炰緥
 *   _byLanguage:  Map<language, Set<name>>            鈥斺€?璇█ 鈫?鍚嶇О闆嗗悎
 *   _byKind:      Map<PatternKind, Set<name>>         鈥斺€?绉嶇被 鈫?鍚嶇О闆嗗悎
 *
 * 鏌ヨ娴佺▼锛坬ueryByLanguageAndKind锛夛細
 *   langNames  鈫?_byLanguage.get(language) ?? _byLanguage.get("*")
 *   kindNames  鈫?_byKind.get(kind)
 *   鍙栦氦闆?     鈫?瑙ｆ瀽涓?PatternExtractor[] 杩斿洖
 * ```
 *
 * **璁捐鍔ㄦ満**锛歕n * - 鏂板鎻愬彇鍣ㄥ彧闇€ `register()` 涓€娆★紝娑堣垂鏂归€氳繃 `queryBy*` 鍔ㄦ€佸彂鐜癨n * - 娑堣垂鏂规棤闇€ `import` 鍏蜂綋鎻愬彇鍣ㄥ疄鐜扮被锛岄潰鍚戞敞鍐岃〃缂栫▼
 * - 鏀寔绮剧‘鏌ヨ鍜岄€氶厤鏌ヨ锛圽

 琛ㄧず閫氱敤璇█锛塡n * - 娉ㄥ唽鍚屽悕鎻愬彇鍣ㄦ椂鑷姩瑕嗙洊骞堕噸寤虹储寮昞n *
 * **鍏稿瀷浣跨敤娴佺▼**锛歕n * ```typescript
 * const registry = new PatternExtractorRegistry();
 *
 * // 鈶?娉ㄥ唽鎻愬彇鍣╘n * registry.register(new AstPatternExtractor());
 * registry.register(new RegexPatternExtractor());
 *
 * // 鈶?鎸夎瑷€ + 绉嶇被鏌ヨ
 * const extractors = registry.queryByLanguageAndKind(
 *   "typescript",
 *   PatternKind.Structural,
 * );
 *
 * // 鈶?閬嶅巻鎵ц鎻愬彇
 * for (const ext of extractors) {
 *   const result = ext.extract(sourceCode);
 *   // ...
 * }
 * ```
 *
 * @design P06 鈥?娉ㄥ唽琛ㄦ槧灏勬ā寮忥紙缁ф壙鑷瘝椤圭洰 AgentFactoryRegistry / SkillRegistry锛塡n * @usedBy PatternExtractorPipeline 鈥?绠＄嚎鍦?ExtractStage 涓煡璇㈡敞鍐岃〃鑾峰彇鍖归厤鎻愬彇鍣╘n * @usedBy ExtractorFactory 鈥?宸ュ巶鍦ㄦ瀯閫犳椂鑷姩娉ㄥ唽娉ㄥ叆鐨勬彁鍙栧櫒鍒楄〃
 * @usedBy PatternScanner 瀹炵幇绫?鈥?鎵弿鍣ㄦ寜 language + targetKinds 鏌ヨ娉ㄥ唽琛╘n *
 * @example
 * ```typescript
 * // 鈹€鈹€ 娉ㄥ唽 鈹€鈹€
 * registry.register(astExtractor);
 * registry.registerAll([regexExtractor, heuristicExtractor]);
 *
 * // 鈹€鈹€ 鏌ヨ 鈹€鈹€
 * registry.queryByLanguageAndKind("typescript", PatternKind.Structural);
 * // 鈫?[astExtractor]锛堣繑鍥炲尮閰嶇殑鎻愬彇鍣ㄦ暟缁勶級
 *
 * registry.queryByTags(["typescript", "python"]);
 * // 鈫?[astExtractor, regexExtractor, heuristicExtractor]
 *
 * // 鈹€鈹€ 鑾峰彇 / 鍒楀嚭 鈹€鈹€
 * registry.get("ast-extractor");
 * // 鈫?astExtractor 瀹炰緥
 *
 * registry.list();
 * // 鈫?[astExtractor, regexExtractor, heuristicExtractor]
 *
 * // 鈹€鈹€ 绠＄悊 鈹€鈹€
 * registry.has("ast-extractor"); // 鈫?true
 * registry.size;                 // 鈫?3
 * registry.unregister("ast-extractor"); // 鈫?true
 * registry.clear();
 * ```
 *
 * @since 0.1.0
 */
export class PatternExtractorRegistry {
  /** 鍚嶇О 鈫?鎻愬彇鍣ㄥ疄渚嬫槧灏勶紙涓荤储寮曪級 */
  private readonly _byName: Map<string, PatternExtractor> = new Map();

  /** 璇█ 鈫?鎻愬彇鍣ㄥ悕绉伴泦鍚堟槧灏勶紙"*" 琛ㄧず閫氱敤锛屾敮鎸佷换鎰忚瑷€锛?*/
  private readonly _byLanguage: Map<string, Set<string>> = new Map();

  /** 妯″紡绉嶇被 鈫?鎻愬彇鍣ㄥ悕绉伴泦鍚堟槧灏?*/
  private readonly _byKind: Map<PatternKind, Set<string>> = new Map();

  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  // 搂1.1 娉ㄥ唽
  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 娉ㄥ唽涓€涓彁鍙栧櫒瀹炰緥銆俓n   *
   * 娉ㄥ唽鏃惰嚜鍔ㄥ缓绔嬩笁灞傜储寮曪細
   *   1. `_byName`锛氶€氳繃 `extractor.name` 寤虹珛鍚嶇О 鈫?瀹炰緥鏄犲皠
   *   2. `_byLanguage`锛氶亶鍘?`extractor.supportedLanguages`锛屼负姣忕璇█寤虹珛绱㈠紩
   *   3. `_byKind`锛氶亶鍘?`extractor.supportedKinds`锛屼负姣忕绉嶇被寤虹珛绱㈠紩
   *
   * 鑻ュ凡瀛樺湪鍚屽悕鎻愬彇鍣紙`_byName.has(extractor.name)` 涓?true锛夛紝
   * 鍒欏厛璋冪敤 {@link unregister} 娓呯悊鏃у疄渚嬬殑鍏ㄩ儴绱㈠紩锛屽啀娉ㄥ唽鏂板疄渚嬨€俓n   * 杩欑‘淇濈储寮曚笉浼氭畫鐣欐寚鍚戝凡搴熷純瀹炰緥鐨勫紩鐢ㄣ€俓n   *
   * @param extractor - 寰呮敞鍐岀殑 PatternExtractor 瀹炰緥銆俓n   *   `extractor.name` 蹇呴』涓哄敮涓€鏍囪瘑锛堝瓧姣嶆暟瀛?+ 杩炶瘝绗︼紝濡?"ast-extractor"锛夈€俓n   *   鑻?`supportedLanguages` 鍖呭惈 "*"锛屽垯璇ユ彁鍙栧櫒鍖归厤鎵€鏈夎瑷€鐨勬煡璇€俓n   *
   * @example
   * ```typescript
   * registry.register(new AstPatternExtector());
   * // _byName:     { "ast-extractor" 鈫?AstPatternExtractor }
   * // _byLanguage: { "typescript" 鈫?Set{"ast-extractor"}, "javascript" 鈫?Set{"ast-extractor"}, ... }
   * // _byKind:     { "structural" 鈫?Set{"ast-extractor"}, "behavioral" 鈫?Set{"ast-extractor"}, ... }
   * ```
   */
  register(extractor: PatternExtractor): void {
    const name = extractor.name;

    // 鍚屽悕鎻愬彇鍣ㄥ凡瀛樺湪 鈫?鍏堟竻鐞嗘棫绱㈠紩鍐嶈鐩朶n    // 纭繚涓嶄細娈嬬暀鎸囧悜宸插簾寮冨疄渚嬬殑寮曠敤
    if (this._byName.has(name)) {
      this.unregister(name);
    }

    // 鈶?娉ㄥ唽鍚嶇О绱㈠紩
    this._byName.set(name, extractor);

    // 鈶?娉ㄥ唽璇█绱㈠紩
    //    閬嶅巻 supportedLanguages锛屼负姣忕璇█寤虹珛鍊掓帓绱㈠紩
    for (const lang of extractor.supportedLanguages) {
      const names = this._byLanguage.get(lang);
      if (names) {
        names.add(name);
      } else {
        this._byLanguage.set(lang, new Set([name]));
      }
    }

    // 鈶?娉ㄥ唽绉嶇被绱㈠紩
    //    閬嶅巻 supportedKinds锛屼负姣忕妯″紡绉嶇被寤虹珛鍊掓帓绱㈠紩
    for (const kind of extractor.supportedKinds) {
      const names = this._byKind.get(kind);
      if (names) {
        names.add(name);
      } else {
        this._byKind.set(kind, new Set([name]));
      }
    }
  }

  /**
   * 鎵归噺娉ㄥ唽澶氫釜鎻愬彇鍣ㄥ疄渚嬨€俓n   *
   * 閬嶅巻杈撳叆鍒楄〃锛屼緷娆¤皟鐢?{@link register} 鏂规硶銆俓n   * 鎵归噺娉ㄥ唽鐨勮涔夌瓑鍚屼簬閫愪釜娉ㄥ唽锛歕n   * - 鑻ュ垪琛ㄤ腑瀛樺湪鍚屽悕鎻愬彇鍣紝鍚庢敞鍐岀殑瑕嗙洊鍏堟敞鍐岀殑
   * - 寮傚父涓嶄細闃绘柇鍚庣画鎻愬彇鍣ㄧ殑娉ㄥ唽锛堣皟鐢ㄦ柟璐熻矗寮傚父澶勭悊锛塡n   *
   * @param extractors - 寰呮敞鍐岀殑鎻愬彇鍣ㄥ疄渚嬫暟缁勩€傛暟缁勪负绌烘椂鏃犳搷浣溿€俓n   *
   * @example
   * ```typescript
   * registry.registerAll([
   *   new AstPatternExtractor(),
   *   new RegexPatternExtractor(),
   *   new HeuristicPatternExtractor(),
   * ]);
   * // 娉ㄥ唽琛ㄧ幇鍦ㄥ寘鍚笁涓彁鍙栧櫒
   * ```
   */
  registerAll(extractors: PatternExtractor[]): void {
    for (const extractor of extractors) {
      this.register(extractor);
    }
