} from "@cortex/shared";

/** 閿佽秴鏃堕粯璁ゅ€硷細30s銆侫gent 宕╂簝鍚庨攣鑷姩鍥炴敹 */
const DEFAULT_LOCK_TIMEOUT_MS = 30_000;

/** 鍛ㄦ湡鎬ф竻鐞嗚繃鏈熼攣闂撮殧 */
const CLEANUP_INTERVAL_MS = 60_000;

interface LockEntry {
  type: LockType;
  holders: Set<string>;
  acquiredAt: number;
}

/**
 * FileLockManager 鈥斺€?鏂囦欢绾ц鍐欓攣
 * 鍐欓攣鎺掓枼鎵€鏈夛紝璇婚攣鍏卞瓨銆侺2/L3 纭绛夊緟鏈熼棿涓嶆寔閿併€俓n * 鍐呯疆閿佽秴鏃跺洖鏀讹細Agent 宕╂簝鍚?30s 鑷姩閲婃斁杩囨湡閿併€俓n *
 * @implements ILifecycle 鈥?閫氳繃 BaseLifecycle 鑾峰緱鏍囧噯鐢熷懡鍛ㄦ湡绠＄悊
 * @fix M4 鈥?init() 涓惎鍔ㄥ懆鏈熸€ф竻鐞嗗畾鏃跺櫒锛岄槻姝㈡棤鐣屽唴瀛樺闀裤€俓n * @fix S4-05 鈥?dispose() 鍚庤缃?_disposed 鏍囪锛屽悗缁搷浣滅珛鍗虫姏閿欙紝闃叉鍍靛案閿併€俓n * @fix H-03 鈥?console.warn 鏇挎崲涓?PipelineObserver emit锛屾秷闄よ８ console銆俓n */
export class FileLockManager extends BaseLifecycle {
  private locks = new Map<string, LockEntry>();
  private readonly timeoutMs: number;
  private _cleanupTimer: ReturnType<typeof setInterval> | null = null;
  private _disposed = false;
  private readonly _observer?: IPipelineObserver;

  constructor(
    timeoutMs: number = DEFAULT_LOCK_TIMEOUT_MS,
    observer?: IPipelineObserver,
  ) {
    super();
    this.timeoutMs = timeoutMs;
    this._observer = observer;
  }

  // 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲
  // ILifecycle 瀹炵幇锛堥€氳繃 BaseLifecycle锛塡n  // 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲

  protected async doInit(): Promise<void> {
    this._cleanupTimer = setInterval(() => {
      this.cleanStaleLocks();
    }, CLEANUP_INTERVAL_MS);
    // 鍏佽 Node.js 鍦ㄤ粎鍓╂瀹氭椂鍣ㄦ椂閫€鍑鸿繘绋媆n    if (this._cleanupTimer && typeof this._cleanupTimer === "object" && "unref" in this._cleanupTimer) {
      this._cleanupTimer.unref();
    }
  }

  protected doDispose(): void {
    if (this._cleanupTimer) {
      clearInterval(this._cleanupTimer);
      this._cleanupTimer = null;
    }
    this.locks.clear();
    this._disposed = true;
  }

  // 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲
  // 閿佹搷浣淺n  // 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲

  /**
   * 灏濊瘯鑾峰彇閿併€俬olderId 閫氬父涓?Agent 瀹炰緥 ID銆俓n   * 杩斿洖 true 琛ㄧず鑾峰彇鎴愬姛銆俓n   * 閬囧埌杩囨湡閿佹椂鑷姩鍥炴敹鍚庨噸鏂板皾璇曡幏鍙栥€俓n   */
  acquire(filePath: string, type: LockType, holderId: string): boolean {
    this._checkDisposed("acquire");
    // 鍏堟竻鐞嗚鏂囦欢涓婄殑杩囨湡閿乗n    this._cleanStaleLock(filePath);

    const existing = this.locks.get(filePath);
    if (!existing) {
      this.locks.set(filePath, {
        type,
        holders: new Set([holderId]),
        acquiredAt: Date.now(),
      });
      return true;
    }
    // 鍐欓攣鎺掓枼涓€鍒嘰n    if (existing.type === LockType.Write) return false;
    // 璇婚攣鎺掓枼鍐欓攣
    if (type === LockType.Write && existing.type === LockType.Read) return false;
    // 璇婚攣鍏卞瓨锛堝悓绫诲瀷锛夛紝缁湡浠ヤ繚鎸佹椿璺僜n    if (type === LockType.Read && existing.type === LockType.Read) {
      existing.holders.add(holderId);
      existing.acquiredAt = Date.now();
      return true;
    }
    return false;
  }

  /** 閲婃斁閿?*/
  release(filePath: string, holderId: string): void {
    this._checkDisposed("release");
    const existing = this.locks.get(filePath);
    if (!existing) return;
    existing.holders.delete(holderId);
    if (existing.holders.size === 0) {
      this.locks.delete(filePath);
    }
  }

  /** 鍒锋柊閿佹椿璺冩椂闂达紙鎸侀攣 Agent 蹇冭烦锛岄槻姝㈣璇洖鏀讹級 */
  touch(filePath: string, holderId: string): void {
    this._checkDisposed("touch");
    const existing = this.locks.get(filePath);
    if (existing?.holders.has(holderId)) {
      existing.acquiredAt = Date.now();
    }
  }

  /** 妫€鏌ユ槸鍚﹁閿侊紙涓嶅惈杩囨湡閿侊級 */
  isLocked(filePath: string): boolean {
    this._checkDisposed("isLocked");
    this._cleanStaleLock(filePath);
    return this.locks.has(filePath);
  }

  /** 妫€鏌?holder 鏄惁鎸佹湁鏌愭枃浠剁殑閿?*/
  holds(filePath: string, holderId: string): boolean {
    this._checkDisposed("holds");
    return this.locks.get(filePath)?.holders.has(holderId) ?? false;
  }

  /** 鍏ㄥ眬娓呯悊鎵€鏈夎繃鏈熼攣锛堢敱鍛ㄦ湡鎬у畾鏃跺櫒璋冪敤锛?*/
  cleanStaleLocks(): number {
    if (this._disposed) return 0;
    const now = Date.now();
    let cleaned = 0;
    for (const [filePath, entry] of this.locks) {
      if (now - entry.acquiredAt > this.timeoutMs) {
        this.locks.delete(filePath);
        cleaned++;
      }
    }
    if (cleaned > 0) {
      this._observer?.emit({
        type: PipelineEventType.InfraFileLockExpiredReclaimed,
        priority: PipelinePriority.NORMAL,
        payload: { count: cleaned, detail: `鍥炴敹 ${cleaned} 涓繃鏈熼攣` },
        timestamp: Date.now(),
        notificationType: "FYI",
      });
    }
    return cleaned;
  }

  /** 鍐呴儴锛氭鏌ユ槸鍚﹀凡閲婃斁锛屾槸鍒欐姏閿?*/
  private _checkDisposed(method: string): void {
    if (this._disposed) {
      throw new Error(`FileLockManager 宸查噴鏀撅紝鎷掔粷鎿嶄綔: ${method}`);
    }
  }

  /** 鍐呴儴锛氭竻鐞嗙壒瀹氭枃浠朵笂鐨勮繃鏈熼攣 */
  private _cleanStaleLock(filePath: string): void {
    const entry = this.locks.get(filePath);
    if (entry && Date.now() - entry.acquiredAt > this.timeoutMs) {
      const holders = [...entry.holders].join(", ");
      this._observer?.emit({
        type: PipelineEventType.InfraFileLockExpiredReclaimed,
        priority: PipelinePriority.NORMAL,
        payload: {
          count: 1,
          path: filePath,
          holders,
          detail: `閿佽秴鏃跺洖鏀? ${filePath}锛堟寔鏈夎€呭穿婧冿紵holders: ${holders}锛塦,
        },
        timestamp: Date.now(),
        notificationType: "FYI",
      });
      this.locks.delete(filePath);
    }
  }
}

