/**
 * NodeFileSystemAdapter 鈥斺€?IFileSystemAdapter 鐨?Node.js 瀹炵幇銆俓n *
 * 浣跨敤 node:fs 鍜?node:child_process 鎻愪緵鐨勫師鐢?API銆俓n * 鎵€鏈夋柟娉曞悓姝ユ墽琛岋紙Node.js 鏂囦欢绯荤粺 API 鍘熺敓鍚屾锛夛紝杩斿洖 Promise 浠ョ鍚堟帴鍙ｅ绾︺€俓n *
 * @since v2.1 绾宠タ濡插寮哄缓璁細CLI 妗嗘灦鎶借薄鈥斺€旇В鑰?Toolkit 涓?Node.js 鍘熺敓 API銆俓n * @usedBy Toolkit 浣滀负榛樿鏂囦欢绯荤粺閫傞厤鍣ㄣ€俓n */
export class NodeFileSystemAdapter implements IFileSystemAdapter {
  readonly sep: string = path.sep;

  async readFile(filePath: string): Promise<string> {
    return fs.readFileSync(filePath, "utf-8");
  }

  async writeFile(filePath: string, content: string): Promise<void> {
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.writeFileSync(filePath, content, "utf-8");
  }

  async exists(filePath: string): Promise<boolean> {
    return fs.existsSync(filePath);
  }

  async mkdir(dirPath: string): Promise<void> {
    fs.mkdirSync(dirPath, { recursive: true });
  }

  async unlink(filePath: string): Promise<void> {
    fs.unlinkSync(filePath);
  }

  async listDirectory(dirPath: string): Promise<DirectoryEntry[]> {
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });
    return entries.map((e) => ({
      name: e.name,
      isDirectory: e.isDirectory(),
    }));
  }

  async stat(filePath: string): Promise<{ isFile: boolean; isDirectory: boolean }> {
    const s = fs.statSync(filePath);
    return { isFile: s.isFile(), isDirectory: s.isDirectory() };
  }

  async execCommand(command: string, options?: { cwd?: string; timeout?: number }): Promise<string> {
    return execSync(command, {
      cwd: options?.cwd,
      encoding: "utf-8",
      timeout: options?.timeout ?? 60_000,
      maxBuffer: 5 * 1024 * 1024, // 5MB
    });
  }

  async execFile(filePath: string, args: string[], options?: { cwd?: string; timeout?: number }): Promise<string> {
    return execFileSync(filePath, args, {
      cwd: options?.cwd,
      encoding: "utf-8",
      timeout: options?.timeout ?? 15_000,
    });
  }

  cwd(): string {
    return process.cwd();
  }

  resolve(...paths: string[]): string {
    return path.resolve(...paths);
  }
}

