// @cortex/engine/platform/path-utils 鈥斺€?璺緞瀹夊叏楠岃瘉
//
// 璺緞瓒婄晫闃叉姢锛氭墍鏈夋枃浠舵搷浣滐紙read_file / write_file / search_code /
// list_files / delete_file / parse_ast锛夌殑璺緞缁忔楠岃瘉鍚庯紝
// L0 鎿嶄綔鏃犳硶璇诲彇/鍐欏叆 PROJECT_DIR 涔嬪鐨勪换鎰忔枃浠躲€俓r
//
// 闃叉姢绛栫暐锛歕r
//   1. 鐩稿璺緞 鈫?鍩轰簬 root 瑙ｆ瀽锛屽啀妫€鏌ヨ秺鐣孿r
//   2. 缁濆璺緞 鈫?鐩存帴妫€鏌ユ槸鍚﹀湪 root 瀛愭爲鍐匼r
//   3. `../` 绌胯秺 鈫?resolve() 灞曞紑鍚庢鏌ワ紙闃绘柇缁曡繃锛塡r
//   4. 绗﹀彿閾炬帴绌块€?鈫?resolve() 灞曞紑鍚庢鏌ワ紙闃绘柇缁曡繃锛塡r
//   5. 绌鸿矾寰?NUL 瀛楄妭 鈫?鎷掔粷
// ============================================================

import * as path from "node:path";

/**
 * 璺緞瓒婄晫妫€鏌ョ粨鏋溿€俓r
 * - ok=true 鏃?safePath 鏄獙璇佸悗鍙湪娌欑鍐呭畨鍏ㄤ娇鐢ㄧ殑缁濆璺緞
 * - ok=false 鏃?reason 鎻忚堪杩濊鍘熷洜
 */
export type PathValidationResult =
  | { ok: true; safePath: string }
  | { ok: false; reason: string; input: string };

/**
 * 楠岃瘉鏂囦欢璺緞鏄惁鍦?projectRoot 娌欑鍐呫€俓r
 *
 * @param filePath 宸ュ叿璋冪敤浼犲叆鐨勬枃浠惰矾寰勶紙鍙兘涓虹浉瀵?缁濆璺緞锛塡r
 * @param projectRoot 椤圭洰鏍圭洰褰曪紙缁濆璺緞锛夈€俷ull 鏃惰烦杩囨矙绠辨鏌ワ紙鍚戝悗鍏煎锛塡r
 * @returns 楠岃瘉缁撴灉
 */
export function validatePath(filePath: string, projectRoot: string | null): PathValidationResult {
  // 鈹€鈹€ 鍩虹杈撳叆鏍￠獙 鈹€鈹€
  if (!filePath || filePath.trim() === "") {
    return { ok: false, reason: "璺緞涓虹┖", input: filePath };
  }
  if (filePath.includes("\0")) {
    return { ok: false, reason: "璺緞鍖呭惈 NUL 瀛楄妭", input: filePath };
  }
  // 鈹€鈹€ 鏈娌欑鏃跺厑璁镐换鎰忚矾寰勶紙鍚戝悗鍏煎娴嬭瘯鍦烘櫙锛?鈹€鈹€
  if (!projectRoot) {
    return { ok: true, safePath: path.resolve(filePath) };
  }

  // 鈹€鈹€ 瑙ｆ瀽璺緞锛堝睍寮€ ..銆佺鍙烽摼鎺ョ瓑锛?鈹€鈹€
  const resolvedRoot = path.resolve(projectRoot);

  // 鈹€鈹€ 鏄惧紡闃绘柇 Windows 缁濆璺緞锛堝惈鐩樼锛夛紝闃茶寖璺ㄥ钩鍙扮粫杩?鈹€鈹€
  // 鍦?Unix 涓婏紝"C:\Windows" 浼氳 path.resolve() 褰撲綔鏅€氱浉瀵硅矾寰勶紝
  // 缁曡繃璺ㄦ牴妫€鏌ャ€傛澶勪粎鍦?projectRoot 闈?Windows 璺緞鏃舵娴嬨€俓r
  // Windows 涓婄殑璺ㄧ洏绗︾敱涓嬫柟鐨?path.parse().root 姣斿澶勭悊銆俓r
  const WIN_ABS_PATH_RE = /^[A-Za-z]:[\\/]/;
  if (WIN_ABS_PATH_RE.test(filePath) && !WIN_ABS_PATH_RE.test(resolvedRoot)) {
    return { ok: false, reason: `璺緞瓒婄晫: Windows 缁濆璺緞缁曡繃 "${filePath}"`, input: filePath };
  }

  const resolved = path.resolve(resolvedRoot, filePath);

  // 鈹€鈹€ 璺ㄧ洏绗?璺ㄦ牴妫€娴嬶紙鏇夸唬鏃╂湡 Windows 缁濆璺緞纭嫤鎴級 鈹€鈹€
  // path.parse().root 鍦?Windows 涓婅繑鍥炵洏绗︼紙濡?"C:\"锛夛紝鍦?Unix 涓婅繑鍥?"/"銆俓r
  // 鑻?resolved 涓?resolvedRoot 涓嶅湪鍚屼竴鐩樼/鏍逛笅锛屽垯涓€瀹氭槸瓒婄晫鏀诲嚮銆俓r
  const rootParsed = path.parse(resolvedRoot);
  const fileParsed = path.parse(resolved);
  if (rootParsed.root !== fileParsed.root) {
    return { ok: false, reason: `璺緞瓒婄晫: 璺ㄨ秺鐩樼/鏍?"${filePath}" (瑙ｆ瀽涓?"${resolved}")`, input: filePath };
  }

  // 鈹€鈹€ 瓒婄晫妫€鏌?鈹€鈹€
  // 鍏佽锛歳esolved 绛変簬 root 鎴栧湪 root 瀛愭爲鍐匼r
  // 娉ㄦ剰锛歳oot 鍙兘宸蹭互鍒嗛殧绗︾粨灏撅紙濡?"/"锛夛紝闇€閬垮厤鍙屽垎闅旂璇垽
  const sep = path.sep;
  const rootPrefix = resolvedRoot.endsWith(sep) ? resolvedRoot : resolvedRoot + sep;
  if (resolved === resolvedRoot || resolved.startsWith(rootPrefix)) {
    return { ok: true, safePath: resolved };
  }

  return {
    ok: false,
    reason: `璺緞瓒婄晫: "${filePath}" (瑙ｆ瀽涓?"${resolved}") 涓嶅湪宸ヤ綔鍖?"${resolvedRoot}" 鍐卄,
    input: filePath,
  };
}

/**
 * 楠岃瘉璺緞骞惰繑鍥炲畨鍏ㄧ粷瀵硅矾寰勶紝杩濊鏃舵姏鍑洪敊璇€俓r
 * 閫傜敤浜庨渶瑕佸揩閫熷け璐ワ紙fail-fast锛夌殑鍦烘櫙銆俓r
 *
 * @throws 璺緞瓒婄晫鏃舵姏鍑?Error
 */
export function resolveSafePath(filePath: string, projectRoot: string | null): string {
  const result = validatePath(filePath, projectRoot);
  if (!result.ok) {
    throw new Error(result.reason);
  }
  return result.safePath;
}

/**
 * search-aggregator.ts 鈥斺€?澶氭簮鎼滅储鑱氬悎鍣╘r
 *
 * 鑱岃矗:
 * 1. 骞惰鏌ヨ鎵€鏈夊惎鐢ㄧ殑鎼滅储鍚庣
 * 2. 鎸?URL 鍘婚噸 (鏍囧噯鍖栧悗姣旇緝)
 * 3. 浜ゅ弶鎺掑悕 (interleaving) 淇濊瘉缁撴灉澶氭牱鎬r
 * 4. 鍐呭瓨缂撳瓨 (鎸?query 褰掍竴鍖? TTL 鍙厤缃?
 *
 * @layer platform 鈥斺€?琚?Toolkit 浣跨敤
 */

import type { SearchBackend, SearchResult } from "./search-backend.js";

// 鈹€鈹€鈹€ 缂撳瓨 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

interface CacheEntry {
  results: SearchResult[];
  timestamp: number;
}

// 鈹€鈹€鈹€ SearchAggregator 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export class SearchAggregator {
  private backends: SearchBackend[];
  private cache = new Map<string, CacheEntry>();
  private cacheTTL: number;
  private resultTimeout: number;
  private minBackends: number;

  constructor(opts: {
    backends: SearchBackend[];
    cacheTTL?: number;
    resultTimeout?: number;
    minBackends?: number;
  }) {
    this.backends = opts.backends;
    this.cacheTTL = opts.cacheTTL ?? 300_000;
    this.resultTimeout = opts.resultTimeout ?? 15_000;
    this.minBackends = opts.minBackends ?? 1;
  }

  /** 娣诲姞鍚庣 (杩愯鏃剁儹鎻掓嫈) */
  addBackend(backend: SearchBackend): void {
    this.backends.push(backend);
  }

  /** 鎵ц鎼滅储 */
  async search(query: string, maxResults: number): Promise<SearchResult[]> {
    const normQuery = query.trim().toLowerCase();

    // 鈹€鈹€ 缂撳瓨妫€鏌?鈹€鈹€
    const cached = this.cache.get(normQuery);
    if (cached && (Date.now() - cached.timestamp) < this.cacheTTL) {
      return cached.results.slice(0, maxResults);
    }

    // 娓呯悊杩囨湡缂撳瓨
    const now = Date.now();
    for (const [key, entry] of this.cache) {
      if (now - entry.timestamp > this.cacheTTL) this.cache.delete(key);
    }

    const enabled = this.backends.filter((b) => b.enabled);
    if (enabled.length === 0) return [];

    // 鈹€鈹€ 骞惰鏌ヨ鎵€鏈夊凡鍚敤鍚庣 鈹€鈹€
    const searches = enabled.map(async (backend) => {
      try {
        const results = await Promise.race([
          backend.search(query, maxResults),
          new Promise<SearchResult[]>((_, reject) =>
            setTimeout(() => reject(new Error(`backend "${backend.id}" timed out`)), this.resultTimeout),
          ),
        ]);
        return results;
      } catch {
        return [] as SearchResult[];
      }
    });

    const allResults = (await Promise.all(searches))
      .filter((r) => r.length > 0);

    // 鑷冲皯闇€瑕?minBackends 涓悗绔垚鍔焅r
    if (allResults.length < this.minBackends) return [];

    // 鈹€鈹€ 鍘婚噸 + 浜ゅ弶鎺掑悕 鈹€鈹€
    const merged = this._deduplicateAndInterleave(allResults, maxResults);

    // 鍐欏叆缂撳瓨
    if (merged.length > 0) {
      this.cache.set(normQuery, { results: merged, timestamp: Date.now() });
    }

    return merged;
  }

  // 鈹€鈹€鈹€ 鍘婚噸 + 浜ゅ弶鎺掑悕 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 鎸?URL 鍘婚噸 + 浜ゅ弶浜ょ粐鎺掑悕銆俓r
   *
   * 鍘婚噸绛栫暐: 鏍囧噯鍖?URL (鍘?trailing slash, lowercase host+path) 鍚庢瘮杈冦€俓r
   *   鍚屼竴 URL 鍛戒腑澶氫釜鍚庣鏃讹紝淇濈暀 snippet 鏈€闀跨殑鐗堟湰锛屼笖鍔犳潈鍓嶇疆銆俓r
   *
   * 鎺掑悕绛栫暐: round-robin interleaving銆俓r
   *   鍚勫悗绔彇绗?1 鏉?鈫?鍚勫悗绔彇绗?2 鏉?鈫?...
   *   淇濊瘉缁撴灉澶氭牱鎬э紝闃叉鍗曚竴鍚庣鍨勬柇 top N銆俓r
   */
  private _deduplicateAndInterleave(
    backendResults: SearchResult[][],
    maxResults: number,
  ): SearchResult[] {
    // 1. 鍘婚噸: URL 鈫?鏈€浣?snippet
    const seen = new Map<string, SearchResult>();
    for (const results of backendResults) {
      for (const item of results) {
        const key = normalizeUrl(item.url);
        const existing = seen.get(key);
        if (!existing || item.snippet.length > existing.snippet.length) {
          // 鍚?URL 澶氬悗绔懡涓椂鏍囪
          const boosted = existing ? { ...item, snippet: `[${item.source}+${existing.source}] ${item.snippet}` } : item;
          seen.set(key, boosted);
        }
      }
    }

    // 2. 鎭㈠鍘熷椤哄簭 + 鎸夋潵婧愬垎缁刓r
    const deduped: SearchResult[] = [];
    const sourceBuckets = new Map<string, SearchResult[]>();
    for (const [_urlKey, item] of seen) {
      const source = item.source;
      if (!sourceBuckets.has(source)) sourceBuckets.set(source, []);
      const bucket = sourceBuckets.get(source);
      if (bucket) bucket.push(item);
    }

    // 3. 浜ゅ弶浜ょ粐
    const buckets = [...sourceBuckets.values()];
    let bucketIdx = 0;
    while (deduped.length < maxResults && buckets.length > 0) {
      const bucket = buckets[bucketIdx % buckets.length];
      if (bucket.length > 0) {
        const item = bucket.shift();
        if (item) deduped.push(item);
      }
      bucketIdx++;

      // 瀹夊叏妫€鏌? 鎵€鏈?bucket 閮界┖浜嗗氨閫€鍑篭r
      if (buckets.every((b) => b.length === 0)) break;
    }

    return deduped.slice(0, maxResults);
  }
}

