// ============================================================
// @cortex/engine/platform/tools/diff-files 鈥斺€?diff_files 宸ュ叿
//
// 瀵规瘮涓や釜鏂囦欢鐨勫唴瀹癸紝杩斿洖 unified diff 鏍煎紡鐨勮绾у樊寮傘€俓r
// 绾唴瀛樿绠楋紝涓嶄緷璧栧閮?diff/git 鍛戒护銆俓r
//
// 绠楁硶锛氱粡鍏?LCS锛堟渶闀垮叕鍏卞瓙搴忓垪锛夆啋 unified diff銆俓r
//
// @core v3 鈥斺€?Tool 鎺ュ彛缁熶竴锛歟xport createTool(ctx): Tool
// ============================================================

import { ToolCategory, ReversibilityLevel as RL, type Tool } from "@cortex/shared";
import { LocalTool } from "../local-tool.js";
import type { ToolContext } from "./types.js";

const MAX_FILE_SIZE = 500_000; // 500KB
const MAX_DIFF_LINES = 1_000;

export function createTool(ctx: ToolContext): Tool {
  return new LocalTool(
    "diff_files",
    ToolCategory.Read,
    "Compare two files and return a unified diff. Useful for reviewing changes, verifying edits, or comparing outputs. Pure in-memory LCS algorithm鈥攏o external diff dependency.",
    {
      type: "object",
      properties: {
        file_a: {
          type: "string",
          description: "Absolute path to the first file (baseline)",
        },
        file_b: {
          type: "string",
          description: "Absolute path to the second file (changed)",
        },
        context_lines: {
          type: "number",
          description: "Number of context lines around each diff hunk (default: 3)",
        },
      },
      required: ["file_a", "file_b"],
    },
    RL.L0,
    async (params) => {
      const pathA = ctx.resolvePath(params.file_a as string);
      const pathB = ctx.resolvePath(params.file_b as string);
      const contextLines = (params.context_lines as number) || 3;

      try {
        const [existsA, existsB] = await Promise.all([
          ctx.fs.exists(pathA),
          ctx.fs.exists(pathB),
        ]);

        if (!existsA) {
          return { success: false, error: `鏂囦欢 A 涓嶅瓨鍦? ${pathA}` };
        }
        if (!existsB) {
          return { success: false, error: `鏂囦欢 B 涓嶅瓨鍦? ${pathB}` };
        }

        const [contentA, contentB] = await Promise.all([
          ctx.fs.readFile(pathA),
          ctx.fs.readFile(pathB),
        ]);

        if (contentA.length > MAX_FILE_SIZE || contentB.length > MAX_FILE_SIZE) {
          return {
            success: false,
            error: `鏂囦欢杩囧ぇ (A: ${contentA.length} bytes, B: ${contentB.length} bytes, max: ${MAX_FILE_SIZE})`,
          };
        }

        const linesA = contentA.split("\n");
        const linesB = contentB.split("\n");

        const diff = computeUnifiedDiff(linesA, linesB, pathA, pathB, contextLines);

        return {
          success: true,
          output: diff.slice(0, 30_000),
        };
      } catch (e) {
        return { success: false, error: `diff_files 澶辫触: ${String(e)}` };
      }
    },
  );
}

// 鈹€鈹€ Unified Diff 鐢熸垚鍣?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

interface DiffHunk {
  startA: number;
  countA: number;
  startB: number;
  countB: number;
  lines: string[];
}

function computeUnifiedDiff(
  linesA: string[],
  linesB: string[],
  pathA: string,
  pathB: string,
  context: number,
): string {
  if (linesA.length === 0 && linesB.length === 0) {
    return `--- ${pathA}\n+++ ${pathB}\n@@ -0,0 +0,0 @@\n(empty files)`;
  }

  // 璁＄畻 LCS 缂栬緫搴忓垪
  const edits = computeEdits(linesA, linesB);
  const hunks = buildHunks(edits, context, linesA, linesB);

  if (hunks.length === 0) {
    return `--- ${pathA}\n+++ ${pathB}\n(no changes)`;
  }

  const header = `--- ${pathA}\n+++ ${pathB}\n`;
  return (
    header +
    hunks
      .map((h) => {
        const range = `@@ -${h.startA + 1},${h.countA} +${h.startB + 1},${h.countB} @@`;
        return [range, ...h.lines].join("\n");
      })
      .join("\n")
  );
}

interface Edit {
  type: "equal" | "delete" | "insert";
  aLine?: number;
  bLine?: number;
}

function computeEdits(linesA: string[], linesB: string[]): Edit[] {
  // Myers 宸噺楠ㄦ灦 (绠€鍖栫増鈥斺€旂敤 LCS 鍥炴函)
  const m = linesA.length;
  const n = linesB.length;

  // dp[i][j] = LCS 闀垮害
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (linesA[i - 1] === linesB[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // 鍥炴函 LCS 鐢熸垚缂栬緫搴忓垪
  const edits: Edit[] = [];
  let i = m;
  let j = n;

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && linesA[i - 1] === linesB[j - 1]) {
      edits.unshift({ type: "equal", aLine: i - 1, bLine: j - 1 });
      i--;
      j--;
    } else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
      edits.unshift({ type: "insert", bLine: j - 1 });
      j--;
    } else {
      edits.unshift({ type: "delete", aLine: i - 1 });
      i--;
    }
  }

  return edits;
}

function buildHunks(edits: Edit[], context: number, linesA: string[], linesB: string[]): DiffHunk[] {
  const hunks: DiffHunk[] = [];
  let i = 0;

  while (i < edits.length) {
    // 璺宠繃鍓嶉潰鐨勭浉绛夐儴鍒嗭紙鐣?context 琛岋級
    let equalBefore = 0;
    let scan = i;
    while (scan < edits.length && edits[scan].type === "equal" && equalBefore < context) {
      equalBefore++;
      scan++;
    }

    // 鎵惧埌鍙樻洿寮€濮媆r
    scan = i + equalBefore;
    if (scan >= edits.length) break;

    // 鏀堕泦鍙樻洿鍧梊r
    const hunkStart = Math.max(0, i - context);
    let changeEnd = scan;

    while (changeEnd < edits.length && edits[changeEnd].type !== "equal") {
      changeEnd++;
    }

    // 鎵╁睍 equal 涓婁笅鏂囷紙鍚庨潰锛塡r
    let equalAfter = 0;
    while (changeEnd + equalAfter < edits.length && edits[changeEnd + equalAfter].type === "equal" && equalAfter < context) {
      equalAfter++;
    }

    const hunkEnd = Math.min(edits.length, changeEnd + equalAfter);

    // 鏋勫缓 hunk 琛孿r
    const lines: string[] = [];
    let aLine = 0;
    let bLine = 0;

    for (let k = hunkStart; k < hunkEnd; k++) {
      const edit = edits[k];
      switch (edit.type) {
        case "equal":
          if (edit.aLine !== undefined) {
            aLine = edit.aLine;
          }
          bLine = edit.bLine ?? bLine;
          lines.push(` ${linesA[aLine]}`);
          break;
        case "delete":
          if (edit.aLine !== undefined) aLine = edit.aLine;
          lines.push(`-${linesA[aLine]}`);
          break;
        case "insert":
          if (edit.bLine !== undefined) bLine = edit.bLine;
          lines.push(`+${linesB[bLine]}`);
          break;
      }
    }

    // 璁＄畻鑼冨洿
    let startA = -1;
    let endA = -1;
    let startB = -1;
    let endB = -1;

    for (let k = hunkStart; k < hunkEnd; k++) {
      const e = edits[k];
      if (e.aLine !== undefined) {
        if (startA === -1) startA = e.aLine;
        endA = e.aLine;
      }
      if (e.bLine !== undefined) {
        if (startB === -1) startB = e.bLine;
        endB = e.bLine;
      }
    }

    hunks.push({
      startA: startA === -1 ? 0 : startA,
      countA: startA === -1 ? 0 : endA - startA + 1,
      startB: startB === -1 ? 0 : startB,
      countB: startB === -1 ? 0 : endB - startB + 1,
      lines: lines.slice(0, MAX_DIFF_LINES),
    });

    i = hunkEnd;
  }

  return hunks;
}

// ============================================================
// @cortex/engine/platform/tools/edit-file 鈥斺€?edit_file 宸ュ叿
//
// 绮剧‘鏂囨湰鎼滅储鏇挎崲鈥斺€斿湪鏂囦欢涓煡鎵?old_text锛屾浛鎹负 new_text銆俓r
// 绫讳技 Qoder 鐨?SearchReplace锛屾瘮 write_file锛堝叏閲忚鐩栵級绮掑害鏇寸粏銆俓r
//
// 鏍￠獙瑙勫垯锛歕r
//   1. old_text 蹇呴』鍦ㄦ枃浠朵腑鍞竴鍑虹幇锛堥櫎闈?replace_all=true锛塡r
//   2. old_text 涓?new_text 蹇呴』涓嶅悓
//   3. 鏇挎崲鍚庢枃浠堕暱搴?鈮?1MB
//
// @core v3 鈥斺€?Tool 鎺ュ彛缁熶竴锛歟xport createTool(ctx): Tool
// ============================================================

import { ToolCategory, ReversibilityLevel as RL, type Tool } from "@cortex/shared";
import { LocalTool } from "../local-tool.js";
import type { ToolContext } from "./types.js";

export function createTool(ctx: ToolContext): Tool {
  return new LocalTool(
    "edit_file",
    ToolCategory.Write,
    "Perform a precise search-and-replace in a file. Finds the exact old_text string and replaces it with new_text. Unlike write_file (full overwrite), this only touches the matched portion. Use replace_all=true to replace all occurrences.",
    {
      type: "object",
      properties: {
        file_path: {
          type: "string",
          description: "Absolute path to the file to edit",
        },
        old_text: {
          type: "string",
          description: "The exact text to find and replace. Must be unique in the file unless replace_all is true.",
        },
        new_text: {
          type: "string",
          description: "The replacement text. Must differ from old_text.",
        },
        replace_all: {
          type: "boolean",
          description: "If true, replace all occurrences of old_text (default: false)",
        },
      },
      required: ["file_path", "old_text", "new_text"],
    },
    RL.L2,
    async (params) => {
      const filePath = ctx.resolvePath(params.file_path as string);
      const oldText = params.old_text as string;
      const newText = params.new_text as string;
      const replaceAll = params.replace_all === true;

      if (!oldText) {
        return { success: false, error: "edit_file: old_text 涓嶈兘涓虹┖" };
      }
      if (oldText === newText) {
        return { success: false, error: "edit_file: old_text 涓?new_text 涓嶈兘鐩稿悓" };
      }

      try {
        const exists = await ctx.fs.exists(filePath);
        if (!exists) {
          return { success: false, error: `鏂囦欢涓嶅瓨鍦? ${filePath}` };
        }

        const content = await ctx.fs.readFile(filePath);

        // 璁＄畻鍑虹幇娆℃暟
        const occurrences = countOccurrences(content, oldText);
        if (occurrences === 0) {
          return {
            success: false,
            error: `edit_file: 鍦?"${filePath}" 涓湭鎵惧埌 old_text銆傝纭鏂囨湰绮剧‘鍖归厤锛堝惈绌虹櫧瀛楃锛夈€俙,
          };
        }
        if (!replaceAll && occurrences > 1) {
          const preview = content.slice(
            Math.max(0, content.indexOf(oldText) - 40),
            content.indexOf(oldText) + oldText.length + 40,
          );
          return {
            success: false,
            error: `edit_file: old_text 鍦ㄦ枃浠朵腑鍑虹幇浜?${occurrences} 娆★紝浣?replace_all=false銆俙 +
              `璇锋彁渚涙洿澶氫笂涓嬫枃浣?old_text 鍞竴锛屾垨璁剧疆 replace_all=true銆俙 +
              `\n棣栨鍑虹幇闄勮繎: ...${preview}...`,
          };
        }

        // 鎵ц鏇挎崲
        const newContent = replaceAll
          ? content.split(oldText).join(newText)
          : content.replace(oldText, newText);

        if (newContent.length > 1_048_576) {
          return { success: false, error: `edit_file: 鏇挎崲鍚庢枃浠惰秴杩?1MB 闄愬埗 (${newContent.length} bytes)` };
        }

        await ctx.fs.writeFile(filePath, newContent);

        const replacedCount = replaceAll ? occurrences : 1;
        return {
          success: true,
          output: `edit_file OK: ${filePath}\n鏇挎崲 ${replacedCount} 澶勶紝${content.length} 鈫?${newContent.length} 瀛楃`,
        };
      } catch (e) {
        return { success: false, error: `edit_file 澶辫触: ${String(e)}` };
      }
    },
  );
}

function countOccurrences(haystack: string, needle: string): number {
  if (!needle) return 0;
  let count = 0;
  let pos = 0;
  while ((pos = haystack.indexOf(needle, pos)) !== -1) {
    count++;
    pos += needle.length;
  }
  return count;
}

// ============================================================
// @cortex/engine/platform/tools/file-info 鈥斺€?file_info 宸ュ叿
//
// 鑾峰彇鍗曚釜鏂囦欢鐨勫厓淇℃伅锛氬ぇ灏忋€佽鏁般€佷慨鏀规椂闂淬€佺被鍨嬬瓑銆俓r
// 姣?run_shell "wc -l / stat" 鏇村彲闈狅紝璧?IFileSystemAdapter銆俓r
//
// @core v3 鈥斺€?Tool 鎺ュ彛缁熶竴锛歟xport createTool(ctx): Tool
// ============================================================

import { ToolCategory, ReversibilityLevel as RL, type Tool } from "@cortex/shared";
import { LocalTool } from "../local-tool.js";
import type { ToolContext } from "./types.js";

export function createTool(ctx: ToolContext): Tool {
  return new LocalTool(
    "file_info",
    ToolCategory.Read,
    "Get metadata for a file: size (bytes), line count, existence, file/directory type. Faster and more reliable than shell stat/wc.",
    {
      type: "object",
      properties: {
        file_path: { type: "string", description: "Absolute path to the file" },
      },
      required: ["file_path"],
    },
    RL.L0,
    async (params) => {
      const filePath = ctx.resolvePath(params.file_path as string);
      try {
        const exists = await ctx.fs.exists(filePath);
        if (!exists) {
          return { success: true, output: JSON.stringify({ path: filePath, exists: false }) };
        }

        const [stat, content] = await Promise.all([
          ctx.fs.stat(filePath).catch(() => null),
          ctx.fs.readFile(filePath).catch(() => null),
        ]);

        const info: Record<string, unknown> = {
          path: filePath,
          exists: true,
          isFile: stat?.isFile ?? null,
          isDirectory: stat?.isDirectory ?? null,
          lineCount: content !== null ? content.split("\n").length : null,
          sizeBytes: content !== null ? content.length : null,
        };

        return { success: true, output: JSON.stringify(info, null, 2) };
      } catch (e) {
        return { success: false, error: `鑾峰彇鏂囦欢淇℃伅澶辫触: ${String(e)}` };
      }
    },
  );
}

// ============================================================
// @cortex/engine/platform/tools/format-code 鈥斺€?format_code 宸ュ叿
//
// 瀵规寚瀹氭枃浠讹紙鎴?glob锛夋墽琛屼唬鐮佹牸寮忓寲銆傛敮鎸?prettier / eslint / biome銆俓r
// 姣旇８ run_shell "npx prettier --write" 鏇村畨鍏ㄢ€斺€斾粎鍏佽鐧藉悕鍗曞懡浠ゃ€俓r
//
// @core v3 鈥斺€?Tool 鎺ュ彛缁熶竴锛歟xport createTool(ctx): Tool
// ============================================================

import { ToolCategory, ReversibilityLevel as RL, type Tool } from "@cortex/shared";
import { LocalTool } from "../local-tool.js";
import type { ToolContext } from "./types.js";

const ALLOWED_FORMATTERS = ["prettier", "eslint", "biome"] as const;
type Formatter = (typeof ALLOWED_FORMATTERS)[number];

export function createTool(ctx: ToolContext): Tool {
  return new LocalTool(
    "format_code",
    ToolCategory.Write,
    "Format code in a file or directory using prettier, eslint, or biome. Safer than running shell commands directly.",
    {
      type: "object",
      properties: {
        file_path: {
          type: "string",
          description: "Absolute path to the file or directory to format",
        },
        formatter: {
          type: "string",
          description: "Formatter to use: 'prettier' (default), 'eslint' (--fix), 'biome' (format --write), or 'both' (prettier then eslint)",
        },
        check_only: {
          type: "boolean",
          description: "If true, only check formatting without modifying files (default: false)",
        },
      },
      required: ["file_path"],
    },
    RL.L2,
    async (params) => {
      const filePath = ctx.resolvePath(params.file_path as string);
      const formatter = (params.formatter as string) || "prettier";
      const checkOnly = params.check_only === true;

      const cwd = ctx.workspaceRoot ?? ctx.fs.cwd();

      // 鐧藉悕鍗曟牎楠孿r
      const selected: Formatter[] =
        formatter === "both"
          ? ["prettier", "eslint"]
          : ALLOWED_FORMATTERS.includes(formatter as Formatter)
            ? [formatter as Formatter]
            : [];

      if (selected.length === 0) {
        return {
          success: false,
          error: `涓嶆敮鎸佺殑鏍煎紡鍖栧櫒: "${formatter}"銆傚彲閫? ${ALLOWED_FORMATTERS.join(", ")}, both`,
        };
      }

      const results: string[] = [];

      for (const fmt of selected) {
        let args: string[];
        switch (fmt) {
          case "prettier":
            args = checkOnly
              ? ["prettier", "--check", filePath]
              : ["prettier", "--write", filePath];
            break;
          case "eslint":
            args = checkOnly
              ? ["eslint", filePath]
              : ["eslint", "--fix", filePath];
            break;
          case "biome":
            args = checkOnly
              ? ["biome", "format", filePath]
              : ["biome", "format", "--write", filePath];
            break;
          default:
            continue;
        }

        try {
          const output = await ctx.fs.execCommand(`npx ${args.join(" ")}`, {
            cwd,
            timeout: ctx.toolTimeouts.runShell ?? 60_000,
          });
          results.push(`[${fmt}] ${checkOnly ? "check" : "format"} OK:\n${output.slice(0, 2_000)}`);
        } catch (e) {
          const err = e as { stderr?: unknown; message?: string };
          const detail = err.stderr
            ? String(err.stderr).slice(0, 2_000)
            : (err.message?.slice(0, 500) ?? String(e));
          results.push(`[${fmt}] FAILED:\n${detail}`);
        }
      }

      return { success: true, output: results.join("\n\n") };
    },
  );
}

