// ============================================================
// @cortex/engine/platform/tools/grep-files 鈥斺€?grep_files 宸ュ叿
//
// 鍦ㄦ寚瀹氱殑鏂囦欢鍒楄〃涓悳绱㈠尮閰嶈銆備笌 search_code 涓嶅悓锛歕r
// search_code 鐢?ripgrep 鎼滅储鏁翠釜椤圭洰锛孿r
// grep_files 鍦ㄧ敤鎴锋寚瀹氱殑鏂囦欢鍒楄〃涓€愪竴鎼滅储銆俓r
//
// @core v3 鈥斺€?Tool 鎺ュ彛缁熶竴锛歟xport createTool(ctx): Tool
// ============================================================

import { ToolCategory, ReversibilityLevel as RL, type Tool } from "@cortex/shared";
import { LocalTool } from "../local-tool.js";
import type { ToolContext } from "./types.js";

export function createTool(ctx: ToolContext): Tool {
  return new LocalTool(
    "grep_files",
    ToolCategory.Search,
    "Search for a pattern within a specific list of files. Unlike search_code (project-wide ripgrep), this searches only the exact files you specify. Returns file:line:content matches.",
    {
      type: "object",
      properties: {
        pattern: { type: "string", description: "Text or regex pattern to search for (case-insensitive)" },
        file_paths: {
          type: "array",
          items: { type: "string" },
          description: "Array of absolute file paths to search within (max 20)",
        },
      },
      required: ["pattern", "file_paths"],
    },
    RL.L0,
    async (params) => {
      const pattern = (params.pattern as string)?.toLowerCase();
      const paths = params.file_paths as string[];
      if (!pattern) {
        return { success: false, error: "grep_files 缂哄皯 pattern 鍙傛暟" };
      }
      if (!paths || !Array.isArray(paths) || paths.length === 0) {
        return { success: false, error: "grep_files 闇€瑕?file_paths 鏁扮粍鍙傛暟" };
      }
      if (paths.length > 20) {
        return { success: false, error: `grep_files 鏈€澶氭悳绱?20 涓枃浠讹紝鏀跺埌 ${paths.length}` };
      }

      const matches: string[] = [];
      for (const rawPath of paths) {
        try {
          const filePath = ctx.resolvePath(rawPath);
          const exists = await ctx.fs.exists(filePath);
          if (!exists) continue;
          const content = await ctx.fs.readFile(filePath);
          const lines = content.split("\n");
          for (let i = 0; i < lines.length; i++) {
            if (lines[i].toLowerCase().includes(pattern)) {
              matches.push(`${rawPath}:${i + 1}: ${lines[i].trim().slice(0, 300)}`);
            }
            if (matches.length >= 100) break;
          }
        } catch {
          // 璺宠繃涓嶅彲璇绘枃浠禱r
        }
        if (matches.length >= 100) break;
      }

      if (matches.length === 0) {
        return { success: true, output: `鏈湪鎸囧畾鏂囦欢涓壘鍒板尮閰?"${params.pattern}" 鐨勭粨鏋渀 };
      }
      return { success: true, output: matches.join("\n") };
    },
  );
}

// ============================================================
// @cortex/engine/platform/tools/json-query 鈥斺€?json_query 宸ュ叿
//
// 浣跨敤 JSONPath 璇硶鏌ヨ JSON 鏂囦欢銆傛敮鎸侊細
//   $.store.books[*].title         鈥?璺緞瀵艰埅
//   $.store.books[?(@.price<10)]   鈥?鏉′欢杩囨护
//   $.store.book[-1]               鈥?鏈熬鍏冪礌
//
// 鏃犲閮ㄤ緷璧栤€斺€旀墜鍐欏井鍨?JSONPath 瑙ｆ瀽鍣ㄣ€俓r
//
// @core v3 鈥斺€?Tool 鎺ュ彛缁熶竴锛歟xport createTool(ctx): Tool
// ============================================================

import { ToolCategory, ReversibilityLevel as RL, type Tool } from "@cortex/shared";
import { LocalTool } from "../local-tool.js";
import type { ToolContext } from "./types.js";

export function createTool(ctx: ToolContext): Tool {
  return new LocalTool(
    "json_query",
    ToolCategory.Read,
    "Query a JSON file using JSONPath syntax (e.g. '$.store.books[*].title', '$.foo.bar[?(@.baz>5)]', '$.items[-1]'). Returns the matched value(s).",
    {
      type: "object",
      properties: {
        file_path: {
          type: "string",
          description: "Absolute path to the JSON file to query",
        },
        query: {
          type: "string",
          description: "JSONPath expression starting with '$' (e.g. '$.agents.*.id', '$.items[0].name')",
        },
      },
      required: ["file_path", "query"],
    },
    RL.L0,
    async (params) => {
      const filePath = ctx.resolvePath(params.file_path as string);
      const query = params.query as string;

      try {
        const content = await ctx.fs.readFile(filePath);
        const data = JSON.parse(content);
        const results = jsonPath(data, query);

        if (results.length === 0) {
          return {
            success: true,
            output: JSON.stringify({ query, matches: [], count: 0 }, null, 2),
          };
        }

        return {
          success: true,
          output: JSON.stringify(
            {
              query,
              count: results.length,
              matches: results.length === 1 ? results[0] : results,
            },
            null,
            2,
          ).slice(0, 20_000),
        };
      } catch (e) {
        return { success: false, error: `json_query 澶辫触: ${String(e)}` };
      }
    },
  );
}

// 鈹€鈹€ 寰瀷 JSONPath 寮曟搸 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

function jsonPath(root: unknown, query: string): unknown[] {
  if (!query.startsWith("$")) {
    throw new Error(`JSONPath 蹇呴』浠?'$' 寮€澶? "${query}"`);
  }

  const segments = parseSegments(query.slice(1)); // 鍘绘帀寮€澶寸殑 $
  let current: unknown[] = [root];

  for (const seg of segments) {
    current = applySegment(current, seg);
  }

  return current;
}

interface PathSegment {
  type: "key" | "index" | "wildcard" | "slice" | "filter" | "recursive";
  key?: string;
  index?: number;
  start?: number;
  end?: number;
  step?: number;
  filter?: string; // @.price < 10
}

function parseSegments(path: string): PathSegment[] {
  const segments: PathSegment[] = [];
  let i = 0;

  while (i < path.length) {
    // 閫掑綊涓嬮檷: ..
    if (path[i] === "." && path[i + 1] === ".") {
      segments.push({ type: "recursive" });
      i += 2;
      // 璺宠繃鍚庣画鐨?.
      if (path[i] === ".") i++;
      continue;
    }

    // 鐐瑰彿鍒嗛殧
    if (path[i] === ".") {
      i++;
      continue;
    }

    // 鎷彿绱㈠紩 / 杩囨护
    if (path[i] === "[") {
      i++; // skip [
      let bracket = "";
      let depth = 1;
      while (i < path.length && depth > 0) {
        if (path[i] === "[") depth++;
        if (path[i] === "]") depth--;
        if (depth > 0) bracket += path[i];
        i++;
      }
      // i now points past ]

      if (bracket === "*") {
        segments.push({ type: "wildcard" });
      } else if (/^-?\d+$/.test(bracket.trim())) {
        segments.push({ type: "index", index: parseInt(bracket.trim(), 10) });
      } else if (/^(-?\d+)?:(-?\d+)?(:-?\d+)?$/.test(bracket.trim())) {
        const parts = bracket.split(":").map((p) => (p ? parseInt(p, 10) : undefined));
        segments.push({
          type: "slice",
          start: parts[0],
          end: parts[1],
          step: parts[2],
        });
      } else if (bracket.startsWith("?(") && bracket.endsWith(")")) {
        segments.push({ type: "filter", filter: bracket.slice(2, -1) });
      } else {
        // 瀛楃涓查敭 (鍗曞紩鍙锋垨鍙屽紩鍙?
        const key = bracket.replace(/^['"]|['"]$/g, "");
        segments.push({ type: "key", key });
      }
      continue;
    }

    // 鏅€氶敭鍚峔r
    let key = "";
    while (i < path.length && path[i] !== "." && path[i] !== "[") {
      key += path[i];
      i++;
    }
    if (key) {
      segments.push({ type: "key", key });
    }
  }

  return segments;
}

function applySegment(current: unknown[], seg: PathSegment): unknown[] {
  const results: unknown[] = [];

  for (const item of current) {
    switch (seg.type) {
      case "key": {
        const key = seg.key;
        if (key !== undefined && item && typeof item === "object" && key in item) {
          results.push((item as Record<string, unknown>)[key]);
        }
        break;
      }
      case "index": {
        const idxRaw = seg.index;
        if (idxRaw !== undefined) {
          const arr = item as unknown[];
          if (Array.isArray(arr)) {
            const idx = idxRaw < 0 ? arr.length + idxRaw : idxRaw;
            if (idx >= 0 && idx < arr.length) {
              results.push(arr[idx]);
            }
          }
        }
        break;
      }
      case "wildcard": {
        if (Array.isArray(item)) {
          results.push(...item);
        } else if (item && typeof item === "object") {
          results.push(...Object.values(item as Record<string, unknown>));
        }
        break;
      }
      case "slice": {
        if (Array.isArray(item)) {
          const arr = item as unknown[];
          const len = arr.length;
          const start = seg.start ?? 0;
          const realStart = start < 0 ? Math.max(0, len + start) : Math.min(len, start);
          const end = seg.end ?? len;
          const realEnd = end < 0 ? Math.max(0, len + end) : Math.min(len, end);
          const step = seg.step ?? 1;
          for (let j = realStart; step > 0 ? j < realEnd : j > realEnd; j += step) {
            if (j >= 0 && j < len) results.push(arr[j]);
          }
        }
        break;
      }
      case "filter": {
        const filter = seg.filter;
        if (filter !== undefined && Array.isArray(item)) {
          for (const elem of item) {
            if (evaluateFilter(elem, filter)) {
              results.push(elem);
            }
          }
        }
        break;
      }
      case "recursive": {
        results.push(item);
        collectRecursive(item, results);
        break;
      }
    }
  }

  return results;
}

/** 绠€鏄撹繃婊ゅ櫒锛氭敮鎸?@.key op value锛宱p 鈭?{==, !=, <, >, <=, >=, =~} */
function evaluateFilter(obj: unknown, expr: string): boolean {
  const match = expr.trim().match(/^@\.(\w+)\s*(==|!=|<=|>=|<|>|=~)\s*(.+)$/);
  if (!match) return true; // 鏃犳硶瑙ｆ瀽 鈫?閫氳繃

  const [, key, op, valStr] = match;
  if (!obj || typeof obj !== "object") return false;

  const actual = (obj as Record<string, unknown>)[key];
  const expected = parseFilterValue(valStr.trim());

  switch (op) {
    case "==": return actual == expected;
    case "!=": return actual != expected;
    case "<": return Number(actual) < Number(expected);
    case ">": return Number(actual) > Number(expected);
    case "<=": return Number(actual) <= Number(expected);
    case ">=": return Number(actual) >= Number(expected);
    case "=~": {
      try {
        return new RegExp(String(expected)).test(String(actual));
      } catch {
        return false;
      }
    }
    default: return true;
  }
}

function parseFilterValue(s: string): unknown {
  s = s.trim();
  if ((s.startsWith("'") && s.endsWith("'")) || (s.startsWith('"') && s.endsWith('"'))) {
    return s.slice(1, -1);
  }
  if (s === "true") return true;
  if (s === "false") return false;
  if (s === "null") return null;
  if (/^-?\d+(\.\d+)?$/.test(s)) return parseFloat(s);
  return s;
}

function collectRecursive(node: unknown, into: unknown[]): void {
  if (Array.isArray(node)) {
    for (const item of node) {
      into.push(item);
      collectRecursive(item, into);
    }
  } else if (node && typeof node === "object") {
    for (const v of Object.values(node as Record<string, unknown>)) {
      into.push(v);
      collectRecursive(v, into);
    }
  }
}

// ============================================================
// @cortex/engine/platform/tools/list-files 鈥斺€?list_files 宸ュ叿
//
// @core v3 鈥斺€?Tool 鎺ュ彛缁熶竴锛歟xport createTool(ctx): Tool
// ============================================================

import { ToolCategory, ReversibilityLevel as RL, type Tool } from "@cortex/shared";
import { LocalTool } from "../local-tool.js";
import type { ToolContext } from "./types.js";

export function createTool(ctx: ToolContext): Tool {
  return new LocalTool(
    "list_files",
    ToolCategory.Read,
    "List files and directories at the given path.",
    {
      type: "object",
      properties: {
        dir_path: { type: "string", description: "Absolute path to directory (default: current workspace)" },
        pattern: { type: "string", description: "Glob filter pattern (optional, e.g. '*.ts')" },
      },
      required: [],
    },
    RL.L0,
    async (params) => {
      const dirPath = params.dir_path
        ? ctx.resolvePath(params.dir_path as string)
        : (ctx.workspaceRoot ?? ctx.fs.cwd());
      try {
        const exists = await ctx.fs.exists(dirPath);
        if (!exists) {
          return { success: false, error: `鐩綍涓嶅瓨鍦? ${dirPath}` };
        }
        const entries = await ctx.fs.listDirectory(dirPath);
        const pattern = params.pattern as string | undefined;
        let listing = entries
          .map((e) => `${e.isDirectory ? "[D]" : "[F]"} ${e.name}`)
          .join("\n");
        if (pattern) {
          const regex = new RegExp(
            "^" + pattern.replace(/\*/g, ".*").replace(/\?/g, ".") + "$",
          );
          listing = entries
            .filter((e) => regex.test(e.name))
            .map((e) => `${e.isDirectory ? "[D]" : "[F]"} ${e.name}`)
            .join("\n");
        }
        return { success: true, output: listing || "(绌虹洰褰?" };
      } catch (e) {
        return { success: false, error: `鍒楃洰褰曞け璐? ${String(e)}` };
      }
    },
  );
}

