export function createTool(ctx: ToolContext): Tool {
  return new LocalTool(
    "read_many_files",
    ToolCategory.Read,
    "Read multiple files in parallel. Returns concatenated output with file headers. Use this instead of multiple read_file calls to reduce round-trips.",
    {
      type: "object",
      properties: {
        file_paths: {
          type: "array",
          items: { type: "string" },
          description: "Array of absolute file paths to read (max 10)",
        },
      },
      required: ["file_paths"],
    },
    RL.L0,
    async (params) => {
      const paths = params.file_paths as string[];
      if (!paths || !Array.isArray(paths) || paths.length === 0) {
        return { success: false, error: "read_many_files 闇€瑕?file_paths 鏁扮粍鍙傛暟" };
      }
      if (paths.length > 10) {
        return { success: false, error: `read_many_files 鏈€澶氳鍙?10 涓枃浠讹紝鏀跺埌 ${paths.length}` };
      }

      const resolvedPaths = paths.map((p) => {
        try { return ctx.resolvePath(p); } catch { return p; }
      });

      const reads = resolvedPaths.map(async (filePath, i) => {
        try {
          const exists = await ctx.fs.exists(filePath);
          if (!exists) {
            return `=== ${paths[i]} ===\n[鏂囦欢涓嶅瓨鍦╙\n`;
          }
          const content = await ctx.fs.readFile(filePath);
