        } catch (e) {
          return `=== ${paths[i]} ===\n[璇诲彇澶辫触: ${String(e)}]\n`;
        }
      });

      const outputs = await Promise.all(reads);
      return { success: true, output: outputs.join("\n") };
    },
  );
}

