 *
 * 瀹氫箟 Plugin 鎺ュ彛鐨勬牳蹇冪敓鍛藉懆鏈熷绾︼紙init / execute / destroy锛夛紝
 * 姣忎釜鐢熷懡鍛ㄦ湡鏂规硶鍧囪繑鍥?Promise<void>銆俓n *
 * 鎻愪緵 AbstractPlugin 鎶借薄鍩虹被锛岀畝鍖栧叿浣撴彃浠剁殑瀹炵幇銆俓n * 鎻愪緵 isPlugin 绫诲瀷瀹堝崼鍑芥暟銆俓n */

import type { Plugin, PluginConfig, PluginHooks, ExecuteContext, PluginStatus } from "./types.js";

/**
 * AbstractPlugin 鈥斺€?浜岀骇鎻掍欢鐨勬娊璞″熀绫汇€俓n *
 * 瀹炵幇 Plugin 鎺ュ彛锛屾彁渚涢粯璁よ涓烘ā鏉裤€傚叿浣撴彃浠剁户鎵挎绫诲苟澶嶅啓
 * 蹇呰鐨勬柟娉曘€俓n *
 * 鐢熷懡鍛ㄦ湡绾﹀畾锛歕n *   1. init(config)   鈥?娉ㄥ叆閰嶇疆銆佸垵濮嬪寲鍐呴儴鐘舵€乗n *   2. execute(ctx)   鈥?鎵ц鎻掍欢鏍稿績閫昏緫锛堝彲琚娆¤皟鐢級
 *   3. destroy()      鈥?浼橀泤娓呯悊璧勬簮
 *
 * @template TConfig  鈥?鎻掍欢閰嶇疆绫诲瀷
 */
export abstract class AbstractPlugin<TConfig = PluginConfig>
  implements Plugin<TConfig>
{
  /** 鎻掍欢鍞竴鍚嶇О锛堝瓙绫诲繀椤诲疄鐜帮級 */
  abstract readonly name: string;

  /** 鎻掍欢鐗堟湰鍙凤紙榛樿 "1.0.0"锛?*/
  readonly version: string = "1.0.0";

  /** 鐭弿杩帮紙榛樿绌猴級 */
  readonly description: string = "";

  /** 渚濊禆鐨勪簩绾ф彃浠跺悕绉板垪琛?*/
