  /** 鍐呴儴杩愯鏃剁姸鎬侊紙寤惰繜鍒濆鍖栤€斺€旈伩鍏嶅湪鎶借薄灞炴€ц祴鍊煎墠璁块棶 this.name锛?*/
  private _status?: PluginStatus;

  /** 鑾峰彇褰撳墠杩愯鏃剁姸鎬?*/
  get status(): PluginStatus {
    if (!this._status) {
      this._status = {
        name: this.name,
        phase: "created",
        executionCount: 0,
        failureCount: 0,
        healthy: true,
      };
    }
    return { ...this._status };
  }

  /** 鏇存柊鍐呴儴鐘舵€?*/
  protected setStatus(phase: PluginStatus["phase"], lastError?: string): void {
    const current = this.status;
    this._status = {
