}

/**
 * isPlugin 鈥斺€?绫诲瀷瀹堝崼锛屽垽鏂竴涓湭鐭ュ璞℃槸鍚﹀疄鐜颁簡 Plugin 鎺ュ彛銆俓n *
 * 妫€娴嬩緷鎹細瀵硅薄闈炵┖銆佸叿鏈?string 绫诲瀷鐨?name/version 灞炴€э紝
 * 浠ュ強 init / execute / destroy 涓変釜鍑芥暟鏂规硶銆俓n */
export function isPlugin(obj: unknown): obj is Plugin {
  if (obj === null || obj === undefined) return false;
  if (typeof obj !== "object") return false;

  const candidate = obj as Record<string, unknown>;

  return (
    typeof candidate.name === "string" &&
    typeof candidate.version === "string" &&
    typeof candidate.execute === "function" &&
    typeof candidate.init === "function" &&
    typeof candidate.destroy === "function"
  );
}

/**
 * @cortex/plugin-runner 鈥?鎻掍欢娉ㄥ唽琛ㄦā鍧梊n *
