// 鈹€鈹€ 鍐呴儴绫诲瀷 鈹€鈹€

/** glob 鍖归厤缁撴灉椤?*/
interface GlobMatch {
  /** 鍖归厤鏂囦欢鐨勭粷瀵硅矾寰?*/
  filePath: string;
  /** 鐩稿浜?glob 鍩鸿矾寰勭殑璺緞 */
  relativePath: string;
