// 鈹€鈹€ Glob 妯″紡鍖归厤寮曟搸锛堥浂澶栭儴渚濊禆锛?鈹€鈹€

/**
 * 灏?glob 妯″紡缂栬瘧涓烘鍒欒〃杈惧紡銆俓n *
 * 鏀寔鐨勯€氶厤绗︼細
 * - 鍙屾槦鍙?(**)  鈥?鍖归厤闆舵垨澶氬眰鐩綍锛堝繀椤荤嫭鍗犱竴涓矾寰勬锛屽嵆 ** 鍚庢帴 /锛屾垨 /* 鍚庢帴 *锛塡n * - 鍗曟槦鍙?(*)   鈥?鍖归厤鍗曟鍐呴浂鎴栧涓瓧绗︼紙涓嶈法鐩綍锛塡n * - 闂彿 (?)   鈥?鍖归厤鍗曟鍐呭崟涓瓧绗︼紙涓嶈法鐩綍锛塡n * - 鑺辨嫭鍙?({a,b}) 鈥?鍖归厤澶氫釜澶囬€夐」锛堜粎椤跺眰锛屼笉鏀寔宓屽锛塡n */
function globToRegex(pattern: string): RegExp {
  // 瑙勮寖鍖栬矾寰勫垎闅旂涓?/
  const normalized = pattern.replace(/\\/g, "/");

  // 澶勭悊 {a,b} 灞曞紑 鈥?绠€鍗曠増鏈紙涓嶆敮鎸佸祵濂楋級
  const braceMatch = normalized.match(/{([^}]+)}/);
  if (braceMatch) {
    const alternatives = braceMatch[1].split(",").map((s) => s.trim());
    const prefix = normalized.slice(0, braceMatch.index);
    if (braceMatch.index === undefined) {
      throw new Error("globToRegex: brace match has no index");
    }
    const suffix = normalized.slice(braceMatch.index + braceMatch[0].length);
    const altPatterns = alternatives.map(
      (alt) => `${prefix}${alt}${suffix}`,
    );
    return new RegExp(
      `^(?:${altPatterns.map((p) => globToRegexSource(p)).join("|")})$`,
      "i",
    );
  }

  return new RegExp(`^${globToRegexSource(normalized)}$`, "i");
}

/**
 * 灏嗗崟涓?glob 妯″紡杞崲涓烘鍒欒〃杈惧紡婧愬瓧绗︿覆锛堜笉鍚?^$ 杈圭晫锛夈€俓n */
function globToRegexSource(pattern: string): string {
  let source = "";
  let i = 0;

  while (i < pattern.length) {
    const ch = pattern[i];

    if (ch === "*" && pattern[i + 1] === "*") {
      // ** 鍖归厤闆舵垨澶氫釜璺緞娈礬n      source += "(?:.+[/\\\\])?.*";
      // 璺宠繃鍚庣画鐨?/锛堝鏋滄湁锛塡n      if (pattern[i + 2] === "/" || pattern[i + 2] === "\\") {
        i += 3;
      } else {
        i += 2;
      }
    } else if (ch === "*") {
      // 鍗曟閫氶厤锛堜笉璺ㄧ洰褰曪級
      source += "[^/\\\\]*";
      i += 1;
    } else if (ch === "?") {
      source += "[^/\\\\]";
      i += 1;
    } else if (ch === ".") {
      source += "\\.";
      i += 1;
    } else if (ch === "/" || ch === "\\") {
      source += "[/\\\\]";
      i += 1;
    } else {
      // 杞箟姝ｅ垯鐗规畩瀛楃
      const specials = /[.+^${}()|[\]\\]/;
      if (specials.test(ch)) {
        source += `\\${ch}`;
      } else {
        source += ch;
      }
      i += 1;
    }
  }

  return source;
}

/**
 * 瑙ｆ瀽 glob 妯″紡涓哄熀璺緞鍜岀浉瀵规ā寮忛儴鍒嗐€俓n *
 * 渚嬪: `"./plugins/**\/*.plugin.js"` 鈫抃n * `{ basePath: "/abs/project/plugins", pattern: "**\/*.plugin.js" }`
 *
 * 渚嬪: `"./plugins/my-plugin.js"` 鈫抃n * `{ basePath: "/abs/project/plugins", pattern: "my-plugin.js" }`
 */
function parseGlobPattern(
  globPattern: string,
): { basePath: string; pattern: string } {
  const normalized = globPattern.replace(/\\/g, "/");

  // 鎵惧埌绗竴涓€氶厤绗︿綅缃甛n  const wildcardIndex = normalized.search(/[*?{]/);

  if (wildcardIndex === -1) {
    // 娌℃湁閫氶厤绗?鈥?瑙嗕负鍗曚釜鏂囦欢璺緞
    const absPath = isAbsolute(normalized)
      ? normalize(normalized)
      : resolve(normalized);
    return {
      basePath: dirname(absPath),
      pattern: basename(absPath),
    };
  }

  // 鍦ㄩ€氶厤绗﹀墠鏈€鍚庝竴涓?/ 澶勫垎鍓瞈n  const lastSepBeforeWildcard = normalized.lastIndexOf("/", wildcardIndex);

  if (lastSepBeforeWildcard === -1) {
    // 閫氶厤绗﹀湪绗竴灞傦紙濡?"*.js"锛塡n    return {
      basePath: resolve("."),
      pattern: normalized,
    };
  }

  const basePart = normalized.slice(0, lastSepBeforeWildcard);
  const patternPart = normalized.slice(lastSepBeforeWildcard + 1);

  return {
    basePath: basePart.length === 0
      ? resolve(".")
      : isAbsolute(basePart)
      ? normalize(basePart)
      : resolve(basePart),
    pattern: patternPart,
  };
}

/**
 * 閫掑綊鎵弿鐩綍锛岃繑鍥炴墍鏈夊尮閰?glob 妯″紡鐨勬枃浠躲€俓n *
 * @param dirPath   鈥?褰撳墠鎵弿鐨勭洰褰曡矾寰刓n * @param regex     鈥?缂栬瘧濂界殑 glob 姝ｅ垯
 * @param basePath  鈥?鍩鸿矾寰勶紙鐢ㄤ簬璁＄畻 relativePath锛塡n * @param maxDepth  鈥?鏈€澶ч€掑綊娣卞害锛堥粯璁?10锛岄槻姝㈡棤闄愰€掑綊锛塡n */
async function scanDir(
  dirPath: string,
  regex: RegExp,
  basePath: string,
  maxDepth = 10,
): Promise<GlobMatch[]> {
  if (maxDepth <= 0) return [];

  let entries: string[];
  try {
    entries = await readdir(dirPath);
  } catch {
    // 鐩綍涓嶅彲璇伙紙鏉冮檺/涓嶅瓨鍦級 鈥?闈欓粯璺宠繃
    return [];
  }

  const results: GlobMatch[] = [];

  for (const entry of entries) {
    const fullPath = join(dirPath, entry);

    try {
      const entryStat = await fsStat(fullPath);

      if (entryStat.isDirectory()) {
        // 閫掑綊鎵弿瀛愮洰褰昞n        const subResults = await scanDir(
          fullPath,
          regex,
          basePath,
          maxDepth - 1,
        );
        results.push(...subResults);
      } else if (entryStat.isFile()) {
        const relativePath = relative(basePath, fullPath).replace(/\\/g, "/");
        if (regex.test(relativePath)) {
          results.push({ filePath: fullPath, relativePath });
        }
      }
    } catch {
      // 鍗曚釜鏂囦欢/鐩綍涓嶅彲璇?鈥?璺宠繃
      continue;
    }
  }

  return results;
}

