/**
 * PluginRegistry 鈥斺€?鎻掍欢娉ㄥ唽琛ㄣ€俓n *
 * 绠＄悊浜岀骇鎻掍欢鐨勫畬鏁寸敓鍛藉懆鏈熸敞鍐屼俊鎭€俓n * 鏀寔鎸夊悕绉版敞鍐?娉ㄩ攢銆佹寜鏍囩鏌ヨ銆乬lob 鏂囦欢鍙戠幇鍜屼緷璧栨嫇鎵戞帓搴忋€俓n *
 * 渚濊禆鍊掔疆锛氭湰绫讳粎渚濊禆 `Plugin` 鎺ュ彛锛屼笉渚濊禆浠讳綍鍏蜂綋鎻掍欢瀹炵幇銆俓n */
export class PluginRegistry {
  /** 鎻掍欢缂撳瓨鏄犲皠锛坣ame 鈫?Plugin锛?*/
  private _plugins: Map<string, Plugin> = new Map();

  // 鈹€鈹€ 娉ㄥ唽涓庢敞閿€ 鈹€鈹€

  /**
   * 娉ㄥ唽涓€涓凡瀹炰緥鍖栫殑浜岀骇鎻掍欢銆俓n   *
   * 娉ㄥ唽鍓嶄笉浼氳皟鐢ㄦ彃浠剁殑 init() 鈥?init 鐢?PluginRunner 鎸夐渶瑙﹀彂銆俓n   * 閲嶅娉ㄥ唽鍚屽悕鎻掍欢灏嗘姏鍑烘槑纭敊璇€俓n   *
   * @param plugin 鈥?瀹炵幇浜?Plugin 鎺ュ彛鐨勬彃浠跺疄渚媆n   * @throws 鍚屽悕鎻掍欢宸叉敞鍐屾椂鎶?Error
   */
  register(plugin: Plugin): void {
    if (!plugin || typeof plugin.name !== "string" || plugin.name.length === 0) {
      throw new Error(
        "[PluginRegistry] 娉ㄥ唽澶辫触: 鎻掍欢蹇呴』鍏锋湁闈炵┖鐨?name 灞炴€

usedDeprecatedRules:
${plugin.name}" 宸插瓨鍦╜,
      );
    }

    this._plugins.set(plugin.name, plugin);
  }

  /**
   * 娉ㄩ攢鎸囧畾鍚嶇О鐨勬彃浠躲€俓n   *
   * 娉ㄩ攢鍓嶄笉浼氳嚜鍔ㄨ皟鐢?destroy() 鈥?璋冪敤鏂归渶鑷纭繚璧勬簮娓呯悊銆俓n   *
   * @param name 鈥?瑕佹敞閿€鐨勬彃浠跺悕绉癨n   * @returns 鏄惁鎴愬姛娉ㄩ攢锛坒alse 琛ㄧず璇ュ悕绉版湭娉ㄥ唽锛塡n   */
  unregister(name: string): boolean {
    return this._plugins.delete(name);
  }

  // 鈹€鈹€ 鏌ヨ妫€绱?鈹€鈹€

  /**
   * 鑾峰彇鎸囧畾鍚嶇О鐨勫畬鏁存彃浠跺疄渚嬨€俓n   */
  get(name: string): Plugin | undefined {
    return this._plugins.get(name);
  }

  /**
   * 鑾峰彇鎸囧畾鍚嶇О鐨勬彃浠跺厓淇℃伅锛堣交閲忚鍥撅級銆俓n   *
   * 杩斿洖 PluginMeta锛堢函鏁版嵁瀵硅薄锛夛紝涓嶆毚闇叉彃浠跺疄渚嬬殑寮曠敤銆俓n   * 閫傜敤浜?registry list / discover 绛夋棤闇€鍔犺浇瀹屾暣瀹炰緥鐨勫満鏅€俓n   */
  getMeta(name: string): PluginMeta | undefined {
    const plugin = this._plugins.get(name);
    if (!plugin) return undefined;

    return this._toMeta(plugin);
  }

  /**
   * 妫€鏌ユ寚瀹氬悕绉扮殑鎻掍欢鏄惁宸叉敞鍐屻€俓n   */
  has(name: string): boolean {
    return this._plugins.has(name);
  }

  /**
   * 褰撳墠娉ㄥ唽鐨勬彃浠舵€绘暟銆俓n   */
  get size(): number {
    return this._plugins.size;
  }

  /**
   * 鑾峰彇鎵€鏈夊凡娉ㄥ唽鐨勬彃浠跺疄渚嬫暟缁勩€俓n   */
  getAll(): Plugin[] {
    return Array.from(this._plugins.values());
  }

  /**
   * 鑾峰彇鎵€鏈夊凡娉ㄥ唽鎻掍欢鐨勫厓淇℃伅鏁扮粍銆俓n   */
  getAllMeta(): PluginMeta[] {
    return this.getAll().map((p) => this._toMeta(p));
  }

  /**
   * 鎸夋爣绛炬煡鎵炬墍鏈夊尮閰嶇殑鎻掍欢銆俓n   *
   * @param tag 鈥?瑕佹煡鎵剧殑鏍囩鍚嶏紙绮剧‘鍖归厤锛塡n   */
  findByTag(tag: string): Plugin[] {
    return this.getAll().filter((p) => p.tags.includes(tag));
  }

  /**
   * 鎸夎嚜瀹氫箟杩囨护鍑芥暟鏌ユ壘鎻掍欢銆俓n   *
   * @param filter 鈥?杩囨护璋撹瘝锛屾帴鏀?Plugin 瀹炰緥锛岃繑鍥?true 琛ㄧず鍖归厤
   */
  find(filter: (p: Plugin) => boolean): Plugin[] {
    return this.getAll().filter(filter);
  }

  /**
   * 鎸夊悕绉版壒閲忚幏鍙栨彃浠跺疄渚嬶紙鐢ㄤ簬渚濊禆娉ㄥ叆鍦烘櫙锛夈€俓n   *
   * @param names 鈥?瑕佽幏鍙栫殑鎻掍欢鍚嶇О鍒楄〃
   * @returns 鍚嶇О 鈫?Plugin 瀹炰緥鐨勬槧灏勩€備笉瀛樺湪鐨勫悕绉颁笉浼氬嚭鐜板湪缁撴灉涓€俓n   */
  getMultiple(names: string[]): Map<string, Plugin> {
    const result = new Map<string, Plugin>();
    for (const name of names) {
      const plugin = this._plugins.get(name);
      if (plugin) {
        result.set(name, plugin);
      }
    }
    return result;
  }

  // 鈹€鈹€ 鏂囦欢鍙戠幇 鈹€鈹€

  /**
   * 閫氳繃鏂囦欢璺緞閫氶厤绗︽壂鎻忔枃浠剁郴缁燂紝鍙戠幇骞惰繑鍥炴彃浠跺厓淇℃伅銆俓n   *
   * 鎵弿娴佺▼锛歕n   * 1. 瑙ｆ瀽 glob 妯″紡涓哄熀璺緞 + 鐩稿妯″紡
   * 2. 閫掑綊鎵弿鐩綍锛屾敹闆嗘墍鏈夊尮閰嶇殑鏂囦欢
   * 3. 鍔ㄦ€?import 姣忎釜鏂囦欢
   * 4. 妫€鏌ュ鍑烘槸鍚﹀疄鐜颁簡 Plugin 鎺ュ彛锛堥€氳繃 isPlugin 瀹堝崼锛塡n   * 5. 杩斿洖 PluginMeta 鍒楄〃锛堜笉娉ㄥ唽鍒?registry锛屼粎鍙戠幇锛塡n   *
   * 娉ㄦ剰锛氭鏂规硶浼氭墽琛屽姩鎬?import锛屼絾涓嶄細鑷姩璋冪敤鎻掍欢鐨?init()銆俓n   * 琚鍏ョ殑鎻掍欢妯″潡涓嶅簲鏈夊壇浣滅敤銆俓n   *
   * @param globPattern 鈥?鏂囦欢璺緞閫氶厤绗︼紙鏀寔 **, *, ?, {a,b}锛塡n   * @returns 鍙戠幇鐨勬彃浠跺厓淇℃伅鍒楄〃锛堜笉浼氳嚜鍔ㄦ敞鍐屽埌 registry锛塡n   */
  async discover(globPattern: string): Promise<PluginMeta[]> {
    if (!globPattern || globPattern.trim().length === 0) {
      return [];
    }

    const { basePath, pattern } = parseGlobPattern(globPattern.trim());
    const regex = globToRegex(pattern);

    // 鎵弿鐩綍鑾峰彇鍖归厤鐨勬枃浠禱n    const matches = await scanDir(basePath, regex, basePath);

    if (matches.length === 0) {
      return [];
    }

    // 閫愪釜鍔ㄦ€?import 骞舵鏌ユ槸鍚︿负鎻掍欢
    const discovered: PluginMeta[] = [];

    for (const match of matches) {
      try {
        const fileUrl = pathToFileURL(match.filePath).href;
        const mod = await import(fileUrl);

        // 妫€鏌ユā鍧楃殑榛樿瀵煎嚭鍜屽懡鍚嶅鍑篭n        const candidates: unknown[] = [];

        if (mod.default) {
          candidates.push(mod.default);
        }

        // 鏀堕泦鎵€鏈夊彲鑳界殑鎻掍欢瀵煎嚭
        for (const key of Object.keys(mod)) {
          if (key === "default") continue;
          candidates.push(mod[key]);
        }

        for (const candidate of candidates) {
          if (isPlugin(candidate)) {
            discovered.push({
              name: candidate.name,
              version: candidate.version,
              description: candidate.description,
              tags: [...candidate.tags],
              dependencies: [...candidate.dependencies],
              hooks: { ...candidate.hooks },
              filePath: match.filePath,
            });
          }
        }
      } catch {
        // 鍗曚釜鏂囦欢瀵煎叆澶辫触 鈥?璺宠繃锛屼笉褰卞搷鍏朵粬鏂囦欢鐨勫彂鐜癨n        continue;
      }
    }

    return discovered;
  }

  /**
   * 閫氳繃 glob 妯″紡鍙戠幇鎻掍欢骞惰嚜鍔ㄦ敞鍐屽埌 registry銆俓n   *
   * 鏄?discover() + register() 鐨勪究鎹风粍鍚堛€俓n   * 璺宠繃宸茬粡琚敞鍐岀殑鍚屽悕鎻掍欢锛堥潤榛樿烦杩囷紝涓嶆姏寮傚父锛夈€俓n   *
   * @param globPattern 鈥?鏂囦欢璺緞閫氶厤绗n   * @returns 鎴愬姛娉ㄥ唽鐨勬彃浠舵暟閲廫n   */
  async registerFromGlob(globPattern: string): Promise<number> {
    const discovered = await this.discover(globPattern);

    let registeredCount = 0;

    for (const meta of discovered) {
      if (this._plugins.has(meta.name)) {
        // 鍚屽悕鎻掍欢宸插瓨鍦?鈥?闈欓粯璺宠繃
        continue;
      }

      // 閲嶆柊瀵煎叆骞舵敞鍐孿n      try {
        if (!meta.filePath) {
          throw new Error("PluginRegistry.refresh: missing filePath in metadata");
        }
        const fileUrl = pathToFileURL(meta.filePath).href;
        const mod = await import(fileUrl);

        // 鎵惧埌瀵瑰簲鐨?Plugin 瀹炰緥
        const candidates: unknown[] = [];
        if (mod.default) candidates.push(mod.default);
        for (const key of Object.keys(mod)) {
          if (key === "default") continue;
          candidates.push(mod[key]);
        }

        for (const candidate of candidates) {
          if (isPlugin(candidate) && candidate.name === meta.name) {
            this.register(candidate);
            registeredCount++;
            break;
          }
        }
      } catch {
        continue;
      }
    }

    return registeredCount;
  }

  // 鈹€鈹€ 渚濊禆瑙ｆ瀽 鈹€鈹€

  /**
   * 渚濊禆鎷撴墤鎺掑簭銆俓n   *
   * 浣跨敤 Kahn 绠楁硶瀵瑰綋鍓嶆敞鍐岀殑鎵€鏈夋彃浠惰繘琛屾嫇鎵戞帓搴忥紝
   * 杩斿洖鎸変緷璧栭『搴忔帓鍒楃殑鎵ц鎵规銆俓n   *
   * 鍚屾壒娆″唴鐨勬彃浠舵棤鐩镐簰渚濊禆锛屽彲浠ュ苟琛屾墽琛屻€俓n   * 鎵规闂村繀椤讳覆琛屾墽琛岋紙鍓嶄竴鎵规鍏ㄩ儴瀹屾垚鍚庡啀鎵ц涓嬩竴鎵癸級銆俓n   *
   * 绠楁硶娴佺▼锛歕n   * 1. 鏋勫缓鏈夊悜鍥撅紙渚濊禆鏂瑰悜锛歞ep 鈫?dependent锛塡n   * 2. 璁＄畻姣忎釜鑺傜偣鐨勫叆搴n   * 3. 浠庡叆搴︿负 0 鐨勮妭鐐瑰紑濮嬶紝閫愬眰鍓ョ
   * 4. 姣忓墺绂讳竴灞傚嵆涓轰竴涓壒娆n   *
   * @returns 鎷撴墤鎺掑簭鍚庣殑浜岀淮鏁扮粍
   * @throws 妫€娴嬪埌渚濊禆寰幆鏃舵姏 Error锛堝惈寰幆鍙備笌鑺傜偣淇℃伅锛塡n   */
  resolveDependencies(): Plugin[][] {
    const plugins = this.getAll();

    if (plugins.length === 0) {
      return [];
    }

    // 鍙€冭檻宸叉敞鍐屾彃浠堕棿鐨勪緷璧栧叧绯籠n    const registeredNames = new Set(plugins.map((p) => p.name));

    // 鍏ュ害琛? name 鈫?鍏ュ害鏁帮紙鏈弧瓒崇殑渚濊禆鏁帮級
    const inDegree = new Map<string, number>();
    // 閭绘帴琛? name 鈫?渚濊禆姝ゆ彃浠剁殑鍏朵粬鎻掍欢鍒楄〃
    const adjacency = new Map<string, string[]>();

    // 鍒濆鍖朶n    for (const p of plugins) {
      inDegree.set(p.name, 0);
      adjacency.set(p.name, []);
    }

    // 寤哄浘
    for (const p of plugins) {
      for (const dep of p.dependencies) {
        // 鍙粺璁″凡娉ㄥ唽鐨勪緷璧朶n        if (registeredNames.has(dep)) {
          const neighbors = adjacency.get(dep) ?? [];
          neighbors.push(p.name);
          adjacency.set(dep, neighbors);
          inDegree.set(p.name, (inDegree.get(p.name) ?? 0) + 1);
        }
        // 鏈敞鍐岀殑渚濊禆锛氫笉褰卞搷鎺掑簭锛屾墽琛屾椂鐢?PluginRunner 澶勭悊
      }
    }

    // Kahn 绠楁硶
    const queue: string[] = [];

    for (const [name, degree] of inDegree) {
      if (degree === 0) {
        queue.push(name);
      }
    }

    const batches: Plugin[][] = [];
    let visitedCount = 0;

    while (queue.length > 0) {
      const batchSize = queue.length;
      const batch: Plugin[] = [];

      for (let i = 0; i < batchSize; i++) {
        const name = queue.shift();
        if (!name) continue;
        const plugin = this._plugins.get(name);
        if (plugin) {
          batch.push(plugin);
        }
        visitedCount++;

        const dependents = adjacency.get(name) ?? [];
        for (const dependent of dependents) {
          const newDegree = (inDegree.get(dependent) ?? 1) - 1;
          inDegree.set(dependent, newDegree);
          if (newDegree === 0) {
            queue.push(dependent);
          }
        }
      }

      batches.push(batch);
    }

    if (visitedCount !== plugins.length) {
      // 鎵惧嚭寰幆渚濊禆涓殑鑺傜偣
      const unvisited = plugins.filter(
        (p) => !queue.includes(p.name) && (inDegree.get(p.name) ?? 0) > 0,
      );
      const cycleNames = unvisited.map((p) => p.name).join(", ");
      throw new Error(
        `[PluginRegistry] 渚濊禆寰幆妫€娴嬪埌锛屾棤娉曡В鏋愪緷璧栭『搴忋€傛秹鍙婃彃浠? ${cycleNames}`,
      );
    }

    return batches;
  }

  /**
   * 妫€鏌ユ槸鍚﹀瓨鍦ㄤ緷璧栧惊鐜€俓n   *
   * 浣跨敤涓夎壊鏍囪娉曪紙DFS锛夋娴嬫湁鍚戝浘涓殑鐜€俓n   *
   * @returns 濡傛灉瀛樺湪寰幆鍒欒繑鍥?true锛屽惁鍒欒繑鍥?false
   */
  hasCycle(): boolean {
    const plugins = this.getAll();
    if (plugins.length === 0) return false;

    const registeredNames = new Set(plugins.map((p) => p.name));
    const adjacency = new Map<string, string[]>();

    for (const p of plugins) {
      const deps: string[] = [];
      for (const dep of p.dependencies) {
        if (registeredNames.has(dep)) {
          deps.push(dep);
        }
      }
      adjacency.set(p.name, deps);
    }

    // 涓夎壊鏍囪: 0 = 鏈闂? 1 = 璁块棶涓? 2 = 宸茶闂甛n    const color = new Map<string, number>();
    for (const p of plugins) {
      color.set(p.name, 0);
    }

    function dfs(node: string): boolean {
      color.set(node, 1); // 鏍囪涓鸿闂腑
      const neighbors = adjacency.get(node) ?? [];

      for (const neighbor of neighbors) {
        const neighborColor = color.get(neighbor);
        if (neighborColor === 1) {
          // 鎵惧埌鍥炶竟 鈫?鏈夌幆
          return true;
        }
        if (neighborColor === 0) {
          if (dfs(neighbor)) {
            return true;
          }
        }
      }

      color.set(node, 2); // 鏍囪涓哄凡璁块棶
      return false;
    }

    for (const p of plugins) {
      if (color.get(p.name) === 0) {
        if (dfs(p.name)) {
          return true;
        }
      }
    }

    return false;
  }

  // 鈹€鈹€ 宸ュ叿鏂规硶 鈹€鈹€

  /**
   * 娓呯┖娉ㄥ唽琛ㄣ€俓n   *
   * 绉婚櫎鎵€鏈夊凡娉ㄥ唽鐨勬彃浠跺紩鐢ㄣ€俓n   * 娉ㄦ剰锛氫笉浼氳嚜鍔ㄨ皟鐢ㄦ彃浠剁殑 destroy() 鈥?璋冪敤鏂归渶鑷澶勭悊銆俓n   */
  clear(): void {
    this._plugins.clear();
  }

  /**
   * 杩斿洖褰撳墠娉ㄥ唽鐨勬墍鏈夋彃浠跺悕绉板垪琛ㄣ€俓n   */
  listNames(): string[] {
    return Array.from(this._plugins.keys());
  }

  // 鈹€鈹€ 鍐呴儴杈呭姪 鈹€鈹€

  /**
   * 灏?Plugin 瀹炰緥杞崲涓?PluginMeta 杞婚噺瀵硅薄銆俓n   */
  private _toMeta(plugin: Plugin): PluginMeta {
    return {
      name: plugin.name,
      version: plugin.version,
      description: plugin.description,
      tags: [...plugin.tags],
      dependencies: [...plugin.dependencies],
      hooks: { ...plugin.hooks },
    };
  }
}

