/**
 * @cortex/plugin-runner 鈥?PluginRunner 娌欑鎵ц寮曟搸
 *
 * 鎻愪緵鎻掍欢鐨勫畨鍏ㄦ墽琛岀幆澧冿紝鏍稿績鑱岃矗锛歕n *
 * 1. **鎵ц鍓嶅悎瑙勬牎楠?* 鈥?鏍￠獙鎻掍欢瀛樺湪鎬с€丼chema 閰嶇疆鏍￠獙銆佷緷璧栧瓨鍦ㄦ€ф鏌n * 2. **寮傚父闅旂** 鈥?try/catch 鍖呰９姣忎釜鎻掍欢璋冪敤锛屽崟鎻掍欢宕╂簝涓嶆姏鍒颁笂灞俓n * 3. **瓒呮椂鍒囨柇** 鈥?Promise.race + AbortSignal锛岃秴鏃跺悗鏍囪鎻掍欢鐘舵€佷负 error
 * 4. **璧勬簮娓呯悊** 鈥?鎵ц鍚庤皟鐢?destroy()銆佹竻鐞嗗伐浣滅洰褰曘€佹洿鏂扮姸鎬佺粺璁n * 5. **鎷撴墤鎺掑簭鎵ц** 鈥?executeAll() 鎸変緷璧栭『搴忓垎鎵规墽琛岋紙鍚屾壒骞惰锛屾壒娆′覆琛岋級
 *
 * @module
 */

import { rm } from "node:fs/promises";

import type {
  PluginConfig,
  ExecuteContext,
  PluginResult,
  PluginStatus,
  ExecutionReport,
} from "./types.js";
import type { PluginRegistry } from "./registry.js";
import type { PluginValidator } from "./validator.js";

// 鈹€鈹€ 閰嶇疆鎺ュ彛 鈹€鈹€

/**
 * RunnerOptions 鈥斺€?PluginRunner 鏋勯€犻€夐」銆俓n */
export interface RunnerOptions {
  /** 榛樿瓒呮椂鏃堕棿 ms锛堥粯璁?30000锛?*/
  timeout?: number;
}

// 鈹€鈹€ PluginRunner 绫?鈹€鈹€

/**
 * PluginRunner 鈥斺€?娌欑鎵ц寮曟搸銆俓n *
 * 绠＄悊浜岀骇鎻掍欢鐨勫畨鍏ㄦ墽琛岋紝鎻愪緵鎵ц鍓嶆牎楠屻€佸紓甯搁殧绂汇€佽秴鏃跺垏鏂€佽祫婧愭竻鐞嗐€俓n *
 * 浣跨敤鏂瑰紡锛歕n * ```ts
 * const runner = new PluginRunner(registry, validator, { timeout: 10000 });
 * const result = await runner.execute("myPlugin", {
 *   payload: { foo: "bar" },
 *   deps: new Map(),
 *   workDir: "/tmp/work",
 * });
 * ```
 *
 * @template T 鈥?鎵ц缁撴灉鐨?output 绫诲瀷
 */
export class PluginRunner {
  /** 鎻掍欢娉ㄥ唽琛ㄥ紩鐢?*/
  private _registry: PluginRegistry;

  /** Schema 鏍￠獙鍣ㄥ紩鐢?*/
  private _validator: PluginValidator;

  /** 榛樿瓒呮椂鏃堕棿 (ms) */
  private _defaultTimeout: number;

  /** 杩愯鏃剁姸鎬佽拷韪槧灏?*/
  private _statuses: Map<string, PluginStatus> = new Map();

  /** 鐢辨湰杩愯鍣ㄥ垱寤虹殑涓存椂宸ヤ綔鐩綍闆嗗悎锛坰hutdown 鏃剁粺涓€娓呯悊锛?*/
  private _ownedWorkDirs: Set<string> = new Set();

  /**
   * @param registry 鈥?鎻掍欢娉ㄥ唽琛ㄥ疄渚媆n   * @param validator 鈥?Schema 鏍￠獙鍣ㄥ疄渚媆n   * @param opts 鈥?鍙€夐厤缃紙瓒呮椂绛夛級
   */
  constructor(
    registry: PluginRegistry,
    validator: PluginValidator,
    opts?: RunnerOptions,
  ) {
    this._registry = registry;
    this._validator = validator;
    this._defaultTimeout = opts?.timeout ?? 30_000;
  }

  // 鈹€鈹€ 鍏紑 API 鈹€鈹€

  /**
   * 鎵ц鎸囧畾鍚嶇О鐨勬彃浠躲€俓n   *
   * 瀹屾暣鎵ц娴佺▼锛歕n   * ```
   * 鈹屸攢 鍚堣鏍￠獙 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹怽n   * 鈹?鈶?鎻掍欢瀛樺湪鎬ф鏌?                        鈹俓n   * 鈹?鈶?Schema 閰嶇疆鏍￠獙锛堥€氳繃 PluginValidator锛?鈹俓n   * 鈹?鈶?渚濊禆瀛樺湪鎬ф鏌?                        鈹俓n   * 鈹斺攢鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹榎n   *          鈹?閫氳繃
   *          鈻糪n   * 鈹屸攢 鎵ц闃舵 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹怽n   * 鈹?鈶?plugin.init(config)                  鈹俓n   * 鈹?鈶?plugin.execute(ctx)  鈫?瓒呮椂鎺у埗     鈹俓n   * 鈹?鈶?plugin.destroy()                     鈹俓n   * 鈹斺攢鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹榎n   *          鈹俓n   *          鈻糪n   * 鈹屸攢 鏀跺熬闃舵 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹怽n   * 鈹?鈶?鏇存柊鐘舵€佺粺璁?                         鈹俓n   * 鈹?鈶?杩斿洖 PluginResult                    鈹俓n   * 鈹斺攢鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹榎n   * ```
   *
   * 浠绘剰闃舵鎶涘嚭寮傚父鍧囪 try/catch 鎹曡幏锛屼笉浼氫紶鎾埌璋冪敤鏂广€俓n   *
   * @param name 鈥?瑕佹墽琛岀殑鎻掍欢鍚嶇О锛堥渶宸叉敞鍐屽埌 registry锛塡n   * @param ctx  鈥?鎵ц涓婁笅鏂囷紙payload銆乨eps銆亀orkDir銆乼imeoutMs銆乻ignal锛塡n   * @returns PluginResult 鈥?鏍囧噯鍖栨墽琛岀粨鏋淺n   */
  async execute<T = unknown>(
    name: string,
    ctx: ExecuteContext,
  ): Promise<PluginResult<T>> {
    const startTime = Date.now();

    // 鈹€鈹€鈹€鈹€ 闃舵鈶? 鍚堣鏍￠獙 鈹€鈹€鈹€鈹€

    // 1-a. 鎻掍欢瀛樺湪鎬ф鏌n    const plugin = this._registry.get(name);
    if (!plugin) {
      return {
        success: false,
        error: `[PluginRunner] 鎻掍欢 "${name}" 鏈敞鍐宍,
        durationMs: Date.now() - startTime,
      };
    }

    // 1-b. Schema 閰嶇疆鏍￠獙锛堟棤 schema 鏃堕潤榛橀€氳繃锛塡n    const defaultConfig: PluginConfig = { enabled: true };
    const configResult = this._validator.validateConfig(name, defaultConfig);
    if (!configResult.valid) {
      return {
        success: false,
        error: `[PluginRunner] 閰嶇疆鏍￠獙澶辫触: ${configResult.errors.join("; ")}`,
        durationMs: Date.now() - startTime,
      };
    }

    // 1-c. 渚濊禆瀛樺湪鎬ф鏌n    for (const depName of plugin.dependencies) {
      if (!this._registry.has(depName)) {
        return {
          success: false,
          error: `[PluginRunner] 渚濊禆鎻掍欢 "${depName}" 鏈敞鍐宍,
          durationMs: Date.now() - startTime,
        };
      }
    }

    // 鈹€鈹€鈹€鈹€ 闃舵鈶? 鎵ц闃舵锛堝紓甯搁殧绂伙級 鈹€鈹€鈹€鈹€

    // 鏇存柊鐘舵€?鈫?running
    this._updateStatus(name, "running");

    try {
      // 2-a. 鍒濆鍖栨彃浠禱n      await plugin.init(defaultConfig);
      this._updateStatus(name, "initialized");

      // 2-b. 瓒呮椂鎵ц
      const timeoutMs = ctx.timeoutMs ?? this._defaultTimeout;
      await this._withTimeout(plugin.execute(ctx), timeoutMs, ctx.signal);

      // 2-c. 璇诲彇鍑轰骇鍑篭n      const output = ctx.output as T | undefined;

      // 2-d. 閿€姣佹彃浠讹紙娓呯悊鍐呴儴璧勬簮锛塡n      await plugin.destroy();

      // 鈹€鈹€鈹€鈹€ 闃舵鈶? 鏀跺熬 鈹€鈹€鈹€鈹€
      this._updateStatus(name, "destroyed");

      return {
        success: true,
        output,
        durationMs: Date.now() - startTime,
      };
    } catch (err) {
      // 鈿狅笍 寮傚父闅旂锛氫换浣曢樁娈电殑寮傚父鍧囧湪姝ゆ崟鑾凤紝涓嶆姏鍒颁笂灞俓n
      const errorMessage = err instanceof Error ? err.message : String(err);

      // 灏濊瘯閿€姣佹彃浠讹紙鍗充娇鎵ц澶辫触涔熻娓呯悊璧勬簮锛塡n      try {
        await plugin.destroy();
      } catch {
        // 閿€姣佸け璐ヤ笉褰卞搷涓绘祦绋嬧€斺€旈潤榛樺拷鐣n      }

      // 鏇存柊鐘舵€?鈫?error
      this._updateStatus(name, "error", errorMessage);

      return {
        success: false,
        error: errorMessage,
        durationMs: Date.now() - startTime,
      };
    }
  }

  /**
   * 鎵归噺鎵ц鎵€鏈夊凡娉ㄥ唽鐨勬彃浠躲€俓n   *
   * 鎵ц绛栫暐锛歕n   * - 璋冪敤 `registry.resolveDependencies()` 鑾峰彇鎷撴墤鎺掑簭鎵规
   * - **鍚屾壒娆?*鍐呮彃浠舵棤鐩镐簰渚濊禆锛?*骞惰**鎵ц
   * - **鎵规闂?*蹇呴』涓茶锛堝墠涓€鎵瑰叏閮ㄥ畬鎴愬悗鍐嶆墽琛屼笅涓€鎵癸級
   * - 鍗曚釜鎻掍欢鐨勫け璐ヤ笉浼氬奖鍝嶅悓鎵规鍏朵粬鎻掍欢鐨勬墽琛孿n   *
   * @param ctx 鈥?鎵ц涓婁笅鏂囷紙鎵€鏈夋彃浠跺叡浜級
   * @returns ExecutionReport 鈥?鎵归噺鎵ц鎶ュ憡
   */
  async executeAll(ctx: ExecuteContext): Promise<ExecutionReport> {
    const startTime = Date.now();
    const results = new Map<string, PluginResult>();

    // 鑾峰彇鎷撴墤鎺掑簭鎵规
    const batches = this._registry.resolveDependencies();

    for (const batch of batches) {
      // 鍚屾壒娆″唴鎻掍欢骞惰鎵ц
      const batchResults = await Promise.allSettled(
        batch.map((plugin) => this.execute(plugin.name, ctx)),
      );

      // 鏀堕泦缁撴灉
      for (let i = 0; i < batch.length; i++) {
        const pluginName = batch[i].name;
        const settled = batchResults[i];

        if (settled.status === "fulfilled") {
          results.set(pluginName, settled.value);
        } else {
          // Promise.allSettled 鐞嗚涓婁笉浼氳蛋鍒?rejected 鍒嗘敮锛孿n          // 鍥犱负 execute() 鑷韩 catch 浜嗘墍鏈夊紓甯搞€俓n          // 姝ゅ浣滀负闃插尽寮忓厹搴曘€俓n          const reason = settled.reason;
          results.set(pluginName, {
            success: false,
            error: reason instanceof Error ? reason.message : String(reason),
            durationMs: Date.now() - startTime,
          });
        }
      }
    }

    const allResults = Array.from(results.values());
    const succeeded = allResults.filter((r) => r.success).length;
    const failed = allResults.filter((r) => !r.success).length;

    return {
      total: allResults.length,
      succeeded,
      failed,
      results,
      totalDurationMs: Date.now() - startTime,
    };
  }

  /**
   * 鑾峰彇鎸囧畾鎻掍欢鐨勮繍琛屾椂鐘舵€併€俓n   *
   * @param name 鈥?鎻掍欢鍚嶇О
