   */
  getStatus(name: string): PluginStatus | undefined {
    return this._statuses.get(name);
  }

  /**
   * 浼橀泤鍏抽棴杩愯鍣ㄣ€俓n   *
   * 鎵ц浠ヤ笅娓呯悊鎿嶄綔锛歕n   * 1. 璋冪敤鎵€鏈夊凡娉ㄥ唽鎻掍欢鐨?`destroy()`锛堝紓甯搁殧绂伙紝閫愪釜灏濊瘯锛塡n   * 2. 娓呯悊鏈繍琛屽櫒鍒涘缓鐨勪复鏃跺伐浣滅洰褰昞n   * 3. 娓呯┖杩愯鏃剁姸鎬佽拷韪猏n   */
  async shutdown(): Promise<void> {
    // 1. 閿€姣佹墍鏈夊凡娉ㄥ唽鎻掍欢
    const allPlugins = this._registry.getAll();
    await Promise.allSettled(allPlugins.map((p) => p.destroy()));

    // 2. 娓呯悊鏈繍琛屽櫒鍒涘缓鐨勪复鏃跺伐浣滅洰褰昞n    const cleanupTasks: Promise<void>[] = [];
    for (const dir of this._ownedWorkDirs) {
      cleanupTasks.push(
        rm(dir, { recursive: true, force: true }).catch(() => {
          // 鍗曚釜鐩綍娓呯悊澶辫触 鈥?闈欓粯蹇界暐
        }),
      );
    }
    await Promise.allSettled(cleanupTasks);
    this._ownedWorkDirs.clear();

    // 3. 娓呯┖鐘舵€佽拷韪猏n    this._statuses.clear();
  }

  // 鈹€鈹€ 鍐呴儴鏂规硶 鈹€鈹€

  /**
   * 瓒呮椂鎺у埗銆俓n   *
   * 浣跨敤 Promise.race 瀹炵幇瓒呮椂鍒囨柇銆傝嫢瓒呮椂鍙戠敓锛岃繑鍥炵殑 Promise 浼?reject
   * 骞堕檮甯﹁秴鏃堕敊璇俊鎭€俓n   *
   * 鏀寔澶栭儴 AbortSignal锛氳嫢澶栭儴 signal 鍏堣Е鍙戯紝鍒欎互鍙栨秷閿欒浼樺厛杩斿洖銆俓n   *
   * @param promise 鈥?瑕佹墽琛岀殑寮傛鎿嶄綔
   * @param ms 鈥?瓒呮椂鏃堕棿锛堟绉掞級
   * @param signal 鈥?澶栭儴涓淇″彿锛堝彲閫夛級
   * @returns 鍘熷 Promise 鐨?resolve 鍊糪n   */
  private _withTimeout<T>(
    promise: Promise<T>,
    ms: number,
    signal?: AbortSignal,
  ): Promise<T> {
    // 鑻?ms 鈮?0锛岀洿鎺ヨ繑鍥炲師濮?promise锛堜笉璁捐秴鏃讹級
    if (ms <= 0) {
      return promise;
    }

    const controller = new AbortController();

    // 鍚堝苟澶栭儴 signal 鍜屽唴閮?controller
    const combinedSignal = signal
      ? AbortSignal.any([signal, controller.signal])
      : controller.signal;

    return new Promise<T>((resolve, reject) => {
      let settled = false;

      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        controller.abort();
        reject(new Error(`[PluginRunner] 鎵ц瓒呮椂 (${ms}ms)`));
      }, ms);

      // 鐩戝惉涓淇″彿锛堝閮ㄥ彇娑堟垨瓒呮椂鍙栨秷锛塡n      const onAbort = () => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        reject(new Error("[PluginRunner] 宸查€氳繃 AbortSignal 鍙栨秷"));
      };

      if (combinedSignal.aborted) {
        onAbort();
        return;
      }

      combinedSignal.addEventListener("abort", onAbort, { once: true });

      // 鍘熷 promise 瀹屾垚
      promise.then(
        (val) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          combinedSignal.removeEventListener("abort", onAbort);
          resolve(val);
        },
        (err) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          combinedSignal.removeEventListener("abort", onAbort);
          reject(err);
        },
      );
    });
  }

  /**
   * 鏇存柊鎻掍欢鐨勮繍琛屾椂鐘舵€併€俓n   *
   * 缁存姢 `_statuses` 鏄犲皠锛岀粺璁℃墽琛屾鏁般€佸け璐ユ鏁般€佹渶杩戦敊璇瓑銆俓n   *
   * @param name 鈥?鎻掍欢鍚嶇О
   * @param phase 鈥?褰撳墠鐢熷懡鍛ㄦ湡闃舵
   * @param lastError 鈥?鏈€杩戦敊璇俊鎭紙phase="error" 鏃跺繀濉級
   */
  private _updateStatus(
    name: string,
    phase: PluginStatus["phase"],
    lastError?: string,
  ): void {
    const current = this._statuses.get(name);
    const now = Date.now();

    const newStatus: PluginStatus = {
      name,
      phase,
      lastExecutedAt:
        phase === "running" || phase === "initialized"
          ? now
          : current?.lastExecutedAt,
      executionCount:
        (current?.executionCount ?? 0) + (phase === "running" ? 1 : 0),
      failureCount:
        (current?.failureCount ?? 0) + (phase === "error" ? 1 : 0),
      lastError,
      healthy: phase !== "error",
    };

    this._statuses.set(name, newStatus);
  }
}

