   * @returns 閿欒淇℃伅鏁扮粍
   */
  validate(value: unknown, path?: string): ValidationErrors;

  /**
   * 灏嗗綋鍓嶆牎楠屽櫒鏍囪涓哄彲閫夈€俓n   * 鍙€夊瓧娈靛厑璁?undefined 鍜?null锛堜絾涓嶅厑璁哥己澶?key锛夈€俓n   */
  optional(): TypeValidator<T | undefined>;

  /**
   * 灏嗗綋鍓嶆牎楠屽櫒鏍囪涓哄彲绌恒€俓n   * 鍙┖瀛楁鍏佽 null銆俓n   */
  nullable(): TypeValidator<T | null>;

