/**
 * StringValidator 鈥斺€?瀛楃涓叉牎楠屽櫒銆俓n */
export class StringValidator implements TypeValidator<string> {
  private _minLength?: number;
  private _maxLength?: number;
  private _pattern?: RegExp;
  private _patternMessage?: string;
  private _optional = false;
  private _nullable = false;
  private _trimmed = false;
  private _description?: string;

  /** @internal */
  validate(value: unknown, path = ""): ValidationErrors {
    if (value === undefined) {
      return this._optional ? [] : [`${path}: 蹇呭～`];
    }
    if (value === null) {
      return this._nullable ? [] : [`${path}: 涓嶈兘涓?null`];
    }

    if (typeof value !== "string") {
      return [typeError(path, "string", typeOf(value))];
    }

    const str = this._trimmed ? value.trim() : value;

    const errors: ValidationErrors = [];

    if (this._minLength !== undefined && str.length < this._minLength) {
      errors.push(`${path}: 闀垮害涓嶈兘灏忎簬 ${this._minLength}锛堝綋鍓?${str.length}锛塦);
    }

    if (this._maxLength !== undefined && str.length > this._maxLength) {
      errors.push(`${path}: 闀垮害涓嶈兘澶т簬 ${this._maxLength}锛堝綋鍓?${str.length}锛塦);
    }

    if (this._pattern && !this._pattern.test(str)) {
      errors.push(`${path}: ${this._patternMessage ?? `涓嶅尮閰嶆ā寮?${this._pattern}`}`);
    }

    return errors;
  }

  // 鈹€鈹€ 閾惧紡绾︽潫 鈹€鈹€

  /** 璁剧疆鏈€灏忛暱搴︺€?*/
  min(len: number): this {
    this._minLength = len;
    return this;
  }

  /** 璁剧疆鏈€澶ч暱搴︺€?*/
  max(len: number): this {
    this._maxLength = len;
    return this;
  }

  /** 璁剧疆姝ｅ垯妯″紡鍖归厤銆?*/
  pattern(regex: RegExp, message?: string): this {
    this._pattern = regex;
    this._patternMessage = message;
    return this;
  }

  /** 鏍囪涓哄繀濉紙榛樿琛屼负锛屾樉寮忓０鏄庯級銆?*/
  required(): this {
    this._optional = false;
    return this;
  }

  /** 鏍囪涓哄彲閫夈€?*/
  optional(): this {
    this._optional = true;
    return this;
  }

  /** 鏍囪涓哄彲绌恒€?*/
  nullable(): this {
    this._nullable = true;
    return this;
  }

  /** 娣诲姞鎻忚堪銆?*/
  describe(description: string): this {
    this._description = description;
    return this;
  }

  /** 鑾峰彇鎻忚堪銆?*/
  getDescription(): string | undefined {
    return this._description;
  }

  // 鈹€鈹€ 璇箟蹇嵎鏂瑰紡 鈹€鈹€

  /** 鍖归厤 email 鏍煎紡銆?*/
  email(): this {
    return this.pattern(
      /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
      "鏍煎紡蹇呴』涓烘湁鏁?email 鍦板潃",
    );
  }

  /** 鍖归厤 URL 鏍煎紡銆?*/
  url(): this {
    return this.pattern(
      /^(https?:\/\/)?[\w-]+(\.[\w-]+)+[/#?]?.*$/,
      "鏍煎紡蹇呴』涓烘湁鏁?URL",
    );
  }

  /** 鍖归厤 UUID v4 鏍煎紡銆?*/
  uuid(): this {
    return this.pattern(
      /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i,
      "鏍煎紡蹇呴』涓烘湁鏁?UUID v4",
    );
  }

  /** 闈炵┖瀛楃涓诧紙闀垮害 鈮?1锛夈€?*/
  nonEmpty(): this {
    return this.min(1);
  }

  /** 鍘婚櫎棣栧熬绌虹櫧鍚庢牎楠屻€?*/
  trimmed(): this {
    this._trimmed = true;
    return this;
  }
}

/**
 * NumberValidator 鈥斺€?鏁板瓧鏍￠獙鍣ㄣ€俓n */
export class NumberValidator implements TypeValidator<number> {
  private _min?: number;
  private _max?: number;
  private _integer = false;
  private _positive = false;
  private _optional = false;
  private _nullable = false;
