    if (this._positive && value <= 0) {
      errors.push(`${path}: 蹇呴』涓烘鏁帮紙褰撳墠 ${value}锛塦);
    }

    if (this._min !== undefined && value < this._min) {
      errors.push(`${path}: 涓嶈兘灏忎簬 ${this._min}锛堝綋鍓?${value}锛塦);
    }

    if (this._max !== undefined && value > this._max) {
      errors.push(`${path}: 涓嶈兘澶т簬 ${this._max}锛堝綋鍓?${value}锛塦);
    }

    return errors;
  }

  // 鈹€鈹€ 閾惧紡绾︽潫 鈹€鈹€

  /** 璁剧疆鏈€灏忓€硷紙鍖呭惈锛夈€?*/
  min(n: number): this {
