  max(n: number): this {
    this._max = n;
    return this;
  }

  /** 闄愬埗涓烘暣鏁般€?*/
  integer(): this {
    this._integer = true;
    return this;
  }

  /** 闄愬埗涓烘鏁?(> 0)銆?*/
  positive(): this {
    this._positive = true;
    return this;
  }

  /** 鏍囪涓哄繀濉€?*/
  required(): this {
    this._optional = false;
    return this;
  }

  /** 鏍囪涓哄彲閫夈€?*/
  optional(): this {
    this._optional = true;
    return this;
  }

  /** 鏍囪涓哄彲绌恒€?*/
  nullable(): this {
    this._nullable = true;
    return this;
  }

  /** 娣诲姞鎻忚堪銆?*/
  describe(description: string): this {
    this._description = description;
    return this;
  }

  /** 鑾峰彇鎻忚堪銆?*/
  getDescription(): string | undefined {
    return this._description;
  }
}

