  /** @internal */
  validate(value: unknown, path = ""): ValidationErrors {
    if (value === undefined) {
      return this._optional ? [] : [`${path}: 蹇呭～`];
    }
    if (value === null) {
      return this._nullable ? [] : [`${path}: 涓嶈兘涓?null`];
    }

    if (!Array.isArray(value)) {
      return [typeError(path, "array", typeOf(value))];
