    const errors: ValidationErrors = [];

    if (this._minLength !== undefined && value.length < this._minLength) {
      errors.push(`${path}: 闀垮害涓嶈兘灏忎簬 ${this._minLength}锛堝綋鍓?${value.length}锛塦);
