}

// 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲
// 棰勫畾涔?Schema 妯℃澘
// 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲

/**
 * 閫氱敤鎻掍欢閰嶇疆 Schema銆俓n *
 * 鎻忚堪鏍囧噯鐨?PluginConfig 缁撴瀯锛歕n * ```json
 * {
 *   "enabled": true,
 *   "timeout": 30000,
 *   "env": { "API_KEY": "xxx" }
 * }
 * ```
 *
 * 鎵€鏈夌户鎵?PluginConfig 鐨勯厤缃潎鍙敤姝?schema 鍋氬熀纭€鏍￠獙锛孿n * 鍐嶉€氳繃 `baseConfigSchema.extend(...)` 鎵╁睍鑷畾涔夊瓧娈点€俓n */
export const baseConfigSchema = s.object({
  enabled: s.boolean().optional(),
  timeout: s.number().min(0).max(300_000).optional(),
  env: s.record(s.string()).optional(),
});

/**
 * 涓ユ牸妯″紡閰嶇疆 Schema 鈥斺€?涓嶅厑璁搁澶栧瓧娈点€俓n */
export const strictConfigSchema = baseConfigSchema.strict();

/**
 * 榛樿鎻掍欢 Schema 鈥斺€?閫傜敤浜庣粷澶у鏁版彃浠躲€俓n *
 * 浠呮牎楠屾爣鍑?PluginConfig 瀛楁锛屼笉鏍￠獙 input/output銆俓n */
export const defaultPluginSchema: PluginSchema = defineConfigSchema(
  "default",
  baseConfigSchema,
);

/**
 * 鍒涘缓涓€涓甫鏈夋渶灏忛厤缃姹傜殑閫氱敤 PluginSchema銆俓n *
 * @param name 鈥?鎻掍欢鍚嶇О
 * @param requiredFields 鈥?蹇呭～瀛楁鍒楄〃
 * @returns PluginSchema
 */
export function createMinimalSchema(
  name: string,
  requiredFields: string[] = [],
): PluginSchema {
  const shape: Record<string, TypeValidator> = {
    enabled: s.boolean().optional(),
    timeout: s.number().min(0).max(300_000).optional(),
  };

  for (const field of requiredFields) {
    shape[field] = s.any().describe(`蹇呭～瀛楁: ${field}`);
  }

  return defineConfigSchema(
    name,
    s.object(shape) as TypeValidator<Record<string, unknown>>,
  );
}

// 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲
// 宸ュ叿鍑芥暟
// 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲

/**
 * 灏嗗涓?PluginSchema 鍚堝苟涓轰竴涓鍚?Schema銆俓n *
 * 鍚堝苟瑙勫垯锛歕n * - validateConfig: 鎵€鏈夊瓙 schema 鐨勬牎楠岀粨鏋滃悎骞禱n * - validateInput: 鍙栫涓€涓畾涔変簡 validateInput 鐨勫瓙 schema
 * - validateOutput: 鍙栫涓€涓畾涔変簡 validateOutput 鐨勫瓙 schema
 *
 * @param name 鈥?澶嶅悎 schema 鍚嶇О
 * @param schemas 鈥?瀛?schema 鍒楄〃
 * @returns 澶嶅悎 PluginSchema
 */
export function composeSchemas(
  name: string,
  ...schemas: PluginSchema[]
): PluginSchema {
  return {
    name,
    validateConfig(config: unknown): string[] {
      const errors: string[] = [];
      for (const schema of schemas) {
        errors.push(...schema.validateConfig(config));
      }
      return errors;
    },
    validateInput(input: unknown): string[] {
      for (const schema of schemas) {
        if (schema.validateInput) {
          return schema.validateInput(input);
        }
      }
      return [];
    },
    validateOutput(output: unknown): string[] {
      for (const schema of schemas) {
        if (schema.validateOutput) {
          return schema.validateOutput(output);
        }
      }
      return [];
    },
  };
}

/**
 * 鏍￠獙缁撴灉宸ュ叿鍑芥暟銆俓n */
export const validation = {
  /**
   * 蹇€熸牎楠屽苟杩斿洖甯冨皵鍊笺€俓n   */
  isValid(validator: TypeValidator, value: unknown): boolean {
    return validator.validate(value).length === 0;
  },

  /**
   * 鏍￠獙澶辫触鏃舵姏鍑?Error銆俓n   */
  assert(
    validator: TypeValidator,
    value: unknown,
    label = "value",
  ): void {
    const errors = validator.validate(value);
    if (errors.length > 0) {
      throw new Error(`[Schema] ${label} 鏍￠獙澶辫触:\n  - ${errors.join("\n  - ")}`);
    }
  },

  /**
   * 鏍煎紡鍖栭敊璇垪琛ㄤ负浜虹被鍙瀛楃涓层€俓n   */
  formatErrors(errors: string[]): string {
    if (errors.length === 0) return "鏍￠獙閫氳繃";
    return `鏍￠獙澶辫触 (${errors.length} 椤?:\n${errors.map((e) => `  - ${e}`).join("\n")}`;
  },
};

