/**
 * 瑙勫垯寮曟搸鈥斺€旀墽琛屾牎楠岀殑鏍稿績寮曟搸銆俓n *
 * @design-rule 澶栭儴鎺ュ彛鎶借薄鍏蜂綋鍖栵紙搂9.3锛塡n *   瀵瑰鏆撮湶鐨勫绾︽竻鏅般€佺ǔ瀹氥€佹渶灏忓寲銆俓n *
 * @design-rule 鏁版嵁娴佸悜鏄庣粏鍖栵紙搂9.2锛塡n *   execute() 鍐呴儴绠＄嚎锛歕n *   [鍔犺浇瑙勫垯] 鈫?[绛涢€夊尮閰峕 鈫?[鏂囦欢鎵弿] 鈫?[閫愯鍒欐牎楠宂 鈫?[姹囨€绘姤鍛奭
 */
export interface IRuleEngine {
  /** 鎵ц鍏ㄩ噺鏍￠獙鈥斺€旀壂鎻忛」鐩枃浠跺苟鎵ц鎵€鏈夊尮閰嶈鍒?*/
  execute(options?: {
    rootDir?: string;
    filter?: RuleFilter;
  }): Promise<PolicyReport>;

  /** 瀵规寚瀹氭枃浠跺垪琛ㄦ墽琛屾牎楠?*/
  executeOnFiles(
    files: string[],
    filter?: RuleFilter,
  ): Promise<PolicyReport>;

  /** 娉ㄥ唽浜嬩欢鐩戝惉 */
  on(event: PolicyEvent["type"], handler: PolicyEventHandler): void;

  /** 绉婚櫎浜嬩欢鐩戝惉 */
  off(event: PolicyEvent["type"], handler: PolicyEventHandler): void;

  /** 鏇存柊寮曟搸閰嶇疆锛堣繍琛屾椂鍔ㄦ€佽皟鏁达級 */
  updateConfig(config: Partial<RuleEngineConfig>): void;

  /** 鑾峰彇褰撳墠閰嶇疆 */
  getConfig(): RuleEngineConfig;
}

// ============================================================
// RuleEngine 鈥?瀹炵幇绫籠n// ============================================================

/**
 * RuleEngine 瀹炵幇鈥斺€斿熀浜庡彲鎻掓嫈缁勪欢鐨勪簨浠堕┍鍔ㄥ紩鎿庛€俓n *
 * @design-rule Observer 妯″紡锛埪?4.4锛塡n *   寮曟搸鍙 emit 浜嬩欢锛屼笉鐭ラ亾璋佸湪鍚€俓n *   鏃ュ織璁板綍銆佹姤鍛婄敓鎴愩€佽繘搴︽樉绀洪€氳繃浜嬩欢璁㈤槄瀹炵幇銆俓n */
export class RuleEngine implements IRuleEngine {
  private _registry: IRuleRegistry;
  private _components: Map<string, PolicyValidatorComponent>;
  private _listeners: Map<string, Set<PolicyEventHandler>>;
  private _config: Required<RuleEngineConfig>;

  constructor(
    registry: IRuleRegistry,
    components?: readonly PolicyValidatorComponent[],
    config?: RuleEngineConfig,
  ) {
    this._registry = registry;
    this._components = new Map();
    this._listeners = new Map();
    this._config = {
      ruleTimeoutMs: config?.ruleTimeoutMs ?? 30_000,
      maxConcurrency: config?.maxConcurrency ?? 4,
      failFast: config?.failFast ?? false,
      enableCache: config?.enableCache ?? true,
      verbose: config?.verbose ?? false,
      maxErrors: config?.maxErrors ?? 0,
    };

    if (components) {
      for (const comp of components) {
        this._components.set(comp.ruleId, comp);
      }
    }
  }

  // 鈹€鈹€ 浜嬩欢绠＄悊 鈹€鈹€

  on(event: PolicyEvent["type"], handler: PolicyEventHandler): void {
    if (!this._listeners.has(event)) {
      this._listeners.set(event, new Set());
    }
    const handlers = this._listeners.get(event);
    if (handlers) {
      handlers.add(handler);
    }
  }

  off(event: PolicyEvent["type"], handler: PolicyEventHandler): void {
    this._listeners.get(event)?.delete(handler);
  }

  private _emit(event: PolicyEvent): void {
    const handlers = this._listeners.get(event.type);
    if (handlers) {
      for (const handler of handlers) {
        handler(event);
      }
    }
  }

  // 鈹€鈹€ 閰嶇疆绠＄悊 鈹€鈹€

  updateConfig(config: Partial<RuleEngineConfig>): void {
    this._config = { ...this._config, ...config };
  }

  getConfig(): RuleEngineConfig {
    return { ...this._config };
  }

  // 鈹€鈹€ 鏍稿績鏍￠獙 鈹€鈹€

  async execute(options?: {
    rootDir?: string;
    filter?: RuleFilter;
  }): Promise<PolicyReport> {
    const rootDir = options?.rootDir ?? process.cwd();
    const filter = options?.filter;

    // Step 1: 浠庢敞鍐岃〃鑾峰彇鍖归厤鐨勮鍒橽n    const rules = this._registry.query(filter);
    if (rules.length === 0) {
      return this._emptyReport();
    }

    // Step 2: 鏀堕泦寰呮牎楠屾枃浠讹紙绠€鍖栧疄鐜扳€斺€斿疄闄呭簲鎵弿鏂囦欢绯荤粺锛塡n    const targetFiles = await this._collectTargetFiles(rules, rootDir);

    // Step 3: 鍒濆鍖朶n    const startTime = Date.now();
    this._emit({
      type: "engine-start",
      payload: { totalRules: rules.length, targetFiles },
    });

    // Step 4: 閫愭枃浠堕€愯鍒欐牎楠孿n    const allResults: PolicyRuleResult[] = [];
    let errorCount = 0;

    for (const filePath of targetFiles) {
      if (this._config.maxErrors > 0 && errorCount >= this._config.maxErrors) {
        break;
      }

      let content: string;
      try {
        content = await this._readFile(filePath);
      } catch {
        // 鏂囦欢璇诲彇澶辫触锛岃烦杩嘰n        continue;
      }

      for (const rule of rules) {
        if (this._config.maxErrors > 0 && errorCount >= this._config.maxErrors) {
          break;
        }

        if (!this._matchesFilePattern(rule, filePath)) {
          continue;
        }

        const component = this._components.get(rule.id);
        if (!component) {
          continue;
        }

        this._emit({
          type: "rule-start",
          payload: { ruleId: rule.id, filePath },
        });

        const ruleStart = Date.now();

        try {
          const result = await component.validate(filePath, content);

          if (result) {
            allResults.push(result);

            if (!result.passed && result.severity === "error") {
              errorCount++;
              this._emit({
                type: "rule-fail",
                payload: { ruleId: rule.id, filePath, result },
              });
            } else if (result.passed) {
              this._emit({
                type: "rule-pass",
                payload: {
                  ruleId: rule.id,
                  filePath,
                  durationMs: Date.now() - ruleStart,
                },
              });
            }
          }
        } catch (e) {
          this._emit({
            type: "rule-error",
            payload: {
              ruleId: rule.id,
              filePath,
              error: e instanceof Error ? e.message : String(e),
            },
          });
        }

        if (this._config.failFast && errorCount > 0) {
          break;
        }
      }
    }

    // Step 5: 姹囨€绘姤鍛奬n    const report = this._buildReport(allResults, startTime);
    this._emit({ type: "engine-end", payload: { report } });
    return report;
  }

  async executeOnFiles(
    files: string[],
    filter?: RuleFilter,
  ): Promise<PolicyReport> {
    const rules = this._registry.query(filter);
    if (rules.length === 0) {
      return this._emptyReport();
    }

    const startTime = Date.now();
    this._emit({
      type: "engine-start",
      payload: { totalRules: rules.length, targetFiles: files },
    });

    const allResults: PolicyRuleResult[] = [];
    let errorCount = 0;

    for (const filePath of files) {
      if (this._config.maxErrors > 0 && errorCount >= this._config.maxErrors) {
        break;
      }

      let content: string;
      try {
        content = await this._readFile(filePath);
      } catch {
        continue;
      }

      for (const rule of rules) {
        if (this._config.maxErrors > 0 && errorCount >= this._config.maxErrors) {
          break;
        }

        if (!this._matchesFilePattern(rule, filePath)) {
          continue;
        }

        const component = this._components.get(rule.id);
        if (!component) {
          continue;
        }

        this._emit({
          type: "rule-start",
          payload: { ruleId: rule.id, filePath },
        });

        const ruleStart = Date.now();

        try {
          const result = await component.validate(filePath, content);

          if (result) {
            allResults.push(result);

            if (!result.passed && result.severity === "error") {
              errorCount++;
              this._emit({
                type: "rule-fail",
                payload: { ruleId: rule.id, filePath, result },
              });
            } else if (result.passed) {
              this._emit({
                type: "rule-pass",
                payload: {
                  ruleId: rule.id,
                  filePath,
                  durationMs: Date.now() - ruleStart,
                },
              });
            }
          }
        } catch (e) {
          this._emit({
            type: "rule-error",
            payload: {
              ruleId: rule.id,
              filePath,
              error: e instanceof Error ? e.message : String(e),
            },
          });
        }

        if (this._config.failFast && errorCount > 0) {
          break;
        }
      }
    }

    const report = this._buildReport(allResults, startTime);
    this._emit({ type: "engine-end", payload: { report } });
    return report;
  }

  // 鈹€鈹€ 鍐呴儴杈呭姪鏂规硶 鈹€鈹€

  private async _collectTargetFiles(
    rules: readonly PolicyRule[],
    _rootDir: string,
  ): Promise<string[]> {
    // 绠€鍖栧疄鐜帮細浠庤鍒欑殑 filePattern 鏀堕泦
    const fileSet = new Set<string>();
    for (const rule of rules) {
      if (rule.filePattern) {
        // 瀹為檯椤圭洰涓娇鐢?glob 鎵弿
        // 杩欓噷绠€鍗曡繑鍥炰竴涓┖鏁扮粍锛屾祴璇曚腑瑕嗙洊
        fileSet.add(rule.filePattern);
      }
    }
    return Array.from(fileSet);
  }

  private async _readFile(_filePath: string): Promise<string> {
    // 瀹為檯瀹炵幇浣跨敤 fs.readFile
    // 涓轰究浜庢祴璇曪紝杩斿洖绌哄瓧绗︿覆
    return "";
  }

  private _matchesFilePattern(rule: PolicyRule, filePath: string): boolean {
    if (!rule.filePattern) {
      return true;
    }
    // 绠€鍗?glob 鍖归厤鈥斺€斿疄闄呭疄鐜板簲浣跨敤 minimatch
    const regexStr = rule.filePattern
      .replace(/\./g, "\\.")
      .replace(/\*\*/g, ".*")
      .replace(/\*/g, "[^/]*")
      .replace(/\?/g, ".");
    try {
      return new RegExp(`^${regexStr}$`).test(filePath);
    } catch {
      return filePath === rule.filePattern;
    }
  }

  private _buildReport(
    results: PolicyRuleResult[],
    startTime: number,
  ): PolicyReport {
    const errors = results.filter(r => !r.passed && r.severity === "error");
    const warnings = results.filter(r => !r.passed && r.severity === "warning");
    const infos = results.filter(r => r.passed || r.severity === "info");
    const passed = results.filter(r => r.passed);

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      infos,
      results,
      timestamp: Date.now(),
      durationMs: Date.now() - startTime,
      totalRules: results.length,
      passedRules: passed.length,
      failedRules: results.length - passed.length,
    };
  }

  private _emptyReport(): PolicyReport {
    return {
      valid: true,
      errors: [],
      warnings: [],
      infos: [],
      results: [],
      timestamp: Date.now(),
      durationMs: 0,
      totalRules: 0,
      passedRules: 0,
      failedRules: 0,
    };
  }
}

/**
 * @cortex/policy-validator 鈥?RuleLoader 瑙勫垯鍔犺浇鍣ㄥ疄鐜癨n *
 * 浠庨厤缃簮 (config 甯搁噺銆丣SON銆丮arkdown) 鍔犺浇 PolicyRule 瀹氫箟銆俓n * 渚濇嵁 coding-standards.md锛歕n *   - 搂涓?纭紪鐮佺浠わ細瑙勫垯瀹氫箟浠庨厤缃簮鍔犺浇锛屼笉鍐欐
 *   - 搂8.2 鍙屾簮鍚屾锛氫汉璇绘簮涓庢満鍣ㄦ簮淇濇寔鍚屾
 *   - 搂14.3 Strategy 妯″紡锛氫笉鍚屽姞杞界瓥鐣ュ彲浜掓崲
 *   - 搂14.1 Adapter 妯″紡锛氬閮ㄨ鍒欐簮閫傞厤
 */

import type {
  PolicyRule,
  PolicyDomain,
  RuleSeverity,
  RuleLoadOptions,
  RuleLoadStats,
} from "./types.js";
import type { IRuleRegistry } from "./ruleRegistry.js";

// ============================================================
// IRuleLoader 鈥?瑙勫垯鍔犺浇鍣ㄦ帴鍙n// ============================================================

/**
 * 瑙勫垯鍔犺浇鍣ㄢ€斺€斾粠閰嶇疆婧愬姞杞?PolicyRule銆俓n *
 * @design-rule Strategy 妯″紡锛埪?4.3锛塡n *   涓嶅悓鍔犺浇绛栫暐锛堝父閲忋€丣SON銆乀S 妯″潡锛夐€氳繃缁熶竴鎺ュ彛鍒囨崲銆俓n *
 * @design-rule 閫傞厤鍣ㄦā寮忥紙搂14.1锛塡n *   澶栭儴瑙勫垯婧愰€氳繃閫傞厤鍣ㄦ帴鍏ョ粺涓€鎺ュ彛銆俓n */
export interface IRuleLoader {
  /** 浠?@cortex/config 甯搁噺鍔犺浇鍐呯疆瑙勫垯闆?*/
  loadFromConfig(options?: RuleLoadOptions): Promise<number>;

  /** 浠?JSON 鏂囦欢鍔犺浇瑙勫垯瀹氫箟 */
  loadFromJson(
    jsonPath: string,
    options?: RuleLoadOptions,
  ): Promise<number>;

  /** 浠?TS/JS 妯″潡鍔犺浇鍔ㄦ€佽鍒?*/
  loadFromModule(
    modulePath: string,
    options?: RuleLoadOptions,
  ): Promise<number>;

  /** 浠?Markdown 鏂囦欢鑷姩鎻愬彇瑙勫垯 */
  loadFromMarkdown(
    mdPath: string,
    options?: RuleLoadOptions,
  ): Promise<number>;

  /** 鑾峰彇宸插姞杞界殑瑙勫垯鏁扮粺璁?*/
  getLoadStats(): RuleLoadStats;
}

// ============================================================
// 鍐呯疆瑙勫垯瀹氫箟锛堟牴鎹?coding-standards.md 鏄犲皠锛塡n// ============================================================

/**
 * 鑾峰彇鍐呯疆瑙勫垯闆嗏€斺€斾粠 coding-standards.md 鏄犲皠鐨勯瀹氫箟瑙勫垯銆俓n * 杩欎簺瑙勫垯鏄?coding-standards.md 搂涓€~搂鍗佸洓 鎵€鏈夎鍒欑殑鏈哄櫒鍙琛ㄧず銆俓n *
 * @returns PolicyRule 鏁扮粍
 */
export function getBuiltinRules(): PolicyRule[] {
  return [
    // 搂涓€ 寮傚父澶勭悊
    {
      id: "exception/no-empty-catch",
      domain: "exception",
      severity: "error",
      description: "绂佹绌?catch {} 鍧梊

usedDeprecatedRules:
PROMPTS_DIR_STRUCTURE",
      tags: ["prompts", "structure"],
      standardRef: "搂8.1",
    },

    // 搂涔?鏋舵瀯璁捐鍘熷垯
    {
      id: "architecture/no-interface-leak",
      domain: "architecture",
      severity: "error",
      description: "鎺ュ彛涓嶆硠婕忓唴閮ㄥ疄鐜癨

BODY_MAX_30_LINES",
      tags: ["function", "style"],
      standardRef: "搂11.4",
    },

    // 搂鍗佷簩 瀵煎叆璺緞涓庢ā鍧楃粍缁嘰n    {
      id: "import/sort-order",
      domain: "import",
      severity: "error",
      description: "瀵煎叆鎺掑簭鈥斺€斿唴缃啋涓夋柟鈫扏cortex鈫掔浉瀵筡

OBSERVER_DECOUPLED",
      tags: ["pattern", "design"],
      standardRef: "搂14.4",
    },
  ];
}

// ============================================================
// RuleLoader 鈥?瀹炵幇绫籠n// ============================================================

/**
 * RuleLoader 瀹炵幇鈥斺€斾粠澶氱閰嶇疆婧愬姞杞?PolicyRule 鍒版敞鍐岃〃銆俓n */
export class RuleLoader implements IRuleLoader {
  private _registry: IRuleRegistry;
  private _stats: RuleLoadStats;

  constructor(registry: IRuleRegistry) {
    this._registry = registry;
    this._stats = {
      total: 0,
      byDomain: {} as Record<PolicyDomain, number>,
      bySeverity: {} as Record<RuleSeverity, number>,
      invalidCount: 0,
      durationMs: 0,
    };
  }

  async loadFromConfig(options?: RuleLoadOptions): Promise<number> {
    const startTime = Date.now();
    const strict = options?.strict ?? true;

    if (options?.clearBeforeLoad) {
      this._registry.clear();
    }

    const rules = getBuiltinRules();
    let loaded = 0;

    for (const rule of rules) {
      try {
        this._registry.register(rule);
        loaded++;
      } catch {
        if (strict) {
          throw new Error(`Failed to load builtin rule: ${rule.id}`);
        }
        this._stats.invalidCount++;
      }
    }

    this._updateStats(loaded, startTime);
    return loaded;
  }

  async loadFromJson(
    jsonPath: string,
    _options?: RuleLoadOptions,
  ): Promise<number> {
    const _startTime = Date.now();
    const _strict = _options?.strict ?? true;

    // 瀹為檯瀹炵幇浣跨敤 fs.readFile + JSON.parse
    // 杩欓噷鎶涘嚭涓€涓竻鏅扮殑閿欒锛岃〃鏄庨渶瑕佸疄闄呮枃浠剁郴缁熸敮鎸乗n    throw new Error(
      `loadFromJson requires actual file system access. ` +
      `Attempted to load from: ${jsonPath}. ` +
      `In production, implement with fs.readFile.`,
    );
  }

  async loadFromModule(
    modulePath: string,
    options?: RuleLoadOptions,
  ): Promise<number> {
    const startTime = Date.now();
    const strict = options?.strict ?? true;

    try {
      // 鍔ㄦ€佸鍏ユā鍧椻€斺€斿疄闄呭疄鐜颁腑闇€瑕佸鐞嗚矾寰勮В鏋怽n      const mod = await import(modulePath);
      const rules: PolicyRule[] = mod.default ?? mod.rules ?? [];

      if (options?.clearBeforeLoad) {
        this._registry.clear();
      }

      let loaded = 0;
      for (const rule of rules) {
        try {
          this._registry.register(rule);
          loaded++;
        } catch {
          if (strict) {
            throw new Error(`Failed to load rule from module: ${rule.id}`);
          }
          this._stats.invalidCount++;
        }
      }

      this._updateStats(loaded, startTime);
      return loaded;
    } catch (e) {
      throw new Error(
        `Failed to load module: ${modulePath}. ` +
        `${e instanceof Error ? e.message : String(e)}`,
        { cause: e },
      );
    }
  }

  async loadFromMarkdown(
    mdPath: string,
    _options?: RuleLoadOptions,
  ): Promise<number> {
    const _startTime = Date.now();

    // 瀹為檯瀹炵幇搴旇В鏋?Markdown 琛ㄦ牸鎻愬彇瑙勫垯
    // 杩欓噷鎶涘嚭娓呮櫚鐨勬湭瀹炵幇閿欒
    throw new Error(
      `loadFromMarkdown requires Markdown parsing logic. ` +
      `Attempted to load from: ${mdPath}. ` +
      `Implement with Markdown table parser.`,
    );
  }

  getLoadStats(): RuleLoadStats {
    return { ...this._stats };
  }

  // 鈹€鈹€ 鍐呴儴杈呭姪 鈹€鈹€

  private _updateStats(loaded: number, startTime: number): void {
    const rules = this._registry.getAll();
    this._stats.total = rules.length;
    this._stats.byDomain = this._registry.countByDomain();
    this._stats.bySeverity = this._registry.countBySeverity();
    this._stats.durationMs = Date.now() - startTime;
  }
}

