// IRuleRegistry 鈥?瑙勫垯娉ㄥ唽琛ㄦ帴鍙n// ============================================================

/**
 * 瑙勫垯娉ㄥ唽琛ㄢ€斺€旇鍒欑殑闆嗕腑绠＄悊瀹瑰櫒銆俓n *
 * @design-rule 鎺ュ彛闅旂锛埪?3.1锛塡n *   姝ゆ帴鍙ｅ彧鎻忚堪"瑙勫垯鎬庝箞绠＄悊"锛屼笉娑夊強瑙勫垯鎵ц銆俓n *
 * @design-rule 鍗曟簮鐪熺浉
 *   鎵€鏈夋敞鍐岀殑瑙勫垯鏈変笖浠呮湁涓€涓潵婧愨€斺€攔egister/bulkRegister銆俓n *   瑙勫垯涓€缁忔敞鍐岋紝涓嶅彲鍒犻櫎锛堜絾鍙?disable锛夈€俓n */
export interface IRuleRegistry {
  /** 娉ㄥ唽鍗曟潯瑙勫垯 */
  register(rule: PolicyRule): void;

  /** 鎵归噺娉ㄥ唽澶氭潯瑙勫垯 */
  bulkRegister(rules: readonly PolicyRule[]): void;

  /** 鎸?ID 鑾峰彇瑙勫垯 */
  get(ruleId: string): PolicyRule | undefined;

  /** 鎸夌瓫閫夋潯浠舵煡璇㈣鍒?*/
  query(filter?: RuleFilter): readonly PolicyRule[];

  /** 鑾峰彇鎵€鏈夊凡娉ㄥ唽涓旀湭绂佺敤鐨勮鍒?*/
  getAll(): readonly PolicyRule[];

  /** 鑾峰彇鎵€鏈夌瓥鐣ュ煙 */
  getDomains(): readonly PolicyDomain[];

  /** 鑾峰彇鎸囧畾鍩熶笅鐨勮鍒欐暟 */
  countByDomain(): Record<PolicyDomain, number>;

  /** 鎸変弗閲嶇骇鍒鏁?*/
  countBySeverity(): Record<RuleSeverity, number>;

  /** 绂佺敤瑙勫垯锛堜繚鐣欐敞鍐屼絾璺宠繃鎵ц锛?*/
  disable(ruleId: string): void;

  /** 鍚敤瑙勫垯 */
  enable(ruleId: string): void;

  /** 妫€鏌ヨ鍒欐槸鍚﹀凡绂佺敤 */
  isDisabled(ruleId: string): boolean;

  /** 娓呯┖娉ㄥ唽琛?*/
  clear(): void;

  /** 鑾峰彇娉ㄥ唽瑙勫垯鎬绘暟锛堝寘鍚凡绂佺敤鐨勶級 */
  size(): number;
}

// ============================================================
// RuleRegistry 鈥?瀹炵幇绫籠n// ============================================================

/**
 * RuleRegistry 瀹炵幇鈥斺€斿熀浜?Map 鐨勮鍒欐敞鍐岃〃銆俓n *
 * @design-rule 鍐呴儴鏁版嵁娴佸悜鏄庣粏鍖栵紙搂9.2锛塡n *   - register/bulkRegister锛氬啓鍏ヨ矾寰勶紝鍗曚竴鍏ュ彛
 *   - get/query锛氭煡璇㈣矾寰勶紝涓嶅啓鐘舵€乗n *   - disable/enable锛氱姸鎬佸垏鎹紝鏈夋樉寮忕殑寮€鍏宠褰昞n */
export class RuleRegistry implements IRuleRegistry {
  private _rules: Map<string, PolicyRule>;
  private _disabled: Set<string>;

  constructor() {
    this._rules = new Map();
    this._disabled = new Set();
  }

  register(rule: PolicyRule): void {
    if (this._rules.has(rule.id)) {
      throw new Error(`Rule already registered: ${rule.id}`);
    }
    this._rules.set(rule.id, rule);
  }

  bulkRegister(rules: readonly PolicyRule[]): void {
    for (const rule of rules) {
      this.register(rule);
    }
  }

  get(ruleId: string): PolicyRule | undefined {
    return this._rules.get(ruleId);
  }

  query(filter?: RuleFilter): readonly PolicyRule[] {
    const results: PolicyRule[] = [];
    for (const rule of this._rules.values()) {
      if (this._disabled.has(rule.id)) {
        continue;
      }
      if (!this._matchesFilter(rule, filter)) {
        continue;
      }
      results.push(rule);
    }
    return results;
  }

  getAll(): readonly PolicyRule[] {
    return Array.from(this._rules.values())
      .filter(r => !this._disabled.has(r.id));
  }

  getDomains(): readonly PolicyDomain[] {
    const domains = new Set<PolicyDomain>();
    for (const rule of this._rules.values()) {
      domains.add(rule.domain);
    }
    return Array.from(domains);
  }

  countByDomain(): Record<PolicyDomain, number> {
    const counts: Partial<Record<PolicyDomain, number>> = {};
    for (const rule of this._rules.values()) {
      if (this._disabled.has(rule.id)) {
        continue;
      }
      const current = counts[rule.domain] ?? 0;
      counts[rule.domain] = current + 1;
    }
    return counts as Record<PolicyDomain, number>;
  }

  countBySeverity(): Record<RuleSeverity, number> {
    const counts: Record<RuleSeverity, number> = {
      info: 0,
      warning: 0,
      error: 0,
    };
    for (const rule of this._rules.values()) {
      if (this._disabled.has(rule.id)) {
        continue;
      }
      counts[rule.severity]++;
    }
    return counts;
  }

  disable(ruleId: string): void {
    this._disabled.add(ruleId);
  }

  enable(ruleId: string): void {
    this._disabled.delete(ruleId);
  }

  isDisabled(ruleId: string): boolean {
    return this._disabled.has(ruleId);
  }

  clear(): void {
    this._rules.clear();
    this._disabled.clear();
  }

  size(): number {
    return this._rules.size;
  }

  // 鈹€鈹€ 鍐呴儴杈呭姪 鈹€鈹€

  private _matchesFilter(
    rule: PolicyRule,
    filter?: RuleFilter,
  ): boolean {
    if (!filter) {
      return true;
    }

    // 鎸夊煙绛涢€塡n    if (filter.domains && filter.domains.length > 0) {
      if (!filter.domains.includes(rule.domain)) {
        return false;
      }
    }

    // 鎸変弗閲嶇骇鍒瓫閫塡n    if (filter.severities && filter.severities.length > 0) {
      if (!filter.severities.includes(rule.severity)) {
        return false;
      }
    }

    // 鎸夋爣绛剧瓫閫夛紙浠绘剰鍖归厤涓€涓嵆鍙級
    if (filter.tags && filter.tags.length > 0) {
      if (!rule.tags.some(t => (filter.tags ?? []).includes(t))) {
        return false;
      }
    }

    // 鎸?AgentType 绛涢€塡n    if (filter.agentTypes && filter.agentTypes.length > 0) {
      if (!rule.targetAgentTypes ||
          !rule.targetAgentTypes.some(t => (filter.agentTypes ?? []).includes(t))) {
        return false;
      }
    }

    // 鎸夋枃浠舵ā寮忕瓫閫塡n    if (filter.filePattern) {
      if (!rule.filePattern) {
        return false;
      }
      // 绠€鍗曢€氶厤绗﹀尮閰嶁€斺€斿疄闄呭疄鐜板簲浣跨敤 minimatch 绛夊簱
      if (!simpleGlobMatch(rule.filePattern, filter.filePattern)) {
        return false;
      }
    }

    // 鎸夎鍒?ID 绮剧‘鎸囧畾
    if (filter.ruleIds && filter.ruleIds.length > 0) {
      if (!filter.ruleIds.includes(rule.id)) {
        return false;
      }
    }

    return true;
  }
}

/**
 * 绠€鍗曠殑 glob 妯″紡鍖归厤锛堜粎鏀寔 * 閫氶厤绗︼級銆俓n * 瀹為檯瀹炵幇搴斾娇鐢?minimatch 鎴?micromatch 搴撱€俓n */
function simpleGlobMatch(pattern: string, target: string): boolean {
  // 灏?glob 妯″紡杞崲涓烘鍒橽n  const regexStr = pattern
    .replace(/\./g, "\\.")
    .replace(/\*\*/g, ".*")
    .replace(/\*/g, "[^/]*")
    .replace(/\?/g, ".");
  try {
    return new RegExp(`^${regexStr}$`).test(target);
  } catch {
    return pattern === target;
  }
}

/**
 * @cortex/policy-validator 鈥?ExportRule 瀵煎嚭瑙勮寖瑙勫垯
 *
 * 妫€娴嬫ā鍧楀鍑鸿繚鍙嶇殑瑙勫垯锛歕n * - 妫€鏌?barrel 瀵煎嚭鏄惁缂哄け锛堟柊澧炲叕寮€绗﹀彿浣嗘湭鍦?index.ts 涓鍑猴級
 * - 妫€鏌ユ槸鍚︿娇鐢?export default锛堜紭鍏堝懡鍚嶅鍑猴級
 * - 妫€鏌ユ祴璇曟枃浠舵槸鍚︿娇鐢ㄧ浉瀵硅矾寰勫鍏?src/
 *
 * 閫氳繃鏋勯€犲嚱鏁版敞鍏ユ柟寮忓疄鐜帮紙鍙彃鎷旀牎楠岀粍浠讹級銆俓n * 渚濇嵁 coding-standards.md锛歕n *   - 搂鍥?barrel 閾佸緥锛氭柊澧炲叕寮€绗﹀彿椤绘洿鏂?barrel
 *   - 搂鍗?浠ｇ爜瑙勮寖锛氬懡鍚嶅鍑轰紭鍏圽n *   - 搂14.1 Adapter 妯″紡锛氬彲鎻掓嫈缁勪欢
 */

import type { PolicyRule, PolicyRuleResult } from "../types.js";
import type { PolicyValidatorComponent } from "../ruleEngine.js";

// ============================================================
// 瀵煎嚭瑙勫垯閰嶇疆
// ============================================================

/**
 * 瀵煎嚭瑙勫垯閰嶇疆閫夐」銆俓n * 閫氳繃鏋勯€犲嚱鏁版敞鍏ワ紝閬靛惊閰嶇疆椹卞姩寮€鍙戯紙搂涓冿級銆俓n */
export interface ExportRuleOptions {
  /** 鏄惁妫€鏌?export default锛岄粯璁?true */
  readonly checkDefaultExport?: boolean;

  /** 鏄惁妫€鏌ユ祴璇曟枃浠剁浉瀵瑰鍏ワ紝榛樿 true */
  readonly checkTestRelativeImport?: boolean;

  /** 鏄惁妫€鏌?barrel 瀵煎嚭缂哄け锛岄粯璁?true */
  readonly checkBarrelExport?: boolean;

  /** barrel 鏂囦欢妯″紡锛岄粯璁?"**\/index.ts" */
  readonly barrelPattern?: string;
}

// ============================================================
// ExportRule
// ============================================================

/**
 * 瀵煎嚭瑙勮寖鏍￠獙瑙勫垯鈥斺€旀娴嬪鍑虹浉鍏宠繚鍙嶃€俓n *
 * 閫氳繃鏋勯€犲嚱鏁版敞鍏ラ厤缃紝涓嶄緷璧栧叏灞€鐘舵€併€俓n */
export class ExportRule implements PolicyValidatorComponent {
  readonly name = "ExportRule";
  readonly ruleId = "export/convention";

  private _rule: PolicyRule;
  private _options: Required<ExportRuleOptions>;

  constructor(
    rule: PolicyRule,
    options?: ExportRuleOptions,
  ) {
    this._rule = rule;
    this._options = {
      checkDefaultExport: options?.checkDefaultExport ?? true,
      checkTestRelativeImport: options?.checkTestRelativeImport ?? true,
      checkBarrelExport: options?.checkBarrelExport ?? true,
      barrelPattern: options?.barrelPattern ?? "**/index.ts",
    };
  }

  async validate(filePath: string, content: string): Promise<PolicyRuleResult | null> {
    // 鍙鏌?.ts / .tsx 鏂囦欢
    if (!/\.(ts|tsx)$/.test(filePath)) {
      return null;
    }

    const violations: string[] = [];
    const infoMessages: string[] = [];

    // 1. 妫€鏌?export default
    if (this._options.checkDefaultExport) {
      // 璺宠繃 barrel 鏂囦欢鑷韩鐨勬鏌n      if (!filePath.endsWith("/index.ts") && !filePath.endsWith("\\index.ts")) {
        const lines = content.split("\n");
        for (let i = 0; i < lines.length; i++) {
          if (lines[i].includes("export default")) {
            violations.push(`Line ${i + 1}: Prefer named export over export default`);
            break;
          }
        }
      }
    }

    // 2. 妫€鏌ユ祴璇曟枃浠朵腑鐨勭浉瀵瑰鍏n    if (this._options.checkTestRelativeImport) {
      if (filePath.includes("/tests/") || filePath.includes("\\tests\\") || filePath.includes(".test.")) {
        const lines = content.split("\n");
        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          // 鍖归厤 from "../src/" 鎴?from "./../src/" 绛夋ā寮廫n          if (line.match(/from\s+["']\.\.\/src\//) || line.match(/from\s+["']\.\.\/\.\.\/src\//)) {
            violations.push(`Line ${i + 1}: Test file should not use relative import '../src/' 鈥?use package name instead`);
          }
        }
      }
    }

    // 3. 妫€鏌?barrel 瀵煎嚭锛堜粎浣滀负淇℃伅鎻愮ず锛屼笉闃绘柇锛塡n    if (this._options.checkBarrelExport) {
      // 璺宠繃 barrel 鏂囦欢鑷韩
      if (!filePath.endsWith("/index.ts") && !filePath.endsWith("\\index.ts")) {
        // 妫€鏌ユ枃浠舵槸鍚︽湁鍏紑瀵煎嚭
        const publicExports: string[] = [];
        const exportRegex = /^export\s+(?:function|class|interface|type|const|let|var|enum|abstract\s+class)\s+(\w+)/gm;
        let match: RegExpExecArray | null;

        const regex = new RegExp(exportRegex.source, "gm");
        while ((match = regex.exec(content)) !== null) {
          publicExports.push(match[1]);
        }

        // 濡傛灉鏈夊叕寮€瀵煎嚭浣嗘病鏈夊搴旂殑 barrel 鏂囦欢
        if (publicExports.length > 0) {
          const _dir = filePath.substring(0, Math.max(filePath.lastIndexOf("/"), filePath.lastIndexOf("\\")));
          infoMessages.push(
            `Info: File has ${publicExports.length} public export(s): ${publicExports.join(", ")}. ` +
            `Ensure barrel file re-exports them.`,
          );
        }
      }
    }

    // 濡傛灉娌℃湁浠讳綍 violations 鍜?info锛岀洿鎺ヨ繑鍥為€氳繃
    if (violations.length === 0 && infoMessages.length === 0) {
      return {
        ruleId: this.ruleId,
        severity: this._rule.severity,
        passed: true,
        code: this._rule.code,
        filePath,
        rule: this._rule,
      };
    }

    // 鍙湁 info 娌℃湁 violations 鐨勬儏鍐碉細閫氳繃锛屼絾闄勫甫淇℃伅
    if (violations.length === 0 && infoMessages.length > 0) {
      return {
        ruleId: this.ruleId,
        severity: "info",
        passed: true,
        message: infoMessages.join("; "),
        code: this._rule.code,
        filePath,
        rule: this._rule,
      };
    }

    // 鏈?violations锛氬け璐n    return {
      ruleId: this.ruleId,
      severity: this._rule.severity,
      passed: false,
      message: violations.join("; "),
      code: this._rule.code,
      filePath,
      rule: this._rule,
      fixSuggestion: this._rule.fixSuggestion,
    };
  }
}

/**
