/**
 * 鍛藉悕绾﹀畾瑙勫垯閰嶇疆閫夐」銆俓n * 閫氳繃鏋勯€犲嚱鏁版敞鍏ワ紝閬靛惊閰嶇疆椹卞姩寮€鍙戯紙搂涓冿級銆俓n */
export interface NamingConventionOptions {
