/** camelCase: 棣栧瓧姣嶅皬鍐欐垨涓嬪垝绾匡紝鍚庣画瀛楁瘝鏁板瓧 */
const CAMEL_CASE_REGEX = /^_?[a-z][a-zA-Z0-9]*$/;

/** PascalCase: 棣栧瓧姣嶅ぇ鍐欙紝鍚庣画瀛楁瘝鏁板瓧 */
const PASCAL_CASE_REGEX = /^[A-Z][a-zA-Z0-9]*$/;

/** UPPER_SNAKE_CASE: 鍏ㄥぇ鍐欏瓧姣?鏁板瓧锛岃瘝闂翠笅鍒掔嚎鍒嗛殧 */
const UPPER_SNAKE_CASE_REGEX = /^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$/;

/** 绉佹湁瀛楁鍓嶇紑 _ */
const _PRIVATE_FIELD_REGEX = /^_[a-z][a-zA-Z0-9]*$/;

// ============================================================
// NamingConventionRule
// ============================================================

/**
 * 鍛藉悕绾﹀畾鏍￠獙瑙勫垯鈥斺€旀娴嬪懡鍚嶈鑼冭繚鍙嶃€俓n *
 * 閫氳繃鏋勯€犲嚱鏁版敞鍏ラ厤缃紝涓嶄緷璧栧叏灞€鐘舵€併€俓n */
export class NamingConventionRule implements PolicyValidatorComponent {
  readonly name = "NamingConventionRule";
  readonly ruleId = "naming/convention";

  private _rule: PolicyRule;
  private _options: Required<NamingConventionOptions>;

  constructor(
    rule: PolicyRule,
    options?: NamingConventionOptions,
  ) {
    this._rule = rule;
    this._options = {
      checkFunctionCamelCase: options?.checkFunctionCamelCase ?? true,
      checkClassPascalCase: options?.checkClassPascalCase ?? true,
      checkConstantUpperSnakeCase: options?.checkConstantUpperSnakeCase ?? true,
      checkPrivatePrefix: options?.checkPrivatePrefix ?? true,
    };
  }

  async validate(filePath: string, content: string): Promise<PolicyRuleResult | null> {
    // 鍙鏌?.ts / .tsx / .js / .jsx 鏂囦欢
    if (!/\.(ts|tsx|js|jsx)$/.test(filePath)) {
      return null;
    }

    const violations: string[] = [];

    // 鎸夎妫€鏌n    const lines = content.split("\n");

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const lineNumber = i + 1;

      // 妫€鏌ュ嚱鏁板０鏄庡懡鍚嶏紙鍙尮閰?function 鍏抽敭瀛楀０鏄庯紝涓嶅尮閰?const锛塡n      if (this._options.checkFunctionCamelCase) {
        const funcMatch = line.match(/function\s+(\w+)\s*\(/);
        if (funcMatch) {
          const name = funcMatch[1];
          if (!CAMEL_CASE_REGEX.test(name) && !PASCAL_CASE_REGEX.test(name)) {
            violations.push(`Line ${lineNumber}: Function '${name}' should use camelCase or PascalCase`);
          }
        }

        // 妫€鏌ョ澶村嚱鏁板彉閲忓拰鍑芥暟琛ㄨ揪寮忚祴鍊糪n        const arrowMatch = line.match(/(?:const|let|var)\s+(\w+)\s*=\s*(?:\(|async|function)/);
        if (arrowMatch) {
          const name = arrowMatch[1];
          // 璺宠繃鍏ㄥぇ鍐欏父閲忓悕
          if (!/^[A-Z][A-Z0-9_]*$/.test(name)) {
            if (!CAMEL_CASE_REGEX.test(name) && !PASCAL_CASE_REGEX.test(name)) {
              violations.push(`Line ${lineNumber}: Variable '${name}' should use camelCase or PascalCase`);
            }
          }
        }
      }

      // 妫€鏌ョ被鍚峔n      if (this._options.checkClassPascalCase) {
        const classMatch = line.match(/class\s+(\w+)/);
        if (classMatch) {
          const name = classMatch[1];
          if (!PASCAL_CASE_REGEX.test(name)) {
            violations.push(`Line ${lineNumber}: Class '${name}' should use PascalCase`);
          }
        }
      }

      // 妫€鏌ュ父閲忓懡鍚嶏紙鍏ㄥぇ鍐欏父閲忥級
      if (this._options.checkConstantUpperSnakeCase) {
        const constMatch = line.match(/const\s+([A-Z][A-Z0-9_]+)\s*=/);
        if (constMatch) {
          const name = constMatch[1];
          if (!UPPER_SNAKE_CASE_REGEX.test(name)) {
            violations.push(`Line ${lineNumber}: Constant '${name}' should use UPPER_SNAKE_CASE`);
          }
        }
      }
    }

    if (violations.length === 0) {
      return {
        ruleId: this.ruleId,
        severity: this._rule.severity,
        passed: true,
        code: this._rule.code,
        filePath,
        rule: this._rule,
      };
    }

    return {
      ruleId: this.ruleId,
      severity: this._rule.severity,
      passed: false,
      message: violations.join("; "),
      code: this._rule.code,
      filePath,
      rule: this._rule,
      line: 1,
      fixSuggestion: this._rule.fixSuggestion,
    };
  }
}

/**
 * @cortex/prompt-kit 鈥?澹版槑寮?Prompt 缁勮鍣╘n *
 * 灏?PromptTemplate + PromptAssembly 鈫?鏈€缁堢粍鍚堢殑 prompt 鏂囨湰銆俓n * 閫氳繃瑁呴厤绠＄嚎鎵ц锛氬潡杩囨护 鈫?鍧楁帓搴?鈫?娉ㄥ叆韬唤閿氱偣 鈫?妯℃澘娓叉煋銆俓n *
 * @see DESIGN.md 搂3.2 PromptAssembler
 */

import {
  PromptBlockType,
  type PromptBlock,
  type PromptTemplate,
  type PromptAssembly,
  type PromptContext,
  type PromptResult,
} from "../types.js";
import type { PromptTemplateEngine } from "../template-engine/prompt-template-engine.js";

/**
 * 鍧楅澶勭悊鍣細鍦ㄦ覆鏌撳墠淇敼鍧楀垪琛ㄣ€俓n */
export type BlockPreprocessor = (
  blocks: PromptBlock[],
  context: PromptContext,
) => PromptBlock[];

/**
 * 鍧楀悗澶勭悊鍣細鍦ㄦ覆鏌撳悗淇敼缁撴灉銆俓n */
export type BlockPostprocessor = (
  result: PromptResult,
  context: PromptContext,
) => PromptResult;

/**
 * 鍐呯疆韬唤閿氱偣鍧椼€俓n * 鍦?injectIdentityAnchor=true 鏃惰嚜鍔ㄦ敞鍏ャ€俓n */
const IDENTITY_ANCHOR_BLOCK: PromptBlock = {
  id: "shared-identity-anchor",
  type: PromptBlockType.Identity,
  content: "[绯荤粺鎸囦护] 浣犳槸 Cortex 宸ョ▼鍔╂墜鐨勮韩浠介敋鐐广€俓

usedDeprecatedRules:
\n\n";
    const text = this.engine.renderBlocks(finalBlocks, context, separator);

    // 8. 鏋勫缓缁撴灉
    const result: PromptResult = {
      text,
      templateId: template.id,
      version: template.version,
      renderedBlocks: finalBlocks.map((b, i) => ({
        id: b.id,
        type: b.type,
        content: b.content,
        order: i,
      })),
      skippedBlocks,
      renderTimeMs: Date.now() - startTime,
      timestamp: Date.now(),
    };

    // 9. 搴旂敤鍚庡鐞嗗櫒
    let finalResult = result;
    for (const postprocessor of this.postprocessors) {
      finalResult = postprocessor(finalResult, context);
    }

    return finalResult;
  }

  /**
   * 娉ㄥ唽棰勫鐞嗗櫒銆俓n   */
  registerPreprocessor(name: string, fn: BlockPreprocessor): void {
    this.preprocessors.push(fn);
  }

  /**
   * 娉ㄥ唽鍚庡鐞嗗櫒銆俓n   */
  registerPostprocessor(name: string, fn: BlockPostprocessor): void {
    this.postprocessors.push(fn);
  }

  /**
   * 鍧楄繃婊わ細鎸?condition / accessLevel / blockFilter 杩囨护銆俓n   */
  private filterBlocks(
    blocks: PromptBlock[],
    context: PromptContext,
  ): {
    activeBlocks: PromptBlock[];
    skippedBlocks: PromptResult["skippedBlocks"];
  } {
    const activeBlocks: PromptBlock[] = [];
    const skippedBlocks: PromptResult["skippedBlocks"] = [];

    for (const block of blocks) {
      // 1. 妫€鏌?accessLevel
      if (block.accessLevel === "private" && context.activeBlockIds?.includes(block.id) === false) {
        skippedBlocks.push({ id: block.id, type: block.type, reason: "access_denied" });
        continue;
      }

      // 2. 妫€鏌?condition
      if (block.condition) {
        const conditionMet = this.evaluateCondition(block.condition, context);
        if (!conditionMet) {
          skippedBlocks.push({ id: block.id, type: block.type, reason: "condition_false" });
          continue;
        }
      }

      // 3. 妫€鏌?activeBlockIds 鐧藉悕鍗昞n      if (context.activeBlockIds && !context.activeBlockIds.includes(block.id)) {
        skippedBlocks.push({ id: block.id, type: block.type, reason: "filtered" });
        continue;
      }

      // 4. 妫€鏌ヨ嚜瀹氫箟 blockFilter
      if (context.blockFilter && !context.blockFilter(block)) {
        skippedBlocks.push({ id: block.id, type: block.type, reason: "filtered" });
        continue;
      }

      activeBlocks.push(block);
    }

    return { activeBlocks, skippedBlocks };
  }

  /**
   * 鍧楁帓搴忋€俓n   */
  private sortBlocks(
    blocks: PromptBlock[],
    strategy?: "by_priority" | "by_type" | "custom",
  ): PromptBlock[] {
    switch (strategy) {
      case "by_type":
        return blocks.sort((a, b) => {
          const typeOrder = (t: PromptBlockType) => {
            const order = [
              PromptBlockType.Identity,
              PromptBlockType.Persona,
              PromptBlockType.Context,
              PromptBlockType.Instruction,
              PromptBlockType.OutputFormat,
              PromptBlockType.Example,
              PromptBlockType.Private,
            ];
            return order.indexOf(t);
          };
          return typeOrder(a.type) - typeOrder(b.type);
        });
      case "by_priority":
      default:
        return blocks.sort((a, b) => a.priority - b.priority);
    }
  }

  /**
   * 娉ㄥ叆鍏变韩韬唤閿氱偣銆俓n   * 濡傛灉宸叉湁 Identity 鍧楋紝閿氱偣鎻掑叆鍦ㄦ渶鍓嶆柟銆俓n   */
  private injectAnchor(blocks: PromptBlock[]): PromptBlock[] {
    // 妫€鏌ユ槸鍚﹀凡鍖呭惈 identity 绫诲瀷鐨?anchor 鍐呭
    const hasAnchor = blocks.some(
      (b) => b.type === PromptBlockType.Identity && b.id === "shared-identity-anchor",
    );
    if (hasAnchor) return blocks;

    return [IDENTITY_ANCHOR_BLOCK, ...blocks];
  }

  /**
   * 绠€鍗曟潯浠惰〃杈惧紡璇勪及銆俓n   * 鏀寔锛氬彉閲忓悕銆?鍙栧弽銆俓n   */
  private evaluateCondition(condition: string, context: PromptContext): boolean {
    let expr = condition.trim();

    // 鍙栧弽
    const isNegated = expr.startsWith("!");
    if (isNegated) {
      expr = expr.substring(1).trim();
    }

    // 瀛楅潰閲廫n    if (expr === "true") return !isNegated;
    if (expr === "false") return isNegated;

    // 浠?variables 涓彇鍊糪n    const value = context.variables?.[expr];

    const isTruthy = value !== undefined && value !== null && value !== false;
    return isNegated ? !isTruthy : isTruthy;
  }
}

