/**
 * @cortex/prompt-kit 鈥?閰嶇疆 Prompt 鏉ユ簮
 *
 * 浠?@cortex/config 鐨勫父閲忥紙濡?PLANNING_SYSTEM, REPLAN_SYSTEM锛夊姞杞?PromptTemplate銆俓n * 閫氳繃娉ㄥ唽琛ㄥ皢閰嶇疆閿槧灏勫埌妯℃澘 ID銆俓n *
 * @see DESIGN.md 搂3.1 ConfigSource
 */

import { PromptBlockType, type PromptTemplate } from "../types.js";
import type { PromptSource } from "./prompt-loader.js";

/**
 * 閰嶇疆鏉ユ簮娉ㄥ唽鏉＄洰銆俓n * 瀹氫箟濡備綍灏嗛厤缃父閲忔槧灏勪负 PromptTemplate銆俓n */
export interface ConfigSourceEntry {
  /** 閰嶇疆閿紙濡?"PLANNING_SYSTEM"锛?*/
  key: string;
  /** 鑾峰彇閰嶇疆鍊肩殑鍑芥暟 */
  getValue: () => string;
  /** 妯℃澘 ID */
  templateId: string;
  /** 鍧楃被鍨?*/
  blockType?: PromptBlockType;
  /** 浼樺厛绾?*/
  priority?: number;
}

/**
 * ConfigPromptSource 鈥斺€?閰嶇疆鏉ユ簮銆俓n *
 * 灏?@cortex/config 涓殑甯搁噺锛堝瓧绗︿覆鍊硷級娉ㄥ唽涓?PromptTemplate銆俓n * 鏃犻渶鏂囦欢绯荤粺 I/O銆俓n */
export class ConfigPromptSource implements PromptSource {
  private entries: Map<string, ConfigSourceEntry> = new Map();

  /**
   * 娉ㄥ唽閰嶇疆鏉＄洰銆俓n   */
  register(entry: ConfigSourceEntry): void {
    this.entries.set(entry.templateId, entry);
    // 鍚屾椂鎸?config key 绱㈠紩
    this.entries.set(`config:${entry.key}`, entry);
  }

  /**
   * 鎵归噺娉ㄥ唽銆俓n   */
  registerMany(entries: ConfigSourceEntry[]): void {
    for (const entry of entries) {
      this.register(entry);
    }
  }

  /**
   * 鎸夋ā鏉?ID 鍔犺浇銆俓n   */
  async load(templateId: string): Promise<PromptTemplate | null> {
    const entry = this.entries.get(templateId);
    if (!entry) {
      return null;
    }

    const content = entry.getValue();
    if (!content) {
      return null;
    }

    return {
      id: entry.templateId,
      name: entry.templateId,
      version: "1.0.0",
      blocks: [
        {
          id: `${entry.templateId}-content`,
          type: entry.blockType ?? PromptBlockType.Instruction,
          content,
          priority: entry.priority ?? 40,
          metadata: { configKey: entry.key },
        },
      ],
      tags: [entry.templateId],
      source: `config:${entry.key}`,
    };
  }

  /**
   * 鍒楀嚭鎵€鏈夊彲鐢ㄧ殑妯℃澘 ID銆俓n   */
  async list(): Promise<string[]> {
    return Array.from(this.entries.keys())
      .filter((k) => !k.startsWith("config:")); // 鍙鍑烘ā鏉?ID锛屼笉瀵?config: 鍓嶇紑
  }
}

/**
 * @cortex/prompt-kit 鈥?鏂囦欢绯荤粺 Prompt 鏉ユ簮
 *
 * 浠?prompts/ 鐩綍鎸夌害瀹氬姞杞?PromptTemplate銆俓n * 鏂囦欢 鈫?PromptTemplate 鏄犲皠瑙勫垯锛歕n *   prompts/<agent>/system.md  鈫?templateId: "<agent>-system"
 *   prompts/<agent>/identity.md 鈫?templateId: "<agent>-identity"
 *   prompts/shared/identity-anchor.md 鈫?templateId: "shared-identity-anchor"
 *
 * @see DESIGN.md 搂3.1 鏂囦欢鍔犺浇瑙勫垯
 */

import { readFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { join, relative, resolve, basename, extname } from "node:path";
import { DIR_PROMPTS } from "@cortex/config";
import { PromptBlockType, type PromptTemplate, type PromptBlock, PromptErrorCode } from "../types.js";
import { PromptError } from "../errors.js";
import type { PromptSource } from "./prompt-loader.js";

/**
 * 鏂囦欢鏉ユ簮閫夐」銆俓n */
export interface FilePromptSourceOptions {
  /** 椤圭洰鏍圭洰褰曪紙榛樿 process.cwd()锛?*/
  baseDir?: string;
  /** prompts 鐩綍鍚嶏紙榛樿 "prompts"锛?*/
  promptsDir?: string;
}

/**
 * 鏂囦欢鍚?鈫?PromptBlockType 鏄犲皠瑙勫垯銆俓n * 鐢ㄤ簬浠庢枃浠跺悕鑷姩鎺ㄥ鍧楃被鍨嬨€俓n */
const FILE_TYPE_MAP: Record<string, PromptBlockType> = {
  "system": PromptBlockType.Instruction,
  "identity": PromptBlockType.Identity,
  "persona": PromptBlockType.Persona,
  "roundtable": PromptBlockType.Persona,
  "context": PromptBlockType.Context,
  "format": PromptBlockType.OutputFormat,
  "example": PromptBlockType.Example,
  "private": PromptBlockType.Private,
};

/**
 * FilePromptSource 鈥斺€?鏂囦欢绯荤粺 Prompt 鏉ユ簮銆俓n *
 * 绾﹀畾浼樹簬閰嶇疆锛歕n * - prompts/<agent-type>/system.md 鈫?妯℃澘 ID = "<agent-type>-system"
 * - prompts/<agent-type>/identity.md 鈫?妯℃澘 ID = "<agent-type>-identity"
 * - prompts/shared/identity-anchor.md 鈫?妯℃澘 ID = "shared-identity-anchor"
 *
 * 鍚勬枃浠朵綔涓虹嫭绔嬫ā鏉匡紝涔熻嚜鍔ㄨ仛鍚堜负 agent 绾фā鏉匡紙鍚堝苟鎵€鏈夊潡锛夈€俓n */
export class FilePromptSource implements PromptSource {
  private baseDir: string;
  private promptsDir: string;
  /** 鍐呴儴绱㈠紩锛歵emplateId 鈫?filePath */
  private index: Map<string, string> = new Map();
  /** 鏄惁宸叉壂鎻?*/
  private scanned = false;

  constructor(options: FilePromptSourceOptions = {}) {
    this.baseDir = options.baseDir ?? process.cwd();
    this.promptsDir = options.promptsDir ?? DIR_PROMPTS;
  }

  /**
   * 鎸夋ā鏉?ID 鍔犺浇銆俓n   * 鏀寔涓ょ ID 鏍煎紡锛歕n   * - "nahida-system" 鈫?鍔犺浇 prompts/nahida/system.md
   * - "shared-identity-anchor" 鈫?鍔犺浇 prompts/shared/identity-anchor.md
   */
  async load(templateId: string): Promise<PromptTemplate | null> {
    await this.ensureIndex();

    const filePath = this.index.get(templateId);
    if (!filePath) {
      return null;
    }

    return this.parseFile(filePath, templateId);
  }

  /**
   * 鍒楀嚭鎵€鏈夊彲鐢ㄦā鏉?ID銆俓n   */
  async list(): Promise<string[]> {
    await this.ensureIndex();
    return Array.from(this.index.keys());
  }

  /**
   * 鍒锋柊鏂囦欢绱㈠紩銆俓n   */
  refreshIndex(): void {
    this.scanned = false;
    this.index.clear();
  }

  /**
   * 纭繚绱㈠紩宸叉瀯寤恒€俓n   */
  private async ensureIndex(): Promise<void> {
    if (this.scanned) return;
    this.scanDirectory();
    this.scanned = true;
  }

  /**
   * 鎵弿 prompts 鐩綍鏋勫缓绱㈠紩銆俓n   */
  private scanDirectory(): void {
    const promptsPath = resolve(this.baseDir, this.promptsDir);
    if (!existsSync(promptsPath)) {
      return; // prompts 鐩綍涓嶅瓨鍦紝绌虹储寮昞n    }

    this.scanRecursive(promptsPath, promptsPath);
  }

  /**
   * 閫掑綊鎵弿鐩綍銆俓n   */
  private scanRecursive(currentPath: string, basePath: string): void {
    const entries = readdirSync(currentPath);

    for (const entry of entries) {
      const fullPath = join(currentPath, entry);
      const stats = statSync(fullPath);

      if (stats.isDirectory()) {
        this.scanRecursive(fullPath, basePath);
      } else if (stats.isFile() && (entry.endsWith(".md") || entry.endsWith(".txt"))) {
        // 璁＄畻鐩稿璺緞锛歱rompts/<dir>/<file>.md
        const relPath = relative(basePath, fullPath);
        // 鍘绘帀鎵╁睍鍚嶏紝灏嗚矾寰勫垎闅旂鏇挎崲涓?"-"
        const templateId = relPath
          .replace(/\.(md|txt)$/, "")
          .replace(/[/\\]/g, "-")
          .toLowerCase();
        this.index.set(templateId, fullPath);
      }
    }
  }

  /**
   * 瑙ｆ瀽鍗曚釜鏂囦欢涓?PromptTemplate銆俓n   */
  private parseFile(filePath: string, templateId: string): PromptTemplate {
    if (!existsSync(filePath)) {
      throw new PromptError(
        `鏂囦欢涓嶅瓨鍦? ${filePath}`,
        PromptErrorCode.LOAD_FAILED,
        { filePath, templateId },
      );
    }

    const content = readFileSync(filePath, "utf-8");
    const fileName = basename(filePath, extname(filePath));
    const blockType = FILE_TYPE_MAP[fileName] ?? PromptBlockType.Instruction;

    // 浠庤矾寰勬帹瀵?agent 鍚嶇О
    const relativePath = relative(resolve(this.baseDir, this.promptsDir), filePath);
    const pathParts = relativePath.replace(/\\/g, "/").split("/");
    const agentName = pathParts.length > 1 ? pathParts[0] : "shared";

    const block: PromptBlock = {
      id: templateId,
      type: blockType,
      content,
      priority: this.getDefaultPriority(blockType),
      metadata: {
        filePath,
        agentName,
      },
    };

    return {
      id: templateId,
      name: templateId,
      version: "1.0.0",
      blocks: [block],
      tags: [agentName],
      source: filePath,
    };
  }

  /**
   * 鑾峰彇鍧楃被鍨嬬殑榛樿浼樺厛绾с€俓n   */
  private getDefaultPriority(type: PromptBlockType): number {
    switch (type) {
      case PromptBlockType.Identity: return 10;
      case PromptBlockType.Persona: return 20;
      case PromptBlockType.Context: return 30;
      case PromptBlockType.Instruction: return 40;
      case PromptBlockType.OutputFormat: return 50;
      case PromptBlockType.Example: return 60;
      case PromptBlockType.Private: return 100;
      default: return 50;
    }
  }
}

/**
 * @cortex/prompt-kit 鈥?鍐呰仈 Prompt 鏉ユ簮
 *
 * 鎺ュ彈杩愯鏃跺姩鎬佷紶鍏ョ殑瀛楃涓蹭綔涓?PromptTemplate銆俓n * 鐢ㄤ簬 CLI 涓敤鎴疯嚜瀹氫箟 prompt銆佸姩鎬佺敓鎴愮殑鎸囦护绛夊満鏅€俓n */

import { PromptBlockType, type PromptTemplate, type PromptBlock } from "../types.js";
import type { PromptSource } from "./prompt-loader.js";

/**
 * InlinePromptSource 鈥斺€?鍐呰仈鏉ユ簮銆俓n *
 * 閫氳繃 registerInline() 鍦ㄨ繍琛屾椂娉ㄥ唽鍐呰仈妯℃澘銆俓n * 閫傜敤浜庝互涓嬪満鏅細
 * - CLI 鐢ㄦ埛鑷畾涔?prompt
 * - 鍔ㄦ€佺敓鎴愮殑鏍煎紡鎸囦护
 * - 娴嬭瘯涓?mock prompt
 */
export class InlinePromptSource implements PromptSource {
  private templates: Map<string, PromptTemplate> = new Map();

  /**
   * 娉ㄥ唽鍐呰仈妯℃澘銆俓n   */
  register(
    templateId: string,
    content: string,
    blockType: PromptBlockType = PromptBlockType.Instruction,
    priority: number = 50,
  ): void {
    const block: PromptBlock = {
      id: `${templateId}-inline`,
      type: blockType,
      content,
      priority,
    };

    this.templates.set(templateId, {
      id: templateId,
      name: templateId,
      version: "0.1.0",
      blocks: [block],
      tags: [templateId],
      source: "inline",
    });
  }

  /**
   * 娉ㄥ唽澶氬潡鍐呰仈妯℃澘銆俓n   */
  registerTemplate(template: PromptTemplate): void {
    this.templates.set(template.id, template);
  }

  /**
   * 鎸夋ā鏉?ID 鍔犺浇銆俓n   */
  async load(templateId: string): Promise<PromptTemplate | null> {
    return this.templates.get(templateId) ?? null;
  }

  /**
   * 鍒楀嚭鎵€鏈夊唴鑱旀ā鏉?ID銆俓n   */
  async list(): Promise<string[]> {
    return Array.from(this.templates.keys());
  }

  /**
   * 绉婚櫎鎸囧畾妯℃澘銆俓n   */
  remove(templateId: string): void {
    this.templates.delete(templateId);
  }

  /**
   * 娓呯┖鎵€鏈夊唴鑱旀ā鏉裤€俓n   */
  clear(): void {
    this.templates.clear();
  }
}

/**
 * @cortex/prompt-kit 鈥?PromptOrchestrator 缂栨帓鍣╘n *
 * 缁勫悎 Loader + Assembler + TemplateEngine + Validator + Cache + Version
 * 涓轰竴浣撳寲缂栨帓鍣ㄣ€傚寘澶栫粺涓€鍏ュ彛銆俓n *
 * @see DESIGN.md 搂3.7 PromptOrchestrator
 */

import type {
  PromptTemplate,
  PromptBlock,
  PromptAssembly,
  PromptContext,
  PromptResult,
  PromptLoadOptions,
  ValidationResult,
  CacheStats,
  OrchestratorOptions,
} from "../types.js";
import { PromptLoader } from "../loader/prompt-loader.js";
import { FilePromptSource } from "../loader/file-source.js";
import { ConfigPromptSource } from "../loader/config-source.js";
import { InlinePromptSource } from "../loader/inline-source.js";
import { PromptAssembler } from "../assembler/prompt-assembler.js";
import { PromptTemplateEngine } from "../template-engine/prompt-template-engine.js";
import { PromptValidator } from "../validator/prompt-validator.js";
import { PromptCache } from "../cache/prompt-cache.js";
import { PromptVersion } from "../version/prompt-version.js";

/**
 * PromptOrchestrator 鈥斺€?鎻愮ず璇嶇紪鎺掑櫒銆俓n *
 * 鍖呭缁熶竴鍏ュ彛锛岀粍鍚堝悇瀛愭ā鍧椾负瀹屾暣鐨?prompt 缂栨帓绠￠亾锛歕n * 鍔犺浇 鈫?缁勮 鈫?妯℃澘娓叉煋 鈫?鏍￠獙 鈫?杩斿洖缁撴灉
 */
export class PromptOrchestrator {
  readonly loader: PromptLoader;
  readonly assembler: PromptAssembler;
  readonly templateEngine: PromptTemplateEngine;
  readonly validator: PromptValidator;
  readonly cache: PromptCache;
  readonly version: PromptVersion;

  private options: Required<OrchestratorOptions>;

  constructor(options: OrchestratorOptions = {}) {
    this.options = {
      baseDir: options.baseDir ?? process.cwd(),
      cacheMaxSize: options.cacheMaxSize ?? 100,
      cacheDefaultTtlMs: options.cacheDefaultTtlMs ?? 300_000,
      injectIdentityAnchor: options.injectIdentityAnchor ?? true,
      enableFileWatching: options.enableFileWatching ?? false,
      engineOptions: options.engineOptions ?? {},
    };

    // 1. 妯℃澘寮曟搸
    this.templateEngine = new PromptTemplateEngine(this.options.engineOptions);

    // 2. 鍔犺浇鍣?+ 娉ㄥ唽榛樿鏉ユ簮
    this.loader = new PromptLoader();
    this.registerDefaultSources();

    // 3. 缁勮鍣╘n    this.assembler = new PromptAssembler(this.templateEngine);

    // 4. 鏍￠獙鍣╘n    this.validator = new PromptValidator();

    // 5. 缂撳瓨
    this.cache = new PromptCache(this.options.cacheMaxSize, this.options.cacheDefaultTtlMs);

    // 6. 鐗堟湰绠＄悊
    this.version = new PromptVersion();
  }

  /**
   * 娓叉煋瀹屾暣 system prompt銆俓n   * 缂栨帓鍣ㄤ富鍏ュ彛锛氬姞杞?鈫?缁勮 鈫?娓叉煋 鈫?鏍￠獙 鈫?杩斿洖銆俓n   */
  async renderSystemPrompt(assembly: PromptAssembly): Promise<PromptResult> {
    // 1. 鍔犺浇妯℃澘
    let template: PromptTemplate;

    if (assembly.baseTemplateId) {
      // 浠庣紦瀛樿幏鍙朶n      const cached = this.cache.get(assembly.baseTemplateId);
      if (!cached) {
        template = await this.loader.load(assembly.baseTemplateId);
        this.cache.set(assembly.baseTemplateId, template);
      } else {
        template = cached;
      }
    } else {
      // 鏃犲熀纭€妯℃澘锛氫娇鐢ㄧ┖妯℃澘锛堜粎棰濆鍧楋級
      template = {
        id: "_inline",
        name: "_inline",
        version: "0.1.0",
        blocks: [],
        tags: [],
        source: "inline",
      };
    }

    // 2. 缁勮锛堝惈杩囨护銆佹帓搴忋€佽韩浠介敋鐐规敞鍏ャ€佹ā鏉挎覆鏌擄級
    const result = await this.assembler.assemble(template, assembly);

    // 3. 鏍￠獙
    const validation = this.validator.validateResult(result);
    if (!validation.valid) {
      // 鏍￠獙澶辫触鏃讹紝杩斿洖缁撴灉浣嗗寘鍚敊璇俊鎭紙涓嶉樆鏂覆鏌擄級
      // 璋冪敤鏂瑰彲閫氳繃 result.metadata?.validationErrors 鑾峰彇
      const _result = result as { metadata?: Record<string, unknown> };
      _result.metadata = {
        ..._result.metadata,
        validationErrors: validation.errors,
        validationWarnings: validation.warnings,
      };
    }

    return result;
  }

  /**
   * 鍔犺浇骞剁紦瀛樻ā鏉裤€俓n   */
  async loadTemplate(
    templateId: string,
    options?: PromptLoadOptions,
  ): Promise<PromptTemplate> {
    const cached = this.cache.get(templateId);
    if (cached && options?.useCache !== false) {
      return cached;
    }

    const template = await this.loader.load(templateId, options);
    this.cache.set(templateId, template);
    return template;
  }

  /**
   * 蹇€熸覆鏌撳崟鍧楋紙渚挎嵎鏂规硶锛夈€俓n   */
  async renderBlock(block: PromptBlock, context: PromptContext): Promise<string> {
    return this.templateEngine.renderBlock(block, context);
  }

  /**
   * 楠岃瘉 assembly 鐨勫畬鏁存€с€俓n   */
  validateAssembly(assembly: PromptAssembly): ValidationResult {
    const errors: ValidationResult["errors"] = [];
    const warnings: ValidationResult["warnings"] = [];

    if (!assembly.context || !assembly.context.variables) {
      errors.push({
        path: "context.variables",
        message: "Assembly 缂哄皯 context.variables",
        severity: "error",
      });
    }

    // 妫€鏌?baseTemplateId 瀵瑰簲鐨勬ā鏉挎槸鍚﹀瓨鍦紙涓嶅姞杞斤紝浠呮鏌ョ紦瀛橈級
    if (assembly.baseTemplateId && !this.cache.has(assembly.baseTemplateId)) {
      warnings.push(
        `鍩虹妯℃澘 "${assembly.baseTemplateId}" 鏈湪缂撳瓨涓壘鍒帮紝灏嗗湪娓叉煋鏃跺姞杞絗,
      );
    }

    return {
      valid: errors.filter((e) => e.severity === "error").length === 0,
      errors,
      warnings,
    };
  }

  /**
   * 娓呯┖缂撳瓨銆俓n   */
  clearCache(): void {
    this.cache.clear();
  }

  /**
   * 鑾峰彇缂撳瓨缁熻銆俓n   */
  getCacheStats(): CacheStats {
    return this.cache.stats();
  }

  /**
   * 娉ㄥ唽榛樿鏉ユ簮銆俓n   */
  private registerDefaultSources(): void {
    // 鏂囦欢鏉ユ簮
    const fileSource = new FilePromptSource({
      baseDir: this.options.baseDir,
    });
    this.loader.registerSource("file", fileSource);

    // 鍐呰仈鏉ユ簮
    this.loader.registerSource("inline", new InlinePromptSource());

    // 閰嶇疆鏉ユ簮
    const configSource = new ConfigPromptSource();
    this.loader.registerSource("config", configSource);
  }
}

/**
 * @cortex/prompt-kit 鈥?Prompt 妯℃澘娓叉煋寮曟搸
 *
 * 鎻愪緵涓撲负 prompt 鍦烘櫙澧炲己鐨勬ā鏉挎覆鏌撹兘鍔涳紝缁ф壙 skill-kit 鐨刓n * SimpleTemplateEngine 璇硶骞舵墿灞?prompt 涓撶敤鎸囦护銆俓n *
 * 鏀寔鐨勮娉曪細
 * - {{ variable }} 鈥?鍙橀噺鎻掑€糪n * - {{#if cond}}...{{/if}} 鈥?鏉′欢娓叉煋
 * - {{#each list}}...{{/each}} 鈥?寰幆娓叉煋
 * - {{#role name}}...{{/role}} 鈥?瑙掕壊鍒囨崲鍧梊n * - {{#block id}}...{{/block}} 鈥?鍧楃骇寮曠敤
 * - {{#ref templateId}} 鈥?璺ㄦā鏉垮紩鐢紙鑷棴鍚堬級
 * - {{#include filepath}} 鈥?鏂囦欢鍖呭惈锛堣嚜闂悎锛塡n * - {{#date format}} 鈥?鏃ユ湡鏍煎紡鍖栵紙鑷棴鍚堬級
 *
 * @see DESIGN.md 搂3.3 PromptTemplateEngine
 */

import { PromptErrorCode, type PromptBlock, type PromptContext, type TemplateEngineOptions } from "../types.js";
import { PromptError } from "../errors.js";

// 榛樿閫夐」
const DEFAULT_OPTIONS: Required<TemplateEngineOptions> = {
  delimiters: ["{{", "}}"],
  undefinedPlaceholder: "",
  escapeHtml: false,
  maxNestingDepth: 5,
};

/** 鑷棴鍚堟寚浠ゅ垪琛?鈥?杩欎簺鎸囦护涓嶉渶瑕侀棴鍚堟爣绛?*/
const SELF_CLOSING_DIRECTIVES = new Set(["date", "ref", "include", "block"]);

/**
 * 鎸囦护澶勭悊鍣ㄧ鍚嶃€俓n */
export type DirectiveHandler = (
  params: string,
  body: string,
  context: PromptContext,
  engine: PromptTemplateEngine,
  depth: number,
) => string;

/**
 * PromptTemplateEngine 鈥斺€?澧炲己鍨?Prompt 妯℃澘娓叉煋寮曟搸銆俓n *
 * 缁ф壙 SimpleTemplateEngine 鐨勬牳蹇冭娉曪紝鏂板 prompt 涓撶敤鎸囦护銆俓n * 涓嶄緷璧栦换浣曞閮ㄦā鏉垮紩鎿庡簱銆俓n */
export class PromptTemplateEngine {
  private options: Required<TemplateEngineOptions>;
  private openTag: string;
  private closeTag: string;
  private helpers: Map<string, (...args: unknown[]) => unknown> = new Map();
  private directives: Map<string, DirectiveHandler> = new Map();

  constructor(options: TemplateEngineOptions = {}) {
    this.options = { ...DEFAULT_OPTIONS, ...options };
    [this.openTag, this.closeTag] = this.options.delimiters;
    this.registerBuiltinDirectives();
    this.registerBuiltinHelpers();
  }

  /**
   * 娓叉煋鍗曞潡鍐呭銆俓n   */
  renderBlock(block: PromptBlock, context: PromptContext): string {
    return this.render(block.content, context, 0);
  }

  /**
   * 鎵归噺娓叉煋锛堜緷娆℃覆鏌擄紝鎷兼帴鍒嗛殧绗︼級銆俓n   */
  renderBlocks(
    blocks: PromptBlock[],
    context: PromptContext,
    separator: string = "\n\n",
  ): string {
    return blocks
      .map((block) => this.renderBlock(block, context))
      .filter(Boolean)
      .join(separator);
  }

  /**
   * 娓叉煋妯℃澘瀛楃涓层€俓n   */
  render(template: string, context: PromptContext, depth: number = 0): string {
    if (!template) return "";
    if (depth > this.options.maxNestingDepth) {
      throw new PromptError(
        `妯℃澘宓屽瓒呰繃鏈€澶ф繁搴?${this.options.maxNestingDepth}`,
        PromptErrorCode.CIRCULAR_REFERENCE,
        { depth, maxDepth: this.options.maxNestingDepth },
      );
    }

    let result = template;

    // 1. 澶勭悊鑷棴鍚堟寚浠?{{#directive params}}
    result = this.renderSelfClosingDirectives(result, context, depth);

    // 2. 澶勭悊鍧楁寚浠?{{#directive params}}...{{/directive}}
    result = this.renderBlockDirectives(result, context, depth);

    // 3. 澶勭悊鍙橀噺鎻掑€?{{ variable }} 鍜?{{ variable || fallback }}
    result = this.renderVariables(result, context);

    return result;
  }

  /**
   * 娉ㄥ唽鑷畾涔夎緟鍔╁嚱鏁般€俓n   */
  registerHelper(name: string, fn: (...args: unknown[]) => unknown): void {
    this.helpers.set(name, fn);
  }

  /**
   * 娉ㄥ唽鑷畾涔夋寚浠ゃ€俓n   */
  registerDirective(name: string, handler: DirectiveHandler): void {
    this.directives.set(name, handler);
  }

  // 鈹€鈹€ 鍐呯疆鎸囦护娉ㄥ唽 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private registerBuiltinDirectives(): void {
    // #role 鈥?瑙掕壊鍒囨崲
    this.directives.set("role", (params, body, context, engine, depth) => {
      const roleName = params.trim();
      const rolePersona = context.variables?.[`role_${roleName}`];
      if (rolePersona) {
        return `[${roleName} 瑙掕壊]\n${rolePersona}\n${engine.render(body, context, depth + 1)}`;
      }
      return engine.render(body, context, depth + 1);
    });

    // #block 鈥?鍧楃骇寮曠敤锛堣嚜闂悎锛岄€氳繃 params 鎸囧畾鍧?ID锛塡n    this.directives.set("block", (params, _body, context, _engine, _depth) => {
      const blockMap = context.variables?.__blocks as Record<string, string> | undefined;
      const blockId = params.trim();
      if (blockMap && blockMap[blockId]) {
        return blockMap[blockId];
      }
      return `[鍧?"${blockId}" 鏈壘鍒癩`;
    });

    // #ref 鈥?璺ㄦā鏉垮紩鐢紙鑷棴鍚堬級
    this.directives.set("ref", (params, _body, _context, _engine, _depth) => {
      const templateId = params.trim();
      return `__REF_${templateId}__`;
    });

    // #include 鈥?鏂囦欢鍖呭惈锛堣嚜闂悎锛塡n    this.directives.set("include", (params, _body, _context, _engine, _depth) => {
      const filePath = params.trim();
      return `__INCLUDE_${filePath}__`;
    });

    // #date 鈥?鏃ユ湡鏍煎紡鍖栵紙鑷棴鍚堬級
    this.directives.set("date", (params, _body, _context, _engine, _depth) => {
      const format = params.trim() || "YYYY-MM-DD";
      const now = new Date();
      return this.formatDate(now, format);
    });

    // #if 鈥?鏉′欢娓叉煋
    this.directives.set("if", (params, body, context, engine, depth) => {
      const conditionValue = this.evaluateCondition(params.trim(), context);

      // 澶勭悊 {{else}} 鍒嗘敮
      const elseTag = `${this.openTag}else${this.closeTag}`;
      const elseIndex = body.indexOf(elseTag);

      let trueBody: string;
      let falseBody: string | undefined;

      if (elseIndex !== -1) {
        trueBody = body.substring(0, elseIndex);
        falseBody = body.substring(elseIndex + elseTag.length);
      } else {
        trueBody = body;
        falseBody = undefined;
      }

      if (conditionValue) {
        return engine.render(trueBody, context, depth + 1);
      } else if (falseBody !== undefined) {
        return engine.render(falseBody, context, depth + 1);
      }
      return "";
    });

    // #each 鈥?寰幆娓叉煋
    this.directives.set("each", (params, body, context, engine, depth) => {
      const list = context.variables?.[params.trim()];
      if (!Array.isArray(list)) return "";

      return list.map((item: unknown, index: number) => {
        const itemContext: PromptContext = {
          ...context,
          variables: {
            ...context.variables,
            this: item,
            index,
          },
        };
        return engine.render(body, itemContext, depth + 1);
      }).join("\n");
    });

    // /if, /each, /role 鈥?闂悎鏍囩锛屾棤鎿嶄綔锛堟覆鏌撴椂琚墺绂伙級
    this.directives.set("/if", () => "");
    this.directives.set("/each", () => "");
    this.directives.set("/role", () => "");
  }

  private registerBuiltinHelpers(): void {
    this.helpers.set("toUpper", (str: unknown) => String(str).toUpperCase());
    this.helpers.set("toLower", (str: unknown) => String(str).toLowerCase());
    this.helpers.set("trim", (str: unknown) => String(str).trim());
    this.helpers.set("json", (obj: unknown) => JSON.stringify(obj, null, 2));
  }

  // 鈹€鈹€ 鑷棴鍚堟寚浠ゆ覆鏌?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 澶勭悊鑷棴鍚堟寚浠わ細{{#directive params}}
   * 杩欎簺鎸囦护娌℃湁 body 涔熸病鏈夐棴鍚堟爣绛俱€俓n   */
  private renderSelfClosingDirectives(template: string, context: PromptContext, depth: number): string {
    const regex = new RegExp(
      `${this.escapeRegex(this.openTag)}\\s*#(\\w+)(?:\\s+(.+?))?\\s*${this.escapeRegex(this.closeTag)}`,
      "g",
    );

    let result = template;
    let match;

    while ((match = regex.exec(result)) !== null) {
      const [fullMatch, directiveName, params] = match;

      // 鍙鐞嗚嚜闂悎鎸囦护
      if (!SELF_CLOSING_DIRECTIVES.has(directiveName)) {
        continue;
      }

      const handler = this.directives.get(directiveName);
      if (!handler) continue;

      const replacement = handler(params?.trim() ?? "", "", context, this, depth);
      result = result.replace(fullMatch, replacement);
      regex.lastIndex = 0;
    }

    return result;
  }

  // 鈹€鈹€ 鍧楁寚浠ゆ覆鏌?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 澶勭悊鍧楁寚浠わ細{{#directive params}}...{{/directive}}
   * 杩欎簺鎸囦护鏈?body 鍜岄棴鍚堟爣绛俱€俓n   */
  private renderBlockDirectives(template: string, context: PromptContext, depth: number): string {
    const regex = new RegExp(
      `${this.escapeRegex(this.openTag)}\\s*#(\\w+)(?:\\s+(.+?))?\\s*${this.escapeRegex(this.closeTag)}([\\s\\S]*?)${this.escapeRegex(this.openTag)}\\s*\\/(\\w+)\\s*${this.escapeRegex(this.closeTag)}`,
      "g",
    );

    let result = template;
    let match;

    while ((match = regex.exec(result)) !== null) {
      const [fullMatch, directiveName, params, body, closingTag] = match;

      if (directiveName !== closingTag) {
        continue;
      }

      // 鑷棴鍚堟寚浠ょ敱 renderSelfClosingDirectives 澶勭悊锛岃繖閲岃烦杩嘰n      if (SELF_CLOSING_DIRECTIVES.has(directiveName)) {
        continue;
      }

      const handler = this.directives.get(directiveName);
      if (!handler) continue;

      const replacement = handler(params?.trim() ?? "", body, context, this, depth);
      result = result.replace(fullMatch, replacement);
      regex.lastIndex = 0;
    }

    return result;
  }

  // 鈹€鈹€ 鍙橀噺鎻掑€?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 澶勭悊妯℃澘涓殑鍙橀噺鎻掑€笺€俓n   */
  private renderVariables(template: string, context: PromptContext): string {
    const variableRegex = new RegExp(
      `${this.escapeRegex(this.openTag)}\\s*(?!#|/|__)([\\s\\S]+?)\\s*${this.escapeRegex(this.closeTag)}`,
      "g",
    );

    return template.replace(variableRegex, (_match, expression: string) => {
      const trimmed = expression.trim();

      // 澶勭悊榛樿鍊艰娉曪細variable || fallback
      const pipeIndex = trimmed.indexOf("||");
      let path: string;
      let fallback: string | undefined;

      if (pipeIndex !== -1) {
        path = trimmed.substring(0, pipeIndex).trim();
        fallback = trimmed.substring(pipeIndex + 2).trim();
      } else {
        path = trimmed;
      }

      const value = this.resolvePath(context.variables, path);

      if (value === undefined || value === null) {
        if (fallback !== undefined) {
          const fallbackValue = this.resolvePath(context.variables, fallback);
          return this.safeRender(fallbackValue ?? fallback);
        }
        return this.safeRender(this.options.undefinedPlaceholder);
      }

      if (typeof value === "function") {
        return this.safeRender(value.call(context));
      }

      return this.safeRender(value);
    });
  }

  // 鈹€鈹€ 杈呭姪鏂规硶 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private safeRender(value: unknown): string {
    const str = value === null || value === undefined
      ? this.options.undefinedPlaceholder
      : String(value);

    if (this.options.escapeHtml) {
      return str
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
    }
    return str;
  }

  private resolvePath(obj: Record<string, unknown>, path: string): unknown {
    const parts = path.split(".");
    let current: unknown = obj;

    for (const part of parts) {
      if (current === null || current === undefined) {
        return undefined;
      }
      if (typeof current === "object" && part in (current as Record<string, unknown>)) {
        current = (current as Record<string, unknown>)[part];
      } else {
        return undefined;
      }
    }

    return current;
  }

  private evaluateCondition(condition: string, context: PromptContext): boolean {
    let expr = condition.trim();

    const isNegated = expr.startsWith("!");
    if (isNegated) expr = expr.substring(1).trim();

    if (expr === "true") return !isNegated;
    if (expr === "false") return isNegated;

    const value = context.variables?.[expr];
    const isTruthy = value !== undefined && value !== null && value !== false && value !== 0 && value !== "";
    return isNegated ? !isTruthy : isTruthy;
  }

  private formatDate(date: Date, format: string): string {
    const map: Record<string, string> = {
      "YYYY": String(date.getFullYear()),
      "MM": String(date.getMonth() + 1).padStart(2, "0"),
      "DD": String(date.getDate()).padStart(2, "0"),
      "HH": String(date.getHours()).padStart(2, "0"),
      "mm": String(date.getMinutes()).padStart(2, "0"),
      "ss": String(date.getSeconds()).padStart(2, "0"),
    };

    let result = format;
    for (const [key, value] of Object.entries(map)) {
      result = result.replace(key, value);
    }
    return result;
  }

  private escapeRegex(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
}

/**
 * @cortex/prompt-kit 鈥?Prompt 鏍￠獙鍣╘n *
 * 鏍￠獙 PromptTemplate 鐨勫畬鏁存€у拰娓叉煋浜х墿鐨勮川閲忋€俓n * 鏀寔鑷畾涔夋牎楠岃鍒欏拰娈靛瓨鍦ㄦ€ф鏌ャ€俓n *
 * @see DESIGN.md 搂3.4 PromptValidator
 */

import {
  PromptBlockType,
  type PromptTemplate,
  type PromptResult,
  type ValidationResult,
  type ValidationError,
  type SectionCheckResult,
} from "../types.js";

/**
 * 鏍￠獙瑙勫垯瀹氫箟銆俓n */
export type ValidationRule = (
  template: PromptTemplate,
  result?: PromptResult,
) => ValidationError | null;

/**
 * PromptValidator 鈥?鏍￠獙鍣ㄣ€俓n */
export class PromptValidator {
  private rules: ValidationRule[] = [];

  constructor() {
    // 娉ㄥ唽榛樿鏍￠獙瑙勫垯
    this.registerDefaultRules();
  }

  /**
   * 鏍￠獙妯℃澘缁撴瀯銆俓n   */
  validateTemplate(template: PromptTemplate): ValidationResult {
    const errors: ValidationError[] = [];
    const warnings: string[] = [];

    // 1. 蹇呰瀛楁瀛樺湪
    if (!template.id) {
      errors.push({ path: "id", message: "妯℃澘 ID 涓嶈兘涓虹┖", severity: "error" });
    }
    if (!template.name) {
      errors.push({ path: "name", message: "妯℃澘鍚嶇О涓嶈兘涓虹┖", severity: "error" });
    }
    if (!template.version) {
      warnings.push("妯℃澘鐗堟湰鍙锋湭璁剧疆锛岄粯璁や娇鐢?0.1.0");
    }

    // 2. 鍧楁鏌n    if (!template.blocks || template.blocks.length === 0) {
      errors.push({ path: "blocks", message: "妯℃澘鑷冲皯鍖呭惈涓€涓涔夊潡", severity: "error" });
    } else {
      // 鍧?ID 鍞竴鎬n      const ids = new Map<string, number>();
      for (const block of template.blocks) {
        const count = ids.get(block.id) ?? 0;
        ids.set(block.id, count + 1);
      }
      for (const [id, count] of ids) {
        if (count > 1) {
          errors.push({
            path: `blocks.${id}`,
            message: `鍧?ID "${id}" 閲嶅鍑虹幇 ${count} 娆,
            severity: "error",
          });
        }
      }

      // 鑷冲皯鍖呭惈 Identity 鎴?Persona 鍧梊n      const hasIdentity = template.blocks.some(
        (b) => b.type === PromptBlockType.Identity || b.type === PromptBlockType.Persona,
      );
      if (!hasIdentity) {
        warnings.push("妯℃澘缂哄皯 Identity 鎴?Persona 鍧楋紝鍙兘鏃犳硶姝ｇ‘寤虹珛瑙掕壊");
      }
    }

    // 3. 鎵ц鑷畾涔夎鍒?鈥?閿欒绾х殑鏀惧叆 errors锛岃鍛婄骇鐨勬斁鍏?warnings
    for (const rule of this.rules) {
      const error = rule(template);
      if (error) {
        if (error.severity === "warning") {
          warnings.push(error.message);
        } else {
          errors.push(error);
        }
      }
    }

    return {
      valid: errors.filter((e) => e.severity === "error").length === 0,
      errors,
      warnings,
    };
  }

  /**
   * 鏍￠獙娓叉煋缁撴灉銆俓n   */
  validateResult(result: PromptResult): ValidationResult {
    const errors: ValidationError[] = [];
    const warnings: string[] = [];

    // 娓叉煋缁撴灉蹇呴』鍖呭惈鏂囨湰
    if (!result.text || result.text.trim().length === 0) {
      errors.push({
        path: "text",
        message: "娓叉煋缁撴灉涓虹┖",
        severity: "error",
      });
    }

    // 妫€鏌ユ槸鍚︽湁楂樹紭鍏堢骇鐨勫潡琚烦杩嘰n    const criticalSkipped = result.skippedBlocks.filter((sb) => sb.reason === "access_denied");
    for (const skipped of criticalSkipped) {
      warnings.push(`鍧?"${skipped.id}" 鍥犺闂檺鍒惰璺宠繃`);
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
    };
  }

  /**
   * 妫€鏌ュ繀闇€娈垫槸鍚﹀瓨鍦ㄣ€俓n   */
  checkRequiredSections(
    result: PromptResult,
    requiredTypes: PromptBlockType[],
  ): SectionCheckResult {
    const renderedTypes = new Set(result.renderedBlocks.map((b) => b.type));
    const missing: PromptBlockType[] = [];
    const warnings: string[] = [];

    for (const type of requiredTypes) {
      if (!renderedTypes.has(type)) {
        missing.push(type);
        warnings.push(`缂哄皯蹇呴渶鐨勬绫诲瀷: ${type}`);
      }
    }

    return {
      allPresent: missing.length === 0,
      present: Array.from(renderedTypes).filter((t) => requiredTypes.includes(t)),
      missing,
      warnings,
    };
  }

  /**
   * 娉ㄥ唽鑷畾涔夋牎楠岃鍒欍€俓n   */
  registerRule(name: string, rule: ValidationRule): void {
    this.rules.push(rule);
  }

  /**
   * 娉ㄥ唽榛樿鏍￠獙瑙勫垯銆俓n   */
  private registerDefaultRules(): void {
    // 瑙勫垯锛氭鏌ユā鏉挎槸鍚﹀寘鍚湭闂悎鐨勫彉閲忓紩鐢╘n    this.registerRule("unclosed-variables", (template) => {
      for (const block of template.blocks) {
        const openCount = (block.content.match(/\{\{/g) || []).length;
        const closeCount = (block.content.match(/\}\}/g) || []).length;
        if (openCount !== closeCount) {
          return {
            path: `blocks.${block.id}`,
            message: `鍧?"${block.id}" 涓瓨鍦ㄦ湭闂悎鐨勬ā鏉胯娉曪紙寮€ {{: ${openCount}, 闂?}}: ${closeCount}锛塦,
            severity: "error",
            code: "UNCLOSED_SYNTAX",
          };
        }
      }
      return null;
    });

    // 瑙勫垯锛氭鏌ユ潯浠朵笌寰幆鐨勬垚瀵规€n    this.registerRule("matching-directives", (template) => {
      for (const block of template.blocks) {
        const content = block.content;
        const ifOpen = (content.match(/\{\{#if\b/g) || []).length;
        const ifClose = (content.match(/\{\{\/if\b/g) || []).length;
        const eachOpen = (content.match(/\{\{#each\b/g) || []).length;
        const eachClose = (content.match(/\{\{\/each\b/g) || []).length;

        if (ifOpen !== ifClose) {
          return {
            path: `blocks.${block.id}`,
            message: `鍧?"${block.id}" 涓?{{#if}} 涓?{{/if}} 鏁伴噺涓嶅尮閰嶏紙寮€: ${ifOpen}, 闂? ${ifClose}锛塦,
            severity: "error",
            code: "MISMATCHED_DIRECTIVES",
          };
        }
        if (eachOpen !== eachClose) {
          return {
            path: `blocks.${block.id}`,
            message: `鍧?"${block.id}" 涓?{{#each}} 涓?{{/each}} 鏁伴噺涓嶅尮閰嶏紙寮€: ${eachOpen}, 闂? ${eachClose}锛塦,
            severity: "error",
            code: "MISMATCHED_DIRECTIVES",
          };
        }
      }
      return null;
    });

    // 瑙勫垯锛氭鏌?Source 瀛楁
    this.registerRule("source-tracking", (template) => {
      if (!template.source && template.blocks.length > 0) {
        return {
          path: "source",
          message: "妯℃澘鏈爣娉ㄦ潵婧愶紝鐗堟湰杩借釜鍙兘涓嶅畬鏁碶

warning",
          code: "MISSING_SOURCE",
        };
      }
      return null;
    });
  }
}

/**
 * @cortex/prompt-kit 鈥?Prompt 鐗堟湰绠＄悊
 *
 * 璁板綍鍜岀鐞?prompt 妯℃澘鐨勭増鏈彉鏇淬€俓n * 鏀寔鐗堟湰鍘嗗彶璁板綍銆佺増鏈洖閫€鍜屽樊寮傚姣斻€俓n *
 * @see DESIGN.md 搂3.6 PromptVersion
 */

import type { VersionRecord, VersionDiff, PromptTemplate } from "../types.js";

/**
 * PotVersion 鈥斺€?鐗堟湰绠＄悊鍣ㄣ€俓n *
 * 鐗堟湰璁板綍鍙寔涔呭寲鍒?JSON 鏂囦欢鎴?MemoryStore銆俓n * Core-1 闃舵锛氬唴瀛樺瓨鍌ㄣ€俓n * Core-2锛氭帴鍏?MemoryStore 鎸佷箙鍖栥€俓n */
export class PromptVersion {
  /** templateId 鈫?鐗堟湰璁板綍鍒楄〃锛堟渶鏂板湪鍓嶏級 */
  private history: Map<string, VersionRecord[]> = new Map();
  /** templateId 鈫?鐗堟湰蹇収 */
  private snapshots: Map<string, Map<string, PromptTemplate>> = new Map();

  /**
   * 鑾峰彇妯℃澘鐗堟湰鍘嗗彶銆俓n   */
  getHistory(templateId: string): VersionRecord[] {
    return this.history.get(templateId) ?? [];
  }

  /**
   * 鑾峰彇鎸囧畾鐗堟湰鐨勬ā鏉垮揩鐓с€俓n   */
  getVersion(templateId: string, version: string): Promise<PromptTemplate | null> {
    const templateVersions = this.snapshots.get(templateId);
    if (!templateVersions) return Promise.resolve(null);
    return Promise.resolve(templateVersions.get(version) ?? null);
  }

  /**
   * 璁板綍鐗堟湰鍙樻洿銆俓n   * 浼氳嚜鍔ㄤ繚瀛樺綋鍓嶆ā鏉跨殑蹇収銆俓n   */
  recordChange(
    record: VersionRecord,
    currentTemplate?: PromptTemplate,
  ): void {
    // 杩藉姞鍒板巻鍙瞈n    const records = this.history.get(record.templateId) ?? [];
    records.unshift(record); // 鏈€鏂板湪鍓峔n    this.history.set(record.templateId, records);

    // 淇濆瓨蹇収
    if (currentTemplate) {
      const templateVersions = this.snapshots.get(record.templateId) ?? new Map();
      templateVersions.set(record.version, currentTemplate);
      this.snapshots.set(record.templateId, templateVersions);
    }
  }

  /**
   * 瀵规瘮涓や釜鐗堟湰鐨勫樊寮傘€俓n   */
  diff(templateId: string, fromVersion: string, toVersion: string): VersionDiff {
    const templateVersions = this.snapshots.get(templateId);
    if (!templateVersions) {
      return {
        templateId,
        from: fromVersion,
        to: toVersion,
        additions: [],
        removals: [],
        modifications: [],
      };
    }

    const from = templateVersions.get(fromVersion);
    const to = templateVersions.get(toVersion);

    if (!from || !to) {
      return {
        templateId,
        from: fromVersion,
        to: toVersion,
        additions: [],
        removals: [],
        modifications: [],
        // 鏍囪缂哄け鐗堟湰
        ...(!from ? { _note: `鐗堟湰 ${fromVersion} 鏃犲揩鐓 } : {}),
        ...(!to ? { _note: `鐗堟湰 ${toVersion} 鏃犲揩鐓 } : {}),
      };
    }

    return this.computeDiff(from, to, fromVersion, toVersion);
  }

  /**
   * 璁＄畻涓や釜妯℃澘鐗堟湰鐨勫樊寮傘€俓n   */
  private computeDiff(
    from: PromptTemplate,
    to: PromptTemplate,
    fromVersion: string,
    toVersion: string,
  ): VersionDiff {
    const fromBlockMap = new Map(from.blocks.map((b) => [b.id, b]));
    const toBlockMap = new Map(to.blocks.map((b) => [b.id, b]));

    const fromIds = new Set(from.blocks.map((b) => b.id));
    const toIds = new Set(to.blocks.map((b) => b.id));

    const additions = [...toIds].filter((id) => !fromIds.has(id));
    const removals = [...fromIds].filter((id) => !toIds.has(id));
    const common = [...fromIds].filter((id) => toIds.has(id));

    const modifications: VersionDiff["modifications"] = [];
    for (const id of common) {
      const fromBlock = fromBlockMap.get(id);
      const toBlock = toBlockMap.get(id);
      if (!fromBlock || !toBlock) continue;

      if (fromBlock.content !== toBlock.content || fromBlock.priority !== toBlock.priority) {
        modifications.push({
          blockId: id,
          type: fromBlock.type,
          before: fromBlock.content,
          after: toBlock.content,
        });
      }
    }

    return {
      templateId: from.id,
      from: fromVersion,
      to: toVersion,
      additions,
      removals,
      modifications,
    };
  }
}

