  }

  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  // 鍏紑灞炴€n  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /** 褰撳墠鏂矾鍣ㄧ姸鎬?*/
  get state(): CircuitState {
    return this._state;
  }

  /**
   * 褰撳墠杩炵画澶辫触娆℃暟锛堝彧璇伙級銆俓n   * 鐢ㄤ簬鐩戞帶鍜岃皟璇曘€俓n   */
  get consecutiveFailures(): number {
    return this._consecutiveFailures;
  }

  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  // ICircuitBreaker 鎺ュ彛瀹炵幇
  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 鍦ㄦ柇璺櫒淇濇姢涓嬫墽琛屽紓姝ヨ皟鐢ㄣ€俓n   *
   * 鎵ц閫昏緫鍙栧喅浜庡綋鍓嶇姸鎬侊細
   * - **CLOSED**: 鏀捐璋冪敤锛屾牴鎹粨鏋滆褰曟垚鍔?澶辫触
   * - **OPEN**: 妫€鏌ユ槸鍚﹁揪鍒板崐寮€绛夊緟鏃堕棿锛岃嫢鏈揪鍒板垯蹇€熷け璐ワ紙鎴栨墽琛岄檷绾э級
   * - **HALF_OPEN**: 鏀捐鍗曚竴璇曟帰璇锋眰锛屾垚鍔熷垯闂悎锛屽け璐ュ垯鐔旀柇
   *
   * @param fn 琚繚鎶ょ殑寮傛鍑芥暟
   * @param fallback 鍙€夐檷绾у嚱鏁帮紝鐔旀柇鏃惰皟鐢╘n   * @returns 鎵ц缁撴灉鎴栭檷绾х粨鏋淺n   *
   * @throws {CircuitBreakerOpenError} 褰撴柇璺櫒澶勪簬 OPEN 鐘舵€佷笖鏈彁渚?fallback 鏃舵姏鍑篭n   */
  async call<T>(fn: () => Promise<T>, fallback?: () => Promise<T>): Promise<T> {
    // 鈹€鈹€ 鐘舵€侀妫€ 鈹€鈹€
    if (this._state === 'OPEN') {
      // 妫€鏌ユ槸鍚﹀簲杩涘叆 HALF_OPEN
      if (Date.now() - this._openedAt >= this._halfOpenAfterMs) {
        this._transitionTo('HALF_OPEN');
      } else {
        // 鐔旀柇涓細鎵ц闄嶇骇鎴栧揩閫熷け璐n        if (fallback !== undefined) {
          return fallback();
        }
        throw new CircuitBreakerOpenError(this.name);
      }
    }

    // HALF_OPEN 鐘舵€佷笅锛屽鏋滃厛鍓嶈瘯鎺㈣姹傚凡鎴愬姛锛堜笉搴斿彂鐢燂紝闃插尽鎬ф鏌ワ級
    // 姝ｅ父 HALF_OPEN 娴佺▼鍦?recordSuccess/recordFailure 涓鐞哱n
    try {
      const result = await fn();
      this.recordSuccess();
      return result;
    } catch (err) {
      this.recordFailure();

      // 濡傛灉鎻愪緵浜嗛檷绾у嚱鏁帮紝鍦ㄥけ璐ユ椂灏濊瘯闄嶇骇
      if (fallback !== undefined) {
        return fallback();
      }

      throw err;
    }
  }

  /**
   * 鎵嬪姩璁板綍涓€娆℃垚鍔熴€俓n   *
   * 鏁堟灉锛歕n   * - 娓呴浂杩炵画澶辫触璁℃暟鍣╘n   * - 鑻ュ綋鍓嶄负 HALF_OPEN锛岃浆涓?CLOSED
   */
  recordSuccess(): void {
    this._consecutiveFailures = 0;

    if (this._state === 'HALF_OPEN') {
      this._transitionTo('CLOSED');
    }
  }

  /**
   * 鎵嬪姩璁板綍涓€娆″け璐ャ€俓n   *
   * 鏁堟灉锛歕n   * - 杩炵画澶辫触璁℃暟鍣?+1
   * - 鑻ュ綋鍓嶄负 HALF_OPEN锛岃浆涓?OPEN
   * - 鑻ュ綋鍓嶄负 CLOSED 涓旇繛缁け璐ヨ揪鍒伴槇鍊硷紝杞负 OPEN
   */
  recordFailure(): void {
    this._consecutiveFailures++;

    if (this._state === 'HALF_OPEN') {
      // 鍗婂紑璇曟帰澶辫触 鈫?绔嬪嵆鐔旀柇
      this._transitionTo('OPEN');
      return;
    }

    if (this._state === 'CLOSED' && this._consecutiveFailures >= this._threshold) {
      this._transitionTo('OPEN');
    }
    // OPEN 鐘舵€佷笅 recordFailure 浠呭鍔犺鏁帮紝鐘舵€佷笉鍙榎n  }

  /**
   * 閲嶇疆鏂矾鍣ㄥ埌 CLOSED 鐘舵€併€俓n   *
   * 娓呴浂杩炵画澶辫触璁℃暟鍣紝娓呯┖鎵€鏈夊唴閮ㄧ姸鎬併€俓n   * 閫傜敤浜庯細
   * - 鎵嬪姩鎭㈠
   * - 鍛ㄦ湡鎬у仴搴锋鏌ュ悗閲嶇疆
   * - 娴嬭瘯鐢ㄤ緥閲嶇疆
   */
  reset(): void {
    this._consecutiveFailures = 0;
    this._openedAt = 0;
    this._transitionTo('CLOSED');
  }

  /**
   * 寮哄埗杞崲鍒版寚瀹氱姸鎬侊紙娴嬭瘯/杩愮淮鐢級銆俓n   *
   * 娉ㄦ剰浜嬮」锛歕n   * - 寮哄埗杞崲涓?CLOSED 鏃讹細娓呴浂杩炵画澶辫触璁℃暟鍣╘n   * - 寮哄埗杞崲涓?OPEN 鏃讹細璁剧疆鐔旀柇鏃堕棿鎴充负褰撳墠鏃堕棿
   * - 寮哄埗杞崲涓?HALF_OPEN 鏃讹細淇濇寔褰撳墠杩炵画澶辫触璁℃暟涓嶅彉
   *
   * @param state 鐩爣鐘舵€乗n   */
  forceState(state: CircuitState): void {
    if (state === 'CLOSED') {
      this._consecutiveFailures = 0;
      this._openedAt = 0;
    } else if (state === 'OPEN') {
      this._openedAt = Date.now();
    }
    // HALF_OPEN: 涓嶉渶瑕佺壒娈婂鐞哱n
    this._transitionTo(state);
  }

  /**
   * 璁㈤槄鐘舵€佸彉鏇翠簨浠躲€俓n   *
   * @param handler 鐘舵€佸彉鏇村鐞嗗嚱鏁帮紝鎺ユ敹鏂扮姸鎬佸拰鏃х姸鎬乗n   *
   * @example
   * ```typescript
   * breaker.onStateChange((state, previous) => {
   *   logger.info(`鏂矾鍣ㄧ姸鎬佸彉鏇? ${previous} 鈫?${state}`);
   * });
   * ```
   */
  onStateChange(handler: (state: CircuitState, previous: CircuitState) => void): void {
    this._handlers.push(handler);
  }

  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  // 鍐呴儴鏂规硶
  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 鎵ц鐘舵€佽浆鎹㈠苟閫氱煡鎵€鏈夊凡娉ㄥ唽鐨勪簨浠跺鐞嗗櫒銆俓n   *
   * 鐘舵€佽浆鎹㈠畧鍗細
   * - 濡傛灉鐩爣鐘舵€佷笌褰撳墠鐘舵€佺浉鍚岋紝涓嶈繘琛岃浆鎹n   * - 杞崲鍚庝細瑙﹀彂鎵€鏈?onStateChange 鍥炶皟
   * - 鍗曚釜澶勭悊鍣ㄧ殑寮傚父涓嶄細褰卞搷鍏朵粬澶勭悊鍣紙寮傚父闅旂锛塡n   *
   * @param newState 鐩爣鐘舵€乗n   */
  private _transitionTo(newState: CircuitState): void {
    if (this._state === newState) {
      return;
    }

    const previous = this._state;
    this._state = newState;

    if (newState === 'OPEN') {
