    }

    // 閫氱煡鎵€鏈夌姸鎬佸彉鏇村鐞嗗櫒
    for (const handler of this._handlers) {
      try {
        handler(newState, previous);
      } catch {
        // 浜嬩欢澶勭悊鍣ㄥ紓甯搁殧绂?鈥斺€?涓嶄腑鏂叾浠栧鐞嗗櫒
      }
    }
  }
}

