  onRecordFailure(breaker: StateMachineCircuitBreaker): CircuitState;

  /** 杩涘叆姝ょ姸鎬佹椂鐨勯挬瀛愶紙閲嶇疆璁℃暟鍣ㄧ瓑锛?*/
  onEnter(breaker: StateMachineCircuitBreaker): void;
}

