const OPEN_STATE: FsmState = {
  state: 'OPEN',

  onRecordSuccess(_breaker: StateMachineCircuitBreaker): CircuitState {
    // OPEN 鐘舵€佷笅涓嶄細鏀捐姝ｅ父璋冪敤锛屾鏂规硶涓嶅簲琚皟鐢╘n    return 'OPEN';
  },

  onRecordFailure(_breaker: StateMachineCircuitBreaker): CircuitState {
    // OPEN 鐘舵€佷笅涓嶄細鏀捐姝ｅ父璋冪敤锛屾鏂规硶涓嶅簲琚皟鐢╘n    return 'OPEN';
  },

  onEnter(breaker: StateMachineCircuitBreaker): void {
