/**
 * StateMachineCircuitBreaker 鈥斺€?鍩轰簬鏈夐檺鐘舵€佹満鐨勬柇璺櫒瀹炵幇銆俓n *
 * 浣跨敤鏄惧紡鐨勭姸鎬佸璞★紙FsmState锛夊皝瑁?CLOSED / OPEN / HALF_OPEN
 * 涓夋€佷笅鐨勮浆鎹㈣鍒欙紝閬垮厤鏁ｅ脊寮?switch-case銆俓n *
 * 鏀寔涓ょ鐔旀柇鍒ゅ畾绛栫暐锛歕n * - 'consecutive'锛堣繛缁け璐ヨ鏁帮級锛氳繛缁?failureCount 娆″け璐ュ悗鐔旀柇
 * - 'sliding-window'锛堟粦鍔ㄧ獥鍙ｅけ璐ョ巼锛夛細绐楀彛鍐呭け璐ョ巼瓒呰繃 threshold 鏃剁啍鏂璡n *
 * 鎵ц璇箟锛歕n * - call(fn, fallback) 鐨勮亴璐ｆ槸銆屾斁琛屾垨鎷掔粷銆?銆岃褰曟垚鍔熸垨澶辫触銆峔n * - fn 鎴愬姛 鈫?recordSuccess 鈫?鍙兘瑙﹀彂鐘舵€佽浆鎹n * - fn 澶辫触 鈫?recordFailure 鈫?鍙兘瑙﹀彂鐘舵€佽浆鎹?+ 灏濊瘯 fallback
 * - 鐔旀柇鏃讹紙OPEN锛夆啋 鐩存帴鎵ц fallback 鎴栨姏鍑?CircuitBreakerOpenError
 *
 * @example
 * ```typescript
 * // 杩炵画澶辫触妯″紡锛堥粯璁わ級
 * const breaker = new StateMachineCircuitBreaker('llm-api', {
 *   threshold: 5,
 *   windowMs: 0,
 *   halfOpenAfterMs: 30000,
 *   maxHalfOpenRequests: 3,
 * });
 *
 * // 婊戝姩绐楀彛澶辫触鐜囨ā寮廫n * const breaker2 = new StateMachineCircuitBreaker('search-api', {
 *   threshold: 0.5,
 *   windowMs: 60000,
 *   halfOpenAfterMs: 30000,
 *   minimumCalls: 10,
 *   strategy: 'sliding-window',
 * });
 *
 * // 鐩戝惉鐘舵€佸彉鏇碶n * breaker.onStateChange((state, previous) => {
 *   logger.info(`鏂矾鍣?${breaker.name}: ${previous} 鈫?${state}`);
 * });
 *
 * // 鍙椾繚鎶よ皟鐢╘n * const result = await breaker.call(
 *   () => api.fetchData(),
 *   () => cachedData,  // 鐔旀柇鏃堕檷绾n * );
 * ```
 */
export class StateMachineCircuitBreaker implements ICircuitBreaker {
  /** 鏂矾鍣ㄥ悕绉帮紙鐢ㄤ簬鏃ュ織鍜岀洃鎺э級 */
  readonly name: string;

  // 鈹€鈹€ 鍐呴儴鐘舵€?鈹€鈹€

  /** 褰撳墠 FSM 鐘舵€佸鐞嗗櫒 */
  private _handler: FsmState;

  /**
   * 鐔旀柇寮€鍚殑鏃堕棿鎴筹紙鐢ㄤ簬鍒ゆ柇 halfOpenAfterMs锛夈€俓n   * @internal FSM 鐘舵€佸璞″湪鍚屼竴妯″潡鍐呰闂灞炴€с€俓n   */
  _openedAt = 0;

  /**
   * 杩炵画澶辫触璁℃暟锛堜袱绉嶇瓥鐣ュ潎浼氱淮鎶ゆ鍊硷級銆俓n   * @internal FSM 鐘舵€佸璞″湪鍚屼竴妯″潡鍐呰闂灞炴€с€俓n   */
  _consecutiveFailures = 0;

  /**
   * HALF_OPEN 鐘舵€佷笅璇曟帰鎴愬姛鐨勬鏁般€俓n   * @internal FSM 鐘舵€佸璞″湪鍚屼竴妯″潡鍐呰闂灞炴€с€俓n   */
  _halfOpenSuccesses = 0;

  /** 婊戝姩绐楀彛璋冪敤璁板綍锛堜粎 sliding-window 绛栫暐浣跨敤锛?*/
  private readonly _callRecords: Array<{ timestamp: number; success: boolean }> = [];

  /**
   * 瑙ｆ瀽鍚庣殑閰嶇疆閫夐」銆俓n   * @internal FSM 鐘舵€佸璞″湪鍚屼竴妯″潡鍐呰闂灞炴€с€俓n   */
  _resolvedOptions: Required<CircuitBreakerOptions>;

  /** 鐘舵€佸彉鏇村鐞嗗櫒鍒楄〃 */
  private readonly _stateChangeHandlers: Array<(state: CircuitState, previous: CircuitState) => void> = [];

  /**
   * @param name 鏂矾鍣ㄥ悕绉帮紙鐢ㄤ簬鏃ュ織鍜岀洃鎺э級
   * @param options 鏂矾鍣ㄩ厤缃甛n   *
   * @example
   * ```typescript
   * // 杩炵画澶辫触妯″紡锛? 娆¤繛缁け璐ュ悗鐔旀柇锛?0 绉掑悗灏濊瘯鎭㈠
   * const breaker = new StateMachineCircuitBreaker('llm-api', {
   *   threshold: 5,
   *   windowMs: 0,
   *   halfOpenAfterMs: 30000,
   * });
   *
   * // 婊戝姩绐楀彛妯″紡锛?0 绉掔獥鍙ｅ唴 50% 澶辫触鐜囪Е鍙戠啍鏂璡n   * const breaker2 = new StateMachineCircuitBreaker('search-api', {
   *   threshold: 0.5,
   *   windowMs: 60000,
   *   halfOpenAfterMs: 30000,
   *   minimumCalls: 10,
