  constructor(name: string, options: CircuitBreakerOptions) {
    this.name = name;
    this._resolvedOptions = {
      threshold: options.threshold,
      windowMs: options.windowMs,
      halfOpenAfterMs: options.halfOpenAfterMs,
      maxHalfOpenRequests: options.maxHalfOpenRequests ?? 1,
      minimumCalls: options.minimumCalls ?? (options.strategy === 'sliding-window' ? 10 : 1),
      strategy: options.strategy ?? 'consecutive',
    };
    this._handler = CLOSED_STATE;
  }

  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  // 鍏紑灞炴€n  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /** 褰撳墠鏂矾鍣ㄧ姸鎬?*/
  get state(): CircuitState {
    return this._handler.state;
  }

  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  // ICircuitBreaker 鎺ュ彛瀹炵幇
  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 鍦ㄦ柇璺櫒淇濇姢涓嬫墽琛屽紓姝ヨ皟鐢ㄣ€俓n   *
   * ### 琛屼负鐭╅樀
   *
   * | 褰撳墠鐘舵€?| fn 鎵ц | fallback | 缁撴灉 |
   * |----------|---------|----------|------|
   * | CLOSED   | 鎴愬姛    | 鈥?       | recordSuccess + 杩斿洖缁撴灉 |
   * | CLOSED   | 澶辫触    | 鏈?      | recordFailure + 鎵ц fallback + 杩斿洖闄嶇骇缁撴灉 |
   * | CLOSED   | 澶辫触    | 鏃?      | recordFailure + 鎶涘嚭寮傚父 |
   * | OPEN     | 涓嶆墽琛? | 鏈?      | 鎵ц fallback + 杩斿洖闄嶇骇缁撴灉锛堜笉璁板綍锛?|
   * | OPEN     | 涓嶆墽琛? | 鏃?      | 鎶涘嚭 CircuitBreakerOpenError |
   * | HALF_OPEN | 鎴愬姛   | 鈥?       | recordSuccess + 鍙兘闂悎鐢佃矾 |
   * | HALF_OPEN | 澶辫触   | 鏈?      | recordFailure + 鍥炲埌 OPEN + 鎵ц fallback |
   * | HALF_OPEN | 澶辫触   | 鏃?      | recordFailure + 鍥炲埌 OPEN + 鎶涘嚭寮傚父 |
   *
   * @param fn 琚繚鎶ょ殑寮傛鍑芥暟
   * @param fallback 鍙€夐檷绾у嚱鏁帮紝鐔旀柇鎴栧け璐ユ椂璋冪敤
   * @returns fn 鎴?fallback 鐨勬墽琛岀粨鏋淺n   * @throws {CircuitBreakerOpenError} 鏂矾鍣ㄧ啍鏂笖鏃?fallback 鏃舵姏鍑篭n   * @throws {Error} fn 鎴?fallback 鎶涘嚭鐨勫師濮嬪紓甯竆n   */
  async call<T>(fn: () => Promise<T>, fallback?: () => Promise<T>): Promise<T> {
    // 鈹€鈹€ 1. OPEN 鐘舵€佸鐞嗭細鍗婂紑杞崲妫€鏌?+ 蹇€熷け璐?/ 闄嶇骇 鈹€鈹€
    if (this._handler === OPEN_STATE) {
      return this._handleOpenCall(fn, fallback);
    }

    // 鈹€鈹€ 2. CLOSED / HALF_OPEN锛氭斁琛岃皟鐢?鈹€鈹€
    try {
      const result = await fn();
      // fn 鎴愬姛 鈫?璁板綍鎴愬姛
      this._recordSuccess();
      return result;
    } catch (err) {
      // fn 澶辫触 鈫?璁板綍澶辫触
      this._recordFailure();

      // 灏濊瘯闄嶇骇
      if (fallback) {
        return fallback();
      }

      throw err;
    }
  }

  /**
   * 鎵嬪姩璁板綍涓€娆℃垚鍔熴€俓n   *
   * 鐢ㄤ簬闈?call 鍖呰鐨勫満鏅紙濡傛墜鍔ㄤ笂鎶ュ閮ㄨ娴嬪埌鐨勬垚鍔熺粨鏋滐級銆俓n   * 浼氳Е鍙戠姸鎬佽浆鎹㈠垽鏂€俓n   */
  recordSuccess(): void {
    this._evictExpiredRecords();

    if (this._resolvedOptions.strategy === 'sliding-window') {
      this._callRecords.push({ timestamp: Date.now(), success: true });
    }

    const newState = this._handler.onRecordSuccess(this);
    if (newState !== this._handler.state) {
      this._transitionTo(newState);
    }
  }

  /**
   * 鎵嬪姩璁板綍涓€娆″け璐ャ€俓n   *
   * 鐢ㄤ簬闈?call 鍖呰鐨勫満鏅紙濡傛墜鍔ㄤ笂鎶ュ閮ㄨ娴嬪埌鐨勫け璐ョ粨鏋滐級銆俓n   * 浼氳Е鍙戠姸鎬佽浆鎹㈠垽鏂€俓n   */
  recordFailure(): void {
    this._evictExpiredRecords();

    if (this._resolvedOptions.strategy === 'sliding-window') {
      this._callRecords.push({ timestamp: Date.now(), success: false });
    }

    this._consecutiveFailures++;

    const newState = this._handler.onRecordFailure(this);
    if (newState !== this._handler.state) {
      this._transitionTo(newState);
    }
  }

  /**
   * 閲嶇疆鏂矾鍣ㄥ埌 CLOSED 鐘舵€併€俓n   *
   * 娓呴櫎鎵€鏈夎皟鐢ㄨ褰曘€佽繛缁け璐ヨ鏁板拰鍗婂紑鎴愬姛璁℃暟銆俓n   * 閫傜敤浜庢祴璇曟仮澶嶆垨杩愮淮鎵嬪姩鎭㈠銆俓n   */
  reset(): void {
    this._consecutiveFailures = 0;
    this._halfOpenSuccesses = 0;
    this._openedAt = 0;
    this._callRecords.length = 0;
    this._transitionTo('CLOSED');
  }

  /**
   * 寮哄埗杞崲鍒版寚瀹氱姸鎬侊紙娴嬭瘯/杩愮淮鐢級銆俓n   *
   * @param state 鐩爣鐘舵€乗n   *
   * @example
   * ```typescript
   * breaker.forceState('OPEN');   // 鎵嬪姩鐔旀柇
   * breaker.forceState('CLOSED'); // 鎵嬪姩鎭㈠
   * ```
   */
  forceState(state: CircuitState): void {
    switch (state) {
      case 'CLOSED':
        this._consecutiveFailures = 0;
        this._halfOpenSuccesses = 0;
        this._openedAt = 0;
        this._callRecords.length = 0;
        break;
      case 'OPEN':
        this._consecutiveFailures = 0;
        this._halfOpenSuccesses = 0;
        this._openedAt = Date.now();
        this._callRecords.length = 0;
        break;
      case 'HALF_OPEN':
        // 杩涘叆 HALF_OPEN 涓嶉噸缃繛缁け璐ヨ鏁癨n        this._halfOpenSuccesses = 0;
        break;
    }
    this._transitionTo(state);
  }

  /**
   * 璁㈤槄鐘舵€佸彉鏇翠簨浠躲€俓n   *
   * @param handler 鐘舵€佸彉鏇村洖璋冿紝鎺ユ敹 (newState, previousState)
   *
   * @example
   * ```typescript
   * breaker.onStateChange((state, previous) => {
   *   metrics.recordCircuitBreakerState(breaker.name, state);
   * });
   * ```
   */
  onStateChange(handler: (state: CircuitState, previous: CircuitState) => void): void {
    this._stateChangeHandlers.push(handler);
  }

  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
  // 鍐呴儴鏂规硶
  // 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /**
   * 澶勭悊 OPEN 鐘舵€佷笅鐨勮皟鐢ㄣ€俓n   *
   * 妫€鏌?halfOpenAfterMs 鏄惁宸茶秴鏃讹細
   * - 瓒呮椂 鈫?鍒囨崲鍒?HALF_OPEN 骞堕噸鏂版墽琛?call锛堥€掑綊涓€娆★級
   * - 鏈秴鏃?鈫?鎵ц fallback 鎴栨姏鍑?CircuitBreakerOpenError
   */
  private async _handleOpenCall<T>(
    fn: () => Promise<T>,
    fallback: (() => Promise<T>) | undefined,
  ): Promise<T> {
    // 妫€鏌ユ槸鍚﹀簲杩涘叆鍗婂紑璇曟帰
    if (Date.now() - this._openedAt >= this._resolvedOptions.halfOpenAfterMs) {
      this._transitionTo('HALF_OPEN');
      // 鐘舵€佸凡鍙樹负 HALF_OPEN锛岄噸鏂拌皟鐢紙閫掑綊浣嗗彧鏈変竴娆★級
      return this.call(fn, fallback);
    }

    // 浠嶅浜庣啍鏂姸鎬乗n    if (fallback) {
      return fallback();
    }

    throw new CircuitBreakerOpenError(this.name);
  }

  /**
   * 鍐呴儴璁板綍鎴愬姛锛堝惈婊戝姩绐楀彛璁板綍 + 鐘舵€佽浆鎹級銆俓n   */
  private _recordSuccess(): void {
    this._evictExpiredRecords();

    if (this._resolvedOptions.strategy === 'sliding-window') {
      this._callRecords.push({ timestamp: Date.now(), success: true });
    }

    this._consecutiveFailures = 0;

    const newState = this._handler.onRecordSuccess(this);
    if (newState !== this._handler.state) {
      this._transitionTo(newState);
    }
  }

  /**
   * 鍐呴儴璁板綍澶辫触锛堝惈婊戝姩绐楀彛璁板綍 + 鐘舵€佽浆鎹級銆俓n   */
  private _recordFailure(): void {
    this._evictExpiredRecords();

    if (this._resolvedOptions.strategy === 'sliding-window') {
      this._callRecords.push({ timestamp: Date.now(), success: false });
    }

    this._consecutiveFailures++;

    const newState = this._handler.onRecordFailure(this);
    if (newState !== this._handler.state) {
      this._transitionTo(newState);
    }
  }

  /**
   * 鍒ゆ柇鏄惁搴斾粠 CLOSED 鍒囨崲鍒?OPEN銆俓n   *
   * 鏍规嵁绛栫暐涓嶅悓锛歕n   * - consecutive锛氳繛缁け璐ユ鏁?>= threshold
   * - sliding-window锛氱獥鍙ｅ唴澶辫触鐜?>= threshold锛堜笖璋冪敤鏁?>= minimumCalls锛塡n   *
   * @internal FSM 鐘舵€佸璞★紙CLOSED_STATE锛夊湪鍚屼竴妯″潡鍐呰闂鏂规硶銆俓n   */
  _shouldTransitionToOpen(): boolean {
    if (this._resolvedOptions.strategy === 'consecutive') {
      return this._consecutiveFailures >= this._resolvedOptions.threshold;
    }

    // sliding-window 绛栫暐
    const total = this._callRecords.length;
    if (total < this._resolvedOptions.minimumCalls) {
      return false; // 璋冪敤閲忎笉瓒筹紝涓嶈Е鍙戠啍鏂璡n    }

    const failed = this._callRecords.filter(r => !r.success).length;
    const failureRate = failed / total;

    return failureRate >= this._resolvedOptions.threshold;
  }

  /**
   * 鎵ц鐘舵€佽浆鎹€俓n   *
   * 娴佺▼锛歕n   * 1. 鑻ユ柊鏃х姸鎬佺浉鍚岋紝璺宠繃锛堥槻姝㈤噸澶嶈Е鍙戯級
   * 2. 鍒囨崲 _handler
   * 3. 璋冪敤鏂扮姸鎬佺殑 onEnter 閽╁瓙
   * 4. 閫氱煡鎵€鏈夋敞鍐岀殑 onStateChange 鐩戝惉鍣╘n   *
   * 鐩戝惉鍣ㄧ殑寮傚父琚殧绂伙紝涓嶅奖鍝嶄富娴佺▼銆俓n   */
  private _transitionTo(newState: CircuitState): void {
    const previous = this._handler.state;

    if (previous === newState) {
      return;
    }

    // 鏌ユ壘鏂扮姸鎬佸搴旂殑 handler
    let newHandler: FsmState;
    switch (newState) {
      case 'CLOSED':
        newHandler = CLOSED_STATE;
        break;
      case 'OPEN':
        newHandler = OPEN_STATE;
        break;
      case 'HALF_OPEN':
        newHandler = HALF_OPEN_STATE;
        break;
    }

    this._handler = newHandler;

    // 璋冪敤鏂扮姸鎬佺殑杩涘叆閽╁瓙
    newHandler.onEnter(this);

    // 閫氱煡鎵€鏈夌洃鍚櫒锛堝紓甯搁殧绂伙級
    for (const handler of this._stateChangeHandlers) {
      try {
        handler(newState, previous);
      } catch {
        // 鍗曚釜鐩戝惉鍣ㄧ殑寮傚父涓嶅奖鍝嶅叾浠栫洃鍚櫒
      }
    }
  }

  /**
   * 娣樻卑杩囨湡璋冪敤璁板綍銆俓n   *
   * 浠?sliding-window 绛栫暐鏈夋晥銆俓n   * 绉诲嚭鎵€鏈夎秴鍑?windowMs 鏃堕棿绐楀彛鐨勬棫璁板綍銆俓n   */
  private _evictExpiredRecords(): void {
    if (this._resolvedOptions.strategy !== 'sliding-window') {
      return;
    }

    const cutoff = Date.now() - this._resolvedOptions.windowMs;
    while (this._callRecords.length > 0) {
      const first = this._callRecords[0];
      if (first !== undefined && first.timestamp < cutoff) {
        this._callRecords.shift();
      } else {
        break;
      }
    }
  }
}

