// 鈹€鈹€ IResilienceRegistry 鎺ュ彛 鈥斺€?娉ㄥ唽涓績濂戠害 鈹€鈹€
// ============================================================

/**
 * IResilienceRegistry 鈥斺€?闊ф€х瓥鐣ユ敞鍐屼腑蹇冩帴鍙ｃ€俓n *
 * 鑱岃矗锛歕n * 1. 娉ㄥ唽/鏌ヨ/鍗歌浇绛栫暐瀹炰緥
 * 2. 缁勫悎鎵ц锛坮etry 鈫?circuitBreaker 鈫?timeout 宓屽锛塡n * 3. 鐘舵€佸揩鐓т笌鐩戞帶
 * 4. 鍏ㄥ眬浜嬩欢閫氱煡
 */
export interface IResilienceRegistry {
  /**
   * 娉ㄥ唽涓€缁勭瓥鐣ュ埌鎸囧畾鍚嶇О銆俓n   * 鍚屽悕娉ㄥ唽浼氳鐩栧凡鏈夋潯鐩紙emit REGISTRY_OVERWRITE 浜嬩欢锛夈€俓n   *
   * @param name 绛栫暐缁勫悕绉帮紙濡?'llm-api', 'search-backend'锛塡n   * @param policies 绛栫暐闆嗗悎
   */
  register(name: string, policies: {
    retry?: IRetryPolicy;
    circuitBreaker?: ICircuitBreaker;
    timeout?: ITimeoutPolicy;
  }): void;

  /** 鍗歌浇鎸囧畾鍚嶇О鐨勬墍鏈夌瓥鐣?*/
  unregister(name: string): void;

  /** 鑾峰彇鎸囧畾鍚嶇О鐨勯噸璇曠瓥鐣?*/
  getRetry(name: string): IRetryPolicy | undefined;

  /** 鑾峰彇鎸囧畾鍚嶇О鐨勬柇璺櫒 */
  getCircuitBreaker(name: string): ICircuitBreaker | undefined;

  /** 鑾峰彇鎸囧畾鍚嶇О鐨勮秴鏃剁瓥鐣?*/
  getTimeout(name: string): ITimeoutPolicy | undefined;

  /**
   * 鍦ㄦ寚瀹氱瓥鐣ヤ繚鎶や笅鎵ц鍑芥暟銆俓n   * 鎵ц椤哄簭锛歵imeout 鈫?circuitBreaker 鈫?retry 鈫?fn
   *
   * @param name 娉ㄥ唽鐨勭瓥鐣ョ粍鍚嶇О
   * @param fn 瑕佹墽琛岀殑鍑芥暟
   * @param overrides 鍙€夎鐩栭厤缃紙涓存椂鏇挎崲宸叉敞鍐岀瓥鐣ワ紝涓嶅奖鍝嶆敞鍐岃〃锛塡n   */
  execute<T>(name: string, fn: () => Promise<T>, overrides?: {
    retry?: IRetryPolicy;
    circuitBreaker?: ICircuitBreaker;
    timeout?: ITimeoutPolicy;
  }): Promise<T>;

  /**
   * 鑾峰彇鎵€鏈夊凡娉ㄥ唽绛栫暐鐨勫揩鐓с€俓n   * 鐢ㄤ簬鐩戞帶闈㈡澘/鍋ュ悍妫€鏌ャ€俓n   */
  snapshot(): Array<{
    name: string;
    retry: string | null;
    circuitBreaker: { name: string; state: CircuitState } | null;
    timeout: string | null;
  }>;

  /** 鍏ㄥ眬閲嶇疆鎵€鏈夌瓥鐣ワ紙娴嬭瘯/鎭㈠鐢級 */
  reset(): void;

  /** 娉ㄥ唽鍏ㄥ眬鐘舵€佸彉鏇寸洃鍚櫒 */
  onEvent(handler: (event: ResilienceEvent) => void): void;
}

