 * - count: 璇ヨ妭鐐瑰凡閲嶈鍒掓鏁癨n * - disposition: "failure"锛堟墽琛屽け璐ワ級| "boundary_violation"锛圓gent瓒婄晫锛塡n */
export interface ReplanItem {
  node: TaskNode;
  reason: string;
  count: number;
  /** 澶勭疆绫诲瀷锛歕

锛堥粯璁わ級| "boundary_violation"锛圓gent瓒婄晫锛?*/
  disposition?: "failure" | "boundary_violation";
}

/**
 * IReplanProvider 鈥斺€?閲嶈鍒掑洖璋冭В鑰︽帴鍙ｃ€俓n *
 * 鏇夸唬鐩存帴渚濊禆 MetaAgent 鍏蜂綋绫伙紝閫氳繃姝ゆ帴鍙ｈВ鑰︺€俓n * engine 渚у湪鏋勯€犳椂浼犲叆瀹炵幇浜嗘鎺ュ彛鐨勯€傞厤鍣紙鍖呰 MetaAgent锛夈€俓n *
 * @since @cortex/scheduler 鐙珛鍖匼n */
export interface IReplanProvider {
  requestReplan(
    node: TaskNode,
    reason: string,
    count: number,
    currentDepth?: number,
    maxReplanPerNode?: number,
  ): Promise<{ nodes: TaskNode[]; impactScope: "local" | "subtree"; error?: string }>;

  requestBoundaryReplan(
    node: TaskNode,
    reason: string,
    count: number,
    currentDepth?: number,
    maxReplanPerNode?: number,
  ): Promise<{ nodes: TaskNode[]; impactScope: "local" | "subtree"; error?: string }>;
}

/**
 * ReplanManager 鈥斺€?閲嶈鍒掔鐞嗗櫒銆俓n *
 * 鑱岃矗锛歕n * - 绠＄悊閲嶈鍒掗槦鍒楋紙鍏ラ槦銆佹秷璐广€侀厤棰濇帶鍒讹級
 * - 璺熻釜 replanMap銆乺eplanCount 绛変腑闂寸姸鎬乗n * - 鎵ц缁撴潫鍚庤В鏋愰噸瑙勫垝閾撅紝淇 original node 鐨?result
 *
 * 鐢熷懡鍛ㄦ湡锛氫笌 Scheduler 1:1 缁戝畾銆傛瘡涓?executeAll() 璋冪敤 reset() 娓呴浂鐘舵€併€俓n *
 * @migrated 浠?@cortex/engine 鎻愬彇锛孧etaAgent 渚濊禆鏀逛负 IReplanProvider 鎺ュ彛
 */
export class ReplanManager {
  private replanCount = new Map<string, number>();
  private replanQueue: ReplanItem[] = [];
  private totalReplans = 0;
  private replanMap = new Map<string, string[]>(); // originalId 鈫?replan-generated new ids

  /**
   * @param board TaskBoard 寮曠敤
   * @param observer PipelineObserver 寮曠敤
   * @param replanProvider 鍙€夆€斺€旈噸瑙勫垝鍥炶皟鎻愪緵鑰咃紙濡?MetaAgent 閫傞厤鍣級銆傜己鍒?replan 闈欓粯鎺掔┖
   * @param config 寮曟搸閰嶇疆
   */
  constructor(
    private readonly board: ITaskBoard,
    private readonly observer: IPipelineObserver,
    private readonly replanProvider: IReplanProvider | undefined,
    private readonly config: Required<EngineConfig>,
  ) {}

  /** 鏄惁鏈夊緟澶勭悊鐨勯噸瑙勫垝浠诲姟 */
  get hasPending(): boolean {
    return this.replanQueue.length > 0;
  }

  /**
   * 灏嗚妭鐐瑰叆闃熼噸瑙勫垝闃熷垪銆俓n   * @param node 澶辫触/瓒婄晫鑺傜偣
   * @param reason 澶辫触鍘熷洜鎴栬繚瑙勬弿杩癨n   * @param disposition 澶勭疆绫诲瀷锛歕

锛堥粯璁わ級| "boundary_violation"
   */
  enqueue(node: TaskNode, reason: string, disposition: "failure" | "boundary_violation" = "failure"): void {
    if (!this.replanProvider) return;

    const isReActTimeout = (reason).includes("Exceeded max loops");
    if (isReActTimeout) return;

    const count = this.replanCount.get(node.id) ?? 0;
    if (count >= this.config.maxReplanPerNode) return;

    this.replanQueue.push({ node, reason, count, disposition });
    this.observer.emit({
      type: PipelineEventType.NodeReplanQueued,
      priority: PipelinePriority.HIGH,
      payload: { nodeId: node.id, reason, attempt: count + 1 },
      timestamp: Date.now(),
      notificationType: "WARNING",
    });
  }

  /**
   * 灏濊瘯鍙戝皠鍚庡彴 replan 鎵规銆俓n   * 妫€鏌ュ叏灞€涓婇檺锛屾湭瑙﹂《鍒欏苟琛屽鐞嗘墍鏈夊叆闃熼」銆俓n   * @returns Promise锛堣皟鐢ㄦ柟鍙?await 鎴?fire-and-forget锛夛紝涓婇檺瑙﹂《鏃惰繑鍥?null
   */
  tryFireReplan(): Promise<void> | null {
    if (this.totalReplans >= this.config.maxTotalReplans) {
      this._emitBudgetExhausted();
      return null;
    }
    return this._drain().then(() => {
      if (this.totalReplans >= this.config.maxTotalReplans) {
        this._emitBudgetExhausted();
      }
    });
  }

  /** 鍙戝皠 SchedulerReplanLimit 骞舵竻绌洪槦鍒楋紝闃叉 Scheduler 绌鸿浆 */
  private _emitBudgetExhausted(): void {
    this.observer.emit({
      type: PipelineEventType.SchedulerReplanLimit,
      priority: PipelinePriority.CRITICAL,
      payload: {
        totalReplans: this.totalReplans,
        maxReplans: this.config.maxTotalReplans,
        deferred: this.replanQueue.length,
      },
      timestamp: Date.now(),
      notificationType: "WARNING",
    });
    this.replanQueue.length = 0;
  }

  /**
   * 鎵ц缁撴潫鍚庤В鏋愰噸瑙勫垝閾俱€俓n   * 鑻ヤ换鎰忓悗浠ｈ妭鐐规垚鍔燂紝瑙嗗師濮嬭妭鐐逛负鎴愬姛銆俓n   * @returns [updatedCompleted, updatedFailed] 淇鍚庣殑璁℃暟
   */
  resolveChains(allResults: NodeResult[]): [completed: number, failed: number] {
    let completed = 0;
    let failed = allResults.filter((r) => !r.success).length;

    for (const [origId, newIds] of this.replanMap) {
      const origIdx = allResults.findIndex((r) => r.nodeId === origId);
      if (origIdx < 0) continue;

      if (this._isChainSuccessful(newIds, allResults)) {
        if (allResults[origIdx].success === false) {
          failed--;
          completed++;
        }
        allResults[origIdx] = {
          nodeId: origId,
          success: true,
          output: this._getMergedOutput(newIds, allResults),
        };
      }
    }
    return [completed, failed];
  }

  private _getMergedOutput(newIds: string[], allResults: NodeResult[]): string {
    const parts: string[] = [];
    for (const id of newIds) {
      const r = allResults.find((rr) => rr.nodeId === id);
      if (r?.success && r.output) {
        parts.push("[" + id + "] " + r.output.slice(0, 2000));
      }
    }
    if (parts.length === 0) return "Replanned: task completed by new nodes";
    return "[Replanned - " + newIds.length + " sub-tasks]\n" + parts.join("\n---\n");
  }

  /**
   * 娓呴浂鎵€鏈夌姸鎬侊紙姣忔 executeAll() 缁撴潫鍚庤皟鐢級銆俓n   */
  reset(): void {
    this.replanMap.clear();
    this.replanCount.clear();
    this.totalReplans = 0;
    this.replanQueue.length = 0;
  }

  // 鈹€鈹€ 鍐呴儴瀹炵幇 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private async _drain(): Promise<void> {
    const provider = this.replanProvider;
    if (!provider) {
      const orphanCount = this.replanQueue.length;
      this.replanQueue.length = 0;
      if (orphanCount > 0) {
        this.observer.emit({
          type: PipelineEventType.SchedulerReplanNoMetaAgent,
          priority: PipelinePriority.CRITICAL,
          payload: { orphanCount, hint: "ReplanProvider not configured; replan queue drained silently" },
          timestamp: Date.now(),
          notificationType: "WARNING",
        });
      }
      return;
    }

    const fullBatch = this.replanQueue.splice(0); // 鍘熷瓙鍙栧嚭

    const available = this.config.maxTotalReplans - this.totalReplans;
    if (available <= 0) return;
    const batch = fullBatch.slice(0, available);
    this.totalReplans += batch.length;

    const promises = batch.map(async (item) => {
      const count = item.count + 1;
      this.replanCount.set(item.node.id, count);

      this.observer.emit({
        type: PipelineEventType.NodeReplan,
        priority: PipelinePriority.CRITICAL,
        payload: { nodeId: item.node.id, reason: item.reason, attempt: count },
        timestamp: Date.now(),
        notificationType: "WARNING",
      });

      const result = item.disposition === "boundary_violation"
        ? await provider.requestBoundaryReplan(
            item.node, item.reason, count, undefined, this.config.maxReplanPerNode,
          )
        : await provider.requestReplan(
            item.node, item.reason, count, undefined, this.config.maxReplanPerNode,
          );

      const newIds: string[] = [];
      for (const n of result.nodes) {
        // 鏍囪涓?RLM 瀛愪换鍔♀€斺€旇蛋 pool.spawnSubtask() 鐙珛閰嶉
        n.isRlmSubtask = true;
        this.board.addNode(n);
        this.replanCount.set(n.id, count);
        newIds.push(n.id);
      }
      this.replanMap.set(item.node.id, newIds);

      if (result.impactScope === "subtree") {
        this.board.removeSubtree(item.node.id);
      } else {
        this.board.removeNode(item.node.id);
      }
    });

    const results = await Promise.allSettled(promises);

    for (let i = 0; i < results.length; i++) {
      const r = results[i];
      if (r.status === "rejected") {
        const nodeId = batch[i]?.node.id ?? "unknown";
        this.observer.emit({
          type: PipelineEventType.SchedulerReplanFailed,
          priority: PipelinePriority.CRITICAL,
          payload: { nodeId, error: String(r.reason).slice(0, 200) },
          timestamp: Date.now(),
          notificationType: "WARNING",
        });
      }
    }
  }

  private _isChainSuccessful(nodeIds: string[], allResults: NodeResult[], visited = new Set<string>()): boolean {
    for (const id of nodeIds) {
      if (visited.has(id)) continue;
      visited.add(id);

      const result = allResults.find((r) => r.nodeId === id);
      if (result?.success) return true;

      const childIds = this.replanMap.get(id);
      if (childIds && childIds.length > 0) {
        if (this._isChainSuccessful(childIds, allResults, visited)) return true;
      }
    }
    return false;
  }
}

/**
 * RLM decompose 鈥斺€?浠庡畯瑙?TaskNode 鎷嗚В鍑哄師瀛愬瓙浠诲姟銆俓n *
 * 鍦?ExecuteStep 鍐呴儴璋冪敤鈥斺€斾笉璧?AgentPool 瀹屾暣鐢熷懡鍛ㄦ湡銆俓n * 瀛愪换鍔℃槸鎵ц绛栫暐锛岄潪鐙珛浠诲姟銆俓n *
 * 鏍稿績绾︽潫锛堟€濊€冩墽琛屼綋绯绘€荤翰 搂鍥涳級锛歕n * - 鍗曟枃浠躲€佸崟缁村害銆佹槑纭嚭鍙n * - maxDepth=3 鑷檺
 * - decompose confidence < 0.6 鈫?鍥為€€鐩存帴鎵ц
 * - 宸插師瀛愬寲鐨勫瓙浠诲姟涓嶅啀鎷哱n *
 * @since RLM 閫掑綊鎷嗚В
 */

import type { DecomposeResult, SubTask } from "@cortex/shared";
import { RLM_MIN_CONFIDENCE, RLM_MAX_DEPTH, RLM_MIN_COMPLEXITY_CHARS } from "@cortex/config";

/**
 * LLM 鍙皟鐢ㄧ鍚嶁€斺€斾笌 MetaAgent 浣跨敤妯″紡涓€鑷淬€俓n * (model, messages) 鈫?response content string
 */
export type LlmCallable = (model: string, messages: Array<{ role: string; content: string }>) => Promise<string>;

/** 瀛愪换鍔℃媶瑙ｇ殑鏈€澶ч€掑綊娣卞害锛堜粠 config 瀵煎叆锛?*/
export const MAX_RLM_DEPTH = RLM_MAX_DEPTH;

const DECOMPOSE_SYSTEM = [
  "浣犳槸涓€涓换鍔℃媶瑙ｄ笓瀹躲€備綘鐨勮亴璐ｆ槸灏嗗畯瑙備换鍔℃媶瑙ｄ负鍘熷瓙绾х殑瀛愪换鍔°€俓

}",
].join("\n");

/**
 * 鍒ゆ柇鑺傜偣鏄惁瓒冲澶嶆潅浠ヨЕ鍙?RLM 鎷嗚В銆俓n */
export function shouldDecompose(payload: string, tags: string[], preferredStrategy?: string): boolean {
  if (preferredStrategy === "decompose") return true;
  if (payload.length > RLM_MIN_COMPLEXITY_CHARS) return true;
  if (tags.some((t) => t === "analysis" || t === "research")) return true;
  return false;
}

/**
 * 鏋勫缓 decompose() 鐨勭敤鎴锋彁绀鸿瘝銆俓n */
export function buildDecomposePrompt(payload: string, currentDepth: number): string {
  const depthNote = currentDepth > 0
    ? `褰撳墠鎷嗚В娣卞害: ${currentDepth}/${MAX_RLM_DEPTH}銆傛帴杩戜笂闄愶紝璇风‘淇濆瓙浠诲姟宸茶冻澶熷師瀛愬寲銆俙
    : `鏈€澶ф媶瑙ｆ繁搴? ${MAX_RLM_DEPTH}銆俙;

  return [
    `璇峰皢浠ヤ笅浠诲姟鎷嗚В涓哄師瀛愬瓙浠诲姟锛歚,
    "",
    "```",
    payload,
    "```",
    "",
    depthNote,
    "濡傛灉浠诲姟宸茬粡瓒冲鍘熷瓙鍖栵紙鍗曟枃浠躲€佸崟缁村害銆佹槑纭嚭鍙ｏ級锛岃繑鍥炵┖鐨?subTasks 鏁扮粍锛宑onfidence 璁句负 1.0銆俓

usedDeprecatedRules:
\n");
}

/**
 * 璋冪敤 LLM 鎷嗚В浠诲姟锛岃繑鍥?DecomposeResult銆俓n */
export async function decompose(
  llmCallable: LlmCallable,
  model: string,
  payload: string,
  currentDepth: number = 0,
): Promise<DecomposeResult> {
  // 娣卞害瓒呴檺 鈫?涓嶆媶
  if (currentDepth >= MAX_RLM_DEPTH) {
    return {
      subTasks: [],
      confidence: 1.0,
      rationale: `宸茶揪鍒版渶澶ф媶瑙ｆ繁搴?${MAX_RLM_DEPTH}锛屼笉鍐嶆媶瑙,
    };
  }

  // 澶嶆潅搴︿笉瓒?鈫?涓嶆媶
  if (!shouldDecompose(payload, [], undefined)) {
    return {
      subTasks: [],
      confidence: 1.0,
      rationale: "浠诲姟澶嶆潅搴︿笉瓒筹紝鏃犻渶鎷嗚В",
    };
  }

  const prompt = buildDecomposePrompt(payload, currentDepth);

  let rawContent: string;
  try {
    rawContent = await llmCallable(model, [
      { role: "system", content: DECOMPOSE_SYSTEM },
      { role: "user", content: prompt },
    ]);
  } catch {
    return {
      subTasks: [],
      confidence: 0,
      rationale: "LLM 璋冪敤澶辫触锛屽洖閫€鐩存帴鎵ц",
    };
  }

  return parseDecomposeResponse(rawContent);
}

/**
 * 瑙ｆ瀽 LLM 鐨?JSON 鍝嶅簲涓?DecomposeResult銆俓n */
export function parseDecomposeResponse(raw: string): DecomposeResult {
  let jsonStr = raw.trim();

  // 鍘绘帀鍙兘鐨?markdown 浠ｇ爜鍧楀寘瑁筡n  const codeBlockMatch = jsonStr.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (codeBlockMatch) {
    jsonStr = codeBlockMatch[1].trim();
  }

  // 鎵惧埌绗竴涓?{ 鍒版渶鍚庝竴涓?} 涔嬮棿鐨勫唴瀹筡n  const firstBrace = jsonStr.indexOf("{");
  const lastBrace = jsonStr.lastIndexOf("}");
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    jsonStr = jsonStr.slice(firstBrace, lastBrace + 1);
  }

  try {
    const parsed = JSON.parse(jsonStr) as {
      subTasks?: Array<{
        id?: string;
        description?: string;
        dependsOn?: string[];
        density?: string;
        confidence?: number;
      }>;
      confidence?: number;
      rationale?: string;
    };

    const subTasks: SubTask[] = (parsed.subTasks ?? [])
      .filter((st) => st.id && st.description)
      .map((st, i) => ({
        id: st.id ?? `st-${i}`,
        description: st.description ?? "",
        dependsOn: Array.isArray(st.dependsOn) ? st.dependsOn : [],
        density: (["light", "medium", "heavy"].includes(st.density ?? "") ? st.density : "medium") as SubTask["density"],
        confidence: typeof st.confidence === "number" ? Math.max(0, Math.min(1, st.confidence)) : 0.8,
      }));

    const overallConfidence = typeof parsed.confidence === "number"
      ? Math.max(0, Math.min(1, parsed.confidence))
      : (subTasks.length === 0 ? 1.0 : 0.5);

    return {
      subTasks,
      confidence: overallConfidence,
      rationale: parsed.rationale ?? (subTasks.length === 0 ? "浠诲姟宸插師瀛愬寲" : `鎷嗚В涓?${subTasks.length} 涓瓙浠诲姟`),
    };
  } catch {
    return {
      subTasks: [],
      confidence: 0,
      rationale: `JSON 瑙ｆ瀽澶辫触锛屽師濮嬪搷搴斿墠 200 瀛? ${raw.slice(0, 200)}`,
    };
  }
}

/**
 * 瀵?DecomposeResult 鍋氭渶缁堣鍐斥€斺€斿垽鏂槸鍚﹀簲璇ュ疄闄呮墽琛屾媶瑙ｃ€俓n *
 * 涓嶆媶鐨勬儏鍐碉細
 * - confidence < RLMMIN_CONFIDENCE
 * - subTasks 涓虹┖
 * - 鍙湁涓€涓瓙浠诲姟涓?confidence < 0.8锛堟媶浜嗙瓑浜庢病鎷嗭級
 */
export function shouldExecuteDecomposition(result: DecomposeResult): boolean {
  if (result.confidence < RLM_MIN_CONFIDENCE) return false;
  if (result.subTasks.length === 0) return false;
  if (result.subTasks.length === 1 && result.subTasks[0].confidence < 0.8) return false;
  return true;
}

