semantic";

  /** 妯″瀷鍚?鈫?tier 鍙嶅悜鏄犲皠锛堢敤浜庤绠?agent floor锛?*/
  private readonly _modelTier: Map<string, ModelTier> = new Map();

  /** Agent 妯″瀷娉ㄥ唽琛ㄢ€斺€旀噿鑾峰彇锛圫cheduler 鏋勯€犳椂 models 灏氭湭濉厖锛?*/
  private readonly _modelsGetter: () => Map<string, string>;

  /** 鍒嗙被鍣ㄧ紦瀛橈細payload 鍝堝笇 鈫?{ tier, at } */
