  /** 鍒嗙被鍣ㄩ噸璇曟鏁帮紙涓嶅惈棣栨锛?*/
  private readonly _classifierRetries: number;

  /** 璺敱鍐崇瓥鍥炶皟鈥斺€旂敤浜庡彲瑙傛祴鎬?*/
