 *   娑堥櫎閲嶅 emit 鍜岀淮鎶よ礋鎷呫€俓n */
export class TaskBoard {
    nodes = new Map();
    _observer;
    /**
     * invariant 杩濊涓婃姤鍚庣銆俓n     * 榛樿涓?`null`锛堜粎 console.error锛夈€俓n     * 鍦?bootstrap 涓敞鍏?observer.emit 鍚庯紝鎵€鏈?invariant 杩濊浼氳蛋 observer 绠￠亾銆俓n     *
     * 浼樺厛绾э細瀹炰緥 _observer > 闈欐€?onInvariant > console.error
     */
    static onInvariant = null;
    /** 娉ㄥ叆 PipelineObserver锛堜笌 onInvariant 浜掕ˉ鐨勫弻閫氶亾妯″紡锛?*/
    setObserver(observer) {
