     * 澶╃劧鍘熷瓙銆傝嫢鏈潵寮曞叆寮傛妫€鏌ワ紙濡傛爣绛鹃獙璇侊級锛屽繀椤诲姞浜掓枼閿佹垨鏀逛负鐘舵€佹満銆俓n     *
     * 鏅€氳妭鐐癸細浠?pending 鍙棰嗭紝宸茶棰嗘嫆銆俓n     * needsMultiPerspective锛氫笉鍚?Agent 绫诲瀷鍙苟琛岃棰嗭紝鍚岀被鍨嬩笉鍙噸澶嶃€俓n     */
    claim(nodeId, agentType) {
        const node = this.nodes.get(nodeId);
        if (!node)
            return null;
        // 鏍囩鍖归厤
        const agentTags = getAgentTags()[agentType];
        if (!node.tags.some((t) => agentTags.includes(t)))
            return null;
        if (node.needsMultiPerspective) {
            // 鍚岀被鍨嬩笉鍙噸澶嶈棰哱n            if (node.claimedBy.includes(agentType))
                return null;
            // 宸茬粓鎬佺殑涓嶅彲璁ら
            if (node.status === "done" || node.status === "failed")
                return null;
            node.claimedBy.push(agentType);
            if (node.status === "pending")
                node.status = "running";
            return node;
        }
        // 鏅€氳妭鐐癸細浠?pending 鍙棰嗭紝鍗?Agent
