    if (!claimed) {
      board.failNode(node.id);
      return {
        ...ctx,
        result: {
          nodeId: node.id,
          agentType: agentType as AgentType,
          success: false,
          error: `Failed to claim node ${node.id} for ${agentType}`,
        },
      };
    }

    return {
      ...ctx,
      agentType,
      agent,
    };
  }
