    this._trailingNewline = options?.trailingNewline ?? true;
  }

  /**
   * 閲囬泦涓€鏉￠仴娴嬫暟鎹偣銆俓n   * 鏁版嵁鍏堝啓鍏ュ唴閮ㄧ紦鍐插尯锛岀敱 flush() 缁熶竴鍐欏叆鏂囦欢銆俓n   *
   * @param data - 閬ユ祴鏁版嵁鐐筡n   * @returns 閲囬泦缁撴灉
   */
  async collect(data: TelemetryData): Promise<CollectResult> {
    if (this._shutdown) {
      return { accepted: false, reason: "FileCollector is shut down" };
    }

    this._buffer.push(data);
    return { accepted: true };
  }

  /**
   * 鍒锋柊缂撳啿鍖猴紝灏嗙紦鍐插尯鍐呮墍鏈夋暟鎹偣鍐欏叆鏂囦欢銆俓n   * 浣跨敤 "overwrite" 妯″紡鏃舵瘡娆′粠澶村啓鍏ワ紱
   * 浣跨敤 "append" 妯″紡鏃惰拷鍔犲埌鏂囦欢鏈熬銆俓n   */
  async flush(): Promise<void> {
    if (this._buffer.length === 0) {
      return;
    }

    const entries = this._serializeBatch(this._buffer);

    // 纭繚鐖剁洰褰曞瓨鍦╘n    await mkdir(dirname(this._filePath), { recursive: true });

    // @fix P1-2 鈥?浠呭湪鍐欏叆鎴愬姛鍚庢竻绌虹紦鍐插尯锛岄槻姝?flush 澶辫触鏃舵暟鎹涪澶辨垨閲嶅
    try {
      if (this._mode === "overwrite") {
        await writeFile(this._filePath, entries, { encoding: "utf-8" });
      } else {
        await appendFile(this._filePath, entries, { encoding: "utf-8" });
      }
      this._buffer = [];
    } catch (e) {
      // 鍐欏叆澶辫触鏃朵繚鐣欑紦鍐插尯鏁版嵁锛屼笂灞傚彲閫夋嫨閲嶈瘯鎴栦涪寮僜n      throw new Error(
        `Failed to flush telemetry: ${e instanceof Error ? e.message : String(e)}`,
        { cause: e },
      );
    }
  }

  /**
   * 鍏抽棴閲囬泦鍣ㄣ€傚厛鎵ц鏈€鍚庝竴娆?flush锛岀劧鍚庢爣璁板凡鍏抽棴銆俓n   */
  async shutdown(): Promise<void> {
    await this.flush();
    this._shutdown = true;
  }

  /**
   * 灏嗙紦鍐插尯鍐呮暟鎹偣搴忓垪鍖栦负 JSON Lines 瀛楃涓层€俓n   * @param buffer - 缂撳啿鍖烘暟鎹甛n   * @returns JSON Lines 瀛楃涓瞈n   */
  private _serializeBatch(buffer: TelemetryData[]): string {
    const lines = buffer
      .map((data) => JSON.stringify(data));

    return this._trailingNewline
      ? lines.join("\n") + "\n"
      : lines.join("\n");
  }
}

