// @cortex/telemetry 鈥斺€?Sampler 绛栫暐鎺ュ彛涓庡疄鐜癨n//
// 鎻愪緵 Sampler 绛栫暐鎺ュ彛鍙婁袱绉嶅唴缃噰鏍风瓥鐣ワ細
// - RateSampler锛氭寜鍥哄畾姣斾緥閲囨牱
// - ThresholdSampler锛氭寜鏁板€奸槇鍊奸噰鏍穃n// ============================================================

import type { Sampler, SamplerDecision, TelemetryData } from "./types.js";

// 鈹€鈹€鈹€ RateSampler 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 鎸夋瘮渚嬮噰鏍峰櫒銆俓n *
 * 浠ュ浐瀹氭瘮渚嬶紙rate锛夐殢鏈哄喅瀹氭槸鍚﹂噰闆嗘暟鎹偣銆俓n * rate = 1.0 琛ㄧず鍏ㄩ噺閲囬泦锛宺ate = 0.0 琛ㄧず鍏ㄩ儴涓㈠純銆俓n * rate = 0.1 琛ㄧず澶х害 10% 鐨勬暟鎹偣琚噰闆嗐€俓n *
 * 浣跨敤纭畾鎬у搱甯屼唬鏇跨函闅忔満锛岀‘淇濈浉鍚?ID 鐨勬暟鎹偣
 * 鍦ㄤ笉鍚岃繍琛屾椂寰楀埌涓€鑷寸殑閲囨牱鍐崇瓥锛堜究浜庤皟璇曪級銆俓n *
 * @example
 * ```typescript
 * const sampler = new RateSampler(0.1);
 * const decision = sampler.decide(data);
 * // decision.accept === true -> collect
 * ```
 */
export class RateSampler implements Sampler {
  readonly name: string;
  private readonly _rate: number;

  /**
   * @param rate - 閲囨牱姣斾緥锛?.0 ~ 1.0锛塡n   * @param name - 閲囨牱鍣ㄥ悕绉帮紙榛樿 "rate"锛塡n   * @throws 濡傛灉 rate 涓嶅湪 [0, 1] 鑼冨洿鍐匼n   */
  constructor(rate: number, name = "rate") {
    if (rate < 0 || rate > 1) {
      throw new Error(`RateSampler: rate must be between 0 and 1, got ${rate}`);
    }

    this._rate = rate;
    this.name = name;
  }

  /**
   * 鍒ゆ柇鏄惁搴旈噰闆嗙粰瀹氱殑鏁版嵁鐐广€俓n   * 浣跨敤鍩轰簬 ID 鐨勭‘瀹氭€у搱甯岋紝淇濊瘉鐩稿悓 ID 缁撴灉涓€鑷淬€俓n   *
   * @param data - 閬ユ祴鏁版嵁鐐筡n   * @returns 閲囨牱鍐崇瓥
   */
  decide(data: TelemetryData): SamplerDecision {
    if (this._rate === 0) {
      return { accept: false, reason: "RateSampler: rate=0, all data dropped" };
    }

    if (this._rate === 1) {
      return { accept: true, reason: "RateSampler: rate=1, all data accepted" };
    }

    // 纭畾鎬у搱甯岄噰鏍凤細鐢?data.id 鐨勫搱甯屽€煎喅瀹氭槸鍚﹂噰闆哱n    const hash = this._hashString(data.id);
    const normalized = (hash % 10_000) / 10_000;

    if (normalized < this._rate) {
      return { accept: true, reason: `RateSampler: rate=${this._rate}, hash=${normalized}` };
    }

    return { accept: false, reason: `RateSampler: rate=${this._rate}, hash=${normalized}` };
  }

  /**
   * 绠€鍗曞瓧绗︿覆鍝堝笇锛坉jb2 绠楁硶锛夈€俓n   * 淇濊瘉鍚屼竴瀛楃涓插缁堜骇鐢熺浉鍚屽搱甯屽€笺€俓n   *
   * @param str - 杈撳叆瀛楃涓瞈n   * @returns 鍝堝笇鍊糪n   */
  private _hashString(str: string): number {
    let hash = 5381;
    for (let i = 0; i < str.length; i++) {
      // eslint-disable-next-line no-bitwise
      hash = ((hash << 5) + hash) + str.charCodeAt(i);
      // eslint-disable-next-line no-bitwise
      hash = hash & hash; // Convert to 32-bit integer
    }
    // eslint-disable-next-line no-bitwise
    return Math.abs(hash);
  }
}

// 鈹€鈹€鈹€ ThresholdSampler 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * 闃堝€奸噰鏍峰櫒銆俓n *
 * 鏍规嵁鏁版嵁鐐圭殑鏁板€兼槸鍚﹁秴杩囬槇鍊煎喅瀹氭槸鍚﹂噰闆嗐€俓n * 鏀寔澶т簬妯″紡锛坴alue > threshold 鏃堕噰闆嗭級鍜屽皬浜庢ā寮忥紙value < threshold 鏃堕噰闆嗭級銆俓n *
 * @example
 * ```typescript
 * // 鍙噰闆嗚€楁椂瓒呰繃 1000ms 鐨?LLM 璋冪敤
 * const sampler = new ThresholdSampler(1000, "gt");
 * const decision = sampler.decide(data);
 * ```
 */
export class ThresholdSampler implements Sampler {
  readonly name: string;
  private readonly _threshold: number;
  private readonly _mode: "gt" | "lt";

  /**
   * @param threshold - 闃堝€糪n   * @param mode - 姣旇緝妯″紡锛歕

 = value > threshold 鏃堕噰闆? "lt" = value < threshold 鏃堕噰闆哱n   * @param name - 閲囨牱鍣ㄥ悕绉帮紙榛樿 "threshold"锛塡n   */
  constructor(threshold: number, mode: "gt" | "lt" = "gt", name = "threshold") {
    this._threshold = threshold;
    this._mode = mode;
    this.name = name;
  }

  /**
   * 鍒ゆ柇鏄惁搴旈噰闆嗙粰瀹氱殑鏁版嵁鐐广€俓n   * @param data - 閬ユ祴鏁版嵁鐐筡n   * @returns 閲囨牱鍐崇瓥
   */
  decide(data: TelemetryData): SamplerDecision {
    if (this._mode === "gt") {
      if (data.value > this._threshold) {
        return {
          accept: true,
          reason: `ThresholdSampler: ${data.value} > ${this._threshold} (mode=${this._mode})`,
        };
      }
      return {
        accept: false,
        reason: `ThresholdSampler: ${data.value} <= ${this._threshold} (mode=${this._mode})`,
      };
    }

    // mode === "lt"
    if (data.value < this._threshold) {
      return {
        accept: true,
        reason: `ThresholdSampler: ${data.value} < ${this._threshold} (mode=${this._mode})`,
      };
    }

    return {
      accept: false,
      reason: `ThresholdSampler: ${data.value} >= ${this._threshold} (mode=${this._mode})`,
    };
  }
}

/**
 * 鈺愨晲鈺?閰嶇疆婕傜Щ鎺㈡祴鍣?鈺愨晲鈺怽n *
 * 鎵弿 packages 涓嬪悇瀛愬寘鐨?package.json + 鏍?package.json锛孿n * 妫€娴嬪悓鍚嶄緷璧栫殑鐗堟湰澹版槑鏄惁涓€鑷淬€俓n *
 * 鐢ㄦ硶:
 *   npx tsx packages/tools/src/configuration-drift.ts           # 缁堢鎶ュ憡
 *   npx tsx packages/tools/src/configuration-drift.ts --json    # JSON 杈撳嚭
