function formatText(output: AnalyzerOutput, _verbose: boolean): string {
  const lines: string[] = [];
  const W = '鈹€'.repeat(58);

  lines.push('');
  lines.push('  鈺愨晲鈺?Monorepo Analyzer 鎶ュ憡 鈺愨晲鈺?);
