  lines.push(`  ${W2}`);
  lines.push(`  鎬讳綋鐘舵€? ${statusIcon} ${output.meta.status}`);
  if (output.cycles.length > 0) {
    lines.push(`  寰幆渚濊禆: ${output.cycles.length} 澶刞);
  }
  if (output.drifts.length > 0) {
    lines.push(`  鐗堟湰婕傜Щ: ${output.drifts.length} 澶刞);
  }
  lines.push(`  ${W2}`);
  lines.push('');

  return lines.join('\n');
}

